CONFIG_PATH = os.path.join(os.path.expanduser("~"), ".auto_pt_suite.json")

#  ذاكرة تخطيط الليّرات: لكل ملف DXF بنحفظ الأدوار اللي المستخدم أكّدها
#  ووحدة الرسم، فمش بيتسأل تاني على نفس الملف. المفتاح هو مسار الملف،
#  والتحقق بأسماء الليّرات نفسها - لو الرسمة اتغيّرت وليّراتها اختلفت
#  الذاكرة بتتجاهل وبيتسأل من جديد.
LAYER_MEMORY_PATH = os.path.join(os.path.expanduser("~"),
                                 ".auto_pt_layer_memory.json")


def _layer_key(dxf_path):
    try:
        return os.path.normcase(os.path.abspath(dxf_path))
    except Exception:
        return str(dxf_path or "")


def layer_memory_load():
    if not os.path.isfile(LAYER_MEMORY_PATH):
        return {}
    try:
        with open(LAYER_MEMORY_PATH, encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def layer_memory_get(dxf_path, layer_names):
    """الأدوار المحفوظة لنفس الملف - أو None لو مفيش أو الليّرات اتغيّرت."""
    entry = layer_memory_load().get(_layer_key(dxf_path))
    if not isinstance(entry, dict):
        return None
    if sorted(entry.get("names") or []) != sorted(layer_names):
        return None
    roles = entry.get("roles")
    if not isinstance(roles, dict) or not roles:
        return None
    return {"roles": roles, "unit": entry.get("unit") or "",
            "saved": entry.get("saved") or ""}


def layer_memory_put(dxf_path, layer_names, roles, unit_label):
    data = layer_memory_load()
    data[_layer_key(dxf_path)] = {
        "file": os.path.basename(dxf_path or ""),
        "names": sorted(layer_names),
        "roles": dict(roles),
        "unit": unit_label,
        "saved": datetime.datetime.now().strftime("%Y-%m-%d %H:%M"),
    }
    #  الملف مايكبرش على الآخر: بنسيب آخر 200 رسمة وبس.
    if len(data) > 200:
        rows = sorted(data.items(), key=lambda kv: kv[1].get("saved", ""))
        data = dict(rows[-200:])
    try:
        with open(LAYER_MEMORY_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
        return True
    except Exception:
        return False


def layer_memory_forget(dxf_path=None):
    """يمسح ملف واحد، أو الذاكرة كلها لو dxf_path=None. بيرجّع عدد اللي اتمسح."""
    data = layer_memory_load()
    if dxf_path is None:
        gone = len(data)
        data = {}
    else:
        gone = 1 if data.pop(_layer_key(dxf_path), None) else 0
    try:
        with open(LAYER_MEMORY_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=1)
    except Exception:
        return 0
    return gone

