# ==============================================================================
#  القسم 1 — أدوات هندسية أساسية
#  كل الإحداثيات هنا بالمتر. كل الأسماك والمناسيب بالمليمتر.
# ==============================================================================

def safe_get(obj, attr, default=None):
    """Read a property from an API object without blowing up if it is absent."""
    try:
        val = getattr(obj, attr)
        return val if val is not None else default
    except Exception:
        return default


def dist(p1, p2):
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])


def polygon_area(pts):
    """Polygon area by the shoelace formula, absolute value."""
    n = len(pts)
    if n < 3:
        return 0.0
    a = 0.0
    for i in range(n):
        j = (i + 1) % n
        a += pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1]
    return abs(a) * 0.5


def polygon_centroid(pts):
    n = len(pts)
    if n == 0:
        return (0.0, 0.0)
    if n < 3:
        return (sum(p[0] for p in pts) / n, sum(p[1] for p in pts) / n)
    cx = cy = a = 0.0
    for i in range(n):
        j = (i + 1) % n
        cross = pts[i][0] * pts[j][1] - pts[j][0] * pts[i][1]
        a += cross
        cx += (pts[i][0] + pts[j][0]) * cross
        cy += (pts[i][1] + pts[j][1]) * cross
    if abs(a) < 1e-12:
        return (sum(p[0] for p in pts) / n, sum(p[1] for p in pts) / n)
    a *= 0.5
    return (cx / (6.0 * a), cy / (6.0 * a))


def bbox_of(pts):
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    return min(xs), min(ys), max(xs), max(ys)


def clean_polygon(pts, tol=0.001):
    """Drop duplicate and near-coincident points and close the polygon."""
    if not pts:
        return []
    out = [pts[0]]
    for p in pts[1:]:
        if dist(out[-1], p) > tol:
            out.append(p)
    while len(out) > 2 and dist(out[0], out[-1]) <= tol:
        out.pop()
    return out


def drop_collinear(pts, tol=1e-4):
    """Remove collinear vertices - shrinks the polygon without changing its shape."""
    n = len(pts)
    if n < 4:
        return pts
    out = []
    for i in range(n):
        a = pts[(i - 1) % n]
        b = pts[i]
        c = pts[(i + 1) % n]
        cross = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
        base = max(dist(a, b), dist(b, c), 1e-9)
        if abs(cross) / base > tol:
            out.append(b)
    return out if len(out) >= 3 else pts


def point_in_polygon(x, y, poly):
    """
    [F04] ray-casting صحيح. النسخة القديمة كانت بتستخدم xinters قبل تعريفه
    لما يكون الضلع أفقي تمامًا، وده بيرمي UnboundLocalError.
    """
    n = len(poly)
    if n < 3:
        return False
    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if (yi > y) != (yj > y):
            denom = (yj - yi)
            if denom != 0.0:
                x_int = (xj - xi) * (y - yi) / denom + xi
                if x < x_int:
                    inside = not inside
        j = i
    return inside


def point_to_segment_dist(px, py, x1, y1, x2, y2):
    l2 = (x2 - x1) ** 2 + (y2 - y1) ** 2
    if l2 == 0.0:
        return math.hypot(px - x1, py - y1)
    t = max(0.0, min(1.0, ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2))
    return math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1)))


def segment_intersection(p1, p2, q1, q2):
    """
    [F01] التوقيع الصحيح: أربع نقط، مش ستة أرقام.
    بترجع نقطة التقاطع أو None.
    """
    x1, y1 = p1
    x2, y2 = p2
    x3, y3 = q1
    x4, y4 = q2
    denom = (y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1)
    if abs(denom) < 1e-12:
        return None
    ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denom
    ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denom
    if -1e-9 <= ua <= 1.0 + 1e-9 and -1e-9 <= ub <= 1.0 + 1e-9:
        return (x1 + ua * (x2 - x1), y1 + ua * (y2 - y1))
    return None


def line_polygon_intersections(p1, p2, poly):
    """Every intersection of segment p1->p2 with the polygon edges."""
    out = []
    n = len(poly)
    for i in range(n):
        hit = segment_intersection(p1, p2, poly[i], poly[(i + 1) % n])
        if hit is not None:
            out.append(hit)
    return out


def point_on_polygon_edge(px, py, poly, tol=0.05):
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        if point_to_segment_dist(px, py, x1, y1, x2, y2) <= tol:
            return True
    return False


def scratch_cpt_path(tag):
    """
    اسم فريد لنسخة مؤقتة من موديل (17.67).

    القراءة من SQLite بتتعمل على نسخة من الملف في %TEMP%. الاسم كان
    ثابت (_pt_editor_read.cpt وأخواته)، فنسختين من البرنامج شغالين مع
    بعض - أو رن والمحرر مفتوح - كانوا بيكتبوا على نفس الملف ويقروا
    موديل بعض. mkstemp بيدي اسم ماحدش غيرنا واخده.
    """
    import tempfile
    fd, path = tempfile.mkstemp(prefix=f"_pt_{tag}_", suffix=".cpt")
    os.close(fd)
    return path


def discretize_arc(center, radius, start_deg, end_deg, max_seg=0.25,
                   max_pts=720):
    s = math.radians(start_deg)
    e = math.radians(end_deg)
    if e <= s:
        e += 2 * math.pi
    arc_len = radius * (e - s)
    #  17.65: سقف لعدد النقط. قوس نصف قطره 3 م على رسمة مليمتر كان بيطلع
    #  ~40 ألف نقطة لما max_seg اتحسب بالمتر على وحدات الملف.
    n = max(min(int(arc_len / max(max_seg, 1e-6)), max_pts), 6)
    return [(center[0] + radius * math.cos(s + (e - s) * i / n),
             center[1] + radius * math.sin(s + (e - s) * i / n))
            for i in range(n + 1)]


def stitch_edges(edges, tolerance=0.05):
    """
    [F08] تجميع الخطوط المفتوحة في سلاسل مقفولة — بـ spatial hash بدل O(n²).
    بترجع قائمة مضلعات صالحة.
    """
    if not edges:
        return []

    cell = max(tolerance, 1e-6) * 2.0

    def key(p):
        return (int(math.floor(p[0] / cell)), int(math.floor(p[1] / cell)))

    # فهرس: خلية → [(edge_index, endpoint_index)]
    index = {}
    for i, (a, b) in enumerate(edges):
        index.setdefault(key(a), []).append((i, 0))
        index.setdefault(key(b), []).append((i, 1))

    def neighbours(p):
        kx, ky = key(p)
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                for item in index.get((kx + dx, ky + dy), ()):
                    yield item

    used = [False] * len(edges)
    chains = []

    for seed in range(len(edges)):
        if used[seed]:
            continue
        used[seed] = True
        chain = [edges[seed][0], edges[seed][1]]

        for end in (1, 0):  # امتد من النهاية ثم من البداية
            while True:
                tip = chain[-1] if end == 1 else chain[0]
                found = None
                for (ei, pi) in neighbours(tip):
                    if used[ei]:
                        continue
                    if dist(edges[ei][pi], tip) <= tolerance:
                        found = (ei, 1 - pi)
                        break
                if found is None:
                    break
                ei, other = found
                used[ei] = True
                if end == 1:
                    chain.append(edges[ei][other])
                else:
                    chain.insert(0, edges[ei][other])

        chain = clean_polygon(chain, tol=tolerance * 0.5)
        if len(chain) >= 3 and polygon_area(chain) > 1e-4:
            chains.append(chain)

    return chains


def merge_close_vertices(polygons, tolerance=0.03):
    """Merge near-coincident vertices across polygons, using a spatial hash."""
    if not polygons:
        return []
    cell = max(tolerance, 1e-6) * 2.0
    grid = {}
    canon = []

    def key(p):
        return (int(math.floor(p[0] / cell)), int(math.floor(p[1] / cell)))

    def canonical(p):
        kx, ky = key(p)
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                for idx in grid.get((kx + dx, ky + dy), ()):
                    if dist(canon[idx], p) <= tolerance:
                        return canon[idx]
        canon.append(p)
        grid.setdefault((kx, ky), []).append(len(canon) - 1)
        return p

    out = []
    for poly in polygons:
        new_poly = []
        for p in poly:
            cp = canonical(p)
            if not new_poly or dist(new_poly[-1], cp) > 1e-9:
                new_poly.append(cp)
        new_poly = clean_polygon(new_poly, tol=1e-6)
        if len(new_poly) >= 3:
            out.append(new_poly)
    return out


def round_to(value, step):
    if step <= 0:
        return value
    return round(round(value / step) * step, 3)


def normalize_angle_deg(angle_deg):
    """
    تطبيع زاوية ضلع مستطيل للمدى (-90, 90].
    من غير كده نفس العمود ممكن يطلع 5° مرة و185° مرة حسب اتجاه رسم البوليلاين.
    """
    a = angle_deg % 180.0
    if a > 90.0:
        a -= 180.0
    return a

# ------------------------------------------------------------------------------
#  المستطيل الأصغر المحيط — الأساس في التعرّف على الأعمدة
#
#  الاعتماد على "the polygon must be exactly a quadrilateral" كان بيفشل مع الأعمدة المرسومة
#  بأركان مشطوفة، أو بنقطة زيادة في نص ضلع، أو كـ HATCH، أو من أربع خطوط
#  منفصلة. المستطيل الأصغر المحيط بيشتغل مع كل الحالات دي.
# ------------------------------------------------------------------------------

def convex_hull(points):
    """Convex hull by Andrew monotone chain. Returns points counter-clockwise."""
    pts = sorted(set((round(p[0], 6), round(p[1], 6)) for p in points))
    if len(pts) <= 2:
        return pts

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]


def min_area_rect(points):
    """
    أصغر مستطيل محيط بمجموعة نقط (rotating calipers).
    بترجع dict: المركز، الطول، العرض، الزاوية بالدرجات، ومساحة المستطيل.
    """
    hull = convex_hull(points)
    if len(hull) < 3:
        return None

    best = None
    n = len(hull)
    for i in range(n):
        ax, ay = hull[i]
        bx, by = hull[(i + 1) % n]
        ex, ey = bx - ax, by - ay
        L = math.hypot(ex, ey)
        if L < 1e-9:
            continue
        ux, uy = ex / L, ey / L
        vx, vy = -uy, ux

        us = [(p[0] - ax) * ux + (p[1] - ay) * uy for p in hull]
        vs = [(p[0] - ax) * vx + (p[1] - ay) * vy for p in hull]
        u0, u1 = min(us), max(us)
        v0, v1 = min(vs), max(vs)
        area = (u1 - u0) * (v1 - v0)

        if best is None or area < best["area"]:
            cu, cv = (u0 + u1) / 2.0, (v0 + v1) / 2.0
            best = {
                "area": area,
                "center": (ax + cu * ux + cv * vx, ay + cu * uy + cv * vy),
                "long": max(u1 - u0, v1 - v0),
                "short": min(u1 - u0, v1 - v0),
                "angle_deg": normalize_angle_deg(math.degrees(math.atan2(uy, ux)))
                if (u1 - u0) >= (v1 - v0)
                else normalize_angle_deg(math.degrees(math.atan2(vy, vx))),
            }
    return best


def circularity(points):
    """
    نسبة مساحة المضلع لمساحة الدائرة المكافئة لمحيطه.
    ≈ 1.0 يعني الشكل دائري، والمستطيل بيدي حوالي 0.78 أو أقل.
    """
    if len(points) < 3:
        return 0.0
    area = polygon_area(points)
    perim = sum(dist(points[i], points[(i + 1) % len(points)])
                for i in range(len(points)))
    if perim < 1e-9:
        return 0.0
    return 4.0 * math.pi * area / (perim * perim)



# ==============================================================================
#  القسم 1ب — تسريع اختياري بـ Shapely
#
#  اختبار "point inside the slab" هو أكتر عملية بتتكرر في البرنامج: بيتنادى
#  لكل مقطع في كل خط مسح، ولكل نقطة في كل بروفايل. مع بلاطة فيها فتحات
#  كتير التكلفة بتبقى O(نقط × أضلاع).
#
#  لو Shapely متثبّتة، بنبني مضلع مجهّز (prepared) مرة واحدة = البلاطة ناقص
#  الفتحات، والاختبار بيبقى O(log n) بفهرس مكاني داخلي.
#  لو مش متثبّتة، البرنامج بيشتغل عادي بالكود النقي — مفيش تبعية إجبارية.
#
#      pip install shapely      (اختياري)
# ==============================================================================

try:
    from shapely.geometry import Polygon as _ShpPolygon, Point as _ShpPoint
    from shapely.prepared import prep as _shp_prep
    HAS_SHAPELY = True
except Exception:
    _ShpPolygon = _ShpPoint = _shp_prep = None
    HAS_SHAPELY = False


class SlabRegion:
    """
    منطقة الخرسانة الصافية = الحدود ناقص الفتحات، مع اختبار احتواء سريع.
    نفس الواجهة سواء Shapely موجودة أو لأ.
    """

    def __init__(self, boundary, openings=None, job=None):
        self.boundary = boundary
        self.openings = list(openings or [])
        self._prepared = None
        self.backend = "python"

        if HAS_SHAPELY and boundary and len(boundary) >= 3:
            try:
                holes = [op for op in self.openings if len(op) >= 3]
                poly = _ShpPolygon(boundary, holes)
                if not poly.is_valid:
                    poly = poly.buffer(0)          # تصحيح التقاطعات الذاتية
                self._prepared = _shp_prep(poly)
                self._poly = poly
                self.backend = "shapely"
            except Exception as e:
                self._prepared = None
                if job:
                    job.warn(f"Shapely is present but building the polygon failed ({e}) - "
                             f"falling back to the pure-Python path.")

        if job:
            if self.backend == "shapely":
                job.info("Shapely acceleration active for containment tests.")
            elif not HAS_SHAPELY:
                job.info("Shapely is not installed - using the pure-Python path. "
                         "On large slabs, pip install shapely speeds this up.")

    def contains(self, x, y):
        """Is the point inside the concrete (not in an opening, not outside the boundary)?"""
        if self._prepared is not None:
            return self._prepared.contains(_ShpPoint(x, y))
        if not point_in_polygon(x, y, self.boundary):
            return False
        return not any(point_in_polygon(x, y, op) for op in self.openings)

    @property
    def area(self):
        if self._prepared is not None:
            return self._poly.area
        return polygon_area(self.boundary) - sum(polygon_area(o) for o in self.openings)


def polygon_intersection(subject, clip):
    """
    The overlap of two convex-or-simple polygons (Sutherland-Hodgman).

    Used to cut a pour strip by the slab or drop it sits on, so each piece
    takes the thickness underneath it. Shapely does it properly when present;
    the fallback is exact for a convex clip, which a rectangular drop or a
    straight strip always is.
    """
    if not subject or not clip or len(subject) < 3 or len(clip) < 3:
        return []

    if HAS_SHAPELY:
        try:
            a = _ShpPolygon(subject)
            b = _ShpPolygon(clip)
            if not a.is_valid:
                a = a.buffer(0)
            if not b.is_valid:
                b = b.buffer(0)
            inter = a.intersection(b)
            if inter.is_empty:
                return []
            geom = max(getattr(inter, "geoms", [inter]), key=lambda g: g.area)
            return [(x, y) for x, y in list(geom.exterior.coords)[:-1]]
        except Exception:
            pass

    def inside(p, a, b):
        return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]) >= 0

    def cut(p, q, a, b):
        d1 = (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0])
        d2 = (b[0] - a[0]) * (q[1] - a[1]) - (b[1] - a[1]) * (q[0] - a[0])
        if abs(d1 - d2) < 1e-12:
            return q
        t = d1 / (d1 - d2)
        return (p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1]))

    ring = list(clip)
    if _signed_area(ring) < 0:
        ring = ring[::-1]
    out = list(subject)
    for a, b in zip(ring, ring[1:] + ring[:1]):
        if not out:
            break
        nxt = []
        for p, q in zip(out, out[1:] + out[:1]):
            if inside(q, a, b):
                if not inside(p, a, b):
                    nxt.append(cut(p, q, a, b))
                nxt.append(q)
            elif inside(p, a, b):
                nxt.append(cut(p, q, a, b))
        out = nxt
    return out


def _signed_area(poly):
    s = 0.0
    for a, b in zip(poly, poly[1:] + poly[:1]):
        s += a[0] * b[1] - b[0] * a[1]
    return s / 2.0


# ==============================================================================
#  القسم 2 — قراءة الـ DXF: اكتشاف الليّرات ثم استخراج الهندسة
# ==============================================================================

class CancelledError(Exception):
    """The user pressed Stop."""
    pass


class Job:
    """
    وسيط بين الخيط العامل والواجهة: تسجيل، تقدّم، وإلغاء.
    كل عملية طويلة بتستدعي job.check() عشان تحترم زرار الإيقاف.
    """

    def __init__(self, log_cb=None, progress_cb=None):
        self._log = log_cb or (lambda msg, level="info": None)
        self._progress = progress_cb or (lambda frac, text="": None)
        self.cancel_event = threading.Event()
        #  **18.85: آخر خطوة اتقالت، وعدد السطور اللي بتقول "مااتعملش".**
        #  رن خرج من نصّه من غير ما يقول ليه - اللوج وقف بعد التخطيط
        #  ومافيش كابل اترسم ولا ملف اتحفظ ولا سطر خطأ واحد. الرقمين
        #  دول بيخلّوا المسار يقدر يقول ده في الآخر.
        self.last_step = ""
        self.errors = 0

    def log(self, msg, level="info"):
        if level == "error":
            self.errors += 1
        self._log(msg, level)

    def info(self, msg):
        self._log(msg, "info")

    def ok(self, msg):
        self._log(msg, "ok")

    def warn(self, msg):
        self._log(msg, "warn")

    def error(self, msg):
        self.errors += 1
        self._log(msg, "error")

    def flag(self, msg):
        """
        **سطر لازم يتشاف** (18.81).

        اللوج بيطلع 1,400 سطر على دور واحد، وفيه عشر سطور بس بتغيّر
        قرار: الموديل وصل بكام قطاع راسب، الهندسة كلّفت كام، الرن
        اترجّع، الحديد راح في ظل كمرة، التقريب تمنه كام. المهندس قال
        «عايز أشوف التنبيهات المهمة لوحدها وواضحة عشان آخد بالي» -
        ودي العلامة.

        مش تحذير: التحذير معناه «فيه حاجة غلط». العلامة معناها «ده
        رقم القرار متعلّق بيه»، حتى لو الخبر كويس.
        """
        self._log(msg, "flag")

    def step(self, frac, text=""):
        if text:
            self.last_step = text
        self._progress(frac, text)

    def cancel(self):
        self.cancel_event.set()

    def check(self):
        if self.cancel_event.is_set():
            raise CancelledError()


def guess_role(layer_name):
    """
    ترشيح دور الليّر من اسمه. بترجع (role, confidence 0..1).
    التقييم: تطابق كلمة كاملة أقوى من بداية كلمة أقوى من مجرد احتواء.
    """
    name = (layer_name or "").strip().lower()
    if not name:
        return "ignore", 0.0
    tokens = [t for t in re.split(r"[^0-9a-z\u0600-\u06FF]+", name) if t]
    # Also match against the name with separators removed, so "x direction",
    # "X-Direction" and "XDIRECTION" are all the same layer to us. Without
    # this a layer called "x direction" scored nothing and fell to ignore.
    squashed = "".join(tokens)

    best_role, best_score = "ignore", 0.0
    for role in ROLE_ORDER:
        score = 0.0
        for kw in ROLE_KEYWORDS[role]:
            if kw in tokens:
                score = max(score, 1.0)
            elif len(kw) >= 5 and kw == squashed:
                score = max(score, 1.0)
            elif any(t.startswith(kw) and len(kw) >= 4 for t in tokens):
                score = max(score, 0.75)
            elif len(kw) >= 5 and kw in squashed:
                score = max(score, 0.6)
            elif len(kw) >= 4 and kw in name:
                score = max(score, 0.5)
        if score > best_score:
            best_role, best_score = role, score
    return best_role, best_score


#  17.67: اللي بيتشال بصمت أثناء القراءة بيتعدّ، وparse_dxf بتقوله في
#  اللوج. بلوك فشل فكّه أو أعمق من 3 مستويات كان بيختفي من غير أثر،
#  والمهندس يفضل يدوّر ليه الفتحة اللي في اللوحة مش في الموديل.
_DXF_SKIPPED = {"blocks_failed": 0, "blocks_too_deep": 0, "entities": 0}


def _reset_dxf_skipped():
    for k in _DXF_SKIPPED:
        _DXF_SKIPPED[k] = 0


def _iter_entities(container, depth=0, inherited_layer=None, max_depth=3):
    """
    [F07] مرور على كل الكيانات مع فكّ البلوكات (INSERT) لحد 3 مستويات.
    الكيان اللي ليّره '0' جوه بلوك بيرث ليّر الـ INSERT نفسه — ده سلوك الأوتوكاد.
    """
    if depth == 0:
        #  كل مرور من أول الملف بيبدأ العدّ من الصفر - القراءة الكاملة
        #  بتمر على الملف أكتر من مرة وكل مرة بتشوف نفس البلوكات.
        _reset_dxf_skipped()
    for e in container:
        try:
            etype = e.dxftype()
        except Exception:
            _DXF_SKIPPED["entities"] += 1
            continue

        own_layer = safe_get(e.dxf, "layer", "") or ""
        layer = inherited_layer if (own_layer.strip() in ("", "0") and inherited_layer) else own_layer

        if etype == "INSERT":
            if depth >= max_depth:
                _DXF_SKIPPED["blocks_too_deep"] += 1
                continue
            try:
                sub = list(e.virtual_entities())
            except Exception:
                _DXF_SKIPPED["blocks_failed"] += 1
                continue
            yield from _iter_entities(sub, depth + 1, layer, max_depth)
        else:
            yield e, layer


#  الملف بيتقرا مرة واحدة (17.67): فحص الليّرات ثم القراءة الكاملة كانوا
#  بيفتحوه مرتين. آخر ملف اتقرا بيتحفظ مع وقت تعديله وحجمه، ولو اتغيّر
#  على القرص بيتقرا تاني.
_DXF_DOC_CACHE = {"key": None, "doc": None}


def read_dxf_doc(dxf_path):
    import ezdxf
    try:
        st = os.stat(dxf_path)
        key = (os.path.normcase(os.path.abspath(dxf_path)), st.st_mtime_ns,
               st.st_size)
    except OSError:
        key = None
    if key is not None and _DXF_DOC_CACHE["key"] == key:
        return _DXF_DOC_CACHE["doc"]
    doc = ezdxf.readfile(dxf_path)
    _DXF_DOC_CACHE["key"] = key
    _DXF_DOC_CACHE["doc"] = doc
    return doc


def scan_dxf_layers(dxf_path):
    """
    فحص أولي للملف: بيرجع قائمة بكل ليّر فيه كيانات فعلية، مع دوره المقترح.
    ده اللي بيتعرض في شاشة تأكيد الليّرات.
    """
    doc = read_dxf_doc(dxf_path)
    msp = doc.modelspace()

    counts = {}
    for e, layer in _iter_entities(msp):
        key = layer.strip()
        if not key:
            continue
        rec = counts.setdefault(key, {"count": 0, "types": {}})
        rec["count"] += 1
        t = e.dxftype()
        rec["types"][t] = rec["types"].get(t, 0) + 1

    insunits = 0
    try:
        insunits = int(doc.header.get("$INSUNITS", 0))
    except Exception:
        pass

    layers = []
    for name, rec in sorted(counts.items(), key=lambda kv: -kv[1]["count"]):
        role, conf = guess_role(name)
        if conf < 0.5:
            role = "ignore"
        types = ", ".join(f"{k}×{v}" for k, v in
                          sorted(rec["types"].items(), key=lambda kv: -kv[1])[:3])
        layers.append({
            "name": name,
            "count": rec["count"],
            "types": types,
            "role": role,
            "confidence": conf,
        })

    return layers, insunits


def changelog_text(limit=None):
    """نص سجل التغييرات من الجدول اللي جوّه البرنامج."""
    out = [f"# {APP_NAME} - version history", ""]
    for i, (ver, when, notes) in enumerate(CHANGES):
        if limit is not None and i >= limit:
            break
        out.append(f"## {ver}  -  {when}")
        out.append("")
        for n in notes:
            out.append(f"- {n}")
        out.append("")
    return "\n".join(out)


def _version_tuple(text):
    try:
        return tuple(int(x) for x in str(text).strip().split("."))
    except Exception:
        return (0,)


def changelog_path(folder=None):
    try:
        here = folder or os.path.dirname(os.path.abspath(__file__))
    except Exception:
        here = folder or os.getcwd()
    return os.path.join(here, "CHANGELOG.md")


def newest_changelog_version(path=None):
    """
    أعلى إصدار مكتوب في CHANGELOG.md، أو None لو الملف مش موجود.

    السطر بيبقى "## 17.68  -  2026-09-13" أو "## 17.59 … 17.61  -  ..."؛
    بناخد أعلى رقم في عناوين المستوى التاني.
    """
    path = path or changelog_path()
    if not os.path.isfile(path):
        return None
    best = None
    try:
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                if not line.startswith("## "):
                    continue
                for ver in re.findall(r"\b(\d+\.\d+(?:\.\d+)?)\b",
                                      line.split("-")[0]):
                    if best is None or _version_tuple(ver) > _version_tuple(best):
                        best = ver
    except Exception:
        return None
    return best


def write_changelog(folder=None):
    """
    يكتب CHANGELOG.md جنب البرنامج من الجدول اللي جوّه الكود - **بس لو
    الملف مش موجود أو الجدول أحدث منه.**

    17.69: الجدول جوّه الكود واقف عند 3.9، والملف بقى بيتكتب بالإيد من
    وقتها لحد 17.x. النداء ده كان بيكتب فوقه بالنسخة القديمة ويضيّع
    السجل كله. لو الملف أحدث بيرمي RuntimeError بتقول كده.
    """
    path = changelog_path(folder)
    have = newest_changelog_version(path)
    table = CHANGES[0][0] if CHANGES else "0"
    if have and _version_tuple(have) >= _version_tuple(table):
        raise RuntimeError(
            f"CHANGELOG.md already holds versions up to {have}, written by "
            f"hand; the built-in table ends at {table}. Nothing was "
            f"overwritten - edit the file directly.")
    with open(path, "w", encoding="utf-8") as fh:
        fh.write(changelog_text())
        fh.write("\n")
    return path


def changelog_version_note():
    """سطر تحذير لو أحدث إصدار في CHANGELOG.md مش هو النسخة الشغالة."""
    have = newest_changelog_version()
    if have is None:
        return None
    if _version_tuple(have) != _version_tuple(APP_VERSION):
        return (f"This build is {APP_VERSION} but CHANGELOG.md tops out at "
                f"{have} - the record beside the program does not describe "
                f"this build.")
    return None


def build_stamp():
    """
    Which file is actually running, and when it was last written.

    Not a nicety. Every version of this program is one .py file that gets
    copied around, renamed and edited, and more than one puzzling run has
    turned out to be the previous copy: the log said exactly what the old
    build says because it WAS the old build. The name, the timestamp and a
    short hash of the source settle that in one line.
    """
    try:
        path = os.path.abspath(__file__)
        name = os.path.basename(path)
        with open(path, "rb") as fh:
            src = fh.read()
        digest = hashlib.sha1(src).hexdigest()[:8]
        when = datetime.datetime.fromtimestamp(
            os.path.getmtime(path)).strftime("%Y-%m-%d %H:%M")
        return (f"Version {APP_VERSION} · {name} · saved {when} · "
                f"{digest} · {len(src):,} bytes")
    except Exception:
        return "Build: could not read this script's own file."


def plan_size_is_sensible(span_m, sanity_max=500.0):
    """
    المقاس ده مقاس دور، ولا رقم غلط؟

    الوحدة الغلط مابتفشلش - بتنجح بالمقاس الغلط: رسمة بالملليمتر
    بتتقرا بالمتر بتدّي بلاطة بالكيلومترات وكل عمود بيتبلع جوّه
    "بلاطة". وده بيبان في المقاس نفسه، فالمقاس هو الحَكَم.
    """
    try:
        span = float(span_m)
        hi = max(float(sanity_max or 500.0), 10.0)
    except (TypeError, ValueError):
        return False
    return (hi / 100.0) <= span <= hi


def _scale_that_makes_sense(sample_max_coord, sanity_max=500.0, skip=None):
    """
    معامل الوحدة اللي بيخلّي الرسمة دور - أو None لو مافيش.

    الترتيب بيفضّل الأقرب لحجم الدور المعتاد (10-150 م)، عشان رسمة
    صغيرة ماتتقراش بالوحدة اللي بتكبّرها لكيلومترات لمجرد إنها "جوّه
    الحد".
    """
    best, score = None, None
    for f in sorted(set(v for v in UNIT_CHOICES.values() if v)):
        if skip is not None and abs(f - skip) < 1e-12:
            continue
        span = float(sample_max_coord) * f
        if not plan_size_is_sensible(span, sanity_max):
            continue
        #  بُعد لوغاريتمي عن 40 م - وسط الأدوار
        d = abs(math.log(max(span, 1e-6) / 40.0))
        if score is None or d < score:
            best, score = f, d
    return best


def resolve_unit_scale(chosen_label, insunits, sample_max_coord, job,
                       sanity_max=500.0):
    """
    [F03] تحديد معامل التحويل للمتر قبل أي معالجة هندسية.
    الأولوية: اختيار المستخدم ← $INSUNITS ← تخمين من حجم الإحداثيات.
    """
    explicit = UNIT_CHOICES.get(chosen_label)
    if explicit is not None:
        job.info(f"Unit: manual choice ({chosen_label}) - scale factor {explicit}")
        # The manual choice wins, but it is worth saying loudly when the file
        # disagrees with it. Getting this wrong does not fail - it succeeds
        # quietly at the wrong scale: a 300 mm column read as metres becomes a
        # 300 m slab, every column and wall disappears into "slab", and the
        # run finishes with a model 237 km across and no supports in it.
        header = INSUNITS_TO_M.get(insunits)
        span = sample_max_coord * explicit
        #  **الحجم هو اللي بيحكم، مش الهيدر (17.30).** هيدر غلط مع اختيار
        #  صح بيدّي دور سليم - ورسالة تحذير في الحالة دي ضوضاء بتتحط وسط
        #  السطور اللي بتهم. الهيدر بيتذكر بس لما القراءة تطلع مش منطقية.
        if plan_size_is_sensible(span, sanity_max):
            if header is not None and abs(header - explicit) > 1e-9:
                job.info(
                    f"Unit: the file header says $INSUNITS={insunits} "
                    f"(factor {header}), which disagrees with {chosen_label}. "
                    f"The drawing reads as {span:,.0f} m across either way, so "
                    f"the choice here is taken and the header is left alone.")
            return explicit
        if header is not None and abs(header - explicit) > 1e-9:
            job.warn(
                f"Unit: the file says $INSUNITS={insunits} (factor {header}), "
                f"but the unit chosen here is {chosen_label} (factor "
                f"{explicit}) - everything is read {explicit / header:,.0f} "
                f"times too big, and the drawing comes out {span:,.0f} m "
                f"across, which is not a floor plate. That is why the columns "
                f"and walls will be missing.")
        else:
            job.warn(
                f"Unit: with {chosen_label} this drawing is about "
                f"{span:,.0f} m across, which is not a floor plate. Check the "
                f"unit before reading anything into the result.")
        return explicit

    if insunits in INSUNITS_TO_M:
        s = INSUNITS_TO_M[insunits]
        span = sample_max_coord * s
        #  **والهيدر بيتشك زي الاختيار اليدوي.** الفرع ده كان بياخد
        #  $INSUNITS زي ما هو من غير أي فحص، والفرع اليدوي فوقه بيفحص -
        #  فرق مالوش مبرر. على MASA-FIRST الهيدر بيقول بوصة والملف
        #  بالمتر: 53 × 0.0254 = 1.35 م. النتيجة كانت 32 عمود عرضهم
        #  6-13 مم اترفضوا كلهم، صفر خط ركائز، وفي الآخر "مفيش كابل
        #  ينفع يترسم" - وكل ده من سطر وحدة.
        if plan_size_is_sensible(span, sanity_max):
            job.info(f"Unit: read from the DXF header ($INSUNITS={insunits}) "
                     f"- scale factor {s}")
            return s
        alt = _scale_that_makes_sense(sample_max_coord, sanity_max, skip=s)
        if alt is not None:
            job.warn(
                f"Unit: the header says $INSUNITS={insunits} (factor {s}), "
                f"and at that scale the drawing is {span:,.2f} m across - "
                f"which is not a floor. Reading it as factor {alt} instead "
                f"({sample_max_coord * alt:,.0f} m across), because a header "
                f"is metadata and the coordinates are the drawing. Pick the "
                f"unit by hand and run again if that is wrong.")
            return alt
        job.warn(f"Unit: the header says $INSUNITS={insunits} (factor {s}), "
                 f"and at that scale the drawing is {span:,.2f} m across - "
                 f"which is not a floor, and no other unit makes it one "
                 f"either. Check the drawing, and set the unit by hand.")
        return s

    alt = _scale_that_makes_sense(sample_max_coord, sanity_max)
    if alt is not None:
        job.warn(f"Unit: the file has no $INSUNITS. At factor {alt} the "
                 f"drawing is {sample_max_coord * alt:,.0f} m across, which "
                 f"is a floor - that is the one taken. Pick the unit "
                 f"manually and run again if it is wrong.")
        return alt
    s = 0.001 if sample_max_coord > 1000.0 else 1.0
    job.warn(f"Unit: the file has no $INSUNITS. Guessing from coordinate magnitude "
             f"(max coordinate ≈ {sample_max_coord:,.0f}) -> factor {s}. "
             f"If that is wrong, pick the unit manually and run again.")
    return s


def _entity_points(entity, etype, flat_tol=0.05):
    """Extract flattened points from any supported linear entity."""
    import ezdxf.path

    if etype in ("LWPOLYLINE", "POLYLINE", "SPLINE", "ELLIPSE"):
        try:
            path = ezdxf.path.make_path(entity)
            return [(float(p.x), float(p.y)) for p in path.flattening(distance=flat_tol)]
        except Exception:
            pass
        try:
            return [(float(p[0]), float(p[1])) for p in entity.get_points("xy")]
        except Exception:
            return []

    if etype == "LINE":
        try:
            s, e = entity.dxf.start, entity.dxf.end
            return [(float(s[0]), float(s[1])), (float(e[0]), float(e[1]))]
        except Exception:
            return []

    if etype == "ARC":
        #  17.65: طول القطعة بوحدة الملف. flat_tol هنا هو التسامح بالمتر
        #  مقسوم على المقياس (raw_flat_tol)، فـ flat_tol·5 = 0.25 م في
        #  وحدة الملف أياً كانت. الحد الأدنى القديم 0.25 كان بالمتر لكن
        #  بيتطبق على المليمتر: قطعة كل ربع مليمتر.
        try:
            c = entity.dxf.center
            return discretize_arc((float(c[0]), float(c[1])),
                                  float(entity.dxf.radius),
                                  float(entity.dxf.start_angle),
                                  float(entity.dxf.end_angle),
                                  max_seg=flat_tol * 5)
        except Exception:
            return []

    if etype in ("SOLID", "TRACE", "3DFACE"):
        try:
            pts = []
            for name in ("vtx0", "vtx1", "vtx3", "vtx2"):   # ترتيب SOLID متعرّج
                v = safe_get(entity.dxf, name)
                if v is not None:
                    pts.append((float(v[0]), float(v[1])))
            return pts
        except Exception:
            return []

    if etype == "CIRCLE":
        try:
            c = entity.dxf.center
            return discretize_arc((float(c[0]), float(c[1])),
                                  float(entity.dxf.radius), 0.0, 360.0,
                                  max_seg=flat_tol * 5)
        except Exception:
            return []

    return []


def hatch_boundary_points(entity, flat_tol=0.05):
    """
    نقط حدود الـ HATCH. كتير من الرسومات بترسم الأعمدة كمساحة متهاشرة
    من غير أي بوليلاين ظاهر، والنسخة القديمة كانت بتتجاهلها تمامًا.
    بترجع قائمة مسارات (كل مسار قائمة نقط).
    """
    import ezdxf.path

    paths = []
    try:
        for p in entity.paths:
            pts = []
            try:
                pts = [(float(v[0]), float(v[1])) for v in p.vertices]
            except Exception:
                try:
                    conv = ezdxf.path.from_hatch_boundary_path(p)
                    pts = [(float(v.x), float(v.y))
                           for v in conv.flattening(distance=flat_tol)]
                except Exception:
                    continue
            if len(pts) >= 3:
                paths.append(pts)
    except Exception:
        pass
    return paths


def column_from_points(points, min_side_mm=150.0, max_side_mm=4000.0):
    """
    تحويل أي شكل مقفول لعمود، مهما كان عدد رؤوسه.
    بتستخدم أصغر مستطيل محيط بدل ما تطلب مضلع رباعي بالظبط — ده بيغطي
    الأركان المشطوفة، والرؤوس الزيادة، والـ HATCH، والأشكال الدائرية.
    بترجع dict العمود أو (None, سبب الرفض).
    """
    pts = clean_polygon(points)
    if len(pts) < 3:
        return None, "fewer than 3 vertices"

    area = polygon_area(pts)
    if area <= 1e-9:
        return None, "zero area"

    rect = min_area_rect(pts)
    if rect is None:
        return None, "could not compute the bounding rectangle"

    long_mm = rect["long"] * 1000.0
    short_mm = rect["short"] * 1000.0

    if short_mm < min_side_mm:
        return None, f"smallest side {short_mm:.0f} mm is below the {min_side_mm:.0f} limit"
    if long_mm > max_side_mm:
        return None, f"largest side {long_mm:.0f} mm exceeds the {max_side_mm:.0f} limit (probably a wall)"
    if long_mm / max(short_mm, 1e-6) > 6.0:
        return None, f"aspect {long_mm / short_mm:.1f}:1 - this is a wall, not a column"

    circ = circularity(pts)
    if circ > 0.90 and len(pts) >= 8:
        d = math.sqrt(4.0 * area / math.pi) * 1000.0
        return {
            "center": polygon_centroid(pts),
            "b": round_to(d, 50.0),
            "d": round_to(d, 50.0),
            "angle_deg": 0.0,
            "circular": True,
        }, None

    # فحص امتلاء: لو المضلع مالي أقل من 60% من المستطيل، ده مش عمود
    fill = area / max(rect["area"], 1e-9)
    if fill < 0.60:
        return None, f"the shape fills only {fill * 100:.0f}% of its bounding rectangle"

    return {
        "center": rect["center"],
        "b": round_to(long_mm, 50.0),
        "d": round_to(short_mm, 50.0),
        "angle_deg": rect["angle_deg"],
        "circular": False,
    }, None


LABEL_SECTION_RE = re.compile(r"(\d{2,4})\s*[xX×*]\s*(\d{2,4})")
LABEL_THICKNESS_RE = re.compile(r"\bt\s*=\s*(\d{2,4})", re.I)
LABEL_PRIORITY_RE = re.compile(r"priority\s*=\s*(\d+)", re.I)


def clean_mtext(raw):
    r"""Strip MTEXT formatting codes: \P for newline, \f for font, and so on."""
    if not raw:
        return ""
    txt = raw.replace("\\P", " ").replace("\\p", " ")
    txt = re.sub(r"\\[A-Za-z][^;\\]*;?", " ", txt)
    txt = txt.replace("{", " ").replace("}", " ")
    return re.sub(r"\s+", " ", txt).strip()


def classify_mixed_shape(points, label=None, max_col_side=1500.0, wall_aspect=6.0,
                         min_col_side=100.0):
    """
    تصنيف مضلع مقفول في ليّر مختلط لواحد من: column / wall / slab.

    القاعدة: **الشكل هو اللي بيحدد النوع، والتسمية بتضبط الأبعاد بس.**

    التسمية لوحدها مضلّلة: "t=300" معناها سمك البلاطة على مساحة كبيرة،
    وسمك الحائط على عنصر ضيق طويل. الاعتماد عليها أولاً كان بيحوّل أعمدة
    300×575 لبلاطات فتختفي من الموديل تمامًا.

    الاستثناء الوحيد: وجود "Priority=" دلالة قاطعة على منطقة بلاطة في
    RAM Concept، وده بيتغلّب على الشكل.

    بترجع (kind, info).
    """
    pts = clean_polygon(points)
    if len(pts) < 3:
        return None, None

    rect = min_area_rect(pts)
    if rect is None:
        return None, None
    short_mm = rect["short"] * 1000.0
    long_mm = rect["long"] * 1000.0
    aspect = long_mm / max(short_mm, 1e-6)

    text = clean_mtext(label) if label else ""
    section = LABEL_SECTION_RE.search(text) if text else None
    thickness = LABEL_THICKNESS_RE.search(text) if text else None
    priority = LABEL_PRIORITY_RE.search(text) if text else None

    # 1) Priority= → منطقة بلاطة، مهما كان حجمها
    if priority:
        return "slab", {
            "thickness": float(thickness.group(1)) if thickness else None,
            "priority": int(priority.group(1)),
            "label": text,
        }

    # 2) الشكل بيحدد النوع
    if short_mm < min_col_side:
        # أصغر من أي مقطع حقيقي — شخبطة أو خط تنسيق.
        # لو عدّت، التقريب لأقرب 50 مم بيخليها بُعد صفر، و RAM بيرد
        # بـ "An entity has become misshaped" وقت التحليل.
        return None, None

    if short_mm <= max_col_side:
        kind = "column" if aspect <= wall_aspect else "wall"
    else:
        kind = "slab"

    # 3) التسمية بتضبط الأبعاد جوه النوع اللي الشكل حدده
    if kind == "column":
        b, d = long_mm, short_mm
        if section:
            v1, v2 = float(section.group(1)), float(section.group(2))
            # نقبل المقطع المكتوب لو قريب من المقاس المرسوم
            if abs(max(v1, v2) - long_mm) < max(long_mm * 0.35, 150.0):
                b, d = max(v1, v2), min(v1, v2)
        elif thickness:
            d = float(thickness.group(1))
        return "column", {"b": b, "d": d, "rect": rect, "label": text}

    if kind == "wall":
        width = short_mm
        if thickness:
            width = float(thickness.group(1))
        elif section:
            width = min(float(section.group(1)), float(section.group(2)))
        return "wall", {"width": max(width, 100.0), "rect": rect, "label": text}

    return "slab", {"thickness": float(thickness.group(1)) if thickness else None,
                    "priority": None, "label": text}


def rect_centerline(rect):
    """Centreline along the longest side of the bounding rectangle, for walls and beams."""
    cx, cy = rect["center"]
    half = rect["long"] / 2.0
    a = math.radians(rect["angle_deg"])
    return ((cx - half * math.cos(a), cy - half * math.sin(a)),
            (cx + half * math.cos(a), cy + half * math.sin(a)))


def dedupe_columns(columns, tol=0.25):
    """
    دمج الأعمدة المكررة. شائع جدًا إن العمود يكون مرسوم مرتين: كونتور + هاتش،
    أو بوليلاين + بلوك. من غير الدمج ده بيتحط عمودين فوق بعض في الموديل.
    """
    out = []
    for c in columns:
        merged = False
        for o in out:
            if dist(c["center"], o["center"]) <= tol:
                # نحتفظ بالأكبر — الكونتور عادة أدق من الهاتش
                if c["b"] * c["d"] > o["b"] * o["d"]:
                    o.update(c)
                merged = True
                break
        if not merged:
            out.append(dict(c))
    return out


def rect_from_quad(quad):
    """
    من مضلع رباعي (عمود/كمرة مرسومة كمستطيل): المركز، العرض، العمق، الزاوية.
    الأبعاد بالمليمتر والزاوية بالدرجات في المدى (-90, 90].
    """
    if len(quad) < 4:
        return None
    p0, p1, p2, p3 = quad[:4]
    edges = [(p0, p1, dist(p0, p1)),
             (p1, p2, dist(p1, p2)),
             (p2, p3, dist(p2, p3)),
             (p3, p0, dist(p3, p0))]
    edges.sort(key=lambda e: e[2])
    short1, short2, long1, long2 = edges

    cx = sum(p[0] for p in quad[:4]) / 4.0
    cy = sum(p[1] for p in quad[:4]) / 4.0

    def angle_of(e):
        return normalize_angle_deg(math.degrees(
            math.atan2(e[1][1] - e[0][1], e[1][0] - e[0][0])))

    # نختار الضلع الأقرب للأفقي كمرجع — يخلي b دايمًا في اتجاه الزاوية
    ref = min((long1, long2, short1, short2), key=lambda e: abs(angle_of(e)))
    b_mm = long1[2] * 1000.0
    d_mm = short1[2] * 1000.0
    if ref in (short1, short2):
        b_mm, d_mm = d_mm, b_mm

    return {
        "center": (cx, cy),
        "b": b_mm,
        "d": d_mm,
        "angle_deg": round(angle_of(ref), 2),
        "length": max(long1[2], long2[2]),
    }


def centerline_of_quad(quad):
    """Centreline and thickness of a linear member drawn as a rectangle. Thickness in mm."""
    if len(quad) < 4:
        return None
    a = dist(quad[0], quad[1])
    b = dist(quad[1], quad[2])
    if a > b:
        c1 = ((quad[0][0] + quad[3][0]) / 2.0, (quad[0][1] + quad[3][1]) / 2.0)
        c2 = ((quad[1][0] + quad[2][0]) / 2.0, (quad[1][1] + quad[2][1]) / 2.0)
        return c1, c2, b * 1000.0
    c1 = ((quad[0][0] + quad[1][0]) / 2.0, (quad[0][1] + quad[1][1]) / 2.0)
    c2 = ((quad[3][0] + quad[2][0]) / 2.0, (quad[3][1] + quad[2][1]) / 2.0)
    return c1, c2, a * 1000.0


def _rect_of(poly):
    """
    الطول والعرض واتجاه أصغر مستطيل يحيط بمضلع.

    الاتجاه بيتاخد من **أضلاع** المضلع، مش من أبعد ركنين. القُطر بتاع
    مستطيل 12×0.30 مايل شوية عن ضلعه الطويل، وقياس العرض عليه بيطلّع
    0.60 بدل 0.30 - يعني ضعف الحقيقة. المستطيل الأصغر مساحةً لازم
    يكون أحد أضلاعه موازي لضلع من المضلع، ودي القاعدة اللي بنمشي عليها.
    """
    import math
    if not poly or len(poly) < 3:
        return None
    best = None
    n = len(poly)
    for i in range(n):
        a, b = poly[i], poly[(i + 1) % n]
        L = dist(a, b)
        if L < 1e-9:
            continue
        ux, uy = (b[0] - a[0]) / L, (b[1] - a[1]) / L
        ts = [(q[0] - a[0]) * ux + (q[1] - a[1]) * uy for q in poly]
        vs = [-(q[0] - a[0]) * uy + (q[1] - a[1]) * ux for q in poly]
        w = max(ts) - min(ts)
        h = max(vs) - min(vs)
        if best is None or w * h < best[0]:
            best = (w * h, w, h, ux, uy)
    if best is None:
        return None
    _, w, h, ux, uy = best
    if h > w:                       # الطول هو الأكبر دايمًا
        w, h = h, w
        ux, uy = -uy, ux
    cx = sum(q[0] for q in poly) / len(poly)
    cy = sum(q[1] for q in poly) / len(poly)
    return {"length": w, "width": h,
            "angle": math.degrees(math.atan2(uy, ux)) % 180.0,
            "ux": ux, "uy": uy, "centre": (cx, cy), "poly": poly}


def detect_ribbed_regions(site, params, job=None):
    """
    يتعرّف على البلاطة المعصّبة (Ribbed) وسط البلاطة العادية.

    العصب مرسوم على ليّر الدروب زي أي منطقة أسمك، فالبرنامج كان بيقراه
    دروب بانل: بيرفع الكابل فوقه ويسيبه مفرود. وده غلط تمامًا - العصب
    مش ركيزة، هو **كمرة صغيرة** الكابل بيمشي جواها وينزل فيها.

    التعرّف بأربع علامات مع بعض، ومحدش فيهم كافي لوحده:
      • السمك ضعف سمك البلاطة على الأقل - ده اللي بيفرّق العصب عن
        دروب عادي.
      • الشكل مستطيل طويل: الطول على الأقل تلات أضعاف العرض.
      • متوازيين: كلهم في اتجاه واحد في حدود عشر درجات.
      • **متكررين بانتظام**: المسافات بين مراكزهم متقاربة. تلات
        مستطيلات متفرقة مش بلاطة معصّبة؛ خمسة على مسافات متساوية هي.

    بترجع قائمة مناطق، كل واحدة بمركز عصبها وتباعدها واتجاهها.
    """
    import math

    drops = site.get("drops") or []
    if len(drops) < 3:
        return []
    if params.drop_thickness < 2.0 * params.slab_thickness:
        return []

    rects = [r for r in (_rect_of(dp) for dp in drops) if r]
    rects = [r for r in rects
             if r["width"] > 0.05 and r["length"] >= 3.0 * r["width"]]
    if len(rects) < 3:
        return []

    #  تجميع بالاتجاه: الزاوية زاوية خط مش متجه، فـ 179° و1° نفس الشيء.
    groups = []
    for r in rects:
        for g in groups:
            d = abs(g[0]["angle"] - r["angle"]) % 180.0
            if min(d, 180.0 - d) <= 10.0:
                g.append(r)
                break
        else:
            groups.append([r])

    out = []
    for g in groups:
        if len(g) < 3:
            continue
        ang = math.radians(sum(x["angle"] for x in g) / len(g))
        ux, uy = math.cos(ang), math.sin(ang)
        #  الإحداثي العمودي على العصب هو اللي بيحدد التباعد
        for r in g:
            r["v"] = -r["centre"][0] * uy + r["centre"][1] * ux
            r["t"] = r["centre"][0] * ux + r["centre"][1] * uy
        g.sort(key=lambda r: r["v"])
        gaps = [g[i + 1]["v"] - g[i]["v"] for i in range(len(g) - 1)]
        gaps = [x for x in gaps if x > 0.05]
        if len(gaps) < 2:
            continue
        med = sorted(gaps)[len(gaps) // 2]
        if med <= 1e-6:
            continue
        spread = sum(abs(x - med) for x in gaps) / len(gaps) / med
        if spread > 0.35:
            continue                     # متفرقين، مش نمط منتظم
        out.append({
            "ribs": [r["poly"] for r in g],
            "centres": [r["centre"] for r in g],
            "coords": [r["v"] for r in g],
            "along": [r["t"] for r in g],
            "angle": math.degrees(ang) % 180.0,
            "spacing": med,
            "width": sum(r["width"] for r in g) / len(g),
            "length": max(r["length"] for r in g),
        })

    if job:
        for reg in out:
            job.ok(f"Ribbed slab found: {len(reg['ribs'])} ribs at "
                   f"{reg['angle']:.0f}°, {reg['spacing']:.2f} m centres, "
                   f"each about {reg['width']:.2f} m wide and "
                   f"{reg['length']:.1f} m long. A rib is not a drop panel - "
                   f"it is a small beam, so a tendon runs down the middle of "
                   f"each one instead of the usual sweep, and its low point "
                   f"sits {params.drop_sag_from_soffit:g} mm above the rib "
                   f"soffit.")
    return out


def _polygon_diameter(poly):
    """
    أطول بُعد في مضلع: أكبر مسافة بين أي ركنين.

    مش ضلع ولا مستطيل محيط: الدروب بانل ممكن يكون على شكل L أو مايل،
    والمسافة بين أبعد ركنين هي اللي بتقول «ده دروب طويل ولا قطعة فوق
    عمود».
    """
    if not poly or len(poly) < 2:
        return 0.0
    best = 0.0
    for i in range(len(poly)):
        for j in range(i + 1, len(poly)):
            d = dist(poly[i], poly[j])
            if d > best:
                best = d
    return best


def thickness_from_layer_name(layer_name, default=300.0):
    """If the layer name contains a plausible thickness (100-2000 mm), use it."""
    for m in re.findall(r"\d+", layer_name or ""):
        v = float(m)
        if 100.0 <= v <= 2000.0:
            return v
    return default


#  مدى سمك الحائط المعماري المعقول. الرقمين دول مش تحكّم في الحساب —
#  هما فلتر على الرسم: أي "سمك" برّه المدى ده مش حائط، هو شكل تاني على
#  نفس الليّر (كنتور أوضة، بلوك، هاتش). لوحة حقيقية طلّعت "حائط" سمكه
#  5600 مم من مضلع مقفول على ليّر الحوائط، والحمل طلع 181 kN/م بدل 6.
ARCH_WALL_MIN_MM = 60.0
ARCH_WALL_MAX_MM = 500.0


def merge_collinear_runs(segments, gap_tol=0.12, perp_tol=0.03,
                         angle_tol_deg=2.0):
    """
    يوصّل قطع الخط المكسّرة إلى خط واحد متصل.

    اللوحة المعمارية بترسم وش الحائط قطع قطع: بيتقطع عند كل باب وكل
    تقاطع. في اللوحة اللي جربنا عليها كان فيه 820 خط، نصهم أقصر من متر،
    كلهم أفقي أو رأسي — يعني وشوش حوائط متكسّرة مش أثاث.

    ومزاوجة الوشوش على القطع دي بتفشل، لأن كسرات الوش الأيمن مش في نفس
    أماكن كسرات الوش الشمال. فبنجمّع اللي على نفس المستقيم الأول.

    التجميع بالتقريب (hash) بيفشل عند حدود الخانة: 0.0299 و0.0301
    بيقعوا في خانتين مختلفتين وهما نفس الخط. فبنعنقد بالترتيب والمقارنة
    مع الجار.
    """
    import math

    items = []
    for s in segments:
        a, b = s["p1"], s["p2"]
        dx, dy = b[0] - a[0], b[1] - a[1]
        L = math.hypot(dx, dy)
        if L < 0.05:
            continue
        ux, uy = dx / L, dy / L
        #  اتجاه موحّد: الخط ومعكوسه لازم يدّوا نفس المفتاح
        if ux < -1e-12 or (abs(ux) <= 1e-12 and uy < 0):
            ux, uy = -ux, -uy
        ang = math.degrees(math.atan2(uy, ux))          # [0, 180)
        off = -a[0] * uy + a[1] * ux
        t0 = a[0] * ux + a[1] * uy
        t1 = b[0] * ux + b[1] * uy
        items.append([ang, off, ux, uy, min(t0, t1), max(t0, t1)])

    if not items:
        return []

    def clusters(seq, key, tol):
        seq.sort(key=key)
        out, cur = [], [seq[0]]
        for it in seq[1:]:
            if key(it) - key(cur[-1]) <= tol:
                cur.append(it)
            else:
                out.append(cur)
                cur = [it]
        out.append(cur)
        return out

    runs = []
    for by_angle in clusters(items, lambda it: it[0], angle_tol_deg):
        for line in clusters(by_angle, lambda it: it[1], perp_tol):
            ux, uy = line[0][2], line[0][3]
            off = sum(it[1] for it in line) / len(line)
            ox, oy = -uy * off, ux * off
            spans = sorted((it[4], it[5]) for it in line)
            lo, hi = spans[0]
            merged = []
            for a, b in spans[1:]:
                if a - hi <= gap_tol:
                    hi = max(hi, b)
                else:
                    merged.append((lo, hi))
                    lo, hi = a, b
            merged.append((lo, hi))
            for a, b in merged:
                if b - a < 0.20:
                    continue
                runs.append({"p1": (ox + ux * a, oy + uy * a),
                             "p2": (ox + ux * b, oy + uy * b)})
    return runs


def pair_wall_faces(segments, min_t=ARCH_WALL_MIN_MM / 1000.0,
                    max_t=ARCH_WALL_MAX_MM / 1000.0, angle_tol_deg=6.0,
                    min_overlap=0.15):
    """
    يحوّل خطوط وشوش الحوائط لخطوط أوساط بأسماكها.

    الحائط المعماري مرسوم **وشين متوازيين**، مش خط واحد. لو أخدنا كل خط
    على إنه حائط، الحمل بيتحسب مرتين والخطوط بتقع على الوش مش على الوسط.

    والمزاوجة واحد-لواحد مبتنفعش: الوش الواحد بيتكسّر عند الأبواب، فوش
    طوله 10 متر ممكن يقابله تلات قطع على الناحية التانية. على لوحة
    حقيقية المزاوجة الجشعة واحد-لواحد لقت 152 حائط بس من 579 وش، مع إن
    447 منهم ليهم شريك على 150 أو 200 مم بالظبط.

    فالطريقة هنا مختلفة: كل وش بيدوّر على كل شركاؤه، وبيطلّع خط وسط لكل
    جزء مشترك على حدة. وعشان الحائط ما يتحسبش مرتين، الوش الواحد بس هو
    اللي بيكتب — اللي بُعده أصغر. التاني بيسكت.

    بترجع (walls, paired_count, single_count).
    """
    import math

    runs = []
    for s in segments:
        a, b = s["p1"], s["p2"]
        dx, dy = b[0] - a[0], b[1] - a[1]
        L = math.hypot(dx, dy)
        if L < 0.20:
            continue
        ux, uy = dx / L, dy / L
        if ux < -1e-12 or (abs(ux) <= 1e-12 and uy < 0):
            ux, uy = -ux, -uy
            a, b = b, a
        runs.append({"a": a, "L": L, "ux": ux, "uy": uy,
                     "ang": math.degrees(math.atan2(uy, ux)),
                     "off": -a[0] * uy + a[1] * ux,
                     "t0": a[0] * ux + a[1] * uy})

    n = len(runs)
    walls = []
    matched = [False] * n
    paired = 0

    for i in range(n):
        A = runs[i]
        for j in range(n):
            if i == j:
                continue
            B = runs[j]
            d = abs(A["ang"] - B["ang"]) % 180.0
            if min(d, 180.0 - d) > angle_tol_deg:
                continue
            t = abs(B["off"] - A["off"])
            if not (min_t <= t <= max_t):
                continue

            #  الجزء المشترك على محور A
            b0 = B["t0"]
            b1 = B["t0"] + B["L"] * (B["ux"] * A["ux"] + B["uy"] * A["uy"])
            lo = max(A["t0"], min(b0, b1))
            hi = min(A["t0"] + A["L"], max(b0, b1))
            if hi - lo < min_overlap:
                continue

            matched[i] = matched[j] = True
            #  واحد بس من الاتنين هو اللي بيكتب الحائط
            if (A["off"], i) > (B["off"], j):
                continue

            paired += 1
            off = (B["off"] - A["off"]) / 2.0
            ox, oy = -A["uy"] * off, A["ux"] * off
            base_x = A["a"][0] - A["ux"] * A["t0"]
            base_y = A["a"][1] - A["uy"] * A["t0"]
            walls.append({
                "p1": (base_x + A["ux"] * lo + ox,
                       base_y + A["uy"] * lo + oy),
                "p2": (base_x + A["ux"] * hi + ox,
                       base_y + A["uy"] * hi + oy),
                "width": t * 1000.0})

    singles = 0
    for i in range(n):
        if matched[i]:
            continue
        A = runs[i]
        singles += 1
        walls.append({"p1": A["a"],
                      "p2": (A["a"][0] + A["ux"] * A["L"],
                             A["a"][1] + A["uy"] * A["L"]),
                      "width": None})

    return walls, paired, singles


def wall_udl_check(site, params, job):
    """الحمل المكافئ للقواطيع، والمقارنة بالحمل اللي بنوازنه.

    بيتحسب بعد قراءة الرسمة على طول عشان يبقى متاح في **كل** الأوضاع.
    وضع "كابلات بس" مابيكتبش الأحمال في الرام، فالرقم ده كان مابيتحسبش
    فيه خالص - ولا حتى عشان التحذير. والفرق مش صغير: على الموديل ده
    470 حيطة و1036 م = 3.76 kN/m²، تلت الحمل الميت.
    """
    walls = (site or {}).get("arch_walls") or []
    boundary = (site or {}).get("boundary")
    if not walls or not boundary or len(boundary) < 3:
        return 0.0
    try:
        area = site_plan_area(site) or polygon_area(boundary)
        if area <= 1.0:
            job.warn("The slab boundary has no usable area, so the wall load "
                     "could not be spread over it.")
            return 0.0
        #  wall_line_load بترجّع (الحمل, السمك, الارتفاع الصافي, هل
        #  السمك اتقصّ) - مش رقم واحد. ضرب الـ tuple في مسافة كان بيرمي
        #  TypeError، والـ except كان بيبلعه ويرجّع صفر من غير ما يقول:
        #  اللوج طلع "walls 0.00 kN/m²" وهي 3.76.
        tot = sum(wall_line_load(w, params)[0] * dist(w["p1"], w["p2"])
                  for w in walls)
        udl = tot / area
    except Exception as e:
        job.warn(f"The architectural wall load could not be worked out "
                 f"({type(e).__name__}: {e}), so it is not in the balanced "
                 f"load. Every span will look satisfied.")
        return 0.0
    site["wall_udl"] = udl
    try:
        params.wall_udl = udl
    except Exception:
        pass
    dead = params.self_weight + params.sdl + udl
    bal = params.balanced_load
    job.info(f"Architectural walls spread over the slab: {udl:.2f} kN/m². "
             f"Dead load on the slab is {params.self_weight:.2f} self weight "
             f"+ {params.sdl:.2f} superimposed + {udl:.2f} walls = "
             f"{dead:.2f} kN/m², and the balanced load is {bal:.2f} "
             f"({100.0 * bal / max(dead, 1e-6):.0f}% of it).")
    #  الرقم بيتقال، والحكم للمهندس. الموازنة الواطية قرار تصميمي
    #  معتاد - بتقلّل عدد الكابلات وبتسيب الترخيم والشد للفحوصات
    #  والحديد العادي. البرنامج كان بيحذّر كل رن كأنها غلطة، وهي مش
    #  غلطة: هي اختيار.
    return udl


def parse_dxf(dxf_path, layer_roles, unit_label, job, flat_tol=0.05):
    """
    القراءة الكاملة. layer_roles: dict {layer_name: role}.
    بترجع site dict بكل الهندسة، الإحداثيات بالمتر والأسماك بالمليمتر.
    """
    job.step(0.05, "Opening the DXF file")
    _reset_dxf_skipped()
    doc = read_dxf_doc(dxf_path)
    msp = doc.modelspace()

    insunits = 0
    try:
        insunits = int(doc.header.get("$INSUNITS", 0))
    except Exception:
        pass

    # عيّنة سريعة لتخمين الوحدة لو لزم
    sample_max = 0.0
    for i, (e, _lyr) in enumerate(_iter_entities(msp)):
        if i > 400:
            break
        pts = _entity_points(e, e.dxftype(), flat_tol=1.0)
        for p in pts[:8]:
            sample_max = max(sample_max, abs(p[0]), abs(p[1]))

    scale = resolve_unit_scale(unit_label, insunits, sample_max, job)
    # تسامح التسطيح لازم يكون بوحدة الملف مش بالمتر
    raw_flat_tol = flat_tol / scale if scale > 0 else flat_tol

    slab_polys, drop_polys, openings = [], [], []
    slab_edges, drop_edges, opening_edges = [], [], []
    columns, walls, beams = [], [], []
    # حوائط معمارية (حِمل خطي) ومساند خطية — دورين جداد، هندستهم مقروءة زي
    # الحوائط بالظبط بس معناهم مختلف تمامًا في الموديل.
    arch_walls = []
    arch_face_edges = []      # وشوش الحوائط المعمارية قبل ما تتزاوج
    column_shapes = []        # مضلعات مقفولة مرشّحة كأعمدة
    column_edges = []         # خطوط مفتوحة في ليّر الأعمدة — تتخيّط بعدين
    column_reject = {}        # سبب الرفض → العدد
    mixed_shapes = []         # مضلعات ليّر مختلط، تتصنّف بعدين
    pour_strips = []          # construction joints - concrete, but no tendon crosses
    guides_x = []             # hand-drawn tendon routes, X family
    guides_y = []             # hand-drawn tendon routes, Y family
    mixed_labels = []         # (نقطة، نص) من الـ MTEXT في نفس الليّر
    column_layer_types = {}   # أنواع الكيانات اللي شفناها في ليّرات الأعمدة
    skipped = {"empty": 0, "tiny": 0}
    seen_types = {}

    job.step(0.12, "Reading entities")
    total_entities = 0

    for entity, layer in _iter_entities(msp):
        total_entities += 1
        if total_entities % 500 == 0:
            job.check()

        role = layer_roles.get(layer.strip(), "ignore")
        if role == "ignore":
            continue

        etype = entity.dxftype()
        seen_types[etype] = seen_types.get(etype, 0) + 1

        if role == "column":
            column_layer_types[etype] = column_layer_types.get(etype, 0) + 1

        # --- تسميات الليّر المختلط: "300 x 600" or "t=200 Priority=4" ---
        if role == "auto" and etype in ("MTEXT", "TEXT"):
            try:
                ip = safe_get(entity.dxf, "insert") or safe_get(entity.dxf, "align_point")
                txt = safe_get(entity, "text", None) or safe_get(entity.dxf, "text", "")
                if ip is not None and txt:
                    mixed_labels.append(((float(ip[0]) * scale, float(ip[1]) * scale),
                                         str(txt)))
            except Exception:
                pass
            continue

        # --- مساحات متهاشرة (HATCH): شائعة جدًا في رسم الأعمدة ---
        if etype == "HATCH":
            for path in hatch_boundary_points(entity, flat_tol=raw_flat_tol):
                pts = [(p[0] * scale, p[1] * scale) for p in path]
                if role == "column":
                    column_shapes.append(pts)
                elif role in ("slab", "drop"):
                    poly = clean_polygon(pts)
                    if len(poly) >= 3 and polygon_area(poly) > 0.01:
                        (slab_polys if role == "slab" else drop_polys).append(poly)
                elif role == "opening":
                    poly = clean_polygon(pts)
                    if len(poly) >= 3 and polygon_area(poly) > 0.005:
                        openings.append(poly)
                elif role in ("wall", "beam"):
                    rect = min_area_rect(clean_polygon(pts))
                    if rect and rect["long"] > 0.2:
                        half = rect["long"] / 2.0
                        a = math.radians(rect["angle_deg"])
                        cx, cy = rect["center"]
                        (walls if role == "wall" else beams).append({
                            "p1": (cx - half * math.cos(a), cy - half * math.sin(a)),
                            "p2": (cx + half * math.cos(a), cy + half * math.sin(a)),
                            "width": max(rect["short"] * 1000.0, 100.0)})
            continue

        # --- عمود دائري ---
        if etype == "CIRCLE" and role == "column":
            try:
                c = entity.dxf.center
                r_m = float(entity.dxf.radius) * scale
                columns.append({
                    "center": (float(c[0]) * scale, float(c[1]) * scale),
                    "b": 0.0,
                    "d": round_to(r_m * 2000.0, 50.0),
                    "angle_deg": 0.0,
                    "circular": True,
                })
            except Exception as ex:
                column_reject["reading the circle failed"] = \
                    column_reject.get("reading the circle failed", 0) + 1
                job.warn(f"Circular column on layer '{layer}' skipped: {ex}")
            continue

        raw = _entity_points(entity, etype, flat_tol=raw_flat_tol)
        if len(raw) < 2:
            skipped["empty"] += 1
            continue

        pts = [(p[0] * scale, p[1] * scale) for p in raw]

        is_closed = False
        if etype in ("LWPOLYLINE", "POLYLINE"):
            is_closed = bool(safe_get(entity, "closed", False)) or dist(pts[0], pts[-1]) < 0.05
        elif etype in ("CIRCLE", "ELLIPSE"):
            is_closed = True
        elif etype == "SPLINE":
            is_closed = dist(pts[0], pts[-1]) < 0.05

        # --- حدود / دروب: مضلعات مقفولة أو أضلاع مفتوحة تتخيّط بعدين ---
        if role in ("slab", "drop"):
            target_polys = slab_polys if role == "slab" else drop_polys
            target_edges = slab_edges if role == "slab" else drop_edges
            if is_closed:
                poly = clean_polygon(pts)
                if len(poly) >= 3 and polygon_area(poly) > 0.01:
                    target_polys.append(poly)
                else:
                    skipped["tiny"] += 1
            else:
                for i in range(len(pts) - 1):
                    if dist(pts[i], pts[i + 1]) > 1e-6:
                        target_edges.append((pts[i], pts[i + 1]))
            continue

        # --- فتحات: لازم تكون مقفولة ---
        if role == "pour_strip":
            poly = clean_polygon(pts)
            if poly and len(poly) >= 3 and abs(polygon_area(poly)) > 1e-6:
                pour_strips.append(poly)
            continue

        if role in ("guide_x", "guide_y"):
            # A guide is a route, not a shape: keep its vertices in order and
            # never close it. Splines and arcs arrive here already flattened.
            run = [pts[0]]
            for q in pts[1:]:
                if dist(run[-1], q) > 1e-6:
                    run.append(q)
            if len(run) >= 2 and sum(dist(a, b) for a, b in zip(run, run[1:])) > 0.5:
                (guides_x if role == "guide_x" else guides_y).append(run)
            continue

        if role == "opening":
            poly = clean_polygon(pts)
            if len(poly) >= 3 and polygon_area(poly) > 0.005:
                openings.append(poly)
            else:
                # فتحة مرسومة بخطوط مفتوحة — بتتخيّط مع بعضها بعدين
                for i in range(len(pts) - 1):
                    if dist(pts[i], pts[i + 1]) > 1e-6:
                        opening_edges.append((pts[i], pts[i + 1]))
            continue

        # --- ليّر مختلط: نجمع الأشكال ونصنّفها بعد ما نقرا كل التسميات ---
        if role == "auto":
            if is_closed or len(pts) >= 4:
                mixed_shapes.append(pts)
            continue

        # --- أعمدة: أي شكل مقفول مرشّح، والخطوط المفتوحة تتخيّط بعدين ---
        if role == "column":
            if is_closed or len(pts) >= 4:
                column_shapes.append(pts)
            else:
                for i in range(len(pts) - 1):
                    if dist(pts[i], pts[i + 1]) > 1e-6:
                        column_edges.append((pts[i], pts[i + 1]))
            continue

        # --- حوائط وكمرات وحوائط معمارية ---
        if role in ("wall", "beam", "arch_wall"):
            #  [F17] الدور arch_wall كان معرّف في القوائم بس محدش كان
            #  بيجمّعه، فليّر الحوائط المعمارية كان بيتقري وبيتحسب وبيقع
            #  من الحلقة من غير ما حد ياخد باله - ولا حِمل واحد كان بيتكتب.
            if role == "arch_wall":
                target = arch_face_edges
            else:
                target = walls if role == "wall" else beams
            quad = clean_polygon(pts)
            if len(quad) == 4:
                res = centerline_of_quad(quad)
                if res:
                    c1, c2, thk = res
                    if role == "arch_wall" and not (
                            ARCH_WALL_MIN_MM <= thk <= ARCH_WALL_MAX_MM):
                        #  مش حائط: مضلع تاني على نفس الليّر. وشوشه
                        #  بتروح للمزاوجة زي أي خط.
                        for i in range(len(pts) - 1):
                            if dist(pts[i], pts[i + 1]) > 0.05:
                                arch_face_edges.append({"p1": pts[i],
                                                        "p2": pts[i + 1]})
                        continue
                    if dist(c1, c2) > 0.05:
                        if role == "arch_wall":
                            arch_walls.append({"p1": c1, "p2": c2,
                                               "width": thk})
                        else:
                            target.append({"p1": c1, "p2": c2,
                                           "width": max(thk, 100.0)})
                    continue
            if role == "arch_wall":
                #  الوشوش بتتجمّع هنا وبتتزاوج بعد ما نخلص قراية كل
                #  الليّر - مينفعش نقرر على خط لوحده.
                for i in range(len(pts) - 1):
                    if dist(pts[i], pts[i + 1]) > 0.05:
                        arch_face_edges.append({"p1": pts[i], "p2": pts[i + 1]})
                continue
            thk = thickness_from_layer_name(layer, default=300.0)
            for i in range(len(pts) - 1):
                if dist(pts[i], pts[i + 1]) > 0.05:
                    target.append({"p1": pts[i], "p2": pts[i + 1], "width": thk})
            continue

    job.check()
    job.step(0.30, "Stitching open boundaries")

    for chain in stitch_edges(slab_edges, tolerance=0.05):
        slab_polys.append(chain)
    for chain in stitch_edges(drop_edges, tolerance=0.05):
        drop_polys.append(chain)
    for chain in stitch_edges(opening_edges, tolerance=0.05):
        openings.append(chain)

    # الأعمدة المرسومة بأربع خطوط منفصلة — بنخيّطها لمضلع مقفول
    stitched_cols = stitch_edges(column_edges, tolerance=0.08)
    if stitched_cols:
        job.info(f"{len(stitched_cols)} columns assembled from separate lines.")
        column_shapes.extend(stitched_cols)

    # ---------- تصنيف الليّر المختلط ----------
    if mixed_shapes:
        job.step(0.33, "Classifying the mixed layer")
        tally = {"column": 0, "wall": 0, "slab": 0, "skip": 0}
        labelled = 0

        for shape in mixed_shapes:
            job.check()
            poly_clean = clean_polygon(shape)
            cen = polygon_centroid(poly_clean)

            # التسمية لازم تخص الشكل ده فعلًا: إما نقطة إدراجها جوه المضلع،
            # وإلا قريبة من مركزه بمقدار أصغر من نص أقصر ضلع فيه.
            # "nearest" لوحدها مش كفاية — كانت بتلزق تسمية بلاطة على عمود
            # على بعد متر، فالعمود يتحوّل لبلاطة ويختفي من الموديل.
            rect0 = min_area_rect(poly_clean)
            near_tol = max(min((rect0["short"] if rect0 else 0.3) * 0.5, 1.0), 0.15)

            label, best_d = None, 1e9
            for (lp, txt) in mixed_labels:
                if point_in_polygon(lp[0], lp[1], shape):
                    label, best_d = txt, 0.0
                    break
                d = dist(lp, cen)
                if d < best_d:
                    label, best_d = txt, d
            if best_d > near_tol:
                label = None
            if label:
                labelled += 1

            kind, info = classify_mixed_shape(shape, label)
            if kind == "column":
                rect = info.get("rect") or min_area_rect(clean_polygon(shape))
                columns.append({
                    "center": rect["center"] if rect else cen,
                    "b": round_to(info.get("b", 400.0), 50.0),
                    "d": round_to(info.get("d", 400.0), 50.0),
                    "angle_deg": rect["angle_deg"] if rect else 0.0,
                    "circular": False,
                })
                tally["column"] += 1
            elif kind == "wall":
                rect = info.get("rect") or min_area_rect(clean_polygon(shape))
                if rect:
                    p1, p2 = rect_centerline(rect)
                    walls.append({"p1": p1, "p2": p2,
                                  "width": max(info.get("width",
                                                        info.get("d", 250.0)), 100.0)})
                    tally["wall"] += 1
                else:
                    tally["skip"] += 1
            elif kind == "slab":
                poly = clean_polygon(shape)
                if len(poly) >= 3 and polygon_area(poly) > 0.05:
                    slab_polys.append(poly)
                    tally["slab"] += 1
                else:
                    tally["skip"] += 1
            else:
                tally["skip"] += 1

        job.ok(f"Mixed layer: {tally['column']} columns · {tally['wall']} walls · "
               f"{tally['slab']} slabs · {tally['skip']} skipped "
               f"({labelled} of {len(mixed_shapes)} shapes had a label).")
        if not tally["column"] and not tally["wall"] and tally["slab"]:
            # Every shape came out a slab. On a RAM mesh-input export that
            # never happens by itself: the columns are 300 x 600 rectangles
            # with the section written beside them. It happens when the
            # drawing is being read at the wrong SCALE - a 300 mm column read
            # as 300 m is bigger than any column can be, so the shape test
            # calls it a slab, and the model ends up with no supports at all.
            job.warn(
                f"Mixed layer: not one column and not one wall out of "
                f"{len(mixed_shapes)} shapes - every one measured too big to "
                f"be a section. That is almost always the unit: check the "
                f"unit setting against the file (a millimetre drawing read as "
                f"metres does exactly this).")

    for shape in column_shapes:
        col, reason = column_from_points(shape)
        if col:
            columns.append(col)
        else:
            column_reject[reason] = column_reject.get(reason, 0) + 1

    before = len(columns)
    columns = dedupe_columns(columns, tol=0.25)
    if before != len(columns):
        job.info(f"{before - len(columns)} duplicate columns merged "
                 f"(outline + hatch, or drawn twice).")

    slab_polys = [drop_collinear(p) for p in merge_close_vertices(slab_polys, 0.03)]
    drop_polys = [drop_collinear(p) for p in merge_close_vertices(drop_polys, 0.03)]
    openings = [drop_collinear(p) for p in merge_close_vertices(openings, 0.03)]

    slab_polys = [p for p in slab_polys if polygon_area(p) > 0.05]
    drop_polys = [p for p in drop_polys if polygon_area(p) > 0.05]

    job.step(0.38, "Classifying slab areas")

    # تصنيف البلاطات: لو فيه ليّر دروب صريح نحترمه، ومنعملش تخمين بالمساحة
    slabs = []
    ranked = sorted(({"points": p, "area": polygon_area(p)} for p in slab_polys),
                    key=lambda d: -d["area"])

    if drop_polys:
        for s in ranked:
            slabs.append({"points": s["points"], "area": s["area"],
                          "is_drop": False, "priority": 1})
        for d in drop_polys:
            slabs.append({"points": d, "area": polygon_area(d),
                          "is_drop": True, "priority": 2})
        job.info(f"Explicit drop layer: {len(drop_polys)} drop panels - no area guessing.")
    else:
        #  18.15: مساحة أصغر مركزها **برّه** الأكبر مش دروب - دي بلاطة
        #  تانية (سقف تاني في نفس الرسمة) وبتتصمّم لوحدها.
        _bases = []
        for i, s in enumerate(ranked):
            if i == 0:
                slabs.append({"points": s["points"], "area": s["area"],
                              "is_drop": False, "priority": 1})
                _bases.append(s["points"])
            elif s["area"] > 0.5:
                cx, cy = _poly_centre(s["points"])
                if any(point_in_polygon(cx, cy, b) for b in _bases):
                    slabs.append({"points": s["points"], "area": s["area"],
                                  "is_drop": True, "priority": 2})
                else:
                    slabs.append({"points": s["points"], "area": s["area"],
                                  "is_drop": False, "priority": 1})
                    _bases.append(s["points"])
        if len(ranked) > 1:
            job.warn("No explicit drop layer - smaller slabs inside a larger one were "
                     "guessed to be drop panels; a slab standing on its own is a "
                     "separate piece. Use an explicit drop layer to be sure.")

    boundary = ranked[0]["points"] if ranked else None
    drops = [s["points"] for s in slabs if s["is_drop"]]

    #  الحوائط المعمارية: مزاوجة الوشوش دلوقتي، بعد ما اتقري الليّر كله.
    if arch_face_edges:
        runs = merge_collinear_runs(arch_face_edges)
        paired_walls, n_pairs, n_single = pair_wall_faces(runs)

        #  [F19] الخط اللي ملقاش وش مقابل كان بياخد 120 مم ثابتة، فحائطين
        #  شكلهم واحد في اللوحة كانوا بيطلعوا بحملين مختلفين. الأصح إن
        #  الخط المجهول ياخد سمك **أغلب الحوائط اللي اتقاست فعلاً** في
        #  نفس اللوحة - ده أقرب تخمين ممكن، ومبني على اللوحة نفسها مش
        #  على رقم من عندنا.
        tally = {}
        for w in paired_walls:
            if w.get("width"):
                key = round(w["width"] / 10.0) * 10.0
                tally[key] = tally.get(key, 0) + 1
        if tally:
            fallback = max(tally.items(), key=lambda kv: (kv[1], -kv[0]))[0]
            fallback_src = (f"the commonest measured thickness on this "
                            f"drawing ({fallback:.0f} mm, used by "
                            f"{tally[fallback]} walls)")
        else:
            fallback = 120.0
            fallback_src = ("120 mm - not one wall on this drawing could be "
                            "measured, so there was nothing to copy")

        for w in paired_walls:
            arch_walls.append({"p1": w["p1"], "p2": w["p2"],
                               "width": w["width"] or fallback,
                               "measured": bool(w["width"])})

        job.info(f"Architectural walls drawn as two faces: {n_pairs} pairs "
                 f"matched into centre lines"
                 + (f", {n_single} single lines taken as drawn"
                    if n_single else "") + ".")
        if n_single:
            job.warn(f"{n_single} architectural lines had no opposite face, "
                     f"so their thickness could not be measured. They were "
                     f"given {fallback_src}. If that is wrong for them, draw "
                     f"the second face or set the thickness override on the "
                     f"loads card.")
        if n_single > n_pairs:
            job.warn("More lines were unmatched than matched. If the walls "
                     "really are drawn as two faces, check the layer - a "
                     "hatch or a block reference is not read as a face.")

    if column_reject:
        total = sum(column_reject.values())
        job.warn(f"{total} shapes on the column layer were rejected:")
        for reason, n in sorted(column_reject.items(), key=lambda kv: -kv[1]):
            job.warn(f"    · {n}× {reason}")

    if column_layer_types and not columns:
        types_txt = ", ".join(f"{k}×{v}" for k, v in
                              sorted(column_layer_types.items(), key=lambda kv: -kv[1]))
        job.error(f"No columns were recognised. Entities present on the column layers: "
                  f"{types_txt}. If the type is unsupported, convert the columns to closed polylines "
                  f"or circles in AutoCAD (BOUNDARY or RECTANG).")
    elif columns:
        job.info(f"Columns: {sum(1 for c in columns if c.get('circular'))} circular and "
                 f"{sum(1 for c in columns if not c.get('circular'))} rectangular.")
    if skipped["tiny"]:
        job.warn(f"{skipped['tiny']} polygons were skipped as too small.")

    site = {
        "boundary": boundary,
        "slabs": slabs,
        "drops": drops,
        "openings": openings,
        "columns": columns,
        "walls": walls,
        "beams": beams,
        "pour_strips": pour_strips,
        "arch_walls": arch_walls,
        "guides_x": guides_x,
        "guides_y": guides_y,
        "scale": scale,
        "entity_types": seen_types,
    }

    if pour_strips:
        job.ok(f"Pour strips: {len(pour_strips)}. Tendons will stop at them; "
               f"the concrete is unchanged.")
    if guides_x or guides_y:
        job.ok(f"Guide paths: {len(guides_x)} for the X family, "
               f"{len(guides_y)} for the Y family. Tendons will follow them "
               f"instead of the X/Y sweep.")
    job.ok(f"Read complete: {len(slabs)} slabs ({len(drops)} drops) | {len(openings)} openings | "
           f"{len(columns)} columns | {len(walls)} walls | {len(beams)} beams.")
    if arch_walls:
        total_len = sum(dist(w["p1"], w["p2"]) for w in arch_walls)
        job.ok(f"Architectural walls: {len(arch_walls)} runs, {total_len:.0f} m in "
               f"total. These carry nothing - they are written as line loads.")
    job.step(0.45, "DXF read complete")
    skipped = {k: n for k, n in _DXF_SKIPPED.items() if n}
    if skipped:
        parts = []
        if skipped.get("blocks_failed"):
            parts.append(f"{skipped['blocks_failed']} block(s) could not be "
                         f"exploded")
        if skipped.get("blocks_too_deep"):
            parts.append(f"{skipped['blocks_too_deep']} block(s) nested "
                         f"deeper than 3 levels")
        if skipped.get("entities"):
            parts.append(f"{skipped['entities']} unreadable entities")
        job.warn("Skipped while reading the DXF: " + ", ".join(parts)
                 + ". Whatever they held is not in the model - explode "
                   "them in AutoCAD if they matter.")
    return site


# ==============================================================================
#  القسم 3 — محرك تصميم الكابلات
#
#  المبدأ: كل كابل بيتقسم لبحور بين النقط العالية (فوق الأعمدة/الحوائط/الكمرات).
#  لكل بحر بنحسب القوة اللازمة لموازنة نسبة من الحمل:
#
#        w_bal · s · L²
#   P = ───────────────       ثم   n = ceil(P / Pe_per_strand)
#          8 · a
#
#   w_bal : الحمل المطلوب موازنته (kN/m²)
#   s     : المسافة بين الكابلات / العرض الرافد (m)
#   L     : البحر (m)
#   a     : الـ drape المتاح (m)  =  h − CGS_علوي − CGS_سفلي
#   Pe    : قوة الاستراند الفعّالة بعد الفواقد (kN)
#
#  بعد كده — لو المستخدم فعّل الخيار — بنراجع متوسط إجهاد الضغط P/A لكل اتجاه
#  ونزوّد عدد الاستراندات بالتساوي لحد ما نوصل للحد الأدنى.
# ==============================================================================

def parse_strand_list(text):
    """
    "3,5" -> [3, 5]. أي فاصل بيتقبل. فاضي أو غلط = [] يعني مفيش قيد.
    """
    out = []
    for tok in re.split(r"[^0-9]+", str(text or "")):
        if not tok:
            continue
        try:
            n = int(tok)
        except Exception:
            continue
        if 1 <= n <= 60:
            out.append(n)
    return sorted(set(out))


def _allowed_up(n, allowed):
    """أصغر مقاس متاح مش أقل من n، أو None لو n أكبر من كلهم."""
    return next((a for a in allowed if a >= n), None)


def _tendon_line(t):
    """(الاتجاه, الإحداثي العرضي, البداية, النهاية) لكابل مستقيم."""
    pr = t.get("profile") or []
    if len(pr) < 2:
        return None
    ax = pr[-1]["pos"][0] - pr[0]["pos"][0]
    ay = pr[-1]["pos"][1] - pr[0]["pos"][1]
    n = math.hypot(ax, ay)
    if n < 1e-9:
        return None
    ux, uy = ax / n, ay / n
    if (ux < -1e-9) or (abs(ux) <= 1e-9 and uy < 0):
        ux, uy = -ux, -uy
    across = [-q["pos"][0] * uy + q["pos"][1] * ux for q in pr]
    along = [q["pos"][0] * ux + q["pos"][1] * uy for q in pr]
    return ((ux, uy), sum(across) / len(across), min(along), max(along))


def merge_for_strand_sizes(tendons, params, job=None):
    """
    **جمع كابلين متجاورين في واحد بدل ما كل واحد يتقرّب لفوق** (18.80).

    قاعدة المهندس: «الزيادة اللي من التقريب دي غلط - اجمع الكابلات
    القريبة من بعضها في كابل واحد وقلّل الزيادة، مع الحفاظ على
    القواعد».

    وهو محق، والرقم من رنّه: تخطيط جه بـ **311 استرند**، والتقريب
    للمقاسات [2, 3, 5] طلّعه **361** - زيادة 50 استرند (16%) من
    التقريب لوحده، 50 كابل كل واحد اتقرّب درجة.

    السبب إن التقريب بيشتغل على كل كابل **لوحده**. كابل محتاج 4 على
    قايمة [2,3,5] بياخد 5 - يضيع واحد. اتنين جنب بعض محتاجين 4 و1
    بياخدوا 5+2 = 7؛ لو اتجمعوا في واحد يبقى 5 بالظبط: **استرندين
    وفّروا، ودكت ومرساة أقل**.

    الشرط إن الجمع يوفّر فعلاً:

        allowed_up(n1) + allowed_up(n2)  >  allowed_up(n1 + n2)

    والقواعد اللي مابتتكسرش:
      · `max_strands` - الكابل المجمّع مايعديهاش.
      · `max_tendon_spacing` - شيل كابل بيوسّع المسافة للي بعده،
        والكود بيحدّها (ACI 318-19 §8.7.2.3). لو الفراغ اللي هيفضل
        أوسع من الحد، الجمع مابيحصلش.
      · الكابلين لازم يكونوا متوازيين، متجاورين، وماشيين على نفس
        المدى تقريباً - جمع كابلين على بحور مختلفة بينقل القوة لمكان
        مش محتاجها.
      · كابل مهندس تاني (`as_drawn` / `from_model` / `from_adapt`)
        مابيتلمسش.

    الكابل اللي بيفضل هو **صاحب العدد الأكبر** - هو اللي أقرب لمركز
    القوة بين الاتنين، وخطه مرسوم على صف أعمدة في الغالب.

    بترجّع (كام زوج اتجمع, كام استرند اتوفّر).
    """
    allowed = sorted(int(a) for a in
                     (getattr(params, "allowed_strands", []) or []))
    if not allowed or not tendons:
        return 0, 0
    if not bool(getattr(params, "merge_for_sizes", True)):
        return 0, 0
    n_max = min(int(getattr(params, "max_strands", 5) or 5), allowed[-1])
    gap_max = float(getattr(params, "max_tendon_spacing", 0.0) or 0.0)
    min_gap = float(getattr(params, "min_clear_spacing", 0.0) or 0.0)

    rows = []
    for t in tendons:
        if t.get("_deleted") or t.get("band"):
            continue
        if not _ours(t) or t.get("from_adapt"):
            continue
        line = _tendon_line(t)
        if line is None:
            continue
        rows.append((line, t))
    if len(rows) < 2:
        return 0, 0

    #  التجميع في عائلات: نفس الاتجاه (±10°)، والترتيب بالإحداثي العرضي
    fams = []
    for (u, across, lo, hi), t in rows:
        for f in fams:
            if abs(f["u"][0] * u[0] + f["u"][1] * u[1]) > 0.985:
                f["items"].append((across, lo, hi, t))
                break
        else:
            fams.append({"u": u, "items": [(across, lo, hi, t)]})

    merged = saved = 0
    for f in fams:
        items = sorted(f["items"], key=lambda z: z[0])
        i = 0
        while i < len(items) - 1:
            a_ac, a_lo, a_hi, ta = items[i]
            b_ac, b_lo, b_hi, tb = items[i + 1]
            if ta.get("_deleted") or tb.get("_deleted"):
                i += 1
                continue
            na = int(ta.get("strands") or 0)
            nb = int(tb.get("strands") or 0)
            if na <= 0 or nb <= 0:
                i += 1
                continue
            up_a, up_b = _allowed_up(na, allowed), _allowed_up(nb, allowed)
            up_ab = _allowed_up(na + nb, allowed)
            if up_a is None or up_b is None or up_ab is None:
                i += 1
                continue
            if up_ab > n_max or up_a + up_b <= up_ab:
                i += 1
                continue
            #  نفس المدى تقريباً - 70% من الأقصر جوّه الأطول
            ov = min(a_hi, b_hi) - max(a_lo, b_lo)
            span = min(a_hi - a_lo, b_hi - b_lo)
            if span <= 0 or ov / span < 0.70:
                i += 1
                continue
            #  الفراغ اللي هيفضل بعد الشيل
            keep, drop = (ta, tb) if na >= nb else (tb, ta)
            k_ac = a_ac if keep is ta else b_ac
            others = [z[0] for z in items
                      if z[3] is not keep and z[3] is not drop
                      and not z[3].get("_deleted")]
            if gap_max > 0 and others:
                left = [o for o in others if o < k_ac]
                right = [o for o in others if o > k_ac]
                worst = 0.0
                if left:
                    worst = max(worst, k_ac - max(left))
                if right:
                    worst = max(worst, min(right) - k_ac)
                if worst > gap_max + 1e-6:
                    i += 1
                    continue
            if min_gap > 0 and abs(a_ac - b_ac) < min_gap - 1e-6:
                #  دول ملزوقين أصلاً - الجمع بيصلّح ده كمان
                pass
            keep["strands"] = up_ab
            keep.setdefault("governing", {})["merged_for_size"] = True
            drop["_deleted"] = True
            merged += 1
            saved += (up_a + up_b) - up_ab
            i += 2
        #  الكابل المشال بيخرج من القايمة
    if merged and job:
        job.ok(f"{merged} pair(s) of neighbouring tendons were made into one "
               f"carrying both their strands, which saves {saved} strand(s) "
               f"the rounding would otherwise have added - and {merged} duct(s) "
               f"and {merged} pair(s) of anchorages with them. Rounding works "
               f"on one tendon at a time: on a list of {allowed}, a tendon "
               f"needing 4 costs 5 and one needing 1 costs 2, where the two "
               f"together cost 5. Nothing here crosses the maximum strand "
               f"count, the code's maximum tendon spacing, or the minimum "
               f"clear spacing.")
    tendons[:] = [t for t in tendons if not t.get("_deleted")]
    return merged, saved


def apply_allowed_strands(tendons, params, job):
    """
    يقصر عدد الاسترندات على المقاسات المتاحة فعلاً في الموقع.

    التقريب **لفوق دايمًا**: كابل محتاج 4 والمتاح 3 و5 بياخد 5. التقريب
    لتحت كان هيسيبه أقل من القوة اللي اتصمّم لها، وده تصميم غلط مش
    تبسيط. اللي محتاج أكتر من أكبر مقاس بيقف عند أكبر مقاس وبيتقال.

    بترجّع (raised, capped).
    """
    allowed = list(getattr(params, "allowed_strands", []) or [])
    if not allowed or not tendons:
        return 0, 0
    top = allowed[-1]
    raised = capped = 0
    kept = 0
    wanted = []
    for t in tendons:
        #  الكابل الجاي من ملف أدابت بياخد عدده من الملف. تقريبه لأقرب
        #  مقاس متاح بيخلي الموديلين مختلفين، وده عكس الهدف.
        if t.get("from_adapt"):
            kept += 1
            continue
        try:
            n = int(t.get("strands") or 0)
        except Exception:
            continue
        wanted.append(n)
        if n in allowed:
            continue
        up = next((a for a in allowed if a >= n), None)
        if up is None:
            t["strands"] = top
            t.setdefault("governing", {})["size_capped"] = True
            capped += 1
        else:
            t["strands"] = up
            raised += 1
    if kept and job:
        job.info(f"{kept} tendons keep the strand count read from the ADAPT "
                 f"file - the available-sizes rounding is not applied to "
                 f"them.")
    if raised:
        job.info(f"Strand sizes are restricted to {allowed}: {raised} tendons "
                 f"were rounded UP to the next size on the list. Rounding up "
                 f"never leaves a tendon short of the force it was designed "
                 f"for.")
        #  **18.80: وأي مقاس ناقص من القايمة هو اللي بيدفع الفرق؟**
        #  الهدر ده مش قدر - هو حاصل ضرب قايمة المقاسات في توزيع
        #  الأعداد. رن المهندس: تخطيط بـ 311 استرند طلع 361، والجمع
        #  مايقدرش يوفّر لما الجارين الاتنين كبار (4+4 = 8 وأقصى
        #  مقاس 5). اللي بيوفّرها مقاس واحد ناقص من القايمة - والرقم
        #  ده بيقوله بالظبط بدل ما المهندس يخمّن.
        try:
            want = [int(_w) for _w in wanted if _w > 0]
            lost = sum(_allowed_up(w, allowed) - w for w in want
                       if _allowed_up(w, allowed) is not None)
            if lost > 0:
                best, gain = None, 0
                for cand in range(1, int(allowed[-1]) + 1):
                    if cand in allowed:
                        continue
                    al = sorted(set(allowed + [cand]))
                    now = sum((_allowed_up(w, al) or w) - w for w in want)
                    if lost - now > gain:
                        best, gain = cand, lost - now
                job.info(f"    that rounding costs {lost} strand(s) on this "
                         f"floor.")
                if best is not None and gain > 0:
                    job.info(f"    {gain} of them would go if {best} were on "
                             f"the list of available sizes - the waste is "
                             f"not the rounding, it is the hole in the list "
                             f"at {best}. Joining neighbouring tendons "
                             f"cannot close it where both of them are "
                             f"already near the maximum: two tendons "
                             f"needing 4 each cannot become one carrying 8.")
        except Exception:
            pass
    if capped:
        job.warn(f"{capped} tendons need more than {top} strands - the "
                 f"largest size on your list - and were held there. Either "
                 f"add a larger size or bring the tendons closer together.")
    return raised, capped


class TendonDesignParams:
    """Every design input in one place, fully validated before a run."""

    def __init__(self, **kw):
        # الهندسة
        self.slab_thickness = float(kw.get("slab_thickness", 260.0))    # mm
        self.drop_thickness = float(kw.get("drop_thickness", 400.0))
        #  **18.26: السُمك اللي في الموديل هو السُمك، والسلام.** الفحص كان
        #  بيقول "the model governs" وبيسيب الإعداد مكانه، فالخرسانة
        #  بتتبني على 200 والوزن الذاتي والحمل الموازن والـ drape
        #  بيتحسبوا على 240. القوة بتطلع لقطاع مش موجود. لما يكون في
        #  الموديل سُمك، بيتكتب هنا قبل ما أي رقم يتحسب.
        self.thickness_from_model = bool(kw.get("thickness_from_model", True))
        #  17.54: منطقة أتخن طويلة وعليها ركايز = كمرة عريضة (band beam)
        self.band_beams = bool(kw.get("band_beams", True))
        self.band_beam_ratio = float(kw.get("band_beam_ratio", 3.0))
        self.band_beam_supports = int(kw.get("band_beam_supports", 2))
        self.band_beam_min_length = float(kw.get("band_beam_min_length", 8.0))
        #  17.57: الكابل الماشي جوّه كمرة عريضة
        self.band_run_profile = bool(kw.get("band_run_profile", True))
        self.band_run_share = float(kw.get("band_run_share", 0.5))
        #  17.59: عدد كابلات الكمرة العريضة من مومنتها وعمقها
        self.band_tendon_count = bool(kw.get("band_tendon_count", True))
        self.band_tendon_spacing = float(kw.get("band_tendon_spacing", 0.30))
        self.band_tendon_edge = float(kw.get("band_tendon_edge", 0.10))
        self.band_moment_face = float(kw.get("band_moment_face", 0.50))
        # --- النقطة السفلية جوه الدروب بانل الطويل ---
        # الدروب القصير قطعة فوق عمود، الكابل بيعدّي فوقه مفرود وده صح.
        # الدروب الطويل بحر بذاته ولازم الكابل ينزل فيه، وإلا مابيوازنش
        # حِمل هناك. الارتفاع بيتقاس من بطن الدروب لأن الدروب هو اللي
        # تحت الكابل مش البلاطة.
        self.drop_sag_min_length = float(kw.get("drop_sag_min_length", 6.0))
        self.drop_sag_min_span = float(kw.get("drop_sag_min_span", 5.0))
        self.drop_sag_from_soffit = float(kw.get("drop_sag_from_soffit", 75.0))
        #  البلاطة المعصّبة: التعرّف عليها بيغيّر التوزيع والبروفايل.
        self.ribbed_enabled = bool(kw.get("ribbed_enabled", True))    # mm
        self.beam_depth = float(kw.get("beam_depth", 500.0))            # mm
        self.column_height = float(kw.get("column_height", 3000.0))     # mm
        self.wall_height = float(kw.get("wall_height", 3000.0))         # mm
        # --- الحوائط المعمارية: حِمل خطي مش ركيزة ---
        # الكثافة بالـ kN/m³ للمبنى كامل (طوب + بياض): الطوب الأحمر حوالي 18،
        # والبلوك المفرّغ 12-14. الارتفاع ارتفاع الدور، والصافي بيتحسب بطرح
        # سمك البلاطة. ومعامل الفتحات بيخصم الأبواب والشبابيك.
        self.arch_wall_density = float(kw.get("arch_wall_density", 14.0))
        self.arch_wall_height = float(kw.get("arch_wall_height", 3.0))   # m
        self.arch_wall_opening_factor = float(
            kw.get("arch_wall_opening_factor", 0.85))
        # 0 = استعمل السمك المرسوم لكل حائط
        self.arch_wall_thickness = float(kw.get("arch_wall_thickness", 0.0))
        # إيه اللي يتكتب في الموديل
        self.write_area_loads = bool(kw.get("write_area_loads", False))
        self.write_wall_loads = bool(kw.get("write_wall_loads", False))
        #  18.108: حمل خطي على حدود البلاطة الخارجية (kN/m)
        self.write_edge_load = bool(kw.get("write_edge_load", False))
        self.edge_line_load = float(kw.get("edge_line_load", 0.0) or 0.0)
        # --- شرائح التصميم (Support Lines) ---
        # مقفولة افتراضيًا: الشرائح بتحكم التصميم كله في RAM، ورسمها
        # أوتوماتيك على بلاطة شبكتها مش منتظمة بيدي نتيجة تبان صح وهي غلط.
        # تتفتح عن قصد وتتراجع في RAM قبل الحساب.
        self.write_design_strips = bool(kw.get("write_design_strips", True))
        #  18.123: الأسعار والتكلفة
        self.cost_report = bool(kw.get("cost_report", True))
        self.cost_currency = str(kw.get("cost_currency", "SAR") or "SAR")
        self.price_strand_kg = float(kw.get("price_strand_kg", 12.0) or 0.0)
        self.price_duct_small_m = float(kw.get("price_duct_small_m", 8.0) or 0.0)
        self.price_duct_large_m = float(kw.get("price_duct_large_m", 12.0) or 0.0)
        self.duct_small_max_strands = int(kw.get("duct_small_max_strands", 3) or 3)
        self.price_anchor_s2 = float(kw.get("price_anchor_s2", 60.0) or 0.0)
        self.price_anchor_s3 = float(kw.get("price_anchor_s3", 75.0) or 0.0)
        self.price_anchor_s4 = float(kw.get("price_anchor_s4", 90.0) or 0.0)
        self.price_anchor_s5 = float(kw.get("price_anchor_s5", 110.0) or 0.0)
        self.price_concrete_m3 = float(kw.get("price_concrete_m3", 450.0) or 0.0)
        self.price_rebar_kg = float(kw.get("price_rebar_kg", 4.5) or 0.0)
        self.rebar_kg_m2 = float(kw.get("rebar_kg_m2", 12.0) or 12.0)
        #  18.121: فحص الثقب بعد رسم الكابلات
        self.punch_check = bool(kw.get("punch_check", True))
        self.punch_code = str(kw.get("punch_code", list(PUNCH_CODES)[0]) or list(PUNCH_CODES)[0])
        self.punch_fc = float(kw.get("punch_fc", 30.0) or 30.0)
        self.punch_cover = float(kw.get("punch_cover", 30.0) or 30.0)
        self.strip_replace_existing = bool(kw.get("strip_replace_existing", False))
        #  17.9: فحص الشرايح اللي رام ولّدها، وقفل الفجوات بالقياس
        self.strip_check = bool(kw.get("strip_check", True))
        #  **18.27: الشاشة مقفولة افتراضياً.** الفحص بيفضل شغّال وكل
        #  اللي بيلاقيه بيتكتب في اللوج بالمساحات والإحداثيات - اللي
        #  اتغيّر هو إن الرن مابيقفش يستنى حد يقفل شاشة. المهندس بيشغّل
        #  الرن الكامل من الـ DXF للتقشير في ضغطة واحدة، وشاشة في
        #  النص بتلغي المعنى.
        self.strip_check_show = bool(kw.get("strip_check_show", False))
        #  **18.26: شغّال افتراضيًا.** الفحص كان بيقيس الفجوات ويكتبها
        #  ويسيبها: على الرن ده 91 م² في X و142 م² في Y من غير أي
        #  شريحة، ومنهم قطعة 53.2 × 8.9 م. القطاع اللي مالهوش شريحة
        #  مافيهوش فحص إجهاد ولا P/A - يعني الخرسانة دي مش متصمّمة، مش
        #  "متصمّمة بتحذير". الآلية اللي بتقفلها (`close_strip_gaps`)
        #  كانت موجودة وكاملة ومتوقّفة على الخيار ده وبس.
        self.strip_close_gaps = bool(kw.get("strip_close_gaps", True))
        self.strip_gap_min_area = float(kw.get("strip_gap_min_area", 5.0))
        self.strip_gap_min_length = float(kw.get("strip_gap_min_length", 2.0))
        self.strip_gap_line_spacing = float(
            kw.get("strip_gap_line_spacing", 6.0))
        self.strip_gap_min_clear = float(kw.get("strip_gap_min_clear", 2.0))
