        # read off its peak.
        self.reinforce_basis = kw.get("reinforce_basis", "both")
        self.hog_average_width = float(kw.get("hog_average_width", 4.0))
        # If an added tendon stops this close to a slab edge or an opening,
        # run it out to meet it rather than leaving an unstressed sliver.
        self.snap_to_edge = float(kw.get("snap_to_edge", 1.0))           # m
        # Clearance past the far face of a drop panel when an added tendon
        # would otherwise end inside one.
        self.drop_end_margin = float(kw.get("drop_end_margin", 0.5))     # m
        # Moment below which a contour region is treated as ripple, not as a
        # real support or midspan.
        self.min_region_moment = float(kw.get("min_region_moment", 8.0))
        # Moment above which a drop panel or wall will NOT lift the tendon.
