        self.split_max_length = float(kw.get("split_max_length", 60.0))
        self.lap_length = float(kw.get("lap_length", 2.0))  # kNm/m
        # Let the high point sink as the tendon moves away from the column.
        # This was removed once because it also drove span detection and left
