#  قياس دور - نفس الأرقام اللي بنحكم بيها، من غير رام (17.31)
# ---------------------------------------------------------------------------


def _sharpest_bend(t):
    """أحدّ لفّة في بروفايل الكابل ده بالمتر، أو None."""
    pr = t.get("profile") or []
    s, best = [0.0], None
    for a, b in zip(pr, pr[1:]):
        s.append(s[-1] + dist(a.get("pos") or (0, 0), b.get("pos") or (0, 0)))
    key = [k for k, q in enumerate(pr)
           if k == 0 or k == len(pr) - 1 or q.get("high") or q.get("sag")]
    for j in range(1, len(key) - 1):
        i1, i2, i3 = key[j - 1], key[j], key[j + 1]
        h1, h2 = s[i2] - s[i1], s[i3] - s[i2]
        if h1 <= 0.01 or h2 <= 0.01:
            continue
        d1 = float(pr[i1].get("depth") or 0.0) / 1000.0
        d2 = float(pr[i2].get("depth") or 0.0) / 1000.0
        d3 = float(pr[i3].get("depth") or 0.0) / 1000.0
        ypp = 2.0 * ((d3 - d2) / h2 - (d2 - d1) / h1) / (h1 + h2)
        if abs(ypp) > 1e-12:
            r = 1.0 / abs(ypp)
            best = r if best is None else min(best, r)
    return best


def _span_offsets(site, lines, params, direction, span_set):
    """بُعد كل بحر عن اتجاه الكابلات اللي فوقه، بالدرجات."""
    fam, _u, guides = gap_family_direction(site, params, span_set)
    out = []
    for L in lines or []:
        if L.get("dir") != direction:
            continue
        for sp in L.get("spans") or []:
            a, b = sp.get("p1"), sp.get("p2")
            if not a or not b:
                continue
            own = math.degrees(math.atan2(b[1] - a[1], b[0] - a[0]))
            loc = (guide_angle_for_span(a, b, guides, fam, 2.0)
                   if guides else fam)
            d = loc - own
            while d > 90.0:
                d -= 180.0
            while d <= -90.0:
                d += 180.0
            out.append(abs(d))
    return out


def measure_design(site=None, tendons=None, lines=None, strip_report=None,
                   params=None):
    """
    **الأرقام اللي بنحكم بيها على دور (17.31).** بتاخد اللي اتقرا وبترجّع
    القياسات - مفيش قراءة ملفات هنا ولا رام، عشان تتقاس لوحدها.
    """
    p = params
    out = {"when": datetime.datetime.now().isoformat(timespec="seconds"),
           "version": APP_VERSION}
    try:
        area = slab_area_m2(site or {}) if site else 0.0
    except Exception:
        area = 0.0
    out["slab_m2"] = round(area or 0.0, 1)

    ts = list(tendons or [])
    kgm = 0.0
    try:
        kgm = strand_kg_per_m(p) if p is not None else 0.0
    except Exception:
        kgm = 0.0
    strands = sum(int(t.get("strands") or 0) for t in ts)
    kg = 0.0
    for t in ts:
        try:
            kg += (int(t.get("strands") or 0) * tendon_plan_length(t) * kgm)
        except Exception:
            continue
    bends = [r for r in (_sharpest_bend(t) for t in ts) if r]
    out["tendons"] = {
        "count": len(ts), "strands": strands, "kg": round(kg, 1),
        "kg_m2": round(kg / area, 2) if area else None,
        "sharpest_bend_m": round(min(bends), 2) if bends else None}

    dirs = {}
    for ss, info in ((strip_report or {}).get("dirs") or {}).items():
        dirs[ss] = {
            "coverage": round(float(info.get("coverage") or 0.0), 1),
            "strips": int(info.get("strips") or 0),
            "overlap_pairs": len(info.get("overlaps") or []),
            "overlap_m2": round(sum(float(d.get("area") or 0.0)
                                    for d in info.get("overlaps") or []), 2),
            "uncovered_m2": round(float(info.get("gap_area") or 0.0), 1)}
    out["strips"] = dirs

    if site and lines is not None:
        sup, dirn = {}, {}
        for d, ss in (("X", "latitude"), ("Y", "longitude")):
            try:
                allp, missed, _s = supports_without_a_line(lines, site, p, d)
                sup[d] = {"total": len(allp), "missed": len(missed)}
            except Exception:
                pass
            offs = _span_offsets(site, lines, p, d, ss)
            if offs:
                offs_sorted = sorted(offs)
                lim = float(getattr(p, "strip_search_angle", 25.0) or 25.0)
                dirn[d] = {
                    "spans": len(offs),
                    "mean_off_deg": round(sum(offs) / len(offs), 1),
                    "median_off_deg": round(offs_sorted[len(offs) // 2], 1),
                    "worst_off_deg": round(offs_sorted[-1], 1),
                    "past_the_allowance": sum(1 for o in offs if o > lim)}
        if sup:
            out["supports"] = sup
        if dirn:
            out["direction"] = dirn
    return out


def measure_model(cpt_path, params, job=None, site=None):
    """
    **قِس الموديل ده (17.31).** بيقرا الموديل المحفوظ من الملف نفسه -
    من غير ما رام يفتح - ويطلّع نفس أرقام القياس.

    `site` اختياري: لو جه من الـ DXF بتاعه بمساراته، القياس بيشمل بُعد
    البحور عن اتجاه الكابلات كمان.
    """
    site_m = site
    if site_m is None:
        try:
            site_m = site_from_cpt(cpt_path, job)
        except Exception:
            site_m = {}
    for k in ("slabs", "openings", "boundary", "columns", "walls"):
        site_m.setdefault(k, [])
    try:
        tendons = tendons_from_cpt(cpt_path, params, job)
    except Exception:
        tendons = []
    lines = []
    try:
        segs = read_strips_from_cpt(cpt_path, job)["segments"]
        for ss, rows in segs.items():
            d = DIR_OF_SPAN_SET.get(ss, "X")
            for p1, p2, _n, _u in rows:
                lines.append({"dir": d, "spans": [{"p1": p1, "p2": p2}]})
    except Exception:
        pass
    rep = None
    try:
        rep = check_design_strips(cpt_path, site_m, params, job)
    except Exception:
        rep = None
    out = measure_design(site_m, tendons, lines, rep, params)
    out["model"] = os.path.basename(cpt_path)
    return out


def format_measurements(m, job=None):
    """القياس في صورة سطور تتقرا."""
    t = m.get("tendons") or {}
    lines = [f"{m.get('model', 'this model')}: {m.get('slab_m2', 0):,.0f} m2 "
             f"of slab, {t.get('count', 0)} tendon(s), "
             f"{t.get('strands', 0)} strand(s), {t.get('kg', 0):,.0f} kg"
             + (f" = {t['kg_m2']:.2f} kg/m2" if t.get("kg_m2") else "")
             + (f", sharpest bend {t['sharpest_bend_m']:.2f} m"
                if t.get("sharpest_bend_m") else "")]
    for ss, s in (m.get("strips") or {}).items():
        lines.append(f"    {ss}: {s['strips']} strip(s), {s['coverage']:.1f}% "
                     f"of the slab, {s['overlap_pairs']} overlapping pair(s) "
                     f"({s['overlap_m2']:.1f} m2), {s['uncovered_m2']:,.0f} m2 "
                     f"with no strip")
    for d, s in (m.get("supports") or {}).items():
        lines.append(f"    {_dir_name(d.lower())}: {s['missed']} of "
                     f"{s['total']} support(s) have no line over them")
    for d, s in (m.get("direction") or {}).items():
        lines.append(f"    {_dir_name(d.lower())}: {s['spans']} span(s) sit "
                     f"{s['mean_off_deg']:.1f} deg off the tendons on average, "
                     f"worst {s['worst_off_deg']:.1f} deg, "
                     f"{s['past_the_allowance']} past the allowance")
    if job:
        job.log("Measured", "head")
        for ln in lines:
            job.info(ln)
    return lines


def save_measurements(m, folder, stem, job=None):
    """بيحفظ القياس جنب الموديل عشان أي تحسين جاي يتقارن برقم محفوظ."""
    try:
        path = os.path.join(folder, f"{stem}_AutoPT_measured.json")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(m, fh, indent=1)
        if job:
            job.ok(f"The measurements are saved as {os.path.basename(path)} - "
                   f"the next change can be compared against this file "
                   f"instead of against memory.")
        return path
    except Exception as e:
        if job:
            job.info(f"    the measurements were not saved ({e}).")
        return None



