#  الموديل مقابل الإعدادات - قبل ما الرن يبدأ (17.32)
# ---------------------------------------------------------------------------


def cpt_inflection_ratio(cpt_path):
    """
    نسبة نقطة الانقلاب اللي رام بيدّيها للكابلات (18.09)، من الملف نفسه:
    أكتر قيمة متكررة في جدول Tendon، وإلا DefaultTendon. None لو ماتقرتش.
    """
    if not cpt_path or not os.path.isfile(cpt_path):
        return None
    import sqlite3
    try:
        db = sqlite3.connect("file:" + cpt_path + "?mode=ro", uri=True)
    except Exception:
        return None
    try:
        for tab in ("Tendon", "DefaultTendon"):
            try:
                rows = db.execute(f"select InflectionRatio from '{tab}'").fetchall()
            except Exception:
                continue
            vals = [float(r[0]) for r in rows if r and r[0] is not None and 0.0 < float(r[0]) < 1.0]
            if vals:
                cnt = {}
                for v in vals:
                    k = round(v, 3)
                    cnt[k] = cnt.get(k, 0) + 1
                return max(cnt, key=lambda k: cnt[k])
    except Exception:
        return None
    finally:
        try:
            db.close()
        except Exception:
            pass
    return None


def cpt_min_curvature_radius(cpt_path):
    """
    `MinRadius` بتاعة نظام الـ PT من الملف نفسه، بالمتر - من غير رام.

    الملف SQLite والقيمة متخزنة بوحدة 1e-4 م. بترجّع (متر, اسم النظام)
    أو None.
    """
    if not cpt_path or not os.path.isfile(cpt_path):
        return None
    import sqlite3
    try:
        db = sqlite3.connect("file:" + cpt_path + "?mode=ro", uri=True)
    except Exception:
        return None
    best = None
    try:
        for (tab,) in db.execute("select name from sqlite_master "
                                 "where type='table'"):
            cols = [c[1] for c in db.execute(f"pragma table_info('{tab}')")]
            if "MinRadius" not in cols:
                continue
            name_col = "Name" if "Name" in cols else cols[0]
            for row in db.execute(f"select {name_col}, MinRadius "
                                  f"from '{tab}'"):
                try:
                    r = float(row[1]) * RAM_LEN
                except (TypeError, ValueError):
                    continue
                if r > 0 and (best is None or r > best[0]):
                    best = (round(r, 3), str(row[0]))
            break
    except Exception:
        best = None
    finally:
        try:
            db.close()
        except Exception:
            pass
    return best


def compare_model_and_settings(cpt_path, params, job=None):
    """
    **القيم اللي ليها نسخة في الموديل ونسخة في الإعدادات (17.32).**

    مشكلة نصف القطر مكانتش حالة واحدة - كانت **نوع**: البرنامج ماسك رقم
    والموديل ماسك نفس الرقم، والاتنين مختلفين، ومحدش قال. الفخ ده
    متحطوط في كل قيمة ليها توأم.

    كل مقارنة بتتقرا من الملف مباشرة - مفيش رام. بترجّع صفوف:
    {what, model, setting, unit, agrees, governs, note}.
    """
    rows = []
    if not cpt_path or not os.path.isfile(cpt_path):
        return rows

    got = cpt_min_curvature_radius(cpt_path)
    if got:
        r, name = got
        mine = float(getattr(params, "min_tendon_radius", 0.0) or 0.0)
        follow = bool(getattr(params, "radius_from_model", True))
        agrees = abs(r - mine) <= 0.005
        rows.append({
            "what": f"minimum tendon radius (PT system '{name}')",
            "model": r, "setting": mine, "unit": "m", "agrees": agrees,
            "governs": ("the larger of the two" if follow else "the setting"),
            "note": ("" if agrees else
                     ("RAM judges every tendon by its own value; the profiles "
                      "are held to the larger of the two."
                      if follow else
                      "'Take the minimum radius from the model' is off, so "
                      "RAM may still report a bend it will not accept."))})

    force, n = None, 0
    try:
        force, n = strand_force_from_model(cpt_path, None, None)
    except Exception:
        force = None
    if force:
        mine = float(getattr(params, "strand_force_kn", 0.0) or 0.0)
        agrees = mine <= 0 or abs(force - mine) <= max(0.02 * force, 1.0)
        rows.append({
            "what": f"effective force per strand (from {n} tendon(s))",
            "model": round(force, 1), "setting": (round(mine, 1) if mine
                                                  else None),
            "unit": "kN", "agrees": agrees,
            "governs": "the model" if mine <= 0 else "the setting",
            "note": ("" if agrees else
                     "The strand count is priced on the setting while the "
                     "model balances with its own force.")})

    #  **سُمك البلاطة من البلاطة، مش من عند الأعمدة (17.51).** الأعمدة
    #  واقفة جوّه الدروب: على The Bridge P02، 36 عمود من 45 جوّه دروب
    #  350 م م و85% من الخرسانة بلاطة 240. فالفحص كان بيقول البلاطة 350،
    #  وإعداد 350 الغلط "متفق"، و240 الصح "مختلف".
    slab_th = drop_th = None
    slab_share = 0.0
    try:
        site_m = site_from_cpt(cpt_path, None)
        mark_band_beams(site_m, params, None)
        by_th, drops_th = {}, {}
        for s in site_m.get("slabs") or []:
            pts = s.get("points") or []
            if len(pts) < 3:
                continue
            a = abs(polygon_area(pts))
            t = round(float(s.get("thickness") or 0.0), 0)
            if t <= 0:
                continue
            if s.get("is_band"):
                continue        # كمرة عريضة، مش بلاطة ولا دروب
            bucket = drops_th if s.get("is_drop") else by_th
            bucket[t] = bucket.get(t, 0.0) + a
        if by_th:
            slab_th = max(by_th, key=lambda k: by_th[k])
            slab_share = by_th[slab_th] / max(sum(by_th.values()), 1e-9)
        if drops_th:
            drop_th = max(drops_th, key=lambda k: drops_th[k])
    except Exception:
        slab_th = drop_th = None
    #  **18.26: "the model governs" بقى يعني إن الإعداد بيتغيّر فعلاً.**
    #  قبل كده الصف ده كان تقرير وبس: الخرسانة بتتبني بسُمك الموديل
    #  والتصميم بيفضل ماشي على الإعداد. على الرن ده الموديل 200 م م
    #  والإعداد 240، فالوزن الذاتي والحمل الموازن والـ drape (0.140 م
    #  في X) كلهم اتحسبوا على بلاطة أتخن 20% من اللي اتصبّت. دلوقتي
    #  السُمك بيتنقل للإعدادات هنا، قبل أول حساب في الرن.
    adopt = bool(getattr(params, "thickness_from_model", True))
    if slab_th:
        mine = float(getattr(params, "slab_thickness", 0.0) or 0.0)
        agrees = abs(slab_th - mine) <= 1.0
        took = False
        if adopt and not agrees:
            params.slab_thickness = float(slab_th)
            took = True
        rows.append({
            "what": "slab thickness",
            "model": slab_th, "setting": round(mine, 0),
            "unit": "mm", "agrees": agrees, "governs": "the model",
            "adopted": took,
            "note": ("" if agrees else
                     (f"{slab_share * 100:.0f}% of the slab is {slab_th:.0f} "
                      f"mm, so the setting has been replaced by it: the self "
                      f"weight, the balanced load and the drape are all "
                      f"worked out on {slab_th:.0f} mm."
                      if took else
                      f"{slab_share * 100:.0f}% of the slab is {slab_th:.0f} "
                      f"mm. 'Take the thickness from the model' is off, so "
                      f"the self weight, the balanced load and the drape are "
                      f"worked out on the setting, not on the slab."))})
    if drop_th:
        mine_d = float(getattr(params, "drop_thickness", 0.0) or 0.0)
        agrees_d = abs(drop_th - mine_d) <= 1.0
        took_d = False
        if adopt and not agrees_d:
            params.drop_thickness = float(drop_th)
            took_d = True
        rows.append({
            "what": "drop panel thickness",
            "model": drop_th, "setting": round(mine_d, 0),
            "unit": "mm", "agrees": agrees_d, "governs": "the model",
            "adopted": took_d,
            "note": ("" if agrees_d else
                     ("The columns stand in the drops, so this is the "
                      "thickness a tendon crosses over its supports - the "
                      "setting has been replaced by it."
                      if took_d else
                      "The columns stand in the drops, so this is the "
                      "thickness a tendon crosses over its supports."))})
    return rows


def report_model_vs_settings(rows, job, params=None):
    """بيقول اللي اختلف بس، والمتفق عليه بيتلخّص في سطر."""
    if not job:
        return rows
    if not rows:
        return rows
    same = [r for r in rows if r.get("agrees")]
    diff = [r for r in rows if not r.get("agrees")]
    job.log("The model against your settings", "head")
    if same:
        job.ok(f"{len(same)} value(s) agree: "
               + ", ".join(str(r["what"]).split(" (")[0] for r in same) + ".")
    for r in diff:
        m, s = r.get("model"), r.get("setting")
        job.warn(f"{r['what']}: the model says {m} {r['unit']}, the settings "
                 f"say {s} {r['unit']}. {r['governs'].capitalize()} governs. "
                 f"{r.get('note', '')}".strip())
    if not diff:
        job.info("    Nothing the model holds disagrees with the settings.")
    #  18.26: السُمك اتغيّر، يبقى كل رقم مبني عليه اتغيّر. الأرقام دي
    #  اتطبعت في أول الرن على الإعداد القديم، فلازم تتقال تاني بقيمتها
    #  الجديدة - وإلا التقرير بيقول رقمين مختلفين لنفس الحاجة.
    if params is not None and any(r.get("adopted") for r in rows):
        job.ok("    The thickness now comes from the model, so every figure "
               "worked out from it is restated here - the lines printed at "
               "the top of this run were on the old setting:")
        job.info(f"    Self weight: {params.self_weight:.2f} kN/m\u00b2")
        job.info(f"    Balanced load: {params.balanced_load:.2f} kN/m\u00b2")
        job.info(f"    Available drape: {params.drape * 1000:.0f} mm")
        for d in ("X", "Y"):
            job.info(f"    Direction {d} drape: "
                     f"{params.drape_for(d) * 1000:.0f} mm")
        job.info(f"    Anchor elevation: {params.anchor_elevation:.0f} mm "
                 f"below the top surface (half the slab).")
    return rows



