def _esc(s):
    return (str(s).replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def _tile(value, label):
    return f'<div class="tile"><b>{_esc(value)}</b><span>{_esc(label)}</span>' \
           f'</div>'


def render_run_report(m, notes=None, title=None):
    """
    **التقرير كصفحة واحدة (17.34).** بياخد ناتج `measure_design` ويطلّع
    HTML قايم بذاته - مفيش ملفات برّه ولا إنترنت، فيفتح على أي جهاز.
    """
    m = m or {}
    t = m.get("tendons") or {}
    name = title or m.get("model") or "this floor"
    head = [f'<title>{_esc(name)} - PT design</title>',
            f"<style>{REPORT_CSS}</style>",
            '<div class="wrap">',
            f"<h1>{_esc(name)}</h1>",
            f'<div class="sub">Auto PT Suite {_esc(m.get("version", ""))}'
            f' · {_esc(m.get("when", ""))}</div>']

    tiles = [_tile(f'{m.get("slab_m2", 0):,.0f} m²', "slab designed"),
             _tile(f'{t.get("count", 0):,}', "tendons"),
             _tile(f'{t.get("strands", 0):,}', "strands")]
    if t.get("kg"):
        tiles.append(_tile(f'{t["kg"]:,.0f} kg', "strand weight"))
    if t.get("kg_m2"):
        tiles.append(_tile(f'{t["kg_m2"]:.2f}', "kg per m²"))
    if t.get("sharpest_bend_m"):
        tiles.append(_tile(f'{t["sharpest_bend_m"]:.2f} m', "sharpest bend"))
    body = ['<h2>The design</h2>', '<div class="tiles">'] + tiles + ['</div>']

    strips = m.get("strips") or {}
    if strips:
        body += ['<h2>Design strips</h2>', "<table><tr><th>Direction</th>"
                 "<th class='n'>Strips</th><th class='n'>Coverage</th>"
                 "<th class='n'>Overlap</th><th class='n'>No strip</th></tr>"]
        for ss, s in strips.items():
            cov = float(s.get("coverage") or 0.0)
            ov = float(s.get("overlap_m2") or 0.0)
            body.append(
                f"<tr><td>{_esc(ss)}</td>"
                f"<td class='n'>{s.get('strips', 0)}</td>"
                f"<td class='n' class2=''>{cov:.1f}%</td>"
                f"<td class='n {'bad' if ov > 0.5 else 'good'}'>"
                f"{ov:.1f} m² ({s.get('overlap_pairs', 0)} pair(s))</td>"
                f"<td class='n'>{s.get('uncovered_m2', 0):,.0f} m²</td></tr>")
        body.append("</table>")

    sup = m.get("supports") or {}
    dirn = m.get("direction") or {}
    if sup or dirn:
        body += ['<h2>Lines and supports</h2>',
                 "<table><tr><th>Direction</th>"
                 "<th class='n'>Supports with no line</th>"
                 "<th class='n'>Spans</th>"
                 "<th class='n'>Off the tendons</th>"
                 "<th class='n'>Past the allowance</th></tr>"]
        for d in sorted(set(list(sup) + list(dirn))):
            s = sup.get(d) or {}
            g = dirn.get(d) or {}
            miss = s.get("missed")
            body.append(
                f"<tr><td>{_esc(d)}</td>"
                f"<td class='n'>"
                + (f"{miss} of {s.get('total', 0)}" if miss is not None
                   else "-") + "</td>"
                f"<td class='n'>{g.get('spans', '-')}</td>"
                f"<td class='n'>"
                + (f"{g['mean_off_deg']:.1f}° mean, {g['worst_off_deg']:.1f}° "
                   f"worst" if g else "-") + "</td>"
                f"<td class='n {'bad' if g.get('past_the_allowance') else 'good'}'>"
                + (str(g.get("past_the_allowance", 0)) if g else "-")
                + "</td></tr>")
        body.append("</table>")

    if notes:
        body += ["<h2>Worth knowing</h2>", "<ul>"]
        body += [f"<li>{_esc(n)}</li>" for n in notes]
        body.append("</ul>")

    body.append('<div class="foot">Written by the run that produced the '
                'model beside this file. The numbers are measured from that '
                'model, not estimated.</div></div>')
    return "\n".join(head + body)


def save_run_report(m, folder, stem, job=None, notes=None):
    """بيكتب التقرير جنب الموديل. بترجّع المسار أو None."""
    try:
        os.makedirs(folder, exist_ok=True)
        path = os.path.join(folder, f"{stem}_AutoPT_report.html")
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(render_run_report(m, notes))
        if job:
            job.ok(f"One page with everything this run designed: "
                   f"{os.path.basename(path)} - it opens in a browser and on "
                   f"a phone, and it is the file to send on.")
        return path
    except Exception as e:
        if job:
            job.info(f"    the report was not written ({e}).")
        return None



