def support_lines_offline(site, params, job=None):
    """
    خطوط الركائز بنفس قواعد الرن الحقيقي - من غير ما يتكتب حاجة في رام.

    `write_design_strips_to_ram` بتعمل الترتيب ده بالظبط قبل ما ترسم،
    فالتخطيط اللي بيطلع من هنا هو اللي رام كان هياخده.
    """
    lines = []
    for _sub in split_site_into_pieces(site):                   # 18.15
        if str(getattr(params, "strip_layout", "frames")) == "frames":
            _l = build_lines_from_walls(_sub, params, job)
            if not _l:
                _l = build_support_lines(_sub, params, job)
        else:
            _l = build_support_lines(_sub, params, job)
        lines.extend(_l or [])
    lines, _m, _g = snap_lines_onto_supports(lines, site, params, job)
    lines, _w = extend_lines_to_walls(lines, site, params, job)
    lines, _c1, _s1 = prune_crowded_spans(lines, params, job)
    lines, _a, _cov = cover_every_support(lines, site, params, job)
    lines, _c2, _s2 = prune_crowded_spans(lines, params, job)
    return lines


# ==============================================================================
#  التصميم الابتدائي - السُمك والدروبات، قبل ما يتبني موديل
# ==============================================================================
#  البرنامج كله بيبدأ من سُمك مكتوب في الإعدادات ودروبات مرسومة في الكاد.
#  الاتنين دول **أكبر قرارين في المشروع** من ناحية الفلوس: تخطيط
#  الكابلات بيحرّك حديد الـ PT 10-20٪، والسُمك بيحرّك الخرسانة والوزن
#  الذاتي - وده بيرجع يزوّد الـ PT والحديد والأعمدة والقواعد - والشدّة.
#  والدروب هو اللي بيقرر أصلاً إذا كانت البلاطة تقدر تبقى رفيعة.
#
#  اللي هنا بيقرر الاتنين من شبكة الأعمدة، بقواعد الكود، ومتسعّر. مش
#  رأي: تلات فحوص، كل واحد بيرجّع رقم ومرجعه.
#
#  **رام يفضل الحكم.** اللي هنا تصميم ابتدائي - هو اللي بيختار من إيه
#  يتبني الموديل، مش اللي بيعتمده.

#  نسب البحر/السُمك للبلاطات المسبقة الإجهاد. القيم دي **مش** من جداول
#  الخرسانة العادية (ACI 318 جدول 8.3.1.1) - دي للبلاطات المسلحة،
#  واستعمالها لبلاطة PT بيطلّع سُمك أكبر 30-40٪ من اللي بيتبني فعلاً.
#  مصادر PT: Concrete Society TR43 (البند 3.3)، PTI DC20.9، وVSL.
#  الرقم = L/h، فالأكبر معناه بلاطة أرفع.
#  الأربع حالات مكتوبة صريحة. أول نسخة كانت بتحسب حالة "الحمل التقيل"
#  من الحالتين التانيين، والحساب طلع **مقلوب**: حمل أتقل كان بيدّي
#  نسبة أكبر يعني بلاطة أرفع. الحمل التقيل بيرفع الترخيم فبيطلب
#  بلاطة **أتخن** - يعني نسبة أصغر.
SPAN_DEPTH = {
    #  الكود: L/h لكل حالة
    "ACI":  {"flat": 45.0, "drops": 50.0,
             "flat_heavy": 40.0, "drops_heavy": 45.0,
             "beams": 52.0, "beams_heavy": 46.0},
    "EC2":  {"flat": 42.0, "drops": 48.0,
             "flat_heavy": 38.0, "drops_heavy": 42.0,
             "beams": 48.0, "beams_heavy": 43.0},
    "ECP":  {"flat": 40.0, "drops": 45.0,
             "flat_heavy": 36.0, "drops_heavy": 40.0,
             "beams": 45.0, "beams_heavy": 40.0},
}

#  الحد الأدنى للضغط المتوسط. ACI 318 §8.6.2.1: 0.86 MPa (125 psi).
#  والحد الأعلى العملي 3.0 - فوقه القِصَر والزحف بياكلوا القوة.
PA_MIN, PA_MAX = 0.86, 3.00

#  فرق التكلفة اللي تحته الحلول بتتعامل كإنها متساوية، والاحتياطي هو
#  اللي بيرجّح. 5% في الخرسانة مش فرق يشتري بيه حل بلا هامش في الثقب.
PRELIM_COST_TIE = 0.05

#  أقل غطسة تستاهل. تحتها البلاطة مالهاش سلوك مسبق الإجهاد: القوة
#  المطلوبة بتنفجر، والغطاء والدكت مااخدوش مكانهم أصلاً.
PRELIM_MIN_DRAPE = 30.0


def _axis_lines(values, tol):
    """يجمّع قيم متقاربة في محاور، ويرجّع مركز كل محور."""
    out = []
    for v in sorted(values):
        if out and v - out[-1][-1] <= tol:
            out[-1].append(v)
        else:
            out.append([v])
    return [sum(g) / len(g) for g in out]


def beams_are_downstand(site, params=None):
    """
    كمرات الرسمة ساقطة ولا مخفية؟

    الفرق ده بيقلب التصميم: الكمرة الساقطة ركيزة خطية، فالبلاطة بتشيل
    **بين الكمرات** مش بين الأعمدة، ونسب البلاطة المسطحة مالهاش محل،
    والعمود اللي الكمرات داخلة فيه مشكلته قص كمرة مش ثقب.

    الرسمة نفسها بتقول لو الكمرة مكتوب عمقها. لما ماتقولش - وده
    الغالب - الإعداد هو اللي بيحكم، وبيتقال في اللوج بدل ما البرنامج
    يفترض ويسكت.
    """
    mode = str(getattr(params, "beam_role", "downstand")
               or "downstand").lower()
    if mode.startswith("down"):
        return True, "the settings say the beams are downstand"
    if mode.startswith("flush") or mode.startswith("band"):
        return False, "the settings say the beams are flush with the slab"
    h = float(getattr(params, "slab_thickness", 250.0) or 250.0)
    deep = [b for b in (site.get("beams") or [])
            if float(b.get("depth") or 0.0) > 1.2 * h]
    if deep:
        return True, (f"{len(deep)} beam(s) in the drawing are deeper than "
                      f"the slab")
    known = [b for b in (site.get("beams") or []) if b.get("depth")]
    if (site.get("beams") or []) and not known:
        return True, ("no beam in the drawing carries a depth, and a beam "
                      "nobody troubled to draw flush is a downstand one")
    return False, "no beam is deeper than the slab"


def _columns_framed_by_beams(site, near=0.8):
    """الأعمدة اللي كمرة بتنتهي عندها أو بتعدّي عليها."""
    out = set()
    for c in (site.get("columns") or []):
        x, y = c["center"]
        for b in (site.get("beams") or []):
            p1, p2 = b.get("p1"), b.get("p2")
            if not p1 or not p2:
                continue
            if point_to_segment_dist(x, y, p1[0], p1[1], p2[0], p2[1]) <= near:
                out.add((round(x, 2), round(y, 2)))
                break
    return out


def beam_support_points(site, coord, along="x", tol=None):
    """نقط عبور الكمرات لخط على `coord` - ركائز البلاطة الحقيقية."""
    tol = AXIS_CLUSTER_TOL if tol is None else tol
    k = 0 if along == "x" else 1
    o = 1 - k
    out = []
    for b in (site.get("beams") or []):
        p1, p2 = b.get("p1"), b.get("p2")
        if not p1 or not p2:
            continue
        lo, hi = sorted((p1[o], p2[o]))
        half = max(float(b.get("width", 300.0) or 300.0), 100.0) / 2000.0
        if lo - half - tol <= coord <= hi + half + tol:
            if abs(p2[o] - p1[o]) > 1e-9:
                f = max(0.0, min(1.0, (coord - p1[o]) / (p2[o] - p1[o])))
                out.append(p1[k] + f * (p2[k] - p1[k]))
            else:
                out.append((p1[k] + p2[k]) / 2.0)
    return out


def floor_grid(site, tol=None, min_on_axis=2):
    """
    شبكة الأعمدة: محاور X ومحاور Y ومراكزها.

    **الأعمدة بس.** أول نسخة كانت بتحط الحوائط كمان، والنتيجة على
    موديل المهندس كانت 13 محور في X بدل 9 - نص جدار كور السلّم بيعمل
    محور لوحده فيطلّع "بحور" 2.05 و2.65 و2.90 م مالهاش وجود، وبيزحلق
    المحور الحقيقي (23.78 مع حيطة على 23.59 بيبقوا 23.15) فالبحر
    الجنبه بيطلع 8.24 م بدل 7.55. البحر الأكبر هو اللي بيحدد السُمك،
    فغلط 0.7 م فيه غلط سنتيمتر في الخرسانة على كل السقف.

    والحائط لسه ركيزة - هو داخل في فحص الثقب وفي الموديل - بس مش
    بيعرّف محور شبكة. والمحور اللي عليه عمود واحد بيتشال: ده عمود
    شارد مش خط.
    """
    tol = AXIS_CLUSTER_TOL if tol is None else tol
    pts = [tuple(c["center"]) for c in (site.get("columns") or [])]
    if not pts:
        return {"x": [], "y": [], "points": []}

    def axes(vals):
        groups = []
        for v in sorted(vals):
            if groups and v - groups[-1][-1] <= tol:
                groups[-1].append(v)
            else:
                groups.append([v])
        return [sum(g) / len(g) for g in groups if len(g) >= min_on_axis]

    return {"x": axes([p[0] for p in pts]), "y": axes([p[1] for p in pts]),
            "points": pts}


def support_rows(site, along="x", tol=None):
    """
    صفوف الأعمدة: كل صف قايمة أعمدة على نفس الخط، مرتّبة.

    `along="x"` معناه صفوف أفقية (نفس الـ y) - ودي اللي بحورها في X.
    """
    tol = AXIS_CLUSTER_TOL if tol is None else tol
    cols = list(site.get("columns") or [])
    if not cols:
        return []
    key = 1 if along == "x" else 0
    cols.sort(key=lambda c: c["center"][key])
    rows, cur = [], []
    for c in cols:
        if cur and c["center"][key] - cur[-1]["center"][key] > tol:
            rows.append(cur)
            cur = []
        cur.append(c)
    if cur:
        rows.append(cur)
    other = 0 if along == "x" else 1
    return [sorted(r, key=lambda c: c["center"][other])
            for r in rows if len(r) >= 2]


def row_supports(row, site, along="x", tol=None, beams=False):
    """
    نقط الركيزة على صف واحد: مراكز أعمدته، **وأي حائط بيقطع الصف**.

    الحائط مش بيعرّف محور شبكة، بس هو ركيزة بكل معنى الكلمة: الكور
    اللي في نص السقف بيقسم البحر لنصين. من غيره الصف عند y = -16.47
    بيطلع بحر 11.95 م بين عمودين، وفي الحقيقة كور السلّم عند x = -1.4
    واقف في نصّه - يعني بحرين قدّهم 5.9 م. الفرق ده وحده بيرفع السُمك
    المقترح من 220 لـ 300 مم على السقف كله.
    """
    tol = AXIS_CLUSTER_TOL if tol is None else tol
    k = 0 if along == "x" else 1
    o = 1 - k
    coord = sum(c["center"][o] for c in row) / len(row)
    pts = [c["center"][k] for c in row]
    for w in (site.get("walls") or []):
        p1, p2 = w.get("p1"), w.get("p2")
        if not p1 or not p2:
            continue
        lo, hi = sorted((p1[o], p2[o]))
        half = max(float(w.get("width", 250.0) or 250.0), 100.0) / 2000.0
        if lo - half - tol <= coord <= hi + half + tol:
            #  الحائط بيقطع الصف - نقطة الركيزة هي عبوره
            if abs(p2[o] - p1[o]) > 1e-9:
                f = (coord - p1[o]) / (p2[o] - p1[o])
                f = max(0.0, min(1.0, f))
                pts.append(p1[k] + f * (p2[k] - p1[k]))
            else:
                pts.append((p1[k] + p2[k]) / 2.0)
    #  والكمرة الساقطة ركيزة زي الحائط - البلاطة بتشيل بين الكمرات.
    if beams:
        pts.extend(beam_support_points(site, coord, along, tol))
    #  نقطتين متلاصقتين = نفس الركيزة (وشّي حائط واحد)
    pts.sort()
    out = [pts[0]]
    for v in pts[1:]:
        if v - out[-1] > tol:
            out.append(v)
    return out, coord


def grid_spans(site_or_grid, min_span=2.0, beams=False):
    """
    كل بحر في السقف، مقيس **على صفه هو**.

    الشبكة المتعرجة هي القاعدة مش الاستثناء: على موديل المهندس الصف
    عند y = -13.32 بحوره 8.13 و9.33 و7.20 و7.25 و7.15 و6.80، والصف
    عند y = -23.65 بحوره 6.50 و7.20 و5.60 و6.35 و7.54 و6.68 و4.94
    و7.55. قياس البحور من محاور عامة بيخلط الصفين ويطلّع بحور مالهاش
    وجود - ولأن البحر الأكبر هو اللي بيحدد السُمك، الغلطة دي بتتحوّل
    سنتيمترات خرسانة على السقف كله.

    بترجّع {"x": [...], "y": [...]} بالأطوال، و`spans_detail` بيدّي
    نفس البحور بمكانها.
    """
    site = site_or_grid
    if isinstance(site, dict) and ("columns" in site or "boundary" in site):
        out = {}
        for d in ("x", "y"):
            vals = []
            for row in support_rows(site, d):
                pts, _c = row_supports(row, site, d, beams=beams)
                for a, b in zip(pts, pts[1:]):
                    if b - a >= min_span:
                        vals.append(b - a)
            out[d] = sorted(vals)
        return out
    #  شكل قديم: محاور جاهزة
    grid = site_or_grid
    out = {}
    for d in ("x", "y"):
        ax = grid.get(d) or []
        out[d] = [b - a for a, b in zip(ax, ax[1:]) if b - a >= min_span]
    return out


def spans_detail(site, min_span=2.0, beams=False):
    """كل بحر ومكانه: [(الاتجاه, الطول, من, إلى, إحداثي الصف)]."""
    out = []
    for d in ("x", "y"):
        for row in support_rows(site, d):
            pts, coord = row_supports(row, site, d, beams=beams)
            for a, b in zip(pts, pts[1:]):
                if b - a >= min_span:
                    out.append((d.upper(), b - a, a, b, coord))
    out.sort(key=lambda z: -z[1])
    return out


def min_thickness(span_m, code="ACI", has_drops=False, live_kpa=0.0,
                  sdl_kpa=0.0, on_beams=False):
    """
    أقل سُمك من نسبة البحر/السُمك، بالمليمتر.

    الحمل داخل في الاختيار: نسبة L/50 متعايرة على حمل مكتبي/سكني، ومع
    حمل تشغيل تقيل بترجع لنسبة البلاطة المسطحة - وده اللي جداول TR43
    بتقوله بالنص.
    """
    tab = SPAN_DEPTH.get(code) or SPAN_DEPTH["ACI"]
    heavy = (float(live_kpa or 0.0) + float(sdl_kpa or 0.0)) >= 5.0
    #  البلاطة على كمرات ساقطة مسنودة على خطوط، مش على نقط - فهي أرفع
    #  من البلاطة المسطحة عند نفس البحر، مش أتخن.
    base = "beams" if on_beams else ("drops" if has_drops else "flat")
    return float(span_m) * 1000.0 / tab[base + ("_heavy" if heavy else "")]


def _f_sqrt(fc):
    return math.sqrt(max(float(fc or 30.0), 1.0))


def punching_capacity(code, fc, b0, d, beta=1.0, alpha_s=40.0, fpc=0.0,
                      vp=0.0):
    """
    مقاومة ثقب القص، بالنيوتن.

    · ACI 318-19 §22.6.5.2 للخرسانة العادية: أقل تلات قيم
      0.33·√f'c · b0·d ، 0.17(1+2/β)√f'c · b0·d ،
      0.083(2+αs·d/b0)√f'c · b0·d
      ومع سبق الإجهاد §22.6.5.5: (0.29√f'c + 0.3·fpc)·b0·d + Vp،
      والـ fpc بينفع لحد 3.5 MPa بس، وده **بالظبط سبب إن الضغط
      المتوسط بيساعد في الثقب** - حاجة بتتنسى وبتطلّع دروبات مش
      محتاجينها.
    · EC2 §6.4.4: 0.18/γc · k · (100ρl fck)^(1/3) · u1·d ، بحد أدنى
      vmin، وزائد 0.10·σcp.
    · ECP 203 §4-2-2-3: qcup = 0.316√(fcu/γc) مضروبة في نفس معاملات
      الشكل.
    """
    fc = float(fc or 30.0)
    b0 = float(b0); d = float(d)
    if b0 <= 0 or d <= 0:
        return 0.0
    if code == "EC2":
        k = min(1.0 + math.sqrt(200.0 / max(d, 1.0)), 2.0)
        rho = 0.005                      # نسبة حديد نموذجية في الابتدائي
        v = max(0.12 * k * (100.0 * rho * fc) ** (1.0 / 3.0),
                0.035 * k ** 1.5 * math.sqrt(fc))
        return (v + 0.10 * min(float(fpc or 0.0), 2.0)) * b0 * d
    if code == "ECP":
        fcu = fc * 1.25                  # أسطواني -> مكعبي بالتقريب المعتاد
        q = min(0.316 * math.sqrt(fcu / 1.5),
                0.316 * math.sqrt(fcu / 1.5) * (0.50 + d / max(b0, 1.0)))
        return q * b0 * d
    #  ACI / SBC
    fr = _f_sqrt(fc)
    base = min(0.33 * fr,
               0.17 * (1.0 + 2.0 / max(beta, 1.0)) * fr,
               0.083 * (2.0 + alpha_s * d / max(b0, 1.0)) * fr)
    if fpc and fpc > 0:
        pre = 0.29 * fr + 0.3 * min(float(fpc), 3.5)
        base = max(base, min(pre, 0.5 * fr))
    return base * b0 * d + float(vp or 0.0)


# ==============================================================================
#  فحص الثقب بعد رسم الكابلات (18.121)
#
#  ACI 318-19 §22.6 (والكود السعودي SBC 304 بيتبعه حرفياً): إجهاد القص
#  على القطاع الحرج على d/2 من وش العمود
#      vu = Vu/(b0·d) + γv·Mu·c/Jc        (§8.4.4.2.3)
#  من رد فعل العمود اللي رام حسبه للتوليفة المضاعفة - القوة الرأسية
#  والعزم غير المتوازن في الاتجاهين - مقابل
#      φ·vc ، vc من §22.6.5.2 (عادي) أو §22.6.5.5 (مسبق الإجهاد:
#      0.29√f'c + 0.3·fpc، بشرط fpc ≥ 0.9 MPa في الاتجاهين والعمود
#      الداخلي مش أقرب من 4h لحرف حر).
#  القطاع الحرج بيتبني كأضلاع، والضلع اللي بيقع برّه البلاطة بيتشال -
#  فعمود الحرف والركن بياخدوا قطاعهم الحقيقي ومركزه الحقيقي، وJc بتتحسب
#  على الأضلاع اللي فضلت. والعمود اللي في دروب بيتفحص مرتين: عند وشه
#  بعمق الدروب، وعند حرف الدروب بعمق البلاطة.
# ==============================================================================

PUNCH_CODES = {
    "ACI 318-19 / SBC 304": "ACI",
    "EC2 (EN 1992-1-1)": "EC2",
    "ECP 203": "ECP",
}


def punch_section_segments(cx, cy, c1_mm, c2_mm, d_mm, boundary, openings=None):
    """
    أضلاع القطاع الحرج (بالمتر) حوالين عمود مركزه (cx, cy) ومقاسه c1×c2
    مم، على d/2 من الوش. الضلع اللي نصه برّه البلاطة (أو جوّه فتحة)
    بيتشال - ده عمود حرف أو ركن.
    """
    hx = (float(c1_mm) + float(d_mm)) / 2000.0
    hy = (float(c2_mm) + float(d_mm)) / 2000.0
    corners = [(cx - hx, cy - hy), (cx + hx, cy - hy), (cx + hx, cy + hy), (cx - hx, cy + hy)]
    segs = []
    for i in range(4):
        a, b = corners[i], corners[(i + 1) % 4]
        mid = ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0)
        if boundary and len(boundary) >= 3 and not point_in_polygon(mid[0], mid[1], boundary):
            continue
        if any(len(o) >= 3 and point_in_polygon(mid[0], mid[1], o) for o in (openings or [])):
            continue
        segs.append((a, b))
    return segs


def punch_section_props(segs, d_mm):
    """
    خواص القطاع الحرج من أضلاعه (الأطوال بالمليمتر): المحيط b0،
    المركز، وJc حول المحورين (§8.4.4.2.3، R8.4.4.2.3) والمسافة من
    المركز لأبعد ليفة في كل اتجاه. Jc حول X بتستخدم مسافات y.
    """
    d = float(d_mm)
    if not segs:
        return None
    L = [math.hypot((b[0] - a[0]) * 1000.0, (b[1] - a[1]) * 1000.0) for a, b in segs]
    b0 = sum(L)
    if b0 <= 0:
        return None
    mx = sum(l * (a[0] + b[0]) / 2.0 for l, (a, b) in zip(L, segs)) / b0
    my = sum(l * (a[1] + b[1]) / 2.0 for l, (a, b) in zip(L, segs)) / b0
    jx = jy = 0.0          # jx: حول محور X (مسافات y)، jy: حول Y (مسافات x)
    for l, (a, b) in zip(L, segs):
        along_x = abs(b[0] - a[0]) >= abs(b[1] - a[1])
        ymid = ((a[1] + b[1]) / 2.0 - my) * 1000.0
        xmid = ((a[0] + b[0]) / 2.0 - mx) * 1000.0
        if along_x:
            jy += d * l ** 3 / 12.0 + l * d ** 3 / 12.0 + d * l * xmid ** 2
            jx += d * l * ymid ** 2
        else:
            jx += d * l ** 3 / 12.0 + l * d ** 3 / 12.0 + d * l * ymid ** 2
            jy += d * l * xmid ** 2
    xs = [p[0] for a, b in segs for p in (a, b)]
    ys = [p[1] for a, b in segs for p in (a, b)]
    return {"b0": b0, "cx": mx, "cy": my, "Jx": jx, "Jy": jy,
            "cx_max": max(abs(x - mx) for x in xs) * 1000.0,
            "cy_max": max(abs(y - my) for y in ys) * 1000.0,
            "bx": (max(xs) - min(xs)) * 1000.0, "by": (max(ys) - min(ys)) * 1000.0}


def punch_gamma_v(b1, b2):
    """نصيب العزم غير المتوازن اللي بيتنقل بالقص (§8.4.4.2.2): γv = 1 − γf."""
    return 1.0 - 1.0 / (1.0 + (2.0 / 3.0) * math.sqrt(max(b1, 1.0) / max(b2, 1.0)))


def punch_fpc_at(tendons, cx, cy, h_mm, params, half=3.0):
    """
    متوسط الضغط المسبق (MPa) في كل اتجاه عند العمود: الكابلات اللي بتعدّي
    على العمود في حدود ±half م عرضياً، قوتها الفعّالة على مساحة
    (2·half) × h. بترجّع (fpc_x, fpc_y).
    """
    out = {}
    try:
        pe = float(params.force_per_strand)
    except Exception:
        pe = float(getattr(params, "strand_force_kn", 0.0) or 100.0)
    for direction in ("X", "Y"):
        force = 0.0
        for t in (tendons or []):
            if t.get("_deleted") or osh_tendon_dir(t) != direction:
                continue
            prof = t.get("profile") or []
            if len(prof) < 2:
                continue
            ax = 0 if direction == "X" else 1
            lo = min(q["pos"][ax] for q in prof)
            hi = max(q["pos"][ax] for q in prof)
            at = cx if direction == "X" else cy
            if not (lo - 0.3 <= at <= hi + 0.3):
                continue
            if abs(osh_across(t, direction) - (cy if direction == "X" else cx)) > half:
                continue
            force += int(t.get("strands") or 0) * pe
        out[direction] = force * 1000.0 / max(2.0 * half * 1000.0 * float(h_mm), 1.0)
    return out["X"], out["Y"]


def punch_one(cx, cy, c1, c2, d_mm, boundary, openings, Vu_kN, Mx_kNm, My_kNm,
              fc, code, fpc=0.0, phi=None):
    """
    فحص واحد على قطاع حرج واحد. بيرجّع dict فيه vu وφvc والاستغلال،
    أو None لو القطاع مافيهوش ضلع جوّه البلاطة.
    """
    segs = punch_section_segments(cx, cy, c1, c2, d_mm, boundary, openings)
    pr = punch_section_props(segs, d_mm)
    if pr is None:
        return None
    d = float(d_mm)
    Vu = abs(float(Vu_kN)) * 1000.0
    Mx = abs(float(Mx_kNm)) * 1.0e6
    My = abs(float(My_kNm)) * 1.0e6
    v_dir = Vu / (pr["b0"] * d)
    gvx = punch_gamma_v(pr["by"], pr["bx"])      # عزم حول X: البحر في اتجاه y
    gvy = punch_gamma_v(pr["bx"], pr["by"])
    v_mx = gvx * Mx * pr["cy_max"] / max(pr["Jx"], 1.0)
    v_my = gvy * My * pr["cx_max"] / max(pr["Jy"], 1.0)
    vu = v_dir + v_mx + v_my
    n_sides = len(segs)
    pos = "interior" if n_sides == 4 else ("edge" if n_sides == 3 else "corner")
    beta = max(c1, c2) / max(min(c1, c2), 1.0)
    cap = punching_capacity(code, fc, pr["b0"], d, beta=beta,
                            alpha_s=POSITION[pos]["alpha_s"], fpc=fpc)
    vc = cap / (pr["b0"] * d)
    if phi is None:
        phi = 1.0 if code == "EC2" else 0.75
    return {"vu": vu, "v_dir": v_dir, "v_mx": v_mx, "v_my": v_my, "vc": vc,
            "phi": phi, "phi_vc": phi * vc, "u": vu / max(phi * vc, 1e-9),
            "b0": pr["b0"], "d": d, "sides": n_sides, "position": pos,
            "fpc": fpc, "gamma_vx": gvx, "gamma_vy": gvy}


def punching_check_columns(site, reactions_by_combo, params, tendons=None, job=None):
    """
    كل أعمدة الموديل على كل توليفة مضاعفة، والأسوأ لكل عمود.
    `reactions_by_combo`: {اسم التوليفة: نتيجة read_reactions_from_ram}.
    بيرجّع {"code", "fc", "h", "rows": [...], "failed": [...], "combos": [...]}.
    """
    code = PUNCH_CODES.get(str(getattr(params, "punch_code", "") or ""), None) or (
        "EC2" if "EC" in str(getattr(params, "design_code", "")).upper() else "ACI")
    fc = float(getattr(params, "punch_fc", 0.0) or 0.0) or 30.0
    h = float(getattr(params, "slab_thickness", 250.0) or 250.0)
    h_drop = float(getattr(params, "drop_thickness", 0.0) or 0.0)
    cover = float(getattr(params, "punch_cover", 30.0) or 30.0)
    d_slab = max(h - cover - 16.0, 50.0)
    boundary = site.get("boundary") or []
    openings = [o for o in (site.get("openings") or []) if o and len(o) >= 3]
    drops = [dp for dp in (site.get("drops") or []) if dp and len(dp) >= 3]
    cols = list(site.get("columns") or [])
    order = sorted(range(len(cols)), key=lambda i: (-round(cols[i]["center"][1], 1),
                                                    round(cols[i]["center"][0], 1)))
    ids = {i: f"C{k + 1}" for k, i in enumerate(order)}
    rows = []
    for i, col in enumerate(cols):
        cx, cy = float(col["center"][0]), float(col["center"][1])
        c1 = float(col.get("b", 400.0) or 400.0)
        c2 = float(col.get("d", 400.0) or 400.0)
        pos = column_position((cx, cy), boundary)
        fpc_x, fpc_y = punch_fpc_at(tendons, cx, cy, h, params) if tendons else (0.0, 0.0)
        fpc = 0.0
        if code == "ACI" and pos == "interior" and min(fpc_x, fpc_y) >= 0.9 and fc <= 70.0:
            fpc = min(fpc_x, fpc_y)
        elif code != "ACI":
            fpc = min(fpc_x, fpc_y)
        in_drop = next((dp for dp in drops if point_in_polygon(cx, cy, dp)), None)
        row = {"id": ids[i], "at": (cx, cy), "c1": c1, "c2": c2, "position": pos,
               "fpc_x": fpc_x, "fpc_y": fpc_y, "fpc": fpc, "drop": in_drop is not None,
               "u": 0.0, "combo": "", "Vu": 0.0, "Mx": 0.0, "My": 0.0,
               "col": None, "drop_face": None, "notes": []}
        near_open = min((min(math.hypot(px - cx, py - cy) for px, py in o) for o in openings),
                        default=1e9)
        if near_open <= 4.0 * h / 1000.0:
            row["notes"].append(f"an opening within 4h ({near_open:.1f} m): the perimeter "
                                f"facing it is not reduced here (ACI 22.6.4.3)")
        found = False
        for combo, rx in (reactions_by_combo or {}).items():
            best = None
            for rc in (rx or {}).get("columns", []):
                dd = math.hypot(rc["pos"][0] - cx, rc["pos"][1] - cy)
                if dd <= 0.6 and (best is None or dd < best[0]):
                    best = (dd, rc)
            if best is None:
                continue
            found = True
            F = best[1]["F"]
            Vu, Mx, My = F.get("Fz", 0.0), F.get("Mx", 0.0), F.get("My", 0.0)
            if in_drop and h_drop > h:
                r_col = punch_one(cx, cy, c1, c2, max(h_drop - cover - 16.0, 50.0),
                                  boundary, openings, Vu, Mx, My, fc, code, fpc)
                x0, y0, x1, y1 = bbox_of(in_drop)
                r_dp = punch_one((x0 + x1) / 2.0, (y0 + y1) / 2.0, (x1 - x0) * 1000.0,
                                 (y1 - y0) * 1000.0, d_slab, boundary, openings,
                                 Vu, Mx, My, fc, code, fpc)
            else:
                r_col = punch_one(cx, cy, c1, c2, d_slab, boundary, openings,
                                  Vu, Mx, My, fc, code, fpc)
                r_dp = None
            if r_col is None:
                continue
            u = max(r_col["u"], r_dp["u"] if r_dp else 0.0)
            if u > row["u"] or not row["combo"]:
                row.update({"u": u, "combo": combo, "Vu": abs(Vu), "Mx": abs(Mx),
                            "My": abs(My), "col": r_col, "drop_face": r_dp})
        if not found:
            row["notes"].append("no reaction found for this column in the model")
        rows.append(row)
    failed = [r for r in rows if r["u"] > 1.0]
    return {"code": code, "fc": fc, "h": h, "h_drop": h_drop, "rows": rows,
            "failed": failed, "combos": list((reactions_by_combo or {}).keys()),
            "n": len(rows)}


def punching_check_in_session(session, site, params, job, tendons=None):
    """
    يقرا ردود أفعال الأعمدة من التوليفات المضاعفة في الموديل المفتوح
    (لازم يكون متحلّل) ويفحص الثقب. بيرجّع النتيجة أو None.
    """
    try:
        cases = ram_load_cases(session, None)
    except Exception as e:
        if job:
            job.warn(f"Punching check: the load combinations could not be listed ({e}).")
        return None
    combos = [c for c in cases if c.get("kind") == "combo"]
    picked = [c for c in combos if "factored" in c["name"].lower()
              or "ultimate" in c["name"].lower() or "uls" in c["name"].lower()]
    if not picked:
        picked = [c for c in combos if "1.2" in c["name"] or "1.4" in c["name"]]
    if not picked:
        if job:
            job.warn("Punching check: no factored load combination was found in the "
                     "model (a name with 'Factored'), so the check did not run.")
        return None
    by = {}
    for c in picked:
        try:
            by[c["name"]] = read_reactions_from_ram(session, [c["name"]], None)
        except Exception as e:
            if job:
                job.warn(f"Punching check: reactions for '{c['name']}' could not be read ({e}).")
    if not by:
        return None
    res = punching_check_columns(site, by, params, tendons=tendons, job=job)
    if job:
        job.log("Punching shear check", "head")
        job.info(f"{PUNCH_CODES_NAMES.get(res['code'], res['code'])}: f'c {res['fc']:.0f} MPa, "
                 f"slab {res['h']:.0f} mm" + (f", drops {res['h_drop']:.0f} mm" if res['h_drop'] > res['h'] else "")
                 + f"; {res['n']} column(s) checked on {len(by)} factored combination(s): "
                 + ", ".join(by.keys()) + ".")
        for r in res["rows"]:
            c = r.get("col") or {}
            line = (f"    {r['id']} ({r['at'][0]:.1f}, {r['at'][1]:.1f}) {r['position']}"
                    f"{' + drop' if r['drop'] else ''}: Vu {r['Vu']:.0f} kN, Mu "
                    f"{r['Mx']:.0f}/{r['My']:.0f} kNm, vu {c.get('vu', 0):.2f} vs φvc "
                    f"{c.get('phi_vc', 0):.2f} MPa"
                    + (f" (at the drop edge {r['drop_face']['vu']:.2f} vs {r['drop_face']['phi_vc']:.2f})"
                       if r.get("drop_face") else "")
                    + f" -> {r['u']:.2f}" + (f" [{r['combo']}]" if r['combo'] else ""))
            if r["notes"]:
                line += " · " + "; ".join(r["notes"])
            (job.warn if r["u"] > 1.0 else job.info)(line)
        if res["failed"]:
            job.flag(f"PUNCHING: {len(res['failed'])} of {res['n']} column(s) fail - "
                     + ", ".join(f"{r['id']} ({r['u']:.2f})" for r in res["failed"]) + ".")
        else:
            job.ok(f"Punching: all {res['n']} column(s) are safe (worst "
                   f"{max((r['u'] for r in res['rows']), default=0.0):.2f} of the limit).")
    return res


PUNCH_CODES_NAMES = {v: k for k, v in PUNCH_CODES.items()}


def column_position(pt, boundary, near=1.2):
    """داخلي / طرفي / ركن - من قرب العمود لحدود البلاطة."""
    if not boundary:
        return "interior"
    n = len(boundary)
    close = 0
    for i in range(n):
        a, b = boundary[i], boundary[(i + 1) % n]
        if point_to_segment_dist(pt[0], pt[1], a[0], a[1], b[0], b[1]) <= near:
            close += 1
    return "corner" if close >= 2 else ("edge" if close == 1 else "interior")


#  معاملات الشكل والموقع. αs من ACI 318 §22.6.5.3، وهي اللي بتخلّي
#  عمود الركن أضعف كتير من الداخلي عند نفس المحيط.
POSITION = {"interior": {"alpha_s": 40.0, "trib": 1.00},
            "edge":     {"alpha_s": 30.0, "trib": 0.50},
            "corner":   {"alpha_s": 20.0, "trib": 0.25}}


def critical_perimeter(c1, c2, d_mm, position="interior"):
    """
    محيط القطاع الحرج على بُعد d/2 من وش العمود، بالمليمتر.

    ACI بيقيس المحيط المستطيل؛ EC2 بيقيس محيط مدوّر على 2d، وهو أطول.
    الفرق ده متسيب عن قصد: كل كود بيتحسب بمحيطه هو، وإلا بنخلط
    مقاومة كود مع هندسة كود تاني.
    """
    c1 = float(c1); c2 = float(c2); d = float(d_mm)
    if position == "corner":
        return (c1 + d / 2.0) + (c2 + d / 2.0)
    if position == "edge":
        return 2.0 * (c1 + d / 2.0) + (c2 + d)
    return 2.0 * (c1 + d) + 2.0 * (c2 + d)


def critical_perimeter_ec2(c1, c2, d_mm, position="interior"):
    """محيط EC2 على 2d من الوش، بأركان مدوّرة."""
    c1 = float(c1); c2 = float(c2); d = float(d_mm)
    full = 2.0 * (c1 + c2) + 2.0 * math.pi * 2.0 * d
    return {"corner": 0.25, "edge": 0.5}.get(position, 1.0) * full


def punching_check_column(col, grid, boundary, h_mm, params, code="ACI",
                          drop_size_m=0.0, drop_h_mm=0.0, fpc=0.0):
    """
    فحص الثقب عند عمود واحد.

    بيرجّع dict فيه الاستغلال عند وش العمود (`u_col`) وعند وش الدروب
    (`u_drop`)، والحمل والمحيط والعمق الفعّال - عشان اللي بيقرا يقدر
    يراجع الرقم مش يصدّقه.

    القص المطلوب = الحمل المضاعف × (مساحة التحميل − المساحة جوّه
    المحيط الحرج). طرح المساحة الجوّانية بند في الكود مش تدقيق: الحمل
    اللي واقع جوّه المحيط بينزل على العمود مباشرة.
    """
    pt = tuple(col["center"])
    pos = column_position(pt, boundary)
    c1 = float(col.get("b", 400.0) or 400.0)
    c2 = float(col.get("d", 400.0) or 400.0)
    cov = float(getattr(params, "bot_cover", 40.0) or 40.0)
    fc = float(getattr(params, "prelim_fc", 0.0) or 0.0) or 30.0

    #  مساحة التحميل: نص البحر من كل ناحية
    sx = _half_spans(pt[0], grid.get("x") or [])
    sy = _half_spans(pt[1], grid.get("y") or [])
    trib = sx * sy
    wu = factored_load(params, h_mm)          # kN/m2

    out = {"at": pt, "position": pos, "trib_m2": trib, "wu": wu,
           "code": code, "c1": c1, "c2": c2}

    def one(hh, cc1, cc2, alpha_mul=1.0):
        d = max(hh - cov - 12.0, 50.0)        # مركز الحديد تحت الغطاء
        if code == "EC2":
            b0 = critical_perimeter_ec2(cc1, cc2, d, pos)
        else:
            b0 = critical_perimeter(cc1, cc2, d, pos)
        inside = (b0 / 4.0 / 1000.0) ** 2 if pos == "interior" else 0.0
        vu = wu * max(trib - inside, 0.0) * 1000.0        # نيوتن
        beta = max(cc1, cc2) / max(min(cc1, cc2), 1.0)
        cap = punching_capacity(code, fc, b0, d, beta=beta,
                                alpha_s=POSITION[pos]["alpha_s"] * alpha_mul,
                                fpc=fpc)
        phi = 0.75 if code != "EC2" else 1.0
        return {"d": d, "b0": b0, "vu": vu, "cap": phi * cap,
                "u": vu / max(phi * cap, 1e-9)}

    out["col"] = one(drop_h_mm or h_mm, c1, c2)
    out["u_col"] = out["col"]["u"]
    if drop_size_m and drop_h_mm:
        #  الفحص التاني: وش الدروب، بسُمك البلاطة
        side = float(drop_size_m) * 1000.0
        out["drop"] = one(h_mm, side, side)
        out["u_drop"] = out["drop"]["u"]
    else:
        out["u_drop"] = 0.0
    out["u"] = max(out["u_col"], out["u_drop"])
    return out


def _half_spans(v, axis):
    """نص البحر يمين + نص البحر شمال حوالين محور - عرض التحميل."""
    if not axis:
        return 0.0
    i = min(range(len(axis)), key=lambda k: abs(axis[k] - v))
    lo = (axis[i] - axis[i - 1]) / 2.0 if i > 0 else 0.0
    hi = (axis[i + 1] - axis[i]) / 2.0 if i + 1 < len(axis) else 0.0
    if lo <= 0 and hi <= 0:
        return 0.0
    #  عمود طرفي: الكابولي أو حتة الحافة، والنص الناقص بياخد نص البحر
    #  الموجود بدل صفر - عمود الحافة بيشيل أكتر من ربع البحر بكتير.
    lo = lo or hi * 0.5
    hi = hi or lo * 0.5
    return lo + hi


def factored_load(params, h_mm):
    """
    الحمل المضاعف kN/m2: 1.2(الوزن الذاتي + SDL) + 1.6 التشغيل.

    الوزن الذاتي بيتحسب من السُمك اللي بيتجرّب، مش من الإعدادات -
    ودي نص الفايدة: بلاطة أتخن بتحمّل نفسها، والفرق ده هو اللي
    بيخلّي التخين مش دايماً بيحل المشكلة.
    """
    sw = CONCRETE_DENSITY * float(h_mm) / 1000.0
    sdl = float(getattr(params, "sdl", 0.0) or 0.0)
    ll = float(getattr(params, "live_load", 0.0) or 0.0)
    return 1.2 * (sw + sdl) + 1.6 * ll


#  أسعار افتراضية، بأي عملة - المهم النسبة بينهم. اللي بيغيّر القرار
#  هو **نسبة** سعر الخرسانة لسعر الحديد، مش الرقم المطلق.
PRICES = {"concrete_m3": 450.0, "pt_kg": 12.0, "rebar_kg": 4.5,
          "formwork_m2": 60.0}


def option_cost(area_m2, h_mm, drops, prices=None, pt_kg_m2=5.0,
                rebar_kg_m2=12.0):
    """
    تكلفة حل واحد. بترجّع dict بالبنود عشان اللي بيقرا يشوف اللي اتغيّر
    فين، مش رقم واحد.

    الشدّة بتتحسب على مساحة المسقط - الدروب بيزوّد جوانب بس، ودي في
    حدود 2٪ فمتسيبة برّه. والخرسانة بتشمل حجم الدروبات.
    """
    pr = dict(PRICES)
    pr.update(prices or {})
    vol = area_m2 * float(h_mm) / 1000.0
    for d in (drops or []):
        side = float(d.get("size_m") or 0.0)
        extra = max(float(d.get("h_mm") or 0.0) - float(h_mm), 0.0)
        vol += side * side * extra / 1000.0
    out = {
        "concrete_m3": vol,
        "concrete": vol * pr["concrete_m3"],
        "pt": area_m2 * pt_kg_m2 * pr["pt_kg"],
        "rebar": area_m2 * rebar_kg_m2 * pr["rebar_kg"],
        "formwork": area_m2 * pr["formwork_m2"],
    }
    out["total"] = out["concrete"] + out["pt"] + out["rebar"] + out["formwork"]
    out["per_m2"] = out["total"] / max(area_m2, 1e-9)
    return out


def size_drop_for(col, grid, boundary, h_mm, params, code, span_m,
                  fpc=0.0, steps=(0.0, 1.8, 2.4, 3.0, 3.6)):
    """
    أصغر دروب بيعدّي عند العمود ده - أو None لو ولا واحد عدّى.

    الأبعاد بتتجرّب بالترتيب، وأول واحد بيعدّي هو اللي بيترجع: الدروب
    الأكبر من اللازم خرسانة وشدّة مدفوعة على الفاضي. سُمك الدروب
    بيتجرّب هو كمان، لأن دروب عريض رفيع ودروب ضيق تخين حلّين مختلفين
    لنفس المشكلة.

    الحد على المقاس من الكود: امتداد الدروب من محور العمود مايقلّش عن
    L/6 عشان يتحسب دروب في العزوم (ACI 318 §8.2.4)، فأي مقاس أقل من
    كده بيشتغل للثقب بس وبيتقال.
    """
    want_side = 2.0 * span_m / 6.0
    for side in steps:
        if side <= 0:
            r = punching_check_column(col, grid, boundary, h_mm, params, code,
                                      fpc=fpc)
            if r["u"] <= 1.0:
                return {"size_m": 0.0, "h_mm": h_mm, "u": r["u"],
                        "check": r, "counts_for_moment": True}
            continue
        for extra in (100.0, 150.0, 200.0, 250.0):
            hh = h_mm + extra
            r = punching_check_column(col, grid, boundary, h_mm, params, code,
                                      drop_size_m=side, drop_h_mm=hh, fpc=fpc)
            if r["u"] <= 1.0:
                return {"size_m": side, "h_mm": hh, "u": r["u"], "check": r,
                        "counts_for_moment": side >= want_side - 1e-6,
                        "moment_side_m": want_side}
    return None


def prelim_drape_mm(h_mm, params):
    """الغطسة المتاحة عند سُمك معيّن، مم - من الغطاء للغطاء."""
    top = float(getattr(params, "top_cover", 40.0) or 40.0)
    bot = float(getattr(params, "bot_cover", 40.0) or 40.0)
    half = float(getattr(params, "half_duct", 12.0) or 12.0)
    return float(h_mm) - (top + half) - (bot + half)


def prelim_pa(span_m, h_mm, params):
    """
    الضغط المتوسط اللي البلاطة دي هتحتاجه عشان توازن حملها، MPa.

    **الفحص ده كان ناقص، وهو اللي بيحكم على البلاطات الرفيعة.** نسبة
    البحر/السُمك بتقول إن 160 مم تشيل بحر 6.2 م، والثقب بيعدّي بدروب،
    فالاختيار على التكلفة بيقع على 160 - والغطسة هناك **56 مم** ضد
    156 عند 260. والقوة بتتناسب عكسياً مع الغطسة، فالـ P/A بيطلع فوق
    العملي والبلاطة دي مش قابلة للتنفيذ أصلاً.

        P = w·L² / (8·a)   [kN/m من العرض]     ثم   P/A = P / h

    بترجّع (P/A، الغطسة مم، الحمل الموازن kN/m²)، أو (None, ...) لو
    مافيش غطسة خالص.
    """
    a = prelim_drape_mm(h_mm, params)
    if a < PRELIM_MIN_DRAPE:
        return None, a, 0.0
    sw = CONCRETE_DENSITY * float(h_mm) / 1000.0
    dl = sw + float(getattr(params, "sdl", 0.0) or 0.0)
    r = float(getattr(params, "code_balance_ratio", 0.65) or 0.65)
    w = r * dl
    P = w * float(span_m) ** 2 / (8.0 * a / 1000.0)      # kN لكل متر عرض
    return P / float(h_mm), a, w


def governing_span(spans, outlier=1.6):
    """
    البحر اللي السقف بيتصمّم عليه، والبحور الشاذة اللي برّه الحساب.

    **السقف مابيتصمّمش على أطول بحر فيه.** على رسمة المهندس الوسيط
    4.15 م وأطول بحر 25.50 - ستة أضعاف - فالتصميم على الأقصى طلّع
    بلاطة 710 مم. البحر اللي أطول من `outlier` × الوسيط إما قراية غلط
    (ركيزة مش متقروة) أو حتة عايزة كمرة، والاتنين بيتعالجوا موضعياً -
    مش بسنتيمترات خرسانة على السقف كله.

    بترجّع (البحر الحاكم, [البحور الشاذة], الوسيط).
    """
    xs = sorted(float(v) for v in (spans or []) if v and v > 0)
    if not xs:
        return 0.0, [], 0.0
    med = xs[len(xs) // 2]
    cap = outlier * med
    keep = [v for v in xs if v <= cap + 1e-9]
    out = [v for v in xs if v > cap + 1e-9]
    return (keep[-1] if keep else xs[-1]), out, med


# ==============================================================================
#  ملف الدور للذكاء الاصطناعي - وتخطيطه راجع
# ==============================================================================
#  الفكرة: الرسمة تروح لمنصة ذكاء اصطناعي، تقرر التخطيط والمناسيب،
#  والناتج يرجع للبرنامج يبنيه في رام ويحلّله.
#
#  **اللي بيروح مش الـ DXF.** الـ DXF فيه آلاف الكيانات وأسماء ليّرات
#  ومقاسات لوحة، ومفيش نموذج بيقراها بثبات. اللي بيروح هو الهندسة
#  **بعد ما البرنامج قراها**: الأعمدة بمواقعها، البحور مقيسة على صفوفها،
#  الحوائط والكمرات والفتحات، والأحمال والأغطية والحدود الكودية. ده
#  الجزء اللي البرنامج أحسن فيه، والقرار هو الجزء اللي النموذج أحسن فيه.
#
#  واللي بيرجع بيعدّي على نفس قواعد المسقط والبروفايل اللي أي تخطيط
#  بيعدّي عليها - الفتحات، وش الكمرة، أقل طول، المرساتين، نصف القطر -
#  فمافيش حاجة بتترسم من غير ما تتشيّك. النموذج بيقترح، والكود بيفرض،
#  ورام بيحكم.

FLOOR_BRIEF_VERSION = 1


def layout_from_tendons(tendons, params=None):
    """
    التصميم اللي في إيدنا دلوقتي بصيغة ملف التخطيط.

    لازم تبقى موجودة عشان حلقة رام: اللي بيتبعت للموديل في الدورة
    التانية مش التخطيط اللي هو بعته - ده اتقص واتزحلق واترفع من
    القواعد - إنما **اللي رام حلّله فعلاً**.
    """
    out = []
    for t in (tendons or []):
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        out.append({
            "dir": str(t.get("dir") or "X").upper(),
            "strands": int(t.get("strands") or 0),
            "points": [[round(float(q["pos"][0]), 2),
                        round(float(q["pos"][1]), 2),
                        round(float(q["depth"]), 0)] for q in pr],
        })
    return {"tendons": out}


def ai_verdict(plots, params=None, cap=80):
    """
    حكم رام في صورة يقدر الموديل يقرأها: القراءات فوق الحد، الأسوأ الأول.

    الموقع والوش والاتجاه والقيمة والحد - ده كل اللي محتاجه عشان يعرف
    **فين** التخطيط قصّر، وده اللي مافيش طريقة يعرفه بيها غير من رام.
    """
    rows = []
    for pl in (plots or []):
        lim = getattr(pl, "limit", None)
        if lim is None or abs(float(lim)) < 1e-9:
            continue
        face = str(getattr(pl, "face", "") or "")
        d = str(getattr(pl, "direction", "") or "")
        for x, y, v in (getattr(pl, "demand", None) or []):
            u = float(v) / float(lim)
            if u > 1.0:
                rows.append({"at": [round(float(x), 2), round(float(y), 2)],
                             "face": face, "dir": d,
                             "value_mpa": round(float(v), 2),
                             "limit_mpa": round(float(lim), 2),
                             "u": round(u, 2)})
    rows.sort(key=lambda r: -r["u"])
    return {"over_the_limit": len(rows),
            "worst_first": rows[:max(int(cap), 1)]}


def _min_leg(depth_change_mm, params):
    """
    أقصر مسافة في المسقط بين نقطتين فرقهم في العمق كذا، عند أقل نصف قطر.

    من نفس معادلة رام: R = (r/2)·L²/Δ، مقلوبة على L.
    """
    R = float(getattr(params, "min_tendon_radius", 3.0) or 3.0)
    r = float(getattr(params, "ram_inflection_ratio", 0.2) or 0.2)
    d = max(float(depth_change_mm), 1.0) / 1000.0
    return math.sqrt(max(R * d / max(r / 2.0, 1e-6), 0.0))


def brief_rows(site, on_beams=False, min_span=2.0):
    """
    كل صف ركائز بمحطاته وبحوره - {"x": [...], "y": [...]}.

    الكابل الماشي في X عند y معيّن بيقرا صفه هنا على طول: فين الأعمدة
    اللي هيعدّي فوقها، وكل بحر بينهم كام. قايمة الأطوال المرتّبة اللي
    كانت لوحدها في الملف مابتقولش ده - وحسابها من الأول من إحداثيات
    الأعمدة شغل البرنامج عامله فعلاً، وبيغلط فيه اللي يعيده.
    """
    out = {"x": [], "y": []}
    for d in ("x", "y"):
        for row in support_rows(site, d):
            try:
                pts, coord = row_supports(row, site, d, beams=on_beams)
            except Exception:
                continue
            if len(pts) < 2:
                continue
            bays = [round(b - a, 2) for a, b in zip(pts, pts[1:])
                    if b - a >= min_span]
            if not bays:
                continue
            out[d].append({
                ("y" if d == "x" else "x"): round(coord, 2),
                "supports": [round(v, 2) for v in pts],
                "bays": bays,
            })
    return out


def floor_brief(site, params, job=None):
    """
    الدور في صورة يقدر نموذج لغوي يقرأها ويقرر منها. dict جاهز للـ JSON.
    """
    on_beams, why_beams = beams_are_downstand(site, params)
    spans = grid_spans(site, beams=on_beams)
    grid = floor_grid(site)
    area = slab_area_m2(site)
    drape, z_hi, z_lo, h = _drape_m(params)
    w_bal, dl, sw = balanced_load(params)
    allsp = sorted((spans.get("x") or []) + (spans.get("y") or []))
    gov, odd, med = governing_span(
        allsp, float(getattr(params, "prelim_outlier", 1.6) or 1.6))
    bnd = site.get("boundary") or []

    def poly(p):
        return [[round(q[0], 3), round(q[1], 3)] for q in (p or [])]

    out = {
        "brief_version": FLOOR_BRIEF_VERSION,
        "units": {"length": "m", "depth": "mm", "force": "kN",
                  "stress": "MPa", "load": "kN/m2"},
        "slab": {
            "area_m2": round(area, 1),
            "thickness_mm": h,
            "boundary": poly(bnd),
            "openings": [poly(o) for o in (site.get("openings") or [])],
            "drops": [poly(d if isinstance(d, list) else d.get("points"))
                      for d in (site.get("drops") or [])],
            "drop_thickness_mm": float(
                getattr(params, "drop_thickness", 0.0) or 0.0),
        },
        "supports": {
            "columns": [{"at": [round(c["center"][0], 3),
                                round(c["center"][1], 3)],
                         "b_mm": float(c.get("b") or 0.0),
                         "d_mm": float(c.get("d") or 0.0)}
                        for c in (site.get("columns") or [])],
            "walls": [{"from": [round(w["p1"][0], 3), round(w["p1"][1], 3)],
                       "to": [round(w["p2"][0], 3), round(w["p2"][1], 3)],
                       "width_mm": float(w.get("width") or 0.0)}
                      for w in (site.get("walls") or [])],
            "beams": [{"from": [round(b["p1"][0], 3), round(b["p1"][1], 3)],
                       "to": [round(b["p2"][0], 3), round(b["p2"][1], 3)],
                       "width_mm": float(b.get("width") or 0.0),
                       #  صفر كان بيتقرا "كمرة بلا عمق" وهو معناه
                       #  "الرسمة ماكتبتش العمق" - والفرق إن الأولى
                       #  كذب والتانية حقيقة ناقصة.
                       "depth_mm": (float(b.get("depth"))
                                    if float(b.get("depth") or 0.0) > 0
                                    else None)}
                      for b in (site.get("beams") or [])],
            "beams_are_downstand": bool(on_beams),
            "why": why_beams,
        },
        "grid": {"x_axes": [round(v, 3) for v in (grid.get("x") or [])],
                 "y_axes": [round(v, 3) for v in (grid.get("y") or [])]},
        #  **18.50: البحور بمكانها، مش أطوال مجرّدة.** الملف كان بيقول
        #  "66 بحر" بقايمة أطوال مرتّبة، والشغل الحقيقي - أي بحر على
        #  أي صف - كان متروك للموديل يستنتجه من 32 إحداثي عمود. وده
        #  بالظبط اللي البرنامج بيعمله أحسن منه، وبيعمله خلاص.
        "rows": brief_rows(site, on_beams),
        "bays": {
            "x": [round(v, 2) for v in (spans.get("x") or [])],
            "y": [round(v, 2) for v in (spans.get("y") or [])],
            "median_m": round(med, 2),
            "longest_m": round(allsp[-1], 2) if allsp else 0.0,
            "sizing_m": round(gov, 2),
            "outliers_m": [round(v, 2) for v in odd],
        },
        "loads": {
            "self_weight_kpa": round(sw, 2),
            "sdl_kpa": float(getattr(params, "sdl", 0.0) or 0.0),
            "live_kpa": float(getattr(params, "live_load", 0.0) or 0.0),
            "dead_kpa": round(dl, 2),
            "balance_target_kpa": round(w_bal, 2),
            "balance_share_of_dead": round(
                float(getattr(params, "code_balance_ratio", 0.65) or 0.65), 2),
        },
        "tendon": {
            "force_per_strand_kn": round(
                float(getattr(params, "force_per_strand", 110.0) or 110.0), 1),
            "min_strands": int(getattr(params, "min_strands", 2) or 2),
            "max_strands": int(getattr(params, "max_strands", 5) or 5),
            "depth_at_peak_mm": z_hi,
            "depth_at_dip_mm": z_lo,
            "depth_at_anchor_mm": float(
                getattr(params, "anchor_elevation", h / 2.0) or h / 2.0),
            "drape_mm": round(drape * 1000.0, 1),
            #  الغطسة جوّه دروب بانل بتنزل لبطنه، مش لبطن البلاطة -
            #  وده أعمق بكتير، يعني غطسة أكبر وحديد أقل فوق العمود.
            "depth_at_dip_in_drop_mm": round(drop_sag_depth(params, "X"), 1),
            "min_radius_m": float(getattr(params, "min_tendon_radius", 3.0)
                                  or 3.0),
            "min_clear_spacing_m": float(
                getattr(params, "min_clear_spacing", 0.40) or 0.40),
            "min_length_m": float(getattr(params, "min_tendon_length", 6.0)
                                  or 6.0),
            "edge_offset_m": float(getattr(params, "edge_offset", 0.3) or 0.3),
        },
        "rules": [
            "depth is measured DOWN from the top surface of the slab, in mm",
            f"a peak sits at {z_hi:.0f} mm and a dip at {z_lo:.0f} mm; an "
            f"anchorage sits at mid-depth and cannot move",
            "a peak belongs over a support and a dip at the middle of a bay",
            ("DOWNSTAND BEAMS ARE SUPPORTS, like a wall or a column: the "
             "slab spans BETWEEN them. So a slab tendon laid along a beam "
             "carries almost no width and balances almost nothing - do not "
             "band over a column row that a beam already runs along. Run "
             "the slab tendons between the beams, with a peak where they "
             "cross one. Steel that belongs on a beam line belongs IN the "
             "beam, profiled to the beam's own depth where the drape is "
             "several times the slab's - say so in the note rather than "
             "laying it in the slab beside the beam."
             if on_beams else
             "the beams here are flush with the slab, so they are not line "
             "supports and a tendon may run along one"),
            "size each tendon on the bays of the row it follows - they are "
            "in `rows`, already measured along that row with the walls that "
            "split them counted as supports; the sorted list in `bays` is "
            "the whole floor and says nothing about any one tendon",
            "a dip inside a drop panel goes deeper, to "
            f"{drop_sag_depth(params, 'X'):.0f} mm, because the drop is "
            f"thicker - that is more drape for the same slab",
            #  **18.55: قاعدة نصف القطر بالمعادلة، مش بالرقم.** أول
            #  تخطيط حقيقي رجع 9 قطع تحت الحد، و111 قمة اترجّعت لتحت
            #  عشان القاعدة، والغطسة نزلت من 127 لـ 105 مم في المتوسط -
            #  يعني حديد زيادة. الحد كان مكتوب "3.0 م" وبس، وده رقم
            #  مايتشيّكش عليه من غير المعادلة اللي رام بيقيس بيها.
            f"BEND: between any two consecutive points, "
            f"0.1 * L^2 / d must be at least "
            f"{float(getattr(params, 'min_tendon_radius', 3.0) or 3.0):.2f} "
            f"m, with L the distance in metres and d the depth change in "
            f"metres - that is the radius RAM draws from its own inflection "
            f"ratio, and a tighter leg is refused",
            f"the place that bite is a point next to an anchorage, because "
            f"an anchorage cannot move: from {float(getattr(params, 'anchor_elevation', h / 2.0) or h / 2.0):.0f} mm "
            f"to a peak at {z_hi:.0f} mm needs at least "
            f"{_min_leg(abs(float(getattr(params, 'anchor_elevation', h / 2.0) or h / 2.0) - z_hi), params):.2f} m of run, "
            f"and to a dip at {z_lo:.0f} mm at least "
            f"{_min_leg(abs(float(getattr(params, 'anchor_elevation', h / 2.0) or h / 2.0) - z_lo), params):.2f} m; "
            f"closer than that the peak moves farther from the anchorage - "
            f"a peak is never lowered to ease a bend, a dip is lifted instead",
            f"no two tendons closer than "
            f"{float(getattr(params, 'min_clear_spacing', 0.40) or 0.40):.2f} "
            f"m apart in plan - there has to be room for the anchorages and "
            f"for a vibrator between them",
            f"distributed tendons no more than "
            f"{min(8.0 * h / 1000.0, 1.5):.2f} m apart (ACI 318-19 8.7.2.3: "
            f"8h or 1.5 m)",
            "at least two tendons through every column in each direction "
            "(ACI 318-19 8.7.5.6.1)",
            f"average precompression at least {PA_MIN:.2f} MPa in EACH "
            f"direction and not more than {PA_MAX:.2f} in practice "
            f"(ACI 318-19 8.6.2.1)",
            "no tendon may cross an opening or run outside the slab",
            f"no tendon shorter than "
            f"{float(getattr(params, 'min_tendon_length', 6.0) or 6.0):.1f} m",
            "n = w * s * L^2 / (8 * a * Pe) is the load-balancing size, with "
            "w the balanced load, s the tributary width, L the bay, a the "
            "drape and Pe the force per strand",
        ],
        "asked_for": (
            "A tendon layout for this floor. Return JSON in the shape "
            '{"tendons": [{"dir": "X"|"Y", "strands": n, "points": '
            "[[x, y, depth_mm], ...]}]} and nothing else. Give every tendon "
            "its full path: an anchorage at each end, a point over each "
            "support it crosses, and a point at the middle of each bay. "
            "Say in a separate note why you chose the arrangement you chose."
        ),
    }
    if job:
        job.ok(f"Floor brief: {len(out['supports']['columns'])} column(s), "
               f"{len(out['bays']['x']) + len(out['bays']['y'])} bay(s), "
               f"{out['slab']['area_m2']:,.0f} m2, and the rules a layout has "
               f"to satisfy. This is the drawing after it has been read - "
               f"what goes to a model is the geometry and the constraints, "
               f"not the DXF: a drawing has thousands of entities and layer "
               f"names nobody reads the same way twice, and reading it is the "
               f"part this program is good at.")
    return out


def save_floor_brief(site, params, folder, stem, job=None):
    """بيحفظ الملف جنب الرسمة ويرجّع مساره."""
    try:
        data = floor_brief(site, params, job)
        path = os.path.join(folder, f"{stem}_AutoPT_floor.json")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(data, fh, ensure_ascii=False, indent=1)
        if job:
            job.ok(f"Saved as {os.path.basename(path)}. Hand it to whichever "
                   f"model you use and ask for the layout; save what comes "
                   f"back and point 'Or draw a layout from this file' at it. "
                   f"What comes back is drawn as given and then met by every "
                   f"rule this program applies to its own layouts - openings, "
                   f"beam faces, minimum length, anchorage separation, the "
                   f"minimum radius - so nothing reaches RAM unchecked.")
        return path
    except Exception as e:
        if job:
            job.warn(f"The floor brief was not written ({e}).")
        return ""


# ==============================================================================
#  الرفع على منصة الذكاء الاصطناعي - الدور رايح والتخطيط راجع
# ==============================================================================
#  الطرفين كانوا موجودين من 18.36: ملف الدور بيتكتب (`save_floor_brief`)
#  والتخطيط الراجع بيتقرا (`tendons_from_layout`). اللي كان ناقص هو
#  **الرفع نفسه** - كنت بتنسخ الملف وتلزقه في الشات وتنسخ الرد وتحفظه.
#  ده الجزء ده: البرنامج بيكلّم المنصة بنفسه.
#
#  اللي بيتبعت هو **الدور بعد ما اتقرا**، مش الـ DXF: أعمدة بإحداثياتها،
#  بحور متقاسة على صفوفها، حوائط وكمرات وفتحات، أحمال وأغطية وحدود
#  كودية. قراية الرسمة هي الحتة اللي البرنامج أحسن فيها، والقرار هو
#  الحتة اللي النموذج ممكن يكون أحسن فيها.
#
#  واللي راجع مابيوصلش رام زي ما هو: بيعدّي على نفس قواعد المسقط
#  والبروفايل اللي أي تخطيط بيعدّي عليها - الفتحات، وش الكمرة، أقل
#  طول، المرساتين، نصف القطر - وبعدين رام بيحلّله.
#
#      النموذج بيقترح · الكود بيفرض · رام بيحكم
#
#  **المفتاح**: من متغيّر البيئة أو من ملف أنت بتوديه. مابيتحفظش في
#  إعدادات البرنامج ومابيتطبعش في اللوج أبداً - اللي بيتقال مصدره بس.

AI_MODEL_DEFAULT = "claude-opus-5"
#  **18.48: السقف اتوسّع بعد ما رن حقيقي مات عنده.** 32 ألف كانت
#  بتكفي التفكير وتخطيط نص السقف - والتفكير بيتحسب من نفس السقف. أقصى
#  خرج للموديل 128 ألف، و64 مع تقسيم الاتجاهين بيخلّي الاتنين مرتاحين.
AI_MAX_TOKENS = 64000
#  فوق العدد ده من البحور، كل اتجاه بيتطلب لوحده: التخطيط بينقسم نصين
#  وكل نص بياخد سقفه كامل. والاتجاه التاني بيشوف الأول عشان الحمل
#  يتقسّم بينهم مش يتحسب مرتين.
AI_SPLIT_BAYS = 24
#  كم شغل يبذله الموديل قبل ما يرد: low · medium · high · xhigh · max.
#  أعلى = تخطيط أدق ووقت وفلوس أكتر. تخطيط دور شغل تقيل، فالافتراضي
#  high، وmedium بيقصّر الانتظار للنص تقريباً لو بتجرّب.
#  **18.60: medium هو الافتراضي.** القياس على سقف المهندس: 32,349
#  توكن خرج للاتجاه الواحد، **1,600 منهم بس تخطيط** - يعني 95% من
#  الوقت والفلوس تفكير. وvالتفكير ده بيتدفع في كل رن، والرن بيتعاد
#  وأنت بتجرّب. high موجود مكانه للتصميم اللي رايح رام بجد.
AI_EFFORT_DEFAULT = "medium"
AI_EFFORTS = ("low", "medium", "high", "xhigh", "max")

#  شكل الرد، مفروض على النموذج نفسه بدل ما يتراجع بعدين: نفس الشكل
#  اللي `tendons_from_layout` بيقراه من غير أي ترجمة في النص.
AI_LAYOUT_SCHEMA = {
    "type": "object",
    "properties": {
        "tendons": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "dir": {"type": "string", "enum": ["X", "Y"]},
                    "strands": {"type": "integer"},
                    "points": {
                        "type": "array",
                        "items": {"type": "array",
                                  "items": {"type": "number"}},
                    },
                },
                "required": ["dir", "strands", "points"],
                "additionalProperties": False,
            },
        },
        "note": {"type": "string"},
    },
    "required": ["tendons", "note"],
    "additionalProperties": False,
}

AI_SYSTEM = (
    "You are a post-tensioning engineer laying out unbonded tendons on one "
    "floor. The floor reaches you as JSON, already read out of the CAD "
    "drawing: the slab boundary, the openings, the columns, the walls, the "
    "beams, the bays measured along their own support rows, the loads, and "
    "the depths the tendons are held to. Lay the floor out and return the "
    "layout - nothing else.\n"
    "\n"
    "Coordinates are metres in the drawing's own frame. Depth is "
    "millimetres measured DOWN from the top surface of the slab: a small "
    "depth is a high point over a support, a large depth is a dip at "
    "mid-bay, and an anchorage sits at mid-depth and cannot move.\n"
    "\n"
    "How to lay it out:\n"
    " 1. Decide the arrangement before the numbers. Bands over the column "
    "lines in one direction with distributed tendons between them is the "
    "usual flat-slab answer, and the bands belong in the direction with the "
    "longer bays. A floor whose bays are close to square can take one even "
    "mesh both ways. Say which you chose, and why, in the note.\n"
    " 2. Follow the columns. A tendon is worth its price only where it "
    "passes over supports: a run that crosses four columns is worth more "
    "than two runs crossing two. Where a column row is not straight, bend "
    "the tendon to follow it rather than starting a new one - but keep the "
    "bend gentle; the minimum radius in the brief is a hard limit.\n"
    " 3. Profile every tendon over its whole length: an anchorage at each "
    "end, a high point over each support it crosses, and a dip near the "
    "middle of each bay between them. A tendon with no dip balances "
    "nothing.\n"
    " 4. Size it by load balancing, span by span: n = w * s * L^2 / "
    "(8 * a * Pe), with w the balanced load, s the width the tendon carries, "
    "L the bay, a the drape available and Pe the force per strand. Take the "
    "largest n on the tendon, keep it inside the strand limits given, and "
    "round up.\n"
    " 5. Obey the rules list in the brief - the spacing maximum, two "
    "tendons through every column each way, the minimum precompression in "
    "EACH direction, the minimum length, no tendon across an opening or "
    "outside the boundary.\n"
    " 6. Keep away from the openings and from the slab edge by the edge "
    "offset given, and stop a tendon at an edge rather than leaving a short "
    "stub behind it.\n"
    "\n"
    "The layout you return is not built as it stands. The program clears it "
    "of the openings and the beam faces, drops what is too short, separates "
    "anchorages that meet, enforces the minimum radius, and then RAM "
    "analyses it. That pass removes work; it does not add any. So do not "
    "leave it anything to fix.\n"
    "\n"
    "Keep the answer compact: coordinates to two decimals, depths as whole "
    "millimetres, no repeated point, no tendon written twice. The layout is "
    "the whole answer and a floor is a long one - room spent on anything "
    "else is room the layout does not have.\n"
    "\n"
    "If the request names one direction, lay out THAT direction only and "
    "return nothing in the other. Where the tendons already laid out in the "
    "other direction are given with it, they are fixed: read them for the "
    "load they already balance and for where they sit in the section, size "
    "yours for what is left, and do not restate them.\n"
    "\n"
    "When `ram_says` comes with the floor, this is a REVISION, not a new "
    "design. `the_layout_as_built` is what RAM actually analysed - the "
    "layout after the program cut it clear of the openings, moved it off "
    "the beam faces and eased its bends - and `ram_says` is where the "
    "section check came out over the limit, worst first. Work those places "
    "and leave the rest of the floor alone: a reading over the limit wants "
    "drape before it wants steel (take the dip lower or the peak higher if "
    "the cover and the bend allow), then a tendon moved onto the line that "
    "is failing, then strands - in that order, because the first two are "
    "free. Say in the note which readings you went after and what you did "
    "for each. Return the complete layout for the direction asked for, "
    "changed and unchanged tendons alike.\n"
    "\n"
    "The note is for the engineer reading the run afterwards: the "
    "arrangement you chose and why, the direction of the bands, what set "
    "the strand counts, and anything about this floor you would raise with "
    "him - a bay that wants a band beam, an opening that costs a tendon "
    "line, a precompression that says the slab is too thin. Keep it short."
)


def _clean_key(text):
    """
    المفتاح زي ما اتكتب، من غير مسافات ولا علامات تنصيص حواليه.

    **18.45**: `setx KEY "sk-ant-..."` من الـ cmd بيحفظ من غير علامات،
    لكن اللزق في شاشة متغيّرات البيئة بيحفظها معاه - والسيرفر بيرد 401
    على السلسلة دي من غير ما يقول إن العلامتين هما السبب.
    """
    s = (text or "").strip().strip("\r\n").strip()
    while len(s) >= 2 and s[0] == s[-1] and s[0] in "\"'":
        s = s[1:-1].strip()
    return s


def key_shape(key):
    """
    وصف المفتاح **من غير المفتاح**: أوله وطوله وبس.

    ده اللي بيخلّي 401 تتحل من غير ما حد يبعت مفتاحه لحد: مقطوع؟
    توكن دخول مش مفتاح API؟ فيه علامات؟ الثلاثة بيبانوا من الشكل.
    """
    key = key or ""
    head = key[:12] if len(key) > 16 else (key[:4] + "…")
    return f"{head}… , {len(key)} characters"


def ai_credentials(params=None):
    """
    (المفتاح، مصدره، نوعه). المفتاح نفسه مابيترجّعش للّوج ولا بيتحفظ.

    الترتيب: الملف اللي أنت مودّيه، وإلا ANTHROPIC_API_KEY، وإلا
    ANTHROPIC_AUTH_TOKEN. والنوع: "api" بيتبعت في x-api-key، و"oauth"
    (توكن دخول، `sk-ant-oat...`) بيتبعت في Authorization - **هيدر
    مختلف تماماً**، والأول كان بيتبعت مكان التاني فبيترفض.
    """
    prov = ai_provider_of(params)
    path = str(getattr(params, "ai_key_file", "") or "").strip()
    if path:
        base = os.path.basename(path)
        try:
            with open(path, encoding="utf-8") as fh:
                key = _clean_key(fh.read())
        except Exception as e:
            return "", f"the key file could not be read ({e})", "api"
        if key:
            #  **18.97: مفتاح خدمة تانية مابيتقراش أصلاً للباب المحلي.**
            #  المهندس ظبط الخدمة على أولاما وساب خانة ملف المفتاح على
            #  Claude.txt - فالبرنامج قرا مفتاح Anthropic وحاول يبعته
            #  لـ localhost، والحارس رفض ووقف الرن. الحارس صح؛ الغلط
            #  إن المفتاح اتقرا من الأساس: الموديل اللي على الجهاز
            #  مايحتاجش مفتاح. اللي مش شبه مفتاح خدمة تانية بيعدّي زي
            #  ما هو، عشان سيرفر محلي مقفول بمفتاح (vLLM --api-key)
            #  يفضل شغّال.
            if prov == "local" and key.startswith("sk-ant-"):
                return "", (f"the key file {base} holds an Anthropic key "
                            f"and this run uses a model on this machine, "
                            f"which needs none - it was not read, and "
                            f"nothing was sent"), "api"
            return (key, f"the file you pointed at ({base})",
                    "oauth" if key.startswith("sk-ant-oat") else "api")
        return "", f"the key file {base} is empty", "api"
    #  **18.65: كل باب ومفاتيحه.** الكود كان بيقرا ANTHROPIC_API_KEY
    #  مهما كانت المنصة، فرن مقارنة حقيقي بعت **مفتاح Anthropic
    #  لسيرفرات جوجل**. ده مش فشل نداء - ده تسريب سرّ من منصة لمنصة.
    names = {
        "anthropic": ("ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN"),
        "openai": ("OPENAI_API_KEY", "GEMINI_API_KEY", "GOOGLE_API_KEY",
                   "OPENROUTER_API_KEY"),
        "local": (),
    }[prov]
    for name in names:
        key = _clean_key(os.environ.get(name))
        if key:
            kind = ("oauth" if name.endswith("AUTH_TOKEN")
                    or key.startswith("sk-ant-oat") else "api")
            return key, f"the {name} environment variable", kind
    return "", "", "api"


def guard_key_for(params, key, where):
    """
    مفتاح Anthropic عمره ما يروح لحد تاني. بيرمي RuntimeError.

    الحارس هنا مش في مكان النداء عشان يمسك كل الأبواب: المفتاح ممكن
    ييجي من ملف اسمه أي حاجة، والملف هو الطريق اللي بيعدّي منه غالباً.
    """
    if not key:
        return
    if ai_provider_of(params) == "anthropic":
        return
    if key.startswith("sk-ant-"):
        raise RuntimeError(
            f"the key from {where} belongs to Anthropic (it starts "
            f"'sk-ant-') and this request goes to "
            f"{ai_base_url(params) or 'another service'}. It is not sent: "
            f"one service's secret does not travel to another's servers. "
            f"Point the key file at that service's own key, or put it in "
            f"OPENAI_API_KEY / GEMINI_API_KEY. A model on this machine "
            f"needs no key at all - set the service to 'local'.")


def ai_client(params=None):
    """(العميل، مصدر المفتاح). بيرمي RuntimeError برسالة تقول تعمل إيه."""
    key, where, kind = ai_credentials(params)
    if not key:
        raise RuntimeError(
            "there is no API key" + (f" - {where}" if where else "") +
            ". Put the key in the ANTHROPIC_API_KEY environment variable, "
            "or save it in a plain text file on its own and point the key "
            "file box at that file. It is never written into this "
            "program's settings and never printed in the log.")
    try:
        import anthropic
    except ImportError:
        raise RuntimeError(
            "the 'anthropic' package is not installed. Run "
            "'pip install anthropic' in the same Python this program runs "
            "in, then try the run again.")
    if kind == "oauth":
        kw = {"auth_token": key,
              "default_headers": {"anthropic-beta": "oauth-2025-04-20"}}
    else:
        kw = {"api_key": key}
    url = (os.environ.get("ANTHROPIC_BASE_URL") or "").strip()
    if url:
        kw["base_url"] = url
    #  **18.45: المتغيّر التاني بيتشال وقت إنشاء العميل بس.** المكتبة
    #  بتقرا المتغيّرين من البيئة لوحدها، ولو الاتنين موجودين بتبعت
    #  الهيدرين مع بعض والسيرفر بيرفض الطلب - 401 على مفتاح سليم.
    other = "ANTHROPIC_AUTH_TOKEN" if kind == "api" else "ANTHROPIC_API_KEY"
    had = os.environ.pop(other, None)
    try:
        client = anthropic.Anthropic(**kw)
    finally:
        if had is not None:
            os.environ[other] = had
    return client, where


# ---------------------------------------------------------------------------
#  الباب التاني: أي منصة بواجهة OpenAI - وده بيشمل المحلي
# ---------------------------------------------------------------------------
#  **18.58**: البرنامج كان بيعرف منصة واحدة. الواجهة دي بيتكلّمها
#  جيميني وDeepSeek وOpenRouter وxAI، **و**أي موديل شغال على جهازك
#  بـ Ollama أو vLLM أو LM Studio. يعني مهايئ واحد بيفتح على كلهم،
#  ونفس ملف الدور ونفس الـ schema ونفس القواعد تعدّي على اللي راجع -
#  وده شرط عشان المقارنة بين منصتين تبقى عادلة.
#
#  بـ urllib مش بمكتبة: البرنامج ملف واحد بتنسخه، وكل مكتبة زيادة
#  حاجة تانية تتنصّب على جهاز الموقع. والسترييم بيتقرا سطر سطر فالنبضة
#  شغالة والطلب الطويل مابيقعش على مهلة خمول.

AI_PROVIDERS = ("anthropic", "openai", "local")
AI_LOCAL_BASE = "http://localhost:11434/v1"


#  **18.64: عدّاد المصروف.** رن المهندس وقف على «الرصيد خلص» - والبرنامج
#  كان بيقول التوكنز بعد كل نداء ومابيقولش هي كام فلوس ولا المجموع كام.
#  السعر إعداد، مش رقم مدفون: الأسعار بتتغير وكل خدمة بسعرها.
AI_PRICE_IN_DEFAULT = 5.0            # دولار لكل مليون توكن داخل
AI_PRICE_OUT_DEFAULT = 25.0          # دولار لكل مليون توكن خارج
_AI_SPEND = {"in": 0, "out": 0, "usd": 0.0, "calls": 0}


def ai_spend_reset():
    """بداية رن جديد."""
    _AI_SPEND.update({"in": 0, "out": 0, "usd": 0.0, "calls": 0})
    return dict(_AI_SPEND)


def ai_spend_add(params, tok_in, tok_out):
    """بيضيف نداء للعدّاد ويرجّع (تمن النداء، مجموع الرن)."""
    pin = float(getattr(params, "ai_price_in", 0.0) or AI_PRICE_IN_DEFAULT)
    pout = float(getattr(params, "ai_price_out", 0.0) or AI_PRICE_OUT_DEFAULT)
    cost = (int(tok_in or 0) * pin + int(tok_out or 0) * pout) / 1e6
    _AI_SPEND["in"] += int(tok_in or 0)
    _AI_SPEND["out"] += int(tok_out or 0)
    _AI_SPEND["usd"] += cost
    _AI_SPEND["calls"] += 1
    return cost, dict(_AI_SPEND)


def ai_spend_line(cost, run, params):
    """السطر اللي بيتحط جنب التوكنز: تمن النداء ومجموع الرن."""
    cap = float(getattr(params, "ai_budget_usd", 0.0) or 0.0)
    out = f" - about ${cost:.2f} for this call"
    if run.get("calls", 0) > 1:
        out += f", ${run['usd']:.2f} for the run so far"
    if cap > 0:
        out += f" of the ${cap:.2f} you allowed"
    return out


def ai_budget_left(params):
    """
    (فيه مكان؟, الرسالة). الميزانية بتتفحص **قبل** النداء - بعده تكون
    اتصرفت خلاص.
    """
    cap = float(getattr(params, "ai_budget_usd", 0.0) or 0.0)
    if cap <= 0:
        return True, ""
    if _AI_SPEND["usd"] < cap:
        return True, ""
    return False, (
        f"this run has spent about ${_AI_SPEND['usd']:.2f} on "
        f"{_AI_SPEND['calls']} call(s), which is the limit you set "
        f"(${cap:.2f}). Nothing more is sent. Every answer that came back "
        f"before this is saved beside the drawing and can be drawn again "
        f"for nothing; raise 'Stop the run after spending' to carry on.")


def ai_provider_of(params, strict=False):
    """
    اسم المنصة بعد التنظيف. الافتراضي anthropic.

    **18.68: والاسم اللي مش معروف بيتقال، مابيتبلعش.** رن مقارنة حقيقي
    كتب `gemini` كاسم منصة على نسخة لسه ماتعرفهاش، والدالة دي رجّعت
    "anthropic" في سكوت - فطلب جيميني راح لسيرفرات Anthropic بمفتاح
    Anthropic، والجدول طلع فيه صف اسمه gemini-pro-latest ومزوّده
    anthropic. غلطة حرف واحد في خانة كانت بتوصّل لمنصة تانية خالص.
    """
    p = str(getattr(params, "ai_provider", "") or "anthropic").strip().lower()
    if p in AI_PROVIDERS:
        return p
    if strict and p:
        raise RuntimeError(
            f"'{p}' is not a service this program speaks. The ones it knows "
            f"are: {', '.join(AI_PROVIDERS)} - and on a comparison row you "
            f"can name a service instead: "
            f"{', '.join(sorted(set(AI_SERVICES)))}. It is NOT quietly "
            f"treated as the built-in one: that would send this request, "
            f"and this key, to a service you did not ask for.")
    return "anthropic"


def ai_base_url(params):
    """عنوان الخدمة: اللي كتبته، وإلا الافتراضي للمنصة."""
    url = str(getattr(params, "ai_base_url", "") or "").strip()
    if url:
        return url.rstrip("/")
    if ai_provider_of(params) == "local":
        return AI_LOCAL_BASE
    return (os.environ.get("OPENAI_BASE_URL") or "").strip().rstrip("/")


def _sse_lines(resp):
    """أسطر data: من ستريم SSE، واحدة واحدة."""
    for raw in resp:
        line = raw.decode("utf-8", "replace").strip()
        if not line or not line.startswith("data:"):
            continue
        body = line[5:].strip()
        if body == "[DONE]":
            return
        yield body


def ai_models(params, job=None):
    """
    الموديلات اللي المفتاح ده يقدر يستخدمها، من الخدمة نفسها.

    **18.67**: اسم الموديل هو الحاجة الوحيدة اللي لازم تتكتب بالحرف،
    وصفحة المفاتيح مافيهاش أسامي والتوثيق بيقدم. الخدمة عندها القايمة،
    والنداء ده مجاني (GET، مافيش توكنز).
    """
    import urllib.error
    import urllib.request
    base = ai_base_url(params)
    if not base:
        return []
    key, where, _k = ai_credentials(params)
    guard_key_for(params, key, where)
    req = urllib.request.Request(
        base + "/models",
        headers=({"Authorization": f"Bearer {key}"} if key else {}))
    try:
        with urllib.request.urlopen(req, timeout=30.0) as resp:
            data = json.loads(resp.read().decode("utf-8", "replace"))
    except Exception as e:
        if job:
            job.info(f"    the list of models could not be read ({e}).")
        return []
    #  **18.69: الأسامي اللي تنفع للشغل ده الأول.** أول مرة الرسالة
    #  طلعت، القايمة كانت مرتبة أبجدياً ومقصوصة عند 25 - فطلعت كلها
    #  صور وصوت وفيديو، والموديل النصّي اللي هو محتاجه كان بره القص.
    junk = ("image", "audio", "tts", "live", "transcribe", "embedding",
            "robotics", "computer-use", "veo", "lyria", "imagen", "aqa",
            "banana")
    good, rest = [], []
    for row in (data.get("data") or data.get("models") or []):
        name = str(row.get("id") or row.get("name") or "").strip()
        if not name:
            continue
        name = name.split("/")[-1]
        (rest if any(w in name.lower() for w in junk) else good).append(name)
    #  الأقوى الأول: pro قبل flash، والأحدث قبل الأقدم
    good.sort(key=lambda n: (0 if "pro" in n else 1, n), reverse=False)
    return list(dict.fromkeys(good)) + sorted(set(rest))


def ai_timeout_for(params, default_s=900.0, local_s=3600.0):
    """
    كام ثانية ننتظر الرد (18.99).

    الفرق مش تفصيلة: الخدمة السحابية بترد في ثواني، والموديل اللي على
    الجهاز بيولّد توكن توكن بسرعة الكارت (أو المعالج). رن المهندس
    استنى **15 دقيقة كاملة** وبعدين وقع بـ "timed out"، والشغل اللي
    قبله - منشأ وشرايح - راح معاه. مهلة الباب المحلي أطول عن قصد،
    وقابلة للتعديل زي غيرها.
    """
    mine = float(getattr(params, "ai_timeout_s", 0) or 0.0)
    if mine > 0:
        return mine
    return (float(local_s) if ai_provider_of(params) == "local"
            else float(default_s))


def local_token_budget(cap, window, prompt_tokens):
    """
    كام توكن مخرجات ينفع نطلبها من موديل نافذته `window` (18.98).

    بترجّع (السقف الجديد, سطر يتقال أو ""). النافذة مش معروفة -> كل
    حاجة زي ما هي. البريف لوحده أكبر من النافذة -> السقف بيبقى صفر
    والسطر بيقول الأرقام.
    """
    cap = int(cap or 0)
    if not window or window <= 0:
        return cap, ""
    room = int(window) - int(prompt_tokens) - 256          # هامش
    if room <= 0:
        return 0, (f"The floor brief is about {prompt_tokens:,} tokens and "
                   f"this model's whole context is {int(window):,}. There is "
                   f"no room left for an answer, so whatever comes back is "
                   f"truncated. Ask for one direction at a time, raise the "
                   f"model's context (OLLAMA_CONTEXT_LENGTH, or a Modelfile "
                   f"with PARAMETER num_ctx), or use a model with a longer "
                   f"window.")
    if cap <= room:
        return cap, ""
    return room, (f"Asking for {cap:,} output tokens from a model whose whole "
                  f"context is {int(window):,}, with about "
                  f"{prompt_tokens:,} of it already used by the brief. The "
                  f"request is cut to {room:,} so the answer is not silently "
                  f"truncated. Raise the model's context "
                  f"(OLLAMA_CONTEXT_LENGTH, or a Modelfile with PARAMETER "
                  f"num_ctx) if you want more.")


def ollama_models(base_url=None, timeout=4.0):
    """
    الموديلات المنزّلة فعلاً على الجهاز (18.96).

    أولاما بيرد على `/api/tags` بقايمة اللي عنده. العنوان اللي البرنامج
    بيستعمله هو باب الـ OpenAI (`.../v1`)، وجدول الموديلات على الجذر -
    فبنشيل `/v1` ونسأل.

    بترجّع (أسماء، سبب الفشل). القايمة الفاضية مع سبب فاضي معناها
    "أولاما رد ومافيش عنده حاجة".
    """
    import json as _json
    import urllib.error
    import urllib.request
    base = str(base_url or AI_LOCAL_BASE).rstrip("/")
    if base.endswith("/v1"):
        base = base[:-3]
    try:
        with urllib.request.urlopen(base + "/api/tags",
                                    timeout=float(timeout)) as fh:
            data = _json.loads(fh.read().decode("utf-8", "replace"))
    except Exception as e:
        return [], str(e)
    out = []
    for row in (data.get("models") or []):
        name = str(row.get("name") or row.get("model") or "").strip()
        if name:
            out.append(name)
    return sorted(set(out)), ""


def local_model_placement(model, base_url=None, timeout=4.0):
    """
    الموديل ده محمّل فين - كارت ولا معالج؟ (18.100)

    أولاما بيرد على `/api/ps` بكل موديل محمّل وحجمه، و`size_vram` هو
    الجزء اللي فعلاً على الكارت. صفر معناه **المعالج بالكامل**، ورن
    المهندس طلّع ده بالحرف:

        qwen2.5-coder:32b   28 GB   100% CPU
        qwen2.5-coder:14b   15 GB   100% CPU

    وده بيفسّر الربع ساعة من غير رد: موديل 32B على المعالج بيولّد
    توكن أو اتنين في الثانية، وتخطيط دور زي ده آلاف التوكنات.

    بترجّع (النسبة على الكارت 0..1, الحجم الكلي بالبايت) أو None لو
    الموديل مش محمّل دلوقتي - ودي حالة عادية، أولاما بيحمّل عند أول
    نداء وبيفضّي بعد خمس دقايق سكون.
    """
    import json as _json
    import urllib.request
    base = str(base_url or AI_LOCAL_BASE).rstrip("/")
    if base.endswith("/v1"):
        base = base[:-3]
    try:
        with urllib.request.urlopen(base + "/api/ps",
                                    timeout=float(timeout)) as fh:
            data = _json.loads(fh.read().decode("utf-8", "replace"))
    except Exception:
        return None
    want = str(model or "").strip()
    bare = want.partition(":")[0]
    #  **الاسم الكامل الأول.** المهندس كان محمّل :14b و:32b مع بعض،
    #  ومطابقة الاسم من غير الوسم كانت بترجّع أول واحد فيهم - يعني
    #  تقرير عن موديل غير اللي هيتنادى.
    rows = list(data.get("models") or [])
    rows.sort(key=lambda r: 0 if str(r.get("name") or r.get("model")
                                     or "") == want else 1)
    for row in rows:
        name = str(row.get("name") or row.get("model") or "")
        if not (name == want or (":" not in want
                                 and name.partition(":")[0] == bare)):
            continue
        try:
            total = float(row.get("size") or 0.0)
            vram = float(row.get("size_vram") or 0.0)
        except (TypeError, ValueError):
            return None
        if total <= 0:
            return None
        return max(0.0, min(vram / total, 1.0)), total
    return None


LOCAL_TAG_SIZES = ("0.5b", "1b", "1.5b", "2b", "3b", "4b", "7b", "8b",
                   "9b", "12b", "13b", "14b", "22b", "27b", "32b", "34b",
                   "70b", "72b")


def _tag_size_index(name):
    """ترتيب حجم الوسم في `LOCAL_TAG_SIZES`، أو None."""
    tag = str(name or "").partition(":")[2].lower()
    if not tag:
        return None
    for cand in (tag, tag.split("-")[0]):
        try:
            return LOCAL_TAG_SIZES.index(cand)
        except ValueError:
            continue
    return None


def smaller_local_tag(model, have=None):
    """
    أصغر وسم من نفس الموديل **منزّل فعلاً** على الجهاز - أو "" (18.101).

    السطر اللي بيحذّر من البطء كان بينصح بـ `qwen2.5-coder:7b` **وهو
    شغال على 7b بالفعل**، لأن الاسم كان مكتوب في الرسالة بالإيد.

    والنصيحة مابتتخمّنش كمان: أول محاولة للتصليح كانت بتنزّل خطوة في
    جدول الأحجام، فطلعت `qwen2.5-coder:27b` - وسم مالوش وجود في العيلة
    دي أصلاً. اللي بيتقال دلوقتي هو اللي `ollama list` شايفه.
    """
    name = str(model or "").strip()
    base = name.partition(":")[0]
    here = _tag_size_index(name)
    if not base or here is None or here <= 0:
        return ""
    best, best_i = "", -1
    for other in (have or []):
        o = str(other or "").strip()
        if o.partition(":")[0] != base or o == name:
            continue
        i = _tag_size_index(o)
        if i is None or i >= here:
            continue
        if i > best_i:
            best, best_i = o, i
    return best


def local_speed_warning(share, total_bytes, model, have=None):
    """
    السطر اللي بيتقال قبل الانتظار، مش بعده (18.100).

    بترجّع "" لو الموديل على الكارت، أو سطر بيقول المتوقع.
    """
    if share is None:
        return ""
    gb = float(total_bytes or 0.0) / (1024.0 ** 3)
    if share >= 0.99:
        return ""
    if share <= 0.01:
        smaller = smaller_local_tag(model, have)
        return (f"{model} is loaded with NONE of it on the graphics card - "
                f"{gb:.0f} GB, all of it on the processor. A layout for this "
                f"floor is thousands of tokens and a processor generates "
                f"them a few a second, so expect minutes to tens of minutes "
                f"rather than seconds. That is the machine, not the program."
                + (f" {smaller} is already pulled and would answer sooner; "
                   f"a card with room for the whole model is what changes "
                   f"it properly."
                   if smaller else
                   " Nothing smaller of this model is pulled here. On a "
                   "machine with no graphics card in play, a hosted service "
                   "is the practical way to lay out a floor this size, and "
                   "the local one earns its keep on the small jobs."))
    return (f"{model} is {100.0 * share:.0f}% on the graphics card and "
            f"{100.0 * (1.0 - share):.0f}% on the processor ({gb:.0f} GB in "
            f"all). The part on the processor sets the pace, so this will be "
            f"far slower than a model that fits on the card whole.")


def local_model_preload(model, base_url=None, timeout=900.0, job=None):
    """
    يحمّل الموديل في أولاما قبل الطلب نفسه (18.102).

    طلب `/api/generate` من غير prompt بيحمّل الموديل ويرجع على طول. من
    غيره `/api/ps` مابيعرفش الموديل (مش محمّل لسه)، فتحذير المعالج
    (18.100) وطول السياق الفعلي ماكانوش بيتقالوا في أول نداء - وهو
    النداء اللي بيهم. والتحميل ده كان هيحصل جوّه الطلب على أي حال.

    بترجّع (اتحمّل؟, الثواني اللي خدها, السبب لو مااتحمّلش).
    """
    import json as _json
    import urllib.request
    base = str(base_url or AI_LOCAL_BASE).rstrip("/")
    if base.endswith("/v1"):
        base = base[:-3]
    if job:
        job.info(f"    loading {model} into Ollama first - a big model that "
                 f"has to go onto the processor can take minutes here.")
    t0 = time.time()
    try:
        req = urllib.request.Request(
            base + "/api/generate",
            data=_json.dumps({"model": str(model or "")}).encode(),
            headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=float(timeout)) as fh:
            fh.read()
    except Exception as e:
        return False, time.time() - t0, str(e)
    took = time.time() - t0
    if job and took >= 5.0:
        job.info(f"    loaded in {took:.0f}s.")
    return True, took, ""


def local_model_window(model, base_url=None, timeout=4.0):
    """
    طول السياق اللي الموديل المحلي **بيشتغل بيه فعلاً**، بالتوكن،
    ومصدره - أو (None, "") لو أولاما مش بيرد (18.98، واتصلّحت 18.102).

    18.98 كانت بتقرا `.context_length` من `/api/show` - وده أقصى سياق
    الموديل اتدرّب عليه (32,768 لـ qwen2.5-coder)، مش اللي أولاما
    بيحمّله بيه: الافتراضي عنده 4,096 ما لم يتضبط OLLAMA_CONTEXT_LENGTH
    أو num_ctx في Modelfile. فالفحص كان بيعدّي وأولاما بيقص البريف
    بصمت - نفس العرَض اللي 18.98 اتعملت عشانه. الترتيب دلوقتي:
      1) الموديل محمّل: النافذة اللي أولاما بيقولها في `/api/ps`؛
      2) num_ctx في parameters الموديل؛
      3) OLLAMA_CONTEXT_LENGTH على الجهاز ده لو السيرفر محلي؛
      4) وإلا افتراضي أولاما 4,096.
    وكله مسقوف بأقصى سياق الموديل نفسه.
    """
    import json as _json
    import urllib.request
    base = str(base_url or AI_LOCAL_BASE).rstrip("/")
    if base.endswith("/v1"):
        base = base[:-3]

    def _ask(path, body=None):
        try:
            req = urllib.request.Request(
                base + path,
                data=(_json.dumps(body).encode() if body is not None
                      else None),
                headers=({"Content-Type": "application/json"}
                         if body is not None else {}))
            with urllib.request.urlopen(req, timeout=float(timeout)) as fh:
                return _json.loads(fh.read().decode("utf-8", "replace"))
        except Exception:
            return None

    want = str(model or "").strip()
    bare = want.partition(":")[0]
    show = _ask("/api/show", {"model": want})
    ps = _ask("/api/ps")
    if show is None and ps is None:
        return None, ""
    show = show or {}
    trained = None
    for k, v in (show.get("model_info") or {}).items():
        if str(k).endswith(".context_length"):
            try:
                trained = int(v)
            except (TypeError, ValueError):
                trained = None
            break
    window, src = None, ""
    for row in ((ps or {}).get("models") or []):
        name = str(row.get("name") or row.get("model") or "")
        if not (name == want or (":" not in want
                                 and name.partition(":")[0] == bare)):
            continue
        try:
            cl = int(row.get("context_length") or 0)
        except (TypeError, ValueError):
            cl = 0
        if cl > 0:
            window, src = cl, "what Ollama loaded it with (ollama ps)"
            break
    if window is None:
        m = re.search(r"^\s*num_ctx\s+(\d+)",
                      str(show.get("parameters") or ""), re.M)
        if m:
            window, src = int(m.group(1)), "num_ctx in the model's Modelfile"
    if window is None and any(h in base for h in
                              ("localhost", "127.0.0.1", "[::1]", "0.0.0.0")):
        env = (os.environ.get("OLLAMA_CONTEXT_LENGTH") or "").strip()
        if env.isdigit() and int(env) > 0:
            window, src = int(env), "OLLAMA_CONTEXT_LENGTH on this machine"
    if window is None:
        window, src = 4096, ("Ollama's default of 4,096 - set "
                             "OLLAMA_CONTEXT_LENGTH, or num_ctx in a "
                             "Modelfile, to raise it")
    if trained and window > trained:
        window, src = trained, "the model's own limit"
    return window, src


def local_model_is_there(model, base_url=None, timeout=4.0):
    """
    الموديل ده منزّل هنا؟ - بترجّع (نعم/لأ, القايمة, السبب).

    أولاما بيقبل الاسم من غير الوسم (`qwen2.5-coder` = `...:latest`)،
    فالمقارنة بتشوف الاتنين.
    """
    names, why = ollama_models(base_url, timeout)
    if why:
        return True, names, why        # مش قادرين نسأل - مانوقفش الرن
    if not names:
        return False, names, ""        # 18.102: أولاما رد ومافيش حاجة منزّلة
    want = str(model or "").strip()
    if not want:
        return False, names, ""
    bare = want.partition(":")[0]
    for n in names:
        if n == want or n.partition(":")[0] == bare:
            return True, names, ""
    return False, names, ""


def openai_send(system, payload, params, job, schema=AI_LAYOUT_SCHEMA):
    """
    نداء على واجهة OpenAI. بترجّع (النص، الاستخدام، سبب الوقوف).

    الـ schema بيتطلب الأول؛ لو الخدمة رفضته (وفيه خدمات لسه
    مابتعرفوش) بيتعاد بـ json_object والـ prompt هو اللي بيحكم -
    والتحقق عندنا موجود في الحالتين.
    """
    import urllib.error
    import urllib.request

    ai_provider_of(params, strict=True)
    base = ai_base_url(params)
    if not base:
        raise RuntimeError(
            "no address for the service. Put it in 'Service address' on the "
            "settings page - for Gemini that is "
            "https://generativelanguage.googleapis.com/v1beta/openai, for "
            "OpenRouter https://openrouter.ai/api/v1, and for a model on "
            "this machine " + AI_LOCAL_BASE + " (Ollama's default).")
    key, where, _kind = ai_credentials(params)
    guard_key_for(params, key, where)
    if not key and ai_provider_of(params) != "local":
        raise RuntimeError(
            "there is no API key for " + base + ". Save it in a text file "
            "and point the key file box at it, or put it in the "
            "ANTHROPIC_API_KEY variable. A model running on this machine "
            "usually needs no key - set the provider to 'local'.")
    model = str(getattr(params, "ai_model", "") or "").strip()
    if not model:
        raise RuntimeError("no model name. On this door the name is the "
                           "service's own, such as gemini-3-pro or "
                           "qwen2.5-coder:32b.")
    #  **18.96: الموديل المحلي لازم يكون منزّل فعلاً.**
    #  اختيار "On this machine (Ollama)" بيحط الباب والعنوان بس - اسم
    #  الموديل بيفضل اللي في الخانة، وده افتراضياً اسم موديل كلود.
    #  أولاما بيرد 404 باسم مش واضح، فالسؤال بيتعمل هنا والرد بيقول
    #  اللي منزّل فعلاً بالاسم.
    if ai_provider_of(params) == "local":
        _ok, _have, _why = local_model_is_there(model, base)
        if not _ok:
            raise RuntimeError(
                f"'{model}' is not on this machine. Ollama at {base} has: "
                + (", ".join(_have) if _have else "nothing")
                + ". Put one of those in the model box, or pull it first "
                  "(ollama pull " + str(model) + ").")
        if job and _why:
            job.warn(f"Ollama could not be asked what it has ({_why}), so "
                     f"'{model}' is being tried as it stands. If it is not "
                     f"pulled, the call comes back 404.")
    cap = int(getattr(params, "ai_max_tokens", 0) or AI_MAX_TOKENS)
    if ai_provider_of(params) == "local":
        #  **18.98: الطلب لازم يدخل في نافذة الموديل.**
        #  البرنامج بيطلب 64,000 توكن مخرجات - وده وحده أكبر من نافذة
        #  qwen2.5-coder:32b كلها (32,768). والبريف بتاع دور المهندس
        #  طلع 11,676 حرف، يعني حوالي 3,000 توكن داخلة. لو الطلب أكبر
        #  من النافذة، أولاما بيقص من غير ما يقول - والجواب بيرجع
        #  JSON ناقص، واللي بيتقال ساعتها "الرد مش صالح" مش "المقاس".
        #  **18.102: الموديل بيتحمّل الأول، والنافذة هي الفعلية.**
        #  من غير التحميل /api/ps فاضي في أول نداء، فتحذير المعالج
        #  ماكانش بيطلع إلا في النداء التاني. والنافذة كانت أقصى سياق
        #  الموديل مش اللي أولاما شغّال بيه. ولو مافيش مكان للرد الطلب
        #  بيقف هنا بدل ما يتبعت بسقف صفر ويرجع "الرد مش صالح".
        local_model_preload(model, base, timeout=ai_timeout_for(params),
                            job=job)
        _win, _src = local_model_window(model, base)
        _need = (len(system) + len(payload)) // 3        # تقدير محافظ
        cap, _why_cap = local_token_budget(cap, _win, _need)
        if job and _win:
            job.info(f"    {model} runs with a context of {_win:,} tokens "
                     f"({_src}); the brief is about {_need:,} tokens and "
                     f"up to {cap:,} are asked for the answer.")
        if cap <= 0:
            raise RuntimeError(_why_cap or
                               f"there is no room in {model}'s context for "
                               f"an answer")
        if _why_cap and job:
            job.flag(_why_cap)
        #  **18.100: وقول المتوقع قبل الانتظار، مش بعده.**
        _place = local_model_placement(model, base)
        if _place and job:
            _say = local_speed_warning(_place[0], _place[1], model, _have)
            if _say:
                job.flag(_say)
    body = {
        "model": model,
        "messages": [{"role": "system", "content": system},
                     {"role": "user", "content": payload}],
        "max_tokens": cap,
        "stream": True,
        "stream_options": {"include_usage": True},
        "response_format": {
            "type": "json_schema",
            "json_schema": {"name": "tendon_layout", "strict": True,
                            "schema": schema},
        },
    }
    if job:
        job.info(f"    over the OpenAI door at {base} as {model}"
                 + (f", key from {where}"
                    if key else
                    (f" - {where}" if where else ", no key (local)"))
                 + ".")

    def _call(b):
        req = urllib.request.Request(
            base + "/chat/completions",
            data=json.dumps(b).encode("utf-8"),
            headers={"Content-Type": "application/json",
                     "Accept": "text/event-stream",
                     **({"Authorization": f"Bearer {key}"} if key else {})},
            method="POST")
        return urllib.request.urlopen(
            req, timeout=ai_timeout_for(params))

    try:
        resp = _call(body)
    except urllib.error.HTTPError as e:
        detail = ""
        try:
            detail = e.read().decode("utf-8", "replace")[:400]
        except Exception:
            pass
        #  الخدمة مابتعرفش الـ schema: أعد بـ json_object. **بس لو
        #  الرسالة عن الشكل فعلاً** - رن حقيقي رجع 400 "Please pass a
        #  valid API key" والكود قراها "مابيعرفش schema" وأعاد النداء
        #  بشكل أضعف على مفتاح غلط: تخمين، وضيّع نداء، وخبّى السبب.
        _about_shape = any(w in detail.lower() for w in
                           ("schema", "response_format", "json_schema",
                            "structured"))
        if (e.code in (400, 404, 422) and _about_shape
                and "json_schema" in json.dumps(body)):
            if job:
                job.warn(f"    {base} would not take a JSON schema "
                         f"({e.code}), so the shape is asked for in words "
                         f"instead and checked here. {detail[:160]}")
            body["response_format"] = {"type": "json_object"}
            try:
                resp = _call(body)
            except urllib.error.HTTPError as e2:
                raise RuntimeError(f"{base} refused the request "
                                   f"({e2.code}). {detail[:200]}")
        else:
            more = ""
            if e.code in (400, 404) and any(
                    w in detail.lower() for w in ("model", "not found")):
                names = ai_models(params, job)
                if names:
                    more = (f" This key can use {len(names)} models; the "
                            f"ones that write text, strongest first: "
                            + ", ".join(names[:12])
                            + ("…" if len(names) > 12 else "")
                            + ". Put one of those in the model box.")
            raise RuntimeError(f"{base} refused the request ({e.code}). "
                               f"{detail[:200]}" + more)

    text_parts = []
    usage = {}
    finish = ""
    beat = _Heartbeat(job).start()
    try:
        with resp:
            for chunk in _sse_lines(resp):
                beat.events += 1
                try:
                    ev = json.loads(chunk)
                except Exception:
                    continue
                if ev.get("usage"):
                    usage = ev["usage"]
                for ch in (ev.get("choices") or []):
                    bit = ((ch.get("delta") or {}).get("content")
                           or (ch.get("message") or {}).get("content") or "")
                    if bit:
                        text_parts.append(bit)
                        beat.wrote += len(bit)
                    think = (ch.get("delta") or {}).get("reasoning_content")
                    if think:
                        beat.think += len(think)
                        beat.latest = (beat.latest + think)[-400:]
                    if ch.get("finish_reason"):
                        finish = str(ch["finish_reason"])
    finally:
        beat.stop()
    return "".join(text_parts), usage, finish


def _ai_failure_hint(err, key, where):
    """
    السطر اللي بيخلّي الخطأ يتحل. رسالة السيرفر لوحدها بتقول "المفتاح
    غلط" وخلاص، والأسباب الأربعة اللي بتوصل لها معروفة ومحدودة.
    """
    text = f"{err}".lower()
    if "401" in text or "authentication" in text or "invalid x-api-key" in text:
        both = bool(os.environ.get("ANTHROPIC_API_KEY")) and bool(
            os.environ.get("ANTHROPIC_AUTH_TOKEN"))
        out = (f"\n    The key was refused, not the layout. It came from "
               f"{where} and reads as {key_shape(key)}. A working API key "
               f"starts 'sk-ant-api03-' and is about 100 characters. Check, "
               f"in this order: it is a key from console.anthropic.com and "
               f"not a login token from claude.ai or Claude Code; it was "
               f"copied whole, since the console shows it once and a "
               f"half-copied key looks right; there are no quotes or spaces "
               f"around it (echo %ANTHROPIC_API_KEY% in a terminal shows "
               f"what is really stored); and the key still exists.\n"
               f"    And the one that reads as a bad key but is not: a key "
               f"created before the workspace has any credit is refused "
               f"exactly like an invalid one - the console says so when it "
               f"shows you the key, and buying credit is the whole fix. "
               f"A Claude Pro or Max subscription is not API credit.")
        if both:
            out += ("\n    Both ANTHROPIC_API_KEY and ANTHROPIC_AUTH_TOKEN "
                    "are set on this machine. This run sends only one of "
                    "them, but clear the one you are not using - together "
                    "they are refused.")
        return out
    if "429" in text or "rate_limit" in text:
        return ("\n    The account is over its rate limit. Wait a minute "
                "and run it again; nothing about the floor is wrong.")
    if "529" in text or "overloaded" in text:
        return ("\n    The platform is overloaded, not the key. Run it "
                "again in a minute.")
    if ("connect" in text or "timeout" in text or "ssl" in text
            or "proxy" in text):
        return ("\n    The machine could not reach the platform at all - a "
                "proxy, a firewall or no route out. Nothing was sent.")
    if "credit" in text or "billing" in text:
        return ("\n    The key is valid but the workspace has no credit "
                "for it.")
    return ""


class _Heartbeat:
    """
    **18.49: النبضة على ساعة، مش على الأحداث.**

    أول نسخة كانت بتمشي على أحداث الستريم وتقول وصلنا لفين. ولو شكل
    الأحداث مش زي ما هي متوقّعة، بتسكت - وساعتها الرن شكله زي التعليق
    بالظبط، اللي هي الحاجة الوحيدة اللي النبضة موجودة عشانها.

    دلوقتي في خيط لوحده بيتكلّم كل 15 ثانية طول ما الطلب ماشي، سواء
    اتقرا حدث واحد أو ولا حدث. والقراية لو اشتغلت بتحطّ الأرقام في
    العدّادات والخيط بيقولها.
    """

    def __init__(self, job, every=15.0):
        self.job = job
        self.every = float(every)
        self.think = 0
        self.wrote = 0
        self.events = 0
        self.why = ""
        self.latest = ""
        self._said = ""
        self._shape = None
        self.t0 = time.time()
        self._stop = threading.Event()
        self._th = None

    def start(self):
        if not self.job:
            return self
        self._th = threading.Thread(target=self._run, daemon=True)
        self._th.start()
        return self

    def _run(self):
        while not self._stop.wait(self.every):
            gone = time.time() - self.t0
            if self.wrote:
                self.job.info(f"    still going - {self.wrote:,} characters "
                              f"of layout written, {gone:.0f}s so far.")
            elif self.think:
                self.job.info(f"    still thinking about the floor - "
                              f"{self.think:,} characters of reasoning, "
                              f"{gone:.0f}s so far. Nothing is wrong: the "
                              f"thinking comes before the first line of "
                              f"layout.")
                #  آخر ما قاله بلسانه - القرار وهو بيتاخد، مش مؤشّر
                #  بيلف. ده اللي بيخلّي الانتظار مقروء.
                last = (self.latest or "").strip().replace("\n", " ")
                if last and last != self._said:
                    self._said = last
                    self.job.info(f"        \u201c{last[-220:]}\u201d")
            elif self.events:
                self.job.info(f"    the model is working - {gone:.0f}s so "
                              f"far, {self.events:,} event(s) in and no "
                              f"layout yet. It decides the whole "
                              f"arrangement before it writes the first "
                              f"tendon, and it does not stream that part "
                              f"unless it is asked for a summary.")
            else:
                self.job.info(f"    waiting on the model - {gone:.0f}s so "
                              f"far, nothing back yet. A floor this size "
                              f"takes minutes, and the thinking comes "
                              f"before anything can be shown."
                              + (f" (the event stream could not be "
                                 f"followed - {self.why} - so this is a "
                                 f"clock, not a measurement)"
                                 if self.why else ""))

    def follow(self, stream):
        """
        بتعدّي على الأحداث وتملا العدّادات. مابترميش أبداً.

        **18.51: الأشكال التلاتة، وسبب الفشل بيتقال.** رن حقيقي فضل
        150 ثانية بيقول "nothing back yet" والطلب شغّال - يعني القراية
        وقعت والـ except بلعها. الحدث ممكن ييجي خام
        (`delta.type == "thinking_delta"`) أو مجهّز (`ev.type ==
        "thinking"` وجوّه `ev.thinking`)، والعدّ بياخد الاتنين؛ وأي
        حدث مش متصنّف بيتعدّ برضو، لأن "وصلني 400 حدث" أحسن بكتير من
        "مافيش حاجة" لما الاتنين بيحصلوا مع بعض.
        """
        try:
            for ev in stream:
                self.events += 1
                kind = str(getattr(ev, "type", "") or "")
                delta = getattr(ev, "delta", None)
                dkind = str(getattr(delta, "type", "") or "")
                raw = dkind in ("thinking_delta", "text_delta")
                done = kind in ("thinking", "text")
                if not (raw or done):
                    continue
                #  **18.63: كل دلتا بتيجي مرتين** - خام ومجهّزة - والعدّ
                #  كان بياخد الاتنين، فالكلام اللي بيتطبع كان بيتكرر
                #  حرفياً ("a cou a couple of short beams") والأرقام
                #  ضعف الحقيقة. أول شكل يوصل هو اللي بيتعدّ لآخر الرد.
                if self._shape is None:
                    self._shape = "raw" if raw else "done"
                if (self._shape == "raw") != raw:
                    continue
                if raw:
                    bit = (getattr(delta, "thinking", "")
                           if dkind == "thinking_delta"
                           else getattr(delta, "text", "")) or ""
                    wrote = dkind == "text_delta"
                else:
                    bit = (getattr(ev, "thinking", "") if kind == "thinking"
                           else getattr(ev, "text", "")) or ""
                    wrote = kind == "text"
                if wrote:
                    self.wrote += len(bit)
                else:
                    self.think += len(bit)
                    self.latest = (self.latest + bit)[-400:]
        except Exception as e:
            self.why = f"{type(e).__name__}: {e}"
        return self.wrote

    def stop(self):
        self._stop.set()
        if self._th is not None:
            self._th.join(timeout=1.0)
        return self.wrote


def _stream_heartbeat(stream, job, every=15.0):
    """النبضة في نداء واحد - بتشغّل الساعة، تتابع، وتقف."""
    beat = _Heartbeat(job, every).start()
    try:
        return beat.follow(stream)
    finally:
        beat.stop()


def save_ai_raw(text, folder, stem, tag="", job=None):
    """
    اللي رجع من المنصة زي ما هو، **قبل أي تحليل**.

    **18.52**: النداء ممكن ياخد خمس دقايق ويتكلّف فلوس، وبعده أي خطوة
    تقع - قراية، قاعدة، رام - كانت بترمي الرد كله. الملف ده بيتكتب
    أول ما الحروف تكمل، فأسوأ حالة إنك تعيد الخطوة اللي وقعت، مش
    النداء.
    """
    try:
        name = f"{stem}_AutoPT_ai_raw{('_' + tag) if tag else ''}.json"
        path = os.path.join(folder or ".", name)
        k = 2
        while os.path.isfile(path):
            path = os.path.join(folder or ".",
                                name[:-5] + f"-{k}" + ".json")
            k += 1
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(text)
        if job:
            job.ok(f"What came back is on disk as {os.path.basename(path)} "
                   f"({len(text):,} characters) before anything reads it. "
                   f"If a later step fails, the answer is not lost with it.")
        return path
    except Exception as e:
        if job:
            job.warn(f"The answer could not be saved ({e}) - it is still "
                     f"used for this run.")
        return ""


def ask_ai_for_layout(brief, params, job=None, only=None, already=None,
                      out_dir=None, stem=None, verdict=None, layout=None,
                      tag=""):
    """
    بيبعت ملف الدور ويرجّع التخطيط كـ dict بنفس شكل ملف التخطيط.

    `only` = "X" أو "Y" يعني اتجاه واحد بس، و`already` هي كابلات
    الاتجاه التاني اللي اترسمت خلاص - بتتبعت معاه عشان يشوف الحمل
    المتوازن فعلاً بدل ما يتحسب مرتين.

    الرد مفروض عليه schema، فاللي راجع JSON صحيح بالشكل ده أو الكول
    بيقع - مافيش تحليل نص ولا تخمين.
    """
    ok, why = ai_budget_left(params)
    if not ok:
        raise RuntimeError(why)
    prov = ai_provider_of(params, strict=True)
    key, where, _kind = ai_credentials(params)
    client = None
    if prov == "anthropic":
        client, where = ai_client(params)
    model = str(getattr(params, "ai_model", "") or AI_MODEL_DEFAULT)
    cap = int(getattr(params, "ai_max_tokens", 0) or AI_MAX_TOKENS)
    if only or verdict or layout:
        brief = dict(brief)
    if only:
        brief["lay_out_only"] = str(only).upper()
        if already:
            brief["already_laid_out"] = already
    if layout is not None:
        #  **اللي رام حلّله**، مش اللي الموديل بعته: التخطيط اتقص
        #  واتزحلق واترفع من القواعد قبل ما يوصل رام.
        brief["the_layout_as_built"] = layout
    if verdict is not None:
        brief["ram_says"] = verdict
    payload = json.dumps(brief, ensure_ascii=False)
    if job and only:
        job.info(f"    asking for direction {str(only).upper()} on its own"
                 + (f", with the {len(already)} tendon(s) already laid out "
                    f"in the other direction" if already else "")
                 + ".")
    if job:
        job.info(f"Sending the floor to {model}: "
                 f"{len(brief.get('supports', {}).get('columns') or [])} "
                 f"column(s), "
                 f"{len(brief.get('bays', {}).get('x') or []) + len(brief.get('bays', {}).get('y') or [])}"
                 f" bay(s), {brief.get('slab', {}).get('area_m2', 0):,.0f} "
                 f"m2, and the rules a layout has to satisfy - "
                 f"{len(payload):,} characters. "
                 + (f"The key came from {where} ({key_shape(key)}). "
                    if key else
                    (f"No key was sent - {where}. " if where
                     else "No key was sent. "))
                 + f"The drawing itself is not sent: what goes out is the "
                 f"floor after this program has read it.")
    text = ""
    if prov != "anthropic":
        try:
            text, _use, _fin = openai_send(AI_SYSTEM, payload, params, job)
        except Exception as e:
            if prov == "local" and "timed out" in str(e).lower():
                raise RuntimeError(
                    f"the request to {model} timed out after "
                    f"{ai_timeout_for(params) / 60.0:.0f} minutes. Nothing "
                    f"is wrong with the network - the model is on this "
                    f"machine and it is still generating. A 32B model with "
                    f"no room on the graphics card runs on the processor at "
                    f"a few tokens a second, and a layout for this floor is "
                    f"thousands of tokens. Watch it with 'ollama ps': if it "
                    f"says 100% CPU, that is the reason. A smaller model "
                    f"(qwen2.5-coder:14b or :7b) answers in a fraction of "
                    f"the time, or raise 'How long to wait for the "
                    f"platform' on the AI page.")
            raise RuntimeError(f"the request to {model} failed: {e}"
                               + _ai_failure_hint(e, key, where))
        if str(_fin) == "length":
            raise RuntimeError(
                f"{model} ran out of room at {cap:,} tokens before the "
                f"layout was finished"
                + (f" for direction {str(only).upper()}" if only else "") +
                f". Raise 'Token limit for the answer', and lower 'Ask for "
                f"both directions in one call' so each direction is asked "
                f"for on its own.")
        if job and _use:
            _c, _run = ai_spend_add(params,
                                    _use.get("prompt_tokens", 0),
                                    _use.get("completion_tokens", 0))
            job.info(f"    {_use.get('prompt_tokens', 0):,} tokens in and "
                     f"{_use.get('completion_tokens', 0):,} out"
                     + ai_spend_line(_c, _run, params) + ".")
        msg = None
    else:
      try:
        with client.messages.stream(
                model=model,
                max_tokens=cap,
                system=AI_SYSTEM,
                #  **18.53: خلّيه يقول بيفكّر في إيه وهو بيفكّر.**
                #  التفكير الخام مابيترجّعش أصلاً في الموديل ده، فالرن
                #  كان بيقعد دقايق على حدثين. `display: "summarized"`
                #  بيبعت ملخّص جاي أول بأول - يعني اللوج بيوريك القرار
                #  وهو بيتاخد، مش بس إن فيه حاجة شغالة.
                thinking={"type": "adaptive", "display": "summarized"},
                output_config={"format": {"type": "json_schema",
                                          "schema": AI_LAYOUT_SCHEMA},
                               "effort": str(getattr(params, "ai_effort", "")
                                             or AI_EFFORT_DEFAULT)},
                messages=[{"role": "user", "content": payload}],
                timeout=ai_timeout_for(params),
        ) as stream:
            beat = _Heartbeat(job).start()
            try:
                beat.follow(stream)
                msg = stream.get_final_message()
            finally:
                beat.stop()
      except Exception as e:
        raise RuntimeError(f"the request to {model} failed: {e}"
                           + _ai_failure_hint(e, key, where))

    if msg is not None and getattr(msg, "stop_reason", "") == "max_tokens":
        raise RuntimeError(
            f"{model} ran out of room at {cap:,} tokens before the layout "
            f"was finished"
            + (f" for direction {str(only).upper()}" if only else "") +
            f". The thinking is paid for out of the same room as the "
            f"layout, so a floor of this size needs both halves of the "
            f"answer: raise 'Token limit for the answer' on the settings "
            f"page (the model can write up to 128,000), and lower "
            f"'Ask for both directions in one call' so each direction is "
            f"asked for on its own.")
    for b in (getattr(msg, "content", None) or []):
        if getattr(b, "type", "") == "text":
            text = getattr(b, "text", "") or ""
            break
    if not text.strip():
        why = str(getattr(msg, "stop_reason", "") or "") if msg else ""
        kinds = [str(getattr(b, "type", "?"))
                 for b in (getattr(msg, "content", None) or [])] if msg else []
        u = getattr(msg, "usage", None) if msg else None
        #  **18.63: "returned no layout text" كانت بتقول العرض مش السبب.**
        #  الرد وقف بسبب، والسبب في `stop_reason` - رفض، أو سقف توكنز،
        #  أو رد فيه تفكير وبس. من غيره الرن الجاي بيغلط نفس الغلط.
        extra = ""
        if why == "refusal":
            extra = (" The model declined this request outright (a safety "
                     "classifier, not the layout). Run it again; if it "
                     "happens twice, something in the floor's own data is "
                     "tripping it and the brief is on disk to look at.")
        elif why == "max_tokens":
            extra = (" It filled the token limit with reasoning and never "
                     "reached the layout. Raise 'Token limit for the "
                     "answer', or lower 'Ask for both directions in one "
                     "call' so each call is smaller.")
        elif kinds and "text" not in kinds:
            extra = (f" What came back was {', '.join(kinds)} and no text "
                     f"block at all.")
        raise RuntimeError(
            f"{model} returned no layout"
            + (f" and stopped with '{why}'" if why else "")
            + (f" after {getattr(u, 'output_tokens', 0):,} tokens" if u else "")
            + "." + extra
            + " Nothing is lost that was already saved: a direction that "
              "came back before this one is on disk as a layout file.")
    saved = ""
    if stem:
        saved = save_ai_raw(text, out_dir or ".", stem,
                            (str(tag) + str(only or "").upper()) or "", job)
    try:
        data = json.loads(text)
    except Exception as e:
        raise RuntimeError(f"the layout that came back is not valid JSON "
                           f"({e})."
                           + (f" It is saved as {os.path.basename(saved)} "
                              f"and can be repaired by hand rather than "
                              f"asked for again." if saved else ""))
    if not isinstance(data, dict) or not isinstance(data.get("tendons"),
                                                    list):
        raise RuntimeError("the layout that came back has no tendon list.")
    if True:
        u = getattr(msg, "usage", None)
        if u is not None:
            out_tok = int(getattr(u, "output_tokens", 0) or 0)
            _c, _run = ai_spend_add(params,
                                    int(getattr(u, "input_tokens", 0) or 0),
                                    out_tok)
    if job:
        u = getattr(msg, "usage", None)
        if u is not None:
            out_tok = int(getattr(u, "output_tokens", 0) or 0)
            #  التخطيط نفسه تقريباً حرف لكل ربع توكن. الفرق بينه وبين
            #  الخرج كله هو التفكير - وهو اللي بيتدفع فيه الوقت والفلوس.
            lay = max(int(len(text) / 4.0), 1)
            job.info(f"    {getattr(u, 'input_tokens', 0):,} tokens in and "
                     f"{out_tok:,} out"
                     + ai_spend_line(_c, _run, params)
                     + (f", of which the layout is about {lay:,} - the other "
                        f"{max(out_tok - lay, 0):,} is the model deciding "
                        f"the arrangement. That is where the wait and the "
                        f"cost go, and 'How hard the model works before it "
                        f"answers' is the dial on it."
                        if out_tok > lay * 2 else "") + ".")
    return data


def brief_fingerprint(brief):
    """
    بصمة الدور: نفس السقف بنفس القواعد = نفس البصمة.

    غيّر السُمك أو الحمل أو الأغطية - البصمة بتتغيّر والتخطيط المحفوظ
    مابيتردّش استعماله، لأنه بقى لسقف تاني. الحتة اللي بتتشال قبل
    الحساب هي اللي بتتغيّر بين النداءات نفسها (الاتجاه المطلوب، حكم
    رام، التخطيط الحالي).
    """
    core = {k: v for k, v in (brief or {}).items()
            if k not in ("ram_says", "the_layout_as_built", "lay_out_only",
                         "already_laid_out")}
    text = json.dumps(core, sort_keys=True, ensure_ascii=False)
    return hashlib.sha1(text.encode("utf-8")).hexdigest()[:16]


def ai_saved_layout(brief, folder, stem, job=None):
    """
    (التخطيط المحفوظ لنفس الدور, مساره) - أو (None, "").

    **18.70: التخطيط المدفوع تمنه مرة مايتدفعش تانية.** المهندس أعاد
    رن مقارنة عشان يضيف خدمة، فالخدمة اللي رجعت امبارح اتسألت من
    الأول واتدفع فيها دولار ونص على إجابة موجودة على القرص.
    """
    folder = folder or "."
    want = brief_fingerprint(brief)
    best = None
    try:
        for name in os.listdir(folder):
            if not (name.startswith(f"{stem}_AutoPT_ai_layout")
                    and name.endswith(".json")):
                continue
            path = os.path.join(folder, name)
            try:
                with open(path, encoding="utf-8") as fh:
                    data = json.load(fh)
            except Exception:
                continue
            if str(data.get("brief_digest") or "") != want:
                continue
            if not (data.get("tendons") or []):
                continue
            when = os.path.getmtime(path)
            if best is None or when > best[0]:
                best = (when, data, path)
    except Exception:
        return None, ""
    if best is None:
        return None, ""
    if job:
        job.ok(f"This floor was already laid out and the answer is on disk: "
               f"{os.path.basename(best[2])} ({data_count(best[1])}). The "
               f"floor has not changed since - same geometry, same loads, "
               f"same rules - so it is used as it is. No call, nothing "
               f"spent. Untick 'Use a saved layout when the floor has not "
               f"changed' to pay for a fresh one.")
    return best[1], best[2]


def data_count(data):
    """وصف قصير لتخطيط محفوظ."""
    t = (data or {}).get("tendons") or []
    return (f"{len(t)} tendon(s), "
            f"{sum(int(q.get('strands') or 0) for q in t)} strands, from "
            f"{(data or {}).get('when', 'an earlier run')}")


def save_ai_layout(data, brief, params, folder, stem, job=None):
    """
    بيحفظ اللي رجع زي ما هو جنب الرسمة ويرجّع مساره.

    السبب: التصميم لازم يكون قابل للإعادة. الملف ده وحده كفاية عشان
    نفس التخطيط يترسم تاني من غير ما المنصة تتكلّم - هو نفس صيغة
    "أو ارسم تخطيط من الملف ده".
    """
    try:
        folder = folder or "."
        path = os.path.join(folder, f"{stem}_AutoPT_ai_layout.json")
        k = 2
        while os.path.isfile(path):
            path = os.path.join(folder, f"{stem}_AutoPT_ai_layout-{k}.json")
            k += 1
        out = {
            "when": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "version": APP_VERSION,
            "model": str(getattr(params, "ai_model", "")
                         or AI_MODEL_DEFAULT),
            "brief_version": brief.get("brief_version"),
            "units": "m/mm",
            "slab_thickness": (brief.get("slab") or {}).get("thickness_mm"),
            "brief_digest": brief_fingerprint(brief),
            "note": data.get("note") or "",
            "tendons": data.get("tendons") or [],
        }
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(out, fh, ensure_ascii=False, indent=1)
        if job:
            job.ok(f"The layout that came back is saved as "
                   f"{os.path.basename(path)}. It is the same format as a "
                   f"layout file you write yourself, so this exact design "
                   f"can be drawn again without asking the model anything - "
                   f"point 'Or draw a layout from this file' at it.")
        return path
    except Exception as e:
        if job:
            job.warn(f"The layout came back but was not saved ({e}).")
        return ""


def ai_layout_answer(brief, params, job=None, out_dir=None, stem=None,
                     verdict=None, layout=None, tag=""):
    """
    التخطيط كامل - نداء واحد للسقف الصغير، وواحد لكل اتجاه للكبير.

    **ليه التقسيم**: التفكير والتخطيط بياكلوا من نفس سقف التوكنز.
    رن حقيقي على 66 بحر مات عند 32 ألف بعد 7 دقايق من غير ما يرجّع
    حاجة. الاتجاه الواحد نص الطول، والاتجاه التاني بيشوف الأول
    فالحمل بيتقسّم بينهم مش بيتحسب مرتين.
    """
    bays = len((brief.get("bays") or {}).get("x") or []) + \
        len((brief.get("bays") or {}).get("y") or [])
    _at = getattr(params, "ai_split_bays", None)
    split_at = int(AI_SPLIT_BAYS if _at in (None, "") else _at)
    if split_at <= 0 or bays <= split_at:
        return ask_ai_for_layout(brief, params, job, out_dir=out_dir,
                                 stem=stem, verdict=verdict, layout=layout,
                                 tag=tag)

    if job:
        job.info(f"This floor has {bays} bays, over the {split_at} that fit "
                 f"in one answer, so each direction is asked for on its "
                 f"own. The thinking and the layout come out of the same "
                 f"token budget, and half a layout is no layout.")
    first = ask_ai_for_layout(brief, params, job, only="X",
                              out_dir=out_dir, stem=stem, verdict=verdict,
                              layout=layout, tag=tag)
    xs = [t for t in (first.get("tendons") or [])
          if str(t.get("dir") or "X").upper() != "Y"]
    #  **18.52: نصف التخطيط بيتحفظ قبل ما نخاطر بالنص التاني.** لو
    #  النداء التاني وقع، الأول اتدفع تمنه خلاص ومالوش لازمة يضيع معاه.
    if stem and xs:
        save_ai_layout({"tendons": xs, "note": first.get("note") or ""},
                       brief, params, out_dir or ".", f"{stem}_X", job)
    second = ask_ai_for_layout(brief, params, job, only="Y", already=xs,
                               out_dir=out_dir, stem=stem, verdict=verdict,
                               layout=layout, tag=tag)
    ys = [t for t in (second.get("tendons") or [])
          if str(t.get("dir") or "Y").upper() != "X"]
    notes = [str(first.get("note") or "").strip(),
             str(second.get("note") or "").strip()]
    return {"tendons": xs + ys,
            "note": "\n".join(n for n in notes if n)}


def layout_rank(row):
    """
    ترتيب تخطيطين: المخالفات الأول، وبعدين الحديد.

    المخالفة مش عيب شكلي - البندة تحت الحد بتتصلّح بالتنازل عن غطسة،
    والغطسة مقام عدد الاسترندات، فاللي بيوفّر حديد وهو مكسور قواعد
    بيدفعه تاني في الباس اللي بعده.
    """
    return (int(row.get("bends_under_min", 0))
            + int(row.get("pairs_too_close", 0))
            + max(int(row.get("on_a_beam_face", 0)), 0),
            float(row.get("kg_m2", 0.0) or 0.0))


def ai_best_of(site, params, job, brief, out_dir, stem, tries):
    """
    اسأل كذا مرة وخد الأحسن بالقياس.

    **18.71: الإجابة عيّنة مش قرار.** رنّتين على نفس السقف بنفس
    الموديل ونفس الإعدادات رجّعوا 245 و311 استرند - **27% فرق** من
    غير ما حاجة تتغيّر. التباين ده أكبر من أغلب اللي الإعدادات
    بتعمله، والرد عليه هو نفس مبدأ البرنامج: قِس واختار.
    """
    best, best_key, rows = None, None, []
    for i in range(max(int(tries), 1)):
        if job and tries > 1:
            job.log(f"Try {i + 1} of {tries}", "head")
        try:
            data = ai_layout_answer(brief, params, job, out_dir,
                                    f"{stem}_try{i + 1}" if tries > 1
                                    else stem)
        except CancelledError:
            raise
        except Exception as e:
            if job:
                job.warn(f"    try {i + 1} did not come back ({e}).")
            if best is not None:
                break               # عندنا واحد كويس، مانرميهوش
            raise
        tend = tendons_from_layout_data(data, params, None)
        row = layout_scorecard(site, params, tend, None) if tend else {}
        row["try"] = i + 1
        rows.append(row)
        key = layout_rank(row) if tend else (10 ** 9, 10 ** 9)
        if job and tries > 1:
            job.ok(f"    try {i + 1}: {row.get('tendons', 0)} tendon(s), "
                   f"{row.get('strands', 0)} strands, "
                   f"{row.get('kg_m2', 0):.2f} kg/m2, "
                   f"{key[0]} rule(s) broken.")
        if best_key is None or key < best_key:
            best, best_key = data, key
    if job and len(rows) > 1:
        kgs = [r.get("kg_m2", 0) for r in rows if r]
        job.info(f"    the same floor, the same service, {len(rows)} times: "
                 f"{min(kgs):.2f} to {max(kgs):.2f} kg/m2. The answer is a "
                 f"sample, not a decision - which is why more than one is "
                 f"asked for and the best is kept, by rules broken first "
                 f"and steel second.")
    return best


def ai_tendon_layout(site, params, job=None, out_dir=None, stem=None):
    """
    الدور -> المنصة -> كابلات بصيغة البرنامج. بيرمي RuntimeError لو وقع.
    """
    ai_spend_reset()
    brief = floor_brief(site, params, job)
    data = None
    if bool(getattr(params, "ai_reuse_saved", True)):
        data, _path = ai_saved_layout(brief, out_dir or ".",
                                      stem or "floor", job)
    if data is None:
        data = ai_best_of(site, params, job, brief, out_dir or ".",
                          stem or "floor",
                          int(getattr(params, "ai_tries", 1) or 1))
    #  **18.71: من غير اسم للدور مافيش ملف.** الحفظ المفيد هو اللي
    #  جنب الرسمة وباسمها؛ الحفظ في مجلد الشغل الحالي باسم "floor"
    #  بيكوّم ملفات مالهاش صاحب.
    if stem:
        save_ai_layout(data, brief, params, out_dir or ".", stem, job)
    tend = tendons_from_layout_data(data, params, job)
    note = str(data.get("note") or "").strip()
    if note and job:
        job.info("    why it was laid out this way, in the model's own "
                 "words:")
        for line in note.splitlines():
            if line.strip():
                job.info(f"        {line.strip()}")
    if job and _AI_SPEND["calls"]:
        job.info(f"    this layout cost about ${_AI_SPEND['usd']:.2f} in "
                 f"{_AI_SPEND['calls']} call(s) - {_AI_SPEND['in']:,} tokens "
                 f"in and {_AI_SPEND['out']:,} out, at the rates on the "
                 f"settings page. It is saved: drawing it again costs "
                 f"nothing.")
    if not tend:
        raise RuntimeError("the layout that came back holds no usable "
                           "tendon")
    return tend


def ai_revised_tendons(site, params, job, tendons, plots, out_dir=None,
                       stem=None, rnd=0):
    """
    **حلقة رام: الحكم بيرجع للموديل.**

    الدورة كانت بتقف عند «رام بيحكم»، والحكم بيروح للمهندس. هنا بيروح
    للموديل ومعاه التخطيط زي ما اتبنى فعلاً، وبيرجع تخطيط معدّل - وبعدين
    نفس القواعد ونفس رام تاني.

    بترجّع كابلات جديدة، أو None لو مافيش قطاع فوق الحد أو لو الحاجة
    وقعت (الرن بيكمّل بتخطيطه الحالي - ده تحسين، مش شرط).
    """
    try:
        verdict = ai_verdict(plots, params)
        if not verdict.get("over_the_limit"):
            if job:
                job.info("    nothing is over the limit, so there is nothing "
                         "to send back to the model.")
            return None
        if job:
            w = (verdict.get("worst_first") or [{}])[0]
            job.log("Back to the model with RAM's answer", "head")
            job.info(f"{verdict['over_the_limit']} reading(s) over the limit, "
                     f"the worst at u = {w.get('u', 0)} on the "
                     f"{w.get('face', '?')} face at "
                     f"{w.get('at', ['?', '?'])}. What goes out is the "
                     f"layout RAM actually analysed - cut, moved and eased "
                     f"by the rules - not the one the model last sent, and "
                     f"the readings that failed with it.")
        brief = floor_brief(site, params, None)
        built = layout_from_tendons(tendons, params)
        data = ai_layout_answer(brief, params, job, out_dir, stem,
                                verdict=verdict, layout=built,
                                tag=f"r{int(rnd)}")
        out = tendons_from_layout_data(data, params, job)
        if not out:
            if job:
                job.warn("    the revision held no usable tendon, so this "
                         "round keeps the layout it has.")
            return None
        if stem:
            save_ai_layout(data, brief, params, out_dir or ".",
                           f"{stem}_r{int(rnd)}", job)
        note = str(data.get("note") or "").strip()
        if note and job:
            job.info("    what it changed, in its own words:")
            for line in note.splitlines():
                if line.strip():
                    job.info(f"        {line.strip()}")
        if job:
            job.ok(f"The revision has {len(out)} tendon(s) and "
                   f"{sum(t['strands'] for t in out)} strands, against "
                   f"{len(tendons)} and "
                   f"{sum(int(t.get('strands') or 0) for t in tendons)} "
                   f"before it. Every plan and profile rule runs on it "
                   f"again, and the next round is RAM's answer to it.")
        return out
    except CancelledError:
        raise
    except Exception as e:
        if job:
            job.warn(f"The revision did not come back ({e}). The round "
                     f"carries on with the layout it has - the loop is a "
                     f"way to improve the design, not a thing it depends "
                     f"on.")
        return None


# ---------------------------------------------------------------------------
#  منافسة: نفس السقف على أكتر من منصة، والنتيجة بأرقام
# ---------------------------------------------------------------------------
#  السؤال "مين أحسن؟" مالوش إجابة بالكلام. الأرقام اللي تحت كلها
#  بتتقاس من غير رام، فالمقارنة بتخلص في دقايق وبتكلّف نداء لكل منصة:
#  الحديد، والمخالفات اللي القواعد اضطرت تصلّحها، والغطسة اللي التخطيط
#  عرف يجيبها. **ورام بيفضل هو الحَكَم على اللي هيكسب.**


def layout_scorecard(site, params, tendons, job=None):
    """
    كشف حساب لتخطيط واحد، من غير رام: الحديد والمخالفات والغطسة.

    بيتقاس **على التخطيط زي ما جه** - قبل ما القواعد تصلّحه - لأن
    المخالفة اللي القاعدة صلّحتها هي نفسها قياس لجودة التخطيط: كل
    بندة تحت الحد بتتصلّح بغطسة أقل، وكل كابل بيتزحلق بيسيب عموده.
    """
    import copy
    ts = copy.deepcopy(tendons)
    area = slab_area_m2(site) or 0.0
    r = float(getattr(params, "ram_inflection_ratio", 0.2) or 0.2)
    rmin = float(getattr(params, "min_tendon_radius", 3.0) or 3.0)
    tight = 0
    for t in ts:
        pr = t.get("profile") or []
        for a, c in zip(pr, pr[1:]):
            L = dist(a["pos"], c["pos"])
            d = abs(float(a["depth"]) - float(c["depth"])) / 1000.0
            if L < 1e-6 or d < 1e-9:
                continue
            if (r / 2.0) * L * L / d < rmin:
                tight += 1
    gap = float(getattr(params, "min_clear_spacing", 0.40) or 0.40)
    close = 0
    for i, t in enumerate(ts):
        for u in ts[i + 1:]:
            if t.get("dir") != u.get("dir"):
                continue
            g = abs(float(t.get("coord") or 0.0) - float(u.get("coord")
                                                         or 0.0))
            if 1e-6 < g < gap:
                close += 1
    try:
        beams = len(beam_clearance_breaches(ts, params, site))
    except Exception:
        beams = -1
    kg = floor_strand_kg(ts, params)
    row = {
        "tendons": len(ts),
        "strands": sum(int(t.get("strands") or 0) for t in ts),
        "kg": round(kg, 0),
        "kg_m2": round(kg / area, 2) if area else 0.0,
        "bends_under_min": tight,
        "pairs_too_close": close,
        "on_a_beam_face": beams,
        "points": sum(len(t.get("profile") or []) for t in ts),
    }
    #  والقواعد بتعدّي بعدين، والفرق بينهم هو تمن اللي كان غلط
    try:
        enforce_plan_rules(ts, params, None, site)
        ts = [t for t in ts if not t.get("_deleted")]
        row["after_rules_tendons"] = len(ts)
        row["after_rules_kg_m2"] = (round(floor_strand_kg(ts, params) / area,
                                          2) if area else 0.0)
    except Exception:
        pass
    return row


def compare_ai_layouts(site, params, job, entries, out_dir=None, stem=None):
    """
    نفس السقف على كذا منصة، ونتيجة كل واحدة في صف.

    `entries`: [{"label", "provider", "model", "base_url"?}]. بترجّع
    [{"label", ..., "score"/"error"}] وبتطبع الجدول.
    """
    import copy
    out = []
    for e in (entries or []):
        label = str(e.get("label") or e.get("model") or "?")
        p = copy.copy(params)
        p.ai_provider = str(e.get("provider") or "anthropic")
        p.ai_model = str(e.get("model") or "")
        if e.get("base_url") is not None:
            p.ai_base_url = str(e.get("base_url") or "")
        if e.get("key_file"):
            p.ai_key_file = str(e["key_file"])
        elif p.ai_provider != getattr(params, "ai_provider", "anthropic"):
            #  صف على خدمة تانية من غير مفتاح خاص بيه مايورّثش مفتاح
            #  الخدمة اللي في الإعدادات.
            p.ai_key_file = ""
        p.ai_layout = True
        if job:
            job.log(f"Asking {label}", "head")
        t0 = time.time()
        try:
            ts = ai_tendon_layout(site, p, job, out_dir,
                                  f"{stem or 'floor'}_{_safe_tag(label)}")
            row = layout_scorecard(site, p, ts, job)
            row.update({"label": label, "seconds": round(time.time() - t0),
                        "model": p.ai_model, "provider": p.ai_provider})
            out.append(row)
        except CancelledError:
            raise
        except Exception as ex:
            if job:
                job.warn(f"{label} did not produce a layout: {ex}")
            out.append({"label": label, "model": p.ai_model,
                        "provider": p.ai_provider, "error": str(ex),
                        "seconds": round(time.time() - t0)})
    if job:
        report_comparison(out, job)
    return out


#  **18.66: اسم الخدمة بدل عنوانها.** صف المقارنة كان لازم يتكتب فيه
#  عنوان كامل بالحرف - وأي حرف ناقص = 404 غامض. الأسامي دي بتحط
#  العنوان، والباقي اسم موديل وملف مفتاح وبس.
#  **18.76: اختيار الخدمة من الشاشة الأولى.** الإعدادات الكاملة في
#  صفحة الـ AI؛ اللي بيتغيّر من مشروع لمشروع هو «مين هيرسم» - وده
#  بيتحط جنب السؤال اللي بيقول «بالـ AI»، مش في صفحة تانية.
AI_PICKS = {
    "Claude (Anthropic)": "claude",
    "Gemini (Google)": "gemini",
    "OpenAI": "openai",
    "OpenRouter": "openrouter",
    "DeepSeek": "deepseek",
    "On this machine (Ollama)": "ollama",
    "Whatever the AI page is set to": "",
}

AI_SERVICES = {
    "claude":     ("anthropic", AI_MODEL_DEFAULT, ""),
    "anthropic":  ("anthropic", AI_MODEL_DEFAULT, ""),
    "gemini":     ("openai", "",
                   "https://generativelanguage.googleapis.com/v1beta/openai"),
    "google":     ("openai", "",
                   "https://generativelanguage.googleapis.com/v1beta/openai"),
    "openrouter": ("openai", "", "https://openrouter.ai/api/v1"),
    "deepseek":   ("openai", "", "https://api.deepseek.com/v1"),
    "openai":     ("openai", "", "https://api.openai.com/v1"),
    "ollama":     ("local", "", AI_LOCAL_BASE),
    "local":      ("local", "", AI_LOCAL_BASE),
}


def bakeoff_entries(v):
    """
    صفوف المقارنة من الإعدادات: كل صف "منصة | موديل | عنوان".

    الصف الفاضي بيتساب. الصف اللي فيه موديل بس بيتحسب على الباب
    المدمج - عشان مقارنة موديلين من نفس المنصة تبقى سطر واحد.
    """
    out = []
    for k in ("bakeoff_a", "bakeoff_b", "bakeoff_c"):
        raw = ""
        try:
            raw = str(v[k].get() or "").strip()
        except Exception:
            continue
        if not raw:
            continue
        bits = [q.strip() for q in raw.split("|")]
        head = (bits[0] or "").lower()
        #  "openai" و"local" اسم خدمة واسم باب في نفس الوقت. اللي
        #  بيفصل: عنوان في الخانة التالتة يعني الشكل الطويل.
        _long = len(bits) > 2 and bits[2].lower().startswith("http")
        if head in AI_SERVICES and not _long:
            #  الشكل القصير: اسم الخدمة | الموديل | ملف المفتاح
            prov, model, url = AI_SERVICES[head]
            if len(bits) > 1 and bits[1]:
                model = bits[1]
            keyfile = bits[2] if len(bits) > 2 else ""
            if len(bits) > 3 and bits[3]:
                url = bits[3]              # عنوان مخصوص لو حبيت
            if not model:
                continue                   # خدمة من غير موديل مش صف
            out.append({"label": f"{head}:{model}" if prov != "anthropic"
                        else model, "provider": prov, "model": model,
                        "base_url": url, "key_file": keyfile})
            continue
        prov = (bits[0] or "anthropic") if len(bits) > 1 else "anthropic"
        model = bits[1] if len(bits) > 1 else bits[0]
        url = bits[2] if len(bits) > 2 else ""
        #  **18.65: ومفتاح لكل صف.** من غيره المقارنة مستحيلة: خدمتين
        #  في رن واحد ومفتاح واحد معناه إن واحدة منهم بتاخد مفتاح
        #  التانية - وده اللي حصل فعلاً.
        keyfile = bits[3] if len(bits) > 3 else ""
        if not model:
            continue
        out.append({"label": f"{prov}:{model}" if prov != "anthropic"
                    else model, "provider": prov, "model": model,
                    "base_url": url, "key_file": keyfile})
    return out


def _safe_tag(text):
    return "".join(c if (c.isalnum() or c in "-_") else "-"
                   for c in str(text))[:40]


def report_comparison(rows, job):
    """الجدول، وقراءة له بلسان مهندس."""
    good = [r for r in rows if not r.get("error")]
    job.log("Side by side", "head")
    if not good:
        job.warn("No service produced a layout to compare.")
        return
    job.info(f"{'service':<22}{'kg/m2':>8}{'tendons':>9}{'strands':>9}"
             f"{'bends<R':>9}{'too close':>11}{'on a beam':>11}{'sec':>6}")
    for r in sorted(good, key=lambda z: z.get("kg_m2") or 0):
        job.info(f"{str(r['label'])[:21]:<22}{r.get('kg_m2', 0):>8.2f}"
                 f"{r.get('tendons', 0):>9}{r.get('strands', 0):>9}"
                 f"{r.get('bends_under_min', 0):>9}"
                 f"{r.get('pairs_too_close', 0):>11}"
                 f"{r.get('on_a_beam_face', 0):>11}"
                 f"{r.get('seconds', 0):>6}")
    for r in rows:
        if r.get("error"):
            job.warn(f"{r['label']}: {r['error'][:160]}")
    best = min(good, key=lambda z: z.get("kg_m2") or 1e9)
    clean = min(good, key=lambda z: (z.get("bends_under_min", 0)
                                     + z.get("pairs_too_close", 0)
                                     + max(z.get("on_a_beam_face", 0), 0)))
    job.info(f"    lightest: {best['label']} at {best.get('kg_m2', 0):.2f} "
             f"kg/m2. Fewest rules broken: {clean['label']}. They are not "
             f"the same question: steel is what the floor costs, and the "
             f"broken rules are what the layout did not know - a bend under "
             f"the minimum is fixed by giving drape away, which is paid for "
             f"in steel on the next pass anyway.")
    job.info("    none of this is the analysis. RAM decides which of these "
             "floors stands, and a layout that is lighter here can be the "
             "one that fails a section. Take the two best and run them "
             "through a mode that opens RAM.")


def external_tendons(site, params, job=None, out_dir=None, stem=None):
    """
    الكابلات الجاية من بره المحرّك - أو None يعني المحرّك يصمّم.

    ترتيب واحد لكل الأوضاع: المنصة، ثم تخطيط الأكواد، ثم ملف تخطيط
    جاهز. كان الترتيب ده موجود في مسار رام وبس، فوضع الرسم كان
    بيتجاهل الاتنين ويصمّم بالمحرّك من غير ما يقول.
    """
    #  **18.70: الملف اللي وديته بإيدك يسبق النداء.** الترتيب كان
    #  المنصة الأول، فالمهندس حط مسار تخطيط محفوظ والبرنامج راح
    #  ينده على المنصة ويدفع تاني ويتجاهل الملف. المسار ده تعليمة
    #  صريحة، والنداء فلوس ووقت - والصريح المجاني يسبق.
    path = str(getattr(params, "tendon_layout_file", "") or "").strip()
    if path:
        if job and bool(getattr(params, "ai_layout", False)):
            job.info(f"'Or draw a layout from this file instead' points at "
                     f"{os.path.basename(path)}, so no service is asked and "
                     f"nothing is spent. Clear that box to have the floor "
                     f"sent out again.")
        return tendons_from_layout(path, params, job)
    if bool(getattr(params, "ai_layout", False)):
        return ai_tendon_layout(site, params, job, out_dir, stem)
    if bool(getattr(params, "code_layout", False)):
        return code_based_layout(site, params, job)
    return None


def preliminary_sizing(site, params, codes=("ACI", "EC2", "ECP"),
                       thicknesses=None, prices=None, job=None):
    """
    السُمك والدروبات، مقرَّرين من شبكة الأعمدة وقواعد الكود ومتسعّرين.

    الطريقة: لكل سُمك مرشّح، كل كود بيتسأل سؤالين - البحر/السُمك
    بيعدّي؟ وكل عمود بيعدّي في الثقب بأصغر دروب؟ - والحل اللي بيعدّي
    عند **كل** الأكواد المطلوبة بيتسعّر. الأرخص هو المقترح، والباقي
    بيتعرض معاه عشان نقطة التعادل تبان.

    بترجّع {"floor": ..., "options": [...], "best": ...}.
    """
    grid = floor_grid(site)
    on_beams, why_beams = beams_are_downstand(site, params)
    spans = grid_spans(site, beams=on_beams)
    boundary = site.get("boundary") or []
    area = slab_area_m2(site)
    cols = list(site.get("columns") or [])
    all_sp = list(spans.get("x") or []) + list(spans.get("y") or [])
    span, odd, med = governing_span(
        all_sp, float(getattr(params, "prelim_outlier", 1.6) or 1.6))
    span_max = max(all_sp) if all_sp else 0.0
    floor = {"area_m2": area, "columns": len(cols),
             "spans_x": sorted(spans.get("x") or []),
             "spans_y": sorted(spans.get("y") or []),
             "max_span": span, "longest": span_max, "median": med,
             "outliers": odd, "grid": grid,
             "on_beams": on_beams, "why_beams": why_beams,
             "beams": len(site.get("beams") or [])}
    if not cols or span <= 0:
        if job:
            job.warn("No column grid could be read, so no thickness can be "
                     "proposed. Check the layer roles.")
        return {"floor": floor, "options": [], "best": None}

    if thicknesses is None:
        lo = min(min_thickness(span, c, True, params.live_load, params.sdl,
                               on_beams=on_beams) for c in codes)
        #  **الحد الأدنى بقى فيزيا مش رقم.** أول نسخة كانت بتقص عند 160
        #  مم، فرن على سقف بحوره قصيرة اقترح 160 بالظبط - يعني أرفع
        #  حاجة اتجرّبت، مش الأنسب. الحد دلوقتي هو أول سُمك فيه غطسة
        #  تستاهل (30 مم)، والباقي بيترفض بفحص الـ P/A تحت.
        thicknesses = [round((lo + k * 20.0) / 10.0) * 10.0
                       for k in range(-4, 9)]
        thicknesses = [t for t in thicknesses if prelim_drape_mm(t, params)
                       >= PRELIM_MIN_DRAPE]

    out = []
    for h in thicknesses:
        #  الضغط المتوسط المفترض في الابتدائي - الحد الأدنى الكودي.
        #  بيدخل في مقاومة الثقب، ودي حاجة بتتنسى وبتطلّع دروبات
        #  مش محتاجينها.
        fpc = PA_MIN
        opt = {"h_mm": h, "codes": {}, "ok": True, "drops": []}
        for code in codes:
            need = min_thickness(span, code, True, params.live_load,
                                 params.sdl, on_beams=on_beams)
            need_flat = min_thickness(span, code, False, params.live_load,
                                      params.sdl, on_beams=on_beams)
            opt["codes"][code] = {"span_depth_mm": need,
                                  "span_depth_flat_mm": need_flat,
                                  "span_depth_ok": h >= need - 1e-6}
        #  الثقب: أسوأ كود على كل عمود
        drops, worst, failed = [], 0.0, []
        framed = _columns_framed_by_beams(site) if on_beams else set()
        for col in cols:
            if (round(col["center"][0], 2), round(col["center"][1], 2)) \
                    in framed:
                #  الكمرات داخلة في العمود ده: الحمل بيوصله على خطوط،
                #  والمشكلة قص كمرة مش ثقب بلاطة. دروب هنا خرسانة
                #  وشدّة مدفوعة على مشكلة مش موجودة.
                continue
            best = None
            for code in codes:
                r = size_drop_for(col, grid, boundary, h, params, code, span,
                                  fpc=fpc)
                if r is None:
                    best = None
                    failed.append((col["center"], code))
                    break
                if best is None or (r["size_m"], r["h_mm"]) > (best["size_m"],
                                                               best["h_mm"]):
                    best = r
            if best is None:
                continue
            worst = max(worst, best["u"])
            if best["size_m"] > 0:
                drops.append({"at": tuple(col["center"]),
                              "size_m": best["size_m"], "h_mm": best["h_mm"],
                              "u": best["u"],
                              "counts_for_moment": best.get(
                                  "counts_for_moment", False)})
        opt["drops"] = drops
        opt["n_drops"] = len(drops)
        opt["punching_failed"] = failed
        opt["worst_u"] = worst
        opt["span_depth_ok"] = all(c["span_depth_ok"]
                                   for c in opt["codes"].values())
        pa, drape, w_bal = prelim_pa(span, h, params)
        opt["pa"] = pa
        opt["drape_mm"] = drape
        opt["w_bal"] = w_bal
        opt["pa_ok"] = pa is not None and pa <= PA_MAX
        opt["ok"] = opt["span_depth_ok"] and opt["pa_ok"] and not failed
        opt["cost"] = option_cost(area, h, drops, prices)
        out.append(opt)

    ok = [o for o in out if o["ok"]]
    best = None
    if ok:
        cheap = min(o["cost"]["total"] for o in ok)
        #  **التكلفة مش الحكم الوحيد لما الفرق بسيط.** في رن المهندس
        #  160 و180 بينهم 3% في التكلفة، و160 كانت على ثقب 1.00 بالظبط
        #  وعايزة ضعف الدروبات. فرق 3% مش سبب تاخد حل بلا احتياطي.
        band = [o for o in ok
                if o["cost"]["total"] <= cheap * (1.0 + PRELIM_COST_TIE)]
        best = min(band, key=lambda o: (round(o["worst_u"], 2), o["n_drops"],
                                        o["cost"]["total"]))
    return {"floor": floor, "options": out, "best": best,
            "tried": sorted(thicknesses)}


def preliminary_report(res, params, job, codes=("ACI", "EC2", "ECP"),
                       site=None):
    """
    التقرير: السُمك المقترح ودروباته، والحلول التانية بتكلفتها، **وكل
    افتراض ممكن يقلب النتيجة**.

    السطر الأخير مقصود: ده تصميم ابتدائي بيختار من إيه يتبني الموديل،
    ورام هو اللي بيعتمد. الفرق ده لو ضاع يبقى الرقم ده اتقرا كأنه
    تصميم معتمد وهو مش كده.
    """
    f = res.get("floor") or {}
    opts = res.get("options") or []
    best = res.get("best")
    job.log("Preliminary sizing - thickness and drops", "head")
    sx = f.get("spans_x") or []
    sy = f.get("spans_y") or []
    allsp = sorted(sx + sy)
    if not allsp:
        job.warn("No bays could be measured, so nothing is proposed.")
        return
    med = allsp[len(allsp) // 2]
    job.info(f"{f.get('area_m2', 0):,.0f} m2, {f.get('columns', 0)} column(s), "
             f"{len(allsp)} bay(s): median {med:.2f} m, longest "
             f"{allsp[-1]:.2f} m, sized for "
             f"{f.get('max_span') or allsp[-1]:.2f} m.")
    job.info(f"    walls count as supports for the bays and not as grid "
             f"lines - a core standing in the middle of a bay halves it, "
             f"and measuring the grid without it invents spans nobody built.")
    if f.get("on_beams"):
        job.warn(f"**This is a beam-and-slab floor, not a flat slab** - "
                 f"{f.get('why_beams') or 'the beams are downstand'}. The "
                 f"bays above are measured to the beams, because that is "
                 f"what the slab spans between, and the thickness below uses "
                 f"the slab-on-beams ratios rather than the flat-slab ones. "
                 f"A column with beams framing into it is not offered a drop "
                 f"panel either: the load reaches it along lines, so the "
                 f"question there is beam shear, not punching.")
        job.warn(f"    **and the {f.get('beams', 0)} beam(s) are not sized "
                 f"here.** This proposes the slab. On a floor like this the "
                 f"prestress usually belongs in the beams, and their depth "
                 f"comes from their own span over depth - which is a "
                 f"different calculation from anything above. Size them "
                 f"first: the slab thickness below is right only once the "
                 f"beam grid it spans between is settled.")
    elif f.get("beams"):
        job.info(f"    the {f.get('beams', 0)} beam(s) in the drawing are "
                 f"taken as flush with the slab ({f.get('why_beams')}), so "
                 f"the floor is sized as a flat slab. If they are downstand, "
                 f"say so on the geometry page - it changes what the slab "
                 f"spans between and the answer with it.")
    odd = f.get("outliers") or []
    gov = f.get("max_span") or allsp[-1]
    if odd:
        job.warn(f"**{len(odd)} bay(s) are longer than "
                 f"{float(getattr(params, 'prelim_outlier', 1.6) or 1.6):.1f}x "
                 f"the median and are left out of the sizing** - the longest "
                 f"is {max(odd):.2f} m against a median of {med:.2f}. The "
                 f"floor below is sized for {gov:.2f} m. Carrying the "
                 f"longest across {f.get('area_m2', 0):,.0f} m2 is what "
                 f"turns a sensible slab into a silly one.")
        job.warn(f"    **look at those bays before you use this.** A bay "
                 f"several times the median is usually a support the drawing "
                 f"did not give up - a column on a layer of its own, a "
                 f"column rejected when the file was read, a beam that stops "
                 f"short - and only sometimes a real one. Where it is real "
                 f"it wants a beam or a local deepening there, not a thicker "
                 f"floor everywhere:")
        for v in sorted(odd, reverse=True)[:6]:
            job.warn(f"        {v:.2f} m")
        deep = max((min_thickness(max(odd), c, True, params.live_load,
                                  params.sdl, on_beams=f.get("on_beams"))
                    for c in codes), default=0.0)
        job.info(f"    for the record: carrying {max(odd):.2f} m across the "
                 f"whole floor would want about {deep:.0f} mm on span/depth "
                 f"alone, before the precompression is even looked at.")
    elif allsp[-1] > 1.35 * med:
        job.warn(f"    the longest bay is {allsp[-1] / med:.2f}x the median. "
                 f"Everything below sizes the whole floor for it. A band "
                 f"beam or a deeper drop over that bay alone is usually "
                 f"cheaper than carrying its thickness across "
                 f"{f.get('area_m2', 0):,.0f} m2 - worth pricing before you "
                 f"take the figure below.")
    for o in opts:
        flags = []
        for c in codes:
            cc = (o.get("codes") or {}).get(c) or {}
            flags.append(f"{c} {'ok' if cc.get('span_depth_ok') else 'thin'}")
        why = []
        if not o["span_depth_ok"]:
            why.append("too thin for the span")
        if not o.get("pa_ok"):
            why.append("no drape" if o.get("pa") is None
                       else f"P/A {o['pa']:.2f} over {PA_MAX:.2f}")
        if o["punching_failed"]:
            why.append(f"{len(o['punching_failed'])} column(s) punch")
        job.info(f"    {o['h_mm']:.0f} mm: {', '.join(flags)} · drape "
                 f"{o['drape_mm']:.0f} mm · P/A "
                 + ("-" if o.get("pa") is None else f"{o['pa']:.2f}")
                 + f" · {o['n_drops']} drop(s) · worst punching "
                 f"{o['worst_u']:.2f} · {o['cost']['concrete_m3']:,.0f} m3 · "
                 f"{o['cost']['per_m2']:,.0f} per m2"
                 + ("" if o["ok"] else "  [no: " + "; ".join(why) + "]"))
    if best is None:
        job.warn("No thickness tried satisfies every code and every column. "
                 "Either the grid needs a band beam, or shear reinforcement "
                 "has to do what a drop cannot.")
        return
    tried = res.get("tried") or []
    job.ok(f"Proposed: {best['h_mm']:.0f} mm slab with {best['n_drops']} drop "
           f"panel(s), {best['cost']['per_m2']:,.0f} per m2, drape "
           f"{best['drape_mm']:.0f} mm, P/A "
           + ("-" if best.get("pa") is None else f"{best['pa']:.2f}")
           + f" MPa. Of the options passing {', '.join(codes)} on span/depth, "
           f"every column on punching, and a workable precompression, it is "
           f"the cheapest - or, where two are within "
           f"{PRELIM_COST_TIE * 100:.0f}% of each other on cost, the one with "
           f"more punching reserve. That tie-break matters: a few per cent of "
           f"concrete is not worth a floor sitting at a utilisation of 1.00.")
    if tried and best["h_mm"] in (min(tried), max(tried)):
        job.warn(f"    it sits at the {'thin' if best['h_mm'] == min(tried) else 'thick'} "
                 f"end of the range tried ({min(tried):.0f}-{max(tried):.0f} "
                 f"mm), so read it as the best of what was offered rather "
                 f"than a turning point. The range is set by the drape: under "
                 f"{PRELIM_MIN_DRAPE:.0f} mm there is nothing for a tendon to "
                 f"work with.")

    sizes = {}
    for d in best["drops"]:
        k = (d["size_m"], d["h_mm"])
        sizes[k] = sizes.get(k, 0) + 1
    for (side, hh), n in sorted(sizes.items()):
        job.info(f"    {n} x {side:.1f} m square, {hh:.0f} mm deep")
    thin = [d for d in best["drops"] if not d.get("counts_for_moment")]
    if thin:
        job.info(f"    {len(thin)} of them are sized for punching only - they "
                 f"are narrower than the span/6 a drop needs before it may "
                 f"be taken into the moments (ACI 318 8.2.4), so the strips "
                 f"still see a flat slab there.")
    job.info("    Assumptions that move these numbers most, in order: the "
             f"average precompression is taken at the code minimum "
             f"{PA_MIN:.2f} MPa, and prestress raises the punching capacity - "
             f"at the P/A this floor will really carry, fewer drops are "
             f"needed; shear reinforcement is not considered at all, and "
             f"studs are often cheaper than a drop; and the concrete is "
             f"taken at 30 MPa.")
    job.info("    This chooses what the model is built from. RAM still "
             "decides whether it stands.")


# ==============================================================================
#  تخطيط حزم وموزّع، من الأكواد - من غير محرّك التصميم
# ==============================================================================
#  ده التخطيط اللي مصمّم بيرسمه بإيده: حزم فوق محاور الأعمدة في اتجاه،
#  وكابلات موزّعة بتباعد ثابت في الاتجاه التاني، والمقاسات من موازنة
#  الأحمال على البحر **بتاع كل حزمة**.
#
#  المراجع:
#    ACI 318-19 §8.7.2.3   أقصى تباعد للموزّع: 8h أو 1.5 م
#                §8.7.5.6.1 كابلين على الأقل يمرّوا في كل عمود
#                §8.6.2.1  أقل ضغط متوسط 0.86 MPa
#    TR43 §5.8             الحمل الموازن 60-80% من الحمل الميت
#    PTI DC20.9            ترتيب الحزم/الموزّع
#
#  الفرق عن `PTEngine`: المحرّك بيبني تخطيط منتظم بتباعد واحد في
#  الاتجاهين وبيحسب لكل كابل على بحوره. اللي هنا بيفصل الدورين -
#  الموزّع بيوصّل للحزمة، والحزمة بتوصّل للعمود - وده اللي بيخلّي
#  الحديد يتركّز فين ما هو نافع. الاتنين بيعدّوا على نفس قواعد المسقط
#  والبروفايل بعد كده، ورام هو الحكم للاتنين.

BAND_PITCH_DEFAULT = 0.30       # تباعد كابلات الحزمة، م


def _drape_m(params):
    """الغطسة المتاحة: من القمة عند الغطاء العلوي للغطسة عند السفلي."""
    h = float(getattr(params, "slab_thickness", 250.0) or 250.0)
    top = float(getattr(params, "top_cover", 40.0) or 40.0)
    bot = float(getattr(params, "bot_cover", 40.0) or 40.0)
    half = float(getattr(params, "half_duct", 12.0) or 12.0)
    z_hi = top + half
    z_lo = h - bot - half
    return max(z_lo - z_hi, 1.0) / 1000.0, z_hi, z_lo, h


def balanced_load(params):
    """kN/m² - نسبة من الحمل الميت، زي ما TR43 بيقول."""
    h = float(getattr(params, "slab_thickness", 250.0) or 250.0)
    sw = CONCRETE_DENSITY * h / 1000.0
    dl = sw + float(getattr(params, "sdl", 0.0) or 0.0)
    r = float(getattr(params, "code_balance_ratio", 0.65) or 0.65)
    return r * dl, dl, sw


def _n_strands(w_kpa, width_m, span_m, drape_m, pe_kn, end=False):
    """n = w·s·L² / (8·a·Pe)، والبحر الطرفي ×1.15."""
    if drape_m <= 0 or pe_kn <= 0:
        return 0.0
    n = w_kpa * width_m * span_m ** 2 / (8.0 * drape_m * pe_kn)
    return n * (1.15 if end else 1.0)


def _profile_points(a, b, sups, along_x, z_hi, z_lo, z_anch):
    """مرساة · قمة على كل ركيزة · غطسة في نص كل بحر · مرساة."""
    k = 0 if along_x else 1
    lo, hi = (a[k], b[k]) if a[k] <= b[k] else (b[k], a[k])
    inner = [s for s in sups if lo + 0.6 < s < hi - 0.6]
    out, prev = [(lo, z_anch)], lo
    for s in inner:
        out.append(((prev + s) / 2.0, z_lo))
        out.append((s, z_hi))
        prev = s
    out.append(((prev + hi) / 2.0, z_lo))
    out.append((hi, z_anch))
    fixed = a[1] if along_x else a[0]
    prof = []
    for v, z in out:
        pos = (v, fixed) if along_x else (fixed, v)
        prof.append({"pos": pos, "depth": z, "drop_idx": -1,
                     "high": abs(z - z_hi) < 1e-6,
                     "sag": abs(z - z_lo) < 1e-6})
    return prof


def _pieces(a, b, site, along_x, floor_len, edge=0.0):
    """
    قطع الخط اللي على خرسانة، مقصوصة عند الحدود والفتحات ومترجّعة
    `edge` من كل طرف، وأي قطعة أقصر من الحد بتتشال.

    **الخط بيتمدّ برّه البلاطة الأول.** `slice_line_by_slab` بتبني
    القطع **بين نقط التقاطع**، فالخط اللي بيبدأ وبينتهي جوّه الخرسانة
    مالوش تقاطع عند طرفيه - وأول نسخة كانت بتدّي خط جوّه السقف فيرجع
    سنتيمترات حوالين الفتحات وبس، وصفر كابل موزّع على سقف كامل.
    """
    k = 0 if along_x else 1
    lo, hi = (a, b) if a[k] <= b[k] else (b, a)
    far_lo = (lo[0] - 200.0, lo[1]) if along_x else (lo[0], lo[1] - 200.0)
    far_hi = (hi[0] + 200.0, hi[1]) if along_x else (hi[0], hi[1] + 200.0)
    try:
        segs = slice_line_by_slab(far_lo, far_hi, site.get("boundary") or [],
                                  site.get("openings") or [], along_x)
    except Exception:
        segs = [(lo, hi)]
    out = []
    for (s, e) in segs:
        s0, e0 = (s, e) if s[k] <= e[k] else (e, s)
        #  الحدود اللي المستخدم طلبها (أطراف الحزمة مثلاً) بتقصّ كمان
        p0 = max(s0[k] + edge, lo[k])
        p1 = min(e0[k] - edge, hi[k])
        if p1 - p0 < floor_len:
            continue
        out.append(((p0, s0[1]), (p1, e0[1])) if along_x
                   else ((s0[0], p0), (e0[0], p1)))
    return out


def _distributed_both_ways(site, params, spans, job=None):
    """
    كابلات موزّعة في الاتجاهين - من غير حزم.

    ده التخطيط اللي بيتعمل لما السقف بحوره متقاربة في الاتجاهين، أو
    لما التنفيذ عايز شبكة واحدة من غير تكويم عند الأعمدة: كل اتجاه
    بياخد تباعده وعدد استرنداته من بحوره هو، والحمل الموازن بيتقسم
    بينهم بنسبة صلابة البحرين - الاتجاه الأقصر بيشيل أكتر لأنه أقسى.

    القسمة `Lx⁴ / (Lx⁴ + Ly⁴)` هي قسمة الحمل على شريحتين متعامدتين
    بنفس الترخيم في النص - نفس اللي بيتعمل في البلاطة المصمتة ذات
    الاتجاهين، والأس أربعة جاي من `5wL⁴/384EI`.
    """
    drape, z_hi, z_lo, h = _drape_m(params)
    z_anch = float(getattr(params, "anchor_elevation", h / 2.0) or h / 2.0)
    pe = float(getattr(params, "force_per_strand", 110.0) or 110.0)
    w_bal, dl, sw = balanced_load(params)
    n_max = int(getattr(params, "max_strands", 5) or 5)
    n_min = int(getattr(params, "min_strands", 2) or 2)
    edge = float(getattr(params, "edge_offset", 0.30) or 0.30)
    floor_len = float(getattr(params, "min_tendon_length", 6.0) or 6.0)
    s_cap = min(8.0 * h / 1000.0, 1.5)
    s_use = min(float(getattr(params, "code_dist_spacing", 0.0) or 0.0)
                or s_cap, s_cap)

    on_beams, _w = beams_are_downstand(site, params)
    gov = {}
    for d in ("x", "y"):
        g, odd, med = governing_span(
            spans.get(d) or [],
            float(getattr(params, "prelim_outlier", 1.6) or 1.6))
        gov[d] = (g, odd, med)
    Lx, Ly = gov["x"][0], gov["y"][0]
    if Lx <= 0 or Ly <= 0:
        if job:
            job.error("One direction has no bay to size on.")
        return []
    #  نصيب كل اتجاه من الحمل الموازن
    share_x = Lx ** 4 / (Lx ** 4 + Ly ** 4)
    share = {"x": share_x, "y": 1.0 - share_x}

    bnd = site.get("boundary") or []
    xs = [p[0] for p in bnd] or [0.0]
    ys = [p[1] for p in bnd] or [0.0]
    lim = {"x": (min(xs), max(xs)), "y": (min(ys), max(ys))}
    if job:
        job.log("A distributed layout in both directions", "head")
        job.info(f"    self weight {sw:.2f} + SDL "
                 f"{float(getattr(params, 'sdl', 0.0) or 0.0):.2f} = "
                 f"{dl:.2f} kN/m2 dead · balancing "
                 f"{100.0 * w_bal / max(dl, 1e-9):.0f}% of it = {w_bal:.2f} "
                 f"kN/m2, split {share['x'] * 100:.0f}% to X and "
                 f"{share['y'] * 100:.0f}% to Y by L^4 - the stiffer "
                 f"direction takes more, which is the same split a two-way "
                 f"solid slab makes.")
        job.info(f"    governing bays: X {Lx:.2f} m, Y {Ly:.2f} m · spacing "
                 f"{s_use:.2f} m both ways (cap {s_cap:.2f}, ACI 318 "
                 f"8.7.2.3) · drape {drape * 1000:.0f} mm")

    out = []
    for d in ("x", "y"):
        along_x = (d == "x")
        L = gov[d][0]
        n = max(n_min, min(n_max, int(math.ceil(
            _n_strands(w_bal * share[d], s_use, L, drape, pe, end=True)
            - 1e-9))))
        o = "y" if along_x else "x"
        rows = support_rows(site, d)
        sup_all = sorted({round(c, 3) for row in rows
                          for c in row_supports(row, site, d,
                                                beams=on_beams)[0]})
        lo_o, hi_o = lim[o]
        v = lo_o + max(edge, 0.5)
        made = 0
        while v <= hi_o - max(edge, 0.5):
            a = (lim[d][0], v) if along_x else (v, lim[d][0])
            z = (lim[d][1], v) if along_x else (v, lim[d][1])
            for (p0, p1) in _pieces(a, z, site, along_x, floor_len, edge):
                out.append({"dir": d.upper(),
                            "profile": _profile_points(p0, p1, sup_all,
                                                       along_x, z_hi, z_lo,
                                                       z_anch),
                            "strands": n, "coord": v,
                            "length": dist(p0, p1), "from_code": True,
                            "role": "distributed", "spans": [],
                            "governing": {}})
                made += 1
            v += s_use
        if job:
            job.ok(f"    {made} tendon(s) in {d.upper()} at {n} strand(s), "
                   f"sized on a {L:.2f} m bay carrying "
                   f"{w_bal * share[d]:.2f} kN/m2")
            if gov[d][1]:
                job.warn(f"    {len(gov[d][1])} bay(s) in {d.upper()} are "
                         f"longer than the sizing bay (the longest "
                         f"{max(gov[d][1]):.2f} m) and want their own "
                         f"tendons or a beam - they are not carried by the "
                         f"count above.")
    enforce_min_precompression(out, site, params, job)
    if job:
        code_layout_checks(out, site, params, job)
    return out


def code_based_layout(site, params, job=None):
    """
    كابلات حزم + موزّع، جاهزة للرسم. بترجّع [tendon].

    الاتجاه: **الموزّع بياخد البحر الأقصر.** الحزمة أقوى، فبتاخد
    الطويل - ودي مش قاعدة جمالية: الموزّع منتشر، فكل متر بحر فيه
    بيتكلّف على عرض السقف كله.
    """
    drape, z_hi, z_lo, h = _drape_m(params)
    z_anch = float(getattr(params, "anchor_elevation", h / 2.0) or h / 2.0)
    pe = float(getattr(params, "force_per_strand", 110.0) or 110.0)
    w_bal, dl, sw = balanced_load(params)
    n_max = int(getattr(params, "max_strands", 5) or 5)
    n_min = int(getattr(params, "min_strands", 2) or 2)
    edge = float(getattr(params, "edge_offset", 0.30) or 0.30)
    floor_len = float(getattr(params, "min_tendon_length", 6.0) or 6.0)
    pitch = float(getattr(params, "band_pitch", BAND_PITCH_DEFAULT) or 0.30)
    #  ACI §8.7.2.3
    s_cap = min(8.0 * h / 1000.0, 1.5)
    s_dist = min(float(getattr(params, "code_dist_spacing", 0.0) or 0.0)
                 or s_cap, s_cap)

    on_beams, _why = beams_are_downstand(site, params)
    spans = grid_spans(site, beams=on_beams)
    if not spans.get("x") or not spans.get("y"):
        if job:
            job.error("No column grid could be read, so no layout can be "
                      "laid out.")
        return []
    style = str(getattr(params, "code_layout_style", "banded")
                or "banded").lower()
    if style.startswith("dist"):
        return _distributed_both_ways(site, params, spans, job)
    #  الحزم في الاتجاه اللي بحوره أطول
    band_x = max(spans["x"]) >= max(spans["y"])
    b_ax, d_ax = ("x", "y") if band_x else ("y", "x")
    rows = support_rows(site, b_ax)
    if not rows:
        return []
    bnd = site.get("boundary") or []
    xs = [p[0] for p in bnd] or [0.0]
    ys = [p[1] for p in bnd] or [0.0]
    lim = {"x": (min(xs), max(xs)), "y": (min(ys), max(ys))}
    k_b = 0 if band_x else 1        # المحور اللي الحزمة ماشية عليه
    k_d = 1 - k_b

    lines = []
    for row in rows:
        pts, coord = row_supports(row, site, b_ax)
        lines.append({"coord": coord, "sups": pts})
    lines.sort(key=lambda z: z["coord"])
    if job:
        job.log("A banded layout worked out from the codes", "head")
        job.info(f"    self weight {sw:.2f} + SDL "
                 f"{float(getattr(params, 'sdl', 0.0) or 0.0):.2f} = "
                 f"{dl:.2f} kN/m2 dead · balancing "
                 f"{100.0 * w_bal / max(dl, 1e-9):.0f}% of it = {w_bal:.2f} "
                 f"kN/m2 (TR43 5.8 asks for 60-80%)")
        job.info(f"    drape {drape * 1000:.0f} mm: peak {z_hi:.0f} mm below "
                 f"the top surface, dip {z_lo:.0f}, anchor {z_anch:.0f}")
        job.info(f"    bands run in {b_ax.upper()} (its bays reach "
                 f"{max(spans[b_ax]):.2f} m) and the distributed tendons in "
                 f"{d_ax.upper()} at {s_dist:.2f} m - the distributed "
                 f"direction takes the shorter bay, because every metre of "
                 f"its span is paid for across the whole floor. The cap is "
                 f"{s_cap:.2f} m (ACI 318 8.7.2.3: 8h or 1.5 m).")

    out = []
    # ---------------------------------------------------------- الموزّع
    d_spans = [z["coord"] for z in lines]
    worst = 0.0
    for i in range(len(d_spans) - 1):
        L = d_spans[i + 1] - d_spans[i]
        worst = max(worst, _n_strands(w_bal, s_dist, L, drape, pe,
                                      end=(i == 0 or i == len(d_spans) - 2)))
    n_dist = max(n_min, min(n_max, int(math.ceil(worst - 1e-9))))
    lo_d, hi_d = lim[d_ax]
    lo_b, hi_b = lim[b_ax]
    v = lo_b + max(edge, 0.5)
    made_d = 0
    while v <= hi_b - max(edge, 0.5):
        #  الموزّع ماشي في `d_ax`: إحداثيه الثابت هو `v` على محور الحزم
        a = (v, lo_d) if band_x else (lo_d, v)
        z = (v, hi_d) if band_x else (hi_d, v)
        for (s, e) in _pieces(a, z, site, not band_x, floor_len, edge):
            prof = _profile_points(s, e, d_spans, not band_x, z_hi, z_lo,
                                   z_anch)
            out.append({"dir": d_ax.upper(), "profile": prof,
                        "strands": n_dist, "coord": v,
                        "length": dist(s, e), "from_code": True,
                        "role": "distributed", "spans": [], "governing": {}})
            made_d += 1
        v += s_dist
    if job:
        job.ok(f"    {made_d} distributed tendon(s) at {n_dist} strand(s), "
               f"sized on the governing {max((d_spans[i+1]-d_spans[i]) for i in range(len(d_spans)-1)):.2f} m "
               f"bay between bands")

    # ------------------------------------------------------------ الحزم
    made_b = 0
    for j, ln in enumerate(lines):
        c = ln["coord"]
        lo = (c + lines[j - 1]["coord"]) / 2.0 if j > 0 else lim[d_ax][0]
        hi = (c + lines[j + 1]["coord"]) / 2.0 if j + 1 < len(lines) \
            else lim[d_ax][1]
        W = w_bal * (hi - lo)                 # kN/m على الحزمة
        sup = ln["sups"]
        bays = [(a, b, b - a) for a, b in zip(sup, sup[1:]) if b - a > 1.0]
        if not bays:
            continue
        med = sorted(z[2] for z in bays)[len(bays) // 2]
        n_base = W * med ** 2 / (8.0 * drape * pe)
        t_base = max(2, int(math.ceil(n_base / n_max)))     # ACI 8.7.5.6.1
        s_base = max(n_min, int(math.ceil(n_base / t_base)))
        got = t_base * s_base
        a0, a1 = min(sup), max(sup)
        for i in range(t_base):
            off = (i - (t_base - 1) / 2.0) * pitch
            cc = min(max(c + off, lim[d_ax][0] + edge), lim[d_ax][1] - edge)
            a = (a0, cc) if band_x else (cc, a0)
            z = (a1, cc) if band_x else (cc, a1)
            for (s, e) in _pieces(a, z, site, band_x, floor_len, edge):
                out.append({"dir": b_ax.upper(),
                            "profile": _profile_points(s, e, sup, band_x,
                                                       z_hi, z_lo, z_anch),
                            "strands": s_base, "coord": cc,
                            "length": dist(s, e), "from_code": True,
                            "role": "band", "spans": [], "governing": {}})
                made_b += 1
        #  الإضافات الموضعية فوق البحور اللي بتطلب أكتر من القاعدة
        for (a_, b_, L) in bays:
            need = W * L ** 2 / (8.0 * drape * pe)
            if need <= got + 0.5:
                continue
            k = int(math.ceil((need - got) / n_max))
            s_ex = min(n_max, int(math.ceil((need - got) / k)))
            lap = 0.25 * L
            for i in range(k):
                off = ((i - (k - 1) / 2.0) * pitch
                       + (t_base / 2.0 + 0.5) * pitch)
                cc = min(max(c + off, lim[d_ax][0] + edge),
                         lim[d_ax][1] - edge)
                p0, p1 = a_ - lap, b_ + lap
                a = (p0, cc) if band_x else (cc, p0)
                z = (p1, cc) if band_x else (cc, p1)
                for (s, e) in _pieces(a, z, site, band_x, floor_len, edge):
                    out.append({"dir": b_ax.upper(),
                                "profile": _profile_points(s, e, sup, band_x,
                                                           z_hi, z_lo, z_anch),
                                "strands": s_ex, "coord": cc,
                                "length": dist(s, e), "from_code": True,
                                "role": "band_extra", "added": True,
                                "spans": [], "governing": {}})
                    made_b += 1
    if job:
        job.ok(f"    {made_b} band tendon(s) over {len(lines)} column line(s), "
               f"each band sized on its own median bay with local tendons "
               f"lapped over the longer ones - a floor is not its worst bay.")
    enforce_min_precompression(out, site, params, job)
    if job:
        code_layout_checks(out, site, params, job)
    return out


def enforce_min_precompression(tendons, site, params, job=None):
    """
    ACI 318-19 §8.6.2.1: الضغط المتوسط مايقلّش عن 0.86 MPa **في كل
    اتجاه**، مش في المجموع.

    قسمة الحمل على الاتجاهين بنسبة الصلابة بتدّي الاتجاه القاسي أغلب
    الحمل - على سقف المهندس 76% لـ X و24% لـ Y - والـ 24% دي طلّعت
    P/A = 0.50 في Y. الحد الأدنى ده **شرط على البلاطة نفسها** مش على
    الموازنة: هو اللي بيقفل الشقوق ويخلّي القطاع يشتغل كقطاع واحد،
    فبيتفرض بعد التوزيع مهما كانت القسمة.

    بترجّع {الاتجاه: استرندات اتزوّدت}.
    """
    pe = float(getattr(params, "force_per_strand", 110.0) or 110.0)
    n_max = int(getattr(params, "max_strands", 5) or 5)
    added = {}
    for d in ("X", "Y"):
        mine = [t for t in tendons
                if t.get("dir") == d and not t.get("_deleted")]
        if not mine:
            continue
        area = direction_section_area(site, params, d)
        if not area:
            continue
        need = PA_MIN * area * 1000.0 / pe          # استرندات مطلوبة
        have = sum(int(t.get("strands") or 0) for t in mine)
        if have >= need - 1e-6:
            continue
        short = int(math.ceil(need - have))
        #  بالدور على الكابلات، والأقل أولاً - توزيع متساوي بدل تكويم
        gone = 0
        for _ in range(short):
            pick = min((t for t in mine
                        if int(t.get("strands") or 0) < n_max),
                       key=lambda t: int(t.get("strands") or 0), default=None)
            if pick is None:
                break
            pick["strands"] = int(pick.get("strands") or 0) + 1
            gone += 1
        added[d] = gone
        if job:
            pa_was = have * pe / area / 1000.0
            pa_now = (have + gone) * pe / area / 1000.0
            if gone < short:
                job.warn(f"    {d}: the code minimum precompression of "
                         f"{PA_MIN:.2f} MPa needs {short} more strand(s) and "
                         f"only {gone} fitted - every tendon is at the "
                         f"{n_max}-strand maximum. P/A {pa_was:.2f} -> "
                         f"{pa_now:.2f}. Close the spacing or allow a bigger "
                         f"tendon.")
            else:
                job.ok(f"    {d}: {gone} strand(s) added to meet the code "
                       f"minimum precompression - the load split left this "
                       f"direction at {pa_was:.2f} MPa and ACI 318 8.6.2.1 "
                       f"asks for {PA_MIN:.2f}. P/A {pa_was:.2f} -> "
                       f"{pa_now:.2f}. This is a condition on the slab, not "
                       f"on the balancing.")
    return added


def code_layout_checks(tendons, site, params, job):
    """الفحوص اللي المصمّم بيعملها بعد ما يخلص الرسم."""
    h = float(getattr(params, "slab_thickness", 250.0) or 250.0)
    pe = float(getattr(params, "force_per_strand", 110.0) or 110.0)
    for d in ("X", "Y"):
        n = sum(int(t.get("strands") or 0) for t in tendons
                if t.get("dir") == d and not t.get("_deleted"))
        area = direction_section_area(site, params, d)
        if not area or not n:
            continue
        pa = n * pe / area / 1000.0
        if pa < PA_MIN:
            job.warn(f"    P/A in {d} is {pa:.2f} MPa, under the "
                     f"{PA_MIN:.2f} the code asks for - this layout is too "
                     f"light to be a prestressed slab in that direction.")
        elif pa > PA_MAX:
            job.warn(f"    P/A in {d} is {pa:.2f} MPa, over the {PA_MAX:.2f} "
                     f"that is workable - shortening and creep eat that "
                     f"force. The slab is too thin for these bays at this "
                     f"balanced load: the drape is what is missing, not the "
                     f"steel. Try the preliminary sizing mode.")
        else:
            job.ok(f"    P/A in {d}: {pa:.2f} MPa (code minimum "
                   f"{PA_MIN:.2f}, workable up to {PA_MAX:.2f})")


def design_offline(dxf_path, params, job, out_dir=None, layer_roles=None,
                   unit_label=None, stem=None, shop=True):
    """
    **الرن الكامل من غير ما رام يفتح (17.36).**

    بيعمل: قراءة الـ DXF -> خطوط الشرايح -> الكابلات والبروفايلات ->
    قاعدة نصف القطر -> القياس -> التقرير والرسم.

    اللي مابيعملوش - وده مقصود: التحليل والتصميم المعتمد كوداً. دول رام
    وبس. فده الباس التمهيدي اللي بتعمله عشر مرات والتخطيط لسه بيتحرك،
    ورام بيفضل للتحقق.

    بترجّع {site, lines, tendons, measured, files, notes}.
    """
    if not dxf_path or not os.path.isfile(dxf_path):
        raise RuntimeError(f"no DXF at {dxf_path}")
    out_dir = out_dir or os.path.dirname(dxf_path)
    stem = stem or os.path.splitext(os.path.basename(dxf_path))[0]

    if layer_roles is None:
        layers, _u = scan_dxf_layers(dxf_path)
        layer_roles = {L["name"]: L["role"] for L in layers}
    if unit_label is None:
        unit_label = list(UNIT_CHOICES)[0]

    job.log("A design pass with RAM never opened", "head")
    #  **18.43: ومافيش رام يعني موازنة الأحمال هي الحَكَم.** الحارس
    #  اللي بيمنع إعادة حساب العدد موجود عشان قراية رام ماتتلغيش -
    #  وهنا مافيش قراية أصلاً، فبيتشال للرن ده وبس ويترجّع بعده.
    _was_sfb = getattr(params, "size_from_balancing", None)
    params.size_from_balancing = True
    try:
        return _design_offline_inner(dxf_path, params, job, out_dir,
                                     layer_roles, unit_label, stem, shop)
    finally:
        if _was_sfb is None:
            try:
                del params.size_from_balancing
            except AttributeError:
                pass
        else:
            params.size_from_balancing = _was_sfb


def _design_offline_inner(dxf_path, params, job, out_dir, layer_roles,
                          unit_label, stem, shop):
    site = parse_dxf(dxf_path, layer_roles, unit_label, job)
    if not site.get("boundary"):
        raise RuntimeError("the DXF has no slab boundary")

    lines = support_lines_offline(site, params, job)
    job.ok(f"{sum(len(L.get('spans') or []) for L in lines)} span(s) on "
           f"{len(lines)} support line(s) - the same lines the run would "
           f"draw in RAM.")

    engine = PTEngine(site, params, job)
    #  **18.44: نفس مصادر الكابلات اللي في مسار رام.** الوضع ده كان
    #  بيصمّم بالمحرّك مهما كانت الإعدادات بتقول إيه، فالرسمة الطالعة
    #  منه مش هي اللي كانت هتتبني في رام.
    tendons = external_tendons(site, params, job, out_dir=out_dir, stem=stem)
    if tendons is None:
        tendons, _design = engine.generate()
    if not tendons:
        raise RuntimeError("no tendon could be laid out on this floor")
    tendons, _cuts = split_long_tendons(tendons, params, job)

    _walls = []
    for key in ("walls", "beams"):
        for w in (site.get(key) or []):
            if w.get("p1") and w.get("p2"):
                _walls.append(((w["p1"][0], w["p1"][1]),
                               (w["p2"][0], w["p2"][1])))
    try:
        _shapes = _support_shapes(site)
    except Exception:
        _shapes = []
    #  **18.44: وقواعد المسقط كمان.** كانت بتتنفّذ جوّه
    #  `write_tendons_to_ram` وبس، فالرسمة الطالعة من الوضع ده كانت
    #  ممكن تعدّي على فتحة أو وش كمرة والرن اللي بيروح رام ينضّفها -
    #  رسمتين مختلفتين لنفس التخطيط. ومع تخطيط جاي من بره، دي هي
    #  الحتة اللي بتفرض الكود على اللي رجع.
    enforce_plan_rules(tendons, params, job, site)
    enforce_profile_rules(tendons, params, job, drops=site.get("drops"),
                          walls=_walls, shapes=_shapes)

    m = measure_design(site, tendons, lines, None, params)
    m["model"] = os.path.basename(dxf_path)
    notes = ["This pass never opened RAM. Coverage and overlap are missing "
             "because RAM builds the strips themselves at Calc All - "
             "everything else here is measured.",
             "Run the same file through RAM for the analysis and the "
             "code-checked design."]
    files = {}
    files["measurements"] = save_measurements(m, out_dir, stem, job)
    files["report"] = save_run_report(m, out_dir, stem, job, notes)
    if shop:
        try:
            shop_path = os.path.join(out_dir, f"{stem}_AutoPT_shop.dxf")
            export_shop_drawing(tendons, site, params, shop_path, job)
            files["shop"] = shop_path
        except Exception as e:
            job.info(f"    the shop drawing was not written ({e}).")
    format_measurements(m, job)
    job.ok("Done with no RAM: the layout, the tendons, the profiles, the "
           "numbers and the drawing are on disk. What is missing is the "
           "analysis - that is the part only RAM does.")
    return {"site": site, "lines": lines, "tendons": tendons, "measured": m,
            "files": files, "notes": notes}


def band_outline(b):
    """
    الخرسانة الحقيقية للكمرة العريضة لو معروفة، وإلا المستطيل من محورها
    (17.62). على UNB 5 المستطيل وقف عند y 16.728 والخرسانة لحد 16.753.
    """
    poly = b.get("poly")
    if poly and len(poly) >= 3:
        return [tuple(q) for q in poly]
    return band_corners(b["p1"], b["p2"], float(b.get("width") or 0.0))


def _near_outline(pt, poly, clear):
    """جوّه المحيط، أو على بعد `clear` منه."""
    if md_point_in_poly(pt, poly):
        return True
    if clear <= 0:
        return False
    for a, b in zip(poly, poly[1:] + poly[:1]):
        if md_seg_dist(pt, a, b) <= clear:
            return True
    return False


def _station_on(pts, cum, p):
    """(المسافة من البوليلاين، المحطة عليه) لأقرب نقطة."""
    best = (1e18, 0.0)
    for i in range(len(pts) - 1):
        a, b = pts[i], pts[i + 1]
        dx, dy = b[0] - a[0], b[1] - a[1]
        L2 = dx * dx + dy * dy
        t = 0.0 if L2 < 1e-12 else max(0.0, min(1.0, (
            (p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L2))
        qx, qy = a[0] + t * dx, a[1] + t * dy
        d = math.hypot(p[0] - qx, p[1] - qy)
        if d < best[0]:
            best = (d, cum[i] + t * math.sqrt(L2))
    return best


def shape_band_runs(tendons, site, params, job=None):
    """
    **الكابل الماشي جوّه كمرة عريضة (17.57).**

    جوّه الكمرة العريضة النقط العالية على الأعمدة والحوائط اللي واقفة
    فيها بس - مش من خريطة المومنت - وكل غطسة بينهم بتنزل لعمق الكمرة
    نفسها. كمرة مسنودة من طرفيها بس = غطسة واحدة. ده رسم المهندس على
    UNB 5: كمرات 900/1000 من غير نقطة عالية جوّاها، وكمرات 450 عاليتها
    على العمود (x 25.6) والحيطة (x 31.6) اللي فيها بالظبط.

    بترجّع عدد الكابلات اللي اتظبطت. متكررة من غير ضرر.
    """
    bands = [b for b in ((site or {}).get("beams") or []) if b.get("band")]
    if not bands or not bool(getattr(params, "band_run_profile", True)):
        return 0
    #  **18.93: الكابل المرسوم بإيد مهندس تاني مايتشكّلش من جديد.**
    #  القاعدة دي بتدّي الكابل الماشي على كمرة عريضة بروفايل الكمرة -
    #  وده صح لما إحنا اللي بانيينه. على كابل جاي من موديل جاهز ده
    #  بيكسر بروفايل مقصود. `enforce_profile_rules` بتحترم `as_drawn`
    #  من زمان؛ دي كانت فاضلة.
    tendons = [t for t in (tendons or []) if not t.get("as_drawn")]
    if not tendons:
        return 0
    share = float(getattr(params, "band_run_share", 0.5) or 0.5)
    rounding = getattr(params, "elevation_rounding", 0) or 1.0
    gap = float(getattr(params, "min_point_gap", 1.5) or 0.0)
    min_span = float(getattr(params, "min_sag_span", 0.8) or 0.0)
    cols = [c["center"] for c in (site.get("columns") or [])
            if c.get("center")]
    members = [m for m in (site.get("walls") or []) + (site.get("beams") or [])
               if not m.get("band")]
    cos_par = math.cos(math.radians(45.0))      # نفس العيلة، X أو Y
    step = 0.25
    eps = 0.01
    #  17.59: الغطسة جوّه الكمرة على قد أقل نصف قطر مسموح
    #  17.60: بنسبة الانقلاب اللي رام بيستعملها فعلاً (0.2 على كل كابل في
    #  UNB 5 وThe Bridge وناتج البرنامج)، مش إعداد نقط الانقلاب في البرنامج
    #  - ده كان 0.0 في إعدادات المهندس فالحد اتقفل.
    beta_default = float(SHOP_INFLECTION)
    r_min = float(getattr(params, "min_tendon_radius", 0.0) or 0.0)
    if bool(getattr(params, "radius_from_model", True)):
        r_min = max(r_min, float(getattr(params, "_ram_min_radius", 0.0)
                                 or 0.0))
    #  17.62: نفس المسافة اللي قاعدة "مفيش غطسة فوق ركيزة" بتبص فيها
    clear = max(float(getattr(params, "sag_support_clear", 0.25) or 0.0), 0.0)
    shaped = taken = placed = 0
    for t in tendons:
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        pts = [tuple(q["pos"]) for q in pr]
        cum = md_cumulative(pts)
        L = cum[-1]
        if L < 1e-6:
            continue
        tvx, tvy = pts[-1][0] - pts[0][0], pts[-1][1] - pts[0][1]
        tn = math.hypot(tvx, tvy) or 1.0
        top, bot = params.covers_for(t.get("dir", "X"))
        zones = []
        for b in bands:
            bvx, bvy = b["p2"][0] - b["p1"][0], b["p2"][1] - b["p1"][1]
            bl = math.hypot(bvx, bvy)
            if bl < 1e-6 or abs(tvx * bvx + tvy * bvy) / (tn * bl) < cos_par:
                continue
            cor = band_outline(b)
            if not cor:
                continue
            ss = [k * step for k in range(int(L / step) + 1)] + [L]
            inside = [s for s in ss
                      if _near_outline(md_polyline_at(pts, cum, s)[0], cor,
                                       clear)]
            if not inside:
                continue
            runs, a0, prev = [], inside[0], inside[0]
            for s in inside[1:]:
                if s - prev > 1.5 * step:
                    runs.append((a0, prev))
                    a0 = s
                prev = s
            runs.append((a0, prev))
            s0, s1 = max(runs, key=lambda r: r[1] - r[0])
            if s1 - s0 < share * bl:
                continue
            zones.append((s0, s1, b, cor))
        if not zones:
            continue
        nodes = [(cum[i], q) for i, q in enumerate(pr)]
        band_zones, band_ids = [], []
        beta = float(t.get("inflection") or beta_default)
        for s0, s1, b, cor in zones:
            d_band = float(b.get("depth") or params.slab_thickness)
            sag_d = round_to(max(d_band - bot, top), rounding)
            high_d = round_to(top, rounding)
            #  17.86: مرساة كابل الكمرة العميقة في نص عمق الكمرة، زي
            #  المهندس (600 في كمرة 1200)، والقاعدة اللي بتشد الأطراف
            #  لمنسوب مرساة البلاطة بتسيبها (band).
            if t.get("beam_tendon") and b.get("deep_beam"):
                for s_end, q_end in nodes:
                    if (s_end <= eps or s_end >= L - eps) and \
                            (s0 - 0.3 <= s_end <= s1 + 0.3):
                        q_end["depth"] = round_to(d_band / 2.0, rounding)
                        q_end["band"] = True
                        q_end["sag"] = False
            taken += sum(1 for s, q in nodes
                         if s0 + eps < s < s1 - eps and eps < s < L - eps
                         and q.get("high"))
            nodes = [(s, q) for s, q in nodes
                     if not (s0 + eps < s < s1 - eps)
                     or s <= eps or s >= L - eps]
            sup = []
            for c in cols:
                if md_point_in_poly(c, cor):
                    _d, s = _station_on(pts, cum, c)
                    if s0 - 0.3 <= s <= s1 + 0.3:
                        sup.append(s)
            #  17.58: حيطة واقفة جوّه الكمرة ركيزة حتى لو الكابل مابيقطعش
            #  خطها: على UNB 5 الحيطة عند x 31.6 بتقف عند y 10.4 والكابل
            #  ماشي على 10.2. اللي بتعدّي الكابلات = عالية عند خطها؛
            #  اللي ماشية معاها = عالية عند أطرافها اللي جوّه الكمرة.
            for mbr in members:
                a_m, b_m = tuple(mbr["p1"]), tuple(mbr["p2"])
                k_m = max(int(dist(a_m, b_m) / step), 1)
                inb = [(a_m[0] + (b_m[0] - a_m[0]) * i / k_m,
                        a_m[1] + (b_m[1] - a_m[1]) * i / k_m)
                       for i in range(k_m + 1)]
                inb = [z for z in inb if md_point_in_poly(z, cor)]
                if not inb:
                    continue
                mvx, mvy = b_m[0] - a_m[0], b_m[1] - a_m[1]
                ml = math.hypot(mvx, mvy) or 1.0
                if abs(mvx * tvx + mvy * tvy) / (ml * tn) >= cos_par:
                    for end in (a_m, b_m):
                        if md_point_in_poly(end, cor):
                            _d, s = _station_on(pts, cum, end)
                            if s0 - 0.3 <= s <= s1 + 0.3:
                                sup.append(s)
                else:
                    z = min(inb, key=lambda w: _station_on(pts, cum, w)[0])
                    _d, s = _station_on(pts, cum, z)
                    if s0 - 0.3 <= s <= s1 + 0.3:
                        sup.append(s)
            highs = []
            for s in sorted(sup):
                s = max(0.0, min(L, s))
                if s <= gap or s >= L - gap:
                    continue                    # لازقة في المرساة
                if any(abs(s - x) < gap for x in highs):
                    continue
                highs.append(s)
            for s in highs:
                nodes = [(x, q) for x, q in nodes
                         if not (abs(x - s) < gap and eps < x < L - eps
                                 and not (s0 + eps < x < s1 - eps))
                         or q.get("high")]
                pos, _u = md_polyline_at(pts, cum, s)
                nodes.append((s, {"pos": pos, "depth": high_d, "drop_idx": -1,
                                  "high": True, "sag": False, "src": "band",
                                  "band": True}))
            placed += len(highs)
            nodes.sort(key=lambda kv: kv[0])
            fixed = [s for s, q in nodes
                     if q.get("high") or s <= eps or s >= L - eps]
            for a, c_ in zip(fixed, fixed[1:]):
                mid = (a + c_) / 2.0
                if not (s0 <= mid <= s1) or c_ - a < min_span:
                    continue
                if any(q.get("sag") and a < s < c_ for s, q in nodes):
                    continue
                pos, _u = md_polyline_at(pts, cum, mid)
                #  **على قد أقل نصف قطر (17.59).** رام بيلفّ الكابل عند
                #  نقطة الانقلاب على β من نص البحر، فأحدّ انحناء على القمة:
                #  R = β·h²/(2a) ← أعمق غطس مسموح a = β·h²/(2R).
                #  17.62: غطسة بره خرسانة الكمرة (كابل على وشّها، في
                #  البلاطة) بتنزل لعمق البلاطة، مش لعمق الكمرة.
                cap = sag_d if md_point_in_poly(pos, cor) else round_to(
                    max(float(params.slab_thickness) - bot, top), rounding)
                d_here = cap
                if beta > 0 and r_min > 0:
                    h_half = (c_ - a) / 2.0
                    a_mm = 1000.0 * beta * h_half * h_half / (2.0 * r_min)
                    d_here = min(cap, max(top, math.floor(
                        (top + a_mm) / rounding) * rounding))
                nodes.append((mid, {"pos": pos, "depth": d_here,
                                    "drop_idx": -1, "high": False,
                                    "sag": True, "band": True}))
            nodes.sort(key=lambda kv: kv[0])
            band_zones.append((cor, sag_d))
            band_ids.append(id(b))
        for _s, q in nodes:
            q.pop("_s", None)
        t["profile"] = [q for _s, q in nodes]
        t["band_zones"] = band_zones
        t["band_ids"] = band_ids
        shaped += 1
    if shaped and job:
        job.ok(f"Band beams: {shaped} tendon(s) run along a band. Inside it "
               f"their high points sit only on the columns and walls standing "
               f"in the band ({placed}), none from the moment field ({taken} "
               f"taken off), and each dip goes down to the band's own depth.")
    return shaped


def size_band_tendons(tendons, site, params, fields, job=None):
    """
    **عدد كابلات الكمرة العريضة من مومنتها وعمقها (17.59).**

    لكل كمرة: كل بحر بين الركايز اللي واقفة فيها بيتقرا من خريطة المومنت
    على عرض الكمرة. التأرجح = المومنت الموجب - متوسط السالب عند طرفيه
    (على بعد `band_moment_face` من الركيزة، بعد القمة الشاذة). القوة =
    نسبة الموازنة × التأرجح × عرض الكمرة ÷ غطسة البحر نفسه، والاسترندات =
    القوة ÷ قوة الاسترند، على أسوأ بحر. الكابلات بتتزوّد جنب بعض جوّه
    الكمرة من طرفها لطرفها لحد ما تاخد اللي محتاجاه.

    من غير خريطة مومنت مابيعملش حاجة وبيقول كده. بترجّع عدد الكابلات
    اللي اتزوّدت.
    """
    import copy as _copy
    bands = [b for b in ((site or {}).get("beams") or []) if b.get("band")]
    if not bands or not bool(getattr(params, "band_tendon_count", True)):
        return 0
    fields = fields or {}
    shape_band_runs(tendons, site, params, None)
    F = float(getattr(params, "force_per_strand", 0.0) or 0.0)
    smax = int(getattr(params, "max_strands", 5) or 5)
    smin = int(getattr(params, "min_strands", 2) or 1)
    beta_bal = float(getattr(params, "balance_ratio", 0.70) or 0.0)
    spacing = max(float(getattr(params, "band_tendon_spacing", 0.30) or 0.30),
                  0.05)
    edge = max(float(getattr(params, "band_tendon_edge", 0.10) or 0.0), 0.0)
    face = max(float(getattr(params, "band_moment_face", 0.50) or 0.0), 0.0)
    clear_b = max(float(getattr(params, "sag_support_clear", 0.25) or 0.0),
                  0.0)
    rounding = getattr(params, "elevation_rounding", 0) or 1.0
    if F <= 0:
        return 0
    added = 0
    no_field = 0
    lines = []
    for b in bands:
        p1, p2 = tuple(b["p1"]), tuple(b["p2"])
        Lb = dist(p1, p2)
        if Lb < 1e-6:
            continue
        ux, uy = (p2[0] - p1[0]) / Lb, (p2[1] - p1[1]) / Lb
        nx, ny = -uy, ux
        width = float(b.get("width") or 0.0) / 1000.0
        d = "X" if abs(ux) >= abs(uy) else "Y"
        members = [t for t in tendons if t.get("dir") == d
                   and id(b) in (t.get("band_ids") or [])]
        if not members:
            continue
        fld = fields.get(d)
        if fld is None:
            no_field += 1
            continue
        top, bot = params.covers_for(d)

        def along(pos):
            return (pos[0] - p1[0]) * ux + (pos[1] - p1[1]) * uy

        def across(pos):
            return (pos[0] - p1[0]) * nx + (pos[1] - p1[1]) * ny

        ref = max(members, key=lambda t: sum(
            1 for q in t["profile"] if 0.0 <= along(q["pos"]) <= Lb
            and abs(across(q["pos"])) <= width / 2.0 + clear_b))
        inner = sorted((q for q in ref["profile"]
                        if -1e-6 <= along(q["pos"]) <= Lb + 1e-6
                        and abs(across(q["pos"])) <= width / 2.0 + clear_b
                        + 1e-6),
                       key=lambda q: along(q["pos"]))
        highs = [along(q["pos"]) for q in inner if q.get("high")]
        fixed = [0.0] + [h for h in highs if 0.0 < h < Lb] + [Lb]
        offs = ([0.0] if width < 0.3 else
                [-width / 2.0 + width * 0.15, 0.0, width / 2.0 - width * 0.15])
        worst = None
        for a, c in zip(fixed, fixed[1:]):
            span = c - a
            if span < float(getattr(params, "min_sag_span", 0.8) or 0.0):
                continue
            k = max(int(span / 0.25), 2)
            rows = []
            for i in range(k + 1):
                u = a + span * i / k
                vals = [fld.value_at(p1[0] + ux * u + nx * o,
                                     p1[1] + uy * u + ny * o) for o in offs]
                vals = [v for v in vals if v is not None]
                if vals:
                    rows.append((u, sum(vals) / len(vals)))
            if not rows:
                continue
            m_sag = max(0.0, max(v for _u, v in rows))

            def hog_near(x0):
                near = [(abs(u - x0), v) for u, v in rows
                        if abs(u - x0) >= min(face, span / 4.0) - 1e-6]
                if not near:
                    return 0.0
                dmin = min(dd for dd, _v in near)
                return min(0.0, min(v for dd, v in near if dd <= dmin + 1e-6))

            hog = (hog_near(a) + hog_near(c)) / 2.0
            swing = m_sag - hog
            sags = [q["depth"] for q in inner
                    if q.get("sag") and a < along(q["pos"]) < c]
            depth = max(sags) if sags else float(b.get("depth") or 0.0) - bot
            drape = max(depth - top, rounding) / 1000.0
            P = beta_bal * swing * width / drape
            if worst is None or P > worst[0]:
                worst = (P, swing, span, depth, a, c)
        if worst is None:
            continue
        P, swing, span, depth, _a, _c = worst
        need = int(math.ceil(P / F - 1e-9))
        have = sum(int(t.get("strands") or 0) for t in members)
        occupied = [across(next(q["pos"] for q in sorted(
                        t["profile"], key=lambda q: abs(along(q["pos"])
                                                        - Lb / 2.0))))
                    for t in members]
        slots = []
        usable = width - 2.0 * edge
        n_lines = max(int(usable / spacing + 1e-9) + 1, 1)
        for i in range(n_lines):
            o = (-usable / 2.0 + i * spacing
                 + (usable - (n_lines - 1) * spacing) / 2.0)
            if all(abs(o - e) >= spacing * 0.5 for e in occupied):
                slots.append(o)
        slots.sort(key=abs)
        new_here = []
        short = need - have
        for o in slots:
            if short <= 0:
                break
            s = min(smax, max(smin, short))
            shift = o - across(inner[0]["pos"]) if inner else o
            u0, u1 = min(edge, Lb / 2.0), max(Lb - edge, Lb / 2.0)
            prof = [{"pos": (p1[0] + ux * u0 + nx * o, p1[1] + uy * u0 + ny * o),
                     "depth": round_to(params.anchor_elevation, rounding),
                     "drop_idx": -1, "high": False, "sag": False,
                     "anchor": True}]
            for q in inner:
                u = along(q["pos"])
                if u0 + 0.05 < u < u1 - 0.05 and (q.get("high")
                                                  or q.get("sag")):
                    nq = {k: v for k, v in q.items() if not k.startswith("_")}
                    nq["pos"] = (q["pos"][0] + nx * shift,
                                 q["pos"][1] + ny * shift)
                    prof.append(nq)
            prof.append({"pos": (p1[0] + ux * u1 + nx * o,
                                 p1[1] + uy * u1 + ny * o),
                         "depth": round_to(params.anchor_elevation, rounding),
                         "drop_idx": -1, "high": False, "sag": False,
                         "anchor": True})
            nt = _copy.deepcopy({k: v for k, v in ref.items()
                                 if k not in ("profile", "path", "band_zones",
                                              "band_ids", "jacks", "nodes")})
            nt.update({"dir": d, "strands": s, "profile": prof,
                       "length": sum(dist(prof[i]["pos"], prof[i + 1]["pos"])
                                     for i in range(len(prof) - 1)),
                       "coord": (prof[0]["pos"][1] if d == "X"
                                 else prof[0]["pos"][0]),
                       "band_tendon": True, "added": True})
            new_here.append(nt)
            short -= s
        tendons.extend(new_here)
        added += len(new_here)
        lines.append(
            f"    {Lb:.1f} x {width:.1f} m at {float(b.get('depth') or 0):.0f} "
            f"mm: worst span {span:.1f} m, swing {swing:.0f} kN.m/m, drape "
            f"{depth - top:.0f} mm -> {P:,.0f} kN = {need} strands; {have} "
            f"there, {len(new_here)} tendon(s) added"
            + (f" - {short} strand(s) had no room at "
               f"{spacing * 1000:.0f} mm spacing" if short > 0 else ""))
    if job and lines:
        job.ok(f"Band beams sized from their own moment and depth: {added} "
               f"tendon(s) added.")
        for ln in lines:
            job.info(ln)
    if job and no_field:
        job.info(f"{no_field} band beam(s) kept the tendons the layout gave "
                 f"them: sizing a band from its moment needs a moment field "
                 f"(the plots, or the moments read from RAM).")
    if added:
        shape_band_runs(tendons, site, params, None)
    return added


def nodes_to_draw(profile):
    """
    العقد اللي بتتكتب في رام (18.23): كل حاجة ما عدا نقط الانقلاب.

    رام بيرسم كل قطعة بين عقدتين كقطعين مكافئين بنقطة انقلاب من عنده
    (Tendon.InflectionRatio، 0.2). لما نكتب نقطة الانقلاب بتاعتنا كعقدة
    على بُعد 0.23 م من القمة، رام بيحط قوسه المعكوس جوّه القطعة القصيرة
    دي - 40 -> 104 مم على 0.23 م = نصف قطر 8 سم - و380 تحذير على سقف
    واحد. المهندس مابيرسمش نقط انقلاب: قمم وغطسات ومراسي وبس.
    """
    out = [q for q in (profile or []) if not q.get("inflection")]
    if len(out) < 2 and profile:
        return list(profile)
    return out


# ---------------------------------------------------------------------------
#  قواعد المسقط الأفقي - بتتطبق قبل قواعد البروفايل، على كل مسارات الكتابة
# ---------------------------------------------------------------------------
#  القواعد دي كلها اتقاسـت على موديل المهندس نفسه (رن 23:34)، مش مفترضة:
#    · 4 كابلات أطراف مشتركة بالظبط مع كابل في الاتجاه التاني - القارئ
#      بيقراهم كابل واحد بيلف 90 درجة، والرام بيرسم مرساتين في نفس
#      السنتيمتر. مافيش مكان لأنكرين في نفس النقطة.
#    · 3 أزواج على نفس الاستقامة بينهم 0.92 و 2.35 و 2.41 م - المفروض
#      كابل واحد.
#    · 4 كابلات أقصر من 6.00 م (الحد الأدنى في الإعدادات) - كلهم من
#      الحلقة، لأن فلتر الطول بيشتغل في التخطيط المنتظم بس.
#    · 12 كابل ليه عقدة جوّه فتحة.


def _plan_axis(t):
    """اتجاه الكابل في المسقط - وحدة اتجاه من أول نقطة لآخر نقطة."""
    pr = t.get("profile") or []
    if len(pr) < 2:
        return None
    dx = pr[-1]["pos"][0] - pr[0]["pos"][0]
    dy = pr[-1]["pos"][1] - pr[0]["pos"][1]
    n = math.hypot(dx, dy)
    if n < 1e-9:
        return None
    return (dx / n, dy / n)


def _plan_length(t):
    pr = t.get("profile") or []
    return sum(dist(pr[i]["pos"], pr[i + 1]["pos"])
               for i in range(len(pr) - 1))


def _ours(t):
    """
    الكابل ده من صنع الرن ده، فينفع نلمسه.

    `as_drawn` بتتحط في المسار اللي بيقرا من الموديل، بس **مش في وضع
    `full`** - وهناك الكابل بيبقى بتاع المهندس وعلامته الوحيدة
    `from_model`. فالاتنين بيتشافوا هنا، عشان القاعدة تبقى واحدة في كل
    الدوال بدل ما كل واحدة تفتكر لوحدها.
    """
    return not t.get("as_drawn") and not t.get("from_model")


def _on_slab(pos, boundary, openings, margin=0.0):
    """النقطة على خرسانة: جوّه الحدود وبرّه كل فتحة."""
    x, y = pos
    if boundary and not point_in_polygon(x, y, boundary):
        return False
    for op in (openings or []):
        if op and point_in_polygon(x, y, op):
            return False
    return True


def _run_to_slab_end(pos, u, boundary, openings, limit, step=0.05):
    """
    المسافة من `pos` في اتجاه `u` لحد ما الخرسانة تخلص - أو None لو
    الخرسانة مستمرة بعد `limit`.

    بيتمشى بخطوة صغيرة بدل ما يقطع مع الأضلاع عشان الفتحة اللي بتبدأ
    بعد الطرف بخطوة واحدة تتحسب، والحدود المقعّرة كمان.
    """
    if limit <= 0:
        return None
    n = int(limit / step) + 1
    last = 0.0
    for i in range(1, n + 1):
        s = min(i * step, limit)
        q = (pos[0] + u[0] * s, pos[1] + u[1] * s)
        if not _on_slab(q, boundary, openings):
            return last
        last = s
    return None


def extend_stub_ends(tendons, params, site, job=None):
    """
    طرف كابل فاضل بينه وبين الفتحة أو نهاية السقف أقل من مترين: يتمدّ
    للنهاية.

    السبب: الشُبر ده مش بيشيل حاجة - البحر الطرفي بتاعه أقصر من إن
    الكابل يعمل فيه غطسة مفيدة - وبيخلّي الصلب السفلي شغّال لوحده في
    آخر متر. تمديده لحد الحافة بيكلّف طول كابل بس، من غير ولا استرند
    زيادة، وبيدّي الطرف مرساة على حافة نظيفة بدل ما يقف في نص اللمة.
    """
    limit = float(getattr(params, "stub_extend_gap", 2.0) or 0.0)
    if limit <= 0 or not site:
        return 0
    clear = float(getattr(params, "edge_offset", 0.30) or 0.0)
    clear = max(min(clear, 0.15), 0.05)      # مرساة على الحافة مش فيها
    boundary = site.get("boundary") or []
    openings = site.get("openings") or []
    done = 0
    for t in tendons:
        if t.get("_deleted") or not _ours(t):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        for k, j in ((0, 1), (-1, -2)):
            a, b = pr[k]["pos"], pr[j]["pos"]
            L = dist(a, b)
            if L < 1e-6:
                continue
            u = ((a[0] - b[0]) / L, (a[1] - b[1]) / L)   # بره الكابل
            run = _run_to_slab_end(a, u, boundary, openings, limit)
            if run is None or run <= clear:
                continue
            go = run - clear
            if go < 0.10:
                continue
            cap_len = float(getattr(params, "max_tendon_length", 0.0) or 0.0)
            if 0 < cap_len < _plan_length(t) + go:
                continue
            pr[k]["pos"] = (a[0] + u[0] * go, a[1] + u[1] * go)
            pr[k].pop("_s", None)
            t["_stub_extended"] = round(
                float(t.get("_stub_extended") or 0.0) + go, 3)
            done += 1
    if job and done:
        job.ok(f"{done} tendon end(s) stopped less than {limit:g} m short of "
               f"an opening or the slab edge and were run out to it - the "
               f"stub they left could not balance anything, and taking it to "
               f"the edge costs length, not strands.")
    return done


def merge_collinear_tendons(tendons, params, job=None, site=None):
    """
    كابلين على نفس الاستقامة بينهم فجوة قصيرة = كابل واحد.

    الفجوة لازم تكون خرسانة سليمة - لو فيها فتحة أو هي بره البلاطة
    فالكابلين منفصلين بحق والوصل غلط.
    """
    gap_limit = float(getattr(params, "collinear_merge_gap", 3.0) or 0.0)
    off_tol = float(getattr(params, "collinear_merge_offset", 0.15) or 0.0)
    cap_len = float(getattr(params, "max_tendon_length", 0.0) or 0.0)
    if gap_limit <= 0:
        return 0
    boundary = (site or {}).get("boundary") or []
    openings = (site or {}).get("openings") or []

    def ends(t):
        pr = t["profile"]
        return pr[0]["pos"], pr[-1]["pos"]

    live = [t for t in tendons
            if not t.get("_deleted") and _ours(t)
            and len(t.get("profile") or []) >= 2]
    merged = 0
    changed = True
    while changed:
        changed = False
        for i, t in enumerate(live):
            if t.get("_deleted"):
                continue
            ua = _plan_axis(t)
            if ua is None:
                continue
            for o in live[i + 1:]:
                if o.get("_deleted"):
                    continue
                ub = _plan_axis(o)
                if ub is None:
                    continue
                if abs(ua[0] * ub[0] + ua[1] * ub[1]) < 0.999:
                    continue
                a0, a1 = ends(t)
                b0, b1 = ends(o)
                #  الإزاحة العمودية: الاتنين على نفس الخط؟
                off = max(abs((q[0] - a0[0]) * ua[1] - (q[1] - a0[1]) * ua[0])
                          for q in (b0, b1))
                if off > off_tol:
                    continue
                #  المسافة على المحور - لازم يكونوا مش متداخلين
                sa = sorted((0.0, (a1[0] - a0[0]) * ua[0]
                             + (a1[1] - a0[1]) * ua[1]))
                sb = sorted(((b0[0] - a0[0]) * ua[0] + (b0[1] - a0[1]) * ua[1],
                             (b1[0] - a0[0]) * ua[0] + (b1[1] - a0[1]) * ua[1]))
                if sb[0] < sa[1] and sa[0] < sb[1]:
                    continue                    # متداخلين - مش فجوة
                gap = sb[0] - sa[1] if sb[0] >= sa[1] else sa[0] - sb[1]
                if gap < 0 or gap > gap_limit:
                    continue
                #  الوصل مايكسرش أقصى طول. القاعدة دي موجودة عشان
                #  الكابل يتشد على الواقع، والوصل من غيرها بيعمل
                #  كابل 62 م من قطعتين سليمتين.
                if 0 < cap_len < (_plan_length(t) + _plan_length(o) + gap):
                    continue
                #  الفجوة خرسانة؟
                near_t = a1 if sb[0] >= sa[1] else a0
                near_o = b0 if abs(sb[0] - sa[1] - gap) < 1e-6 else b1
                if boundary or openings:
                    bad = False
                    for f in (0.15, 0.35, 0.5, 0.65, 0.85):
                        q = (near_t[0] + (near_o[0] - near_t[0]) * f,
                             near_t[1] + (near_o[1] - near_t[1]) * f)
                        if not _on_slab(q, boundary, openings):
                            bad = True
                            break
                    if bad:
                        continue
                _join_tendons(t, o, params)
                merged += 1
                changed = True
                break
            if changed:
                break
    if job and merged:
        job.ok(f"{merged} pair(s) of tendons sat on the same line with less "
               f"than {gap_limit:g} m of sound concrete between them and were "
               f"joined into one - two anchorages facing each other across a "
               f"{gap_limit:g} m gap cost four anchorage assemblies and "
               f"balance nothing in between.")
    return merged


def _join_tendons(t, o, params):
    """
    بيوصّل `o` في `t`: البروفايلين بيتلموا مرتّبين على المحور، والطرفين
    المتقابلين بيتشالوا (بقوا في نص الكابل مش مرساة)، والاسترندات
    بتاخد الأكبر عشان القوة ماتقلّش في أي بحر.
    """
    ua = _plan_axis(t)
    s0 = t["profile"][0]["pos"]

    def at(q):
        return (q["pos"][0] - s0[0]) * ua[0] + (q["pos"][1] - s0[1]) * ua[1]

    #  الطرفين المتقابلين بقوا في نص الكابل. المرساة منسوبها نص
    #  السُمك، وسايبها مكانها بيعمل حدبة في نص بحر - نقطة عالية كذّابة
    #  مالهاش ركيزة تحتها. بتتشال، وقاعدة الامتداد المسطّح في
    #  enforce_profile_rules هي اللي بتحط الغطسة في نص البحر الجديد.
    inner_t = t["profile"][-1] if at(t["profile"][-1]) > at(t["profile"][0]) \
        else t["profile"][0]
    ends_o = sorted(o["profile"], key=at)
    inner_o = ends_o[0] if at(ends_o[0]) > at(inner_t) else ends_o[-1]
    drop = {id(q) for q in (inner_t, inner_o)
            if not q.get("high") and not q.get("manual") and not q.get("band")}
    pts = [q for q in (list(t["profile"]) + list(o["profile"]))
           if id(q) not in drop]
    pts.sort(key=at)
    t["profile"] = pts
    t["strands"] = max(int(t.get("strands") or 0), int(o.get("strands") or 0))
    t["length"] = _plan_length(t)
    t["added"] = bool(t.get("added") or o.get("added"))
    o["_deleted"] = True
    o["_merged_into"] = t


def drop_short_tendons(tendons, params, job=None):
    """
    الكابل الأقصر من الحد الأدنى بيتشال، واسترنداته بتروح لأقرب كابل
    موازي لو فيه مكان.

    الفلتر ده موجود في التخطيط المنتظم من زمان، بس الكابل اللي الحلقة
    بتضيفه مابيعدّيش عليه - فطلع في الرن 4 كابلات أقصر من الحد: 3.58،
    3.58، 5.92، 6.00 م. مرستين وقصّتين ودكت كاملة عشان 3.58 م.
    """
    floor = float(getattr(params, "min_tendon_length", 6.0) or 0.0)
    if floor <= 0:
        return 0, 0
    cap = int(getattr(params, "max_strands", 8) or 8)
    tol = 1e-3
    gone = moved = 0
    for t in list(tendons):
        if t.get("_deleted") or not _ours(t):
            continue
        L = _plan_length(t)
        if L >= floor - tol:
            continue
        _d, best = nearest_parallel(t, [q for q in tendons
                                        if q is not t
                                        and not q.get("_deleted")])
        n = int(t.get("strands") or 0)
        take = 0
        if best is not None:
            take = min(n, max(cap - int(best.get("strands") or 0), 0))
            best["strands"] = int(best.get("strands") or 0) + take
        t["_deleted"] = True
        gone += 1
        moved += take
    if job and gone:
        job.warn(f"{gone} tendon(s) this run drew came out shorter than the "
                 f"{floor:g} m minimum and were taken out; {moved} of their "
                 f"strand(s) went into the nearest tendon running the same "
                 f"way. A tendon that short pays for two anchorages, two "
                 f"stressing operations and a full duct to balance one "
                 f"short span.")
    return gone, moved


def separate_shared_ends(tendons, params, job=None):
    """
    مرساتين على نفس النقطة.

    ده اللي المهندس شافه "كابل غيّر اتجاهه": كابل في X بينتهي بالظبط
    عند نقطة بداية كابل في Y، فالاتنين بيتقروا - ويترسموا - سلسلة
    واحدة بتلف 90 درجة. في الموديل بتاع 23:34 حصلت 4 مرات.

    ومهما كانت القراية، مرساتين في نفس السنتيمتر حاجة مش قابلة
    للتنفيذ: كل مرساة عايزة جسمها ومخروط إجهادها ومكان للمكبس.
    """
    clear = float(getattr(params, "min_anchor_separation", 0.20) or 0.0)
    if clear <= 0:
        return 0, 0
    live = [t for t in tendons if not t.get("_deleted")
            and len(t.get("profile") or []) >= 2]
    moved = stuck = 0
    for i, t in enumerate(live):
        for o in live[i + 1:]:
            for k in (0, -1):
                for m in (0, -1):
                    a = t["profile"][k]["pos"]
                    b = o["profile"][m]["pos"]
                    if dist(a, b) >= clear:
                        continue
                    if _pull_anchor_back(o, m, clear, params):
                        moved += 1
                    elif _pull_anchor_back(t, k, clear, params):
                        moved += 1
                    else:
                        stuck += 1
    if job and moved:
        job.ok(f"{moved} anchorage(s) were sitting within {clear * 1000:.0f} "
               f"mm of another tendon's anchorage and were pulled back along "
               f"their own tendon. Two anchorages on one point read as a "
               f"single tendon turning a corner, in this program and in RAM.")
    if job and stuck:
        job.warn(f"{stuck} pair(s) of anchorages share a point and neither "
                 f"tendon could give up the length - they came in with the "
                 f"model. Move one of each pair in the editor.")
    return moved, stuck


def _pull_anchor_back(t, k, need, params):
    """بيرجّع الطرف `k` على طول الكابل مسافة `need` لو الطول بيسمح."""
    if not _ours(t):
        return False
    pr = t.get("profile") or []
    if len(pr) < 2:
        return False
    j = 1 if k == 0 else len(pr) - 2
    a, b = pr[k]["pos"], pr[j]["pos"]
    leg = dist(a, b)
    floor = float(getattr(params, "min_tendon_length", 6.0) or 0.0)
    if leg <= need + 0.10:
        return False
    if _plan_length(t) - need < floor:
        return False
    f = need / leg
    pr[k]["pos"] = (a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f)
    pr[k].pop("_s", None)
    return True


def tendon_void_hits(tendons, site):
    """الكابلات اللي ليها عقدة جوّه فتحة - (الكابل, عدد العقد)."""
    openings = (site or {}).get("openings") or []
    if not openings:
        return []
    out = []
    for t in tendons:
        if t.get("_deleted"):
            continue
        n = 0
        for q in (t.get("profile") or []):
            x, y = q["pos"]
            if any(op and point_in_polygon(x, y, op) for op in openings):
                n += 1
        if n:
            out.append((t, n))
    return out


def clear_tendons_of_voids(tendons, params, job=None, site=None):
    """
    عقدة جوّه فتحة = دكت ماشية في الهوا. الكابل بيتقص عند الفتحة
    والجزء الأطول هو اللي بيفضل؛ ولو الاتنين أقصر من الحد بيتشال كله.
    """
    hits = tendon_void_hits(tendons, site)
    if not hits:
        return 0, 0
    openings = (site or {}).get("openings") or []
    boundary = (site or {}).get("boundary") or []
    floor = float(getattr(params, "min_tendon_length", 6.0) or 0.0)
    trimmed = dropped = 0
    for t, _n in hits:
        if not _ours(t):
            continue
        pr = t["profile"]
        runs, cur = [], []
        for q in pr:
            if _on_slab(q["pos"], boundary, openings):
                cur.append(q)
            else:
                if len(cur) >= 2:
                    runs.append(cur)
                cur = []
        if len(cur) >= 2:
            runs.append(cur)
        best = max(runs, key=lambda r: sum(
            dist(r[i]["pos"], r[i + 1]["pos"]) for i in range(len(r) - 1)),
            default=None)
        L = 0.0 if best is None else sum(
            dist(best[i]["pos"], best[i + 1]["pos"])
            for i in range(len(best) - 1))
        if best is None or L < floor:
            t["_deleted"] = True
            dropped += 1
            continue
        if len(best) != len(pr):
            best[0] = dict(best[0], sag=False, high=False)
            best[-1] = dict(best[-1], sag=False, high=False)
            t["profile"] = best
            t["length"] = L
            trimmed += 1
    if job and (trimmed or dropped):
        job.warn(f"{trimmed + dropped} tendon(s) had a node inside an "
                 f"opening - a duct across thin air. {trimmed} were cut back "
                 f"to the concrete either side and {dropped} were taken out "
                 f"because what was left was under the {floor:g} m minimum.")
    return trimmed, dropped


def tendons_in_beam_shadow(tendons, site, params, reach=None, share=0.5):
    """
    الكابلات اللي ماشية **في ظل كمرة ساقطة** - موازية لها وجنبها.

    **قاعدة المهندس**: الكمرة الساقطة ركيزة زي الحيطة والعمود. البلاطة
    بتشيل **بينها**، فالكابل الماشي جنب كمرة عرضه الحامل يقرب من
    الصفر: بيوزن حِمل مافيش، وبيدفع حديد على الفاضي. الحديد اللي مكانه
    خط الكمرة بيتحط **جوّه الكمرة** (كابل كمرة بغطسة عمقها)، مش في
    البلاطة جنبها.

    مش قاعدة بتمسح: 21% من حديد أول تخطيط حقيقي كان كده، ومسح الحديد
    ده في السكوت أسوأ من رسمه. بترجّع [(الكابل, النسبة, الكمرة)]
    والقرار للمهندس.

    `reach` = لحد كام متر من وش الكمرة يعتبر ظلها (الافتراضي: البحر
    المجاور/4، بحد أدنى 1.5 م). `share` = نسبة الطول اللي فوقها يتقال.
    """
    if not bool(getattr(params, "beam_shadow_check", True)):
        return []
    on_beams, _why = beams_are_downstand(site or {}, params)
    if not on_beams:
        return []                      # كمرة مخفية مش ركيزة خطية
    beams = [b for b in ((site or {}).get("beams") or [])
             if b.get("p1") and b.get("p2")]
    if not beams:
        return []
    far = float(reach if reach is not None
                else getattr(params, "beam_shadow_reach", 1.5) or 1.5)
    lim = float(getattr(params, "beam_parallel_deg", 30.0) or 30.0)
    out = []
    for t in tendons:
        if t.get("_deleted") or t.get("band"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        inside = total = 0
        who = None
        for a, c in zip(pr, pr[1:]):
            ux = c["pos"][0] - a["pos"][0]
            uy = c["pos"][1] - a["pos"][1]
            un = math.hypot(ux, uy)
            if un < 1e-9:
                continue
            steps = max(int(un / 0.25), 1)
            for k in range(steps):
                f = (k + 0.5) / steps
                x = a["pos"][0] + f * ux
                y = a["pos"][1] + f * uy
                total += 1
                for b in beams:
                    p1, p2 = b["p1"], b["p2"]
                    bx, by = p2[0] - p1[0], p2[1] - p1[1]
                    bn = math.hypot(bx, by)
                    if bn < 1e-9:
                        continue
                    cos = abs((ux / un) * (bx / bn) + (uy / un) * (by / bn))
                    ang = math.degrees(math.acos(max(-1.0, min(1.0, cos))))
                    if ang > lim:
                        continue
                    half = max(float(b.get("width", 300.0) or 300.0),
                               100.0) / 2000.0
                    d = point_to_segment_dist(x, y, p1[0], p1[1],
                                              p2[0], p2[1]) - half
                    if d < far:
                        inside += 1
                        who = b
                        break
        frac = inside / float(total or 1)
        if frac >= share and who is not None:
            out.append((t, frac, who))
    return out


def beam_shadow_ids(tendons, site, params):
    """
    `id()` الكابلات اللي في ظل كمرة ساقطة - عشان قرار الحديد يسأل مرة
    واحدة بدل ما كل دالة تعيد القياس.

    **ليه ده قرار مش تقرير (18.72):** التقرير بيتطبع بعد ما الحديد
    اتوزّع خلاص. على موديل المهندس (1752) حلقة الـ EFM زوّدت 31
    استرند - **4 منهم** راحوا لكابلين ماشيين في ظل كمرة 300×700
    (X عند -23.30 و-22.90، كل واحد 4 -> 6). الكابل ده عرضه الحامل
    قريب من الصفر لأن الكمرة جنبه شايلة، فالاسترند اللي فيه بيدي ضغط
    محوري وبس - والقطاع الراسب بيفضل راسب، فالدورة اللي بعدها بتزوّد
    تاني. الترتيب لازم يعرف ده قبل ما يوزّع، مش بعديه.
    """
    try:
        return {id(t) for t, _f, _b in
                tendons_in_beam_shadow(tendons, site, params)}
    except Exception:
        return set()


def report_beam_shadow(tendons, site, params, job=None):
    """بيقول اللي في الظل بالإحداثي والحديد. مابيمسحش."""
    bad = tendons_in_beam_shadow(tendons, site, params)
    if not bad or not job:
        return len(bad)
    strands = sum(int(t.get("strands") or 0) for t, _f, _b in bad)
    total = sum(int(t.get("strands") or 0) for t in tendons
                if not t.get("_deleted")) or 1
    job.flag(f"{len(bad)} tendon(s) carrying {strands} strand(s) "
             f"({100.0 * strands / total:.0f}% of the floor's) run alongside "
             f"a downstand beam for most of their length. The beams here are "
             f"supports: the slab spans BETWEEN them, so a tendon laid beside "
             f"one has almost no width to carry and balances almost nothing - "
             f"it buys precompression and little else. Steel on a beam line "
             f"belongs IN the beam, profiled to the beam's depth, where the "
             f"drape is several times the slab's. Nothing has been deleted: "
             f"that is a design decision, and 21% of a floor's strand is not "
             f"something to remove in silence.")
    for t, frac, b in bad[:8]:
        pr = t.get("profile") or []
        job.info(f"    {int(t.get('strands') or 0)} strand(s) at "
                 f"({pr[0]['pos'][0]:.1f}, {pr[0]['pos'][1]:.1f}) - "
                 f"{100.0 * frac:.0f}% of its length beside the beam from "
                 f"({b['p1'][0]:.1f}, {b['p1'][1]:.1f}) to "
                 f"({b['p2'][0]:.1f}, {b['p2'][1]:.1f})")
    return len(bad)


def beam_clearance_breaches(tendons, params, site, only_ours=True):
    """
    الكابلات اللي ماشية على كمرة أقرب من `edge_offset` من وش الكمرة.

    المسافة بتتقاس من **وش** الكمرة مش من محورها - كمرة 300 مم محورها
    على بُعد 150 مم من وشها، وقياس على المحور بيبلّغ عن كابلات سليمة.
    الكابل المتعلّم `band` بيمشي جوّه الكمرة عن قصد وبيتستثنى.
    """
    beams = (site or {}).get("beams") or []
    if not beams:
        return []
    want = float(getattr(params, "edge_offset", 0.30) or 0.0)
    #  **18.56: الكابل اللي بيقطع الكمرة مش الكابل اللي ماشي عليها.**
    #  القاعدة كانت بتقيس أقرب مسافة من أي نقطة لأي كمرة وخلاص. على
    #  أول تخطيط حقيقي بلّغت عن 21 كابل من 24 - **17 منهم الزاوية
    #  بينهم وبين الكمرة 90 درجة**، يعني قطع عمودي، وهو اللي كل كابل
    #  لازم يعمله. و41 كابل في رن المهندس اتزحلقوا 30 سم بسببها،
    #  والزحلقة بتشيل القمم من على الأعمدة - يعني القاعدة كانت بتكسر
    #  اللي هي موجودة تحميه.
    _lim = getattr(params, "beam_parallel_deg", None)
    lim = float(30.0 if _lim in (None, "") else _lim)
    out = []
    for t in tendons:
        if t.get("_deleted") or t.get("band"):
            continue
        if only_ours and not _ours(t):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        worst, who = 1e9, None
        for b in beams:
            half = max(float(b.get("width", 300.0) or 300.0), 100.0) / 2000.0
            p1, p2 = b["p1"], b["p2"]
            bx, by = p2[0] - p1[0], p2[1] - p1[1]
            bn = math.hypot(bx, by)
            if bn < 1e-9:
                continue
            bx, by = bx / bn, by / bn
            #  القياس على القطع مش على النقط: كابل ماشي على كمرة ونقطه
            #  متباعدة 3 أمتار ممكن ما تكونش أي نقطة منهم قريبة، وهو
            #  ماشي فوقها بطوله.
            for a, c in zip(pr, pr[1:]):
                ux, uy = c["pos"][0] - a["pos"][0], c["pos"][1] - a["pos"][1]
                un = math.hypot(ux, uy)
                if un < 1e-9:
                    continue
                cos = abs((ux / un) * bx + (uy / un) * by)
                ang = math.degrees(math.acos(max(-1.0, min(1.0, cos))))
                if ang > lim:
                    continue                 # عابر، مش ماشي عليها
                d = min(
                    point_to_segment_dist(a["pos"][0], a["pos"][1],
                                          p1[0], p1[1], p2[0], p2[1]),
                    point_to_segment_dist(c["pos"][0], c["pos"][1],
                                          p1[0], p1[1], p2[0], p2[1]),
                    point_to_segment_dist(p1[0], p1[1], a["pos"][0],
                                          a["pos"][1], c["pos"][0],
                                          c["pos"][1]),
                    point_to_segment_dist(p2[0], p2[1], a["pos"][0],
                                          a["pos"][1], c["pos"][0],
                                          c["pos"][1])) - half
                if d < worst:
                    worst, who = d, b
        if who is not None and worst < want:
            out.append((t, max(worst, 0.0), who))
    return out


def clear_tendons_of_beams(tendons, params, job=None, site=None):
    """
    الكابل المضاف اللي واقف أقرب من `edge_offset` من وش كمرة بيتزحلق
    بعيد عنها لو المكان يسمح.

    الزحلقة بتتلغي لو الخط الجديد بيخرج من البلاطة أو بيدخل فتحة أو
    بيقرّب من كابل موازي أقل من الحد الأدنى - ساعتها بيتقال بالإحداثي
    وخلاص، لأن تحريكه لمكان أسوأ مش إصلاح.
    """
    bad = beam_clearance_breaches(tendons, params, site)
    if not bad:
        return 0, 0
    want = float(getattr(params, "edge_offset", 0.30) or 0.0)
    gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.0)
    boundary = (site or {}).get("boundary") or []
    openings = (site or {}).get("openings") or []
    shifted = left = 0
    for t, have, b in bad:
        u = _plan_axis(t)
        if u is None:
            left += 1
            continue
        nrm = (-u[1], u[0])
        mid = t["profile"][len(t["profile"]) // 2]["pos"]
        p1, p2 = b["p1"], b["p2"]
        #  الجهة اللي الكابل فيها بالنسبة للكمرة: المتجه من أقرب نقطة
        #  على محور الكمرة للكابل نفسه. الإشارة بتتاخد منه مباشرة -
        #  حساب الجهة بضرب اتجاهين (نسخة أولى) كان بيطلع عكسها في نص
        #  الحالات فيزحلق الكابل **ناحية** الكمرة.
        bx, by = p2[0] - p1[0], p2[1] - p1[1]
        bl = bx * bx + by * by
        f = 0.0 if bl <= 1e-12 else max(0.0, min(
            1.0, ((mid[0] - p1[0]) * bx + (mid[1] - p1[1]) * by) / bl))
        wx = mid[0] - (p1[0] + f * bx)
        wy = mid[1] - (p1[1] + f * by)
        sgn = 1.0 if (nrm[0] * wx + nrm[1] * wy) >= 0 else -1.0
        go = (want - have) + 0.01
        cand = [(q["pos"][0] + sgn * nrm[0] * go,
                 q["pos"][1] + sgn * nrm[1] * go) for q in t["profile"]]
        if any(not _on_slab(q, boundary, openings) for q in cand):
            left += 1
            continue
        _d, near = nearest_parallel(t, [q for q in tendons
                                        if q is not t
                                        and not q.get("_deleted")])
        if near is not None:
            d = min(dist(q, r["pos"]) for q in cand
                    for r in (near.get("profile") or []))
            if d < gap:
                left += 1
                continue
        for q, pos in zip(t["profile"], cand):
            q["pos"] = pos
            q.pop("_s", None)
        t["coord"] = (t["profile"][0]["pos"][1] if t.get("dir") == "X"
                      else t["profile"][0]["pos"][0])
        shifted += 1
    if job and shifted:
        job.ok(f"{shifted} tendon(s) were running closer to a beam "
               f"face than the {want:g} m the settings ask for and were "
               f"moved off it.")
    if job and left:
        job.warn(f"{left} tendon(s) are closer to a beam face than "
                 f"{want:g} m and could not be moved - the room beside them "
                 f"is taken by the slab edge, an opening or another tendon.")
        for t, have, _b in bad[:6]:
            c = t["profile"][len(t["profile"]) // 2]["pos"]
            job.warn(f"    {have * 1000:.0f} mm clear near "
                     f"({c[0]:.1f}, {c[1]:.1f})")
    return shifted, left


def enforce_plan_rules(tendons, params, job=None, site=None):
    """
    قواعد المسقط الأفقي، بالترتيب اللي بيخلّي كل واحدة تشتغل على ناتج
    اللي قبلها:

      1. الكابل يخرج من الفتحة الأول - القصّ بيغيّر الطول، وقواعد
         الطول بعديه.
      2. الوصل على نفس الاستقامة - قبل فلتر الطول، عشان قطعتين 4 م
         يبقوا كابل 11 م بدل ما الاتنين يتشالوا.
      3. التمديد للحافة - بعد الوصل، عشان الطرف اللي اتوصّل مابقاش طرف.
      4. فلتر الطول.
      5. فصل المرساتين، آخر حاجة - لأن كل اللي فوق بيحرّك أطراف.

    بتترجع قبل `enforce_profile_rules` عن قصد: كل تحريك هنا بيغيّر
    البحور، وقواعد البروفايل هي اللي بترجّع الغطسة لنص بحرها الجديد.
    """
    if not tendons:
        return {}
    out = {}
    if bool(getattr(params, "plan_rules", True)) is False:
        return out
    try:
        out["void_trim"], out["void_drop"] = clear_tendons_of_voids(
            tendons, params, job, site)
    except Exception as e:
        if job:
            job.warn(f"The opening check was skipped ({e}).")
    try:
        out["merged"] = merge_collinear_tendons(tendons, params, job, site)
    except Exception as e:
        if job:
            job.warn(f"The collinear join was skipped ({e}).")
    try:
        out["extended"] = extend_stub_ends(tendons, params, site, job)
    except Exception as e:
        if job:
            job.warn(f"The short-stub extension was skipped ({e}).")
    try:
        out["short"], out["short_moved"] = drop_short_tendons(
            tendons, params, job)
    except Exception as e:
        if job:
            job.warn(f"The minimum-length check was skipped ({e}).")
    try:
        out["off_beam"], out["on_beam"] = clear_tendons_of_beams(
            tendons, params, job, site)
    except Exception as e:
        if job:
            job.warn(f"The beam clearance check was skipped ({e}).")
    try:
        out["beam_shadow"] = report_beam_shadow(tendons, site, params, job)
    except Exception as e:
        if job:
            job.warn(f"The beam-shadow check was skipped ({e}).")
    try:
        out["anchors"], out["anchors_stuck"] = separate_shared_ends(
            tendons, params, job)
    except Exception as e:
        if job:
            job.warn(f"The anchorage separation was skipped ({e}).")
    #  الكابل المشال بيخرج من القايمة هنا، مش بعلامة بس: الكاتب بيمشي
    #  على القايمة زي ما هي، وكل قاعدة بعد دي بتقيس على الباقي.
    tendons[:] = [t for t in tendons if not t.get("_deleted")]
    return out


def write_tendons_to_ram(session: RamSession, tendons, job: Job,
                         params: TendonDesignParams, drops=None, site=None):
    """
    Draw the tendons.

    Every profile point is held internally as a depth below the top surface -
    one unambiguous frame - and converted here to the datum the user chose.
    """
    #  الحوائط والكمرات ركائز زي الدروب: الكابل بيمشي فوق على طولها.
    _sup = []
    for key in ("walls", "beams"):
        for w in (site or {}).get(key, []) or []:
            try:
                _sup.append(((w["p1"][0], w["p1"][1]), (w["p2"][0], w["p2"][1])))
            except Exception:
                continue
    try:
        _shapes = _support_shapes(site or {})
    except Exception:
        _shapes = []
    _sync_min_radius_from_model(session, params, job)   # 17.22
    try:
        shape_band_runs(tendons, site, params, job)     # 17.57
    except Exception as _e:
        job.warn(f"The tendons along band beams were left as designed ({_e}).")
    #  18.28: قواعد المسقط الأفقي قبل قواعد البروفايل - كل واحدة فيها
    #  بتحرّك طرف أو بتقص أو بتوصّل، وقواعد البروفايل هي اللي بترجّع
    #  الغطسة لنص بحرها بعد ما البحر يتغيّر.
    enforce_plan_rules(tendons, params, job, site=site)
    enforce_profile_rules(tendons, params, job, drops=drops, walls=_sup,
                          shapes=_shapes)
    _LAST_DRAWN["tendons"] = tendons                   # 17.27
    _LAST_DRAWN["params"] = params
    Point2D = session.api["Point2D"]
    LineSegment2D = session.api["LineSegment2D"]
    ref = resolve_elevation_refs(session.api["ElevationReference"], job,
                                 wanted=params.elevation_reference)
    ref_name = ref["name"]
    drops = drops or []

    cad = session.model.cad_manager
    lat_layer, lon_layer = pick_tendon_layers(cad, job)
    #  17.57: الغطسة جوّه كمرة عريضة بتتقاس من بطن الكمرة
    _band_th = [(band_outline(b), float(b.get("depth") or 0.0))
                for b in ((site or {}).get("beams") or []) if b.get("band")]

    #  18.07: سُمك البلاطة من الموديل نفسه، مش من الإعدادات. على
    #  01-PART-9-FIRST H (بلاطة 240 والإعدادات على 280) الغطسة المقروءة
    #  190 من السطح اتكتبت "90 فوق الغطاء السفلي" (280-190) - يعني 150
    #  في بلاطة 240 - وكل قراية/كتابة بعدها بتخسر 40 مم تاني: بعد
    #  التخفيف طلعت 130 فوق الغطاء = 110 من السطح، غطسة فوق نص السمك.
    _site_slabs = []
    for _s in ((site or {}).get("slabs") or []):
        try:
            _pts = _s.get("points") or []
            _th = float(_s.get("thickness") or 0.0)
            if len(_pts) >= 3 and _th > 0:
                _drop = bool(_s.get("is_drop")) or int(_s.get("priority") or 1) > 1
                _site_slabs.append((_pts, _th, _drop))
        except Exception:
            continue
    _site_drops = [z for z in _site_slabs if z[2]]
    _site_base = [z for z in _site_slabs if not z[2]]

    def local_thickness(pos):
        for cor, dth in _band_th:
            if cor and dth > 0 and point_in_polygon(pos[0], pos[1], cor):
                return dth
        for _pts, _th, _d in _site_drops:
            if point_in_polygon(pos[0], pos[1], _pts):
                return _th
        for _pts, _th, _d in _site_base:
            if point_in_polygon(pos[0], pos[1], _pts):
                return _th
        for dp in drops:
            if point_in_polygon(pos[0], pos[1], dp):
                return params.drop_thickness
        return params.slab_thickness

    members = {}
    EnumRef = session.api["ElevationReference"]
    for name in ("ABOVE_TOP_COVER", "ABOVE_BOTTOM_COVER"):
        try:
            members[name] = getattr(EnumRef, name)
        except Exception:
            members[name] = ref["member"]

    def _near_drop_edge(pos, clear=0.75):
        """النقطة على بُعد أقل من clear من حافة أي دروب (جوّه أو برّه)."""
        x, y = pos
        for dp in drops:
            n = len(dp)
            for i in range(n):
                ax, ay = dp[i]
                bx, by = dp[(i + 1) % n]
                dx, dy = bx - ax, by - ay
                L2 = dx * dx + dy * dy
                t = 0.0 if L2 <= 1e-12 else max(0.0, min(1.0, ((x - ax) * dx + (y - ay) * dy) / L2))
                if math.hypot(x - (ax + t * dx), y - (ay + t * dy)) < clear:
                    return True
        return False

    def datum_for(point):
        """
        Hogging regions are dimensioned from the top, sagging regions from the
        bottom - that is how a PT profile is detailed and how the two cover
        values on the Geometry page are meant. So each point carries its own
        datum instead of forcing one datum on the whole tendon.

        High points, anchors and inflection points -> Top Cover.
        Sag points at midspan                       -> Bottom Cover.

        17.79: never a bottom datum within 0.75 m of a drop panel's edge. The
        value is worked out from OUR idea of the thickness there; RAM applies
        it to whichever slab area it resolves the point to, and on the edge
        the two disagree by the drop's extra depth (a 250 slab and a 450 drop:
        a low point meant 175 mm down landed 335 mm down - a kink that read
        10 MPa in the section beside it, on every floor with drops). The top
        surface is continuous, so a Top Cover value is the same everywhere.
        """
        if params.per_point_datum:
            if point.get("sag") and not _near_drop_edge(point["pos"]):
                return "ABOVE_BOTTOM_COVER"
            return "ABOVE_TOP_COVER"
        return ref_name

    #  18.21: مفيش نقطة على 5 مم. القص القديم كان بيحوّل أي عمق أعمق من
    #  السُمك المحلي (غطسة على عمق الدروب مكتوبة خارج الدروب، أو عمق
    #  متحسب على سُمك الإعدادات) لـ "5 فوق الغطاء السفلي" في صمت. دلوقتي
    #  النقطة بتاخد المستوى اللي ظروفها بتقوله: الطرف في نص السُمك، والغطسة
    #  على الغطاء السفلي، والقمة على الغطاء العلوي - وبيتقال في اللوج.
    #  **18.89: الحدّ هو الغطاء، مش 5 مم من الوش.**
    #  المهندس شاف عقدة مكتوب عندها 15 وسأل عنها، وقال إنه غيّر سُمك
    #  البلاطة بعد الرن وبعدين شغّل حلقة. والحساب بيطابق كلامه بالضبط:
    #  قواعد البروفايل بتحسب عمق الغطسة من **`params.slab_thickness`**
    #  (الإعداد)، والكاتب بيحوّل للمنسوب بـ **`local_thickness`** (سُمك
    #  الموديل عند النقطة). لما الاتنين يختلفوا:
    #
    #      الإعداد 270، الغطاء السفلي 35  ->  العمق = 235
    #      الموديل عنده 250              ->  المكتوب = 250 - 235 = 15
    #
    #  والفحص القديم كان بيسمح بيها: 235 أقل من 245 (يعني h-5).
    #  الحدّ الصح هو الغطاء نفسه، وبالسُمك المحلي - ودي نقطة واحدة كل
    #  المسارات بتعدّي منها، فبتمسك الفرق مهما كانت القاعدة اللي جابته.
    _fixed = {"deep": 0, "high": 0, "cover": 0, "worst": 0.0,
              "where": None, "set_h": 0.0, "loc_h": 0.0}

    def sane_depth(point, tendon=None, is_end=False):
        h = local_thickness(point["pos"])
        d = float(point.get("depth") or 0.0)
        tc, bc = params.covers_for((tendon or {}).get("dir", "X"))
        if d > h - 5.0:
            _fixed["deep"] += 1
            if is_end:
                return h / 2.0
            return max(h - float(bc), h / 2.0 + 5.0)
        if d < 5.0:
            _fixed["high"] += 1
            if is_end:
                return h / 2.0
            return min(float(tc), h / 2.0 - 5.0)
        if is_end:
            return d
        d2, off = depth_inside_covers(d, h, tc, bc)
        if off > 0:
            _fixed["cover"] += 1
            if off > _fixed["worst"]:
                _fixed["worst"] = off
                _fixed["where"] = point["pos"]
                _fixed["set_h"] = float(getattr(params, "slab_thickness",
                                                0.0) or 0.0)
                _fixed["loc_h"] = h
            return d2
        return d

    for _t in tendons:
        _pr = _t.get("profile") or []
        for _i, _q in enumerate(_pr):
            _q["depth"] = sane_depth(_q, _t, is_end=(_i == 0 or _i == len(_pr) - 1))
    if job and _fixed["cover"]:
        job.flag(
            f"{_fixed['cover']} profile point(s) were placed closer to a "
            f"face than the cover allows and have been pulled back onto it. "
            f"The profile rules work the depth out from the SETTINGS slab "
            f"thickness; the elevation that goes into the model is worked "
            f"out from the thickness AT THAT POINT. When the two differ - "
            f"the setting changed after the model was built, or the point "
            f"sits on a drop or a beam - the difference lands entirely on "
            f"the cover. The worst here was "
            f"{_fixed['worst']:.0f} mm"
            + (f" at ({_fixed['where'][0]:.2f}, {_fixed['where'][1]:.2f})"
               if _fixed["where"] else "")
            + (f", where the setting says {_fixed['set_h']:.0f} mm and the "
               f"model is {_fixed['loc_h']:.0f} mm."
               if abs(_fixed["set_h"] - _fixed["loc_h"]) > 1.0 else ".")
            + " Run the model against your settings (the thickness row) "
              "before a loop, so the two are the same number.")
    if job and (_fixed["deep"] or _fixed["high"]):
        job.warn(f"{_fixed['deep']} profile point(s) sat deeper than the slab under "
                 f"them and {_fixed['high']} above its top; each was put where its "
                 f"kind belongs - ends at mid-depth, low points on the bottom cover, "
                 f"high points on the top cover - instead of being pinned 5 mm from a "
                 f"surface. A dip written at a drop panel's depth outside the panel is "
                 f"the usual cause: check the drop outlines in the model.")

    def value_for(point):
        h = local_thickness(point["pos"])
        name = datum_for(point)
        v = elevation_value(point["depth"], name, h)
        lo = elevation_value(h - 5.0, name, h)
        hi = elevation_value(5.0, name, h)
        v = max(min(v, max(lo, hi)), min(lo, hi))
        #  **18.84: التقريب ناحية نص السمك، مش لأقرب رقم.** التقريب
        #  لأقرب 5 مم مع المرجع السفلي بيقدر يعمّق الغطسة 2.5 مم بعد ما
        #  `enforce_min_radius` رفعها بالظبط للحد - فاللفّة ترجع تحت
        #  الحد ورام يحذّر من نفس العقدة تاني.
        kind = ("sag" if point.get("sag")
                else "high" if point.get("high") else "")
        v = elevation_round_for_kind(v, params.elevation_rounding, name, kind)
        v = max(min(v, max(lo, hi)), min(lo, hi))
        return v, name

    def apply_elevations(seg, p1, p2):
        for idx, pt in ((1, p1), (2, p2)):
            val, name = value_for(pt)
            try:
                setattr(seg, f"elevation_reference_{idx}",
                        members.get(name, ref["member"]))
            except Exception:
                pass
            setattr(seg, f"elevation_value_{idx}", float(val))
            #  اللي اتكتب فعلاً - عشان نعيد قياس نصف القطر عليه
            pt["_written_depth"] = depth_from_elevation(
                val, name, local_thickness(pt["pos"]))
            pt["_written_ref"] = name

    if params.per_point_datum:
        job.ok("Datum per point: high points, anchors and inflections are "
               "written against Top Cover; midspan sag points against "
               "Bottom Cover.")

    job.ok(f"Anchor: {params.anchor_elevation:.0f} mm Top Cover "
           f"(half the base slab thickness {params.slab_thickness:.0f} mm).")
    for d in ("X", "Y"):
        tc, bc = params.covers_for(d)
        job.info(f"Direction {d}: high point {tc:.0f} mm Top Cover   ·   "
                 f"sag {bc:.0f} mm Bottom Cover   "
                 f"(exactly the values entered).")
    if params.elevation_rounding:
        job.info(f"Elevations rounded to the nearest "
                 f"{params.elevation_rounding:g} mm.")

    drawn = 0
    failed = 0
    #  لو الموديل رفض أول عشرين قطعة ورا بعض، مفيش فايدة من 1200 محاولة
    #  تانية. اللي حصل في رن 12:43: كل القطع فشلت، والجاكات فشلت،
    #  وgenerate_mesh فشل - يعني الجلسة نفسها باظت مش قطعة بعينها.
    #  البرنامج فضل ماشي لآخره وحفظ موديل فيه صفر كابل وقال "Audit passed".
    run_fail = 0
    job.step(0.80, "Drawing tendons into the model")
    _skipped_inflection = 0
    #  **18.52: المرحلة دي بتتقاس، مش بتتحمل.** الكتابة بتاخد دقايق
    #  والسبب مش بايثون: كل قطعة كابل فيها نداء إنشاء + عدد الاسترندات
    #  + أربع مناسيب = ست رحلات كاملة لرام. القياس بيحوّل "بطيء" لرقم:
    #  لو المعدّل قطعتين في الثانية فده رام، ولو أقل بكتير فده احنا.
    _t0 = time.time()
    _segs = sum(max(len(nodes_to_draw(t.get("profile") or [])) - 1, 0)
                for t in tendons)
    job.info(f"{len(tendons)} tendon(s) with {_segs:,} segment(s) between "
             f"them. RAM is called about six times per segment - the "
             f"segment itself, its strand count and its four elevation "
             f"values - so this stage is roughly {_segs * 6:,} calls into "
             f"the model, and minutes rather than seconds on a floor this "
             f"size. Every point the layout carries is paid for here.")

    for i, t in enumerate(tendons):
        if i % 25 == 0:
            job.check()
            _gone = time.time() - _t0
            _rate = (drawn / _gone) if (_gone > 1.0 and drawn) else 0.0
            _left = ((_segs - drawn) / _rate) if _rate > 0 else 0.0
            job.step(0.80 + 0.06 * i / max(len(tendons), 1),
                     f"Drawing tendons {i}/{len(tendons)}"
                     + (f" - {drawn:,}/{_segs:,} segments, {_rate:.1f}/s, "
                        f"about {_left / 60.0:.1f} min left"
                        if _rate > 0 else ""))
        layer = lat_layer if t["dir"] == "X" else lon_layer
        profile = nodes_to_draw(t["profile"])
        _skipped_inflection += len(t["profile"]) - len(profile)
        for k in range(len(profile) - 1):
            p1, p2 = profile[k], profile[k + 1]
            if dist(p1["pos"], p2["pos"]) < 1e-4:
                continue
            try:
                seg = layer.add_tendon_segment(LineSegment2D(
                    Point2D(p1["pos"][0], p1["pos"][1]),
                    Point2D(p2["pos"][0], p2["pos"][1])))
                seg.strand_count = int(t["strands"])
                #  **علامة تعيش بعد الحفظ.** جدول Tendon في الملف فيه
                #  عمود Name فاضي، والكابل المضاف كان بيتكتب بلا اسم -
                #  فأول ما الموديل يتقفل ويتفتح تاني، مافيش طريقة
                #  نعرف بيها مين كابل المهندس ومين كابل الحلقة. النتيجة
                #  إن تنظيف الكابلات الملزوقة مااشتغلش ولا مرة على
                #  موديل اتقرا من القرص: الأزواج اللي تحت 40 سم فضلت
                #  مكانها لأن ولا واحد فيهم متعلّم إنه مضاف.
                if t.get("added"):
                    try:
                        seg.name = ADDED_TAG
                    except Exception:
                        pass
                apply_elevations(seg, p1, p2)
                drawn += 1
                run_fail = 0
            except Exception as e:
                failed += 1
                run_fail += 1
                if failed <= 5:
                    job.warn(f"A tendon segment was not drawn: {e}")
                if run_fail == 12 and drawn == 0:
                    #  محاولة واحدة: هات الليّرات من الموديل من جديد.
                    #  بعد مسح جماعي المقبض القديم ممكن يكون بايت.
                    try:
                        lat_layer, lon_layer = pick_tendon_layers(cad, job)
                        layer = lat_layer if t["dir"] == "X" else lon_layer
                        job.warn("Nothing is being accepted - the tendon "
                                 "layers were fetched again from the model "
                                 "and the drawing continues.")
                    except Exception:
                        pass
                if run_fail >= 40 and drawn == 0:
                    raise RuntimeError(
                        f"RAM refused the first {run_fail} tendon segments in "
                        f"a row and nothing has been drawn - so this is the "
                        f"model, not one bad tendon, and carrying on would "
                        f"save a file with no tendons in it. If this file had "
                        f"its tendons cleared by a version before 6.7, the "
                        f"layer's Category and Level containers were deleted "
                        f"with them and no tendon can ever be added to it "
                        f"again: go back to the model from before that clear, "
                        f"or build it again. Last reason: {e}")

    if drawn == 0 and failed:
        raise RuntimeError(
            f"Not one of the {failed} tendon segments was accepted by RAM. "
            f"The model would be saved empty, so the run is stopping here.")
    if failed:
        job.warn(f"{failed} tendon segments were not drawn "
                 f"(only the first 5 reasons shown).")
    _gone = max(time.time() - _t0, 1e-6)
    job.ok(f"Drew {drawn} tendon segments from {len(tendons)} tendons in "
           f"{_gone:.0f}s - {drawn / _gone:.1f} segments a second, about "
           f"{(drawn * 6) / _gone:.0f} calls into RAM a second. That rate "
           f"is the model's, not this program's: the same loop on this side "
           f"takes under a second for a floor of this size. A layout with "
           f"fewer nodes is the only thing that makes this stage shorter - "
           f"each node is a segment end, and each segment is six calls.")
    if _skipped_inflection:
        job.info(f"    {_skipped_inflection} inflection point(s) were not drawn as "
                 f"nodes: RAM draws each segment between two nodes as two "
                 f"parabolas with its own inflection ratio, and a node 0.2 m "
                 f"from a peak gave it a bend of a few centimetres.")
    #  **18.84: وبعد الكتابة، نصف القطر يتقاس على اللي اتكتب.**
    try:
        covers_survived_writing(tendons, params, local_thickness, job)
    except Exception as _e:
        job.warn(f"The written-cover check did not run ({_e}).")
    try:
        _rd, _rw, _lost = radius_survived_writing(tendons, params, job)
        if _rd is not None and _rw is not None and not _lost:
            job.info(f"    Sharpest bend as designed {_rd:.2f} m, as written "
                     f"into the model {_rw:.2f} m - the rounding kept it.")
    except Exception as _e:
        job.warn(f"The written-elevation radius check did not run ({_e}).")
    return drawn


def write_jacks_to_ram(session, tendons, job, params):
    """
    Place jacks (stressing anchorages) on every tendon.

    One jack at the start when the tendon is shorter than the two-end
    threshold, jacks at both ends when it is longer. Friction and wobble grow
    with length, so a long tendon stressed from one end only loses far too much
    at the far end.

    add_jack exists on TendonLayer but its signature is not documented here, so
    the call is probed once and the working form reported.
    """
    Point2D = session.api["Point2D"]
    LineSegment2D = session.api["LineSegment2D"]
    cad = session.model.cad_manager
    lat_layer, lon_layer = pick_tendon_layers(cad, job)

    known = {"form": None}

    def try_forms(layer, pos, nxt):
        """Return (jack, description) using whichever call shape works."""
        forms = [
            ("Point2D", lambda: layer.add_jack(Point2D(pos[0], pos[1]))),
            ("LineSegment2D", lambda: layer.add_jack(LineSegment2D(
                Point2D(pos[0], pos[1]), Point2D(nxt[0], nxt[1])))),
            ("x, y", lambda: layer.add_jack(pos[0], pos[1])),
        ]
        #  17.67: الشكل اللي نجح أول مرة بيتجرّب الأول في كل جاك بعدها.
        #  كان بيتجرّب بالترتيب الثابت كل مرة، فلو Point2D بتفشل كل جاك
        #  كان بيدفع نداء فاشل زيادة على الرام.
        if known["form"]:
            forms.sort(key=lambda f: f[0] != known["form"])
        errors = []
        for name, fn in forms:
            try:
                obj = fn()
                if obj is not None:
                    return obj, name
            except Exception as e:
                errors.append(f"{name}: {type(e).__name__}: {str(e)[:70]}")
        return None, " | ".join(errors)

    threshold = params.jack_both_ends_over
    placed = 0
    failed = 0
    form_used = None

    job.step(0.86, "Placing jacks")
    for t in tendons:
        job.check()
        layer = lat_layer if t["dir"] == "X" else lon_layer
        prof = t["profile"]
        if len(prof) < 2:
            continue

        ends = [(prof[0]["pos"], prof[1]["pos"])]
        if t["length"] > threshold:
            ends.append((prof[-1]["pos"], prof[-2]["pos"]))
        t["jacks"] = len(ends)

        for pos, nxt in ends:
            obj, info = try_forms(layer, pos, nxt)
            if obj is None:
                failed += 1
                if failed == 1:
                    job.error(f"add_jack failed in every form tried - {info}")
                continue
            known["form"] = info
            if form_used is None:
                form_used = info
                job.info(f"Jacks are created with add_jack({info}). "
                         f"Properties on a jack: {describe_element(obj)}")
            placed += 1

    one = sum(1 for t in tendons if t.get("jacks") == 1)
    two = sum(1 for t in tendons if t.get("jacks") == 2)
    job.ok(f"Jacks: {placed} placed - {one} tendons stressed from one end, "
           f"{two} from both ends (threshold {threshold:g} m).")
    if failed:
        job.warn(f"{failed} jacks could not be created.")
    return placed


def write_design_report(path, site, params: TendonDesignParams, tendons, design):
    """CSV report, one row per tendon, plus a design summary. UTF-8 BOM for Excel."""
    lines = []
    lines.append("# " + APP_NAME + " " + APP_VERSION + " - tendon design report")
    lines.append("# " + datetime.datetime.now().strftime("%Y-%m-%d %H:%M"))
    lines.append("#")
    for s in params.summary_lines():
        lines.append("# " + s)
    lines.append("#")
    for d in ("X", "Y"):
        info = ((design or {}).get("pa") or {}).get(d)
        if info:
            lines.append(f"# Direction {d}: {info['tendons']} tendons · "
                         f"{info['strands']} strands · force {info['force_kN']:,.0f} kN · "
                         f"P/A = {info['pa_MPa']:.3f} MPa")
    for n in design.get("notes", []):
        lines.append("# " + n)
    lines.append("")
    field_run = any(t.get("field") for t in tendons)
    losses_on = any(t.get("losses") for t in tendons)

    cols = ["No", "Direction", "Coordinate (m)", "Source", "Strip",
            "Tributary (m)", "Length (m)", "Strands", "Force (kN)",
            "Governing span (m)", "Required force (kN)"]
    if field_run:
        # A tendon added to fix one bay looked identical to a base tendon of
        # the same length. These say which is which and what sized it.
        cols += ["M hog (kNm/m)", "M sag (kNm/m)", "Swing (kNm/m)",
                 "Covers span (m)"]
    if losses_on:
        cols += ["Total angle (rad)", "Total loss %"]
    banded_run = any(t.get("band_group") or t.get("band_high_points")
                     for t in tendons)
    if banded_run:
        # Which tendons make a band, and which were lifted over one.
        cols += ["In a band", "Band high points"]
    grouped_run = any(t.get("span_groups") for t in tendons)
    if grouped_run:
        # Spans this tendon shares with its neighbours - one schedule line
        # each, however the tendon behaves outside them.
        cols += ["Shared spans", "Shared span count"]
    cols.append("Profile points")
    lines.append(",".join(cols))

    for i, t in enumerate(tendons, 1):
        gov = t["governing"]
        pe = (t["losses"]["force_per_strand"] if t.get("losses")
              else params.force_per_strand)
        row = [
            str(i),
            t["dir"],
            f"{t['coord']:.3f}",
            "infill" if t.get("added") else "base",
            "column" if t.get("strip") == "column" else "middle",
            f"{t['tributary']:.3f}",
            f"{t['length']:.2f}",
            str(t["strands"]),
            f"{pe * t['strands']:.1f}",
            f"{gov.get('span', 0.0):.2f}",
            f"{gov.get('p_req', 0.0):.1f}",
        ]
        if field_run:
            fd = t.get("field") or {}
            span = t.get("covers_span")
            row += [
                f"{fd.get('m_hog', 0.0):.1f}" if fd else "-",
                f"{fd.get('m_sag', 0.0):.1f}" if fd else "-",
                f"{fd.get('swing', 0.0):.1f}" if fd else "-",
                f"{span[0]:.1f} to {span[1]:.1f}" if span else "-",
            ]
        if losses_on:
            row += [
                f"{t['losses']['alpha_rad']:.4f}" if t.get("losses") else "-",
                f"{t['losses']['total_loss_pct']:.1f}" if t.get("losses") else "-",
            ]
        if banded_run:
            row += ["yes" if t.get("band_group") else "no",
                    str(t.get("band_high_points", 0))]
        if grouped_run:
            gids = [str(g) for _a, _b, g in (t.get("span_groups") or [])]
            row += ["G" + "/G".join(gids) if gids else "-", str(len(gids))]
        row.append(str(len(t["profile"])))
        lines.append(",".join(row))

    with open(path, "w", encoding="utf-8-sig") as f:
        f.write("\n".join(lines))
    return path


def _api_segment_ends(loc):
    """
    (start, end) of a LineSegment2D from the API.

    [F12] This used to look for `pt1`/`pt2`. The API names them `start_point`
    and `end_point`, so every lookup returned None, the fallback asked a
    LineSegment2D for `points` - which it does not have - and the walls and
    beams of an existing model came back as EMPTY LISTS. In "tendons only"
    mode that meant a slab with walls and beams was profiled as though it had
    columns and nothing else, silently.
    """
    if loc is None:
        return None
    for a, b in (("start_point", "end_point"), ("pt1", "pt2")):
        p1, p2 = safe_get(loc, a), safe_get(loc, b)
        if p1 is not None and p2 is not None:
            try:
                return ((float(p1.x), float(p1.y)), (float(p2.x), float(p2.y)))
            except Exception:
                continue
    return None


def _api_polygon_points(loc):
    """Points of a Polygon2D from the API, as plain tuples."""
    pts = safe_get(loc, "points")
    if not pts:
        return []
    out = []
    for p in pts:
        try:
            out.append((float(p.x), float(p.y)))
        except Exception:
            continue
    return out


def read_model_structure(session: RamSession, job: Job):
    """
    قراءة الأعمدة والحوائط والكمرات والبلاطات من موديل موجود — بتُستخدم في نمط
    «الكابلات فقط» عشان البروفايل يتبني على المنشأ الحقيقي مش على الرسمة.

    الأسماء هنا مطابقة للـ API:
      StructureLayer: columns_below/above · walls_below/above · beams ·
                      slab_areas · slab_openings
      Column: location · b · d · angle      (b = 0 → عمود دائري قطره d)
      Wall  : location · thickness          Beam: location · width · thickness
      SlabArea: location (Polygon2D) · thickness · priority
    """
    structure = session.model.cad_manager.structure_layer

    columns = []
    for src in ("columns_below", "columns_above"):
        for c in (safe_get(structure, src, []) or []):
            loc = safe_get(c, "location")
            if loc is None:
                continue
            try:
                b = float(safe_get(c, "b", 0.0) or 0.0)
                d = float(safe_get(c, "d", 400.0) or 400.0)
                columns.append({
                    "center": (float(loc.x), float(loc.y)),
                    # [F13] b = 0 is how the API says "round column, diameter d".
                    # Reading it as a 0-wide rectangle put a zero-size support
                    # on every circular column in a model.
                    "b": d if b <= 1e-6 else b,
                    "d": d,
                    "angle_deg": float(safe_get(c, "angle", 0.0) or 0.0),
                    "circular": b <= 1e-6,
                })
            except Exception:
                continue
        # Both lists matter: a column above the slab supports it just as one
        # below does, so they are collected, not stopped at the first hit.

    walls = []
    for src in ("walls_below", "walls_above"):
        for w in (safe_get(structure, src, []) or []):
            pair = _api_segment_ends(safe_get(w, "location"))
            if pair:
                walls.append({"p1": pair[0], "p2": pair[1],
                              "width": float(safe_get(w, "thickness", 250.0) or 250.0)})

    beams = []
    for b in (safe_get(structure, "beams", []) or []):
        pair = _api_segment_ends(safe_get(b, "location"))
        if pair:
            beams.append({"p1": pair[0], "p2": pair[1],
                          "width": float(safe_get(b, "width", 300.0) or 300.0)})

    # [F14] The thickness was read from `structure.slabs`, which does not
    # exist - the API calls it `slab_areas`. So the model's own thickness was
    # never found and the value typed on the Geometry page was used instead,
    # even when the model plainly said otherwise.
    slabs = []
    thicknesses = []
    for slab in (safe_get(structure, "slab_areas", []) or []):
        pts = _api_polygon_points(safe_get(slab, "location"))
        t = safe_get(slab, "thickness")
        try:
            t = float(t) if t is not None else None
        except Exception:
            t = None
        if len(pts) >= 3:
            slabs.append({"points": pts, "thickness": t,
                          "priority": int(safe_get(slab, "priority", 1) or 1)})
        if t and t > 50.0:
            thicknesses.append(t)

    openings = []
    for op in (safe_get(structure, "slab_openings", []) or []):
        pts = _api_polygon_points(safe_get(op, "location"))
        if len(pts) >= 3:
            openings.append(pts)

    main_thickness = None
    if thicknesses:
        candidates = [t for t in thicknesses if t >= 150.0]
        main_thickness = min(candidates) if candidates else max(thicknesses)

    job.info(f"From the model: {len(columns)} columns · {len(walls)} walls · "
             f"{len(beams)} beams · {len(slabs)} slab areas · "
             f"{len(openings)} openings"
             + (f" · slab thickness {main_thickness:.0f} mm" if main_thickness else ""))
    if not walls and not beams and not columns:
        job.warn("The model returned no supports at all. If it does have "
                 "columns or walls, the API is not exposing them under the "
                 "expected names - check the RAM Concept version.")
    return {"columns": columns, "walls": walls, "beams": beams,
            "slabs": slabs, "openings": openings,
            "thickness": main_thickness}


def verify_alignment(site, model_struct, job):
    """
    فحص تطابق إحداثيات الـ DXF مع الموديل.
    ده أخطر مصدر أخطاء في البرنامج: لو الرسمة مرسومة على origin مختلف عن
    الموديل، كل حاجة هتطلع في مكان غلط من غير أي رسالة خطأ.
    """
    dxf_cols = [c["center"] for c in site["columns"]]
    ram_cols = [c["center"] for c in model_struct["columns"]]
    if not dxf_cols or not ram_cols:
        return None

    worst = 0.0
    total = 0.0
    for p in dxf_cols:
        d = min(math.hypot(p[0] - q[0], p[1] - q[1]) for q in ram_cols)
        worst = max(worst, d)
        total += d
    avg = total / len(dxf_cols)

    if worst > 0.5:
        job.warn(f"⚠️ Coordinates do not match: the furthest DXF column is "
                 f"{worst:.2f} m from the nearest model column (average {avg:.2f} m). "
                 f"The drawing is probably on a different origin - tendons will land in the wrong place.")
    else:
        job.ok(f"Coordinates match (max difference {worst:.3f} m).")
    return worst


# ==============================================================================
#  القسم 4ب — كتابة خطوط الركائز في RAM Concept
#
#  ⚠️ ملاحظة صريحة: أسماء دوال الـ Design Strip في الـ API مش موحّدة بين
#  الإصدارات، وأنا مش عندي التوثيق الرسمي (بيتفتح من جوه البرنامج:
#  Help > Scripting API). فالكود هنا بيجرّب مجموعة أسماء محتملة بالترتيب،
#  وبيسجّل بالظبط إيه اللي اشتغل وإيه اللي مالقاهوش. لو فشل، شغّل خيار
#  «تشخيص الـ API» وابعتلي اللي هيتطبع في السجل عشان نثبّت الأسماء الصح.
# ==============================================================================

SUPPORT_LINE_LAYER_NAMES = {
    "X": ["latitude_design_strip_layer", "latitude_support_line_layer",
          "latitude_strip_layer", "lat_design_strip_layer"],
    "Y": ["longitude_design_strip_layer", "longitude_support_line_layer",
          "longitude_strip_layer", "long_design_strip_layer"],
}





def probe_api_package(job: Job):
    """
    المرور على حزمة ram_concept نفسها — مش على كائن مفتوح.

    ده أقوى من فحص cad_manager لوحده: لو الطبقة اسمها مش متوقّع، الكلاس
    بتاعها موجود في الحزمة بأي حال، ومنه نعرف اسم دالة الإضافة الصح.
    """
    try:
        import ram_concept
        import pkgutil
        import importlib
        import inspect
    except Exception as e:
        job.warn(f"[probe] Could not import ram_concept: {e}")
        return {}

    pkg_dir = os.path.dirname(ram_concept.__file__)
    keywords = ("strip", "support", "span", "design")
    hits = {}

    for _, mod_name, _ in pkgutil.iter_modules([pkg_dir]):
        try:
            mod = importlib.import_module(f"ram_concept.{mod_name}")
        except Exception:
            continue
        for cls_name, cls in inspect.getmembers(mod, inspect.isclass):
            if getattr(cls, "__module__", "") != mod.__name__:
                continue
            low = (cls_name + " " + mod_name).lower()
            if any(k in low for k in keywords):
                members = [m for m in dir(cls) if not m.startswith("_")]
                hits[cls_name] = (f"ram_concept.{mod_name}", members)

    # مسح تاني بدون فلترة بالاسم: أي كلاس فيه دالة add_* أو generate_*
    # ممكن يكون هو المدخل الصح حتى لو اسمه مالوش علاقة ظاهرة.
    creators = {}
    for _, mod_name, _ in pkgutil.iter_modules([pkg_dir]):
        try:
            mod = importlib.import_module(f"ram_concept.{mod_name}")
        except Exception:
            continue
        for cls_name, cls in inspect.getmembers(mod, inspect.isclass):
            if getattr(cls, "__module__", "") != mod.__name__:
                continue
            adders = [m for m in dir(cls)
                      if m.startswith(("add_", "generate_", "create_"))]
            if adders:
                creators[f"ram_concept.{mod_name}.{cls_name}"] = adders

    if creators:
        job.info(f"[probe] Every class with create/add methods ({len(creators)}):")
        for path, adders in sorted(creators.items()):
            job.info(f"    {path}: {', '.join(sorted(adders))}")

    if not hits:
        job.warn("[probe] No class in the package is named with "
                 "strip / support / span / design.")
        return {"creators": creators}

    job.ok(f"[probe] Design-strip-like classes in the package ({len(hits)}):")
    for cls_name, (mod_name, members) in sorted(hits.items()):
        job.info(f"    {mod_name}.{cls_name}")
        adders = [m for m in members if m.startswith(("add_", "generate_"))]
        widths = [m for m in members if "width" in m.lower()]
        if adders:
            job.info(f"        add methods: {', '.join(adders)}")
        if widths:
            job.info(f"        width properties: {', '.join(widths)}")
    return hits


def probe_ram_api(session: RamSession, job: Job):
    """
    طباعة الخصائص والدوال المتاحة على الكائنات المهمة — أسرع طريقة نعرف بيها
    أسماء الـ API الصح في إصدارك بدل التخمين.
    """
    def dump(title, obj, filt=None):
        if obj is None:
            job.warn(f"[probe] {title}: not present")
            return
        try:
            names = [a for a in dir(obj) if not a.startswith("_")]
        except Exception as e:
            job.warn(f"[probe] {title}: could not be read ({e})")
            return
        if filt:
            names = [n for n in names if any(k in n.lower() for k in filt)]
        job.info(f"[probe] {title} ({len(names)}): {', '.join(names)}")

    probe_api_package(job)

    cad = session.model.cad_manager
    dump("model", session.model, ["strip", "design", "generate", "calc"])
    dump("cad_manager", cad, ["layer", "strip", "support", "span"])

    for direction in ("X", "Y"):
        layer = None
        for name in SUPPORT_LINE_LAYER_NAMES[direction]:
            layer = safe_get(cad, name)
            if layer is not None:
                job.ok(f"[probe] {direction}-direction layer is: cad_manager.{name}")
                break
        dump(f"{direction} layer", layer)

    for attr in ("design_strip_layers", "strip_layers", "layers"):
        coll = safe_get(cad, attr)
        if coll:
            try:
                job.info(f"[probe] cad_manager.{attr} = "
                         f"{[safe_get(l, 'name', repr(l)) for l in coll]}")
            except Exception:
                pass


def layer_add_methods(obj):
    """Every add_*/create_* method on the object, with no expected-name list."""
    out = []
    for m in dir(obj):
        if m.startswith("_"):
            continue
        if not (m.startswith("add_") or m.startswith("create_") or m.startswith("new_")):
            continue
        try:
            if callable(getattr(obj, m)):
                out.append(m)
        except Exception:
            continue
    return out


def _looks_like_layer(obj):
    """
    هل الكائن ده طبقة؟ = ليه اسم نصّي وأي دالة إضافة كانت.

    النسخة القديمة كانت بتشترط دالة من قايمة أسماء **أنا** كاتبها
    (add_support_line, add_span_segment, ...). يعني طبقة اسم دالتها
    add_design_strip كانت هتتفلتر وماتظهرش في التشخيص أصلاً — وأنا بنيت على
    التشخيص ده استنتاج إن الطبقة مش موجودة. الاستنتاج كان أوسع من الدليل.
    """
    name = safe_get(obj, "name")
    if not isinstance(name, str):
        return False
    return bool(layer_add_methods(obj))


def _call_first(obj, names, *args):
    """Call the first method that exists from a list. Returns (result, name) or (None, None)."""
    for n in names:
        fn = safe_get(obj, n)
        if callable(fn):
            try:
                return fn(*args), n
            except Exception as e:
                raise RuntimeError(f"{n}() failed: {e}")
    return None, None


GENERATE_STRIP_METHODS = ["generate_strips", "generate_design_strips",
                          "generate_all_strips", "auto_generate_strips",
                          "generate_design_sections"]


def generate_strips_in_ram(session, job):
    """
    Ask RAM to build the design strips itself (Process -> Generate Design
    Strips). Its own logic is better than anything we could reconstruct, so
    when it is reachable we always prefer it.
    """
    job.step(0.87, "Generating design strips")
    for target, label in ((session.model, "model"),
                          (session.model.cad_manager, "cad_manager"),
                          (session.concept, "concept")):
        for name in GENERATE_STRIP_METHODS:
            fn = safe_get(target, name)
            if not callable(fn):
                continue
            try:
                fn()
                job.ok(f"Design strips generated by RAM ({label}.{name}).")
                return True
            except Exception as e:
                job.warn(f"{label}.{name}() exists but failed: {e}")
    #  الرسالة القديمة كانت "RAM exposes no strip generation method" وسابتها
    #  غلط دلوقتي: إحنا بنرسم خطوط الركائز فعلاً بأوامر الشجرة، وRAM بيولّد
    #  الشرائح منها لوحده وقت الحساب لأن LockStripGeneration = false.
    job.info("There is no generate-strips call in this API, and none is "
             "needed: RAM rebuilds the design strips from the support lines "
             "every time it calculates. Switch on 'Design strips (support "
             "lines) from the grid' if you want the program to draw those "
             "lines for you.")
    return False


def count_existing_strips(session, job):
    """
    Report the design strips already present in the model, which is what the
    reinforcement pass will read its results from.
    """
    cad = session.model.cad_manager
    found = []
    for attr in sorted(dir(cad)):
        if attr.startswith("_"):
            continue
        try:
            val = getattr(cad, attr)
        except Exception:
            continue
        if callable(val):
            continue
        items = val if isinstance(val, (list, tuple)) else [val]
        for it in items:
            name = safe_get(it, "name")
            if isinstance(name, str) and any(
                    k in name.lower() for k in ("strip", "span", "design")):
                found.append(f"{attr} -> {name}")
    if found:
        job.ok(f"Design strips already in the model ({len(found)}):")
        for f in found[:12]:
            job.info(f"    {f}")
    else:
        job.warn("No design strips are visible through the API. If you drew "
                 "them in RAM they exist in the file, but this API version "
                 "does not expose them, so their results cannot be read.")
    return found


# ==============================================================================
#  القسم 4ج — فحص الموديل، تشغيل التحليل، وتصدير DXF
# ==============================================================================

def point_inside_tol(x, y, poly, tol=0.05):
    """
    داخل المضلع أو على حدوده بتسامح.
    كانت دالة داخلية، وده سبّب NameError لما مسار تنفيذ معيّن مايعدّيش على
    تعريفها. أي دالة مساعدة بيستخدمها generator داخلي لازم تكون على مستوى
    الوحدة — مفيش استثناءات.
    """
    return point_in_polygon(x, y, poly) or point_on_polygon_edge(x, y, poly, tol)


def profile_segment_midpoints(profile):
    """Midpoint of each profile segment. The vertices themselves sit on boundaries."""
    for k in range(len(profile) - 1):
        a, b = profile[k]["pos"], profile[k + 1]["pos"]
        yield ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0)


def audit_model(site, params: TendonDesignParams, tendons, support_lines, design):
    """
    فحص محلي للموديل قبل الكتابة — مش محتاج RAM ولا الـ API.
    بترجع قائمة (المستوى، الرسالة) والمستوى واحد من: error / warn / ok.
    """
    out = []
    boundary = site.get("boundary")


    # ---------- الهندسة ----------
    if not boundary or len(boundary) < 3:
        out.append(("error", "No valid slab boundary."))
        return out

    area = site_plan_area(site) or polygon_area(boundary)
    open_area = sum(polygon_area(o) for o in site.get("openings", []))
    net = area - open_area
    if net <= 0:
        out.append(("error", "Opening area exceeds slab area - check the layer mapping."))
    if area > 20000:
        out.append(("warn", f"Slab area {area:,.0f} m² is unusually large. "
                            f"Check the drawing unit."))
    if area < 5:
        out.append(("error", f"Slab area {area:,.2f} m² is far too small. "
                             f"The drawing unit is probably wrong."))

    # ---------- الركائز ----------
    cols = site.get("columns", [])
    walls = site.get("walls", [])
    if not cols and not walls:
        out.append(("error", "No columns and no walls. The slab cannot be analysed without supports."))
    else:
        # النقطة اللي بالظبط على الحد مش "outside" — لازم تسامح، وإلا كل عمود
        # على محيط البلاطة هيتبلّغ عنه غلط.
        outside = sum(1 for c in cols
                      if not point_inside_tol(c["center"][0], c["center"][1], boundary, 0.30))
        if outside:
            out.append(("warn", f"{outside} columns have their centre outside the slab boundary - "
                                f"probably a coordinate mismatch between the DXF and the model."))
        in_opening = 0
        for c in cols:
            for op in site.get("openings", []):
                if point_in_polygon(c["center"][0], c["center"][1], op) and \
                        not point_on_polygon_edge(c["center"][0], c["center"][1], op, 0.05):
                    in_opening += 1
                    break
        if in_opening:
            out.append(("warn", f"{in_opening} columns fall inside an opening - check the layers."))

        odd = [c for c in cols if min(c.get("b", 0), c.get("d", 0)) < 150
               or max(c.get("b", 0), c.get("d", 0)) > 2500]
        if odd:
            out.append(("warn", f"{len(odd)} columns have unusual dimensions "
                                f"(under 150 mm or over 2500 mm)."))

    # ---------- المقطع ----------
    if params.top_cover + params.bot_cover >= params.slab_thickness:
        out.append(("error", "The two covers together exceed the thickness - no drape available."))
    elif params.drape < 0.05:
        out.append(("warn", f"Only {params.drape * 1000:.0f} mm of drape is available - "
                            f"very little, so a large prestress force will be needed."))

    anchor = params.anchor_elevation
    if abs(anchor - params.slab_thickness / 2.0) > 1.0:
        out.append(("warn", f"The anchor sits {anchor:.0f} mm below the top surface, "
                            f"not at mid-depth ({params.slab_thickness / 2.0:.0f} mm)."))
    else:
        out.append(("ok", f"Anchor at mid-depth: {anchor:.0f} mm below the top surface."))

    # ---------- الكابلات ----------
    if tendons:
        depths = [q["depth"] for t in tendons for q in t["profile"]]
        if min(depths) < 15.0:
            out.append(("error", f"The shallowest profile point is {min(depths):.0f} mm - "
                                 f"the tendon is too close to the top surface."))
        deepest = max(depths)
        if deepest > params.drop_thickness - 15.0:
            out.append(("error", f"The deepest point {deepest:.0f} mm exceeds the available thickness - "
                                 f"the tendon would break out of the soffit."))

        # الفحص بيتم على منتصف كل قطعة مش على رؤوسها: رؤوس الكابل بتقع
        # بالظبط على الحدود وعلى حواف الفتحات لأنها اتقصّت عندها، فاختبارها
        # مباشرةً بيدي إنذارات كاذبة.
        outside = sum(1 for t in tendons
                      if any(not point_inside_tol(mx, my, boundary, 0.05)
                             for mx, my in profile_segment_midpoints(t["profile"])))
        if outside:
            out.append(("warn", f"{outside} tendons have a portion outside the slab boundary."))

        in_open = sum(1 for t in tendons
                      if any(any(point_in_polygon(mx, my, op)
                                 for op in site.get("openings", []))
                             for mx, my in profile_segment_midpoints(t["profile"])))
        if in_open:
            out.append(("error", f"{in_open} tendons pass through an opening."))
        elif tendons:
            out.append(("ok", "No tendon passes through an opening."))

        capped = design["stats"].get("capped", 0)
        if capped:
            out.append(("warn", f"{capped} tendons need more strands than the maximum."))

        n_col = design["stats"].get("n_column_strip", 0)
        n_mid = design["stats"].get("n_middle_strip", 0)
        if n_col == 0 and n_mid > 0:
            out.append(("warn", "Every tendon was classified as middle strip - "
                                "review the column axis clustering tolerance."))

        spans = []
        for t in tendons:
            highs = [i for i, q in enumerate(t["profile"]) if q.get("high")]
            for k in range(len(highs) - 1):
                L = sum(dist(t["profile"][i]["pos"], t["profile"][i + 1]["pos"])
                        for i in range(highs[k], highs[k + 1]))
                spans.append((L, t.get("dir"), t["profile"][highs[k]]["pos"],
                              t["profile"][highs[k + 1]]["pos"]))
        if spans:
            lengths = [z[0] for z in spans]
            longest = max(lengths)
            ratio = longest / (params.slab_thickness / 1000.0)
            if ratio > 45:
                out.append(("warn", f"Longest span {longest:.1f} m gives a span/depth ratio of "
                                    f"{ratio:.0f}, above the usual 35 to 45 "
                                    f"for post-tensioned flat plates."))
            else:
                out.append(("ok", f"Span/depth ratio {ratio:.0f} is within the usual range."))
            out.extend(audit_phantom_spans(spans, params))

        for d in ("X", "Y"):
            info = ((design or {}).get("pa") or {}).get(d)
            if not info:
                out.append(("warn", f"No tendons at all in direction {d}."))
                continue
            pa = info["pa_MPa"]
            if pa < PA_MIN_DEFAULT:
                out.append(("warn", f"Direction {d}: P/A = {pa:.2f} MPa is below "
                                    f"{PA_MIN_DEFAULT} MPa."))
            elif pa > PA_MAX_DEFAULT:
                out.append(("warn", f"Direction {d}: P/A = {pa:.2f} MPa is above "
                                    f"{PA_MAX_DEFAULT} MPa."))
            else:
                out.append(("ok", f"Direction {d}: P/A = {pa:.2f} MPa is within the acceptable range."))

        if params.losses.enabled:
            worst = max(t["losses"]["total_loss_pct"] for t in tendons if t.get("losses"))
            if worst > 30:
                out.append(("warn", f"Highest prestress loss {worst:.0f}% is high. "
                                    f"Consider jacking from both ends or shortening the tendons."))
            else:
                out.append(("ok", f"Highest prestress loss {worst:.0f}% is acceptable."))

    # ---------- خطوط الركائز ----------
    # Straight jumps between profile points - a node out of order shows up
    # as a diagonal cutting across the floor, and is easy to miss on a plan.
    if tendons:
        out.extend(audit_segment_geometry(tendons, params))
        out.extend(audit_route_parallelism(tendons, params))

    return out


def audit_route_parallelism(tendons, params):
    """كابل ماشي عكس اللفّة بتاعة عيلته.

    الكابل المفروض يفضل موازي لجيرانه على طوله. لو الفجوة بينه وبين أقرب
    جار بتتغير بأمتار من طرف للطرف التاني، يبقى هو ماشي مستقيم والعيلة
    لافّة - أو العكس. وأخطر من الشكل: الفجوة بتضيق تحت الخلوص المسموح.

    القياس بيتعمل عند نقط على طول الكابل، وكل نقطة بتتقاس لأقرب موضع على
    الجار - **بشرط** الموضع ده ماكونش طرف الجار نفسه. من غير الشرط ده،
    كابل جاره أقصر منه بيدّي "فجوة" 23 م عند طرفه، وهي مش فجوة: هي
    المسافة لنهاية الجار. أول نسخة من الفحص دي بلّغت 42 كابل في X و53 في
    Y بالغلط للسبب ده.
    """
    out = []
    gapmin = getattr(params, "min_clear_spacing", 0.20)
    span = max(2.0 * getattr(params, "spacing", 1.5), 1.0)
    for d in ("X", "Y"):
        g = [t for t in tendons
             if t.get("dir") == d and len(t.get("profile") or []) >= 2]
        if len(g) < 3:
            continue

        def poly(t):
            return [q["pos"] for q in t["profile"]]

        def foot(pt, pts):
            """(المسافة, المسافة الطولية على الجار, طول الجار)"""
            best = (1e9, 0.0, 0.0)
            s = 0.0
            for i in range(len(pts) - 1):
                a2, c2 = pts[i], pts[i + 1]
                L = dist(a2, c2)
                if L < 1e-9:
                    continue
                u = max(0.0, min(1.0, ((pt[0]-a2[0])*(c2[0]-a2[0])
                                       + (pt[1]-a2[1])*(c2[1]-a2[1])) / (L*L)))
                q = (a2[0]+u*(c2[0]-a2[0]), a2[1]+u*(c2[1]-a2[1]))
                dd = dist(pt, q)
                if dd < best[0]:
                    best = (dd, s + u * L, 0.0)
                s += L
            return best[0], best[1], s

        def samples(t):
            P0 = poly(t)
            n = len(P0)
            return [P0[0], P0[max(1, n // 4)], P0[n // 2],
                    P0[min(n - 2, 3 * n // 4)], P0[-1]]

        drift, tight = [], []
        for t in g:
            pts = samples(t)
            mid = pts[2]
            nb = min((x for x in g if x is not t),
                     key=lambda x: foot(mid, poly(x))[0])
            npts = poly(nb)
            ds = []
            for pt in pts:
                dd, s_at, L = foot(pt, npts)
                #  الجار مابيغطّيش المحطة دي - الفجوة هنا مش فجوة
                if s_at < 0.5 or s_at > L - 0.5:
                    continue
                ds.append(dd)
            if len(ds) < 3:
                continue
            if max(ds) - min(ds) > span:
                drift.append((max(ds) - min(ds), t.get("coord", 0.0),
                              [ds[0], ds[len(ds)//2], ds[-1]]))
            if min(ds) < gapmin:
                tight.append((min(ds), t.get("coord", 0.0)))
        if drift:
            drift.sort(reverse=True)
            w = drift[0]
            out.append(("warn",
                        f"Direction {d}: {len(drift)} tendon(s) do not stay "
                        f"parallel to the family - the gap to the nearest "
                        f"neighbour changes along the run. Worst at "
                        f"{w[1]:.1f}: {w[2][0]:.2f} m at one end, "
                        f"{w[2][1]:.2f} m at midspan, {w[2][2]:.2f} m at the "
                        f"other. A straight tendon in a fanned family, or the "
                        f"other way round."))
        if tight:
            tight.sort()
            out.append(("error",
                        f"Direction {d}: {len(tight)} tendon(s) come closer to "
                        f"a neighbour than the {gapmin:.2f} m clear spacing - "
                        f"the closest is {tight[0][0]:.2f} m at "
                        f"{tight[0][1]:.1f}."))
        if not drift and not tight:
            out.append(("ok", f"Direction {d}: every tendon stays parallel to "
                              f"its neighbours along its whole run."))
    return out



def audit_phantom_spans(spans, params, factor=2.0):
    """
    **18.26: بحر أطول بكتير من بحور الدور = قمة ناقصة، مش منشأ.**

    البحر عند load balancing بيتحوّل لقوة بـ w·L²/(8a) - يعني الطول
    **تربيعي**. فكابل عدّى فوق عمود ومااخدش قمة هناك بيتقرا بحر واحد
    طوله بحرين أو تلاتة، والقوة اللي بيطلبها بتتضرب في 4 أو 9. وده
    بيوصل لآخره: الكابل بيقف عند أقصى عدد استراندات، والباقي بيتقال إنه
    "نقص مش مغطّى"، وP/A بيطلع فوق السقف - وكل ده على بحر مش موجود.

    على الدور ده: متوسط البحر 3.4 م وأطول بحر 13.8 م - أربع مرات
    ونص. الأرقام اللي طلعت بعدها (20 كابل عند الحد الأقصى، 7,050 kN
    نقص، P/A 7.03) كلها من هنا.

    الفحص ده مابيصلّحش البروفايل - بيقول إن الرقم مشكوك فيه وفين
    بالظبط، عشان حد يبص على القمة الناقصة بدل ما يزوّد استراندات
    لبحر مالوش وجود.
    """
    if not spans:
        return []
    lengths = sorted(z[0] for z in spans)
    median = lengths[len(lengths) // 2]
    if median <= 0.1:
        return []
    limit = factor * median
    odd = sorted((z for z in spans if z[0] > limit), key=lambda z: -z[0])
    if not odd:
        return [("ok", f"Every span is within {factor:g}x the floor's median "
                       f"of {median:.1f} m - no tendon is being sized for a "
                       f"span that is not there.")]
    worst = odd[0]
    out = [("warn",
            f"{len(odd)} span(s) are more than {factor:g}x the floor's median "
            f"of {median:.1f} m - the worst is {worst[0]:.1f} m, which is "
            f"{worst[0] / median:.1f}x. Load balancing sizes on L\u00b2, so "
            f"that one asks for about {(worst[0] / median) ** 2:.0f}x the "
            f"force a median bay does. A span that long on this grid is "
            f"normally a high point that was not placed, not a real bay: "
            f"check for a support line or a column crossing inside it before "
            f"adding strands.")]
    for L, d, a, b in odd[:6]:
        out.append(("warn",
                    f"    {L:.1f} m in {d} from ({a[0]:.1f}, {a[1]:.1f}) to "
                    f"({b[0]:.1f}, {b[1]:.1f})"))
    return out


def audit_segment_geometry(tendons, params, limit=None):
    """
    Find profile points that are in the wrong place - not merely far apart.

    The two are different and the first version confused them. A long straight
    run with no node in it gives a long segment, and that is fine: the segment
    lies along the route. A node out of order gives a segment that CUTS ACROSS
    the route, and that is what shows on the plan as a diagonal.

    The test is therefore the detour: chord length against the distance along
    the path between the same two nodes. Equal means the segment follows the
    route however long it is; much shorter means the segment is a short-cut
    and one of the nodes does not belong there.
    """
    cap = limit or max(4.0 * params.spacing, 20.0)
    out = []
    for d in ("X", "Y"):
        detours = []
        longest = 0.0
        for t in tendons:
            if t["dir"] != d:
                continue
            pr = t["profile"]
            path = t.get("path")
            for k in range(len(pr) - 1):
                a, b = pr[k], pr[k + 1]
                chord = dist(a["pos"], b["pos"])
                longest = max(longest, chord)
                # The path is the authority. A node carries the arc
                # distance it was CREATED at, and a later rule can move it -
                # re-centring a low point, sliding a peak onto a band. A
                # stale number here makes the audit report a segment that is
                # fine, or pass one that is not. When the tendon carries its
                # route, both ends are measured on it afresh.
                if path is not None:
                    sa = path.distance_of(a["pos"])
                    sb = path.distance_of(b["pos"])
                else:
                    sa, sb = a.get("_s"), b.get("_s")
                    if sa is None or sb is None:
                        continue
                arc = abs(sb - sa)
                # A short-cut: the two nodes are far apart along the route but
                # close together on the plan, or the other way round.
                if arc > 1e-6 and abs(chord - arc) > max(0.25 * arc, 1.0):
                    detours.append((abs(chord - arc), round(t["coord"], 2),
                                    chord, arc))
        if not detours and longest == 0.0:
            continue
        if detours:
            detours.sort(reverse=True)
            worst = detours[0]
            out.append(("error",
                        f"Direction {d}: {len(detours)} segments cut across "
                        f"the route instead of following it - the worst joins "
                        f"two points {worst[3]:.1f} m apart along the tendon "
                        f"with a {worst[2]:.1f} m straight line, at "
                        f"{worst[1]}. A node is in the wrong place."))
        else:
            out.append(("ok", f"Direction {d}: every segment follows the "
                              f"tendon route; longest is {longest:.1f} m."))
        if longest > cap and not detours:
            out.append(("warn",
                        f"Direction {d}: the longest straight run between "
                        f"profile points is {longest:.1f} m. That is correct "
                        f"geometry, but a node every {cap:.0f} m or less is "
                        f"easier to build - lower the chord tolerance if you "
                        f"want more."))
    return out


def format_audit(rows):
    n_err = sum(1 for lvl, _ in rows if lvl == "error")
    n_warn = sum(1 for lvl, _ in rows if lvl == "warn")
    icon = {"error": "✖", "warn": "⚠", "ok": "✔"}
    lines = [f"{icon.get(lvl, '•')}  {msg}" for lvl, msg in rows]
    return lines, n_err, n_warn


# ==============================================================================
#  SECTION 6e — the EFM loop: RAM designs, we read what it had to add
#
#  الفكرة اللي الحلقة قايمة عليها: بعد ما RAM يحسب ويصمّم ويحفظ، الملف نفسه
#  بيبقى فيه **الحديد اللي البرنامج حطّه** (جدول ConcentratedRebar، الحقل
#  DesignedBy = 2). الحديد ده مقياس القصور: البحر اللي كابلاته كافية بياخد
#  الحد الأدنى، واللي قصّر بياخد أكتر وبقد ما قصّر.
#
#  يعني مفيش داعي لتصدير خرايط عزوم بالإيد ولا وقفة في نص الشغل - الإشارة
#  في الملف المحفوظ، وبتتقرا بالـ SQLite من غير API.
#
#  اتأكدت الإشارة قبل ما تتبني عليها: على بلاطة الصفا، الـ 19 نقطة إجهاد
#  الفاشلة (مقروءة من خريطة إجهادات RAM - مقياس مستقل تماماً) وقعت في وسيط
#  **23%** الأسوأ من ترتيب الحلقة، والصدفة 51%. وأسوأ نقطتين إجهاد الاتنين
#  على البحر اللي الحلقة مرتباه رقم 1.
#
#  الحلقة **مش بتتنبّأ - بتقيس**: بتزوّد، تعيد الحساب، تشوف الحديد نزل كام
#  لكل استرند، وتستعمل المقيس ده في الدورة اللي بعدها.
# ==============================================================================

STEEL_DENSITY = 7850.0            # كجم/م³
RAM_LEN = 1e-4                    # وحدة الطول الداخلية في RAM بالمتر
EFM_OBJECTIVES = ("report_only", "section_only", "zero_rebar", "min_cost",
                  "even_steel")


def _ram_pts(s):
    return [(int(a) * RAM_LEN, int(b) * RAM_LEN)
            for a, b in re.findall(r"\[(-?\d+)\]\[(-?\d+)\]", s or "")]


def _seg_dist(q, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    l2 = dx * dx + dy * dy
    u = 0.0 if l2 < 1e-12 else max(0.0, min(
        1.0, ((q[0] - a[0]) * dx + (q[1] - a[1]) * dy) / l2))
    return math.hypot(q[0] - a[0] - u * dx, q[1] - a[1] - u * dy)


def _side_of(a, b, q):
    return (b[0] - a[0]) * (q[1] - a[1]) - (b[1] - a[1]) * (q[0] - a[0])


def _spans_cross(p1, p2, p3, p4):
    """
    تقاطع قطعتين - نسخة حلقة الـ EFM.

    اسمها كان _segments_cross، وده اسم دالة تانية موجودة فوق بتعامل
    **اللمس عند طرف مشترك على إنه مش تقاطع**. الاتنين بياخدوا أربع نقط
    وبيرجّعوا بوليان، فالتغطية ماكانتش بتقع - كانت بتغيّر إجابة فاحص
    تقاطع خطوط الركائز في السكوت، وده أسوأ من الوقوع.
    """
    d1 = _side_of(p3, p4, p1)
    d2 = _side_of(p3, p4, p2)
    d3 = _side_of(p1, p2, p3)
    d4 = _side_of(p1, p2, p4)
    return ((d1 > 0) != (d2 > 0)) and ((d3 > 0) != (d4 > 0))


def read_designed_steel(cpt_path):
    """
    الحديد اللي RAM صمّمه + البحور + الكابلات، من ملف .cpt متحسوب ومحفوظ.

    البحور بتتاخد من SpanSegment (محور البحر نفسه، ومنه الطول). جدول
    SpanDesign بيدّي القطاع **العرضي** عبر الشريحة - أخد الطول منه بيطلع
    صفر لأن صفوفه لنفس البحر مكرّرة على نفس الخط.
    """
    import sqlite3
    con = sqlite3.connect(cpt_path)
    try:
        bars = {}
        for uid, name, a in con.execute('select UID,Name,"As" from Rebar'):
            bars[uid] = (name, (a or 0.0) / 100.0)   # As مخزّنة بوحدة 0.01 مم²

        spans = {}
        #  AtSupport0/1: طرف القطعة ده ركيزة ولا مجرد تقسيم جوّه البحر.
        #  علاج الوش العلوي محتاجه عشان يمشي لآخر البحر المجاور فعلاً،
        #  مش لآخر قطعة منه.
        try:
            _span_rows = con.execute(
                "select Name,Point0,Point1,SpanSet,FrameNumber,SpanNumber,"
                "SegmentNumber,AtSupport0,AtSupport1 from SpanSegment"
            ).fetchall()
        except Exception:
            _span_rows = [tuple(r) + (None, None) for r in con.execute(
                "select Name,Point0,Point1,SpanSet,FrameNumber,SpanNumber,"
                "SegmentNumber from SpanSegment").fetchall()]

        def _flag(v):
            if v is None:
                return None
            return str(v).strip().lower() in ("1", "true", "yes")

        for nm, p0, p1, ss, fr, sn, sg, s0, s1 in _span_rows:
            a, b = _ram_pts(p0), _ram_pts(p1)
            if not a or not b:
                continue
            a, b = a[0], b[0]
            spans[(ss, fr, sn, sg)] = {
                "name": nm, "a": a, "b": b,
                "mid": ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0),
                "length": dist(a, b),
                "at_support_a": _flag(s0), "at_support_b": _flag(s1)}

        rebar = []
        for p0, p1, face, btype, cnt, by in con.execute(
                "select Point0,Point1,BarFace,BarType,BarCount,DesignedBy "
                "from ConcentratedRebar"):
            a, b = _ram_pts(p0), _ram_pts(p1)
            if not a or not b:
                continue
            a, b = a[0], b[0]
            _nm, area1 = bars.get(btype, ("?", 0.0))
            rebar.append({"mid": ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0),
                          "len": dist(a, b),
                          "face": "top" if face == 1 else "bot",
                          "area": (cnt or 0) * area1,
                          #  عدد الأسياخ نفسه، مش مساحته. سيخ أو اتنين
                          #  زيادة مش مشكلة تستاهل كابل - والمساحة لوحدها
                          #  ماكانتش بتفرّق بين سيخين تخان وستة رفيعين.
                          "bars": int(cnt or 0),
                          "designed": by == 2})

        #  قطع الكابلات: العقدة بتتشاور عليها بنص الإحداثي مش برقمها.
        segs = []
        for n0, n1, ns in con.execute(
                "select TendonNode0,TendonNode1,NumStrands from Tendon"):
            a, b = _ram_pts(n0), _ram_pts(n1)
            if a and b:
                segs.append({"a": a[0], "b": b[0], "strands": ns or 0})

        area = 0.0
        try:
            rows = con.execute("select MultiPoint,Priority from SlabArea")
        except Exception:
            rows = [(mp, 1) for mp,
                    in con.execute("select MultiPoint from SlabArea")]
        for mp, pri in rows:
            p = _ram_pts(mp)
            if len(p) >= 3 and (pri or 1) <= 1:
                area += abs(sum(p[i][0] * p[(i + 1) % len(p)][1]
                                - p[(i + 1) % len(p)][0] * p[i][1]
                                for i in range(len(p)))) / 2.0
    finally:
        con.close()
    return {"spans": spans, "rebar": rebar, "segs": segs, "slab_area": area}


def steel_by_span(model, reach=6.0, strip=12.0):
    """كل مجموعة حديد بتروح لأقرب محور بحر، والاسترندات بتتعد بالتقاطع."""
    out = {}
    for key, sp in model["spans"].items():
        out[key] = {"key": key, "set": key[0], "frame": key[1],
                    "span": key[2], "seg": key[3], "name": sp["name"],
                    "a": sp["a"], "b": sp["b"], "mid": sp["mid"],
                    "length": sp["length"], "top": 0.0, "bot": 0.0,
                    "kg": 0.0, "kg_top": 0.0, "kg_bot": 0.0,
                    "bars_top": 0, "bars_bot": 0,
                    "groups": 0, "strands": 0}
    for r in model["rebar"]:
        best, bd = None, 1e18
        for key, sp in model["spans"].items():
            d = _seg_dist(r["mid"], sp["a"], sp["b"])
            if d < bd:
                best, bd = key, d
        if best is None or bd > reach:
            continue
        o = out[best]
        o[r["face"]] += r["area"]
        w = r["area"] * 1e-6 * r["len"] * STEEL_DENSITY
        o["kg"] += w
        o["kg_top" if r["face"] == "top" else "kg_bot"] += w
        o["bars_top" if r["face"] == "top" else "bars_bot"] += \
            int(r.get("bars") or 0)
        o["groups"] += 1

    for o in out.values():
        c1, c2 = _cross_line(o, strip)
        tot = 0
        for t in model["segs"]:
            if _spans_cross(c1, c2, t["a"], t["b"]):
                tot += t["strands"]
        o["strands"] = tot
    return out


def _cross_line(span, half=12.0):
    """خط عرضي عند منتصف البحر، بطول 2×half - أوسع من أي شريحة عملية."""
    ax, ay = span["a"]
    bx, by = span["b"]
    ux, uy = bx - ax, by - ay
    n = math.hypot(ux, uy) or 1.0
    px, py = -uy / n, ux / n
    mx, my = span["mid"]
    return ((mx - px * half, my - py * half), (mx + px * half, my + py * half))


def _face_of(params):
    f = str(getattr(params, "efm_face", "both") or "both").lower()
    return f if f in ("both", "bottom", "top") else "both"


def face_kg(v, face):
    """
    وزن الحديد اللي الحلقة بتشتغل عليه في البحر ده، حسب الوش المختار.

    الحديد **العلوي** فوق الركائز محكوم بالثقب والحد الأدنى الكودي، والقوة
    الزيادة بتنفع فيه أقل بكتير - وهو اللي بيضخّم الكميات. فالشغل على
    السفلي وحده خيار حقيقي، مش تبسيط.
    """
    if face == "bottom":
        return float(v.get("kg_bot") or 0.0)
    if face == "top":
        return float(v.get("kg_top") or 0.0)
    return float(v.get("kg") or 0.0)


def face_bars(v, face):
    """عدد الأسياخ اللي RAM حطّها في البحر ده على الوش المطلوب."""
    if face == "bottom":
        return int(v.get("bars_bot") or 0)
    if face == "top":
        return int(v.get("bars_top") or 0)
    return int(v.get("bars_top") or 0) + int(v.get("bars_bot") or 0)


def face_area(v, face):
    if face == "bottom":
        return float(v.get("bot") or 0.0)
    if face == "top":
        return float(v.get("top") or 0.0)
    return float(v.get("top") or 0.0) + float(v.get("bot") or 0.0)


def steel_replaced_by_one_strand(params):
    """مساحة الحديد اللي استرند واحد بيغني عنها، مم² - نفس ذراع العزم."""
    fpe = float(params.strand_fpu) * float(params.fpe_ratio)
    fy = float(getattr(params, "rebar_fy", 460.0) or 460.0)
    return float(params.strand_area) * fpe / max(fy, 1.0)


_LEDGER = {}


def efm_advice(table, params, objective, measured=None, max_step=6):
    """
    بترجّع [{key, add, why}] مرتّبة بالأهم. measured = كجم حديد لكل استرند
    من دورة سابقة؛ لما بيبقى موجود بيتقدّم على التقدير النظري.
    """
    rows = list(table.values())
    #  section_only (17.2) مابيطاردش الحديد المصمَّم خالص
    if not rows or objective in ("report_only", "section_only"):
        return []
    face = _face_of(params)
    kgs = sorted(face_kg(r, face) for r in rows)
    med = kgs[len(kgs) // 2] if kgs else 0.0
    a1 = steel_replaced_by_one_strand(params)
    p_strand = float(getattr(params, "efm_price_strand", 3.5) or 0.0)
    p_rebar = float(getattr(params, "efm_price_rebar", 0.9) or 0.0)
    floor = float(getattr(params, "efm_min_steel", 0.0) or 0.0)

    #  فلترين قبل أي حساب - الاتنين من ملاحظة في الموقع:
    #
    #  · **سيخ أو اتنين زيادة مش مشكلة.** الحلقة كانت بتجري ورا أي
    #    مساحة حديد فوق الصفر، فبحور فيها سيخين إضافيين كانت بتاخد
    #    كابل - كابل بأنكرين وجيب شد عشان حاجة الكود بيقولها ومش
    #    بتزنق حد. الحد الافتراضي 6 أسياخ على الوش اللي بنشتغل عليه.
    #
    #  · **البحر القصير مش مكان زيادة قوة.** الحديد السفلي في بحر
    #    قصير غالباً جاي من الكابلات نفسها - بروفايل بيتكسر على بحر
    #    ماينفعش يشيل غطسة كاملة (قاعدة نصف القطر الأدنى بترفع الغطسة
    #    هناك أصلاً)، أو كابلات كتير عدّت عليه. زيادة القوة فيه بتزوّد
    #    الطين بلة بدل ما تحلّه.
    min_bars = int(getattr(params, "efm_min_bars", 6) or 0)
    min_span = float(getattr(params, "efm_min_span", 6.0) or 0.0)
    skip_bars = skip_short = 0
    skipped_rows = []

    out = []
    for r in rows:
        excess = face_area(r, face) - floor
        if excess <= 0:
            continue
        if min_bars > 0 and face_bars(r, face) < min_bars:
            skip_bars += 1
            skipped_rows.append((r, f"{face_bars(r, face)} bars"))
            continue
        if min_span > 0 and float(r.get("length") or 0.0) < min_span:
            skip_short += 1
            skipped_rows.append((r, f"{float(r['length']):.1f} m long"))
            continue
        r_kg = face_kg(r, face)
        per = (measured or {}).get(r["key"])
        add = (r_kg / per) if (per and per > 1e-6) else (excess / max(a1, 1.0))

        if objective == "zero_rebar":
            why = "clear the designed steel"
        elif objective == "even_steel":
            if r_kg <= med:
                continue
            add *= (r_kg - med) / max(r_kg, 1e-6)
            why = f"toward the median {med:.0f} kg"
        elif objective == "min_cost":
            #  الحساب ده **على وزن الصلب وبس** - مش حاسب إن البوست تنشن
            #  بيقلل السمك والترخيم، وده غالباً هو اللي بيدفع تكلفته.
            span_len = max(r.get("length") or 0.0, 1.0)
            cost = p_strand * span_len
            saved = per if per else a1 * 1e-6 * STEEL_DENSITY * span_len
            r["breakeven"] = (saved * p_rebar / cost) if cost else 0.0
            if saved * p_rebar <= cost:
                continue
            why = (f"saves ~{saved:.0f} kg worth {saved * p_rebar:.0f} "
                   f"for {cost:.0f}")
        else:
            continue

        n = max(0, min(int(round(add)), int(max_step)))
        if n <= 0:
            continue
        out.append({"key": r["key"], "name": r["name"], "set": r["set"],
                    "add": n, "kg": r_kg, "top": r["top"], "bot": r["bot"],
                    "strands": r["strands"], "why": why,
                    "a": r["a"], "b": r["b"], "mid": r["mid"]})
    out.sort(key=lambda d: -d["kg"])
    #  اللي اتشال بيترجّع في خاصية جنبية بدل ما نغيّر شكل القيمة
    #  المرجّعة - الحلقة بتقراها وتقوله في اللوج.
    efm_advice.skipped = (skip_bars, skip_short, min_bars, min_span)
    efm_advice.skipped_rows = sorted(
        skipped_rows, key=lambda z: -face_kg(z[0], face))[:4]
    return out


def _tendons_over_span(tendons, d, strip=12.0):
    """الكابلات اللي بتقطع الخط العرضي عند منتصف البحر وموازية لمحوره."""
    c1, c2 = _cross_line(d, strip)
    ax, ay = d["a"]
    bx, by = d["b"]
    span_ang = math.atan2(by - ay, bx - ax)
    out = []
    for t in tendons:
        prof = t.get("profile") or []
        if len(prof) < 2:
            continue
        hit = None
        for q1, q2 in zip(prof, prof[1:]):
            if _segments_cross(c1, c2, q1["pos"], q2["pos"]):
                hit = (q1["pos"], q2["pos"])
                break
        if hit is None:
            continue
        ang = math.atan2(hit[1][1] - hit[0][1], hit[1][0] - hit[0][0])
        off = abs(math.degrees(ang - span_ang)) % 180.0
        if off > 90.0:
            off = 180.0 - off
        if off <= 45.0:
            out.append(t)
    return out


def allocate_strands(tendons, advice, params, job=None, strip=12.0):
    """
    يوزّع الزيادة على **أقل عدد كابلات** يقدر يوصّلها، مش على كل كابل.

    الطريقة الأولى كانت بتقسّم زيادة كل بحر على كابلاته وتاخد الأكبر،
    فكل كابل بياخد 1 - والنتيجة كانت رفع شامل: 306 استرند بقوا 408 ثم
    510، +1 لكل كابل في كل دورة، مع إن الهدف رشّح 50 بحر من 104. ده مش
    استهداف، ده كان ممكن تعمله بإيدك بإنك تحط 5 لكل كابل.

    السبب إن الكابل مستمر: مينفعش تقوّي بحر واحد فيه من غير ما تقوّي
    باقي بحوره. والاستنتاج الصح من ده هو **العكس** بالظبط: كابلات أقل
    تاخد استرندات أكتر، عشان القوة تتركّز فين ما هي مطلوبة وتسيب باقي
    البلاطة.

    فالتوزيع بقى جشِع: الاسترند بيروح للكابل اللي **بيخدم أكتر بحور
    محتاجة** - لأن استرند واحد فيه بيقلّل عجز كل البحور اللي بيعدّي
    عليها في نفس الوقت.
    """
    cap = int(getattr(params, "max_strands", 12) or 12)
    allowed = list(getattr(params, "allowed_strands", []) or [])
    step_cap = int(getattr(params, "efm_max_step", 6) or 6)

    #  خريطة البحر -> كابلاته، والعجز الباقي لكل بحر
    need = {}
    serves = {}
    orphan = 0
    for d in advice:
        picks = _tendons_over_span(tendons, d, strip)
        if not picks:
            orphan += 1
            continue
        need[id(d)] = float(d["add"])
        for t in picks:
            serves.setdefault(id(t), {"t": t, "spans": [], "given": 0})
            serves[id(t)]["spans"].append(d)

    if not serves:
        return 0, orphan

    def value(rec):
        """قيمة استرند في الكابل ده = مجموع العجز الباقي في بحوره."""
        return sum(need.get(id(d), 0.0) for d in rec["spans"]
                   if need.get(id(d), 0.0) > 0.0)

    added = 0
    capped = 0
    guard = 0
    while guard < 20000:
        guard += 1
        best, bv = None, 0.0
        for rec in serves.values():
            if rec["given"] >= step_cap:
                continue
            t = rec["t"]
            now = int(t.get("strands") or 0)
            if now >= cap:
                continue
            v = value(rec)
            if v > bv:
                best, bv = rec, v
        if best is None or bv <= 0.0:
            break
        t = best["t"]
        now = int(t.get("strands") or 0)
        nxt = now + 1
        if allowed:
            up = next((a for a in allowed if a > now), None)
            if up is None or up > cap:
                capped += 1
                best["given"] = step_cap        # اقفله
                continue
            nxt = up
        nxt = min(nxt, cap)
        if nxt <= now:
            capped += 1
            best["given"] = step_cap
            continue
        gain = nxt - now
        t["strands"] = nxt
        t.setdefault("governing", {})["efm"] = True
        best["given"] += gain
        added += gain
        #  **دفتر**: مين اتزوّد عشان مين. من غيره الاسترجاع مستحيل -
        #  الكابل بيعدّي على كذا بحر، ومن غير قيد مانعرفش الاسترند ده
        #  دخل عشان أنهي بحر عشان نرجّعه لو ما ردّش.
        gv = t.setdefault("_gave", {})
        for d in best["spans"]:
            k = d.get("key")
            if k is not None:
                gv[k] = int(gv.get(k, 0)) + gain
                _LEDGER[k] = int(_LEDGER.get(k, 0)) + gain
        #  الاسترند ده بيخدم كل بحور الكابل مرة واحدة
        for d in best["spans"]:
            if id(d) in need:
                need[id(d)] = max(0.0, need[id(d)] - gain)

    if job:
        touched = sum(1 for r in serves.values() if r["given"] > 0)
        if touched:
            sizes = {}
            for r in serves.values():
                if r["given"] > 0:
                    sizes[r["given"]] = sizes.get(r["given"], 0) + 1
            spread = " · ".join(f"{v} tendon(s) +{k}"
                                for k, v in sorted(sizes.items()))
            job.ok(f"+{added} strands went into {touched} of {len(tendons)} "
                   f"tendons: {spread}. The rest were left alone.")
        left = sum(1 for v in need.values() if v > 0.5)
        if left:
            job.warn(f"{left} span(s) still short after the round - every "
                     f"tendon over them is at the cap of {cap} strands or at "
                     f"this round's step of {step_cap}.")
    return added, orphan


def _consecutive_runs(advice):
    """
    البحور المحتاجة بتتجمّع في **سلاسل متجاورة على نفس الإطار**.

    البحور 24-2 و24-3 و24-5 على إطار واحد: 2 و3 جنب بعض فهما سلسلة،
    و5 لوحده. كل سلسلة بتاخد كابل إضافي واحد بدل تلاتة.
    """
    by = {}
    for d in advice:
        by.setdefault((d["set"], d["key"][1]), []).append(d)
    runs = []
    for _k, rows in by.items():
        rows.sort(key=lambda d: (d["key"][2], d["key"][3]))
        cur = [rows[0]]
        for a, b in zip(rows, rows[1:]):
            if b["key"][2] - a["key"][2] <= 1:
                cur.append(b)
            else:
                runs.append(cur)
                cur = [b]
        runs.append(cur)
    return runs


def _station_of(prof, pos):
    """محطة أقرب نقطة على مسار الكابل للنقطة دي، ومسافتها عنه."""
    s = 0.0
    best = (1e18, 0.0)
    for a, b in zip(prof, prof[1:]):
        pa, pb = a["pos"], b["pos"]
        dx, dy = pb[0] - pa[0], pb[1] - pa[1]
        seg = math.hypot(dx, dy)
        l2 = dx * dx + dy * dy
        u = 0.0 if l2 < 1e-12 else max(0.0, min(
            1.0, ((pos[0] - pa[0]) * dx + (pos[1] - pa[1]) * dy) / l2))
        d = math.hypot(pos[0] - pa[0] - u * dx, pos[1] - pa[1] - u * dy)
        if d < best[0]:
            best = (d, s + u * seg)
        s += seg
    return best[1], best[0]


def _profile_point_at(prof, station):
    """
    (x, y) عند محطة على بروفايل كابل - نقطه ديكشنري فيها "pos".

    الاسم بقى مخصوص عن قصد: كان اسمها _point_at، وفيه دالة بنفس الاسم
    فوق بتاخد بوليجون نقطه تبل عادية. الاتنين في نفس الملف، والتانية
    كانت بتغطّي الأولى - فمولّد شرائح التغطية وقع بـ
    "tuple indices must be integers" وهو بيمرّر بوليجون لدالة بتتوقع
    بروفايل.
    """
    s = 0.0
    for a, b in zip(prof, prof[1:]):
        pa, pb = a["pos"], b["pos"]
        seg = dist(pa, pb)
        if s + seg >= station or b is prof[-1]:
            u = 0.0 if seg < 1e-9 else max(0.0, min(1.0, (station - s) / seg))
            return (pa[0] + (pb[0] - pa[0]) * u, pa[1] + (pb[1] - pa[1]) * u)
        s += seg
    return prof[-1]["pos"]


def _slide_between_neighbours(new, donor, tendons, params):
    """
    يزحلق الكابل الإضافي **عمودي على مساره** لحد ما يقع بين الكابل
    المانح وأقرب جاره - مش فوقه.

    ده كان أخطر عيب في الكابلات الإضافية: البروفايل بيتنسخ من المانح
    بإحداثياته، فالكابل الجديد بيطلع على بُعد **صفر** من القديم - 28
    من 28 في الاختبار. كابلين في نفس المكان حاجة مستحيلة في التنفيذ،
    وRAM بيختنق بيها: التحليل طلع من 20 ثانية لـ 44، وبعدين وقف.

    الجار بيتلاقى بإسقاط بداية كل كابل في نفس الاتجاه على عمودي
    المانح. الكابل الجديد بياخد **نص المسافة** لأقرب جار. ولو مفيش
    جار، بياخد نص المسافة المسموحة بين الكابلات من الإعدادات.

    بترجّع الإزاحة بالمتر (بالإشارة).
    """
    prof = donor.get("profile") or []
    if len(prof) < 2:
        return 0.0
    ax = prof[-1]["pos"][0] - prof[0]["pos"][0]
    ay = prof[-1]["pos"][1] - prof[0]["pos"][1]
    n = math.hypot(ax, ay) or 1.0
    ux, uy = ax / n, ay / n
    nx, ny = -uy, ux
    o0 = donor["profile"][0]["pos"]

    offs = []
    for t in tendons:
        if t is donor:
            continue
        #  الكابلات الإضافية اللي اترسمت قبل كده في نفس الدورة (أو في
        #  دورة فاتت) **حاجز حقيقي**: تجاهلها هنا هو اللي كان بيخلّي
        #  التاني يقع في نفس الفراغ بنفس الإزاحة. دلوقتي بتتحسب معاهم.
        if t.get("added") and len(t.get("profile") or []) < 2:
            continue
        q = (t.get("profile") or [{}])[0].get("pos")
        if not q:
            continue
        #  نفس الاتجاه تقريباً
        tp = t.get("profile") or []
        if len(tp) < 2:
            continue
        bx = tp[-1]["pos"][0] - tp[0]["pos"][0]
        by = tp[-1]["pos"][1] - tp[0]["pos"][1]
        bn = math.hypot(bx, by) or 1.0
        if abs((bx / bn) * ux + (by / bn) * uy) < 0.70:      # > 45°
            continue
        d = (q[0] - o0[0]) * nx + (q[1] - o0[1]) * ny
        if abs(d) > 0.05:
            offs.append(d)
    if offs:
        pos = [d for d in offs if d > 0]
        neg = [d for d in offs if d < 0]
        cand = []
        if pos:
            cand.append(min(pos) / 2.0)
        if neg:
            cand.append(max(neg) / 2.0)
        shift = min(cand, key=abs) if cand else 0.0
    else:
        shift = 0.0
    gap = 2.0 * shift          # المسافة الكاملة للجار، بالإشارة
    if abs(shift) < 0.10:
        #  مفيش جار: نص المسافة القصوى بين الكابلات، وإلا نص متر
        g = float(getattr(params, "max_spacing", 0.0) or 0.0)
        shift = (g / 2.0) if g > 0.2 else 0.5
        gap = 2.0 * shift
    new["_gap"] = gap
    new["_normal"] = (nx, ny)
    new["_base"] = [tuple(q["pos"]) for q in new["profile"]]
    #  الإزاحة الثابتة كويسة على مسار مستقيم، لكن المسار بيلف - فالكابل
    #  ممكن يقرّب من جار تاني عند طرف. قِيس: واحد وصل 55 مم من جاره.
    #  فبنجرّب الإزاحة، ولو الخلوص أقل من الحد بنجرّب الناحية التانية،
    #  وبعدين نصف الإزاحة - وآخر حاجة نرفض الكابل بدل ما نحطه ملزوق.
    clear_min = float(getattr(params, "efm_added_clear", 0.25) or 0.0)
    base = [dict(q) for q in new["profile"]]

    def _place(sh):
        for q, src in zip(new["profile"], base):
            q["pos"] = (src["pos"][0] + nx * sh, src["pos"][1] + ny * sh)
            q.pop("_s", None)

    def _clearance():
        worst = 1e9
        for q in new["profile"][1:-1]:
            for t in tendons:
                if t is new:
                    continue
                for r in (t.get("profile") or []):
                    worst = min(worst, dist(q["pos"], r["pos"]))
        return worst

    #  أربع محاولات كانت بتكفي وإحنا بنتجاهل الكابلات الإضافية. دلوقتي
    #  وهي محسوبة، تاني كابل في نفس الفراغ محتاج مكان تاني - فبنمشّط
    #  الفراغ نفسه: من ربع المسافة للجار لحد ثلاثة أرباعها، ناحيتين،
    #  ونقف على أول مكان خلوصه كافي.
    trials = []
    for f in (1.0, 0.5, 1.5, 0.75, 1.25, 0.25, 1.75):
        trials.extend((shift * f, -shift * f))
    seen = set()
    for trial in trials:
        if abs(trial) < 0.05:
            continue
        r = round(trial, 3)
        if r in seen:
            continue
        seen.add(r)
        if abs(gap) > 0.01 and abs(trial) > abs(gap) - clear_min:
            continue
        _place(trial)
        if _clearance() >= clear_min:
            return trial
    _place(shift)
    new["too_close"] = round(_clearance(), 3)
    return shift


def nearest_parallel(new, tendons):
    """
    أقرب كابل **موازي** للكابل الجديد، و(المسافة, الكابل).

    الكابل اللي ماشي عرضاني بيتقاطع مع ده، والتقاطع مش ازدحام - الحد
    بين المتوازيات بس. بترجّع (inf, None) لو مافيش ولا واحد موازي.
    """
    pr_new = (new or {}).get("profile") or []
    if len(pr_new) < 2:
        return float("inf"), None
    ax = pr_new[-1]["pos"][0] - pr_new[0]["pos"][0]
    ay = pr_new[-1]["pos"][1] - pr_new[0]["pos"][1]
    an = math.hypot(ax, ay) or 1.0
    ax, ay = ax / an, ay / an
    inner = pr_new[1:-1] or pr_new
    worst, near = float("inf"), None
    for t in tendons or []:
        if t is new or t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        bx = pr[-1]["pos"][0] - pr[0]["pos"][0]
        by = pr[-1]["pos"][1] - pr[0]["pos"][1]
        bn = math.hypot(bx, by) or 1.0
        if abs(ax * bx / bn + ay * by / bn) < 0.7071:
            continue
        here = min(dist(q["pos"], r["pos"]) for q in inner for r in pr)
        if here < worst:
            worst, near = here, t
    return worst, near


def _crowded_by_thin_neighbour(new, tendons, params):
    """
    **18.27: كابل رفيع مابيتحطش جنب كابل رفيع.**

    قاعدة المهندس بالحرف: «ماتفضلش تزوّد كابل 2 استرند جنب كابل 2
    استرند ماشيين جنب بعض بالظبط - زوّد عدد الاسترندات في الكابل
    الحالي وخلاص». وهي قاعدة تنفيذ قبل ما تكون قاعدة تصميم: كابلين
    بـ2 استرند على بُعد نص متر = ضعف المراسي وضعف الدكتات وضعف الشد،
    مقابل نفس القوة اللي كابل واحد بـ4 بيديها - وبياكلوا من عرض
    البلاطة اللي كابل تالت كان ممكن يحتاجه.

    الشرط الأساسي: **الجار لسه فيه مكان**. لو هو عند أقصى عدد
    استرندات، يبقى الكابل الجديد هو الحل الوحيد فعلاً وبيعدّي.

    والرفض مابيضيّعش القوة: بيترفض بـ `_no_room`، وهو نفس الباب اللي
    `tendons_from_deficit` بيعدّي منه عشان يحط الاسترندات على الكابلات
    اللي في الحارة.
    """
    thin = float(getattr(params, "thin_neighbour_gap", 0.0) or 0.0)
    if thin <= 0:
        return False
    cap = int(getattr(params, "max_strands", 5) or 5)
    worst, near = nearest_parallel(new, tendons)
    return (near is not None and worst < thin
            and int(near.get("strands") or 0) < cap)


def plan_added_tendon(run, tendons, params, extend_m=None, strip=12.0,
                      site=None):
    """
    **خطة** الكابل الإضافي: مين المانح، ومن أنهي محطة لأنهي محطة عليه.

    الخطوة دي كانت جوّه make_added_tendon، وفصلها هو اللي بيخلّي
    الكوّمة تتحل: سلسلتين على إطارين مختلفين ممكن يطلعوا على **نفس
    الكابل المانح وفي نفس المدى** - فيتبنوا كابلين بنفس الإحداثيات
    بالظبط. مقيس على موديل من الموديلات: 48 كابل إضافي، 4 أزواج منهم
    على بُعد **صفر** من بعض. لما الخطط بتتحسب الأول، اللي بيتلامسوا
    منها بيتلموا في خطة واحدة أطول - وده بالظبط اللي المهندس طلبه:
    "زوّد طول الكابل، مش تركّب اتنين فوق بعض".

    بترجّع dict أو None، ومعاها سبب الرفض في "why" لما ترجّع None.
    """
    #  **18.72: المانح الأقرب للرسوب، مش أول واحد بنفس التغطية.**
    #  الكابل الجديد نسخة من مسار المانح مزحلقة جنبه، فالمانح هو اللي
    #  بيحدد الحديد الجديد هيقع فين. القاعدة كانت `n > bn` - أول كابل
    #  بأكبر تغطية في ترتيب اللستة يكسب، والترتيب ده مالوش علاقة
    #  بمكان القراءة الراسبة. لما يبقى فيه كذا كابل بنفس التغطية،
    #  أقربهم لنص الحارة هو اللي الحديد المحطوط جنبه هيشتغل فعلاً.
    _mid = None
    if run:
        _mx = sum(d["mid"][0] for d in run) / float(len(run))
        _my = sum(d["mid"][1] for d in run) / float(len(run))
        _mid = (_mx, _my)
    best, bn, bd = None, 0, 1e18
    for t in tendons:
        if t.get("added"):
            continue
        n = sum(1 for d in run if _tendons_over_span([t], d, strip))
        if n == 0:
            continue
        near = 0.0
        if _mid is not None:
            pr = t.get("profile") or []
            near = min((dist(_mid, q["pos"]) for q in pr), default=1e18)
        if n > bn or (n == bn and near < bd - 1e-9):
            best, bn, bd = t, n, near
    if best is None or bn == 0:
        return None
    prof = best.get("profile") or []
    if len(prof) < 3:
        return None

    sts = []
    for d in run:
        for q in (d["a"], d["b"], d["mid"]):
            st, off = _station_of(prof, tuple(q))
            if off <= strip:
                sts.append(st)
    if not sts:
        return None
    lo, hi = min(sts), max(sts)

    total = sum(dist(prof[i]["pos"], prof[i + 1]["pos"])
                for i in range(len(prof) - 1))
    ext = float(extend_m if extend_m is not None
                else getattr(params, "efm_added_extend", 2.0) or 2.0)
    if ext <= 0:
        ext = 2.0
    lo = max(0.0, lo - ext)
    hi = min(total, hi + ext)
    return {"donor": best, "lo": lo, "hi": hi, "total": total,
            "runs": [list(run)], "ext": ext}


def merge_added_plans(plans, params):
    """
    خطتين على نفس الكابل المانح ومداهما متلامس -> خطة واحدة أطول.

    الشرط: نفس المانح، والفراغ بينهما أصغر من الامتداد المسموح. ساعتها
    الاتحاد [min(lo), max(hi)] كابل واحد بيغطي الاتنين. ده بيمنع
    الكابلات المتكوّمة من أصلها بدل ما يعالجها بعد ما تترسم.
    """
    out = []
    for pl in plans:
        hit = None
        for q in out:
            if q["donor"] is not pl["donor"]:
                continue
            gap = max(pl["lo"], q["lo"]) - min(pl["hi"], q["hi"])
            if gap <= pl["ext"]:
                hit = q
                break
        if hit is None:
            out.append(pl)
            continue
        hit["lo"] = min(hit["lo"], pl["lo"])
        hit["hi"] = max(hit["hi"], pl["hi"])
        hit["runs"].extend(pl["runs"])
    return out


def build_added_tendon(plan, tendons, params, site=None):
    """
    يبني الكابل الإضافي من خطته: نسخة من مسار المانح وبروفايله،
    مقصوصة على المدى، مع أنكر على كل طرف، ومزحلقة عمودياً عشان تقع بين
    الكابلات مش فوقها.
    """
    best = plan["donor"]
    prof = best.get("profile") or []
    lo, hi, total = plan["lo"], plan["hi"], plan["total"]
    run = [d for r in plan["runs"] for d in r]

    #  التقريب للحرف: أنكر واقف على بُعد متر أو اتنين من حرف البلاطة
    #  مالوش لازمة - جيب شد جوّه البلاطة عشان تكسب مترين.
    snap = float(getattr(params, "efm_added_snap", 2.0) or 0.0)
    snapped = []
    if snap > 0:
        if lo <= snap:
            lo = 0.0
            snapped.append("start")
        if total - hi <= snap:
            hi = total
            snapped.append("end")
        for poly in ((site or {}).get("openings") or []):
            for q in poly:
                st, off = _station_of(prof, q)
                if off > 1.5:
                    continue
                if 0.0 < lo - st <= snap:
                    lo = st
                    snapped.append("opening")
                if 0.0 < st - hi <= snap:
                    hi = st
                    snapped.append("opening")

    #  أقل من 6 م كابل بأنكرين مالوش معنى تنفيذي. **بس** الرد الصح مش
    #  إننا نسيبه: بحر 81-1 عليه 321 كجم حديد سفلي وكان بيترمي لأن
    #  مداه 5 م. بنمدّه للستة على المانح - في الاتجاهين لو فيه مكان.
    if hi - lo < 6.0 and total >= 6.0:
        need = (6.0 - (hi - lo)) / 2.0
        lo2, hi2 = lo - need, hi + need
        if lo2 < 0.0:
            hi2 += -lo2
            lo2 = 0.0
        if hi2 > total:
            lo2 -= (hi2 - total)
            hi2 = total
        lo, hi = max(0.0, lo2), min(total, hi2)
        snapped.append("stretched to 6 m")
    if hi - lo < 6.0:
        return None
    #  الكابل اللي بيغطي طول المانح كله مش "إضافي" بالمعنى الضيّق -
    #  بس رفضه كان بيسيب أتقل بحر في البلاطة من غير أي علاج: بحر 39-1
    #  عليه 1,906 كجم حديد سفلي، وسلسلته بتغطي 127 م من 129 م، فالقاعدة
    #  كانت بتشيله. إطار محتاج قوة على طوله محتاج **كابل كامل زيادة في
    #  الحارة**، مش لا شيء. بيتبني عادي وبيتعلّم إنه كامل الطول.
    full = (hi - lo) > 0.85 * total

    pts = [dict(q) for q in prof
           if lo < _station_of(prof, q["pos"])[0] < hi]
    a_pos = _profile_point_at(prof, lo)
    b_pos = _profile_point_at(prof, hi)
    try:
        anchor = float(params.slab_thickness) / 2.0
    except Exception:
        anchor = 140.0
    head = {"pos": a_pos, "depth": anchor, "drop_idx": -1,
            "high": True, "sag": False, "manual": True}
    tail = {"pos": b_pos, "depth": anchor, "drop_idx": -1,
            "high": True, "sag": False, "manual": True}
    prof_new = [head] + pts + [tail]
    if len(prof_new) < 3:
        return None

    new = {k: v for k, v in best.items()
           if k not in ("profile", "path", "_deleted", "jacks", "nodes",
                        "live_at_start", "live_at_end", "governing")}
    new["profile"] = prof_new
    new["added"] = True
    #  الكابل ده **إحنا** رسمناه، مش مستورد. علامة as_drawn معناها
    #  "ده بروفايل مهندس تاني، ماتلمسوش" - وحطها هنا كان بيعفي الكابل
    #  الجديد من كل القواعد، ومنها نصف القطر الأدنى.
    new["as_drawn"] = False
    new["governing"] = {"efm_added": True}
    new["length"] = hi - lo
    new["full_length"] = bool(full)
    new["strands"] = max(int(getattr(params, "min_strands", 2) or 2), 1)
    new["spans"] = [d["name"] for d in run]
    new["snapped"] = sorted(set(snapped))
    new["offset"] = _slide_between_neighbours(new, best, tendons, params)
    #  كابلين إضافيين في نفس الفراغ لازم يبعدوا عن بعض بالحد الأدنى
    #  بين الكابلات، مش بحد الخلوص العام. من غير ده الحارة اللي محتاجة
    #  كابلين بتاخدهم ملزوقين - مقيس: 3 أزواج على بُعد أقل من 40 سم.
    #  **المسافة بتتقاس من كل الكابلات، مش من المضافة بس.**
    #  الشرط كان `if not t.get("added")` -> يعني الكابل الجديد كان
    #  بيتقاس على المضافين قبله وبس، والكابلات الأصلية مالهاش أي وزن
    #  في الحكم. النتيجة على موديل مسلَّم: أقرب كابلين في نفس الاتجاه
    #  131 مم، و14 زوج تحت 40 سم - 9 منهم في X. اللي بيشوفه المهندس
    #  على الشاشة هو كابل أفقي ملزوق في كابل أفقي، وده مش قابل
    #  للتنفيذ أصلاً.
    #  والمانح نفسه داخل في القياس: الكابل الجديد نسخة منه مزحلقة
    #  جنبه، فلو الزحلقة أقل من الحد يبقى مافيش مكان له من أصله.
    min_gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.0)
    if min_gap > 0:
        ax = new["profile"][-1]["pos"][0] - new["profile"][0]["pos"][0]
        ay = new["profile"][-1]["pos"][1] - new["profile"][0]["pos"][1]
        an = math.hypot(ax, ay) or 1.0
        ax, ay = ax / an, ay / an
        worst, _near = nearest_parallel(new, tendons)
        if worst < min_gap:
            #  الحارة مليانة. الرد الصح مش إننا نحشره - الرد إن
            #  الاسترندات تروح للكابلات اللي هناك بالفعل، وده اللي
            #  بيحصل في tendons_from_deficit بعد الرفض ده.
            new["_no_room"] = round(worst, 3)
            return None
        if _crowded_by_thin_neighbour(new, tendons, params):
            #  نفس الباب: `_no_room` هو اللي بيوصّل الطلب للكابلات
            #  اللي في الحارة بدل ما يضيع.
            new["_no_room"] = round(worst, 3)
            new["_thin_neighbour"] = round(worst, 3)
            #  والعدّ على الـ params عشان الرن يقدر يقول القاعدة اشتغلت
            #  كام مرة. من غير السطر ده القاعدة بتشتغل في الضلمة: على رن
            #  المهندس الفجوات تحت 0.6 م في X نزلت من 8 لـ 1 ومافيش ولا
            #  كلمة في اللوج تقول ليه.
            try:
                params._thin_rejects = list(
                    getattr(params, "_thin_rejects", None) or [])
                params._thin_rejects.append(round(worst, 3))
            except Exception:
                pass
            return None
    if new.get("too_close") is not None:
        #  مافيش مكان بين الكابلات للكابل ده أصلاً - أحسن مايترسمش
        #  من إنه يترسم ملزوق في كابل تاني. الحد: نص الخلوص المطلوب.
        #  كابل على بُعد 10 سم من جاره مش قابل للتنفيذ - الحارة هناك
        #  مليانة أصلاً، والبحر هياخد استرندات على الكابلات الموجودة
        #  في خطوة التوزيع بدل ما نحشر كابل مكانش ليه مكان.
        floor = max(0.5 * float(getattr(params, "efm_added_clear", 0.25)
                                or 0.25), 0.10)
        if float(new["too_close"]) < floor:
            return None
    #  **18.72: الحديد الجديد مايتحطش في ظل كمرة ساقطة.**
    #  الكمرة الساقطة ركيزة: البلاطة بتشيل **بينها**، فالكابل الماشي
    #  جنبها عرضه الحامل قريب من الصفر. حديد جديد هناك بيشتري ضغط
    #  محوري وبس، والقطاع اللي طلبه بيفضل راسب فالدورة الجاية بتزوّد
    #  تاني. المسح مابيحصلش (كابل موجود قرار المهندس)، لكن **الإضافة**
    #  في الظل غلط في كل الحالات - العلاج بتاعها حديد جوّه الكمرة
    #  بغطسة عمقها، وده اللي اللوج بيقوله.
    try:
        hit = tendons_in_beam_shadow([new], site, params) if site else []
        if hit:
            new["_beam_shadow"] = True
            #  العدّ على الـ params زي `_thin_rejects` - القاعدة اللي
            #  بتشتغل في الضلمة مافيش منها فايدة.
            try:
                _b = hit[0][2]
                params._shadow_rejects = list(
                    getattr(params, "_shadow_rejects", None) or [])
                params._shadow_rejects.append(
                    (round(new["profile"][0]["pos"][0], 2),
                     round(new["profile"][0]["pos"][1], 2),
                     round(float(_b.get("depth", 0.0) or 0.0), 0)))
            except Exception:
                pass
            return None
    except Exception:
        pass
    return new


def merge_crowded_added(tendons, params, job=None):
    """
    كابل **مضاف** واقف أقرب من الحد الأدنى من كابل موازي له: استرنداته
    بتروح للجار، وهو بيتشال.

    ليه ده لازم يتعمل على الموديل الموجود مش بس يتمنع في الجديد: نسخة
    قديمة كانت بتقيس المسافة على الكابلات **المضافة** بس، فالكابل
    الجديد كان يقدر يقف 13 سم من كابل أصلي ويعدّي. الموديل اللي طلع من
    الرن ده فيه 14 زوج تحت 40 سم، أقربهم 131 مم - كابلين أفقيين فوق
    بعض، وده مش قابل للتنفيذ: مافيش مكان لدكتين ولا لأنكرين.

    القوة مابتضيعش: استرندات الكابل المشال بتتحط في جاره لحد أقصى عدد
    في الإعدادات. واللي مايتحملش بيتقال بالرقم بدل ما يختفي.

    الكابلات الأصلية مابتتلمسش أبداً - دي حاجة المهندس التاني، ولو
    اتنين منها قريبين من بعض ده قراره هو.
    """
    gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.0)
    cap = int(getattr(params, "max_strands", 8) or 8)
    if gap <= 0:
        return 0, 0

    def _ax(t):
        pr = t.get("profile") or []
        if len(pr) < 2:
            return None
        dx = pr[-1]["pos"][0] - pr[0]["pos"][0]
        dy = pr[-1]["pos"][1] - pr[0]["pos"][1]
        n = math.hypot(dx, dy) or 1.0
        return (dx / n, dy / n)

    removed, moved, lost = 0, 0, 0
    for t in sorted([q for q in tendons
                     if q.get("added") and not q.get("_deleted")],
                    key=lambda q: int(q.get("strands") or 0)):
        ua = _ax(t)
        if ua is None:
            continue
        best, bd = None, 1e9
        for o in tendons:
            if o is t or o.get("_deleted"):
                continue
            ub = _ax(o)
            if ub is None or abs(ua[0] * ub[0] + ua[1] * ub[1]) < 0.7071:
                continue
            d = min(dist(q["pos"], r["pos"])
                    for q in t["profile"] for r in o["profile"])
            if d < bd:
                bd, best = d, o
        if best is None or bd >= gap:
            continue
        n = int(t.get("strands") or 0)
        room = max(cap - int(best.get("strands") or 0), 0)
        take = min(n, room)
        best["strands"] = int(best.get("strands") or 0) + take
        t["_deleted"] = True
        t["_merged_into"] = best          # 17.7: استرنداته راحت فين
        removed += 1
        moved += take
        lost += (n - take)
    #  **الأزواج اللي مش قادرين نلمسها.** موديل اتعمل بنسخة قديمة
    #  كابلاته المضافة مالهاش علامة، فمش هينفع نشيلها - وسكوتنا عنها
    #  معناه إن التحليل ماشي على قوة مش قابلة للتنفيذ. فبتتقال بالاسم
    #  والإحداثي، والقرار قرار المهندس.
    if job:
        left, seen = [], set()
        alive = [q for q in tendons if not q.get("_deleted")]
        for i, t in enumerate(alive):
            ua = _ax(t)
            if ua is None:
                continue
            for o in alive[i + 1:]:
                ub = _ax(o)
                if ub is None or abs(ua[0] * ub[0] + ua[1] * ub[1]) < 0.7071:
                    continue
                d = min(dist(q["pos"], r["pos"])
                        for q in t["profile"] for r in o["profile"])
                if d >= gap:
                    continue
                c = ((t["profile"][0]["pos"][0]
                      + t["profile"][-1]["pos"][0]) / 2.0,
                     (t["profile"][0]["pos"][1]
                      + t["profile"][-1]["pos"][1]) / 2.0)
                k = (round(c[0], 1), round(c[1], 1), round(d, 3))
                if k in seen:
                    continue
                seen.add(k)
                left.append((d, c, t, o))
        if left:
            left.sort(key=lambda z: z[0])
            job.warn(f"{len(left)} pair(s) of tendons running the same way "
                     f"sit closer than the {gap:.2f} m minimum gap, and none "
                     f"of them is one this run may remove - they came in "
                     f"with the model, from your own layout or from a run "
                     f"made before the gap was checked against existing "
                     f"tendons.")
            for d, c, t, o in left[:8]:
                job.warn(f"    {d * 1000:.0f} mm apart near "
                         f"({c[0]:.1f}, {c[1]:.1f}) - "
                         f"{t.get('strands')} and {o.get('strands')} strands")
            job.info("    the analysis treats that force as built. It is "
                     "not: two ducts cannot sit that close, and neither can "
                     "two anchorages. Delete one of each pair in the editor "
                     "and put its strands in the other, or accept that the "
                     "section results there are optimistic.")
    if job and removed:
        job.warn(f"{removed} added tendon(s) were standing closer than the "
                 f"{gap:.2f} m minimum gap to a tendon running the same way "
                 f"- the closest pair was unbuildable, not tight. They have "
                 f"been taken out and {moved} of their strand(s) moved into "
                 f"the neighbour they were crowding.")
        if lost:
            job.warn(f"    {lost} strand(s) could not go anywhere: the "
                     f"neighbour is already at the {cap}-strand maximum. "
                     f"That force is genuinely not placeable there at this "
                     f"spacing, and the section under it needs depth or "
                     f"reinforcement rather than more prestress.")
        job.info("    your own tendons are never touched by this - only "
                 "ones the loop added. Two of yours sitting close is your "
                 "decision.")
    return removed, moved


def make_added_tendon(run, tendons, params, extend_m=None, strip=12.0,
                      site=None):
    """
    كابل إضافي بيغطي سلسلة البحور المحتاجة **وبس**، بدل ما نزوّد
    استرندات على كابل ماشي طول البلاطة.

    السبب مقيس: على موديل الصفا، كابل طوله 60.3 م بيعدّي على 34 بحر
    و16 بس منهم قصّروا. على كل الكابلات: 1,393 عبور بحر، 674 منهم
    محتاج قوة - يعني **52% من القوة المضافة بتنزل في بحر مش محتاجها**.

    بقت غلاف على خطوتين: خطة (مين المانح ومن فين لفين) وبناء. مسارات
    ال FEM وال balance load بتنده عليها زي ما هي.
    """
    plan = plan_added_tendon(run, tendons, params, extend_m, strip, site)
    if plan is None:
        return None
    return build_added_tendon(plan, tendons, params, site)


def _clamp_strands(n, params):
    """
    عدد استرندات كابل حقيقي: من الحد الأدنى للحد الأقصى في الإعدادات.

    الحساب كان بيطلع 1 على بحور كتير والكابل بيتكتب باسترند واحد -
    وده مش كابل. أقل حاجة اتنين، وأكتر حاجة الحد الأقصى.
    """
    lo = max(int(getattr(params, "min_strands", 2) or 2), 1)
    hi = max(int(getattr(params, "max_strands", 5) or 5), lo)
    return max(lo, min(int(n), hi))


def split_added_tendons(tendons, advice, params, job=None):
    """
    الكابل الإضافي وصل للحد الأقصى ولسه البحر قاصر؟ يتشال ويتحط بدله
    **كابلين** في نفس المسافة - لو المسافة تسمح.

    القاعدة: في فراغ عرضه G بين كابلين موجودين، عدد n كابلات إضافية
    بيقسّموه لـ n+1 مسافة، وكل واحدة لازم تبقى ≥ الحد الأدنى بين
    كابلين. على مسافة 1.5 م والحد 0.40 م: كابل واحد -> 0.75 (تمام)،
    اتنين -> 0.50 (تمام)، تلاتة -> 0.375 (تحت الحد). يعني اتنين هما
    الأقصى.

    بترجّع (كام مجموعة اتوسّعت, كام مجموعة المسافة ماسمحتش).
    """
    min_gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    cap = int(getattr(params, "max_strands", 12) or 12)
    short = set()
    for d in advice:
        short.add(d["key"])

    groups = {}
    for t in tendons:
        if t.get("added") and t.get("_base"):
            groups.setdefault(tuple(t.get("span_keys") or ()), []).append(t)

    grew, blocked = 0, 0
    report = []
    stuck = []
    for keys, grp in groups.items():
        if not keys or not any(k in short for k in keys):
            continue
        if any(int(g.get("strands") or 0) < cap for g in grp):
            continue          # لسه فيه مكان في الكابل نفسه
        n = len(grp) + 1
        gap = abs(float(grp[0].get("_gap") or 0.0))
        if gap <= 0.0 or gap / (n + 1) < min_gap:
            blocked += 1
            stuck.append((keys, gap, n))
            continue

        base = grp[0]["_base"]
        nx, ny = grp[0]["_normal"]
        proto = grp[0]
        total = sum(int(g.get("strands") or 0) for g in grp) + n
        for g in grp:
            g["_deleted"] = True
        made = []
        for k in range(1, n + 1):
            off = gap * k / float(n + 1)
            t = {kk: vv for kk, vv in proto.items()
                 if kk not in ("profile", "_deleted", "jacks", "nodes",
                               "path", "live_at_start", "live_at_end")}
            t["profile"] = [dict(q) for q in proto["profile"]]
            for q, b in zip(t["profile"], base):
                q["pos"] = (b[0] + nx * off, b[1] + ny * off)
                q.pop("_s", None)
            t["_base"] = list(base)
            t["strands"] = _clamp_strands(int(math.ceil(total / float(n))),
                                          params)
            t["offset"] = off
            made.append(t)
        tendons[:] = [x for x in tendons if not x.get("_deleted")]
        tendons.extend(made)
        grew += 1
        report.append((len(grp), n, gap, gap / (n + 1), made[0]["strands"]))
    if job and report:
        #  28 سطر متطابقين مش تقرير. سطر واحد بالخلاصة، وتفصيل بس لو
        #  المسافات اختلفت.
        shapes = sorted({(r[1], round(r[3], 2), r[4]) for r in report})
        job.ok(f"{grew} added tendon(s) had hit the cap of {cap} strands "
               f"with their spans still short, so each was replaced by "
               f"more tendons in the same gap: "
               + " · ".join(f"{n2} at {sp:.2f} m apart, {st} strands each"
                            for n2, sp, st in shapes) + ".")
    if job and stuck:
        gaps = sorted({round(g, 2) for _k, g, _n in stuck})
        job.warn(f"{len(stuck)} run(s) are at the cap of {cap} strands and "
                 f"still short, and there is no room for another tendon: "
                 f"the gap is {'/'.join(f'{g:.2f}' for g in gaps)} m and one "
                 f"more would put them under the {min_gap:.2f} m minimum. "
                 f"Raise the cap, deepen the slab there, or accept the "
                 f"rebar.")
    return grew, blocked


def add_tendons_for_shortfall(tendons, advice, params, job=None, strip=12.0,
                              site=None):
    """
    يرسم كابل إضافي لكل سلسلة بحور محتاجة، ويحط فيه الاسترندات المطلوبة.

    بترجّع (عدد الكابلات المضافة, مجموع استرنداتها, البحور اللي اتغطّت).
    """
    cap = int(getattr(params, "max_strands", 12) or 12)
    allowed = list(getattr(params, "allowed_strands", []) or [])
    #  البحور اللي عليها كابل إضافي من دورة سابقة: مابنضيفش فوقها
    #  تاني. من غير الحاجز ده الكابلات بتتكوّم كل دورة - 102 بقوا 131
    #  ثم 158 على نفس البحور.
    already = set()
    for t in tendons:
        if t.get("added"):
            already.update(t.get("span_keys") or ())
    made, strands = [], 0
    covered = set()
    skipped = 0
    #  الخطط الأول، وبعدين اللمّة: سلسلتين على نفس الكابل المانح ومداهما
    #  متلامس بيبقوا كابل واحد أطول بدل كابلين فوق بعض.
    plans = []
    #  السلاسل اللي عليها كابل إضافي من دورة فاتت: **تتقوّى**، ماتتسابش.
    #  السطر في اللوج كان بيقول "بياخدوا استرندات في كابلهم بدل كابل
    #  تاني جنبه" - وماكانش فيه حاجة بتعمل كده فعلاً. البحور دي كانت
    #  بتتشال من التوزيع كمان (عشان القوة ماتتحطش مرتين)، فالنتيجة
    #  كانت صفر استرند وحلقة بتقف بعد دورتين وهي لسه شايفة عجز.
    grown = grown_s = 0
    #  الكابل الإضافي الواحد ممكن يخدم أكتر من سلسلة - يترفع **مرة
    #  واحدة** في الدورة، مش مرة عن كل سلسلة.
    raised_ids = set()
    for run in _consecutive_runs(advice):
        if all(d["key"] in already for d in run):
            skipped += 1
            covered.update(d["key"] for d in run)
            keys = {d["key"] for d in run}
            want = max(int(math.ceil(d["add"])) for d in run)
            for t in tendons:
                if not t.get("added") or t.get("_deleted"):
                    continue
                if not (keys & set(t.get("span_keys") or ())):
                    continue
                if id(t) in raised_ids:
                    continue
                now = int(t.get("strands") or 0)
                nxt = _clamp_strands(now + max(1, min(want, 2)), params)
                if allowed:
                    up = [a for a in allowed if a > now]
                    nxt = min(nxt, up[0]) if up else now
                if nxt > now:
                    t["strands"] = nxt
                    t.setdefault("governing", {})["efm"] = True
                    raised_ids.add(id(t))
                    grown += 1
                    grown_s += nxt - now
            continue
        pl = plan_added_tendon(run, tendons, params, strip=strip, site=site)
        if pl is not None:
            plans.append(pl)
    n_plans = len(plans)
    plans = merge_added_plans(plans, params)
    merged = n_plans - len(plans)
    for pl in plans:
        run = [d for r in pl["runs"] for d in r]
        #  الكابلات اللي اتعملت في الدورة دي حاجز زي أي كابل تاني
        t = build_added_tendon(pl, tendons + made, params, site)
        if t is None:
            continue
        t["span_keys"] = [d["key"] for d in run]
        covered.update(d["key"] for d in run)
        #  الكابل الإضافي بياخد **نصيب كابل واحد** فوق البحر، مش عجز
        #  البحر كله: البحر فيه كابلات شغّالة بالفعل، والجديد بيضيف
        #  عليها. إداه العجز كامل كان بيطلع الدورة 4,095 استرند-متر بدل
        #  1,521 - يعني أغلى بـ169% من رفع الكابلات الطويلة، وهو المفروض
        #  يبقى أرخص. والباقي بيتظبط في الدورة اللي بعدها بالقياس، زي كل
        #  حاجة في الحلقة.
        share = []
        for d in run:
            n_over = len(_tendons_over_span(tendons, d, strip)) + 1
            share.append(d["add"] / float(max(n_over, 1)))
        want = _clamp_strands(int(math.ceil(max(share))), params)
        if allowed:
            up = [a for a in allowed if a >= want]
            want = up[0] if up else allowed[-1]
        t["strands"] = _clamp_strands(want, params)
        made.append(t)
        strands += t["strands"]
    tendons.extend(made)
    if job and made:
        lens = sorted(t["length"] for t in made)
        job.ok(f"{len(made)} added tendon(s) drawn over the spans that are "
               f"short - {strands} strands in total, lengths "
               f"{lens[0]:.0f} to {lens[-1]:.0f} m (median "
               f"{lens[len(lens) // 2]:.0f} m). They stop where the force "
               f"stops, with an anchorage at each end, instead of running "
               f"the full slab.")
        tight = [t for t in made if t.get("too_close") is not None]
        if tight:
            job.warn(f"{len(tight)} added tendon(s) could not be placed with "
                     f"the clearance asked for - the closest sits "
                     f"{min(t['too_close'] for t in tight) * 1000:.0f} mm "
                     f"from a neighbour. Look at those in the editor before "
                     f"the model goes out.")
        offs = sorted(abs(t.get("offset") or 0.0) for t in made)
        job.info(f"Each one is slid sideways to sit BETWEEN the existing "
                 f"tendons, not on top of one - "
                 f"{offs[0]:.2f} to {offs[-1]:.2f} m across (median "
                 f"{offs[len(offs) // 2]:.2f} m).")
        if merged:
            job.info(f"{merged} pair(s) of neighbouring runs were joined into "
                     f"one longer tendon instead of two tendons sitting on "
                     f"top of each other - the length grew, the count did "
                     f"not.")
        n_full = sum(1 for t in made if t.get("full_length"))
        if n_full:
            job.info(f"{n_full} of them run the full length of the band: the "
                     f"whole frame is short there, so what it needs is one "
                     f"more tendon in the lane, not a short patch.")
        n_snap = sum(1 for t in made if t.get("snapped"))
        if n_snap:
            job.info(f"{n_snap} of them were carried all the way to the slab "
                     f"edge or to an opening rather than stopping a metre or "
                     f"two short - an anchorage that close to an edge is a "
                     f"pocket for nothing.")
        for t in made[:6]:
            job.info(f"    {t['strands']} strands over "
                     f"{', '.join(t['spans'][:4])} - {t['length']:.0f} m"
                     + (f" (run out to the {'/'.join(t['snapped'])})"
                        if t.get("snapped") else ""))
    if job and skipped:
        job.info(f"{skipped} run(s) already carry an added tendon from an "
                 f"earlier round - they get more strands in it rather than a "
                 f"second tendon beside it"
                 + (f": +{grown_s} strands into {grown} of them."
                    if grown else
                    ", but every one of those tendons is already at the "
                    f"{int(getattr(params, 'max_strands', 5) or 5)}-strand "
                    f"cap for an added tendon - splitting the gap is what is "
                    f"left, and that needs room between the neighbours."))
    return len(made), strands + grown_s, covered


def efm_round_report(model, table, advice, objective, rnd, face="both"):
    L = []
    a = L.append
    kgs = sorted(face_kg(v, face) for v in table.values())
    tot = sum(kgs)
    area = model["slab_area"] or 1.0
    what = {"bottom": "bottom-face ", "top": "top-face "}.get(face, "")
    a(f"Round {rnd}: {len(table)} spans · {tot:,.0f} kg of {what}designed "
      f"reinforcement over {area:,.0f} m2 = {tot / area:.2f} kg/m2")
    if kgs:
        a(f"    per span: median {kgs[len(kgs) // 2]:,.0f} kg · "
          f"max {kgs[-1]:,.0f} kg · "
          f"{sum(1 for k in kgs if k <= 1.0)} spans need none")
    for v in sorted(table.values(), key=lambda v: -face_kg(v, face))[:6]:
        a(f"    {v['name']:<10} top {v['top']:>8,.0f}  bot {v['bot']:>8,.0f} "
          f"mm2  {face_kg(v, face):>7,.0f} kg  {v['strands']:>4} strands")
    if advice:
        a(f"    next: +{sum(d['add'] for d in advice)} strands over "
          f"{len(advice)} spans ({objective})")
    return "\n".join(L)


RUN_METHODS = ["calc_all", "calculate_all", "calc", "run_analysis",
               "analyze", "calc_all_and_wait"]


MESH_METHODS = ["generate_mesh", "generate_the_mesh", "mesh"]


def generate_mesh_in_ram(session: RamSession, job: Job, mesh_size=None):
    """
    Build the finite element mesh.

    RAM refuses to calculate without one: "There is no structure to analyze;
    did you forget to generate the mesh?". generate_mesh is on Model, so this
    is a required step before calc_all, not an optional extra.

    The signature is not documented here, so the no-argument form is tried
    first and then the sized form.
    """
    for target, label in ((session.model, "model"),
                          (session.model.cad_manager, "cad_manager")):
        for name in MESH_METHODS:
            fn = safe_get(target, name)
            if not callable(fn):
                continue
            attempts = [("()", lambda f=fn: f())]
            if mesh_size:
                attempts.insert(0, (f"({mesh_size})",
                                    lambda f=fn: f(float(mesh_size))))
            errors = []
            for form, call in attempts:
                try:
                    t0 = datetime.datetime.now()
                    call()
                    dt = (datetime.datetime.now() - t0).total_seconds()
                    job.ok(f"Mesh generated in {dt:.1f} s "
                           f"({label}.{name}{form}).")
                    return True
                except Exception as e:
                    errors.append(f"{name}{form}: {type(e).__name__}: "
                                  f"{str(e)[:90]}")
            for err in errors:
                job.warn(f"    {err}")

    job.error("No mesh generation method could be called. RAM will refuse to "
              "analyse without a mesh.")
    return False


def _plot_dir_hint(path):
    """
    اقتراح اتجاه من اسم الملف - **اقتراح، مش حكم**.

    الملف نفسه مافيهوش الاتجاه (الشرح كامل في StressPlot)، فاللي فاضل
    هو اسم اللي صدّر. الأسماء اللي بتتكرر: `..._X`, `..._Y`, `_lat`,
    `_long`, `latitude`, `longitude`. لو الاسم مالوش دلالة بيرجّع None
    والبرنامج بيسأل.
    """
    b = os.path.splitext(os.path.basename(str(path or "")))[0].lower()
    if re.search(r"(^|[^a-z])(longitud\w*|long|lon)([^a-z]|$)", b):
        return "y"
    if re.search(r"(^|[^a-z])(latitud\w*|lat)([^a-z]|$)", b):
        return "x"
    #  حرف لوحده في آخر الاسم أو بين فواصل
    if re.search(r"(^|[^a-z])y([^a-z]|$)", b) and \
            not re.search(r"(^|[^a-z])x([^a-z]|$)", b):
        return "y"
    if re.search(r"(^|[^a-z])x([^a-z]|$)", b) and \
            not re.search(r"(^|[^a-z])y([^a-z]|$)", b):
        return "x"
    return None


def _dir_name(d):
    """اسم الاتجاه زي ما رام بيسمّيه."""
    return {"x": "X (Latitude)", "y": "Y (Longitude)"}.get(d,
                                                           "direction unknown")


class StressPlot:
    """
    قارئ تصدير Section Analysis Plot من رام (DXF).

    **من 17.0 ده الطريق الاحتياطي.** `RamSectionPlot` بيقرا نفس الأرقام
    من رام مباشرة. الـ API كان بيرجّع Unknown analysis value لأن الجولات
    القديمة كانت بتسأل عنصر البلاطة أو العمود على طبقة أحمال - القيم دي
    عايشة على SpanDesign في طبقة Service Design. والملف المحفوظ لسه
    مافيهوش ولا صف نتايج، فالقراية لازم تبقى والموديل مفتوح. اللوحة المصدّرة
    فيها الطلب والمقاومة بالأرقام والإحداثيات، وفيها التهشير اللي رام
    بيعلّم بيه **المقاطع اللي مش سيفة**.

    اللي بيتقرا:
      · MTEXT بأرقام = القراءات. القيمة اللي بتتكرر أكتر من 20 مرة هي
        حد المقاومة (ثابت على اللوحة)، والباقي طلب.
      · خطوط ليّر RAM_Concept_Service_Design = التهشير على المقاطع
        الراسبة.
    """

    def __init__(self, path, direction=None):
        self.path = path
        self.title = ""
        #  **اتجاه اللوحة.** لوحة الفحص المقطعي في رام بتوصف اتجاه
        #  واحد - Latitude أو Longitude - والاتجاه ده **مش موجود في
        #  الملف**. اتقاس على أربع لوحات من نفس السقف (X و Y، علوي
        #  وسفلي):
        #    · العنوان حرف بحرف واحد في الاتنين:
        #      "Section Analysis Plot: (Gross Section Bottom Concrete
        #      Stress)" - مافيهوش Latitude ولا Longitude.
        #    · سطر الليّرات الظاهرة بيسرد الاتجاهين مع بعض في
        #      الاتنين: "Latitude Span Designs; Longitude Span
        #      Designs" - فمش فارق.
        #    · أسماء ليّرات الـ DXF نفسها واحدة.
        #    · زوايا التهشير 45°/135° في الاتنين (تهشير متقاطع).
        #    · وتوزيع القراءات مابيفرقش: أقرب-جار طلع 52%/48% في
        #      لوحة X و 43%/57% في لوحة Y - ضوضاء، مش إشارة.
        #  يعني مفيش طريق آلي. الاتجاه بيتقال من برّه - والاسم بيدّي
        #  اقتراح بس، والمستخدم هو اللي بيأكّد.
        self.direction = (str(direction).lower().strip()[:1]
                          if direction else None)
        if self.direction not in ("x", "y"):
            self.direction = None
        self.dir_hint = _plot_dir_hint(path)
        labels = []
        hatch = []
        try:
            ents = _dxf_entities(path)
        except Exception:
            ents = []
        for e in ents:
            if e["t"] == "MTEXT":
                t = e.get("text", "")
                try:
                    v = float(t)
                except ValueError:
                    if "Section Analysis Plot" in t or "Plot:" in t:
                        self.title = t.replace("\\P", " | ")
                    continue
                labels.append((e["x"], e["y"], v))
            elif e["t"] == "LINE" and e.get("layer") == \
                    "RAM_Concept_Service_Design":
                a = (e["x"], e["y"])
                b = (e.get("x2", 0.0), e.get("y2", 0.0))
                if dist(a, b) > 0.01:
                    hatch.append((a, b))
        #  وحدة اللوحة: التصدير بيطلع بالمليمتر أحياناً وبالمتر أحياناً.
        #  الموديل شغّال بالمتر، فأي حاجة هنعملها بالإحداثيات دي لازم
        #  تبقى بنفس الوحدة. القياس: لو أكبر إحداثي أكبر من 2000، دي
        #  مليمترات (بلاطة 2 كيلومتر متش موجودة).
        rng = max([abs(x) for x, _y, _v in labels]
                  + [abs(y) for _x, y, _v in labels] + [0.0])
        self.scale = 0.001 if rng > 2000.0 else 1.0
        if self.scale != 1.0:
            labels = [(x * self.scale, y * self.scale, v)
                      for x, y, v in labels]
            hatch = [((a[0] * self.scale, a[1] * self.scale),
                      (b[0] * self.scale, b[1] * self.scale))
                     for a, b in hatch]

        #  **فرز المقاومة عن الطلب.** التصدير بيكتب رقمين عند كل
        #  مقطع: المقاومة والطلب. المقاومة بتتكرر بالحرف عبر اللوحة،
        #  والطلب بيتغيّر.
        #
        #  القاعدة القديمة كانت «اتكرر 20 مرة أو أكتر = مقاومة». وده
        #  اتكسر على سقف حقيقي: اللوحة فيها **تلات** قيم مقاومة -
        #  2.95 (162 مرة)، 0.98 (124)، و**3.68 (12 مرة بس)** لمنطقة
        #  مقاومتها مختلفة. الاتنين الأولانيين عدّوا، والتالتة نزلت
        #  تحت العتبة فاتحسبت **طلب** - يعني 12 لافتة مقاومة اتقروا
        #  على إنهم قطاعات راسبة بـ 0.73 ميجا فوق الحد.
        #
        #  ده فسّر كل حاجة: الأرقام دي ماكانتش بتتحرك مهما زوّدنا
        #  استرندات أو نزّلنا قمم، وكانت بتطلع بنفس القيمة بالظبط في
        #  كل رن - لأنها مش إجهاد أصلاً.
        #
        #  القاعدة الجديدة، متقاسة على 14 لوحة من سقفين:
        #    · اتكررت 5 مرات أو أكتر،
        #    · ومنتشرة على ثلث امتداد اللوحة على الأقل (مش متكتّلة)،
        #    · وموجبة وقيمتها من نفس رتبة باقي المقاومات.
        #  الشرط التالت هو اللي بيستبعد الأرقام اللي حوالين الصفر -
        #  دي بتتكرر طبيعي في أي حقل إجهادات، ومالهاش علاقة بالمقاومة.
        cnt = {}
        pos = {}
        for _x, _y, v in labels:
            k = round(v, 4)
            cnt[k] = cnt.get(k, 0) + 1
            pos.setdefault(k, []).append((_x, _y))
        big = sorted(v for v, n in cnt.items() if n >= 20)
        self.capacity = list(big)
        #  القيم المستبعدة: لافتات مقاومة لمنطقة صغيرة. **مابتدخلش
        #  `capacity`** لأن `limit` بياخد أكبر واحدة، ولو دخلت كان الحد
        #  هيقفز من 2.95 لـ 3.68 على السقف كله وكل القطاعات هتعدّي.
        #  هي بتتشال من الطلب وبس - مش إجهاد، ومش حد.
        self.ignored = []
        if big:
            _xs = [q[0] for q in labels]
            _ys = [q[1] for q in labels]
            _w = max(max(_xs) - min(_xs), max(_ys) - min(_ys)) or 1.0
            _floor = 0.5 * max(big)
            for v, n in cnt.items():
                if v in self.capacity or n < 5 or v <= 0 or v < _floor:
                    continue
                _p = pos[v]
                _sp = max(max(q[0] for q in _p) - min(q[0] for q in _p),
                          max(q[1] for q in _p) - min(q[1] for q in _p)) / _w
                if _sp >= 0.30:
                    self.ignored.append((v, n))
            self.capacity.sort()
        capset = set(self.capacity) | {v for v, _n in self.ignored}
        self.demand = [(x, y, v) for x, y, v in labels
                       if round(v, 4) not in capset]
        self.hatch = hatch

    @property
    def limit(self):
        """حد الشد الحاكم على اللوحة."""
        return max(self.capacity) if self.capacity else None

    @property
    def face(self):
        t = self.title
        return ("top" if "Top" in t else
                ("bottom" if "Bottom" in t else "?"))

    def failing(self):
        """
        [(x, y, الإجهاد, الحد)] لكل قراءة شد عدّت الحد.

        **إشارة اللوحة: الموجب شد، السالب ضغط.** ده اتقاس مش اتفرض،
        على تصدير عزم وتصدير إجهاد من نفس الرن بالظبط:

          · الانحدار بين الاتنين موجب (σ = 0.00686·M − 0.44)، وأكبر
            العزوم بالسالب (−1130 مقابل +434 موجب) - يعني السالب هو
            عزم الأعمدة، والوش السفلي عند العمود **مضغوط**. فالسالب
            في الإجهاد ضغط.
          · عند M = 0 الإجهاد −0.44: قطاع بلا عزم في بلاطة مسبقة
            الإجهاد لازم يكون في ضغط صافي. تاني تأكيد.
          · وأقصى قراءة موجبة على كل لوحة بتقف عند الحد بالظبط
            (2.84 مقابل حد 2.82) - ده شكل مقاومة، مش صدفة.

        الإصدارات لحد 14.9 كانت بتقرا `v < -lim`، يعني بتعلّم **أكتر
        القطاعات ضغطاً** وتسمّيها راسبة. النتيجة إن الحلقة كانت بتحطّ
        كابلات في أكتر مكان مضغوط أصلاً، وتسيب القطاعات المشدودة
        فعلاً من غير علاج.
        """
        lim = self.limit
        if lim is None:
            return []
        return [(x, y, v, lim) for x, y, v in self.demand if v > lim]


def _dxf_entities(path):
    """
    قراءة خام لكيانات الـ DXF اللي محتاجينها: MTEXT و LINE.

    مكتوبة بالإيد عشان ezdxf مش شرط يبقى متثبّت على جهاز المستخدم،
    والتصدير ده ملف نصّي بسيط - زوج (كود، قيمة) في كل سطرين.
    """
    out = []
    cur = None
    txt = []
    with open(path, "r", encoding="utf-8", errors="ignore") as fh:
        lines = fh.read().splitlines()
    i = 0
    while i + 1 < len(lines):
        code = lines[i].strip()
        val = lines[i + 1]
        i += 2
        if code == "0":
            if cur is not None and cur["t"] in ("MTEXT", "LINE"):
                cur["text"] = "".join(txt)
                out.append(cur)
            v = val.strip()
            cur = ({"t": v, "x": 0.0, "y": 0.0, "x2": 0.0, "y2": 0.0,
                    "layer": ""} if v in ("MTEXT", "LINE") else None)
            txt = []
            continue
        if cur is None:
            continue
        try:
            if code == "8":
                cur["layer"] = val.strip()
            elif code == "10":
                cur["x"] = float(val)
            elif code == "20":
                cur["y"] = float(val)
            elif code == "11":
                cur["x2"] = float(val)
            elif code == "21":
                cur["y2"] = float(val)
            elif code in ("1", "3"):
                txt.append(val.strip())
        except ValueError:
            continue
    if cur is not None and cur["t"] in ("MTEXT", "LINE"):
        cur["text"] = "".join(txt)
        out.append(cur)
    return out


# ------------------------------------------------------------------------------
#  الفحص المقطعي من رام نفسه (17.0)
# ------------------------------------------------------------------------------
#
#  الأوامر دي مش في توثيق الـ API، بس هي جوّه جدول أوامر Concept.exe
#  نفسه، وعميل ResultAccess بتاع رام بيبنيها بنفس الشكل. اتقاست على
#  `0000_EFM_final-2_EFM_r3.cpt` مقابل التصدير اللي اتعمل منه:
#
#    [GET_ENTITY_LIST][LatitudeSpanDesigns]            على طبقة Service Design
#    [GET_CROSS_SECTION_COUNT]                         على كل SpanDesign
#    [GET_SECTION_SEGMENT][i][DEMAND_SEGMENT]          خط القطاع
#    [GET_SECTION_MAX_FACE_SEGMENT][i][BOTTOM|TOP]     الجزء الحاكم من القطاع
#    [GET_ANALYSIS_USER][0][ContextMaxDemand][SAGrossBottomConcreteStress][i]
#    [GET_ANALYSIS_USER][0][ContextMaxCapacity][SAGrossBottomConcreteStress][i]
#
#  لوحة X = LatitudeSpanDesigns ولوحة Y = LongitudeSpanDesigns. كل رقم
#  مقاومة على اللوحة اتطابق، وكل رقم طلب اتطابق لتلات أرقام معنوية.
#  `GET_CROSS_SECTION_SR` **مش** نسبة إجهاد - دي مكان القطاع على طول
#  البحر (0.197، 0.397، 0.597 ...)، واتقرت غلط مرة قبل كده.

_RAM_SECTION_VALUE = {"bottom": "SAGrossBottomConcreteStress",
                      "top": "SAGrossTopConcreteStress"}


def _ram_float(txt):
    """رقم من رد رام - و None لـ «No Limit» و«No Calc» والفاضي."""
    try:
        v = float(str(txt).strip())
    except (TypeError, ValueError):
        return None
    return v if math.isfinite(v) else None


def _ram_line(txt):
    """
    `[LineSeg2D][[[x0][y0]][[x1][y1]]]` -> ((x0, y0), (x1, y1)).

    الرد بيبتدي باسم النوع، و«2» اللي في LineSeg2D مش إحداثي. قراية
    الأرقام من غير ما يتشال بتزحلق كل الإحداثيات خانة - وده حصل فعلاً:
    المقارنة الأولى طلعت 1% تطابق والمسافات 24 م.
    """
    body = re.sub(r"^\s*\[[A-Za-z][A-Za-z0-9]*\]", "", str(txt or ""))
    v = [float(q) for q in
         re.findall(r"-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?", body)]
    if len(v) < 4:
        return None
    return (v[0], v[1]), (v[2], v[3])


def _mark_shown_sections(rows):
    """
    القطاعات اللي اللوحة بتكتب عليها رقم: **طرفين البحر وكل قمة محلية**.

    اتقاس على اللوحة: 267 قطاع عليه رقم طلب من 688 في X - 65 أول بحر،
    65 آخر بحر، والباقي قمم أو قيعان محلية، وأقصى قطاع في كل بحر عليه
    رقم في الـ 127 بحر من غير استثناء. الحلقة كلها اتعايرت على كثافة
    القراءات دي، فالقراية من رام بتاخد نفس القطاعات - والباقي محفوظ في
    `sections` لو احتجناه.
    """
    ok = [r for r in rows if r["v"] is not None]
    n = len(ok)
    for k, r in enumerate(ok):
        if k == 0 or k == n - 1:
            r["shown"] = True
            continue
        a, b, c = ok[k - 1]["v"], r["v"], ok[k + 1]["v"]
        if (b >= a and b >= c) or (b <= a and b <= c):
            r["shown"] = True


class RamSectionPlot:
    """
    الفحص المقطعي زي ما رام حاسبه، مقروء من الجلسة - بنفس واجهة
    `StressPlot` بالظبط، عشان كل اللي بعده في الحلقة مايحسّش بفرق.

    `demand` = [(x, y, الإجهاد)] للقطاعات اللي اللوحة كانت هتكتب عليها،
    والإشارة زي اللوحة: الموجب شد. `limit` بيطلع نفس حد اللوحة (أكبر
    مقاومة بتغطّي منطقة حقيقية من السقف - شوف التعليق تحت)، فالحلقة بتحكم
    بنفس الطريقة اللي اتعايرت عليها - الفرق إن الأرقام جاية من رام مش DXF.
    """

    source = "ram"

    def __init__(self, face, direction, sections, layer_name="Service Design"):
        self.path = None
        self.face_name = face
        self.direction = direction
        self.dir_hint = direction
        self.scale = 1.0
        self.hatch = []
        self.layer_name = layer_name
        self.title = (f"{layer_name} - Section Analysis Plot: (Gross Section "
                      f"{'Top' if face == 'top' else 'Bottom'} Concrete "
                      f"Stress) - read from RAM")
        self.sections = sections
        shown = [s for s in sections if s.get("shown") and s["v"] is not None]
        self.demand = [(s["x"], s["y"], s["v"]) for s in shown]
        #  **الحد: المقاومة اللي بتغطّي منطقة حقيقية من السقف.** قاعدة
        #  `StressPlot` («اتكررت 20 مرة») اتقاست على لافتات اللوحة، ورام
        #  بيكتب لافتة المقاومة على جزء من القطاعات بس: منطقة الـ 3.68
        #  طلعت 10 لافتات على اللوحة و24 قطاع في القراية من رام - فنفس
        #  القاعدة كانت هتدخّلها وتنطّ الحد لـ 3.68 وتخبّي القطاع الراسب
        #  (حصل في أول اختبار). هنا بنعدّ **البحور**: 3.68 في 6 بحور من 68
        #  في X و3 من 59 في Y، و0.98 و2.95 في أغلب البحور. عتبة 20% من
        #  البحور بتطلّع 2.95 في الاتجاهين، زي اللوحة بالظبط.
        by_span = {}
        for s in sections:
            if s["cap"] is not None:
                by_span.setdefault(round(s["cap"], 4), set()).add(s["span"])
        n_spans = len({s["span"] for s in sections}) or 1
        need = max(2, 0.20 * n_spans)
        big = sorted(c for c, sp in by_span.items() if len(sp) >= need)
        if not big and by_span:
            big = [max(by_span, key=lambda c: len(by_span[c]))]
        self.capacity = big
        self.ignored = sorted((c, len(sp)) for c, sp in by_span.items()
                              if c not in big)
        #  مقاومة كل قطاع لوحده. الـ 0.98 دي **عتبة حديد مش رسوب**: لو
        #  الشد عدّاها القطاع محتاج حديد ملصوق، بس لسه سيف لحد أقصى شد
        #  الكود (2.95 / 3.68). فالحلقة بتحكم بالحد الواحد، والرقم ده مؤشر
        #  حديد بيتقال بس.
        self.over_own = [(s["x"], s["y"], s["v"], s["cap"]) for s in shown
                         if s["cap"] is not None and s["v"] > s["cap"]]

    @property
    def limit(self):
        return max(self.capacity) if self.capacity else None

    @property
    def face(self):
        return self.face_name

    def failing(self):
        lim = self.limit
        if lim is None:
            return []
        return [(x, y, v, lim) for x, y, v in self.demand if v > lim]


# ==============================================================================
#  دفتر التصميم - كل تخطيط اتكتب، ومعاه اللي رام قاله عليه
# ==============================================================================
#  البرنامج بيعمل الزوج ده كل دورة من دورات الحلقة ويرميه: بيرسم كابلات،
#  بيحسب، بيقرا قطاعات، بياخد قراره، وبيعيد. الزوج (التخطيط ← قراءات
#  رام) هو **بالظبط** البيانات اللي أي نموذج متعلّم محتاجها - ومحدش
#  بيحفظه. رن واحد بيعمل من 5 لـ 8 دورات، وكل دورة فيها مئات القراءات.
#
#  اللي بيتحفظ هنا **خام**: الكابلات زي ما اترسمت، والقراءات زي ما رجعت،
#  والباراميترات اللي كانت شغّالة. من غير أي هندسة خصائص - عشان أي فكرة
#  تيجي بعدين تتبني على البيانات دي من غير ما رام يشتغل تاني. كل دورة
#  حوالي 30 كيلوبايت، والرن الكامل ربع ميجا.
#
#  الملف JSONL: سطر لكل دورة، عشان يتقرا بالتدريج ويتزوّد من غير قفل.

DESIGN_LOG_DEFAULT = os.path.join(os.path.expanduser("~"), ".auto_pt_suite",
                                  "design_log")

#  رقم للرن الواحد، بيتعمل مرة واحدة وقت التحميل. من غيره صفوف الدورات
#  بتبقى مكوّمة من غير ما حد يعرف الدورة دي من أي رن - وده بالظبط اللي
#  بيخلّي تتبّع "الدورة دي حسّنت ولا لأ" ممكن.
_DESIGN_RUN_ID = "%s-%d" % (datetime.date.today().strftime("%y%m%d"),
                            os.getpid())

#  الباراميترات اللي بتغيّر التخطيط فعلاً. القايمة مقصودة قصيرة: الصف
#  المحفوظ لازم يفضل مقروء، والباقي متحسب من الكابلات نفسها.
DESIGN_LOG_PARAMS = (
    "slab_thickness", "drop_thickness", "spacing", "band_spacing",
    "edge_offset", "min_strands", "max_strands", "force_per_strand",
    "balance_target", "balance_ratio", "sdl", "live_load",
    "column_bands", "layout_mode", "min_tendon_radius",
    "ram_inflection_ratio", "top_cover", "bot_cover", "anchor_elevation",
    "balance_share_banded", "balance_share_distributed",
)


def _design_log_tendon(t):
    """كابل واحد في أقل صورة بترجّع البروفايل بالكامل."""
    pr = t.get("profile") or []
    return {
        "d": t.get("dir"),
        "n": int(t.get("strands") or 0),
        "added": bool(t.get("added")),
        "mine": bool(t.get("as_drawn") or t.get("from_model")),
        #  [x, y, عمق مم] لكل نقطة، والعلامة: h قمة · s غطسة · . عادية
        "p": [[round(q["pos"][0], 3), round(q["pos"][1], 3),
               round(float(q.get("depth") or 0.0), 1),
               "h" if q.get("high") else ("s" if q.get("sag") else ".")]
              for q in pr],
    }


def design_sample(tendons, plots, params, stem="", stage="", extra=None):
    """
    صف واحد: التخطيط اللي اترسم، والقراءات اللي رام رجّعها عليه.

    بترجّع dict، أو None لو مافيش الزوج كامل - نص الزوج مالوش قيمة
    تدريبية، وحفظه بيوسّخ الدفتر بصفوف مش هتتستعمل.
    """
    live = [t for t in (tendons or []) if not t.get("_deleted")
            and len(t.get("profile") or []) >= 2]
    reads = []
    for pl in (plots or []):
        lim = getattr(pl, "limit", None)
        face = getattr(pl, "face", None)
        d = getattr(pl, "direction", None)
        for x, y, v in getattr(pl, "demand", []) or []:
            reads.append([round(x, 3), round(y, 3), round(float(v), 4),
                          (None if lim is None else round(float(lim), 4)),
                          face, d])
    if not live or not reads:
        return None
    row = {
        "t": datetime.datetime.now().isoformat(timespec="seconds"),
        "build": APP_VERSION,
        "proc": _DESIGN_RUN_ID,
        "run": str(stem or ""),
        "stage": str(stage or ""),
        "params": {k: getattr(params, k, None) for k in DESIGN_LOG_PARAMS},
        "tendons": [_design_log_tendon(t) for t in live],
        "reads": reads,
    }
    if extra:
        row.update(extra)
    return row


def record_design_sample(tendons, plots, params, job=None, stem="",
                         stage="", extra=None):
    """
    بتكتب الصف في دفتر التصميم. بترجّع مسار الملف، أو "" لو ماكتبتش.

    مابترميش استثناء أبداً: ده دفتر، مش جزء من التصميم. رن بيقف لأن
    القرص اتملى أو الفولدر مقفول حاجة مالهاش أي مبرر.
    """
    if not bool(getattr(params, "record_design_log", True)):
        return ""
    try:
        row = design_sample(tendons, plots, params, stem, stage, extra)
        if row is None:
            return ""
        folder = (str(getattr(params, "design_log_dir", "") or "").strip()
                  or DESIGN_LOG_DEFAULT)
        os.makedirs(folder, exist_ok=True)
        path = os.path.join(
            folder, "design_%s.jsonl" % datetime.date.today().isoformat())
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(row, ensure_ascii=False) + "\n")
        return path
    except Exception as e:
        if job:
            job.info(f"    the design log was not written ({e}) - the run is "
                     f"not affected.")
        return ""


def read_design_log(folder=None, limit=0):
    """صفوف الدفتر، الأحدث الأول. `limit` = 0 يعني الكل."""
    folder = (str(folder or "").strip() or DESIGN_LOG_DEFAULT)
    out = []
    try:
        names = sorted(os.listdir(folder), reverse=True)
    except Exception:
        return out
    for name in names:
        if not name.startswith("design_") or not name.endswith(".jsonl"):
            continue
        try:
            with open(os.path.join(folder, name), encoding="utf-8") as fh:
                rows = [json.loads(ln) for ln in fh if ln.strip()]
        except Exception:
            continue
        out.extend(reversed(rows))
        if limit and len(out) >= limit:
            return out[:limit]
    return out[:limit] if limit else out


def design_log_digest(rows):
    """
    (عدد الصفوف, عدد القراءات, عدد الرنّات, أقدم تاريخ, أحدث تاريخ).

    الرقم اللي يهم هو **عدد القراءات**: كل قراية عيّنة تدريب، مش كل رن.
    """
    if not rows:
        return 0, 0, 0, None, None
    reads = sum(len(r.get("reads") or []) for r in rows)
    runs = len({(r.get("proc") or r.get("run") or "") for r in rows})
    ts = sorted(str(r.get("t") or "") for r in rows)
    return len(rows), reads, runs, ts[0], ts[-1]


def read_section_plots_from_ram(session, params, job,
                                layer_name="Service Design"):
    """
    **الأربع لوحات من غير تصدير.** بترجّع [RamSectionPlot] - وش لكل وش
    مطلوب (`efm_face`) × الاتجاهين - من الموديل المفتوح والمتحسوب في
    الجلسة. بترمي استثناء لو مافيش حاجة تتقرا، والحلقة بترجع للوقفة.
    """
    from ram_concept.data import Data

    model = getattr(session, "model", None)
    if model is None:
        raise RuntimeError("no model is open in RAM")
    cad = model.cad_manager
    layer = None
    seen = set()
    for L in list(cad.all_layers) + list(cad._get_children() or []):
        u = getattr(L, "uid", None)
        if u is None or u in seen:
            continue
        seen.add(u)
        if str(getattr(L, "name", "") or "").strip().lower() == \
                layer_name.lower():
            layer = L
            break
    if layer is None:
        raise RuntimeError(f"the model has no '{layer_name}' layer")

    faces = {"both": ("bottom", "top"), "bottom": ("bottom",),
             "top": ("top",)}[_face_of(params)]
    t0 = datetime.datetime.now()
    calls = [0]

    def ask(obj, cmd):
        calls[0] += 1
        return obj._command(cmd)

    plots = []
    for key in ("LatitudeSpanDesigns", "LongitudeSpanDesigns"):
        job.check()
        ids = [int(u) for u in re.findall(
            r"\[(\d+)\]", ask(layer, f"[GET_ENTITY_LIST][{key}]") or "")]
        if not ids:
            continue
        per_face = {f: [] for f in faces}
        votes = [0, 0]
        for uid in ids:
            job.check()
            sd = Data(uid, model)
            try:
                loc = _ram_line(ask(sd, "[GET_LOCATION_USER]"))
                if loc:
                    dx = abs(loc[1][0] - loc[0][0])
                    dy = abs(loc[1][1] - loc[0][1])
                    votes[0 if dx >= dy else 1] += 1
                n = int(str(ask(sd, "[GET_CROSS_SECTION_COUNT]")).strip()
                        or 0)
            except Exception:
                continue
            rows = {f: [] for f in faces}
            for i in range(n):
                try:
                    seg = _ram_line(ask(
                        sd, f"[GET_SECTION_SEGMENT][{i}][DEMAND_SEGMENT]"))
                except Exception:
                    seg = None
                for f in faces:
                    val = _RAM_SECTION_VALUE[f]
                    try:
                        v = _ram_float(ask(
                            sd, f"[GET_ANALYSIS_USER][0][ContextMaxDemand]"
                                f"[{val}][{i}]"))
                        cap = _ram_float(ask(
                            sd, f"[GET_ANALYSIS_USER][0][ContextMaxCapacity]"
                                f"[{val}][{i}]"))
                    except Exception:
                        v = cap = None
                    try:
                        mf = _ram_line(ask(
                            sd, f"[GET_SECTION_MAX_FACE_SEGMENT][{i}]"
                                f"[{f.upper()}]"))
                    except Exception:
                        mf = None
                    ln = mf or seg
                    if ln is None:
                        continue
                    base = seg or ln
                    rows[f].append({
                        "x": (ln[0][0] + ln[1][0]) / 2.0,
                        "y": (ln[0][1] + ln[1][1]) / 2.0,
                        "sx": (base[0][0] + base[1][0]) / 2.0,
                        "sy": (base[0][1] + base[1][1]) / 2.0,
                        "line": base, "v": v, "cap": cap,
                        "span": uid, "i": i, "shown": False})
            for f in faces:
                _mark_shown_sections(rows[f])
                per_face[f].extend(rows[f])
        d = "x" if votes[0] >= votes[1] else "y"
        for f in faces:
            pl = RamSectionPlot(f, d, per_face[f], layer_name)
            if pl.demand:
                plots.append(pl)

    if not plots:
        raise RuntimeError(f"RAM returned no section results on "
                           f"'{layer_name}' - is the model calculated?")
    #  18.29: الزوج (التخطيط ← قراءات رام) بيتحفظ هنا، مكان واحد لكل
    #  الثمن نداءات. الكابلات هي اللي `write_tendons_to_ram` رسمها آخر
    #  مرة - يعني اللي جوّه الموديل اللي رام لسه حاسبه.
    record_design_sample(_LAST_DRAWN.get("tendons"), plots, params,
                         job, stem=str(_LAST_DRAWN.get("stem") or ""),
                         stage=layer_name)
    dt = (datetime.datetime.now() - t0).total_seconds()
    job.ok(f"Section check read straight from RAM ({layer_name}) in "
           f"{dt:.0f} s, {calls[0]:,} questions - no export needed.")
    for pl in plots:
        lim = pl.limit
        job.info(f"    {pl.face} face, {_dir_name(pl.direction)}: "
                 f"{len(pl.demand)} readings from {len(pl.sections)} "
                 f"sections, limit "
                 + (f"{lim:.2f} MPa, {len(pl.failing())} over it"
                    if lim is not None else "not found")
                 + (f" · {len(pl.over_own)} above their rebar threshold"
                    if pl.over_own else ""))
    if any(pl.over_own for pl in plots):
        job.info("    Every reading is judged against the code's maximum "
                 "tension, the limit above. RAM also gives each section its "
                 "own capacity, and where that is lower (the 0.98 MPa "
                 "regions) a section above it needs bonded reinforcement but "
                 "is not failing - it stays safe up to the code maximum. That "
                 "count is a rebar indicator, reported and not acted on.")
    job.info("    Wherever the log below says 'export the plot again' or 'the "
             "next export', read 'the next round': it reads the section check "
             "from RAM again by itself, and nothing needs exporting.")
    return plots


def strand_relief_mpa(pt, tendons, params, face="bottom", half=1.5,
                      direction=None):
    """
    **كام ميجا بيشيلها استرند واحد لكل متر عرض عند النقطة دي** - بالضغط
    المحوري **والعزم اللي غطسة الكابل بتولّده**، مش بالمحوري وحده.

    ده كان أكبر نقص في الحساب كله. الاسترند بيعمل حاجتين:

      1. **ضغط محوري**:  Δσ = P / (1000 × h)
      2. **عزم من موقعه في القطاع**: الكابل عند نقطته الواطية بيبقى
         تحت المحور المحايد بمسافة e، فبيولّد عزم P·e في عكس اتجاه
         عزم الأحمال. والإجهاد اللي بيشيله من الليفة السفلية:
             Δσ = P·e / Z ،  Z = 1000·h²/6  لكل متر عرض

    القديم كان بيحسب رقم 1 وبس - والسطر اللي تحته في اللوج كان بيعترف
    بده كل مرة: «الحساب على الضغط المحوري وحده؛ الكابل الجديد بيوازن
    حمل كمان». على بلاطة 280 مم واسترند 98 كيلو نيوتن عند نقطة واطية
    (e ≈ 100 مم)، الجزء العزمي **1.5 ضعف** المحوري - يعني الحساب كان
    بيطلب أكتر من الضعف.

    **والإشارة بتفرق حسب الوش**: عند نقطة واطية (e موجب) الكابل بيريّح
    الليفة السفلية ويضغط على العلوية؛ عند القمة بالعكس. فالكابل اللي
    بروفايله مقلوب على القطاع بيدّي الجزء المحوري بس - والعزم بتاعه
    بيشتغل ضدّه، وده بالظبط اللي تحذير «البروفايل بالمقلوب» بيقوله.

    بترجّع (ميجا لكل استرند لكل متر عرض، كام كابل دخل الحساب).
    """
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    p1 = float(params.force_per_strand) * 1000.0          # نيوتن
    axial = p1 / (1000.0 * max(h, 1e-6))                  # ميجا
    z = 1000.0 * h * h / 6.0                              # مم³ لكل متر
    want = (str(direction).lower()[:1] if direction else None)
    vals = []
    for t in (tendons or []):
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        if want in ("x", "y"):
            ax = pr[-1]["pos"][0] - pr[0]["pos"][0]
            ay = pr[-1]["pos"][1] - pr[0]["pos"][1]
            n = math.hypot(ax, ay) or 1.0
            if abs((ax if want == "x" else ay) / n) < 0.7071:
                continue
        q = min(pr, key=lambda r: dist(pt, r["pos"]))
        if dist(pt, q["pos"]) > half:
            continue
        #  العمق من سطح البلاطة لمركز الكابل، والبُعد عن المحور المحايد
        depth = float(q.get("depth") or h / 2.0)
        e = depth - h / 2.0        # موجب = تحت المحور (نقطة واطية)
        flex = p1 * e / max(z, 1e-9)
        #  الوش السفلي بيستفيد من e الموجب؛ العلوي من السالب
        gain = axial + (flex if face == "bottom" else -flex)
        vals.append(gain)
    if not vals:
        return axial, 0
    vals.sort()
    med = vals[len(vals) // 2]
    #  **الكابل بيشتغل ضد القطاع؟ ده مش سبب لطلب استرندات أكتر.**
    #  لو الرقم طلع أقل من المحوري، معناه إن الكابل عند نقطته العالية
    #  فوق قطاع شغّال موجب - غطسته بتزوّد الشد السفلي بدل ما تشيله.
    #  الرد الصح هو تحريك النقطة، مش ضخ قوة في المكان الغلط: لو
    #  قسّمنا على رقم صغير كان الطلب هيقفز من 1.9 استرند/م لـ 7.4،
    #  يعني أربع أضعاف قوة في أسوأ مكان ممكن تتحط فيه.
    #  فبنسقّف عند المحوري ونعلّم القراءة، والتقرير بيسمّيها.
    if med < axial:
        return axial, -len(vals)          # سالب = البروفايل ضد القطاع
    return med, len(vals)


def plot_deficits(plot, params, thickness_mm=None, tendons=None):
    """
    من الإجهاد الراسب إلى **عدد الاسترندات المطلوبة لكل متر عرض**.

        الزيادة عن الحد  Δσ  (ميجا باسكال)
        ÷ اللي الاسترند الواحد بيشيله عند النقطة دي  (ميجا لكل متر عرض)
        = عدد الاسترندات لكل متر

    واللي الاسترند بيشيله بيتحسب بالمحوري **والعزم من غطسته** - شوف
    `strand_relief_mpa`. القديم كان بالمحوري وحده، فكان بيطلب أكتر من
    الضعف عند القطاعات اللي في نص البحر.

    بترجّع [{x, y, over, kn_per_m, strands_per_m, relief}] بالأسوأ.
    """
    h = float(thickness_mm if thickness_mm is not None
              else getattr(params, "slab_thickness", 280.0) or 280.0)
    p_strand = float(params.force_per_strand)                  # kN
    face = getattr(plot, "face", "bottom")
    dirn = getattr(plot, "direction", None)
    axial = p_strand / max(h, 1e-6)
    out = []
    for x, y, v, lim in plot.failing():
        over = v - lim                      # الموجب شد؛ الفائض فوق الحد
        kn = over * h                       # N/mm × mm = kN لكل متر عرض
        if tendons:
            rel, n_t = strand_relief_mpa((x, y), tendons, params, face,
                                         direction=dirn)
        else:
            rel, n_t = axial, 0
        out.append({"x": x, "y": y, "over": over, "kn_per_m": kn,
                    "relief": rel, "n_tendons": abs(n_t),
                    "profile_against": bool(n_t < 0),
                    "strands_per_m": over / max(rel, 1e-9)})
    out.sort(key=lambda d: -d["over"])
    return out


def precompression_at(pt, tendons, params, half=1.5):
    """
    الضغط المسبق الموجود فعلاً عند نقطة، بالميجا باسكال.

    الاسترندات اللي بتعدّي في حدود ±half متر من النقطة، مقسومة على
    مساحة القطاع (العرض × السُمك). ده تقدير شريط، مش تحليل - بس بيدّي
    الرقم اللي المحادثة كلها كانت ناقصاه.
    """
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    p1 = float(params.force_per_strand)                  # kN للاسترند
    n = 0
    for t in tendons:
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if any(dist(pt, q["pos"]) <= half for q in pr):
            n += int(t.get("strands") or 0)
    width = 2.0 * half
    return (n * p1) / max(width * h, 1e-6), n


def thin_over_provided(tendons, plots, params, job=None, half=1.5,
                       budget=None):
    """
    **يشيل استرندات من المكان اللي مابيستفدش بيها** - وبس بالشروط.

    التوزيع الموروث موحّد: نفس عدد الاسترندات فوق بحر مشدود وفوق بحر
    مضغوط. والحلقة لحد دلوقتي بتزوّد وبس، فالفايض بيفضل مكانه للأبد.
    على سقف حقيقي: 19 قراءة عليها 20 استرند في 1.5 م بتدّي 2.34 ميجا
    ضغط، والقطاع تحتها قراءته -1.12 ميجا - يعني مضغوط أصلاً. القوة دي
    مش بتعمل حاجة، والاسترندات دي لو خرجت تدفع تمن الحارات القصيرة
    من غير أي زيادة على إجمالي السقف.

    الشروط، وكلها لازم تتحقق مع بعض:

      1. **الكابل مايعديش على أي قطاع راسب** - ولا واحد. كابل بيمر
         على قراءة فوق الحد مش مرشح للتخفيف مهما كان الباقي مريح.
      2. **أسوأ قراءة على مساره تفضل تحت الحد بهامش** بعد التخفيف،
         محسوبة بنقص الضغط المحوري `k·P/(عرض·سُمك)`.
      3. **مايقلش عن أقل عدد استرندات** في الإعدادات.
      4. **سقف على النزول**: استرندين بالكتير من الكابل الواحد، وربع
         عدده. التخفيف الكبير قرار تخطيط مش تعديل.
      5. **ميزانية**: مش أكتر من اللي الرن زوّده، عشان السقف
         مايخفّش صافي من غير ما تطلب انت كده.

    ⚠ **اللي الحساب ده مابيشوفوش**: الاسترند بيدّي ضغط محوري **و**
      حمل موازن من الغطسة. الشيل بيودّي الاتنين. الحساب هنا على
      الضغط المحوري بس، فهو **متفائل** - والهوامش فوق موضوعة عشان
      كده. والترخيم والتشقق مش في الرقم ده خالص. فالتصدير اللي بعده
      هو الحكم، مش الدالة دي.

    بترجّع (كام كابل خفّ، كام استرند خرج).
    """
    #  **كل اللوحات مع بعض، مش واحدة واحدة.** أول نسخة كانت بتخفّف
    #  على لوحة X وبعدين على لوحة Y، فكابل نضيف في X ممكن يكون ماشي
    #  على قطاع راسب في Y - وياخد تخفيف مايستحقهوش. اختبار الأمان
    #  مسك واحد بالظبط. والكابل كان بياخد تخفيف مرتين، مرة لكل لوحة،
    #  فسقف «استرندين بالكتير» كان بيتكسر من غير ما حد يشوف.
    plots = [q for q in (plots if isinstance(plots, (list, tuple))
                         else [plots]) if q is not None
             and q.limit is not None]
    if not plots or not tendons:
        return 0, 0
    lim = min(q.limit for q in plots)
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    p1 = float(params.force_per_strand)
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    #  الهامش اللي القطاع لازم يفضل تحته بعد التخفيف
    keep = float(getattr(params, "efm_thin_margin", 0.60) or 0.60)
    #  ميجا لكل استرند على عرض الشريط. **18.30: من `mpa_per_strand`
    #  مش نسخة تالتة من نفس المعادلة** - وإلا العامل المقاس من دفتر
    #  المهندس بيتطبّق في مكانين ويتنسى في التالت.
    _ = (h, p1)

    rows = [(x, y, v, getattr(pl, "face", None))
            for pl in plots for x, y, v in pl.demand]
    fails = [(x, y) for pl in plots for x, y, v, l in pl.failing()]
    out_n, out_s = 0, 0
    detail = []
    for t in tendons:
        if t.get("_deleted"):
            continue
        n_now = int(t.get("strands") or 0)
        if n_now <= n_min:
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        #  **قاعدة قاطعة**: قطاع راسب واحد على مساره في أي لوحة = خلاص.
        if any(dist(f, q["pos"]) <= half for f in fails for q in pr):
            continue
        near = [(v, f) for x, y, v, f in rows
                if any(dist((x, y), q["pos"]) <= half for q in pr)]
        if not near:
            continue
        worst, worst_face = max(near)
        if worst > lim - keep:
            #  فيه قطاع على مساره قريب من الحد - مايتلمسش
            continue
        per_strand = mpa_per_strand(params, half, face=worst_face,
                                    for_removal=True)
        room = (lim - keep - worst) / max(per_strand, 1e-9)
        #  السقف بيتحسب على اللي خرج من الكابل ده **في الرن كله**،
        #  مش في النداء ده - وإلا لوحتين معناها ضعف التخفيف.
        done = int(t.get("_thinned") or 0)
        k = int(min(room, max(2 - done, 0), max(n_now // 4, 1),
                    n_now - n_min))
        if k <= 0:
            continue
        if budget is not None and out_s + k > budget:
            k = max(int(budget - out_s), 0)
            if k <= 0:
                break
        t["strands"] = n_now - k
        t["_thinned"] = int(t.get("_thinned") or 0) + k
        out_n += 1
        out_s += k
        c = (sum(q["pos"][0] for q in pr) / len(pr),
             sum(q["pos"][1] for q in pr) / len(pr))
        detail.append((k, n_now, worst, c))
    if job:
        if out_s:
            detail.sort(key=lambda z: -z[0])
            job.log("Taking force out of where it buys nothing", "head")
            job.ok(f"{out_s} strand(s) came out of {out_n} tendon(s). Every "
                   f"one of them passes no failing section at all, and the "
                   f"most tensile reading within {half:.1f} m of it stays "
                   f"at least {keep:.2f} MPa under the {lim:.2f} limit "
                   f"after the strand is gone.")
            for k, was, worst, c in detail[:6]:
                job.info(f"    -{k} of {was} strands near "
                         f"({c[0]:.1f}, {c[1]:.1f}) - worst reading on its "
                         f"path {worst:+.2f} MPa")
            job.warn("    this is worked out from axial precompression "
                     "alone. A strand also carries balanced load through "
                     "its drape, and taking it out removes that too - so "
                     "this errs optimistic, which is what the margin is "
                     "for. Deflection and cracking are not in it at all. "
                     "The next export is the judge.")
        elif budget:
            job.info("    Nothing could be thinned: every tendon with spare "
                     "strands either passes a failing section or sits too "
                     "close to the limit for one to come out.")
    return out_n, out_s


def _dist_to_path(pt, profile):
    """أقرب مسافة من نقطة لمسار الكابل (على القطع، مش العقد بس)."""
    pts = [q["pos"] for q in profile]
    if not pts:
        return 1e9
    if len(pts) == 1:
        return dist(pt, pts[0])
    best = 1e9
    for a, b in zip(pts, pts[1:]):
        dx, dy = b[0] - a[0], b[1] - a[1]
        L2 = dx * dx + dy * dy
        if L2 < 1e-12:
            d = dist(pt, a)
        else:
            u = ((pt[0] - a[0]) * dx + (pt[1] - a[1]) * dy) / L2
            u = max(0.0, min(1.0, u))
            d = math.hypot(pt[0] - (a[0] + u * dx), pt[1] - (a[1] + u * dy))
        if d < best:
            best = d
    return best


# ==============================================================================
#  سعر الاسترند الحقيقي - متقاس من دفتر التصميم، مش مفترض
# ==============================================================================
#  `mpa_per_strand` بيقول إن الاسترند بيضيف P1/(2·reach·h) ميجا ضغط.
#  ده صح كأكسيال، بس اللي رام بيقيسه في القطاع هو الأكسيال **زائد** عزم
#  الموازنة، والاتنين بيتجمعوا على وش ويتطرحوا على التاني.
#
#  القياس على أول دفتر وصل (دورين، 11 دورة، 7,003 قراية). اتاخد من
#  الدورات اللي مساراتها ومناسيبها ما اتغيّرتش - يعني اللي اتغيّر فيها
#  عدد الاسترندات وبس، فالفرق في القراية سببه الاسترندات لوحدها:
#
#      الوش العلوي   0.90 من المفترض   [0.85 .. 0.95]   n = 597
#      الوش السفلي   0.44 من المفترض   [0.40 .. 0.49]   n = 570
#
#  يعني على القطاع الساقط (الوش السفلي) الاسترند بيدّي أقل من نص اللي
#  البرنامج بيفترضه. ونتيجة ده مباشرة: `section_shortfall` بتطلب نص
#  العدد المطلوب، فالقطاع بيفضل فوق الحد والحلقة بتلف من غير ما تقفله -
#  وده بالظبط اللي حصل في رن المهندس: 5 → 4 → 3 → 3 → 2 → 2 → 2 ووقفت
#  وسيباها 2 فوق الحد. وفي التخفيف بيحصل العكس: بيشيل أقل من اللي
#  الهامش يسمح بيه، فحديد بيفضل مكانه.
#
#  **بس رقم من مبنى واحد مايتحطش كثابت.** الدوال دي بتقيس النسبة من
#  دفتر المهندس نفسه كل رن، وبتطبّقها لما تبقى مبنية على عدد قراءات
#  كفاية. من غير دفتر، النسبة 1.00 - يعني سلوك النهاردة بالحرف.


def _log_path_key(t):
    """المسار والمناسيب - بيتقارن بيهم إذا كان الكابل اتحرك ولا لأ."""
    return (t.get("d"),
            tuple((round(q[0], 3), round(q[1], 3), round(q[2], 1))
                  for q in (t.get("p") or [])))


def _log_strands_near(tendons, x, y, direction, reach):
    """مجموع استرندات الكابلات في اتجاه معيّن اللي بتعدّي في متناول النقطة."""
    tot = 0.0
    for t in tendons:
        if t.get("d") != direction:
            continue
        p = t.get("p") or []
        if len(p) < 2:
            continue
        xs = [q[0] for q in p]
        ys = [q[1] for q in p]
        if (x < min(xs) - reach or x > max(xs) + reach
                or y < min(ys) - reach or y > max(ys) + reach):
            continue
        near = False
        for i in range(len(p) - 1):
            if point_to_segment_dist(x, y, p[i][0], p[i][1],
                                     p[i + 1][0], p[i + 1][1]) <= reach:
                near = True
                break
        if near:
            tot += float(t.get("n") or 0.0)
    return tot


def current_run_rows(rows, run_id=None):
    """صفوف الرن الشغّال دلوقتي بس - العامل بتاع الدور ده، مش متوسط أدوار."""
    rid = run_id or _DESIGN_RUN_ID
    return [r for r in rows if r.get("proc") == rid]


def paired_strand_response(rows, reach=1.5, kept_share=0.8):
    """
    {الوش: (ميجا لكل استرند, عدد الأزواج)} من صفوف الدفتر.

    الزوج بيتاخد من دورتين **متتاليتين في نفس الرن**، وبشرط إن أغلب
    الكابلات مساراتها ما اتغيّرتش - القياس عايز تغيير في الاسترندات
    وبس. الدورة اللي البروفايل اتحرك فيها بتتشال، لأن الغطسة بتغيّر
    القراية أكتر من الاسترند نفسه وبتبلّع القياس (أول حساب عملته كده
    طلّع نسبة 0.30، والرقم كان تلوّث مش نتيجة).

    الميل بيتحسب من غير قاطع: القراية ما بتتغيّرش لما الاسترندات ما
    تتغيّرش - ودي متثبتة في الدفتر نفسه، دورة كاملة 572 نقطة الفرق
    فيها صفر بالظبط.
    """
    out = {}
    pairs = {}
    for a, b in zip(rows, rows[1:]):
        if a.get("proc") and b.get("proc") and a["proc"] != b["proc"]:
            continue
        ta, tb = a.get("tendons") or [], b.get("tendons") or []
        if not ta or not tb:
            continue
        kept = len({_log_path_key(t) for t in ta}
                   & {_log_path_key(t) for t in tb})
        if kept < kept_share * len(ta):
            continue
        ka = {(round(q[0], 2), round(q[1], 2), q[4], q[5]): q
              for q in (a.get("reads") or [])}
        kb = {(round(q[0], 2), round(q[1], 2), q[4], q[5]): q
              for q in (b.get("reads") or [])}
        for k in set(ka) & set(kb):
            qa, qb = ka[k], kb[k]
            d = "X" if str(qa[5]).lower().startswith("x") else "Y"
            na = _log_strands_near(ta, qa[0], qa[1], d, reach)
            nb = _log_strands_near(tb, qb[0], qb[1], d, reach)
            if abs(nb - na) < 1e-9:
                continue
            pairs.setdefault(qa[4], []).append((nb - na, qb[2] - qa[2]))
    for face, pr in pairs.items():
        den = sum(dn * dn for dn, _ in pr)
        if den < 1e-9:
            continue
        out[face] = (sum(dn * dv for dn, dv in pr) / den, len(pr))
    return out


#  حدود العقل. برّه النطاق ده معناه إن القياس اتلخبط - دورة اتغيّر
#  فيها الحمل أو السمك أو الشرائح - مش إن الفيزيا اتقلبت.
#
#  **18.31: الحد الأدنى نزل من 0.25 لـ 0.15.** لما دفتر المهندس كبر
#  لـ 25 دورة النسبة السفلية طلعت 0.22 على 826 قراية - يعني الحد
#  القديم كان هيرفض قياس سليم في الحالة اللي الغلطة فيها أكبر. و0.22
#  مش رقم غريب فيزيائياً: `mpa_per_strand` بيفرض إن ضغط الاسترند
#  بيقف جوّه عرض 2·reach (3 م)، والضغط في البلاطة بينتشر أوسع من كده
#  بكتير - عرض فعّال 10 م لوحده بيدّي 0.3. النسبة دي تصحيح لعرض
#  الانتشار، وطبيعي تختلف من دور لدور لأن الانتشار بيعتمد على
#  التخطيط نفسه.
RESPONSE_MIN, RESPONSE_MAX = 0.15, 1.50

#  الأرضية وقت **الشيل**. القياس بيتصدّق كامل لما بيطلب حديد زيادة،
#  وبحذر لما بيطلب حديد أقل - مش تناقض، ده عدم تماثل مقصود: القياس
#  من دورتين على دور واحد، والغلط ناحية الزيادة بيكلّف كيلوهات
#  والغلط ناحية الشيل بيكلّف أمان.
RESPONSE_REMOVAL_FLOOR = 0.75

_RESPONSE_CACHE = {}


def strand_response_factors(params, job=None):
    """
    {"top": عامل, "bottom": عامل} - 1.00 معناها الافتراض زي ما هو.

    اليدوي بيغلب المقاس، والمقاس بيغلب الافتراضي - وكل واحد بيتقال في
    اللوج بمصدره وبعدد القراءات اللي وراه، عشان الرقم اللي بيغيّر
    التصميم ما يبقاش مجهول المصدر.
    """
    out = {"top": 1.0, "bottom": 1.0}
    manual = {"top": float(getattr(params, "strand_response_top", 0.0) or 0.0),
              "bottom": float(getattr(params, "strand_response_bottom", 0.0)
                              or 0.0)}
    for f, v in manual.items():
        if v > 0:
            out[f] = max(RESPONSE_MIN, min(v, RESPONSE_MAX))
    if not bool(getattr(params, "calibrate_strand_response", True)):
        return out
    if all(manual[f] > 0 for f in out):
        return out
    folder = (str(getattr(params, "design_log_dir", "") or "").strip()
              or DESIGN_LOG_DEFAULT)
    need = int(getattr(params, "strand_response_min_pairs", 200) or 200)
    reach = float(getattr(params, "shave_reach", 1.5) or 1.5)
    ck = (folder, need, round(reach, 3))
    if ck in _RESPONSE_CACHE:
        meas, where = _RESPONSE_CACHE[ck]
    else:
        meas, where = {}, ""
        try:
            #  **18.31: الدور ده الأول، والدفتر كله احتياطي.** لما دفتر
            #  المهندس بقى 3 رنّات النسبة السفلية طلعت 0.27 في رن و0.13
            #  في التاني - يعني متوسط الاتنين مايوصفش ولا واحد فيهم.
            #  الانتشار بيعتمد على تخطيط الدور نفسه، والحلقة بتعمل 5-8
            #  دورات على نفس الدور، فالداتا بتاعته موجودة من الدورة
            #  التانية.
            all_rows = list(reversed(read_design_log(folder)))
            mine = current_run_rows(all_rows)
            meas = paired_strand_response(mine, reach)
            where = "this run"
            if not any(n >= need for _k, n in meas.values()):
                pooled = paired_strand_response(all_rows, reach)
                #  الدفتر كله بياخدها لو هو اللي عنده الكفاية - أو لو
                #  الرن ده لسه مافيهوش ولا زوج، عشان اللي في اللوج
                #  يبقى عدد حقيقي مش صفر.
                if any(n >= need for _k, n in pooled.values()) or not meas:
                    meas, where = pooled, "every run in the log"
        except Exception as e:
            meas = {}
            if job:
                job.info(f"    the strand response could not be measured "
                         f"({e}); the assumed value is used.")
        _RESPONSE_CACHE[ck] = (meas, where)
    assumed = mpa_per_strand(params, reach, face=None, raw=True)
    for f in ("top", "bottom"):
        if manual[f] > 0:
            if job:
                job.info(f"    {f} face: one strand is taken as "
                         f"{manual[f]:.2f} of {assumed:.3f} MPa - your own "
                         f"figure, from the settings.")
            continue
        k, n = meas.get(f, (None, 0))
        if k is None or n < need or assumed <= 0:
            if job and meas:
                job.info(f"    {f} face: {n} paired reading(s) in the design "
                         f"log, under the {need} needed - the assumed "
                         f"{assumed:.3f} MPa per strand stands.")
            continue
        ratio = abs(k) / assumed
        if not (RESPONSE_MIN <= ratio <= RESPONSE_MAX):
            if job:
                job.warn(f"    {f} face: the log measures {ratio:.2f} of the "
                         f"assumed response, outside the {RESPONSE_MIN:.2f}-"
                         f"{RESPONSE_MAX:.2f} band this trusts. Something "
                         f"other than the strands moved between those "
                         f"rounds; the assumed value is used.")
            continue
        out[f] = ratio
        if job:
            job.ok(f"    {f} face: one strand measures "
                   f"{abs(k):.3f} MPa against the {assumed:.3f} assumed "
                   f"({ratio:.2f}x), over {n} paired readings from "
                   f"{where or 'your own runs'}. The sizing uses the measured "
                   f"figure where it asks for more steel, and no less than "
                   f"{RESPONSE_REMOVAL_FLOOR:.2f} where it asks for less.")
    return out


def mpa_per_strand(params, reach=None, face=None, raw=False,
                   for_removal=False):
    """
    الضغط المحوري اللي استرند واحد بيضيفه، بالميجا باسكال.

    القوة موزّعة على عرض 2·reach وسُمك البلاطة. الوحدات شكلها غلط
    وهي مظبوطة: kN على (م × مم) بتدّي MPa لأن تحويل المليمتر لمتر
    وتحويل kN/m² لـ MPa نفس الألف. 100 kN على 2×1.5 م × 250 مم =
    100 / 750 = 0.133 MPa.

    كانت متحسوبة جوّه `shave_candidates` وبس. أي حتة تانية عايزة تترجم
    "هامش بالميجا" لـ "استرندات" ماكانش قدّامها غير تكرّرها.
    """
    half = float(reach if reach is not None
                 else (getattr(params, "shave_reach", 1.5) or 1.5))
    h = float(getattr(params, "slab_thickness", 250.0) or 250.0)
    p1 = float(getattr(params, "force_per_strand", 100.0) or 100.0)
    per = p1 / max(2.0 * half * h, 1e-6)
    #  **18.30: والقطاع بيقيس الأكسيال زائد عزم الموازنة، مش الأكسيال
    #  لوحده.** الرقم فوق أكسيال صافي، وقياسه على دفتر المهندس طلّع
    #  0.90 منه على الوش العلوي و**0.44** على السفلي. شوف
    #  `strand_response_factors` - العامل بييجي من دفتره هو، و1.00
    #  لما مافيش دفتر.
    if face and not raw:
        f = float(strand_response_factors(params).get(face, 1.0) or 1.0)
        #  **18.31: القياس بيتصدّق كامل لما بيطلب حديد، وبحذر لما
        #  بيطلب شيل.** نفس الرقم في الاتجاهين مش تماثل - هو مخاطرة
        #  غير متماثلة: القياس من دور واحد، وتحت التقدير في الزيادة
        #  بيكلّف دورة، وتحت التقدير في الشيل بيكلّف أمان.
        if for_removal:
            f = max(f, float(getattr(params, "strand_response_removal_floor",
                                     RESPONSE_REMOVAL_FLOOR)
                             or RESPONSE_REMOVAL_FLOOR))
        per *= f
    return per


def section_utilisation(plots):
    """
    [(x, y, v, limit, u)] لكل قراية في كل لوحة ليها حد، و u = v / limit.

    **ده الرقم اللي التصميم المفروض يتحكم بيه، مش P/A.** الـ P/A بيقول
    كام ميجا ضغط في القطاع؛ والـ u بيقول القطاع ده قرب من حدّه قد إيه -
    وهو اللي الكود بيرسّب عليه. قطاع عند u = 0.4 فيه حديد اتحط ومالوش
    لازمة، وقطاع عند 1.05 لازم يتعالج، والاتنين ممكن يكون عندهم نفس
    الـ P/A بالظبط.
    """
    out = []
    for pl in (plots if isinstance(plots, (list, tuple)) else [plots]):
        if pl is None:
            continue
        lim = getattr(pl, "limit", None)
        if lim is None or abs(lim) < 1e-9:
            continue
        face = getattr(pl, "face", None)
        for x, y, v in pl.demand:
            #  الوش سادس عنصر عن قصد: كل اللي بيقرا بالفهرس (0..4) ما
            #  حسّش، واللي محتاج الوش بياخده.
            out.append((x, y, v, lim, v / lim, face))
    return out


def utilisation_stats(plots):
    """
    ملخص الاستغلال: (عدد القراءات, الأدنى, الوسيط, الأقصى, اللي فوق 1).

    الوسيط هو المؤشر: سقف وسيطه 0.55 فيه تقريبًا ضعف الحديد اللي
    محتاجه، مهما كان عدد القطاعات الراسبة صفر.
    """
    us = sorted(r[4] for r in section_utilisation(plots))
    if not us:
        return 0, None, None, None, 0
    return (len(us), us[0], us[len(us) // 2], us[-1],
            sum(1 for u in us if u > 1.0))


def tendon_headroom(tendons, plots, params, reach=None, margin=None):
    """
    كل كابل وأسوأ قراية على مساره، مترجمة لاسترندات.

    بترجّع {id(الكابل): {"u", "room", "spare", "short", "near"}}:
      · `u`     أعلى استغلال على مسار الكابل
      · `room`  أضيق هامش (الحد − القراية) بالميجا
      · `spare` كام استرند ينفع يخرج من غير ما الهامش يقل عن `margin`
      · `short` كام استرند لازم يدخل عشان أسوأ قطاع ينزل تحت الحد.
        الهامش `margin` مش داخل فيها عن قصد: الهامش احتياطي بيتطلب وقت
        الشيل، مش شرط لازم كل قطاع في السقف يحققه - طلبه في الزيادة
        بيحط حديد التصميم مش محتاجه.
      · `near`  عدد القراءات في متناوله

    الترجمة من ميجا لاسترندات هي نفس اللي دور التخفيف بيستعملها، فالباص
    ده والدور بيتكلموا نفس اللغة.
    """
    half = float(reach if reach is not None
                 else (getattr(params, "shave_reach", 1.5) or 1.5))
    keep = float(margin if margin is not None
                 else (getattr(params, "shave_margin", 0.30) or 0.0))
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 0)
    rows = section_utilisation(plots)
    out = {}
    for t in tendons:
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        near = [r for r in rows if _dist_to_path((r[0], r[1]), pr) <= half]
        if not near:
            continue
        worst = max(near, key=lambda r: r[4])
        #  أضيق هامش، وسعر الاسترند بتاع **الوش اللي الهامش ده عليه**.
        #  رقم واحد للسقف كله كان بيغلط على القطاع الساقط بأكتر من
        #  الضعف.
        tight = min(near, key=lambda r: r[3] - r[2])
        room = tight[3] - tight[2]
        #  `spare` رقم شيل و`short` رقم زيادة - وكل واحد بياخد سعره.
        per_out = mpa_per_strand(params, half, face=tight[5], for_removal=True)
        per = mpa_per_strand(params, half, face=tight[5])
        n = int(t.get("strands") or 0)
        spare = int(max((room - keep) / per_out, 0.0)) if per_out > 0 else 0
        out[id(t)] = {
            "u": worst[4],
            "room": room,
            "at": (worst[0], worst[1]),
            "near": len(near),
            "spare": max(0, min(spare, max(n - n_min, 0))),
            "short": (int(math.ceil(-room / per))
                      if per > 0 and room < 0 else 0),
        }
    return out


def section_shortfall(plots, params, reach=None):
    """
    الاسترندات الناقصة عند **كل مكان راسب**، مرة واحدة لكل قراية.

    **18.27: وده كان بيتجمّع من ناحية الكابلات.** `tendon_headroom` بتدّي
    لكل كابل عجز أسوأ قراية على مساره، وجمعهم بيحمّل نفس القطاع الراسب
    على كل كابل عدّى جنبه: على دور المهندس ٨ قراءات راسبة طلعوا **٢٣٧
    استرند نقص** - يعني نفس السبعة استرندات متعدودين ٣٥ مرة. الرقم كان
    مالوش أي معنى.

    بترجّع (عدد الأماكن الراسبة, استرندات الأسوأ فيهم, مجموعهم).
    """
    need = []
    for x, y, v, lim, u, face in section_utilisation(plots):
        per = mpa_per_strand(params, reach, face=face)
        if v > lim and per > 0:
            need.append(int(math.ceil((v - lim) / per)))
    if not need:
        return 0, 0, 0
    return len(need), max(need), sum(need)


def utilisation_report(tendons, plots, params, job=None, reach=None,
                       margin=None):
    """
    **السطر اللي بيقول فين الحديد الضايع.**

    عدد القطاعات الراسبة بيقول إن التصميم آمن ولا لأ. مابيقولش إنه
    اقتصادي. سقف كل قطاعاته تحت الحد وأقل استغلال فيه 0.35 فيه حديد
    متحطّ في مكان مش بيشتغل، والرقم ده لوحده هو اللي بيفرق بين تصميم
    عدّى وتصميم اتظبط.

    بترجّع (إحصاء الاستغلال، الاسترندات الفايضة، الاسترندات الناقصة).
    """
    n, lo, med, hi, over = utilisation_stats(plots)
    if not n:
        if job:
            job.info("Utilisation: the section check has no limit to measure "
                     "against, so nothing can be said about how hard the "
                     "sections are working.")
        return (0, None, None, None, 0), 0, 0
    #  18.30: سعر الاسترند بيتقال قبل أي رقم متحسب عليه، عشان اللي
    #  بيقرا اللوج يعرف الترجمة اللي الأرقام اللي تحت اتعملت بيها.
    if job:
        strand_response_factors(params, job)
        report_strand_influence(params, job)
    head = tendon_headroom(tendons, plots, params, reach, margin)
    #  عدد الكابلات اللي فيها فايض، مش مجموع الفايض: نفس القطاع المرتاح
    #  بيسمح لكل كابل عدّى جنبه بنفس التخفيف، وجمعهم بيوعد بحاجة لو
    #  اتعملت على الكل مرة واحدة القطاع كان هيرسب.
    loose = sum(1 for h in head.values() if h["spare"] > 0)
    places, worst_need, short = section_shortfall(plots, params, reach)
    idle = sum(1 for h in head.values() if h["u"] < 0.60)
    if job:
        job.info(
            f"Utilisation across {n:,} readings (demand over the limit; "
            f"negative means the section is in compression): lowest "
            f"{lo:.2f}, median {med:.2f}, highest {hi:.2f}"
            + (f", {over} over 1.00." if over else ", none over 1.00.")
            + f" {len(head)} tendons sit beside a reading; {idle} of them "
              f"never pass anything working harder than 0.60.")
        if places:
            job.info(
                f"    {places} place(s) over the limit: the worst needs about "
                f"{worst_need} strand(s) across it, {short} counting every "
                f"place once. One strand can serve more than one place, so "
                f"that total is an upper bound.")
        if loose:
            job.info(
                f"    {loose} tendon(s) have room to give up at least one "
                f"size. They cannot all give it up at once - the same easy "
                f"section is what allows each of them - so the shave takes "
                f"them a few at a time and re-analyses.")
        if not places and not loose:
            job.ok("    every tendon is within one strand of what its "
                   "sections ask for.")
    return (n, lo, med, hi, over), loose, short


def shave_step_down(n, params):
    """المقاس اللي تحت n على سلّم المقاسات المتاحة، أو None لو n هو الأقل."""
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    allowed = sorted({int(a) for a in (getattr(params, "allowed_strands", []) or [])
                      if int(a) >= n_min})
    if allowed:
        lower = [a for a in allowed if a < n]
        return lower[-1] if lower else None
    return (n - 1) if (n - 1) >= n_min else None


def shave_deletable(t, live, params):
    """
    الكابل ينفع يتشال كله (17.95)؟ لازم يكون له جار من الجهتين على خطوط
    موازية بيغطّوا نص طوله على الأقل، والمسافة بين الجارين بعد شيله
    ماتزيدش عن أقصى تباعد (8h أو 1.5 م). كابل الحافة مابيتشالش.
    """
    d = t.get("dir")
    c = t.get("coord")
    if d not in ("X", "Y") or c is None:
        return False
    try:
        max_sp = float(getattr(params, "max_tendon_spacing", 1.5) or 1.5)
    except Exception:
        max_sp = 1.5
    ax = 0 if d == "X" else 1
    pr = t.get("profile") or []
    if len(pr) < 2:
        return False
    lo = min(q["pos"][ax] for q in pr)
    hi = max(q["pos"][ax] for q in pr)
    span = max(hi - lo, 1e-6)
    left = right = None
    for o in live:
        if o is t or o.get("_deleted") or o.get("dir") != d or o.get("coord") is None:
            continue
        opr = o.get("profile") or []
        if len(opr) < 2:
            continue
        olo = min(q["pos"][ax] for q in opr)
        ohi = max(q["pos"][ax] for q in opr)
        if min(hi, ohi) - max(lo, olo) < 0.5 * span:
            continue
        dc = float(o["coord"]) - float(c)
        if dc < -0.05:
            left = o["coord"] if left is None else max(left, o["coord"])
        elif dc > 0.05:
            right = o["coord"] if right is None else min(right, o["coord"])
    if left is None or right is None:
        return False
    return (float(right) - float(left)) <= max_sp + 1e-6


def shave_apply(take, tendons, params):
    """
    تطبيق قطع الدور بالترتيب. الشيل بيتعاد فحصه على الكابلات اللي لسه
    عايشة: كابلين جيران الاتنين كانوا "ينفع يتشالوا" وقت الترشيح، ولو
    اتشالوا مع بعض الفجوة بتبقى ضعف المسموح (GROUND P.03: فجوة 4.5 م).
    بترجّع [(الكابل, المقاس القديم)].
    """
    changed = []
    for t, new, room, left in take:
        if int(new) <= 0:
            live = [q for q in tendons if not q.get("_deleted")]
            if not shave_deletable(t, live, params):
                continue
            changed.append((t, int(t["strands"])))
            t["_deleted"] = True
        else:
            changed.append((t, int(t["strands"])))
            t["strands"] = int(new)
    return changed


def efm_must_be_put_back(arrived_over, now_over):
    """
    الرن كله يرجع؟ - دالة صافية، زي أختها في التقشير.

    **18.77: والسبب إنها مكانتش موجودة أصلاً.** حلقة الـ EFM في
    الشاشة كانت بتفتح الموديل وتدخل الحلقة على طول - **من غير ما
    تحلّل الموديل زي ما وصل ولا مرة واحدة**. يعني مافيش خط أساس: كل
    الأرقام في اللوج متقاسة على الدورة الأولى، وهي أصلاً بعد ما
    القواعد لمست البروفايلات. فلما المهندس يقول «الموديل القديم
    مسيّف والجديد لأ»، البرنامج مايقدرش يكذّبه ولا يأكّده - هو عمره
    ماشاف القديم.

    `arrived_over` = القطاعات فوق الحد في الملف زي ما وصل.
    `now_over` = اللي في الملف اللي الرن عمله.
    """
    return int(now_over) > int(arrived_over)


def shave_must_be_put_back(base_total, reach, unreach):
    """
    التقشير كله يرجع؟ - دالة صافية، عشان القرار ده يتجرّب.

    قاعدة المهندس: **اللي دخل سايف يفضل سايف.** توفير الحديد مالوش أي
    قيمة قدام قطاع راسب اتعمل هنا. الدالة صغيرة عن قصد: الحلقة اللي
    جواها تمانمية سطر ومحتاجة جلسة رام عشان توصلها، والقرار اللي
    مايتجربش هو اللي بيشحن غلط - زي `efm_stall_step` بالظبط.
    """
    return int(reach) + int(unreach) > int(base_total)


def strip_reserve(plots, params=None):
    """
    **كل شريحة تصميم وكام احتياطي عندها** (18.72).

    رام بيرجّع مع كل قراية رقم البحر اللي هي عليه، والبحور دي هي
    الشرايح. الاحتياطي = أسوأ قراية على الشريحة مقسومة على حد اللوحة:
    شريحة استغلالها 0.55 عندها ضعف الحديد اللي محتاجاه، وشريحة 0.98
    مالهاش ولا مليمتر.

    بترجّع {(الاتجاه, الوش, البحر): {"u", "n", "x", "y", "limit"}}،
    وقاموس فاضي لو اللوحة مش فيها أرقام بحور - ساعتها القاعدة اللي
    فوقها بتقع على سلوكها القديم بدل ما تمنع كل حاجة.
    """
    out = {}
    plots = [q for q in (plots if isinstance(plots, (list, tuple)) else [plots])
             if q is not None and getattr(q, "limit", None) is not None]
    for pl in plots:
        lim = float(pl.limit)
        if lim <= 0:
            continue
        for sec in (getattr(pl, "sections", None) or []):
            if not sec.get("shown") or sec.get("v") is None:
                continue
            span = sec.get("span")
            if span is None:
                continue
            key = (getattr(pl, "direction", None), getattr(pl, "face", None),
                   span)
            u = float(sec["v"]) / lim
            row = out.get(key)
            if row is None or u > row["u"]:
                out[key] = {"u": u, "n": (row["n"] + 1 if row else 1),
                            "x": float(sec["x"]), "y": float(sec["y"]),
                            "limit": lim}
            else:
                row["n"] += 1
    return out


def strips_with_room(plots, params, target=None):
    """
    الشرايح اللي فيها فايض - مرتّبة بالأوسع احتياطي الأول.

    **قاعدة المهندس**: مانحاولش نشيل حديد غير من الشرايح السايفة
    **بزيادة** عن الحد. الشريحة اللي استغلالها فوق الهدف مش مكان
    للتقشير مهما كان الكابل اللي عليها مريّح: القراية الواحدة اللي
    على الحد بتاخد الدور كله رجوع، وده اللي كان بيخلّي التقشير يقضي
    خمس دقايق ويرجع بصفر استرند.

    بترجّع (مجموعة المفاتيح السايفة، القايمة مرتّبة).
    """
    tab = strip_reserve(plots, params)
    if not tab:
        return set(), []
    t = float(target if target is not None
              else (getattr(params, "shave_target_u", 0.0) or 0.0))
    if t <= 0:
        t = 1.0
    rows = sorted(tab.items(), key=lambda kv: kv[1]["u"])
    return {k for k, v in rows if v["u"] <= t}, rows


def strip_reserve_report(plots, params, job=None, target=None):
    """اللي بيتطبع قبل التقشير: الشرايح فيها فايض قد إيه، وفين."""
    ok, rows = strips_with_room(plots, params, target)
    if not rows or job is None:
        return len(ok)
    t = float(target if target is not None
              else (getattr(params, "shave_target_u", 0.0) or 0.0)) or 1.0
    job.log("Which design strips have steel to spare", "head")
    job.ok(f"{len(ok)} of {len(rows)} strip(s) sit at or under {t:.2f} of "
           f"their limit and are where the shave is allowed to take strands "
           f"from. The rest are carrying what they were given: a strip at "
           f"0.98 has not a millimetre to give, and trying it costs a full "
           f"RAM analysis to find that out.")
    for k, v in rows[:6]:
        job.info(f"    {k[0]} {k[1]} span {k[2]}: {v['u']:.2f} of the limit "
                 f"at ({v['x']:.1f}, {v['y']:.1f}) - the most room")
    tight = [r for r in rows if r[1]["u"] > t]
    for k, v in tight[-3:]:
        job.info(f"    {k[0]} {k[1]} span {k[2]}: {v['u']:.2f} - left alone")
    return len(ok)


def shave_candidates(tendons, plots, params, frozen=None, half=None, margin=None):
    """
    **الكابلات اللي ممكن تنزل مقاس** (17.93): مابتعدّيش على أي قطاع راسب
    في أي لوحة، وأضيق هامش على مسارها (حد اللوحة - القراية) بيغطّي
    التخفيف المقدّر (نقص الضغط المحوري للاستراندات اللي هتخرج على عرض
    2 x shave_reach) وفوقه shave_margin. بترجّع
    [(الكابل, المقاس الجديد, أضيق هامش, اللي فاضل بعد التخفيف)] الأوسع
    هامشاً الأول. التقدير محوري بس - الحمل الموازن مش فيه - فالتحليل
    اللي بعده هو الحكم، والدور بيرجّع اللي رسّب.
    """
    plots = [q for q in (plots if isinstance(plots, (list, tuple)) else [plots])
             if q is not None and getattr(q, "limit", None) is not None]
    if not plots or not tendons:
        return []
    half = float(half if half is not None
                 else (getattr(params, "shave_reach", 1.5) or 1.5))
    keep = float(margin if margin is not None
                 else (getattr(params, "shave_margin", 0.30) or 0.0))
    #  **18.27: هدف استغلال بدل هامش ثابت.** `shave_margin` رقم واحد
    #  بالميجا لكل السقف (0.30)، فالقطاع اللي مقاومته 0.98 بيتساب له
    #  31% احتياطي والقطاع اللي مقاومته 3.68 بيتساب له 8%. اللي بيحكم
    #  هو النسبة مش الفرق. لما `shave_target_u` يبقى أكبر من صفر،
    #  الشرط بيبقى "أسوأ قراية تفضل تحت الهدف بعد ما الاسترندات تخرج"،
    #  والفرق ده هو اللي بيسيب الحديد يخرج من المناطق المرتاحة فعلاً.
    #  صفر (الافتراضي) = القاعدة القديمة بالحرف.
    target_u = float(getattr(params, "shave_target_u", 0.0) or 0.0)
    rows = [(x, y, v, pl.limit, getattr(pl, "face", None))
            for pl in plots for x, y, v in pl.demand]
    fails = [(x, y) for pl in plots for x, y, v, l in pl.failing()]
    #  **18.72: الشريحة الأول، وبعدين الكابل.** قاعدة المهندس بالحرف:
    #  «ماتحاولش تمسح كابل إلا من القطاعات اللي سايفة بزيادة عن الحد -
    #  شوف الأول مين الشرايح اللي فيها فايض وابدأ تقلّل منها». الترتيب
    #  القديم كان بيقيس هامش كل كابل لوحده، فكابل مريّح ماشي جوّه شريحة
    #  على الحد كان بيتعرض للتقشير، والقراية اللي على الحد بتاخد الدور
    #  كله رجوع بتحليل كامل. القاعدة دي بتوفّر الدورة دي من أصلها.
    if bool(getattr(params, "shave_strip_reserve", True)):
        _ok_strips, _all_strips = strips_with_room(plots, params)
    else:
        _ok_strips, _all_strips = set(), []
    _by_pt = {}
    if _all_strips:
        for pl in plots:
            for sec in (getattr(pl, "sections", None) or []):
                if not sec.get("shown") or sec.get("v") is None:
                    continue
                if sec.get("span") is None:
                    continue
                _by_pt[(round(float(sec["x"]), 2),
                        round(float(sec["y"]), 2))] = (
                    getattr(pl, "direction", None), getattr(pl, "face", None),
                    sec["span"])
    frozen = frozen or set()
    out = []
    remove_ok = bool(getattr(params, "shave_remove", True))
    live = [t for t in tendons if not t.get("_deleted")]
    for t in live:
        if id(t) in frozen:
            continue
        n = int(t.get("strands") or 0)
        new = shave_step_down(n, params)
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        if new is None:
            #  17.95: أقل مقاس خلاص - يتشال كله لو الجيران بيغطّوا
            if not (remove_ok and n > 0 and shave_deletable(t, live, params)):
                continue
            new = 0
        if any(_dist_to_path(f, pr) <= half for f in fails):
            continue
        near = [(v, l, f) for x, y, v, l, f in rows
                if _dist_to_path((x, y), pr) <= half]
        if not near:
            continue
        room = min(l - v for v, l, _f in near)
        #  **18.30: سعر الاسترند بتاع الوش اللي الهامش ده عليه.** رقم
        #  واحد للسقف كان بيفترض إن الاسترند بيدّي على القطاع الساقط
        #  زي ما بيدّي فوق الركيزة، ودفتر المهندس بيقول إنه بيدّي
        #  0.44 منه. في التخفيف الغلطة دي بتخلّي الشيل **يقلّ**، فهي
        #  مش خطر - بس هي نفس الغلطة اللي في الزيادة خطر.
        worst_face = min(near, key=lambda z: z[1] - z[0])[2]
        per_strand = mpa_per_strand(params, half, face=worst_face,
                                    for_removal=True)
        if target_u > 0:
            #  اللي هيخرج فعلاً من الاسترندات، مش كلهم ولا ولا واحد
            gone = per_strand * (n - int(new or 0))
            left = min(target_u * l - v for v, l, _f in near) - gone
        else:
            #  17.95: الحكم للتحليل. نزول مقاس بيتجرّب بأي هامش فوق keep؛
            #  شيل كابل كامل بياخد الحمل الموازن كله معاه فبيطلب هامش
            #  يغطّي التقدير المحوري لكل استرانداته.
            est = per_strand * n if new == 0 else 0.0
            left = room - keep - est
        if left < 0:
            continue
        #  الشرايح اللي الكابل ده ماشي عليها: لو واحدة منها مش سايفة
        #  بزيادة، الكابل مش مرشح - مهما كان هامشه هو.
        u_worst = 0.0
        if _by_pt:
            keys = set()
            for x, y, v, l, _f in rows:
                if _dist_to_path((x, y), pr) <= half:
                    k = _by_pt.get((round(x, 2), round(y, 2)))
                    if k is not None:
                        keys.add(k)
            if keys and not keys <= _ok_strips:
                continue
            for k in keys:
                for kk, vv in _all_strips:
                    if kk == k:
                        u_worst = max(u_worst, vv["u"])
                        break
        out.append((t, new, room, left, u_worst))
    #  نزول المقاسات قبل الشيل، وأوسع شريحة احتياطاً الأول، وبعدين
    #  أوسع كابل هامشاً - الترتيب بيمشي من "المكان اللي فيه فايض"
    #  لجوّه، مش من الكابل لبرّه.
    out.sort(key=lambda z: (z[1] == 0, z[4], -z[3]))
    return [(t, new, room, left) for t, new, room, left, _u in out]


def hopt_trim_surplus(session, tendons, params, job, out_dir, stem,
                     site=None, mesh_size=None, plots=None):
    """
    **H optimization: التخفيف الآمن فقط**.

    بعد ما الحلقة زادت الاسترندات في القطاعات الراسبة، هذه الدالة
    تتأكد إن السقف أصبح آمن، ثم تزيل الاسترندات الفائضة من الكابلات
    اللي عندها هامش كبير، وبلا تعرّض لأي قسم آمن للانزلاق فوق الحد.
    أي تغيير يسبّب عجز جديد يترجع فوراً، والقطعة تبقى كما هي.
    """
    rounds_max = max(1, int(getattr(params, "hopt_trim_rounds", 2) or 2))
    if rounds_max <= 0 or not tendons:
        return {"rounds": [], "best": None, "removed": 0,
                "stopped": "off"}

    def live():
        return [t for t in tendons if not t.get("_deleted")]

    def draw_and_read(label):
        clear_tendons_in_ram(session, job)
        write_tendons_to_ram(session, live(), job, params,
                             drops=(site or {}).get("drops"), site=site)
        if bool(getattr(params, "place_jacks", True)):
            try:
                write_jacks_to_ram(session, live(), job, params)
            except Exception as e:
                job.warn(f"Jacks were not placed: {e}")
        res = run_model_analysis(session, job, mesh_size)
        if not res.get("ok"):
            raise RuntimeError("RAM did not finish the analysis")
        pl = read_section_plots_from_ram(session, params, job)
        return pl, md_summary(label, live(), pl, params)

    if plots is None:
        plots, s0 = draw_and_read("before H trim")
    else:
        s0 = md_summary("before H trim", live(), plots, params)

    if int(s0["reach"]) > 0:
        if job:
            job.info("H optimization trim is skipped because the floor is "
                     "still over the limit. The add-only pass stays in force "
                     "until the current layout is safe enough to trim.")
        return {"rounds": [], "best": None, "removed": 0,
                "stopped": "floor still over limit"}

    result = {"rounds": [], "best": None, "removed": 0,
              "stopped": "rounds finished"}
    best_path = None
    last = s0
    for rnd in range(1, rounds_max + 1):
        cands = shave_candidates(live(), plots, params, frozen=set())
        if not cands:
            break
        take = cands[: min(len(cands), 2)]
        changed = shave_apply(take, tendons, params)
        if not changed:
            break
        asked = sum(old - (0 if t.get("_deleted") else int(t["strands"]))
                    for t, old in changed)
        if asked <= 0:
            break
        plots2, s1 = draw_and_read(f"H trim round {rnd}")
        if int(s1["reach"]) > 0:
            for t, old in changed:
                t.pop("_deleted", None)
                t["strands"] = old
            if job:
                job.warn(f"H trim round {rnd}: the reduction created a new "
                         f"failure, so it was rolled back and the safe trim "
                         f"stopped.")
            plots = plots2
            last = s1
            break
        plots = plots2
        last = s1
        total_cut = asked
        total_removed = sum(old - (0 if t.get("_deleted") else int(t["strands"]))
                            for t, old in changed)
        result["rounds"].append({"round": rnd, "cut": asked,
                                  "strands": s1["strands"],
                                  "reach": s1["reach"],
                                  "unreach": s1["unreach"]})
        result["removed"] += total_removed
        if job:
            job.ok(f"H trim round {rnd}: kept out {asked} strands without "
                   f"creating a new section failure.")
        path = os.path.join(out_dir, f"{stem}_hopt_trim_r{rnd}.cpt")
        if safe_save(session, path, job):
            best_path = path
        result["best"] = best_path
        if int(s1["reach"]) == 0:
            break
    result.update({"best": best_path, "stopped": result["stopped"],
                   "strands": last["strands"],
                   "strand_m": last["strand_m"],
                   "reach": last["reach"], "unreach": last["unreach"]})
    return result


def run_h_optimization_pass(session, tendons, params, job, plot, site=None,
                           mesh_size=None, out_dir=None, stem=None,
                           skip_xy=None):
    """
    **H Optimization بعد الرسم**.

    المسار ده لا يشتغل كـ "رسم كل الكابلات من الصفر". هو فقط
    "optimization after drawing" على موديل موجود فعلياً، وبأولوية:

      1) lower sections: القطاعات السفلية اللي لسه فوق الحد
      2) upper sections: القطاعات العلوية اللي لسه فوق الحد
      3) band-based optimization: تجميع الأقرب في نفس البحر/القطاع
      4) safe trim: شيل الفائض بس لو الموديل لسه سيف
      5) stop conditions: وقف فوراً لو مفيش عجز، أو لو الإضافة خلّفت
         فشل جديد، أو ما فيش كابل/مسار مناسب

    الهدف: الوصول إلى section safe دون إهدار الكابلات أو تحريك كل
    التخطيط بشكل مضر.
    """
    if plot is None or not tendons:
        return {"added": 0, "trimmed": 0, "safe": False,
                "stopped": "no data"}

    face_name = str(getattr(plot, "face", "bottom") or "bottom")
    raw_rows = plot_deficits(plot, params, tendons=tendons)
    rows = [r for r in raw_rows if float(r.get("over") or 0.0) > 0.0]
    #  18.102: القراءات اللي pass الإضافة عالجها الدورة دي مش بتتسعّر
    #  تاني هنا - كانت بتاخد استرندات مرتين في نفس الدورة من غير تحليل
    #  بينهم. واللوحة ثابتة جوّه الدورة: اللي اتعالج بيتشال من القايمة
    #  بدل ما يتقرا تاني من نفس اللوحة ويطلع "لسه راسب".
    _skip = [(float(a), float(b)) for a, b in (skip_xy or [])]
    if _skip:
        rows = [r for r in rows
                if min((dist((float(r["x"]), float(r["y"])), p)
                        for p in _skip), default=1e9) > 0.75]
    if not rows:
        return {"added": 0, "trimmed": 0, "safe": True,
                "stopped": "already safe"}
    treated_xy = []

    def _untreated(some_rows):
        return [r for r in some_rows
                if min((dist((float(r["x"]), float(r["y"])), p)
                        for p in treated_xy), default=1e9) > 0.75]

    gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    n_max = max(int(getattr(params, "max_strands", 5) or 5), n_min)

    def stage_rows(stage_name, stage_rows):
        if not stage_rows:
            return []
        if stage_name == "band":
            grouped = {}
            for r in stage_rows:
                key = (round(float(r["x"]) / 1.5, 0),
                       round(float(r["y"]) / 1.5, 0))
                grouped.setdefault(key, []).append(r)
            ordered = [v for _, v in sorted(grouped.items(),
                                            key=lambda kv: -sum(float(x["over"]) for x in kv[1]))]
            return [r for band in ordered[:6] for r in band]
        return sorted(stage_rows, key=lambda r: -float(r.get("over") or 0.0))

    lower_rows = [r for r in rows if face_name.lower() == "bottom"]
    upper_rows = [r for r in rows if face_name.lower() == "top"]
    band_rows = stage_rows("band", rows)

    stage_order = []
    if lower_rows:
        stage_order.append(("lower", stage_rows("lower", lower_rows)))
    if upper_rows:
        stage_order.append(("upper", stage_rows("upper", upper_rows)))
    if band_rows:
        stage_order.append(("band", band_rows))

    added = 0
    added_ids = []
    if job:
        job.info(f"H optimization: {len(rows)} failing reading(s) remain on the "
                 f"{face_name} face; the pass is narrowed to still-short sections "
                 f"only, in stages: lower → upper → band-based.")

    def add_to_nearest_tendon(stage_name, stage_rows):
        nonlocal added
        if not stage_rows:
            return 0
        used = 0
        row_limit = min(6, max(3, len(stage_rows)))
        for r in stage_rows[:row_limit]:
            x, y = float(r["x"]), float(r["y"])
            deficit = max(0.25, float(r.get("over") or 0.0))
            if deficit <= 0.25:
                continue
            best_t, best_dist = None, 1e18
            for t in tendons:
                if t.get("_deleted"):
                    continue
                pr = t.get("profile") or []
                if len(pr) < 2:
                    continue
                d = min(dist((x, y), q["pos"]) for q in pr)
                if d < best_dist:
                    best_dist, best_t = d, t
            if best_t is None:
                continue
            if best_dist > max(4.0, gap * 6.0):
                #  18.102: مافيش كابل في المتناول - كان بياخد أول كابل في
                #  القايمة أياً كان مكانه ويزوّده. القراءة دي بتتساب
                #  لمسار الكابل الجديد (add_offset_tendon).
                continue
            n_now = int(best_t.get("strands") or 0)
            if n_now >= n_max:
                continue
            step = 1
            if deficit > 2.0 and n_now + 2 <= n_max:
                step = 2
            step = max(1, min(step, n_max - n_now))
            if step <= 0:
                continue
            best_t["strands"] = n_now + step
            added += step
            used += step
            added_ids.append(id(best_t))
            treated_xy.append((x, y))
            if job:
                job.info(f"    [{stage_name}] H optimization adds {step} strand(s) "
                         f"to the nearest tendon near ({x:.1f}, {y:.1f}) while "
                         f"keeping the existing layout intact.")
        return used

    def add_offset_tendon(stage_name, stage_rows):
        nonlocal added
        if not stage_rows:
            return 0
        donor = next((t for t in tendons if not t.get("_deleted")
                      and (t.get("profile") or []) and len((t.get("profile") or [])) >= 2), None)
        for r in stage_rows[:min(4, max(2, len(stage_rows)))]:
            x, y = float(r["x"]), float(r["y"])
            deficit = max(0.25, float(r.get("over") or 0.0))
            if deficit <= 0.25:
                continue
            offset_step = 1
            if deficit > 2.0:
                offset_step = 2
            run = [{"a": (x - 1.5, y - 0.75),
                    "b": (x + 1.5, y + 0.75),
                    "mid": (x, y),
                    "key": ("hopt", x, y, 0),
                    "name": f"hopt@{x:.1f},{y:.1f}",
                    "set": "hopt", "add": float(r.get("over") or 0.0),
                    "kg": 0.0}]
            pl = plan_added_tendon(run, tendons, params, strip=max(8.0, gap * 2.0), site=site)
            if pl is None and donor is not None:
                prof = donor.get("profile") or []
                if len(prof) >= 2:
                    total = sum(dist(prof[i]["pos"], prof[i + 1]["pos"]) for i in range(len(prof) - 1))
                    pl = {"donor": donor,
                          "lo": 0.0,
                          "hi": max(6.0, min(total, max(6.0, total * 0.8))),
                          "total": total,
                          "runs": [list(run)],
                          "ext": max(2.0, gap * 2.0)}
            if pl is None:
                continue
            t = build_added_tendon(pl, tendons, params, site)
            if t is None and donor is not None:
                prof = donor.get("profile") or []
                if len(prof) >= 2:
                    pts = [dict(q) for q in prof]
                    dx = pts[-1]["pos"][0] - pts[0]["pos"][0]
                    dy = pts[-1]["pos"][1] - pts[0]["pos"][1]
                    n = math.hypot(dx, dy) or 1.0
                    ux, uy = dx / n, dy / n
                    for q in pts:
                        q["pos"] = (q["pos"][0] + 0.75 * ux,
                                    q["pos"][1] + 0.75 * uy)
                        q["manual"] = True
                    t = {k: v for k, v in donor.items() if k not in ("profile", "path", "_deleted", "jacks", "nodes", "live_at_start", "live_at_end")}
                    t["profile"] = pts
                    t["added"] = True
                    t["as_drawn"] = False
                    t["governing"] = {"efm_added": True}
                    t["length"] = max(6.0, sum(dist(pts[i]["pos"], pts[i + 1]["pos"]) for i in range(len(pts) - 1)))
                    t["full_length"] = False
                    t["strands"] = max(n_min, min(n_max, offset_step))
                    t["from_deficit"] = {"spm": float(r.get("strands_per_m") or 0.0),
                                          "width": 1.0, "readings": 1, "run": 1.0}
            if t is None:
                continue
            if not isinstance(t, dict):
                continue
            if not any(id(q) == id(t) for q in tendons):
                tendons.append(t)
            added += offset_step
            treated_xy.append((x, y))
            if job:
                job.info(f"    [{stage_name}] H optimization adds a new offset tendon "
                         f"near ({x:.1f}, {y:.1f}) to cover the still-short band "
                         f"without re-laying the whole floor.")
            return offset_step
        return 0

    for stage_name, stage_rows_list in stage_order:
        #  18.102: المرحلة بتشوف اللي المرحلة اللي قبلها ماوصلتلوش بس.
        stage_rows_list = _untreated(stage_rows_list)
        if not stage_rows_list:
            continue
        if job:
            job.info(f"    stage: {stage_name} ({len(stage_rows_list)} failing reading(s))")
        stage_added = add_to_nearest_tendon(stage_name, stage_rows_list)
        if stage_added <= 0:
            stage_added = add_offset_tendon(stage_name, stage_rows_list)
        if stage_added <= 0:
            if job:
                job.info(f"    [{stage_name}] no safe addition was possible; this stage is complete.")
            continue
        if job:
            job.info(f"    [{stage_name}] stage accepted: {stage_added} strand(s) added.")
        #  Stop condition (18.102): the plot does not change inside the
        #  round, so "remaining" is what no stage has given strands yet -
        #  re-reading the same plot always said "still failing".
        remaining = _untreated(rows)
        if not remaining:
            if job:
                job.ok("    H optimization gave strands to every failing "
                       "reading on this face; the next export says whether "
                       "they closed.")
            break

    trim = 0
    if out_dir and stem and session and job:
        try:
            trim_res = hopt_trim_surplus(session, tendons, params, job,
                                        out_dir, stem, site=site,
                                        mesh_size=mesh_size)
            trim = int(trim_res.get("removed") or 0)
            if trim > 0:
                if job:
                    job.ok(f"    Safe H trim removed {trim} strand(s) from surplus "
                           f"only, without creating a new fail.")
        except Exception as e:
            if job:
                job.warn(f"The safe H trim could not run: {e}")

    if added <= 0:
        return {"added": 0, "trimmed": trim, "safe": False,
                "stopped": "no safe addition"}

    #  "safe" مش معروفة من غير تحليل جديد - اللوحة اللي في الإيد اتقرت
    #  قبل الإضافة. الحلقة اللي بتنادي هي اللي بتعيد التصدير وتحكم.
    if not _untreated(rows):
        return {"added": added, "trimmed": trim, "safe": False,
                "stopped": "every failing reading was given strands; "
                           "re-analyse to confirm"}

    return {"added": added, "trimmed": trim, "safe": False,
            "stopped": "some readings could not be reached"}


# ==============================================================================
#  Optimum solution H  (18.103)
# ==============================================================================
#  المسار ده بيشتغل على موديل فيه كابلات مرسومة فعلاً - سواء اترسمت
#  دلوقتي من الـ DXF أو الموديل جاهز - وبيمشي على تلات مراحل، كل
#  مرحلة بتتحفظ في ملفها:
#
#    1. القطاعات السفلية: الكابل اللي أكتر من نص بحوره راسبة بياخد
#       استرندات؛ وإلا نسخة من الكابل على البحر ده بس (+3 م من الجهتين)
#       في أكبر فجوة بين الكابلات المارّة فيه.
#    2. القطاعات العلوية (بعد ما السفلية تخلص): حافة الدروب والنقطة
#       العالية، ثم القمة على وش الركيزة لو البحر عنده احتياطي، ثم
#       تحريك الغطسة 10/20/30% ناحية القطاع الراسب، ثم الإضافة.
#    3. التحسين: المجموعة اللي معظم شرايحها عندها احتياطي بتتخفف وبحرها
#       اللي على الحد بياخد كابل بنفس اللي اتخفف، الكابلات المتتالية على
#       نفس المحور بتتوصل، والقصيرة اللي بتغطي أكتر من 70% من محورها
#       بتتلغي واسترنداتها بتروح للجيران أو لكابل طويل واحد.
#
#  النسخة اللي بتترجّع عمرها ما تبقى أسوأ من اللي اتحفظت في نهاية
#  المرحلة 2 - التحسين لو كسر قطاع بيتراجع.

OSH_STARTS = {
    "Keep the tendons as they are": "keep",
    "Reduce every tendon to the minimum strands, then build up": "reduce",
}
OSH_SIZINGS = {
    "Ratio: strands x (stress / limit)": "ratio",
    "Measured: what a strand relieves at that section": "measured",
}
OSH_ORDERS = {
    "The direction with the longer spans first": "longer",
    "X first": "x",
    "Y first": "y",
}
#  **18.114: الغطسة في نص البحر وفي قاع البلاطة هي الأولوية.** رن المهندس
#  (18.111) طلّع إن زحزحة الغطسة 10/20/30% ناحية الطرف الراسب - مع الرفع
#  اللي نصف القطر الأدنى بيفرضه - ماساعدتش القطاع العلوي (19-1: 1.67 →
#  1.73) وكسرت قطاعات سفلية كانت سليمة (42-2: 0.97 → 1.25)، وهو نفسه
#  سيّف البحرين بغطسة في النص وفي القاع. فالافتراضي بقى "أبداً"، و"آخر
#  حل" بيجرّبها بس لما الاسترندات والكابل مايتضافوش ويرجّعها لو ماساعدتش.
OSH_LOW_SHIFTS = {
    "Never: the low points stay at mid-span, at the bottom of the slab": "never",
    "Last resort: only when no strand or tendon can be added, undone if it does not help": "last",
    "Before adding: 10/20/30% steps toward the failing end, then a tendon": "first",
}


def osh_live(tendons):
    return [t for t in (tendons or []) if not t.get("_deleted")]


def osh_dir_of_plot(plot):
    d = str(getattr(plot, "direction", "x") or "x").lower()
    return "X" if d.startswith("x") else "Y"


def osh_tendon_dir(t):
    d = str(t.get("dir") or "").upper()
    if d in ("X", "Y"):
        return d
    pr = t.get("profile") or []
    if len(pr) < 2:
        return "X"
    dx = abs(pr[-1]["pos"][0] - pr[0]["pos"][0])
    dy = abs(pr[-1]["pos"][1] - pr[0]["pos"][1])
    return "X" if dx >= dy else "Y"


def osh_stations(prof):
    st = [0.0]
    for a, b in zip(prof, prof[1:]):
        st.append(st[-1] + dist(a["pos"], b["pos"]))
    return st


def osh_along(pt, direction):
    return pt[0] if direction == "X" else pt[1]


def osh_across_pt(pt, direction):
    return pt[1] if direction == "X" else pt[0]


def osh_across(t, direction):
    """الإحداثي العرضي لمنتصف الكابل."""
    pr = t.get("profile") or []
    if not pr:
        return 0.0
    mid = _profile_point_at(pr, osh_stations(pr)[-1] / 2.0)
    return osh_across_pt(mid, direction)


def osh_across_at(t, d, direction):
    """الإحداثي العرضي للكابل عند منتصف البحر ده."""
    pr = t.get("profile") or []
    if not pr:
        return 0.0
    s, _ = _station_of(pr, d["mid"])
    return osh_across_pt(_profile_point_at(pr, s), direction)


def osh_min_gap(params):
    g = float(getattr(params, "min_clear_spacing", 0.0) or 0.0)
    if g <= 0:
        g = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    return max(g, 0.25)


def osh_span_of(xy, spans, direction, tol=3.0):
    """أقرب بحر تصميم (من رام) في الاتجاه ده للنقطة - (المفتاح, البحر) أو None."""
    best, bd = None, 1e18
    for key, d in (spans or {}).items():
        a, b = d["a"], d["b"]
        if not _span_in_direction(a, b, direction.lower()):
            continue
        dd = point_to_segment_dist(xy[0], xy[1], a[0], a[1], b[0], b[1])
        if dd < bd:
            bd, best = dd, (key, d)
    if best is None or bd > tol:
        return None
    return best


def osh_tendons_in_span(live, d, direction, half=3.0):
    """
    الكابلات اللي بتعدّي القطاع العرضي عند منتصف البحر، في اتجاهه.

    الخط العرضي بيتاخد عند المنتصف وعند 15 سم بعده كمان: كابل عقدته
    واقعة على المنتصف بالظبط كان بيفلت من اختبار التقاطع.
    """
    out = list(_tendons_over_span(live, d, strip=half))
    ax, ay = d["a"]
    bx, by = d["b"]
    n = math.hypot(bx - ax, by - ay) or 1.0
    d2 = dict(d)
    d2["mid"] = (d["mid"][0] + 0.15 * (bx - ax) / n,
                 d["mid"][1] + 0.15 * (by - ay) / n)
    for t in _tendons_over_span(live, d2, strip=half):
        if not any(t is x for x in out):
            out.append(t)
    out = [t for t in out if osh_tendon_dir(t) == direction]
    out.sort(key=lambda t: osh_across_at(t, d, direction))
    return out


def osh_spans_of_tendon(t, spans, direction, half=3.0):
    out = []
    for key, d in (spans or {}).items():
        if not _span_in_direction(d["a"], d["b"], direction.lower()):
            continue
        if _tendons_over_span([t], d, strip=half):
            out.append(key)
    return out


def osh_read_state(plots, spans, live, params):
    """
    القراءات كلها مع نسبة الاستغلال لكل واحدة، وبحرها، وملخص لكل بحر:
    أعلى استغلال على كل وش، والقراءات نفسها.
    """
    state = {"readings": [], "spans": {}, "fail": set(), "n_over": 0}
    for pl in plots or []:
        lim = getattr(pl, "limit", None)
        if lim is None or abs(float(lim)) < 1e-9:
            continue
        lim = float(lim)
        face = str(getattr(pl, "face", "bottom") or "bottom").lower()
        face = "top" if face.startswith("t") else "bottom"
        direction = osh_dir_of_plot(pl)
        for x, y, v in (getattr(pl, "demand", None) or []):
            u = float(v) / lim
            hits = []
            if face == "top":
                #  القراءة العلوية فوق ركيزة مشتركة بتخص البحرين اللي
                #  على جنبيها: كل واحد بيشوفها عند طرفه.
                for key, d in (spans or {}).items():
                    if not _span_in_direction(d["a"], d["b"], direction.lower()):
                        continue
                    if (dist((x, y), d["a"]) <= 1.0
                            or dist((x, y), d["b"]) <= 1.0):
                        hits.append((key, d))
            if not hits:
                one = osh_span_of((x, y), spans, direction)
                if one:
                    hits.append(one)
            rec = {"x": float(x), "y": float(y), "v": float(v), "lim": lim,
                   "u": u, "face": face, "dir": direction,
                   "span_key": hits[0][0] if hits else None,
                   "span": hits[0][1] if hits else None}
            state["readings"].append(rec)
            if u > 1.0:
                state["n_over"] += 1
            for key, d in hits:
                s = state["spans"].setdefault(
                    key, {"d": d, "dir": direction, "bottom": 0.0,
                          "top": 0.0, "rows": {"bottom": [], "top": []}})
                s[face] = max(s[face], u)
                s["rows"][face].append(rec)
                if u > 1.0:
                    state["fail"].add((key, face))
    return state


def run_temp_dir(out_dir, cpt):
    """
    **18.107: كل رن في مجلده.** المجلد اللي فيه الموديل كان بيتملي
    بملفات كل دورة من كل رن (_OSH_bottom_r1, _EFM_r3, لوجات، تقارير...)
    ومحدش عارف الملف النهائي أنهو. دلوقتي كل رن بيكتب كل حاجة في
    Temp\<اسم الموديل>_<التاريخ والوقت>\ جنب الموديل، والملف النهائي
    بس هو اللي بيتنسخ جنب الموديل الأصلي (finish_run_output).
    """
    stem = os.path.splitext(os.path.basename(cpt or "run"))[0] or "run"
    when = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    path = os.path.join(out_dir, "Temp", f"{stem}_{when}")
    k = 2
    base = path
    while os.path.exists(path):
        path = f"{base}-{k}"
        k += 1
    os.makedirs(path, exist_ok=True)
    return path


def finish_run_output(last_output, run_dir, final_dir, log=None):
    """
    ينسخ الملف النهائي من مجلد الرن لجنب الموديل الأصلي ويرجّع مساره -
    أو الملف زي ما هو لو مش جوّه مجلد الرن. الاسم زي ما هو، ونسخة
    قديمة بنفس الاسم بتتكتب فوقها: نسختها الكاملة لسه جوّه Temp.
    """
    try:
        if not last_output or not run_dir or not final_dir:
            return last_output
        src = os.path.abspath(str(last_output))
        if not os.path.isfile(src):
            return last_output
        if os.path.commonpath([src, os.path.abspath(run_dir)]) != os.path.abspath(run_dir):
            return last_output
        dst = os.path.join(final_dir, os.path.basename(src))
        shutil.copy2(src, dst)
        if log:
            log(f"Final model beside the one you started from: {dst}", "ok")
            log(f"Everything else from this run is in {run_dir}", "info")
        return dst
    except Exception as e:
        if log:
            log(f"The final model could not be copied beside the original "
                f"({e}); it is in {run_dir}", "warn")
        return last_output


def osh_path(out_dir, stem, label):
    base = os.path.join(out_dir or ".", f"{stem}_OSH_{label}.cpt")
    path, k = base, 2
    while os.path.isfile(path):
        path = base[:-4] + f"-{k}.cpt"
        k += 1
    return path


def osh_cycle(session, tendons, params, site, mesh, job, out_dir, stem, label):
    """
    ارسم الكابلات الحية، حلّل، احفظ، اقرا القطاعات من رام والبحور من
    الملف المحفوظ - وارجع الحالة كلها.
    """
    live = osh_live(tendons)
    job.check()
    clear_tendons_in_ram(session, job)
    write_tendons_to_ram(session, live, job, params,
                         drops=(site or {}).get("drops"), site=site)
    if bool(getattr(params, "place_jacks", True)):
        try:
            write_jacks_to_ram(session, live, job, params)
        except Exception as e:
            job.warn(f"Jacks were not placed: {e}")
    res = run_model_analysis(session, job, mesh)
    if not res.get("ok"):
        raise RuntimeError("RAM did not finish the analysis"
                           + (f": {res.get('error')}" if res.get("error") else ""))
    path = osh_path(out_dir, stem, label)
    if not safe_save(session, path, job):
        raise RuntimeError("the model could not be saved")
    plots = read_section_plots_from_ram(session, MdParams(params, efm_face="both"),
                                        job)
    spans = {}
    try:
        spans = (read_designed_steel(path) or {}).get("spans") or {}
    except Exception as e:
        job.warn(f"The design-strip spans could not be read from "
                 f"{os.path.basename(path)} ({e}); readings are matched to "
                 f"tendons by position only.")
    state = osh_read_state(plots, spans, live, params)
    state["path"] = path
    state["plots"] = plots
    state["ram_spans"] = spans
    state["summary"] = md_summary(label, live, plots, params)
    state["kg"] = floor_strand_kg(live, params)
    sm = state["summary"]
    job.info(f"    {label}: {len(live)} tendons, {sm['strands']} strands, "
             f"{state['kg']:,.0f} kg, {state['n_over']} reading(s) over the "
             f"limit ({sm['reach']} reachable, {sm['unreach']} out of reach).")
    return state


def osh_faces_over(state):
    """{ (dir, face): count } للقراءات فوق الحد."""
    out = {}
    for r in state["readings"]:
        if r["u"] > 1.0:
            k = (r["dir"], r["face"])
            out[k] = out.get(k, 0) + 1
    return out


# ---------------------------------------------------------------------------
#  الميزانية
# ---------------------------------------------------------------------------

def osh_budget_total(params, site, base_kg):
    total = None
    rate = float(getattr(params, "budget_kg_m2", 0.0) or 0.0)
    area = slab_area_m2(site) if site else None
    if rate > 0 and area:
        total = rate * float(area)
    cap = float(getattr(params, "add_cap_pct", 0.0) or 0.0)
    if cap > 0 and base_kg:
        c = float(base_kg) * (1.0 + cap / 100.0)
        total = c if total is None else min(total, c)
    return total


def osh_budget_left(tendons, params, total):
    if total is None:
        return None
    return float(total) - floor_strand_kg(osh_live(tendons), params)


# ---------------------------------------------------------------------------
#  الاسترندات المطلوبة والإضافة
# ---------------------------------------------------------------------------

def osh_need_strands(rows, tendons_in, live, params, face, direction,
                     n_start=None, hist=None):
    """
    (المطلوب زيادة, الموجود, أعلى استغلال). بالنسبة والتناسب افتراضياً:
    n المطلوب = n اللي اللوحة اتقرت عليه × (الإجهاد ÷ الحد)؛ أو بالقياس:
    الزيادة فوق الحد ÷ اللي الاسترند الواحد بيخففه عند القطاع ده.

    `n_start` = استرندات كل كابل أول الجولة: اللوحة بتوصف الموديل قبل
    أي زيادة في الجولة دي، فالنسبة بتتحسب على الرقم ده - واللي اتزاد
    خلاص على نفس الكابلات من بحر جاره بيتخصم من المطلوب مش بيتضاعف.
    """
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    n_now = sum(int(t.get("strands") or 0) for t in tendons_in)
    n_base = sum(int((n_start or {}).get(id(t), t.get("strands") or 0))
                 for t in tendons_in)
    u_max = max((float(r["u"]) for r in rows), default=1.0)
    need = None
    if str(getattr(params, "osh_sizing", "ratio") or "ratio") == "measured":
        worst = max(rows, key=lambda r: r["u"])
        try:
            rel, _n = strand_relief_mpa((worst["x"], worst["y"]), live, params,
                                        face=face, direction=direction)
        except Exception:
            rel = 0.0
        if rel and rel > 1e-6:
            acr = [osh_across_at(t, worst["span"], direction)
                   for t in tendons_in] if worst.get("span") else []
            width = max(1.0, (max(acr) - min(acr)) if len(acr) > 1 else 1.0)
            need = int(math.ceil((worst["v"] - worst["lim"]) / rel * width))
    if need is None:
        if n_base > 0:
            need = int(math.ceil(n_base * u_max - 1e-9)) - n_now
        else:
            need = n_min
    #  18.106: من الجولة التانية الحساب بالقياس - كام الاستغلال نزل لكل
    #  استرند اتزاد على البحر ده الجولة اللي فاتت. النسبة الخطية بتفترض
    #  إن الإجهاد كله من الاسترندات، وهو مش كده: بحر 2-8 خد 21 استرند
    #  على ست جولات ونزل من 1.37 لـ 1.10 بس، لأن كل جولة كانت بتقول
    #  "محتاج 3". القياس بيقول محتاج 12 من أول جولة.
    if (hist and hist.get("n") is not None and hist.get("u") is not None
            and n_now > int(hist["n"])):
        dn = n_now - int(hist["n"])
        relief = (float(hist["u"]) - u_max) / dn
        if relief <= 0.002:
            return -1, n_now, u_max
        need_m = int(math.ceil((u_max - 0.95) / relief - 1e-9))
        need = max(1, min(need_m, max(2, 2 * n_now)))
    return max(0, need), n_now, u_max


def osh_raise_strands(cands, need, params):
    """+1 بالدور على الكابلات المرشحة لحد ما المطلوب يتحقق أو الكل يوصل للحد."""
    n_max = max(1, int(getattr(params, "max_strands", 5) or 5))
    added = 0
    while added < need:
        progressed = False
        for t in cands:
            if added >= need:
                break
            n = int(t.get("strands") or 0)
            if n >= n_max:
                continue
            t["strands"] = n + 1
            t.setdefault("governing", {})["osh"] = True
            added += 1
            progressed = True
        if not progressed:
            break
    return added


def osh_slots(d, live, direction, params):
    """
    أماكن مرشحة للكابل الجديد عبر البحر: منتصف أكبر فجوة بين الكابلات
    المارّة فيه (الأكبر الأول)، ثم برّه آخر كابل من الجهتين.
    """
    half = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    xs = sorted(osh_across_at(t, d, direction)
                for t in osh_tendons_in_span(live, d, direction, half))
    gap = osh_min_gap(params)
    side = max(gap, 0.5 * float(getattr(params, "spacing", 1.0) or 1.0))
    centre = osh_across_pt(d["mid"], direction)
    cands = []
    for a, b in zip(xs, xs[1:]):
        w = b - a
        if w >= 2.0 * gap:
            cands.append((w, (a + b) / 2.0))
    if xs:
        #  برّه آخر كابل من الجهتين - ومنها الفراغ اللي بين حد البلاطة
        #  (أو الفتحة) وأول كابل، وده اللي المهندس طلب نستغله.
        cands += [(2.0 * side, xs[-1] + side), (2.0 * side, xs[0] - side)]
    else:
        cands.append((0.0, centre))
    #  18.116: الأقرب لمحور الركيزة الأول (مش أوسع فجوة) - الكابل القريب
    #  من خط الأعمدة هو اللي بيشيل القطاع اللي عليه، والتعادل للأوسع.
    cands.sort(key=lambda g: (round(abs(g[1] - centre), 2), -g[0]))
    out = [c for _w, c in cands]
    #  18.106: جوّه الشريحة بس - كابل على بُعد 3.75 م من محور البحر
    #  مابيعملش حاجة للقطاع اللي في نصه.
    inside = [c for c in out if abs(c - centre) <= half]
    return inside or out[:1]


def osh_route_is_clear(pts, site, clear=0.25, step=0.25):
    """
    المسار ده جوّه الخرسانة وبعيد عن كل فتحة؟ (18.105)

    أكبر فجوة بين الكابلات كتير بتبقى فتحة أصلاً - التوزيع الأصلي
    اتجنّبها - فالكابل المنسوخ كان بيتحط فيها وبيتشوّه عند الرسم.
    العيّنات كل ربع متر لازم تقع جوّه إحدى قطع البلاطة (أو حدودها)
    وبرّه كل فتحة بسماحية `clear`.
    """
    site = site or {}
    pieces = [p for p in (site.get("pieces") or []) if p and len(p) >= 3]
    if not pieces:
        b = site.get("boundary") or []
        pieces = [b] if len(b) >= 3 else []
    holes = [o for o in (site.get("openings") or []) if o and len(o) >= 3]
    if not pieces and not holes:
        return True
    if len(pts) < 2:
        return True

    def near_edge(pt, poly):
        n = len(poly)
        for i in range(n):
            a, b = poly[i], poly[(i + 1) % n]
            if point_to_segment_dist(pt[0], pt[1], a[0], a[1], b[0], b[1]) <= clear:
                return True
        return False

    samples = []
    for a, b in zip(pts, pts[1:]):
        pa, pb = a["pos"], b["pos"]
        seg = dist(pa, pb)
        n = max(1, int(seg / step))
        for i in range(n + 1):
            u = i / n
            samples.append((pa[0] + (pb[0] - pa[0]) * u,
                            pa[1] + (pb[1] - pa[1]) * u))
    for q in samples:
        if pieces and not any(point_in_polygon(q[0], q[1], p) for p in pieces):
            return False
        for o in holes:
            if point_in_polygon(q[0], q[1], o) or near_edge(q, o):
                return False
    return True


def osh_clone_over_span(donor, d, live, params, site, strands, extend,
                        direction, tag=""):
    """
    نسخة من جزء الكابل المانح اللي بيغطي البحر (نفس النقاط والمناسيب)
    من بداية البحر لنهايته زائد `extend` من الجهتين، مزحلقة عرضياً
    لأقرب مكان فاضي لمحور الركيزة. بترجّع الكابل أو None لو مافيش مكان.
    """
    prof = donor.get("profile") or []
    if len(prof) < 2:
        return None
    st = osh_stations(prof)
    total = st[-1]
    sa, _ = _station_of(prof, d["a"])
    sb, _ = _station_of(prof, d["b"])
    lo = max(0.0, min(sa, sb) - float(extend))
    hi = min(total, max(sa, sb) + float(extend))
    if hi - lo < 3.0:
        return None
    h = float(getattr(params, "slab_thickness", 260.0) or 260.0)
    anchor = h / 2.0

    def clean(q):
        c = {k: v for k, v in q.items() if not str(k).startswith("_")}
        c["pos"] = (float(q["pos"][0]), float(q["pos"][1]))
        c["manual"] = True
        return c

    pts = []
    if lo <= 1e-6:
        pts.append(clean(prof[0]))
    else:
        pts.append({"pos": _profile_point_at(prof, lo), "depth": anchor,
                    "high": True, "sag": False, "manual": True,
                    "src": "osh_anchor"})
    for q, s in zip(prof, st):
        if lo + 0.05 < s < hi - 0.05 and not q.get("inflection"):
            pts.append(clean(q))
    if hi >= total - 1e-6:
        pts.append(clean(prof[-1]))
    else:
        pts.append({"pos": _profile_point_at(prof, hi), "depth": anchor,
                    "high": True, "sag": False, "manual": True,
                    "src": "osh_anchor"})
    if len(pts) < 2:
        return None
    here = osh_across_at(donor, d, direction)
    nx, ny = (0.0, 1.0) if direction == "X" else (1.0, 0.0)
    gap = osh_min_gap(params)
    keep = ("profile", "path", "_deleted", "jacks", "nodes", "live_at_start",
            "live_at_end", "governing", "name", "spans", "span_keys",
            "from_deficit", "snapped", "offset", "added_nodes",
            "strands_manual", "_topped", "_thinned", "_shave_was",
            "_merged_into", "_gave", "from_model", "as_drawn", "inflection",
            "losses", "radius_free")
    for slot in osh_slots(d, live, direction, params):
        off = slot - here
        moved = []
        for c in pts:
            c2 = dict(c)
            c2["pos"] = (c["pos"][0] + nx * off, c["pos"][1] + ny * off)
            moved.append(c2)
        new = {k: v for k, v in donor.items() if k not in keep}
        new.update({
            "profile": moved, "dir": direction,
            "strands": _clamp_strands(int(strands), params),
            "added": True, "as_drawn": False, "from_model": False,
            "governing": {"osh_added": True, "span": d.get("name")},
            "length": tendon_plan_length({"profile": moved}),
            "full_length": False,
            "coord": osh_across_pt(moved[0]["pos"], direction),
            "name": f"OSH{tag} {d.get('name') or ''}".strip(),
            "osh_span": d.get("name"), "offset": off,
        })
        dmin, _near = nearest_parallel(new, live)
        if dmin < gap - 1e-6:
            continue
        if not osh_route_is_clear(moved, site,
                                  float(getattr(params, "efm_added_clear", 0.25)
                                        or 0.25)):
            continue
        return new
    return None


def osh_clone_full(donor, across_target, direction, strands, params, live,
                   name="", site=None):
    """نسخة كاملة الطول من كابل، مزحلقة عرضياً لإحداثي معيّن."""
    prof = donor.get("profile") or []
    if len(prof) < 2:
        return None
    here = osh_across(donor, direction)
    off = float(across_target) - here
    nx, ny = (0.0, 1.0) if direction == "X" else (1.0, 0.0)
    pts = []
    for q in prof:
        c = {k: v for k, v in q.items() if not str(k).startswith("_")}
        c["pos"] = (float(q["pos"][0]) + nx * off, float(q["pos"][1]) + ny * off)
        c["manual"] = True
        pts.append(c)
    new = {"profile": pts, "dir": direction,
           "strands": _clamp_strands(int(strands), params),
           "added": True, "as_drawn": False, "from_model": False,
           "governing": {"osh_added": True, "long": True},
           "length": tendon_plan_length({"profile": pts}),
           "full_length": True,
           "coord": osh_across_pt(pts[0]["pos"], direction),
           "name": name or "OSH long", "offset": off}
    dmin, _near = nearest_parallel(new, live)
    if dmin < osh_min_gap(params) - 1e-6:
        return None
    if not osh_route_is_clear(pts, site,
                              float(getattr(params, "efm_added_clear", 0.25)
                                    or 0.25)):
        return None
    return new


# ---------------------------------------------------------------------------
#  هندسة الركائز والدروب على مسار الكابل
# ---------------------------------------------------------------------------

def osh_support_polys(site):
    return [corners for _k, corners, _bb, _dv in _support_shapes(site or {})
            if corners]


def osh_walk_first_inside(prof, s_from, s_to, polys, step=0.05):
    """أول محطة من s_from لـ s_to النقطة عندها جوّه أي بوليجون - أو None."""
    if not polys:
        return None
    n = max(1, int(abs(s_to - s_from) / step))
    for i in range(n + 1):
        s = s_from + (s_to - s_from) * i / n
        p = _profile_point_at(prof, s)
        for poly in polys:
            if poly and len(poly) >= 3 and point_in_polygon(p[0], p[1], poly):
                return s
    return None


def osh_end_geometry(t, d, end_xy, site, reach=1.5, edge_reach=3.0, across=1.5):
    """
    للكابل عند طرف البحر ده: (محطة الطرف, إشارة الاتجاه من الداخل للخارج,
    محطة وش الركيزة أو None, محطة حافة الدروب أو None).

    **18.113: الركيزة هي طرف شريحة التصميم نفسه** (End 1 / End 2 في رام) -
    مش أقرب بصمة عامود في 3 م زي قبل كده، لأن الكابل الماشي جنب فتحة أو
    جنب عامود كان بيلاقي بصمة غلط أو مايلاقيش حاجة. البصمة بتتستخدم بس
    عشان القمة تتظبّط على الوش لو فيه بصمة **عند الطرف ده فعلاً**: في
    حدود `reach` منه على مسار الكابل وعلى ≤ `across` منه عرضياً. لو الكابل
    ماشي فوقها الوش هو أول نقطة جوّاها من ناحية البحر، ولو ماشي جنبها
    الوش هو إسقاطها على المسار. غير كده بيرجع None والطرف نفسه هو الهدف.
    """
    prof = t.get("profile") or []
    st = osh_stations(prof)
    s_end, _ = _station_of(prof, end_xy)
    s_mid, _ = _station_of(prof, d["mid"])
    sign = 1.0 if s_end >= s_mid else -1.0
    total = st[-1]
    w_lo = max(0.0, min(total, s_end - reach))
    w_hi = max(0.0, min(total, s_end + reach))
    inner, outer = (w_lo, w_hi) if sign > 0 else (w_hi, w_lo)
    face = None
    best = None
    for poly in osh_support_polys(site):
        pts = [_station_of(prof, c) for c in poly]
        if min(o for _s, o in pts) > across:
            continue
        lo = min(s for s, _o in pts)
        hi = max(s for s, _o in pts)
        if hi < w_lo or lo > w_hi:
            continue
        #  18.116: الوش بس لما الكابل ماشي فوق البصمة فعلاً. الكابل اللي
        #  ماشي جنب العامود هدفه طرف الشريحة نفسه (محور الركيزة) - إسقاط
        #  البصمة عليه كان بيسيب القمة على حافة الدروب ويقول "على الوش".
        f = osh_walk_first_inside(prof, inner, outer, [poly])
        if f is None:
            continue
        score = abs((lo + hi) / 2.0 - s_end)
        if best is None or score < best:
            best, face = score, f
    e_lo = max(0.0, min(total, s_end - edge_reach))
    e_hi = max(0.0, min(total, s_end + edge_reach))
    e_in, e_out = (e_lo, e_hi) if sign > 0 else (e_hi, e_lo)
    edge = osh_walk_first_inside(prof, e_in, e_out,
                                 [p for p in ((site or {}).get("drops") or [])
                                  if p and len(p) >= 3])
    return s_end, sign, face, edge


def osh_near_drop_edge(xy, drops, tol):
    for poly in drops or []:
        n = len(poly)
        if n < 3:
            continue
        for i in range(n):
            a, b = poly[i], poly[(i + 1) % n]
            if point_to_segment_dist(xy[0], xy[1], a[0], a[1], b[0], b[1]) <= tol:
                return poly
    return None


def osh_insert_point(prof, station, point, min_gap):
    """يحط نقطة عند محطة، لو مافيش نقطة تانية أقرب من min_gap. بيرجّع True/False."""
    st = osh_stations(prof)
    for s in st:
        if abs(s - station) < min_gap:
            return False
    idx = len(prof) - 1
    for i, s in enumerate(st):
        if s > station:
            idx = i
            break
    point = dict(point)
    point["pos"] = _profile_point_at(prof, station)
    point["manual"] = True
    prof.insert(idx, point)
    return True


def osh_top_depth(t, params, direction):
    """
    منسوب القمة الجديدة: **الغطاء العلوي من الإعدادات** (18.116) - المهندس
    طلب إن الرسم يمشي على الارتفاعات اللي في الإعدادات. قمم الكابل نفسه
    بتتستخدم بس لو الإعدادات ماتقرتش.
    """
    try:
        return float(params.covers_for(direction)[0])
    except Exception:
        pass
    highs = [float(q["depth"]) for q in (t.get("profile") or [])[1:-1]
             if q.get("high") and q.get("depth") is not None]
    if highs:
        return min(highs)
    return float(getattr(params, "top_cover", 40.0) or 40.0)


def osh_add_drop_high(t, d, end_xy, site, params, direction):
    """
    نقطة عالية بين حافة الدروب والعامود لو مافيش. بترجّع
    "added" / "exists" / "no drop" / "no room".
    """
    s_end, sign, face, edge = osh_end_geometry(t, d, end_xy, site)
    if edge is None:
        return "no drop"
    stop = face if face is not None else s_end
    lo, hi = sorted((edge, stop))
    prof = t["profile"]
    st = osh_stations(prof)
    for q, s in zip(prof[1:-1], st[1:-1]):
        if q.get("high") and lo + 1e-6 < s < hi - 1e-6:
            return "exists"
    inset = float(getattr(params, "drop_node_inset", 0.30) or 0.30)
    station = edge + sign * inset
    if not (lo <= station <= hi):
        station = (lo + hi) / 2.0
    gap = max(0.5, float(getattr(params, "min_point_gap", 0.5) or 0.5))
    ok = osh_insert_point(prof, station, {"depth": osh_top_depth(t, params, direction),
                                          "high": True, "sag": False,
                                          "src": "osh_drop"}, gap)
    return "added" if ok else "no room"


def osh_peak_to_face(t, d, end_xy, site, params, direction, tol=0.25):
    """
    القمم اللي في جهة الطرف ده وبعيدة عن وش الركيزة بتتشال، وقمة واحدة
    بتتحط على الوش بالظبط. بترجّع عدد اللي اتغيّر (0 = القمة على الوش
    خلاص). **18.113:** الركيزة هي طرف شريحة التصميم (End 1 / End 2): القمة
    بتتحط على وش بصمتها لو فيه بصمة عند الطرف ده، وإلا على الطرف نفسه.
    الطرف اللي رام بيقول إنه مش على ركيزة (AtSupport = False، تقسيمة
    جوّه البحر) مابيتحطش عليه قمة. السبب في t["_osh_face_why"].
    """
    s_end, sign, face, _edge = osh_end_geometry(t, d, end_xy, site)
    t["_osh_face_why"] = "face"
    if face is None:
        at_sup = (d.get("at_support_a") if dist(end_xy, d["a"]) <= dist(end_xy, d["b"])
                  else d.get("at_support_b"))
        if at_sup is False:
            t["_osh_face_why"] = "no support"
            return 0
        face = s_end
        t["_osh_face_why"] = "span end"
    prof = t["profile"]
    st = osh_stations(prof)
    s_mid, _ = _station_of(prof, d["mid"])
    lo, hi = sorted((s_mid, s_end + sign * 2.5))
    gap = max(0.5, float(getattr(params, "min_point_gap", 0.5) or 0.5))
    on_face = any(0 < i < len(prof) - 1 and q.get("high") and lo < s < hi
                  and abs(s - face) <= tol
                  for i, (q, s) in enumerate(zip(prof, st)))
    if on_face:
        #  القمة على الهدف خلاص: القمم التانية اللي في النافذة بتتشال بس.
        keep = [q for i, (q, s) in enumerate(zip(prof, st))
                if not (0 < i < len(prof) - 1 and q.get("high") and lo < s < hi
                        and abs(s - face) > tol)]
        changed = len(prof) - len(keep)
        prof[:] = keep
        return changed
    #  **18.116: القمة عمرها ما تتشال من غير ما واحدة تتحط مكانها.** في رن
    #  المهندس القمة القديمة اتشالت وقاعدة "مافيش نقطة أقرب من 0.5 م"
    #  رفضت الجديدة (نقطة انقلاب أو عقدة مسار جنب الوش) - فالكابل خرج
    #  من غير قمة عند الركيزة. دلوقتي: نقط الانقلاب اللي جنب الهدف
    #  بتتشال، والعقدة اللي لسه أقرب من الفجوة بتتنقل هي نفسها على الهدف
    #  وتبقى القمة. ولو ماينفعش، القمم القديمة تفضل مكانها.
    old = [(q, s) for i, (q, s) in enumerate(zip(prof, st))
           if 0 < i < len(prof) - 1 and q.get("high") and lo < s < hi]
    keep = []
    for i, (q, s) in enumerate(zip(prof, st)):
        inner = 0 < i < len(prof) - 1
        if inner and q.get("high") and lo < s < hi:
            continue
        if inner and q.get("inflection") and abs(s - face) < gap:
            continue
        keep.append(q)
    changed = len(prof) - len(keep)
    prof[:] = keep
    point = {"depth": osh_top_depth(t, params, direction), "high": True,
             "sag": False, "src": "osh_face"}
    if osh_insert_point(prof, face, point, gap):
        return changed + 1
    st2 = osh_stations(prof)
    near = [(abs(s - face), i) for i, (q, s) in enumerate(zip(prof, st2))
            if 0 < i < len(prof) - 1 and not q.get("sag") and abs(s - face) < gap]
    if near:
        i = min(near)[1]
        q = prof[i]
        q.update(point)
        q["pos"] = _profile_point_at(prof, face)
        q["manual"] = True
        q.pop("inflection", None)
        return changed + 1
    #  مافيش مكان ولا عقدة تتنقل: القمم القديمة ترجع زي ما كانت.
    for q, s in old:
        osh_insert_point(prof, s, q, 0.0)
    t["_osh_face_why"] = "no room"
    return 0


def osh_shift_lows(t, d, toward_xy, frac, params):
    """
    الغطسات اللي جوّه البحر ده بتتحرك ناحية الطرف الراسب بنسبة `frac`
    من طول البحر - مقيسة من مكانها الأصلي، فـ 10 ثم 20 ثم 30 تراكمياً
    من نفس المركز. بترجّع عدد النقاط اللي اتحركت.
    """
    prof = t.get("profile") or []
    if len(prof) < 3:
        return 0
    st = osh_stations(prof)
    sa, _ = _station_of(prof, d["a"])
    sb, _ = _station_of(prof, d["b"])
    lo, hi = sorted((sa, sb))
    L = hi - lo
    if L < 1.0:
        return 0
    s_to, _ = _station_of(prof, toward_xy)
    sign = 1.0 if s_to >= (lo + hi) / 2.0 else -1.0
    gap = max(0.5, float(getattr(params, "min_point_gap", 0.5) or 0.5))
    #  18.106: الغطسة ماتقرّبش من القمة أكتر من اللي نصف القطر الأدنى
    #  يسمح بيه: R = (r/2)·L²/Δ (نفس معادلة enforce_min_radius)، يعني
    #  L ≥ √(2·R·Δ/r). من غير كده الزحزحة 20-30% كانت بتعمل كوع أحدّ من
    #  الدكت، وقاعدة نصف القطر بتردّ عليه برفع الغطسة - فالغطس بيقل
    #  والقطاع بيبقى أسوأ مش أحسن.
    try:
        rmin = float(effective_min_radius(params) or 0.0)
    except Exception:
        rmin = 0.0
    r_inf = float(getattr(params, "ram_inflection_ratio", 0.2) or 0.2)
    r_inf = max(0.02, min(r_inf, 0.5))

    #  **18.110: الغطسة بتتحرك زي ما القاعدة بتقول، ولو القرب من القمة
    #  كسر نصف القطر بتترفع بالقدر اللي يرجّعه.** النسخة اللي فاتت كانت
    #  بتمنع الحركة خالص لو البحر أصلاً على حد نصف القطر - وده حال أغلب
    #  البحور القصيرة بين الدروبات - فالمهندس شاف قطاع علوي راسب
    #  والغطسة مكانها. الرفع بيتحسب من نفس معادلة enforce_min_radius:
    #  Δ المسموح = (r/2)·L²/R على كل جهة، والغطسة بتاخد الأعمق المسموح.
    moved, lifted = 0, 0.0
    for i in range(1, len(prof) - 1):
        q = prof[i]
        if not q.get("sag"):
            continue
        base = q.get("_osh_base_s")
        if base is None:
            base = st[i]
            q["_osh_base_s"] = base
        if not (lo < base < hi):
            continue
        new = base + sign * float(frac) * L
        new = max(st[i - 1] + gap, min(st[i + 1] - gap, new))
        if abs(new - st[i]) < 0.05:
            continue
        depth = float(q.get("depth") or 0.0)
        cap = depth
        if rmin > 0:
            for nb, s_nb in ((prof[i - 1], st[i - 1]), (prof[i + 1], st[i + 1])):
                if nb.get("sag"):
                    continue
                L_side = abs(new - s_nb)
                d_nb = float(nb.get("depth") or 0.0)
                dz_max = (r_inf / 2.0) * L_side * L_side / rmin * 1000.0
                cap = min(cap, d_nb + dz_max)
        shallowest = max(float(prof[i - 1].get("depth") or 0.0),
                         float(prof[i + 1].get("depth") or 0.0)) + 10.0
        if cap < shallowest:
            #  الحركة دي تخلّي الغطسة فوق القمة اللي جنبها - مش غطسة خلاص
            continue
        q["pos"] = _profile_point_at(prof, new)
        q["manual"] = True
        q.pop("_s", None)
        if cap < depth - 0.5:
            q["depth"] = round_to(cap, float(getattr(params, "elevation_rounding", 5.0) or 5.0))
            q["_osh_lifted_mm"] = depth - q["depth"]
            lifted = max(lifted, depth - q["depth"])
        moved += 1
    t["_osh_lift_mm"] = lifted
    return moved


# ---------------------------------------------------------------------------
#  صور للتراجع
# ---------------------------------------------------------------------------

def osh_centre_low(t, d, params, tol_frac=0.05):
    """
    الغطسة الوحيدة جوّه البحر ده بترجع لنص البحر لو بعيدة عنه أكتر من
    `tol_frac` من طوله (18.111). بترجّع 1 لو اتحركت.
    """
    prof = t.get("profile") or []
    if len(prof) < 3:
        return 0
    st = osh_stations(prof)
    sa, _ = _station_of(prof, d["a"])
    sb, _ = _station_of(prof, d["b"])
    lo, hi = sorted((sa, sb))
    L = hi - lo
    if L < 1.0:
        return 0
    idx = [i for i in range(1, len(prof) - 1)
           if prof[i].get("sag") and lo < st[i] < hi]
    if len(idx) != 1:
        return 0
    i = idx[0]
    mid = (lo + hi) / 2.0
    if abs(st[i] - mid) <= tol_frac * L:
        return 0
    gap = max(0.5, float(getattr(params, "min_point_gap", 0.5) or 0.5))
    new = max(st[i - 1] + gap, min(st[i + 1] - gap, mid))
    if abs(new - st[i]) < 0.05:
        return 0
    q = prof[i]
    q["pos"] = _profile_point_at(prof, new)
    q.pop("_s", None)
    q.pop("_osh_base_s", None)
    return 1


def osh_window_snapshot(t, d, end_xy, reach=2.5):
    """
    صورة النقط الداخلية اللي بين نص البحر وطرفه (+reach) بهويتها، عشان
    نقلة القمة على الركيزة تتقاس وترجع لو ماكانتش نافعة (18.116).
    """
    prof = t.get("profile") or []
    if len(prof) < 3:
        return None
    st = osh_stations(prof)
    s_end, _ = _station_of(prof, end_xy)
    s_mid, _ = _station_of(prof, d["mid"])
    sign = 1.0 if s_end >= s_mid else -1.0
    lo, hi = sorted((s_mid, s_end + sign * reach))
    return {"lo": lo, "hi": hi,
            "pts": [(q, dict(q)) for i, (q, s_q) in enumerate(zip(prof, st))
                    if 0 < i < len(prof) - 1 and lo < s_q < hi]}


def osh_window_restore(t, snap):
    """بيرجّع النافذة زي ما كانت: اللي اتشال يرجع، اللي اتضاف يتشال، واللي اتعدّل يرجع."""
    if not snap:
        return 0
    prof = t.get("profile") or []
    if len(prof) < 2:
        return 0
    lo, hi = snap["lo"], snap["hi"]
    ids = {id(q) for q, _s in snap["pts"]}
    st = osh_stations(prof)
    prof[:] = [q for i, (q, s_q) in enumerate(zip(prof, st))
               if i == 0 or i == len(prof) - 1 or id(q) in ids or not (lo < s_q < hi)]
    present = {id(q) for q in prof}
    n = 0
    for q, saved in snap["pts"]:
        if id(q) in present:
            if dict(q) != saved:
                q.clear()
                q.update(saved)
                n += 1
            continue
        st = osh_stations(prof)
        s_q, _ = _station_of(prof, saved["pos"])
        idx = len(prof) - 1
        for i, s_i in enumerate(st):
            if s_i > s_q:
                idx = i
                break
        prof.insert(idx, dict(saved))
        n += 1
    return n


def osh_size_down(n, params):
    """أكبر مقاس متاح تحت n لو فيه قايمة مقاسات، وإلا n-1."""
    sizes = sorted(int(x) for x in (getattr(params, "allowed_strands", None) or [])
                   if int(x) > 0)
    n = int(n)
    if not sizes:
        return n - 1
    below = [x for x in sizes if x < n]
    return below[-1] if below else n


def osh_snapshot(tendons):
    import copy
    return [(t, copy.deepcopy({k: v for k, v in t.items() if k != "path"}))
            for t in (tendons or [])]


def osh_restore(tendons, snap):
    """بيرجّع كل كابل لصورته، وبيشيل اللي اتضاف بعدها."""
    known = set()
    for t, saved in snap:
        known.add(id(t))
        path = t.get("path")
        t.clear()
        t.update(saved)
        if path is not None:
            t["path"] = path
    for t in tendons or []:
        if id(t) not in known:
            t["_deleted"] = True


# ---------------------------------------------------------------------------
#  البحور المتجاورة على محور واحد (18.109)
# ---------------------------------------------------------------------------

def osh_span_groups(keys, span_state, tol=0.6):
    """
    البحور الراسبة اللي وراء بعض على نفس الخط بتتجمّع في مجموعة واحدة:
    طرف واحد بيقابل بداية اللي بعده. بترجّع [[(key, d), ...], ...].
    """
    items = [(k, span_state[k]["d"]) for k in keys if k in span_state]
    groups, used = [], set()
    for k, d in items:
        if k in used:
            continue
        grp = [(k, d)]
        used.add(k)
        changed = True
        while changed:
            changed = False
            for k2, d2 in items:
                if k2 in used:
                    continue
                if any(dist(d2["a"], g["b"]) <= tol or dist(d2["b"], g["a"]) <= tol
                       or dist(d2["a"], g["a"]) <= tol or dist(d2["b"], g["b"]) <= tol
                       for _k, g in grp):
                    grp.append((k2, d2))
                    used.add(k2)
                    changed = True
        groups.append(grp)
    return groups


def osh_group_span(grp, direction):
    """بحر واحد بيغطي المجموعة كلها: من أول طرف لآخر طرف على المحور."""
    if len(grp) == 1:
        return grp[0][1]
    pts = [g["a"] for _k, g in grp] + [g["b"] for _k, g in grp]
    lo = min(pts, key=lambda p: osh_along(p, direction))
    hi = max(pts, key=lambda p: osh_along(p, direction))
    return {"name": "+".join(str(g.get("name") or "?") for _k, g in grp),
            "a": lo, "b": hi,
            "mid": ((lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0),
            "length": dist(lo, hi), "group": [k for k, _g in grp]}


def osh_band_donor(t_in, d, direction):
    """
    الكابل اللي بروفايله بيتنسخ: أقرب كابل لمحور البحر - يعني لخط
    الأعمدة (الـ band zone)، مش الأبعد عنها. البروفايل هناك هو اللي
    قممه على الركائز فعلاً. (18.109)
    """
    if not t_in:
        return None
    centre = osh_across_pt(d["mid"], direction)
    return min(t_in, key=lambda t: (abs(osh_across_at(t, d, direction) - centre),
                                    -tendon_plan_length(t)))


def osh_fail_share(t, fail_ds, half):
    """
    نسبة طول الكابل اللي بيمرّ في بحور راسبة: مجموع أطوال البحور
    الراسبة اللي بيقطعها ÷ طوله. دي اللي بتقرر "زوّد استرندات المحور
    كله الأول".
    """
    L = tendon_plan_length(t)
    if L <= 0:
        return 0.0
    fl = 0.0
    for d in fail_ds:
        if _tendons_over_span([t], d, strip=half):
            fl += float(d.get("length") or dist(d["a"], d["b"]))
    return min(1.0, fl / L)


# ---------------------------------------------------------------------------
#  المرحلة 1 - القطاعات السفلية
# ---------------------------------------------------------------------------

def osh_bottom_round(state, tendons, params, site, job, direction, budget,
                     hist=None, stages=None):
    """
    كل بحر راسب على الوش السفلي في الاتجاه ده بياخد علاجه في الجولة دي.

    **18.109: المحور قبل البحر.** البحور الراسبة المتجاورة على نفس الخط
    بتتعالج كمجموعة واحدة: الكابل اللي البحور الراسبة بتغطي أكتر من
    `osh_span_ratio` من طوله بياخد استرندات الأول (المحور كله)، واللي
    يفضل ناقص بياخد كابل طويل واحد بيغطي المجموعة كلها (+3 م من
    الجهتين) - مش قطعة لكل بحر فوق بعض.
    بترجّع (اتزوّد استرندات, اتضاف كابلات, بحور اتعالجت, اللي مافيش له علاج).
    """
    live = osh_live(tendons)
    half = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    ratio_min = float(getattr(params, "osh_span_ratio", 70.0) or 70.0) / 100.0
    extend = float(getattr(params, "osh_extend_m", 3.0) or 3.0)
    n_max = max(1, int(getattr(params, "max_strands", 5) or 5))
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    step_max = max(1, int(getattr(params, "osh_step_max", 3) or 3))
    fail_keys = [k for (k, f) in state["fail"]
                 if f == "bottom" and state["spans"][k]["dir"] == direction]
    fail_ds = [state["spans"][k]["d"] for k in fail_keys]
    strands_added, tendons_added, treated, stuck = 0, 0, 0, []
    stages = stages if stages is not None else {}
    n_start = {id(t): int(t.get("strands") or 0) for t in live}
    _share = {}

    def share_of(t):
        if id(t) not in _share:
            _share[id(t)] = osh_fail_share(t, fail_ds, half)
        return _share[id(t)]

    groups = osh_span_groups(fail_keys, state["spans"])
    groups.sort(key=lambda grp: -max(state["spans"][k]["bottom"] for k, _d in grp))
    for grp in groups:
        job.check()
        dg = osh_group_span(grp, direction)
        label = dg.get("name") or "?"
        t_in, seen = [], set()
        needs, u_worst, n_tot = [], 0.0, 0
        for k, d in grp:
            rec = state["spans"][k]
            t_k = osh_tendons_in_span(live, d, direction, half)
            for t in t_k:
                if id(t) not in seen:
                    seen.add(id(t))
                    t_in.append(t)
            prev = (hist or {}).get(k)
            need_k, n_k, u_k = osh_need_strands(rec["rows"]["bottom"], t_k, live,
                                                params, "bottom", direction,
                                                n_start=n_start, hist=prev)
            if hist is not None:
                hist[k] = {"u": u_k, "n": n_k}
            needs.append(need_k)
            u_worst = max(u_worst, u_k)
            n_tot = max(n_tot, n_k)
        live_needs = [n for n in needs if n >= 0]
        if not live_needs:
            job.warn(f"    span {label} ({direction}, bottom): worst {u_worst:.2f} "
                     f"- the strands added here last round did not move it, so "
                     f"nothing more is put here. That section wants depth, a "
                     f"drop or reinforcement.")
            stuck.append((label, "unresponsive"))
            continue
        need = max(live_needs)
        job.info(f"    span {label} ({direction}, bottom"
                 + (f", {len(grp)} spans on one axis" if len(grp) > 1 else "")
                 + f"): worst {u_worst:.2f} of the limit, {len(t_in)} tendon(s) "
                 f"with {n_tot} strands - needs about {need} more.")
        #  **18.111: الهندسة قبل الحديد.** أول مرة البحر ده يتعالج: القمم
        #  اللي جنب طرفيه بتتحط على وش الركيزة (مش على حافة الدروب)
        #  والغطسة بترجع لنص البحر - وده اللي المهندس عمله بإيده وسيّف
        #  البحر بـ 3 استرندات بدل 5. لو حاجة اتحركت بنحلل الأول.
        gk = tuple(sorted(str(k) for k, _d in grp))
        stg = stages.setdefault(gk, {"geom": False})
        if not stg["geom"] and t_in:
            stg["geom"] = True
            n_g = 0
            for t in t_in:
                for k, d in grp:
                    for exy in (d["a"], d["b"]):
                        n_g += osh_peak_to_face(t, d, exy, site, params, direction)
                    n_g += osh_centre_low(t, d, params)
            if n_g:
                treated += 1
                strands_added += 0
                job.ok(f"        geometry first: {n_g} point(s) put where they "
                       f"belong - high points on the support faces, the low "
                       f"point at mid-span - on {len(t_in)} tendon(s); "
                       f"re-analysing before any strand is added.")
                stuck.append((label, "geometry"))
                continue
        if need > step_max:
            job.info(f"        capped at {step_max} strand(s) this round; the "
                     f"next round measures what they did before adding more.")
            need = step_max
        if need <= 0:
            job.info("        already covered by what this round put on the "
                     "same tendons for a neighbouring span.")
            treated += 1
            continue
        left = osh_budget_left(tendons, params, budget)
        if left is not None and left <= 0:
            stuck.append((label, "budget"))
            job.warn("        the strand budget is used up - nothing added.")
            continue
        #  1) المحور كله الأول: الكابل اللي البحور الراسبة بتغطي أكتر من
        #     النسبة من طوله بياخد الاسترندات.
        got = 0
        cands = [t for t in t_in if share_of(t) > ratio_min
                 and int(t.get("strands") or 0) < n_max]
        if cands:
            cands.sort(key=lambda t: (-share_of(t), -int(t.get("strands") or 0)))
            got = osh_raise_strands(cands, need, params)
            if got:
                strands_added += got
                job.ok(f"        +{got} strand(s) on {len(cands)} tendon(s) along "
                       f"the axis - failing spans cover "
                       f"{', '.join(f'{100 * share_of(t):.0f}%' for t in cands[:4])}"
                       f" of their length.")
        rest = need - got
        if rest > 0:
            why = (f"no tendon through it has failing spans over more than "
                   f"{100 * ratio_min:.0f}% of its length"
                   if not cands else "the tendons along the axis are at the "
                                     "strand limit")
            if not t_in:
                why = "no tendon passes through it"
            donor = osh_band_donor(t_in, dg, direction)
            if donor is None:
                cand = [t for t in live if osh_tendon_dir(t) == direction]
                if cand:
                    donor = min(cand, key=lambda t: _station_of(
                        t["profile"], dg["mid"])[1])
            #  18.116: الكابل اللي اتضاف قبل كده على نفس البحر بيتملى
            #  للحد الأول - كابلين خمسات أحسن من تلاتة تلاتات.
            prior = [t for t in t_in if (t.get("governing") or {}).get("osh_added")
                     and int(t.get("strands") or 0) < n_max]
            if prior and rest > 0:
                more = osh_raise_strands(prior, rest, params)
                if more:
                    strands_added += more
                    rest -= more
                    job.ok(f"        +{more} strand(s) on the {len(prior)} tendon(s) "
                           f"added earlier over this span - filled before "
                           f"another one is added.")
            #  2) كابل طويل واحد على المجموعة كلها
            made = 0
            while rest > 0 and donor is not None and made < 2:
                n = min(n_max, max(n_min, rest))
                new = osh_clone_over_span(donor, dg, osh_live(tendons), params,
                                          site, n, extend, direction,
                                          tag=f"-b{made + 1}")
                if new is None:
                    break
                tendons.append(new)
                live = osh_live(tendons)
                made += 1
                tendons_added += 1
                rest -= int(new["strands"])
                job.ok(f"        new tendon over {label} as one piece, "
                       f"{new['strands']} strand(s), offset {new['offset']:+.2f} m "
                       f"into the free lane nearest the column line, extended {extend:.0f} m past "
                       f"each end ({why}).")
            if rest > 0 and made == 0:
                room = [t for t in t_in if int(t.get("strands") or 0) < n_max]
                extra = osh_raise_strands(room, rest, params) if room else 0
                if extra:
                    strands_added += extra
                    rest -= extra
                    job.ok(f"        no gap wide enough for a new tendon that "
                           f"stays inside the slab and clear of the openings, "
                           f"so +{extra} strand(s) went onto the "
                           f"{len(room)} tendon(s) through the span instead.")
                else:
                    stuck.append((label, "no room" if donor is not None else "no tendon"))
                    job.warn(f"        nothing could be placed here: {why}, "
                             f"no gap wide enough for a new tendon that stays "
                             f"inside the slab and clear of the openings, and "
                             f"the tendons through it are at the strand limit.")
        if got or rest <= 0 or need - got < need:
            treated += 1
    return strands_added, tendons_added, treated, stuck


# ---------------------------------------------------------------------------
#  المرحلة 2 - القطاعات العلوية
# ---------------------------------------------------------------------------

def osh_top_round(state, tendons, params, site, job, direction, budget, stages,
                  hist=None):
    """
    كل بحر راسب على الوش العلوي في الاتجاه ده بيتقدّم خطوة واحدة في
    الجولة دي حسب مرحلته: حافة الدروب → القمة على الوش → النهايتين ولا
    نهاية → إضافة (استرندات على المحور ثم كابل). `stages` بتفضل بين
    الجولات. بترجّع (عدد الأفعال, بحور استنفدت علاجها).

    **18.114:** زحزحة الغطسة ناحية الطرف الراسب بقت حسب `osh_low_shift`:
    "never" (الافتراضي) الغطسة بتفضل في نص البحر وفي القاع؛ "last" بتتجرّب
    بس لما الاسترندات والكابل مايتضافوش، وبتترجّع لو الجولة الجاية ماوّرتش
    تحسّن؛ "first" هي سلّم 18.103 القديم (قبل الإضافة) مع نفس التراجع.
    """
    live = osh_live(tendons)
    half = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    extend = float(getattr(params, "osh_extend_m", 3.0) or 3.0)
    big = float(getattr(params, "osh_margin_big", 0.70) or 0.70)
    edge_tol = float(getattr(params, "osh_drop_edge_tol", 0.60) or 0.60)
    shifts = [float(x) / 100.0 for x in
              str(getattr(params, "osh_low_shift_steps", "10, 20, 30")
                  or "10, 20, 30").replace(";", ",").split(",") if x.strip()]
    if not shifts:
        shifts = [0.10, 0.20, 0.30]
    shift_mode = str(getattr(params, "osh_low_shift", "never") or "never")
    if shift_mode == "never":
        shifts = []
    n_max = max(1, int(getattr(params, "max_strands", 5) or 5))
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    drops = (site or {}).get("drops") or []
    fail_keys = [k for (k, f) in state["fail"]
                 if f == "top" and state["spans"][k]["dir"] == direction]
    fail_ds = [state["spans"][k]["d"] for k in fail_keys]
    ratio_min = float(getattr(params, "osh_span_ratio", 70.0) or 70.0) / 100.0
    actions, exhausted = 0, []
    n_start = {id(t): int(t.get("strands") or 0) for t in live}
    #  البحور اللي هتوصل لخطوة الإضافة الجولة دي - عشان المتجاور منها
    #  ياخد كابل واحد طويل.
    add_ready = set()
    for k in fail_keys:
        st0 = stages.get(k) or {}
        rows0 = state["spans"][k]["rows"]["top"]
        ends0 = {("a" if dist((r["x"], r["y"]), state["spans"][k]["d"]["a"])
                  <= dist((r["x"], r["y"]), state["spans"][k]["d"]["b"]) else "b")
                 for r in rows0 if r["u"] > 1.0}
        if (st0.get("step") == "add" and int(st0.get("adds", 0)) < 3) or (
                st0.get("step") == "ends" and len(ends0) == 2):
            add_ready.add(k)

    def add_over(d, rows, t_in, label, tag, key=None):
        nonlocal live
        worst = max(rows, key=lambda r: r["u"])
        wkey = (round(worst["x"], 1), round(worst["y"], 1), "top",
                stages.get("_round", 0))
        done = stages.setdefault("_cloned", set())
        if wkey in done:
            job.info(f"        a tendon was already added for this section "
                     f"from the span on the other side of the support.")
            return 0
        prev = (hist or {}).get(key) if key is not None else None
        need, n_now, u_max = osh_need_strands(rows, t_in, live, params, "top",
                                              direction, n_start=n_start,
                                              hist=prev)
        if need < 0:
            job.warn(f"        the strands added here last round did not move "
                     f"this section ({prev['u']:.2f} -> {u_max:.2f}); nothing "
                     f"more is put here.")
            return 0
        if need <= 0:
            need = max(1, int(getattr(params, "min_strands", 2) or 2))
        step_max = max(1, int(getattr(params, "osh_step_max", 3) or 3))
        if need > step_max:
            job.info(f"        capped at {step_max} strand(s) this round; the "
                     f"next round measures what they did before adding more.")
            need = step_max
        left = osh_budget_left(tendons, params, budget)
        if left is not None and left <= 0:
            job.warn("        the strand budget is used up - nothing added.")
            return 0
        #  18.109: المحور الأول - الكابل اللي القطاعات العلوية الراسبة
        #  على أكتر من النسبة من طوله بياخد استرندات قبل أي كابل جديد.
        rest = need
        cands = [t for t in t_in if osh_fail_share(t, fail_ds, half) > ratio_min
                 and int(t.get("strands") or 0) < n_max]
        got = osh_raise_strands(cands, rest, params) if cands else 0
        if got:
            rest -= got
            job.ok(f"        +{got} strand(s) on {len(cands)} tendon(s) along "
                   f"the axis first (their failing spans cover more than "
                   f"{100 * ratio_min:.0f}% of their length).")
            if rest <= 0:
                return got
        #  والبحر المجاور اللي وصل لنفس الخطوة بياخد نفس الكابل: قطعة
        #  واحدة طويلة على الاتنين بدل قطعتين فوق بعض.
        dg = d
        twins = []
        for k2 in list(add_ready):
            if k2 == key or k2 not in state["spans"]:
                continue
            d2 = state["spans"][k2]["d"]
            if (dist(d2["a"], d["b"]) <= 0.6 or dist(d2["b"], d["a"]) <= 0.6
                    or dist(d2["a"], d["a"]) <= 0.6 or dist(d2["b"], d["b"]) <= 0.6):
                twins.append((k2, d2))
        if twins:
            dg = osh_group_span([(key, d)] + twins, direction)
            for k2, _d2 in twins:
                stages.setdefault(k2, {})["_covered"] = stages.get("_round", 0)
            label = dg["name"]
            for k2, d2 in twins:
                for t in osh_tendons_in_span(live, d2, direction, half):
                    if not any(t is x for x in t_in):
                        t_in.append(t)
        donor = osh_band_donor(t_in, dg, direction)
        if donor is None:
            cand = [t for t in live if osh_tendon_dir(t) == direction]
            if cand:
                donor = min(cand, key=lambda t: _station_of(t["profile"], dg["mid"])[1])
        #  18.116: الكابل اللي اتضاف قبل كده على البحر ده بيتملى للحد الأول.
        prior = [t for t in t_in if (t.get("governing") or {}).get("osh_added")
                 and int(t.get("strands") or 0) < n_max]
        if prior and rest > 0:
            more = osh_raise_strands(prior, rest, params)
            if more:
                got += more
                rest -= more
                job.ok(f"        +{more} strand(s) on the {len(prior)} tendon(s) "
                       f"added earlier over this span - filled before another "
                       f"one is added.")
                if rest <= 0:
                    return got
        made = 0
        while rest > 0 and donor is not None and made < 2:
            n = min(n_max, max(n_min, rest))
            new = osh_clone_over_span(donor, dg, osh_live(tendons), params, site,
                                      n, extend, direction, tag=f"-{tag}{made + 1}")
            if new is None:
                break
            tendons.append(new)
            live = osh_live(tendons)
            made += 1
            done.add(wkey)
            rest -= int(new["strands"])
            job.ok(f"        new tendon over {label}"
                   + (" as one piece over both spans" if twins else "")
                   + f", {new['strands']} strand(s), offset {new['offset']:+.2f} m, "
                   f"extended {extend:.0f} m past the supports.")
        if made == 0:
            room = [t for t in t_in if int(t.get("strands") or 0) < n_max]
            extra = osh_raise_strands(room, rest, params) if room else 0
            if extra:
                job.ok(f"        no gap wide enough for a new tendon over "
                       f"{label}, so +{extra} strand(s) went onto the "
                       f"{len(room)} tendon(s) through the span instead.")
                return extra + got
            job.warn(f"        no gap wide enough for a new tendon over {label}"
                     f"{', and the tendons through it are at the strand limit' if t_in else ''}.")
        return made + got

    for key in sorted(fail_keys, key=lambda k: -state["spans"][k]["top"]):
        job.check()
        rec = state["spans"][key]
        d = rec["d"]
        rows = rec["rows"]["top"]
        if not rows:
            continue
        label = d.get("name") or str(key)
        t_in = osh_tendons_in_span(live, d, direction, half)
        st = stages.setdefault(key, {"step": "drop", "shift": 0, "adds": 0})
        if st.get("_covered") == stages.get("_round", 0):
            job.info(f"    span {d.get('name') or key} ({direction}, top): covered "
                     f"by the long tendon added with the span next to it.")
            st["adds"] = int(st.get("adds", 0)) + 1
            st["step"] = "add"
            continue
        worst = max(rows, key=lambda r: r["u"])
        if hist is not None:
            _n_now = sum(int(t.get("strands") or 0) for t in t_in)
            _prev = hist.get(key)
            hist[key] = {"u": worst["u"], "n": _n_now}
            if _prev is not None:
                hist[key]["_prev"] = _prev
        wxy = (worst["x"], worst["y"])
        near_a = dist(wxy, d["a"]) <= dist(wxy, d["b"])
        end_xy = d["a"] if near_a else d["b"]
        other_xy = d["b"] if near_a else d["a"]
        ends_failing = {("a" if dist((r["x"], r["y"]), d["a"])
                         <= dist((r["x"], r["y"]), d["b"]) else "b")
                        for r in rows if r["u"] > 1.0}
        bottom_u = rec["bottom"]
        job.info(f"    span {label} ({direction}, top): worst {worst['u']:.2f} "
                 f"of the limit at the {'a' if near_a else 'b'} end"
                 f"{' - both ends' if len(ends_failing) == 2 else ''}, "
                 f"mid-span bottom at {bottom_u:.2f}, {len(t_in)} tendon(s).")
        if not t_in:
            job.info("        no tendon passes through this span: one is "
                     "copied from the nearest tendon in this direction.")
            made = add_over(d, rows, t_in, label, "t", key=key)
            actions += made
            if not made:
                exhausted.append((label, "no tendon"))
                st["step"] = "done"
            continue

        #  18.114: الغطسة اللي اتحركت الجولة اللي فاتت بتتقاس هنا: لو
        #  القراءة ماتحسّنتش بترجع مكانها (نص البحر، في القاع).
        snap = st.pop("_shift_snap", None)
        if snap is not None:
            u0 = float(st.pop("_shift_u", worst["u"]))
            if worst["u"] > u0 - 0.02:
                for q, saved in snap:
                    q.clear()
                    q.update(saved)
                for t in t_in:
                    t.pop("_osh_lift_mm", None)
                st["shift"] = len(shifts)
                actions += 1
                job.warn(f"        the low points moved last round did not help "
                         f"this section ({u0:.2f} -> {worst['u']:.2f}): they go "
                         f"back to mid-span, at the bottom, and are not moved "
                         f"again.")
                if shift_mode == "last":
                    st["step"] = "done"
                    exhausted.append((label, "everything tried"))
                    continue
                st["step"] = "add"
            else:
                job.info(f"        the moved low points helped ({u0:.2f} -> "
                         f"{worst['u']:.2f}); they stay.")
        #  18.116: القمة اللي اتنقلت على الركيزة الجولة اللي فاتت بتتقاس:
        #  لو القراءة ساءت ترجع، وغير كده تفضل حتى لو القطاع لسه راسب -
        #  وبعدها الإضافة للبحر ده.
        psnap = st.pop("_peak_snap", None)
        if psnap is not None:
            u0 = float(st.pop("_peak_u", worst["u"]))
            if worst["u"] > u0 + 0.02:
                n_back = sum(osh_window_restore(t, sn) for t, sn in psnap)
                actions += 1 if n_back else 0
                job.warn(f"        the high points moved onto the support last "
                         f"round made this section worse ({u0:.2f} -> "
                         f"{worst['u']:.2f}): {n_back} point(s) put back.")
            elif worst["u"] < u0 - 0.02:
                job.ok(f"        the high points on the support helped ({u0:.2f} "
                       f"-> {worst['u']:.2f}); they stay, and what is still "
                       f"missing is added for this span.")
            else:
                job.info(f"        the high points on the support changed little "
                         f"({u0:.2f} -> {worst['u']:.2f}); they stay where a "
                         f"peak belongs.")
        step = st["step"]
        if step == "drop":
            st["step"] = "peaks"
            if osh_near_drop_edge(wxy, drops, edge_tol) is not None:
                res = [osh_add_drop_high(t, d, end_xy, site, params, direction)
                       for t in t_in]
                n_add = res.count("added")
                if n_add:
                    actions += n_add
                    job.ok(f"        the section sits at a drop-panel edge and "
                           f"no high point sat between the edge and the column: "
                           f"one added on {n_add} tendon(s), {'' if n_add == len(t_in) else f'{len(res) - n_add} had no room; '}re-analysing.")
                    continue
                if "exists" in res:
                    job.info("        at a drop-panel edge and a high point "
                             "already sits between the edge and the column: "
                             "tendons are added here.")
                    made = add_over(d, rows, t_in, label, "t", key=key)
                    actions += made
                    st["adds"] += 1 if made else 0
                    #  18.106: لو لسه راسب الجولة الجاية السلّم بيكمل -
                    #  القمة على الوش، الغطسة، وإضافة تانية.
                    continue
            step = "peaks"
        if step == "peaks":
            st["step"] = "ends"
            #  18.116: دايماً - مش بس لما النص عنده احتياطي. القمة على
            #  الركيزة والغطسة في نص البحر، وبعدين نقيس.
            n_mv = 0
            sides = [end_xy] + ([other_xy] if len(ends_failing) == 2 else [])
            whys = set()
            snaps = []
            for t in t_in:
                for exy in sides:
                    sn = osh_window_snapshot(t, d, exy)
                    n = osh_peak_to_face(t, d, exy, site, params, direction)
                    whys.add(t.get("_osh_face_why", "face"))
                    if n and sn is not None:
                        snaps.append((t, sn))
                    n_mv += n
                n_mv += osh_centre_low(t, d, params)
            if n_mv:
                actions += n_mv
                st["_peak_snap"] = snaps
                st["_peak_u"] = float(worst["u"])
                job.ok(f"        the high points sat off the support: {n_mv} "
                       f"point(s) moved onto "
                       + ("the design strip's end (the support; the tendons "
                          "do not run over a column footprint there)"
                          if "span end" in whys
                          else "the support face at the strip's end")
                       + f", the low point kept at mid-span"
                       + (f" (mid-span bottom at {bottom_u:.2f})" if bottom_u > big else "")
                       + "; re-analysing - kept unless the reading gets worse.")
                continue
            if "no support" in whys and len(whys) == 1:
                job.info("        this end of the strip is not on a "
                         "support (a cantilever or a free edge), so no "
                         "peak is put there.")
            else:
                job.info("        the high points already sit on the "
                         "support; strands or a tendon are added for this "
                         "span.")
            step = "ends"
        if step == "ends":
            if len(ends_failing) == 2:
                job.info("        both ends of the strip are over: a tendon is "
                         "added over the span.")
                made = add_over(d, rows, t_in, label, "t", key=key)
                actions += made
                st["step"] = "add"
                st["adds"] += 1 if made else 0
                if not made:
                    step = "shift" if shift_mode == "last" and shifts else "done"
                    st["step"] = step
                    if step == "done":
                        exhausted.append((label, "no room"))
                        continue
                else:
                    continue
            else:
                step = "shift" if shift_mode == "first" and shifts else "add"
                st["step"] = step

        def try_shift():
            """خطوة زحزحة واحدة؛ True لو حاجة اتحركت (نحلل)، وإلا False."""
            import copy
            i = int(st.get("shift", 0))
            if i >= len(shifts):
                return False
            frac = shifts[i]
            #  الصورة بتتاخد للنقط نفسها (الزحزحة بتعدّلها في مكانها)، مش
            #  للبروفايل كله: البحرين على نفس العامود بيشتركوا في الكابلات،
            #  ورجوع بروفايل كامل كان بيرجّع زحزحة البحر التاني معاه.
            snap = []
            for t in t_in:
                prof = t.get("profile") or []
                if len(prof) < 3:
                    continue
                sa, _ = _station_of(prof, d["a"])
                sb, _ = _station_of(prof, d["b"])
                lo_s, hi_s = sorted((sa, sb))
                for q, s_q in zip(prof, osh_stations(prof)):
                    if q.get("sag") and lo_s - 1e-6 <= s_q <= hi_s + 1e-6:
                        snap.append((q, dict(q)))
            n_mv = sum(osh_shift_lows(t, d, end_xy, frac, params) for t in t_in)
            lift = max([float(t.get("_osh_lift_mm") or 0.0) for t in t_in] or [0.0])
            st["shift"] = i + 1
            if n_mv:
                st["_shift_snap"] = snap
                st["_shift_u"] = float(worst["u"])
                job.ok(f"        one end over: {n_mv} low point(s) moved "
                       f"{100 * frac:.0f}% of the span toward it"
                       + (f", raised up to {lift:.0f} mm to keep the "
                          f"minimum radius" if lift > 0 else "")
                       + "; re-analysing - put back if the reading does not "
                       "improve.")
                return True
            job.info("        no low point could move: none inside the "
                     "span, or the move would put it above the peak "
                     "beside it.")
            st["shift"] = len(shifts)
            return False

        if step == "shift" and shift_mode == "first":
            if try_shift():
                actions += 1
                continue
            st["step"] = "add"
            step = "add"
        if step == "add":
            if int(st.get("adds", 0)) >= 3:
                exhausted.append((label, "three additions"))
                step = "shift" if shift_mode == "last" and shifts else "done"
                st["step"] = step
                if step == "done":
                    continue
            else:
                job.info("        still over: a tendon is added over the span"
                         + (" (sized on what the last one did)" if st.get("adds")
                            else "") + ".")
                made = add_over(d, rows, t_in, label, "t", key=key)
                actions += made
                if made:
                    st["adds"] += 1
                    continue
                step = "shift" if shift_mode == "last" and shifts else "done"
                st["step"] = step
                if step == "done":
                    exhausted.append((label, "no room"))
                    continue
        if step == "shift" and shift_mode == "last":
            if int(st.get("shift", 0)) == 0:
                job.info("        nothing more can be added here, so as a last "
                         "resort the low points move toward the failing end.")
            if try_shift():
                actions += 1
                continue
            st["step"] = "done"
            exhausted.append((label, "everything tried"))
            continue
        if step == "done":
            exhausted.append((label, "everything tried"))
    return actions, exhausted


# ---------------------------------------------------------------------------
#  المرحلة 3 - التحسين
# ---------------------------------------------------------------------------

def osh_lanes(live, direction, tol):
    ts = sorted([t for t in live if osh_tendon_dir(t) == direction],
                key=lambda t: osh_across(t, direction))
    lanes, cur = [], []
    for t in ts:
        if cur and osh_across(t, direction) - osh_across(cur[0], direction) > tol:
            lanes.append(cur)
            cur = []
        cur.append(t)
    if cur:
        lanes.append(cur)
    return lanes


def osh_size_up(n, params):
    """أقرب مقاس متاح من فوق لو فيه قايمة مقاسات، وإلا العدد زي ما هو."""
    sizes = sorted(int(x) for x in (getattr(params, "allowed_strands", None) or [])
                   if int(x) > 0)
    n = int(n)
    if not sizes:
        return n
    for x in sizes:
        if x >= n:
            return x
    return sizes[-1]


def osh_reduce_step(state, tendons, params, site, job, direction):
    """
    **18.116: التخفيف استرند استرند، مقيس.** كل كابل في الاتجاه ده أسوأ
    شريحة بيقطعها بتحدد اللي محتاجه عند الحد المستهدف؛ لو أقل من اللي
    شايله بينزل **مقاس واحد** بس الجولة دي (على قايمة المقاسات لو فيه)،
    والجولة الجاية بتقيس. الكابل اللي اتجمّد (رجع بعد ما كسر قطاع)
    مابيتلمسش. بترجّع (اتخفف, عدد الكابلات).
    """
    live = osh_live(tendons)
    half = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    near = float(getattr(params, "osh_margin_near", 0.90) or 0.90)
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    spans = state["ram_spans"]
    removed, count = 0, 0
    for t in live:
        if osh_tendon_dir(t) != direction or t.get("_osh_frozen"):
            continue
        n = int(t.get("strands") or 0)
        if n <= n_min:
            continue
        keys = [k for k in osh_spans_of_tendon(t, spans, direction, half)
                if k in state["spans"]]
        if not keys:
            continue
        u_max = max(max(state["spans"][k]["top"], state["spans"][k]["bottom"])
                    for k in keys)
        if u_max <= 0:
            continue
        want = max(n_min, int(math.ceil(n * u_max / near - 1e-9)))
        if want >= n:
            continue
        new_n = max(n_min, osh_size_down(n, params))
        if new_n >= n:
            continue
        t["strands"] = new_n
        t["_osh_last_cut"] = n - new_n
        t["_osh_reduced_by"] = int(t.get("_osh_reduced_by") or 0) + (n - new_n)
        t.setdefault("governing", {})["osh_reduced"] = t["_osh_reduced_by"]
        removed += n - new_n
        count += 1
    if count:
        job.ok(f"    {count} tendon(s) ({direction}) carry more than their worst "
               f"strip needs at {near:.2f}: {removed} strand(s) taken off, one "
               f"size per tendon this round; the next analysis measures it.")
    return removed, count


def osh_reduce_solo(state, tendons, params, site, job, direction):
    """
    **18.112: الكابل اللي كل شرايحه عندها احتياطي كبير بيتخفف.** رن
    المهندس طلّع كابلات خمسات على طول الدور وكل قطاعاتها تحت 0.70،
    وقاعدة المجموعات ماكانتش بتلمسها لأنها بتدوّر على "بحر واحد على
    الحد". هنا كل كابل بيتقاس لوحده: أسوأ شريحة بيقطعها بتحدد اللي
    محتاجه، ولو كلها تحت الهامش الكبير بينزل لقد ما الأسوأ فيها
    محتاجة عند الحد المستهدف. بترجّع (اتخفف, عدد الكابلات).
    """
    live = osh_live(tendons)
    half = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    big = float(getattr(params, "osh_margin_big", 0.70) or 0.70)
    near = float(getattr(params, "osh_margin_near", 0.90) or 0.90)
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    spans = state["ram_spans"]
    removed, count = 0, 0
    for t in live:
        if osh_tendon_dir(t) != direction:
            continue
        n = int(t.get("strands") or 0)
        if n <= n_min:
            continue
        keys = [k for k in osh_spans_of_tendon(t, spans, direction, half)
                if k in state["spans"]]
        if len(keys) < 2:
            continue
        u_max = max(max(state["spans"][k]["top"], state["spans"][k]["bottom"])
                    for k in keys)
        if u_max > big or u_max <= 0:
            continue
        new_n = osh_size_up(max(n_min, int(math.ceil(n * u_max / near - 1e-9))),
                            params)
        if new_n >= n:
            continue
        t["strands"] = new_n
        t["_osh_reduced_by"] = n - new_n
        t.setdefault("governing", {})["osh_reduced"] = n - new_n
        removed += n - new_n
        count += 1
    if count:
        job.ok(f"    {count} tendon(s) ({direction}) run only through strips "
               f"under {big:.2f} of the limit: {removed} strand(s) taken off "
               f"them, each cut to what its worst strip needs at {near:.2f}.")
    return removed, count


def osh_reduce_groups(state, tendons, params, site, job, direction, budget):
    """
    المجموعة اللي معظم شرايحها عندها احتياطي كبير وبحر واحد (أو اتنين)
    على الحد: استرنداتها بتتخفف لقد ما الشرايح الآمنة محتاجة، والبحر
    اللي على الحد بياخد كابل بعدد اللي اتخفف. بترجّع (اتخفف, اتضاف).
    """
    live = osh_live(tendons)
    half = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    big = float(getattr(params, "osh_margin_big", 0.70) or 0.70)
    near = float(getattr(params, "osh_margin_near", 0.90) or 0.90)
    extend = float(getattr(params, "osh_extend_m", 3.0) or 3.0)
    tol = max(float(getattr(params, "max_spacing", 1.5) or 1.5), 1.0)
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    n_max = max(1, int(getattr(params, "max_strands", 5) or 5))
    spans = state["ram_spans"]
    removed_all, added_all = 0, 0
    for lane in osh_lanes(live, direction, tol):
        if len(lane) < 2:
            continue
        job.check()
        keys = set()
        for t in lane:
            keys.update(osh_spans_of_tendon(t, spans, direction, half))
        keys = [k for k in keys if k in state["spans"]]
        if len(keys) < 3:
            continue
        u_of = {k: max(state["spans"][k]["top"], state["spans"][k]["bottom"])
                for k in keys}
        big_k = [k for k in keys if u_of[k] <= big]
        near_k = [k for k in keys if u_of[k] >= near]
        if len(big_k) * 3 < len(keys) * 2 or not (1 <= len(near_k) <= 2):
            continue
        u_ref = max([u_of[k] for k in keys if k not in near_k] or [big])
        removed = 0
        plan = []
        for t in lane:
            n = int(t.get("strands") or 0)
            new_n = max(n_min, int(math.ceil(n * u_ref / near - 1e-9)))
            if new_n < n:
                plan.append((t, n, new_n))
                removed += n - new_n
        if removed <= 0:
            continue
        names = ", ".join(state["spans"][k]["d"].get("name") or "?" for k in near_k)
        job.info(f"    group of {len(lane)} tendons ({direction}, across "
                 f"{osh_across(lane[0], direction):.1f}..{osh_across(lane[-1], direction):.1f} m): "
                 f"{len(big_k)} of {len(keys)} strips under {big:.2f}, "
                 f"{len(near_k)} at or near the limit ({names}).")
        for t, n, new_n in plan:
            t["strands"] = new_n
            t.setdefault("governing", {})["osh_reduced"] = n - new_n
        job.ok(f"        {removed} strand(s) taken off the group (to what the "
               f"safest strips need at {u_ref:.2f} -> {near:.2f}).")
        removed_all += removed
        share = int(math.ceil(removed / len(near_k)))
        for k in near_k:
            d = state["spans"][k]["d"]
            t_in = osh_tendons_in_span(osh_live(tendons), d, direction, half)
            donor = osh_band_donor(t_in, d, direction) or lane[0]
            rest, made = share, 0
            while rest > 0 and made < 3:
                n = min(n_max, max(n_min, rest))
                new = osh_clone_over_span(donor, d, osh_live(tendons), params,
                                          site, n, extend, direction,
                                          tag=f"-o{made + 1}")
                if new is None:
                    break
                tendons.append(new)
                made += 1
                rest -= int(new["strands"])
                added_all += int(new["strands"])
                job.ok(f"        new tendon over {d.get('name') or '?'} with "
                       f"{new['strands']} strand(s) - the strands the group "
                       f"gave up, put where the limit is.")
            if made == 0:
                job.warn(f"        no room for a tendon over "
                         f"{d.get('name') or '?'}; the reduction there is "
                         f"undone.")
                for t, n, new_n in plan:
                    t["strands"] = n
                removed_all -= removed
                break
    return removed_all, added_all


def osh_join_inline(tendons, params, site, job, direction):
    """
    كابلان وراء بعض على نفس المحور وبينهم فجوة لحد `osh_merge_gap_m`
    بيتوصلوا: الفجوة بتاخد نقاط الكابل الموازي المجاور (نفس البروفايل)،
    وإلا قمة لو فيه ركيزة في الفجوة وإلا غطسة. بترجّع عدد الوصلات.
    """
    live = osh_live(tendons)
    across_tol = float(getattr(params, "osh_merge_across", 0.25) or 0.25)
    gap_max = float(getattr(params, "osh_merge_gap_m", 3.0) or 3.0)
    gap_pt = max(0.5, float(getattr(params, "min_point_gap", 0.5) or 0.5))
    h = float(getattr(params, "slab_thickness", 260.0) or 260.0)
    polys = osh_support_polys(site)
    joined = 0

    def ordered(t):
        pr = list(t.get("profile") or [])
        if len(pr) >= 2 and osh_along(pr[-1]["pos"], direction) < osh_along(
                pr[0]["pos"], direction):
            pr.reverse()
        return pr

    changed = True
    while changed:
        changed = False
        live = osh_live(tendons)
        ts = [t for t in live if osh_tendon_dir(t) == direction]
        ts.sort(key=lambda t: osh_along(ordered(t)[0]["pos"], direction))
        for i, t1 in enumerate(ts):
            p1 = ordered(t1)
            if len(p1) < 2:
                continue
            e1 = osh_along(p1[-1]["pos"], direction)
            for t2 in ts[i + 1:]:
                if t2 is t1 or t2.get("_deleted") or t1.get("_deleted"):
                    continue
                p2 = ordered(t2)
                if len(p2) < 2:
                    continue
                if abs(osh_across(t1, direction) - osh_across(t2, direction)) > across_tol:
                    continue
                s2 = osh_along(p2[0]["pos"], direction)
                g = s2 - e1
                if g < 0.0 or g > gap_max:
                    continue
                here = osh_across(t1, direction)
                nx, ny = (0.0, 1.0) if direction == "X" else (1.0, 0.0)
                fill = []
                others = [x for x in live if x is not t1 and x is not t2
                          and osh_tendon_dir(x) == direction]
                dmin, nb = nearest_parallel(t1, others)
                if nb is not None:
                    for q in (nb.get("profile") or [])[1:-1]:
                        a = osh_along(q["pos"], direction)
                        if e1 + gap_pt < a < s2 - gap_pt and (q.get("high") or q.get("sag")):
                            c = {k: v for k, v in q.items() if not str(k).startswith("_")}
                            off = here - osh_across_pt(q["pos"], direction)
                            c["pos"] = (q["pos"][0] + nx * off, q["pos"][1] + ny * off)
                            c["manual"] = True
                            fill.append(c)
                if not fill and g > 2.0 * gap_pt:
                    mx = ((p1[-1]["pos"][0] + p2[0]["pos"][0]) / 2.0,
                          (p1[-1]["pos"][1] + p2[0]["pos"][1]) / 2.0)
                    on = any(point_in_polygon(mx[0], mx[1], p) for p in polys)
                    fill.append({"pos": mx, "manual": True,
                                 "high": on, "sag": not on,
                                 "depth": (osh_top_depth(t1, params, direction) if on
                                           else h - float(params.covers_for(direction)[1])),
                                 "src": "osh_join"})
                new_prof = p1[:-1] + fill + p2[1:]
                if not osh_route_is_clear([p1[-2] if len(p1) > 1 else p1[-1]]
                                          + fill + [p2[1] if len(p2) > 1 else p2[0]],
                                          site,
                                          float(getattr(params, "efm_added_clear",
                                                        0.25) or 0.25)):
                    continue
                t1["profile"] = new_prof
                t1["strands"] = max(int(t1.get("strands") or 0),
                                    int(t2.get("strands") or 0))
                t1["length"] = tendon_plan_length(t1)
                t1.setdefault("governing", {})["osh_joined"] = True
                t1["manual"] = True
                t2["_deleted"] = True
                t2["_merged_into"] = t1
                joined += 1
                changed = True
                job.ok(f"    joined two tendons in line ({direction}, across "
                       f"{here:.1f} m, gap {g:.1f} m) with "
                       f"{len(fill)} point(s) copied from the neighbour.")
                break
            if changed:
                break
    return joined


def osh_remove_short_runs(tendons, params, site, job, direction):
    """
    محور فيه كابلات قصيرة مجموع طولها أكتر من `osh_axis_short_pct` من
    طوله: بتتلغي واسترنداتها بتروح للكابلات المجاورة، ولو الجيران عند
    الحد بتتجمع في كابل طويل واحد. بترجّع (اتلغى, اتضاف).
    """
    live = osh_live(tendons)
    pct = float(getattr(params, "osh_axis_short_pct", 70.0) or 70.0) / 100.0
    across_tol = float(getattr(params, "osh_merge_across", 0.25) or 0.25)
    n_max = max(1, int(getattr(params, "max_strands", 5) or 5))
    gone, made = 0, 0
    for axis in osh_lanes(live, direction, across_tol):
        job.check()
        others = [t for t in osh_live(tendons)
                  if t not in axis and osh_tendon_dir(t) == direction]
        neigh = []
        for t in axis:
            _d, nb = nearest_parallel(t, others)
            if nb is not None and nb not in neigh:
                neigh.append(nb)
        axis_len = max([tendon_plan_length(t) for t in axis]
                       + [tendon_plan_length(n) for n in neigh])
        if axis_len <= 0:
            continue
        shorts = [t for t in axis if tendon_plan_length(t) < 0.6 * axis_len]
        if not shorts:
            continue
        #  التغطية = اتحاد الامتدادات على المحور، مش مجموع الأطوال - قطعتين
        #  فوق بعض كانوا بيطلعوا "117% من المحور".
        spans_along = sorted(
            (min(osh_along(q["pos"], direction) for q in t["profile"]),
             max(osh_along(q["pos"], direction) for q in t["profile"]))
            for t in shorts if len(t.get("profile") or []) >= 2)
        cover, cur = 0.0, None
        for lo, hi in spans_along:
            if cur is None or lo > cur[1]:
                if cur is not None:
                    cover += cur[1] - cur[0]
                cur = [lo, hi]
            else:
                cur[1] = max(cur[1], hi)
        if cur is not None:
            cover += cur[1] - cur[0]
        if cover <= pct * axis_len:
            continue
        total = sum(int(t.get("strands") or 0) for t in shorts)
        room = [(n, n_max - int(n.get("strands") or 0)) for n in neigh
                if int(n.get("strands") or 0) < n_max]
        have = sum(r for _n, r in room)
        job.info(f"    axis at {osh_across(axis[0], direction):.1f} m "
                 f"({direction}): {len(shorts)} short tendon(s) cover "
                 f"{100 * cover / axis_len:.0f}% of its {axis_len:.0f} m, "
                 f"{total} strand(s) between them.")
        if have >= total:
            left = total
            for n, r in sorted(room, key=lambda x: -x[1]):
                take = min(r, left)
                if take <= 0:
                    continue
                n["strands"] = int(n.get("strands") or 0) + take
                n.setdefault("governing", {})["osh_gift"] = take
                left -= take
                if left <= 0:
                    break
            for t in shorts:
                t["_deleted"] = True
                t["_osh_removed"] = True
                gone += 1
            job.ok(f"        removed; their {total} strand(s) went onto "
                   f"{len([1 for _n, r in room if r > 0])} neighbouring tendon(s).")
            continue
        donor = max(neigh, key=lambda n: tendon_plan_length(n)) if neigh else None
        if donor is None:
            job.info("        no neighbour to take the strands and none to copy "
                     "- left as is.")
            continue
        for t in shorts:
            t["_deleted"] = True
            t["_osh_removed"] = True
        new = osh_clone_full(donor, osh_across(axis[0], direction), direction,
                             min(n_max, total), params, osh_live(tendons),
                             name=f"OSH long {direction}", site=site)
        if new is None:
            for t in shorts:
                t["_deleted"] = False
                t.pop("_osh_removed", None)
            job.warn("        no room for one long tendon in their place - "
                     "left as is.")
            continue
        tendons.append(new)
        gone += len(shorts)
        made += 1
        left = total - int(new["strands"])
        for n, r in sorted(room, key=lambda x: -x[1]):
            take = min(r, left)
            if take <= 0:
                break
            n["strands"] = int(n.get("strands") or 0) + take
            left -= take
        job.ok(f"        the neighbours are at the strand limit: one long "
               f"tendon from end to end with {new['strands']} strand(s) "
               f"replaces them.")
    return gone, made


