#  المسار كله
# ---------------------------------------------------------------------------

def osh_direction_order(params, state, site):
    want = str(getattr(params, "osh_dir_order", "longer") or "longer").lower()
    if want in ("x", "y"):
        first = want.upper()
        return [first, "Y" if first == "X" else "X"]
    lens = {"X": [], "Y": []}
    for _k, d in (state.get("ram_spans") or {}).items():
        dd = "X" if _span_in_direction(d["a"], d["b"], "x") else "Y"
        lens[dd].append(float(d.get("length") or dist(d["a"], d["b"])))
    if not lens["X"] and not lens["Y"]:
        try:
            g = grid_spans(site)
            lens = {"X": list(g.get("x") or []), "Y": list(g.get("y") or [])}
        except Exception:
            pass
    mx = (sum(lens["X"]) / len(lens["X"])) if lens["X"] else 0.0
    my = (sum(lens["Y"]) / len(lens["Y"])) if lens["Y"] else 0.0
    return ["X", "Y"] if mx >= my else ["Y", "X"]


def osh_new_failures(before, after):
    """(البحر, الوش) اللي كان مسيف قبل وبقى راسب بعد."""
    return sorted(k for k in after["fail"] if k not in before["fail"])


def run_optimum_h(session, tendons, params, job, out_dir, stem, site=None,
                  mesh_size=None, base_kg=None):
    """
    Optimum solution H على موديل مفتوح في الجلسة وكابلاته في `tendons`.

    بترجّع {"best": المسار, "safe": مسار نسخة نهاية المرحلة 2,
    "before"/"after": ملخصات, "put_back": bool, "stopped": str}.
    """
    rounds_max = max(1, int(getattr(params, "osh_rounds", 6) or 6))
    extend = float(getattr(params, "osh_extend_m", 3.0) or 3.0)
    n_min = max(1, int(getattr(params, "min_strands", 2) or 2))
    result = {"best": None, "safe": None, "put_back": False, "stopped": ""}

    job.log("Optimum solution H", "head")
    job.info(f"Three stages: bottom sections, then top sections, then the "
             f"optimisation. Up to {rounds_max} analyses per stage. New "
             f"tendons cover one span and run {extend:.0f} m past its "
             f"supports; strands are sized by "
             f"{'what a strand measured to relieve' if getattr(params, 'osh_sizing', 'ratio') == 'measured' else 'the stress-to-limit ratio'}.")

    # ---------------- المرحلة 0
    start = str(getattr(params, "osh_start", "keep") or "keep")
    if start == "reduce":
        n_before = sum(int(t.get("strands") or 0) for t in osh_live(tendons))
        for t in osh_live(tendons):
            if int(t.get("strands") or 0) > n_min:
                t["strands"] = n_min
                t.setdefault("governing", {})["osh_reduced_start"] = True
        n_after = sum(int(t.get("strands") or 0) for t in osh_live(tendons))
        job.ok(f"Every tendon reduced to {n_min} strand(s) to start from "
               f"({n_before} -> {n_after} strands, hand-drawn ones included).")
    state = osh_cycle(session, tendons, params, site, mesh_size, job, out_dir,
                      stem, "start")
    before = state
    result["before"] = state["summary"]
    result["before_state"] = state
    budget = osh_budget_total(params, site, base_kg if base_kg is not None
                              else state["kg"])
    if budget is not None:
        job.info(f"    strand budget: {budget:,.0f} kg in all "
                 f"({osh_budget_left(tendons, params, budget):,.0f} kg left).")
    order = osh_direction_order(params, state, site)
    job.info(f"    direction order: {order[0]} then {order[1]}.")

    def over_count(st, face):
        return sum(1 for r in st["readings"] if r["face"] == face and r["u"] > 1.0)

    # ---------------- المرحلة 1
    hist_b, hist_t = {}, {}
    stages_b = {}
    if over_count(state, "bottom") == 0:
        job.ok("Stage 1: no bottom section is over the limit.")
    for rnd in range(1, rounds_max + 1):
        if over_count(state, "bottom") == 0:
            break
        job.log(f"Stage 1 - bottom sections, round {rnd}", "head")
        did = 0
        for direction in order:
            s_add, t_add, treated, stuck = osh_bottom_round(
                state, tendons, params, site, job, direction, budget,
                hist=hist_b, stages=stages_b)
            did += s_add + t_add + sum(1 for _l, why in stuck if why == "geometry")
        if did == 0:
            job.warn("Nothing more can be added for the bottom sections "
                     "(strand limit, no room, or budget). Moving on.")
            break
        state = osh_cycle(session, tendons, params, site, mesh_size, job,
                          out_dir, stem, f"bottom_r{rnd}")
        job.info(f"    bottom readings over the limit: "
                 f"{over_count(before, 'bottom')} at the start -> "
                 f"{over_count(state, 'bottom')} now.")

    # ---------------- المرحلة 2
    stages = {}
    if over_count(state, "top") == 0:
        job.ok("Stage 2: no top section is over the limit.")
    for rnd in range(1, rounds_max + 1):
        if over_count(state, "top") == 0:
            break
        job.log(f"Stage 2 - top sections, round {rnd}", "head")
        did = 0
        stages["_round"] = rnd
        for direction in order:
            acts, exhausted = osh_top_round(state, tendons, params, site, job,
                                            direction, budget, stages,
                                            hist=hist_t)
            did += acts
        if did == 0:
            job.warn("Every top section still over the limit has had every "
                     "step tried (drop-edge high point, peak on the support "
                     "face, strands and a tendon added"
                     + (", low points moved" if getattr(params, "osh_low_shift", "never") != "never" else "")
                     + "). Moving on.")
            break
        state = osh_cycle(session, tendons, params, site, mesh_size, job,
                          out_dir, stem, f"top_r{rnd}")
        job.info(f"    top readings over the limit: {over_count(before, 'top')} "
                 f"at the start -> {over_count(state, 'top')} now.")

    safe_path = osh_path(out_dir, stem, "safe")
    if safe_save(session, safe_path, job):
        result["safe"] = safe_path
    result["best"] = result["safe"] or state.get("path")
    safe_state = state
    job.ok(f"End of the making-safe stages: {state['n_over']} reading(s) over "
           f"the limit, {state['summary']['strands']} strands, "
           f"{state['kg']:,.0f} kg. Saved as {os.path.basename(safe_path)}.")

    # ---------------- المرحلة 3
    if not bool(getattr(params, "osh_optimise", True)):
        result["stopped"] = "optimisation off"
        result["after"] = state["summary"]
        return result
    job.log("Stage 3 - optimisation", "head")
    #  **18.116: استرند استرند، ومافيش كابل جديد في التحسين.** رن المهندس
    #  (18.115) خفّف 23 استرند من 14 كابل في Y دفعة واحدة، كسر 9 قطاعات
    #  علوية، حاول يصلّحها بـ 9 كابلات جديدة، وطلع أسوأ فاتلغى كله -
    #  والخمسات فضلت خمسات. دلوقتي كل جولة بتنزّل مقاس واحد من كل كابل
    #  عنده احتياطي، بتحلل، واللي كسر قطاع بيرجع ويتجمّد؛ الباقي بيكمل.
    half_ = float(getattr(params, "osh_strip_half", 3.0) or 3.0)
    for direction in order:
        job.check()
        job.info(f"Direction {direction}:")
        snap_dir = osh_snapshot(tendons)
        ref = state
        for t in osh_live(tendons):
            t.pop("_osh_reduced_by", None)
            t.pop("_osh_frozen", None)
        joined = osh_join_inline(tendons, params, site, job, direction)
        gone, made = osh_remove_short_runs(tendons, params, site, job, direction)
        if joined or gone or made:
            state = osh_cycle(session, tendons, params, site, mesh_size, job,
                              out_dir, stem, f"opt_{direction}_join")
            if osh_new_failures(ref, state) or state["n_over"] > ref["n_over"]:
                job.warn(f"    joining / replacing tendons in {direction} broke "
                         f"a section, so it is undone.")
                osh_restore(tendons, snap_dir)
                state = osh_cycle(session, tendons, params, site, mesh_size, job,
                                  out_dir, stem, f"opt_{direction}_join_undone")
            else:
                ref = state
                snap_dir = osh_snapshot(tendons)
        touched = False
        for opt_round in range(1, rounds_max + 1):
            job.check()
            for t in osh_live(tendons):
                t.pop("_osh_last_cut", None)
            removed, count = osh_reduce_step(state, tendons, params, site, job,
                                             direction)
            if not count:
                if opt_round == 1:
                    job.info(f"    nothing left to take off in {direction}.")
                break
            touched = True
            snap_round = osh_snapshot(tendons)
            ref_round = state
            state = osh_cycle(session, tendons, params, site, mesh_size, job,
                              out_dir, stem, f"opt_{direction}_r{opt_round}")
            new_bad = osh_new_failures(ref, state)
            if new_bad:
                names = ", ".join(f"{state['spans'][k]['d'].get('name') or '?'}/{f}"
                                  for k, f in new_bad if k in state["spans"])
                back, orphan = 0, 0
                for k, f in new_bad:
                    if k not in state["spans"]:
                        continue
                    d = state["spans"][k]["d"]
                    dd = state["spans"][k]["dir"]
                    here = 0
                    for t in osh_tendons_in_span(osh_live(tendons), d, dd, half_):
                        r = int(t.get("_osh_last_cut") or 0)
                        if r > 0:
                            t["strands"] = int(t.get("strands") or 0) + r
                            t["_osh_reduced_by"] = int(t.get("_osh_reduced_by") or 0) - r
                            t["_osh_last_cut"] = 0
                            t["_osh_frozen"] = True
                            here += r
                    back += here
                    if not here:
                        orphan += 1
                if orphan:
                    job.warn(f"    {len(new_bad)} section(s) that were safe are "
                             f"over the limit now ({names}), and for {orphan} "
                             f"of them no tendon through the span was cut this "
                             f"round: the whole round is undone.")
                    osh_restore(tendons, snap_round)
                    for t in osh_live(tendons):
                        if int(t.get("_osh_last_cut") or 0) > 0:
                            t["strands"] = int(t.get("strands") or 0) + int(t["_osh_last_cut"])
                            t["_osh_reduced_by"] = int(t.get("_osh_reduced_by") or 0) - int(t["_osh_last_cut"])
                            t["_osh_last_cut"] = 0
                            t["_osh_frozen"] = True
                    state = osh_cycle(session, tendons, params, site, mesh_size, job,
                                      out_dir, stem, f"opt_{direction}_r{opt_round}_undone")
                    break
                job.warn(f"    {len(new_bad)} section(s) that were safe are over "
                         f"the limit now ({names}): {back} strand(s) put back on "
                         f"the tendons cut through them, and those tendons are "
                         f"not touched again; re-analysing.")
                state = osh_cycle(session, tendons, params, site, mesh_size, job,
                                  out_dir, stem, f"opt_{direction}_r{opt_round}_back")
                if osh_new_failures(ref, state) or state["n_over"] > ref["n_over"]:
                    job.warn(f"    still over after the put-back: the whole round "
                             f"is undone.")
                    osh_restore(tendons, snap_round)
                    for t in osh_live(tendons):
                        if int(t.get("_osh_last_cut") or 0) > 0:
                            t["strands"] = int(t.get("strands") or 0) + int(t["_osh_last_cut"])
                            t["_osh_reduced_by"] = int(t.get("_osh_reduced_by") or 0) - int(t["_osh_last_cut"])
                            t["_osh_last_cut"] = 0
                            t["_osh_frozen"] = True
                    state = osh_cycle(session, tendons, params, site, mesh_size, job,
                                      out_dir, stem, f"opt_{direction}_r{opt_round}_undone")
                    break
            elif state["n_over"] > ref_round["n_over"]:
                job.warn(f"    round {opt_round} left more readings over the limit "
                         f"({ref_round['n_over']} -> {state['n_over']}), so it is "
                         f"undone.")
                osh_restore(tendons, snap_round)
                state = osh_cycle(session, tendons, params, site, mesh_size, job,
                                  out_dir, stem, f"opt_{direction}_r{opt_round}_undone")
                break
            job.ok(f"    round {opt_round}: {ref_round['summary']['strands']} -> "
                   f"{state['summary']['strands']} strands, {state['n_over']} "
                   f"reading(s) over.")
        if state["n_over"] > ref["n_over"] or osh_new_failures(ref, state):
            job.warn(f"    the optimisation in {direction} left {state['n_over']} "
                     f"reading(s) over the limit against {ref['n_over']} before "
                     f"it, so it is undone.")
            osh_restore(tendons, snap_dir)
            state = osh_cycle(session, tendons, params, site, mesh_size, job,
                              out_dir, stem, f"opt_{direction}_undone")
        elif touched or joined or gone or made:
            job.ok(f"    {direction} optimised: {ref['summary']['strands']} -> "
                   f"{state['summary']['strands']} strands, "
                   f"{ref['kg']:,.0f} -> {state['kg']:,.0f} kg, "
                   f"{ref['n_over']} -> {state['n_over']} reading(s) over.")

    final_path = osh_path(out_dir, stem, "final")
    if safe_save(session, final_path, job):
        result["best"] = final_path
    result["after"] = state["summary"]
    result["after_state"] = state
    if state["n_over"] > safe_state["n_over"]:
        job.flag(f"The optimised model has {state['n_over']} reading(s) over "
                 f"the limit against {safe_state['n_over']} at the end of "
                 f"stage 2, so the stage-2 file is the one handed back.")
        result["best"] = result["safe"] or result["best"]
        result["put_back"] = True

    # ---------------- التقرير
    b, a = before, state
    job.log("Optimum solution H - before and after", "head")
    job.info(f"    tendons:      {b['summary']['tendons']} -> {a['summary']['tendons']}")
    job.info(f"    strands:      {b['summary']['strands']} -> {a['summary']['strands']}")
    job.info(f"    strand-m:     {b['summary']['strand_m']:,.0f} -> {a['summary']['strand_m']:,.0f}")
    job.info(f"    strand steel: {b['kg']:,.0f} kg -> {a['kg']:,.0f} kg")
    fo_b, fo_a = osh_faces_over(b), osh_faces_over(a)
    for key in sorted(set(fo_b) | set(fo_a)):
        job.info(f"    over the limit, {key[0]} {key[1]}: "
                 f"{fo_b.get(key, 0)} -> {fo_a.get(key, 0)}")
    job.info(f"    readings over the limit in all: {b['n_over']} -> {a['n_over']}")
    if a["n_over"]:
        job.flag(f"{a['n_over']} reading(s) are still over the limit: the "
                 f"tendons through them reached the strand limit or there was "
                 f"no room for another. Those are for depth, a drop, or "
                 f"reinforcement.")
    result["stopped"] = "finished"
    return result


def run_shave_loop(session, tendons, params, job, out_dir, stem, site=None,
                   mesh_size=None, plots=None):
    """
    **دور التخفيف** (17.93): ابدأ من تخطيط عدّى، شيل مقاس من الكابلات
    اللي حواليها هامش (shave_fraction من المرشحين في الدور، الأوسع
    هامشاً الأول)، ارسم وحلّل واقرا فحص القطاعات من رام. لو قطاع جديد
    رسب: الكابلات اللي اتخفّفت في متناول shave_reach منه بترجع لمقاسها
    وبتتجمّد لباقي الرن، ولو مافيش كابل يتلام الدور كله بيرجع. الدور
    بيقف لما مايبقاش فيه مرشح أو لما دورين ورا بعض مايكسبوش حاجة.

    بترجّع {rounds, best, removed, strands, reach, stopped}.
    """
    rounds_max = int(getattr(params, "shave_rounds", 6) or 0)
    frac = float(getattr(params, "shave_fraction", 0.25) or 0.25)
    half = float(getattr(params, "shave_reach", 1.5) or 1.5)
    result = {"rounds": [], "best": None, "removed": 0, "stopped": "off"}
    if rounds_max <= 0 or not tendons:
        return result

    def live():
        return [t for t in tendons if not t.get("_deleted")]

    def draw_and_read(label):
        clear_tendons_in_ram(session, job)
        write_tendons_to_ram(session, live(), job, params,
                             drops=(site or {}).get("drops"), site=site)
        if bool(getattr(params, "place_jacks", True)):
            try:
                write_jacks_to_ram(session, live(), job, params)
            except Exception as e:
                job.warn(f"Jacks were not placed: {e}")
        res = run_model_analysis(session, job, mesh_size)
        if not res.get("ok"):
            raise RuntimeError("RAM did not finish the analysis")
        pl = read_section_plots_from_ram(session, params, job)
        return pl, md_summary(label, live(), pl, params)

    job.log("Shaving: taking strands out where the sections have room", "head")
    if plots is None:
        plots, s0 = draw_and_read("before shaving")
    else:
        s0 = md_summary("before shaving", live(), plots, params)
    base_reach = int(s0["reach"])
    #  17.99: الحكم على مجموع القطاعات الراسبة (قابلة + خارج المتناول):
    #  شيل استراندات بيغيّر تصنيف القطاع بين الاتنين من غير ما يرسب قطاع
    #  جديد، وكان بيطلع إنذار كاذب "8 بدل 7" ومافيش مين يتلام.
    base_total = int(s0["reach"]) + int(s0["unreach"])
    #  17.99: نفس القطاع = نفس النقطة (5 سم). 0.5 م كانت بتخلّي القطاع
    #  اللي جنب قطاع راسب أصلاً يرسب من غير ما يتحسب "جديد"، والعدّ
    #  يزيد والدور مايلاقيش مين يلومه.
    base_fails = [(x, y) for pl in plots for x, y, v, l in pl.failing()]
    job.info(f"Start: {s0['strands']} strands, {s0['strand_m']:,.0f} strand-m, "
             f"{base_reach} section(s) over the limit. A tendon is a candidate "
             f"when no failing section lies within {half:.1f} m of it and the "
             f"tightest margin on its path covers the estimated loss plus "
             f"{float(getattr(params, 'shave_margin', 0.30) or 0.0):.2f} MPa.")
    utilisation_report(live(), plots, params, job, half)
    if bool(getattr(params, "shave_strip_reserve", True)):
        try:
            strip_reserve_report(plots, params, job)
        except Exception as e:
            job.warn(f"The strip reserve table could not be worked out ({e}).")

    #  **18.27: التقشير بيشتغل على سقف عدّى، مش على سقف لسه راسب.**
    #
    #  أول سطر في وصف الدور بيقول "ابدأ من تخطيط عدّى" - وماكانش فيه حاجة
    #  بتتأكد. على رن المهندس 21:56 حلقة الـ EFM وقفت بعدّاد الدورات وسابت
    #  6 قراءات فوق الحد، والتقشير اشتغل عليها **خمس دقايق ورجع بصفر
    #  استرند**: كل دور بيرسّب قطاع، بيتنصّف، بيرسّب تاني، لحد ما وقف
    #  على "two single changes in a row failed". ولا تحليل من العشرين
    #  كان ممكن ينفع، لأن السقف مش جاهز للتقشير أصلاً.
    #
    #  الترتيب الصح واضح: تقفل الراسب الأول، وبعدين تشيل الفايض. القرار
    #  اللي بيتاخد هنا مش "نشيل ولا مانشيلش" - هو "دلوقتي ولا بعدين".
    if base_reach > 0 and bool(getattr(params, "shave_only_when_clear", True)):
        result["stopped"] = ("the floor still has sections over the limit - "
                             "the shave did not start")
        job.flag(
            f"**The shave is not starting: {base_reach} section(s) prestress "
            f"can reach are still over the limit.** Taking strands out of a "
            f"floor that has not passed yet is the wrong way round, and it "
            f"costs a full RAM analysis per round to find that out - on one "
            f"of your runs, five minutes of them to remove nothing at all. "
            f"Close those sections first: raise 'Rounds at most' on the EFM "
            f"page (the loop now stops itself once it stops closing "
            f"sections, so a bigger number costs nothing on a floor that "
            f"finishes early), or deal with them by hand where prestress "
            f"cannot. Then run the shave on the model that passed. To shave "
            f"anyway, turn off 'Only shave a floor that has passed'.")
        #  **والكارت بيتطبع برضه.** الخروج المبكر ده كان بيشيل آخر
        #  حاجة الرن بيقولها: strand-m/m²، مدى الاستغلال، والبوابات.
        #  رنّتين كاملتين خرجوا من غير أي ملخص - والرن اللي مابيشيلش
        #  استرندات هو بالظبط الرن اللي محتاج تعرف فيه السقف واقف فين.
        try:
            card = design_scorecard(live(), plots, params, site, job, half)
            result["card"] = card
            result["gates_ok"], result["gates"] = design_gates(
                card, live(), params, job)
        except Exception as e:
            job.warn(f"The scorecard could not be worked out: {e}")
        return result
    #  مقاس كل كابل قبل ما التقشير يلمسه - ده اللي بيرجع لو الرن كله
    #  طلع الموديل أسوأ من اللي دخل (الفحص في آخر الدالة).
    for t in tendons:
        t["_shave_was"] = int(t.get("strands") or 0)
    frozen = set()
    removed = 0
    best_path = None
    idle = 0
    stopped = "rounds finished"
    last = s0
    #  17.97: لما الدور كله يرجع، نصه (الأوسع هامشاً) بيتجرّب لوحده بدل ما
    #  الكل يتجمّد. 17.99: اللوم بيتوسّع (1x، 2x، 4x المدى) قبل ما يقع على
    #  الدور كله، والدور اللي مالوش متهم بيتنصّف مش بيتجمّد، ومحاولات
    #  التنصيف مش بتتحسب من الدورات. على 01-PART-5-FIRST قطاع (66.3, 57.2)
    #  كان على الحد بـ 0.02 MPa قبل التخفيف وبيرسب مع أي تغيير في السقف
    #  كله - بعيد عن كل الكابلات اللي اتغيّرت - فكل دور كان بيتجمّد بحاله.
    tol = float(getattr(params, "shave_tolerance", 0.0) or 0.0)
    near_limit = [(x, y) for pl in plots for x, y, v in pl.demand
                  if pl.limit is not None and v > pl.limit - tol] if tol > 0 else []
    pending = None
    rnd = 0
    retries = 0
    #  18.03: سقف متكيّف على حجم الدور. دور رجع كله = الدور الجاي نصه؛
    #  دور اتقبل كله = الضعف. على FIRST P.01 كل دور جديد كان بيبدأ بـ 47
    #  تغيير، يرسب على قطاع حساس على مستوى السقف، ويتنصّف 3-4 مرات - 15
    #  تحليل عشان 4 كابلات.
    cap = None
    #  18.05: لما التنصيف يوصل لتغيير واحد ويرسب برضه مرتين ورا بعض،
    #  السقف عند حدّه - قطاع على الحد بيرسب بأي تغيير - والباقي تجميد
    #  كابل كابل بتحليل لكل واحد. P01-GR: دورات 3-12 كلها كده.
    single_fails = 0
    while rnd < rounds_max:
        job.check()
        retry = False
        take = None
        if pending:
            take = [c for c in pending
                    if id(c[0]) not in frozen and not c[0].get("_deleted")]
            pending = None
            retry = bool(take)
        if retry:
            retries += 1
            label = f"{rnd}.{retries}"
        else:
            rnd += 1
            retries = 0
            label = f"{rnd}"
            cands = shave_candidates(live(), plots, params, frozen)
            if not cands:
                stopped = "no tendon has room left"
                job.ok(f"Round {label}: no tendon can lose a size without eating "
                       f"into the margin - the shave stops here.")
                break
            n_take = min(len(cands), max(3, int(round(frac * len(cands)))))
            if cap is not None:
                n_take = min(n_take, max(2, cap))
            take = cands[:n_take]
        if retry:
            cands = take
        changed = shave_apply(take, tendons, params)

        def _undo(t, old):
            t.pop("_deleted", None)
            t["strands"] = old

        def _cut_of(pairs):
            return sum(old - (0 if t.get("_deleted") else int(t["strands"]))
                       for t, old in pairs)

        asked = _cut_of(changed)
        n_del = sum(1 for t, old in changed if t.get("_deleted"))
        job.step(0.5, f"Shave round {label}: -{asked} strands from {len(changed)} tendons")
        job.ok(f"Round {label}: {len(cands)} candidate(s)"
               f"{' (the widest-margin half of the round that went back)' if retry else ''}; "
               f"{len(changed) - n_del} lose a size and {n_del} come out "
               f"(-{asked} strands), widest margin first.")
        plots2, s1 = draw_and_read(f"shave round {label}")

        def _new_fails(pls):
            out = []
            for pl in pls:
                for x, y, v, l in pl.failing():
                    if any(dist((x, y), f) < 0.05 for f in base_fails):
                        continue
                    if tol > 0 and v - l <= tol and any(dist((x, y), f) < 0.05 for f in near_limit):
                        continue
                    out.append((x, y))
            return out

        new_fails = _new_fails(plots2)
        kept = list(changed)
        if int(s1["reach"]) + int(s1["unreach"]) > base_total or new_fails:
            blame = []
            reach_used = half
            for mult in (1.0, 2.0, 4.0):
                reach_used = half * mult
                blame = [(t, old) for t, old in changed
                         if any(_dist_to_path(f, t["profile"]) <= reach_used for f in new_fails)]
                if blame:
                    break
            if blame and len(blame) < len(changed):
                for t, old in blame:
                    _undo(t, old)
                    frozen.add(id(t))
                kept = [c for c in changed if c not in blame]
                job.warn(f"Round {label}: {len(new_fails)} new section(s) over the "
                         f"limit ({int(s1['reach'])} in all, {base_reach} before the "
                         f"shave). {len(blame)} of {len(changed)} tendon(s) within "
                         f"{reach_used:.1f} m get their strands back and are frozen "
                         f"for the rest of the run.")
                for x, y in new_fails[:6]:
                    job.info(f"    ({x:.1f}, {y:.1f})")
                plots2, s1 = draw_and_read(f"shave round {label} after the rollback")
                new_fails = _new_fails(plots2)
            else:
                for t, old in changed:
                    _undo(t, old)
                kept = []
                job.warn(f"Round {label}: {len(new_fails)} new section(s) over the "
                         f"limit ({int(s1['reach'])} in all, {base_reach} before the "
                         f"shave) and no changed tendon within {half * 4:.0f} m of "
                         f"them - a floor-wide effect; the round goes back.")
                for x, y in new_fails[:6]:
                    job.info(f"    ({x:.1f}, {y:.1f})")
            if (int(s1["reach"]) + int(s1["unreach"]) > base_total or new_fails) and kept:
                for t, old in kept:
                    _undo(t, old)
                kept = []
            if not kept:
                #  الدور كله راجع: نصّفه بدل ما تجمّده
                if len(changed) > 1:
                    half_n = len(changed) // 2
                    heads = {id(t) for t, old in changed[:half_n] if id(t) not in frozen}
                    pending = [c for c in take if id(c[0]) in heads]
                    job.warn(f"Round {label}: the round goes back; the "
                             f"{len(pending)} with the widest margins are tried "
                             f"again on their own.")
                else:
                    frozen.add(id(changed[0][0]))
                    single_fails += 1
                    job.warn(f"Round {label}: the last change goes back and is frozen.")
                plots2, s1 = draw_and_read(f"shave round {label} undone")
        cut = _cut_of(kept)
        removed += cut
        plots = plots2
        last = s1
        path = os.path.join(out_dir, f"{stem}_shave_r{label}.cpt")
        if safe_save(session, path, job):
            best_path = path
        result["rounds"].append({"round": label, "asked": asked, "cut": cut,
                                 "strands": s1["strands"], "strand_m": s1["strand_m"],
                                 "reach": s1["reach"], "unreach": s1["unreach"],
                                 "frozen": len(frozen), "path": path})
        job.ok(f"Round {label}: -{cut} strands kept out -> {s1['strands']} strands, "
               f"{s1['strand_m']:,.0f} strand-m, {s1['reach']} section(s) over "
               f"({base_reach} before the shave).")
        if retries >= 6:
            pending = None
        if kept:
            single_fails = 0
        if single_fails >= 2:
            stopped = "the floor is at its limit: two single changes in a row failed"
            job.ok(f"Round {label}: twice in a row even a single change made a "
                   f"section fail somewhere on the floor - the shave stops here.")
            break
        if not retry:
            if not kept and changed:
                cap = max(2, len(changed) // 2)
            elif kept and len(kept) == len(changed) and cap is not None:
                cap = cap * 2
        if cut == 0 and not pending:
            idle += 1
            if idle >= 2:
                stopped = "two rounds gained nothing"
                break
        elif cut:
            idle = 0
    #  **18.72: الموديل اللي دخل سايف بيخرج سايف - من غير استثناء.**
    #  الرجوع بيتعمل دور بدور فوق، وده المفروض يكفي. المفروض مش ضمان:
    #  قاعدة المهندس إن اللي دخل سايف يفضل سايف، والضمان الوحيد هو
    #  الفحص ده بعد كل حاجة. لو خرج أسوأ من اللي دخل، كل اللي اتشال
    #  بيرجع والموديل بيترسم تاني على أصله - مليون مرة أرخص من موديل
    #  بيتسلّم وفيه قطاع راسب اتعمل هنا.
    if shave_must_be_put_back(base_total, last["reach"], last["unreach"]):
        job.flag(f"**The shave is being put back in full.** The floor came "
                 f"in with {base_total} section(s) over the limit and this "
                 f"run leaves {int(last['reach']) + int(last['unreach'])}. "
                 f"A model that was safe has to stay safe: saving steel is "
                 f"worth nothing against a section that fails. Every strand "
                 f"taken in this shave goes back and the model is redrawn "
                 f"as it arrived.")
        for rec in reversed(result["rounds"]):
            rec["rolled_back"] = True
        try:
            for t in tendons:
                if t.get("_shave_was") is not None:
                    t.pop("_deleted", None)
                    t["strands"] = int(t["_shave_was"])
            plots, last = draw_and_read("the shave put back")
            path = os.path.join(out_dir, f"{stem}_shave_restored.cpt")
            if safe_save(session, path, job):
                best_path = path
            removed = 0
            stopped = "put back: the floor came in safe and has to leave safe"
        except Exception as e:
            job.error(f"The model could not be redrawn as it arrived ({e}). "
                      f"Use the file saved before the shave.")
    result.update({"best": best_path, "removed": removed, "stopped": stopped,
                   "strands": last["strands"], "strand_m": last["strand_m"],
                   "reach": last["reach"], "unreach": last["unreach"],
                   "start_strands": s0["strands"], "start_strand_m": s0["strand_m"]})
    job.ok(f"Shave done ({stopped}): {s0['strands']} -> {last['strands']} strands "
           f"(-{removed}), {s0['strand_m']:,.0f} -> {last['strand_m']:,.0f} "
           f"strand-m, sections over {base_reach} -> {last['reach']}.")
    #  **18.27: وبعد ما خلص - التصميم ده كويس قد إيه؟**
    #  السطر اللي فوق بيقول اتشال كام. السطرين دول بيقولوا لسه فيه كام،
    #  وإذا كان اللي فاضل عدّى الشروط ولا لأ.
    try:
        card = design_scorecard(live(), plots, params, site, job, half)
        result["card"] = card
        result["gates_ok"], result["gates"] = design_gates(
            card, live(), params, job)
    except Exception as e:
        job.warn(f"The scorecard could not be worked out: {e}")
    return result


def shave_after_loop(session, best_path, params, job, out_dir, stem, site=None,
                     mesh_size=None):
    """
    دور التخفيف بعد حلقة الـ EFM في البرنامج نفسه (17.97): الكابلات
    بتتقرا من أحسن ملف زي ما هي وبتدخل run_shave_loop. بترجّع مسار
    أحسن ملف بعد التخفيف، أو None لو الدور مقفول أو ماعملش حاجة.
    """
    if int(getattr(params, "shave_rounds", 0) or 0) <= 0:
        return None
    if not best_path or not os.path.isfile(best_path):
        job.warn("The shave loop needs the loop's best file and none was saved.")
        return None
    if not bool(getattr(params, "efm_read_ram", True)):
        job.warn("The shave loop reads RAM's section check directly; switch "
                 "'read the section check from RAM' on to use it.")
        return None
    tendons = tendons_from_cpt(best_path, params, job)
    if not tendons:
        return None
    for t in tendons:
        t["as_drawn"] = True
    pe = MdParams(params, efm_face="both")
    r = run_shave_loop(session, tendons, pe, job, out_dir, stem, site=site,
                       mesh_size=mesh_size)
    if r.get("removed") and r.get("best"):
        return r["best"]
    return None


# ==============================================================================
#  الكميات والتكلفة (18.123)
#
#  الاسترند بالكيلو، الدكت بالمتر (صغير لحد N استرند، كبير فوقها)، المرساة
#  بالقطعة حسب عدد الاسترندات (S2..S5، مرساتين لكل كابل)، الخرسانة
#  بالمتر المكعب (البلاطة + زيادة الدروبات)، وحديد التسليح بالكيلو (من
#  حديد رام المصمّم في الملف لو موجود، وإلا كجم/م² من الإعدادات).
#  التكلفة بتتحسب قبل وبعد كل حلقة أو تحسين، وفي مراجعة المشروع.
# ==============================================================================

def designed_rebar_kg(cpt_path):
    """كجم حديد التسليح اللي رام صمّمه في الملف، أو None لو ماينفعش يتقرا."""
    try:
        m = read_designed_steel(cpt_path)
    except Exception:
        return None
    rows = (m or {}).get("rebar") or []
    if not rows:
        return None
    #  المساحة بالمم² × الطول بالمتر × 7850 كجم/م³ ÷ 10⁶
    return sum(float(r.get("area") or 0.0) * float(r.get("len") or 0.0)
               for r in rows) * STEEL_DENSITY_KG_M3 / 1.0e6


def floor_quantities(tendons, site, params, rebar_kg=None):
    """
    كميات السقف وتكلفته من الأسعار في الإعدادات. بترجّع dict فيه الكميات
    (strand_m, strand_kg, duct_small_m, duct_large_m, anchors{2..5},
    concrete_m3, rebar_kg, rebar_source) والتكاليف (cost_strand,
    cost_duct, cost_anchor, cost_pt, cost_concrete, cost_rebar, total).
    """
    p = params
    live = [t for t in (tendons or []) if not t.get("_deleted")]
    small_max = int(getattr(p, "duct_small_max_strands", 3) or 3)
    kgm = strand_kg_per_m(p)
    q = {"tendons": len(live), "strands": 0, "strand_m": 0.0, "strand_kg": 0.0,
         "duct_small_m": 0.0, "duct_large_m": 0.0,
         "anchors": {2: 0, 3: 0, 4: 0, 5: 0}}
    for t in live:
        n = int(t.get("strands") or 0)
        L = tendon_plan_length(t)
        q["strands"] += n
        q["strand_m"] += n * L
        q["strand_kg"] += n * L * kgm
        if n <= small_max:
            q["duct_small_m"] += L
        else:
            q["duct_large_m"] += L
        q["anchors"][max(2, min(5, n))] += 2
    site = site or {}
    area = None
    try:
        area = slab_area_m2(site)
    except Exception:
        area = None
    if not area:
        b = site.get("boundary") or []
        area = (abs(polygon_area(b)) if len(b) >= 3 else 0.0) - sum(
            abs(polygon_area(o)) for o in (site.get("openings") or []) if len(o) >= 3)
    area = max(float(area or 0.0), 0.0)
    h = float(getattr(p, "slab_thickness", 250.0) or 250.0)
    h_drop = float(getattr(p, "drop_thickness", 0.0) or 0.0)
    drop_area = sum(abs(polygon_area(dp)) for dp in (site.get("drops") or []) if len(dp) >= 3)
    q["area_m2"] = area
    q["concrete_m3"] = area * h / 1000.0 + (drop_area * max(h_drop - h, 0.0) / 1000.0)
    if rebar_kg is not None and rebar_kg > 0:
        q["rebar_kg"], q["rebar_source"] = float(rebar_kg), "RAM's designed rebar"
    else:
        q["rebar_kg"] = area * float(getattr(p, "rebar_kg_m2", 12.0) or 12.0)
        q["rebar_source"] = f"{float(getattr(p, 'rebar_kg_m2', 12.0) or 12.0):.1f} kg/m² estimate"
    pr = {k: float(getattr(p, k, 0.0) or 0.0) for k in (
        "price_strand_kg", "price_duct_small_m", "price_duct_large_m",
        "price_anchor_s2", "price_anchor_s3", "price_anchor_s4", "price_anchor_s5",
        "price_concrete_m3", "price_rebar_kg")}
    q["cost_strand"] = q["strand_kg"] * pr["price_strand_kg"]
    q["cost_duct"] = q["duct_small_m"] * pr["price_duct_small_m"] + q["duct_large_m"] * pr["price_duct_large_m"]
    q["cost_anchor"] = sum(q["anchors"][k] * pr[f"price_anchor_s{k}"] for k in (2, 3, 4, 5))
    q["cost_pt"] = q["cost_strand"] + q["cost_duct"] + q["cost_anchor"]
    q["cost_concrete"] = q["concrete_m3"] * pr["price_concrete_m3"]
    q["cost_rebar"] = q["rebar_kg"] * pr["price_rebar_kg"]
    q["total"] = q["cost_pt"] + q["cost_concrete"] + q["cost_rebar"]
    q["per_m2"] = q["total"] / area if area else 0.0
    q["currency"] = str(getattr(p, "cost_currency", "SAR") or "SAR")
    return q


def cost_lines(q, title="Quantities and cost"):
    """سطور اللوج لكميات وتكلفة سقف واحد."""
    c = q["currency"]
    a = q["anchors"]
    return [
        f"{title}:",
        f"    PT: {q['tendons']} tendons, {q['strands']} strands, {q['strand_m']:,.0f} strand-m "
        f"= {q['strand_kg']:,.0f} kg strand -> {q['cost_strand']:,.0f} {c}",
        f"    ducts: small {q['duct_small_m']:,.0f} m, large {q['duct_large_m']:,.0f} m -> "
        f"{q['cost_duct']:,.0f} {c}",
        f"    anchorages: S2 x{a[2]}, S3 x{a[3]}, S4 x{a[4]}, S5 x{a[5]} -> {q['cost_anchor']:,.0f} {c}",
        f"    post-tensioning total: {q['cost_pt']:,.0f} {c}",
        f"    concrete: {q['concrete_m3']:,.1f} m³ on {q['area_m2']:,.0f} m² -> {q['cost_concrete']:,.0f} {c}",
        f"    rebar: {q['rebar_kg']:,.0f} kg ({q['rebar_source']}) -> {q['cost_rebar']:,.0f} {c}",
        f"    FLOOR TOTAL: {q['total']:,.0f} {c}  ({q['per_m2']:,.1f} {c}/m²)",
    ]


def cost_delta_lines(before, after):
    """قبل / بعد / التوفير - للحلقات والتحسين."""
    c = after["currency"]

    def d(k):
        return before[k] - after[k]
    sv = d("total")
    pct = (sv / before["total"] * 100.0) if before["total"] else 0.0
    return [
        "Cost before -> after:",
        f"    post-tensioning: {before['cost_pt']:,.0f} -> {after['cost_pt']:,.0f} {c} "
        f"({d('cost_pt'):+,.0f} saved)",
        f"    concrete: {before['cost_concrete']:,.0f} -> {after['cost_concrete']:,.0f} {c}",
        f"    rebar: {before['cost_rebar']:,.0f} -> {after['cost_rebar']:,.0f} {c} "
        f"({d('cost_rebar'):+,.0f} saved)",
        f"    FLOOR TOTAL: {before['total']:,.0f} -> {after['total']:,.0f} {c}  "
        f"SAVING {sv:+,.0f} {c} ({pct:+.1f}%)",
    ]


def cost_report(job, site, params, tendons_after, cpt_after=None,
                tendons_before=None, cpt_before=None, title="Quantities and cost"):
    """
    بيكتب في اللوج تكلفة السقف (وقبل/بعد لو فيه نقطة بداية). الحديد من
    الملف المحفوظ لو فيه، وإلا تقدير. بيرجّع (before, after).
    """
    if not bool(getattr(params, "cost_report", True)):
        return None, None
    try:
        rk_a = designed_rebar_kg(cpt_after) if cpt_after and os.path.isfile(cpt_after) else None
        after = floor_quantities(tendons_after, site, params, rebar_kg=rk_a)
        before = None
        if tendons_before is not None:
            rk_b = designed_rebar_kg(cpt_before) if cpt_before and os.path.isfile(cpt_before) else None
            before = floor_quantities(tendons_before, site, params, rebar_kg=rk_b)
        job.log("Cost", "head")
        for line in cost_lines(after, title):
            job.info(line)
        if before is not None:
            for line in cost_delta_lines(before, after):
                (job.ok if "SAVING" in line else job.info)(line)
        return before, after
    except CancelledError:
        raise
    except Exception as e:
        job.warn(f"The cost could not be worked out: {e}")
        return None, None


REVIEW_METHODS = {
    "Optimum solution H": "osh",
    "EFM loop, then the shave loop": "efm",
}


def _hm(seconds):
    seconds = max(0, int(round(seconds)))
    h, m = divmod(seconds // 60, 60)
    return f"{h}h {m:02d}m" if h else f"{m} min"


def review_eta_text(i, n, stem, durations, elapsed_current=0.0, now=None):
    """
    سطر الحالة للمراجعة (18.119): الموديل الحالي وترتيبه، ومتوسط زمن
    الموديل من اللي خلصوا فعلاً في الرن ده، والوقت المتبقي المتوقع
    وساعة الانتهاء. قبل أول موديل يخلص مافيش تقدير - بيتقال كده.
    """
    done = len(durations or [])
    head = f"Model {i} of {n}: {stem}"
    if not done:
        return head + " · the estimate comes after the first model finishes"
    avg = sum(durations) / done
    left = max(0.0, avg * (n - done) - float(elapsed_current or 0.0))
    now = now if now is not None else time.time()
    end = time.strftime("%H:%M", time.localtime(now + left))
    return (f"{head} · {done} done, {_hm(avg)} each · about {_hm(left)} "
            f"left, ends ~{end}")


def _review_cost(row, site, params, job):
    """تكلفة قبل/بعد لصف في المراجعة (18.123) - من الملفين."""
    if row.get("status") != "ok" or not bool(getattr(params, "cost_report", True)):
        return
    try:
        tb = tendons_from_cpt(row["path"], params, None)
        ta = tendons_from_cpt(row["output"], params, None) if row.get("output") else tb
        b, a = cost_report(job, site, params, ta, cpt_after=row.get("output"),
                           tendons_before=tb, cpt_before=row["path"])
        if b and a:
            row["cost_before"], row["cost_after"] = b["total"], a["total"]
            row["cost_saving"] = b["total"] - a["total"]
            row["currency"] = a["currency"]
    except Exception as e:
        job.warn(f"Cost for this model could not be worked out: {e}")


def review_project(files, params, job, out_dir, api_path=None, do_efm=True,
                   do_shave=True, method="efm", on_model=None):
    """
    **مراجعة مشروع كامل (18.11):** كل ملف بالترتيب - يتفتح زي ما هو،
    يتحلّل، فحص القطاعات يتقرا، ولو فيه قطاعات راسبة حلقة الـ EFM
    (section_only) تقفلها، وبعدين دور التخفيف يشيل الفايض. الملف
    الأصلي مابيتلمسش؛ كل خطوة بتتحفظ في out_dir. بترجّع صف لكل ملف
    فيه قبل/بعد (استراندات، استراند·متر، كجم، القطاعات الراسبة) والمسار.
    """
    import copy as _cp
    rows = []
    n_all = len(files)
    durations = []
    method = str(method or "efm").lower()
    for i, cpt in enumerate(files):
        job.check()
        stem = os.path.splitext(os.path.basename(cpt))[0]
        row = {"file": os.path.basename(cpt), "path": cpt, "status": "failed",
               "before": None, "after": None, "fails_before": [], "fails_after": [],
               "efm_rounds": 0, "shave_rounds": 0, "output": None, "error": "",
               "kg_before": None, "kg_after": None, "minutes": 0.0,
               "method": method}
        t0 = time.time()
        eta = review_eta_text(i + 1, n_all, stem, durations)
        job.step(i / max(n_all, 1), eta)
        if on_model:
            try:
                on_model({"i": i + 1, "n": n_all, "stem": stem, "t0": t0,
                          "durations": list(durations)})
            except Exception:
                pass
        try:
            job.log("=" * 62, "head")
            job.log(f"[{i + 1}/{n_all}]  {stem}", "head")
            job.info(eta)
            src = cpt
            if not cpt_is_current_format(cpt):
                src = ensure_current_model_format(cpt, out_dir, job, api_path=api_path)
                if not src:
                    raise RuntimeError("the old file format could not be converted")
            site = site_from_cpt(src, job)
            for k in ("guides_x", "guides_y", "arch_walls"):
                site.setdefault(k, [])
            p = _cp.copy(params)
            sync_slab_thickness(p, site, job)
            if method == "osh":
                #  18.119: المراجعة بنظام Optimum solution H - نفس مسار
                #  الموديل الواحد، كل موديل في فولدر باسمه جوّه فولدر
                #  المراجعة، والصف بياخد قبل/بعد من تقرير المسار.
                tendons = tendons_from_cpt(src, p, job)
                if not tendons:
                    raise RuntimeError("the model has no tendons to work with")
                for t in tendons:
                    t["as_drawn"] = True
                if not float(getattr(p, "strand_force_kn", 0.0) or 0.0):
                    _f, _n = strand_force_from_model(src, tendons, job)
                    if _f and _n >= 5:
                        p.strand_force_kn = _f
                enforce_min_radius(tendons, p, job)
                model_dir = os.path.join(out_dir, stem)
                os.makedirs(model_dir, exist_ok=True)
                base_kg = floor_strand_kg(tendons, p)
                with RamSession(job, api_path=api_path) as session:
                    session.open(src)
                    try:
                        _sync_min_radius_from_model(session, p, job)
                    except Exception:
                        pass
                    res = run_optimum_h(session, tendons, p, job, model_dir,
                                        stem, site=site, mesh_size=None,
                                        base_kg=base_kg)
                if not res.get("best"):
                    raise RuntimeError(f"Optimum solution H stopped: "
                                       f"{res.get('stopped') or 'no result'}")
                b_state, a_state = res.get("before_state"), res.get("after_state")
                row["before"] = res.get("before")
                row["after"] = res.get("after")
                row["kg_before"] = base_kg
                row["kg_after"] = (a_state or {}).get("kg")
                row["fails_before"] = [(f"{r['face']}_{str(r['dir']).lower()}", r["x"], r["y"],
                                        r["v"] - r["lim"])
                                       for r in (b_state or {}).get("readings", [])
                                       if r["u"] > 1.0]
                row["fails_after"] = [(f"{r['face']}_{str(r['dir']).lower()}", r["x"], r["y"],
                                       r["v"] - r["lim"])
                                      for r in (a_state or {}).get("readings", [])
                                      if r["u"] > 1.0]
                row["output"] = res["best"]
                row["osh_put_back"] = bool(res.get("put_back"))
                row["status"] = "ok"
                row["minutes"] = round((time.time() - t0) / 60.0, 1)
                durations.append(time.time() - t0)
                _review_cost(row, site, p, job)
                rows.append(row)
                b, a = row.get("before"), row.get("after")
                if b and a:
                    sv = (1.0 - a["strand_m"] / b["strand_m"]) * 100.0 if b["strand_m"] else 0.0
                    job.ok(f"RESULT {stem}: {b['strands']} -> {a['strands']} strands, "
                           f"{b['strand_m']:,.0f} -> {a['strand_m']:,.0f} strand-m ({sv:+.1f}%), "
                           f"sections over {b['reach']}+{b['unreach']} -> {a['reach']}+{a['unreach']}")
                continue
            pe = MdParams(p, efm_face="both", efm_objective="section_only",
                          efm_read_ram=True, stress_plot="",
                          efm_profile_mode="safe", efm_rebalance=True)
            with RamSession(job, api_path=api_path) as session:
                session.open(src)
                try:
                    _sync_min_radius_from_model(session, p, job)
                except Exception:
                    pass
                job.log("The model as it is", "head")
                res = run_model_analysis(session, job, None)
                if not res.get("ok"):
                    raise RuntimeError("RAM did not finish the analysis")
                plots = read_section_plots_from_ram(session, pe, job)
                tendons = tendons_from_cpt(src, p, job)
                for t in tendons:
                    t["as_drawn"] = True
                s0 = md_summary("as it is", tendons, plots, pe)
                row["before"] = s0
                row["kg_before"] = floor_strand_kg(tendons, p)
                row["fails_before"] = [(plot_tag(pl), float(x), float(y), float(v - l))
                                       for pl in plots for x, y, v, l in pl.failing()]
                job.ok(f"As it is: {s0['strands']} strands, {s0['strand_m']:,.0f} strand-m, "
                       f"{s0['reach']} section(s) over the limit that prestress can reach, "
                       f"{s0['unreach']} out of reach.")
                best = src
                work = tendons
                if do_efm and int(s0["reach"]) > 0:
                    job.log("EFM loop (section_only)", "head")
                    r2 = run_efm_loop(session, tendons, pe, job, out_dir,
                                      f"{stem}_review", site=site, mesh_size=None,
                                      base_kg=None, session_source=src, ask_plot=None)
                    best = r2.get("best") or best
                    row["efm_rounds"] = len(r2.get("rounds") or [])
                    if best != src and os.path.isfile(best):
                        work = tendons_from_cpt(best, p, job)
                        for t in work:
                            t["as_drawn"] = True
                if do_shave:
                    job.log("Shave loop", "head")
                    r3 = run_shave_loop(session, work, pe, job, out_dir,
                                        f"{stem}_review", site=site, mesh_size=None)
                    row["shave_rounds"] = len(r3.get("rounds") or [])
                    row["shave_stopped"] = r3.get("stopped")
                    if r3.get("best"):
                        best = r3["best"]
                live = [t for t in work if not t.get("_deleted")]
                if best == src:
                    s1, plots1 = s0, plots
                else:
                    plots1 = read_section_plots_from_ram(session, pe, job)
                    s1 = md_summary("after", live, plots1, pe)
                row["after"] = s1
                row["kg_after"] = floor_strand_kg(live, p)
                row["fails_after"] = [(plot_tag(pl), float(x), float(y), float(v - l))
                                      for pl in plots1 for x, y, v, l in pl.failing()]
                row["output"] = best
                row["status"] = "ok"
                #  18.27: "آمن" و"بأقل حديد" سؤالين مختلفين، والتاني
                #  مكانش ليه ولا سطر.
                card = design_scorecard(live, plots1, pe, site, job)
                row["card"] = card
                row["gates_ok"], row["gates"] = design_gates(card, live, pe, job)
        except CancelledError:
            row["error"] = "stopped"
            rows.append(row)
            raise
        except Exception as e:
            row["error"] = f"{type(e).__name__}: {e}"
            job.error(f"{stem}: {e}")
        row["minutes"] = round((time.time() - t0) / 60.0, 1)
        durations.append(time.time() - t0)
        _review_cost(row, site, p, job)
        rows.append(row)
        b, a = row.get("before"), row.get("after")
        if b and a:
            sv = (1.0 - a["strand_m"] / b["strand_m"]) * 100.0 if b["strand_m"] else 0.0
            job.ok(f"RESULT {stem}: {b['strands']} -> {a['strands']} strands, "
                   f"{b['strand_m']:,.0f} -> {a['strand_m']:,.0f} strand-m ({sv:+.1f}%), "
                   f"sections over {b['reach']}+{b['unreach']} -> {a['reach']}+{a['unreach']}")
    if durations:
        job.info(f"Review timing: {len(durations)} model(s) in "
                 f"{_hm(sum(durations))}, {_hm(sum(durations) / len(durations))} each.")
    job.step(1.0, "Review done")
    return rows


def write_review_xlsx(rows, path, params=None, job=None):
    """تقرير المراجعة كملف إكسل: ملخص، القطاعات، الإعدادات، الإجماليات."""
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils import get_column_letter
    except Exception as e:
        if job:
            job.warn(f"openpyxl is not available ({e}); no Excel report.")
        return None
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Summary"
    head = ["File", "Status", "Strands before", "Strands after", "Strand-m before",
            "Strand-m after", "Saving %", "kg before", "kg after", "Over (reach) before",
            "Over (reach) after", "Out of reach before", "Out of reach after",
            "EFM rounds", "Shave rounds", "Minutes", "Output file", "Note",
            "Cost before", "Cost after", "Cost saving"]
    ws.append(head)
    bold = Font(bold=True)
    fill_h = PatternFill("solid", fgColor="DDE7F0")
    for c in ws[1]:
        c.font = bold
        c.fill = fill_h
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    green = PatternFill("solid", fgColor="E3F4E1")
    red = PatternFill("solid", fgColor="F8E0E0")
    tot = {"sb": 0, "sa": 0, "mb": 0.0, "ma": 0.0, "kb": 0.0, "ka": 0.0,
           "rb": 0, "ra": 0, "ub": 0, "ua": 0, "cb": 0.0, "ca": 0.0}
    for r in rows:
        b, a = r.get("before") or {}, r.get("after") or {}
        sv = None
        if b.get("strand_m") and a.get("strand_m") is not None:
            sv = (1.0 - a["strand_m"] / b["strand_m"]) * 100.0
        line = [r.get("file"), r.get("status"), b.get("strands"), a.get("strands"),
                round(b.get("strand_m") or 0.0, 1) if b else None,
                round(a.get("strand_m") or 0.0, 1) if a else None,
                round(sv, 1) if sv is not None else None,
                round(r.get("kg_before") or 0.0, 1) if r.get("kg_before") is not None else None,
                round(r.get("kg_after") or 0.0, 1) if r.get("kg_after") is not None else None,
                b.get("reach"), a.get("reach"), b.get("unreach"), a.get("unreach"),
                r.get("efm_rounds"), r.get("shave_rounds"), r.get("minutes"),
                os.path.basename(r.get("output") or "") if r.get("output") else "",
                " · ".join(x for x in (
                    "Optimum solution H" if r.get("method") == "osh" else "",
                    "safe copy handed back" if r.get("osh_put_back") else "",
                    r.get("error") or r.get("shave_stopped") or "") if x),
                round(r["cost_before"]) if r.get("cost_before") is not None else None,
                round(r["cost_after"]) if r.get("cost_after") is not None else None,
                round(r["cost_saving"]) if r.get("cost_saving") is not None else None]
        ws.append(line)
        i = ws.max_row
        if sv is not None:
            ws.cell(row=i, column=7).fill = green if sv > 0 else red
        if a and b and (int(a.get("reach") or 0) + int(a.get("unreach") or 0)
                        > int(b.get("reach") or 0) + int(b.get("unreach") or 0)):
            ws.cell(row=i, column=11).fill = red
        if b and a:
            tot["sb"] += int(b.get("strands") or 0); tot["sa"] += int(a.get("strands") or 0)
            tot["mb"] += float(b.get("strand_m") or 0); tot["ma"] += float(a.get("strand_m") or 0)
            tot["kb"] += float(r.get("kg_before") or 0); tot["ka"] += float(r.get("kg_after") or 0)
            tot["rb"] += int(b.get("reach") or 0); tot["ra"] += int(a.get("reach") or 0)
            tot["ub"] += int(b.get("unreach") or 0); tot["ua"] += int(a.get("unreach") or 0)
            tot["cb"] += float(r.get("cost_before") or 0.0); tot["ca"] += float(r.get("cost_after") or 0.0)
        if r.get("cost_saving") is not None:
            ws.cell(row=i, column=21).fill = green if r["cost_saving"] > 0 else red
    svt = (1.0 - tot["ma"] / tot["mb"]) * 100.0 if tot["mb"] else 0.0
    ws.append(["TOTAL", "", tot["sb"], tot["sa"], round(tot["mb"], 1), round(tot["ma"], 1),
               round(svt, 1), round(tot["kb"], 1), round(tot["ka"], 1), tot["rb"], tot["ra"],
               tot["ub"], tot["ua"], "", "", "", "", "",
               round(tot["cb"]), round(tot["ca"]), round(tot["cb"] - tot["ca"])])
    for c in ws[ws.max_row]:
        c.font = bold
    widths = [34, 8, 9, 9, 11, 11, 9, 9, 9, 10, 10, 10, 10, 8, 8, 8, 40, 30, 12, 12, 12]
    for i, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "B2"

    ws2 = wb.create_sheet("Sections")
    ws2.append(["File", "Stage", "Face / direction", "x (m)", "y (m)", "Over the limit (MPa)"])
    for c in ws2[1]:
        c.font = bold
        c.fill = fill_h
    for r in rows:
        for stage, key in (("before", "fails_before"), ("after", "fails_after")):
            for tag, x, y, over in (r.get(key) or []):
                ws2.append([r.get("file"), stage, tag, round(x, 2), round(y, 2), round(over, 2)])
    for i, w in enumerate([34, 8, 16, 9, 9, 18], start=1):
        ws2.column_dimensions[get_column_letter(i)].width = w
    ws2.freeze_panes = "A2"

    ws3 = wb.create_sheet("Settings")
    ws3.append(["Setting", "Value"])
    for c in ws3[1]:
        c.font = bold
        c.fill = fill_h
    ws3.append(["Program", f"{APP_NAME} {APP_VERSION}"])
    ws3.append(["Date", datetime.datetime.now().strftime("%Y-%m-%d %H:%M")])
    if params is not None:
        for k in ("slab_thickness", "drop_thickness", "force_per_strand", "allowed_strands",
                  "min_strands", "max_strands", "spacing", "min_clear_spacing",
                  "max_tendon_length", "min_tendon_radius", "ram_inflection_ratio",
                  "efm_rounds", "shave_rounds", "shave_margin", "shave_reach",
                  "shave_target_u",
                  "shave_fraction", "shave_remove", "shave_tolerance", "low_move_frac",
                  "low_move_max_m", "column_bands", "group_same_crossings"):
            if hasattr(params, k):
                ws3.append([k, str(getattr(params, k))])
    ws3.column_dimensions["A"].width = 26
    ws3.column_dimensions["B"].width = 40
    try:
        wb.save(path)
    except Exception as e:
        if job:
            job.warn(f"The Excel report could not be saved ({e}).")
        return None
    if job:
        job.ok(f"Excel report: {os.path.basename(path)} - Summary, Sections, Settings.")
    return path


def write_review_md(rows, path, job=None):
    """نفس الملخص كنص (Markdown) - يتقرا في أي مكان ويتلزق في وورد."""
    lines = [f"# Project review - {APP_NAME} {APP_VERSION}",
             f"{datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}", "",
             "| File | Strands | Strand-m | Saving | Sections over (reach+out of reach) | Cost before -> after (saving) | Output |",
             "|---|---|---|---|---|---|---|"]
    for r in rows:
        b, a = r.get("before") or {}, r.get("after") or {}
        if not b or not a:
            lines.append(f"| {r.get('file')} | - | - | - | {r.get('error') or ''} | | |")
            continue
        sv = (1.0 - a["strand_m"] / b["strand_m"]) * 100.0 if b.get("strand_m") else 0.0
        cost = (f"{r['cost_before']:,.0f} -> {r['cost_after']:,.0f} ({r['cost_saving']:+,.0f})"
                if r.get("cost_before") is not None else "-")
        lines.append(f"| {r.get('file')} | {b['strands']} -> {a['strands']} | "
                     f"{b['strand_m']:,.0f} -> {a['strand_m']:,.0f} | {sv:+.1f}% | "
                     f"{b['reach']}+{b['unreach']} -> {a['reach']}+{a['unreach']} | {cost} | "
                     f"{os.path.basename(r.get('output') or '')} |")
    try:
        with open(path, "w", encoding="utf-8") as fh:
            fh.write("\n".join(lines) + "\n")
    except Exception as e:
        if job:
            job.warn(f"The text report could not be saved ({e}).")
        return None
    return path


def unreachable_by_prestress(rows, tendons, params, pa_max=None):
    """
    القراءات اللي **مفيش بوست تنشن هيحلّها** - مش لضيق المسافات، لكن
    لأن الضغط المسبق المطلوب أعلى من أي رقم معقول.

    القياس اللي طلّع القاعدة دي: على رن حقيقي، بعد ما اتزادت 26 كابل،
    فضلت 62 قراءة راسبة. النقط دي كان عندها بالفعل **24 استرند في
    3 متر عرض** - يعني حوالي 3.1 ميجا باسكال ضغط مسبق - ولسه محتاجة
    7 لـ 11 استرند لكل متر زيادة، يعني تقريباً 3 ميجا باسكال كمان.
    الإجمالي 6 ميجا، وده ضعف أي P/A مقبول (تدقيق البرنامج نفسه بيقبل
    1 لـ 2.5).

    يعني القطاعات دي مش ناقصة قوة - ناقصة **عمق**: دروب، أو سُمك، أو
    حديد. وإضافة كابلات هناك بتصرف بدون ما تحل.

    ⚠ الأرقام المذكورة تحت اتقاست بقارئ اللوحة **قبل تصحيح الإشارة**
      في 15.0 (كان بيقرا الضغط على إنه شد). فهي توصف سلوك
      نسخة غلط، ومتسيبة هنا للتاريخ بس. الأرقام الصحيحة على نفس
      اللوحة: 23 قراءة راسبة من 538 (4%)، أسوأ فائض 0.75 ميجا،
      وواحدة بس بره متناول البوست تنشن.
    """
    if pa_max is None:
        pa_max = float(getattr(params, "efm_pa_cap", 0.0) or 0.0) or 3.5
    #  17.78: الفائض بيتحوّل لضغط محوري **مكافئ** قبل المقارنة بالسقف.
    #  الاسترند اللي غطسته على الجانب الصح من القطاع بيدي relief (ميجا
    #  لكل استرند/م) أكبر من نصيبه المحوري ax بحوالي 3 مرات - نفس الرقم
    #  اللي التسعير بيستعمله. القاعدة القديمة كانت بتعامل كل ميجا فائض
    #  على إنها محتاجة ميجا ضغط محوري، فقطاع محتاج "8 ميجا" كان بيتساب
    #  بينما المهندس قافله بحزمة 15 استراند (SECOND p.05، y -78.2). عند
    #  قمة كابل (profile_against) الغطسة بتشتغل ضدك فالمحوري هو اللي
    #  يُحسب، زي الأول.
    ax = float(params.force_per_strand) / max(
        float(getattr(params, "slab_thickness", 280.0) or 280.0), 1e-6)
    out = []
    for r in rows:
        now, n = precompression_at((r["x"], r["y"]), tendons, params)
        need = r["over"]
        relief = float(r.get("relief") or 0.0)
        gain = 1.0
        if relief > ax > 0 and not r.get("profile_against"):
            gain = min(relief / ax, 4.0)
        need_eq = need / gain
        r["pa_now"] = now
        r["pa_needed"] = now + need_eq
        r["pa_needed_axial"] = now + need
        r["strands_here"] = n
        if now + need_eq > pa_max:
            out.append(r)
    return out


def over_provided(plot, tendons, params, job=None, half=1.5):
    """
    الوش التاني من الحكاية: **فين القوة زيادة عن اللزوم**.

    القياس اللي طلّع الدالة دي، على رن حقيقي:
      · الارتباط بين عدد الاسترندات حوالين القراءة وبين الشد فيها =
        **+0.09**. يعني عملياً صفر - القوة مش ماشية ورا الطلب.
      · القراءات الراسبة عندها وسيط 12 استرند في 1.5 م. القراءات
        السليمة عندها **نفس الرقم بالظبط** - 12.
      · وأتقل الأماكن في البلاطة (23 لـ 26 استرند) شدّها 0.1 لـ 0.2
        ميجا، يعني بعيدة تماماً عن الحد.
    التوزيع الموروث موحّد، والحلقة بتزوّد فوقه من غير ما تشيل من مكان.

    الدالة دي بتقول أين الفائض: قراءات آمنة بهامش كبير وحواليها كثافة
    عالية. مابتشيلش كابلات لوحدها - القرار ده هندسي وفيه ترخيم وتشقق
    مش بس شد - بس الرقم لازم يكون قدامك.

    ⚠ الأرقام المذكورة تحت اتقاست بقارئ اللوحة **قبل تصحيح الإشارة**
      في 15.0 (كان بيقرا الضغط على إنه شد). فهي توصف سلوك
      نسخة غلط، ومتسيبة هنا للتاريخ بس. الأرقام الصحيحة على نفس
      اللوحة: 23 قراءة راسبة من 538 (4%)، أسوأ فائض 0.75 ميجا،
      وواحدة بس بره متناول البوست تنشن.
    """
    lim = plot.limit
    if lim is None or not tendons:
        return []
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    p1 = float(params.force_per_strand)
    out = []
    for x, y, v in plot.demand:
        if v > 0.35 * lim:           # فيه شد يُعتد به - سيبه
            continue
        pa, n = precompression_at((x, y), tendons, params, half)
        if n <= 0:
            continue
        #  الفائض التقريبي: المسافة لحد الشد، مترجمة استرندات
        room = (lim - max(v, 0.0)) * h / max(p1, 1e-6)
        out.append({"x": x, "y": y, "v": v, "n": n, "pa": pa,
                    "spare_spm": room})
    out.sort(key=lambda d: -d["n"])
    heavy = [d for d in out if d["n"] >= 18]
    if job and not out:
        #  الصمت أسوأ من الخبر: قسم فاضي في التقرير بيتقري «البرنامج
        #  ماشتغلش»، مش «مافيش فايض». رن حقيقي طبع العنوان ده ومحدش
        #  عرف كان قصده إيه.
        job.ok("No reading is carrying prestress it does not need - every "
               "section with force near it has tension to justify it. There "
               "is nothing to take out.")
    if job and out:
        if heavy:
            job.warn(f"{len(heavy)} reading(s) sit under heavy prestress "
                     f"with almost no tension to resist - the worst is "
                     f"{heavy[0]['n']} strands within {half:.1f} m at "
                     f"({heavy[0]['x']:.1f}, {heavy[0]['y']:.1f}) holding "
                     f"{heavy[0]['pa']:.2f} MPa against a section reading "
                     f"{heavy[0]['v']:+.2f} MPa. Force there buys nothing.")
            job.info("    The layout it inherited is uniform, and the loop "
                     "only ever adds - it never thins. Those bands are where "
                     "strands could come out to pay for the ones that are "
                     "short, at no extra cost on the floor. Deflection and "
                     "cracking are not in this number, so it is a candidate "
                     "list, not an instruction.")
    #  **حكم التشبّع.** الحلقة بتزوّد وبس، ومافيش فيها حاجة بتقول
    #  «كفاية». الرقمين اللي بيقولوها موجودين: كام قطاع ناقص، وكام
    #  قطاع عنده فايض. لما الفايض يبقى أضعاف الناقص، الاسترند الجاي
    #  بيروح على سقف مضغوط أصلاً - وبيرجع حديد في البحور القصيرة بدل
    #  ما يشيله. قياس على رن حقيقي: 18 قطاع ناقص مقابل 110 فايض،
    #  والدورة اللي بعدها زوّدت الحديد 1.1% بدل ما تقلّله.
    #  العتبة على القراءات **التقيلة** (18 استرند أو أكتر في 1.5 م)،
    #  مش على أي قراءة فيها فايض. الفرق مقيس: على نفس اللوحة، القراءات
    #  اللي فيها أي فايض 477، والتقيلة منها 60. الأولى بتشمل السقف كله
    #  تقريباً فماتنفعش حكم؛ التانية بتفرّق بين سقف لسه قدامه شغل وسقف
    #  اتشبّع. الصفا: 0 تقيلة - الحكم ماينطقش. سقفك الجنوبي: 60 مقابل
    #  23 ناقصة - ينطق، والدورة اللي بعدها فعلاً زوّدت الحديد 1.1%.
    n_short = len(plot_deficits(plot, params))
    n_heavy = len(heavy)
    if job and n_heavy >= 25 and n_heavy >= 2 * max(n_short, 1):
        job.warn(f"**This face is finished.** {n_short} reading(s) are short, "
                 f"and {n_heavy} are carrying 18 strands or more within "
                 f"1.5 m with nothing to resist - {n_heavy / max(n_short, 1):.0f} "
                 f"times as many. Prestress is no longer what this floor is "
                 f"short of.")
        job.warn("    Another round will spend strands on sections that are "
                 "already compressed, and short spans crossed by those "
                 "tendons answer by asking for MORE bottom steel, not less. "
                 "What is left belongs to depth, a drop, or reinforcement - "
                 "and to taking strands OUT of the bands named above.")
    return out


def deficit_bands(rows, tendons, params, strip=12.0, tol=None,
                  direction=None, job=None):
    """
    تجميع القراءات الراسبة في **حارات**، مش في نقط.

    أول نسخة جمّعت النقط القريبة من بعض فطلعت 29 منطقة، أغلبها قراءة
    واحدة عرضها 40 سم - والنتيجة 26 كابل طول كل واحد 6 متر. ده مش
    تصميم، ده ترقيع نقطة نقطة.

    الصح إن الكابل بيشتغل **على طول حارته**: القراءات الراسبة اللي على
    نفس الحارة (نفس الإحداثي العرضي تقريباً) بتاخد كابل واحد طويل
    يغطّيها كلها. فالتجميع بيتم على الإحداثي **العرضي** لاتجاه الحارة،
    والامتداد الطولي بياخد من أول قراءة لآخر واحدة.

    **`direction`** ("x" أو "y") هو اتجاه اللوحة اللي القراءات دي
    اتقرت منها، ولما يتبعت بيبقى **حاكم**: قراءة راسبة في لوحة Y
    محتاجة قوة في Y، والكابل اللي في X مابيعملهاش حاجة مهما كان
    قريب.

    الغلط اللي القيد ده بيقفله عاش لحد 16.8: كل قراءة كانت بتاخد
    اتجاه **أقرب كابل ليها بالمسافة**. في بلاطة محزّمة كتير في اتجاه
    واحد، أقرب كابل لأي نقطة بيبقى من الحزمة الكتيفة دي - فكل
    الحارات كانت بتطلع في نفس الاتجاه، والقراءات اللي طالبة الاتجاه
    التاني كانت بتاخد كابلات مالهاش لازمة. المستخدم شاف ده بعينه على
    سقف حقيقي: حديد إضافي سفلي في Y، والبرنامج بيكوّم كابلات في X
    ويسيب مناطق محتاجة.

    بترجّع [{ux, uy, across, lo, hi, spm, n, rows}].
    """
    if tol is None:
        tol = max(float(getattr(params, "max_spacing", 0.0) or 0.0), 1.5)
    want = (str(direction).lower()[:1] if direction else None)
    if want not in ("x", "y"):
        want = None
    #  كل قراءة بتاخد اتجاه أقرب كابل ليها **في اتجاه اللوحة**
    tagged = []
    n_nodir = 0
    for r in rows:
        best, bd, u = None, 1e18, None
        for t in tendons:
            if t.get("_deleted"):
                continue
            pr = t.get("profile") or []
            if len(pr) < 2:
                continue
            ax = pr[-1]["pos"][0] - pr[0]["pos"][0]
            ay = pr[-1]["pos"][1] - pr[0]["pos"][1]
            n = math.hypot(ax, ay) or 1.0
            ax, ay = ax / n, ay / n
            #  الفلتر: الكابل ده ماشي في اتجاه اللوحة؟ (±45°)
            if want == "x" and abs(ax) < 0.7071:
                continue
            if want == "y" and abs(ay) < 0.7071:
                continue
            d = min(dist((r["x"], r["y"]), q["pos"]) for q in pr)
            if d < bd:
                bd, best, u = d, t, (ax, ay)
        if best is None or bd > strip:
            #  مفيش كابل في الاتجاه ده جنب القراءة دي. ده **مش** سبب
            #  للتجاهل - ده بالظبط المكان اللي محتاج حزمة جديدة في
            #  الاتجاه ده. القديم كان بيرمي القراءة، وده كان بيخلّي
            #  الاتجاه المهمَل يفضل مهمَل للأبد: مفيش كابل فيه ->
            #  مفيش حارة -> مفيش كابل يتزاد -> مفيش كابل فيه.
            if not want:
                continue
            u = ((1.0, 0.0) if want == "x" else (0.0, 1.0))
            n_nodir += 1
        #  اتجاه الكابل ممكن يتقرا في أي من الاتجاهين (u أو -u) حسب
        #  ترتيب نقطه. ومع الاتجاه بتنقلب إشارة الإحداثي العرضي، فنفس
        #  الحارة بتتحسب حارتين وبيتحط عليها كابلين فوق بعض. القياس: 3
        #  أزواج من الكابلات الجديدة على بُعد أقل من 40 سم، و4 مواضع
        #  فيها أكتر من كابل. التوحيد بيقفل ده من أصله.
        if (u[0] < -1e-9) or (abs(u[0]) <= 1e-9 and u[1] < 0):
            u = (-u[0], -u[1])
        tagged.append((r, u))
    #  التجميع: نفس الاتجاه (±45°) ونفس الإحداثي العرضي
    bands = []
    for r, u in tagged:
        across = -r["x"] * u[1] + r["y"] * u[0]
        along = r["x"] * u[0] + r["y"] * u[1]
        hit = None
        for b in bands:
            if abs(b["ux"] * u[0] + b["uy"] * u[1]) < 0.70:
                continue
            if abs(b["across"] - across) <= tol:
                hit = b
                break
        if hit is None:
            bands.append({"ux": u[0], "uy": u[1], "across": across,
                          "lo": along, "hi": along, "rows": [r],
                          "acr": [across]})
            continue
        hit["lo"] = min(hit["lo"], along)
        hit["hi"] = max(hit["hi"], along)
        hit["rows"].append(r)
        hit["acr"].append(across)
        hit["across"] = sum(hit["acr"]) / len(hit["acr"])
    #  **الكابل بيكمّل على البحور المتصلة بس (17.1).** قراءات الوش العلوي
    #  بتيجي أزواج (_pair): كل زوج بيغطّي البحرين حوالين ركيزته. زوجين على
    #  نفس الخط بينهم بحور سليمة كانوا بيطلعوا حارة واحدة - كابل 53 م على
    #  بحور مش محتاجاه. دلوقتي الفترات اللي بتتلامس (فراغ ≤ ضعف الامتداد)
    #  = حارة واحدة، والباقي حارات منفصلة. قراءات الوش السفلي زي ما هي.
    _join = 2.0 * float(getattr(params, "efm_added_extend", 2.0) or 2.0)
    _split = []
    for b in bands:
        if not any(q.get("_pair") is not None for q in b["rows"]):
            _split.append(b)
            continue
        _ux, _uy = b["ux"], b["uy"]
        _groups = {}
        for q, _ac in zip(b["rows"], b["acr"]):
            _al = q["x"] * _ux + q["y"] * _uy
            _key = q.get("_pair")
            if _key is None:
                _key = ("single", id(q))
            g = _groups.setdefault(_key, {"lo": _al, "hi": _al,
                                          "rows": [], "acr": []})
            g["lo"] = min(g["lo"], _al)
            g["hi"] = max(g["hi"], _al)
            g["rows"].append(q)
            g["acr"].append(_ac)
        _merged = []
        for g in sorted(_groups.values(), key=lambda z: z["lo"]):
            if _merged and g["lo"] - _merged[-1]["hi"] <= _join:
                m = _merged[-1]
                m["hi"] = max(m["hi"], g["hi"])
                m["rows"] += g["rows"]
                m["acr"] += g["acr"]
            else:
                _merged.append({"lo": g["lo"], "hi": g["hi"],
                                "rows": list(g["rows"]), "acr": list(g["acr"])})
        for m in _merged:
            _split.append({"ux": _ux, "uy": _uy,
                           "across": sum(m["acr"]) / len(m["acr"]),
                           "lo": m["lo"], "hi": m["hi"],
                           "rows": m["rows"], "acr": m["acr"]})
    bands = _split
    out = []
    for b in bands:
        spm = sorted(q["strands_per_m"] for q in b["rows"])
        #  الحارة خط واحد من الكابلات، والمقطع الأسوأ عليها هو الحاكم.
        #  المئين 75 كان بيسيب أسوأ قطاع في الحارة من غير علاج: على رن
        #  حقيقي، قطاعات راسبة بـ 5.16 ميجا مكانش حواليها غير 3 استرند،
        #  وقطاعات سليمة تماماً (0.1 ميجا شد) كان عندها 26. الارتباط بين
        #  الاسترندات والشد كان 0.09 - يعني القوة مش ماشية ورا الطلب.
        b["spm"] = spm[-1]
        b["spm_p75"] = spm[int(0.75 * (len(spm) - 1))]
        b["spm_max"] = spm[-1]
        b["n"] = len(b["rows"])
        b["width"] = max(max(b["acr"]) - min(b["acr"]), tol)
        b["cx"] = sum(q["x"] for q in b["rows"]) / b["n"]
        b["cy"] = sum(q["y"] for q in b["rows"]) / b["n"]
        b["dir"] = want
        out.append(b)
    out.sort(key=lambda z: -(z["spm"] * max(z["hi"] - z["lo"], 1.0)))
    if job and want:
        job.info(f"    every band below runs in {_dir_name(want)}, because "
                 f"that is the direction of the plot they were read from. "
                 f"A reading on a {_dir_name(want)} plot is short of "
                 f"prestress in {want.upper()}, and a tendon running the "
                 f"other way does not relieve it.")
        if n_nodir:
            job.warn(f"    {n_nodir} of {len(rows)} failing reading(s) have "
                     f"no {_dir_name(want)} tendon within {strip:.0f} m at "
                     f"all. They get a fresh band on the {want.upper()} "
                     f"axis - this is the part of the floor that was never "
                     f"banded in this direction.")
    return out


def _band_line(b):
    """(اتجاه الحارة، إحداثيها العرضي، مداها الطولي) - بصيغة تتحفظ."""
    return {"ux": float(b["ux"]), "uy": float(b["uy"]),
            "across": float(b["across"]), "lo": float(b["lo"]),
            "hi": float(b["hi"]), "width": float(b.get("width") or 0.0)}


def _reading_in_band(r, ln, tol):
    """القراءة دي واقعة على الحارة دي ولا لأ."""
    across = -r["x"] * ln["uy"] + r["y"] * ln["ux"]
    if abs(across - ln["across"]) > tol:
        return False
    along = r["x"] * ln["ux"] + r["y"] * ln["uy"]
    return (ln["lo"] - 2.0) <= along <= (ln["hi"] + 2.0)


def save_rebanding_record(path, bands, params, plot):
    """
    يسجّل **اللي عملناه واللي كان الوضع وقتها** - عشان الرن الجاي يقدر
    يقيس بدل ما يقدّر.

    اللي بيتحفظ لكل حارة: خطها ومداها، كام استرند حطّينا فيها، والقراءات
    اللي كانت عليها بقيمها. الرن الجاي بيقارن نفس القراءات في اللوحة
    الجديدة، والفرق مقسوم على الاسترندات هو **استجابة المكان ده**.
    """
    recs = []
    for b in bands:
        ln = _band_line(b)
        ln["strands"] = int(b.get("placed") or 0)
        ln["spm_asked"] = float(b.get("spm") or 0.0)
        ln["readings"] = [{"x": float(q["x"]), "y": float(q["y"]),
                           "over": float(q["over"])} for q in b["rows"]]
        recs.append(ln)
    data = {"limit": plot.limit, "face": plot.face,
            "dir": getattr(plot, "direction", None), "bands": recs,
            "when": datetime.datetime.now().isoformat(timespec="seconds")}
    try:
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(data, fh, ensure_ascii=False, indent=1)
        return path
    except Exception:
        return None


def rebanding_path(out_dir, stem, tag=""):
    """
    مسار السجل. الاسم بيتنضّف من `_EFM_rN` عشان كل دورات نفس الموديل
    تكتب وتقرا من نفس الملف - وإلا كل دورة هتقرا فاضي وتفضل تخمّن.

    **`tag`**: وش واتجاه اللوحة (`bottom_y` مثلاً). من ساعة ما الرن بقى
    ياخد أكتر من لوحة في الدورة الواحدة - وش علوي وسفلي، اتجاه X و Y -
    السجل الواحد بقى يتكتب أربع مرات فوق بعضه، وكل لوحة تقرا قياس
    لوحة تانية. القياس ده كان بيطلع رقم ملوش أي معنى: استجابة قِسناها
    في اتجاه X بتتحط تسعيرة لحارة في Y.
    """
    #  اللاحقة بتتراكم: 0000 -> 0000_EFM_r2 -> 0000_EFM_r2_EFM_r2. شيل
    #  واحدة بس معناه إن كل جيل بيكتب ملف باسم جديد ومابيلاقيش اللي
    #  قبله - رن حقيقي كتب 0000_stress_bands.json وبعدين دوّر على
    #  0000_EFM_r2_stress_bands.json وقال «مفيش سجل»، فالقياس اتلغى من
    #  غير ما حد يعرف. الشيل بيتكرر لحد ما يوصل للاسم الأصلي.
    #  اللاحقة بقت شكلين: `_EFM_rN` من الدورات، و`_EFM_final` من
    #  الكتابة الأخيرة. الشيل كان بيمسك الأول بس، فأول ما الرن يشتغل
    #  على `0000_EFM_final.cpt` بقى يدوّر على
    #  `0000_EFM_final_bottom_x_stress_bands.json` بدل
    #  `0000_bottom_x_stress_bands.json` - ويقول «مفيش سجل» ويسعّر
    #  بالورق. القياس اللي اتجمّع عبر رنّات كان بيضيع كل جيل من غير
    #  ما حد يعرف: اللوج قال «هامش 1.30» بدل «1.05» وهو عنده القياس
    #  على بُعد اسم ملف.
    base = re.sub(r"(_EFM_(r\d+|final)(-\d+)?)+$", "", str(stem or ""))
    t = re.sub(r"[^A-Za-z0-9]+", "_", str(tag or "")).strip("_")
    return os.path.join(out_dir,
                        base + ("_" + t if t else "") + "_stress_bands.json")


def plot_tag(plot):
    """وش اللوحة واتجاهها، بصيغة تصلح اسم ملف: `bottom_y`."""
    f = getattr(plot, "face", "?") or "?"
    d = getattr(plot, "direction", None)
    return f"{f}_{d}" if d else str(f)


def load_rebanding_record(cpt_path, stem=None, tag=""):
    """سجل الرن اللي فات، لو جنب الموديل."""
    if not cpt_path:
        return None
    if stem is None:
        stem = os.path.splitext(os.path.basename(cpt_path))[0]
        d = os.path.dirname(cpt_path)
    else:
        d = cpt_path
    path = rebanding_path(d, stem, tag)
    if not os.path.isfile(path):
        return None
    try:
        with open(path, encoding="utf-8") as fh:
            rec = json.load(fh)
        if rec and rec.get("bands"):
            return rec
    except Exception:
        pass
    return None


def measured_response(record, plot, params, tol=None):
    """
    **استجابة كل حارة، مقيسة**: كام ميجا نزل الإجهاد لكل استرند لكل متر.

    ده الرقم اللي المعادلة النظرية بتخمّنه. المعادلة بتقول إن استرند لكل
    متر عرض بيدّي Δσ = P/(1م × السُمك) - يعني حوالي 0.39 ميجا لبلاطة
    280. عملياً بيوصل أقل، لأن القوة بتتوزّع في الموديل على عرض أوسع من
    عرض الحارة اللي قِسناه على اللوحة. والفرق ده هو اللي خلّى الدورة
    الأولى تقفل 15 قراءة من 77 بس.

    ⚠ الأرقام المذكورة تحت اتقاست بقارئ اللوحة **قبل تصحيح الإشارة**
      في 15.0 (كان بيقرا الضغط على إنه شد). فهي توصف سلوك
      نسخة غلط، ومتسيبة هنا للتاريخ بس. الأرقام الصحيحة على نفس
      اللوحة: 23 قراءة راسبة من 538 (4%)، أسوأ فائض 0.75 ميجا،
      وواحدة بس بره متناول البوست تنشن.

    بترجّع {index: ميجا لكل استرند-لكل-متر} للحارات اللي اتقاست.
    """
    if not record or not record.get("bands"):
        return {}
    #  **السجل ده من نفس اللوحة؟** رن حقيقي وقع في ده: السجل اتكتب من
    #  لوحة حدها 2.82 (موديل تاني خالص)، والقياس اتعمل على لوحة حدها
    #  2.95. الفائض القديم محسوب فوق حد، والجديد فوق حد تاني - الفرق
    #  بينهم مش استجابة، ده فرق الحدين. والنتيجة كانت 0.038 ميجا لكل
    #  استرند/متر، يعني 10% من النظري - رقم مالوش أي معنى فيزيائي،
    #  واتحسب منه سعر حارات تانية.
    rl = record.get("limit")
    if rl is not None and plot.limit is not None:
        if abs(float(rl) - float(plot.limit)) > 0.01:
            return {"_mismatch": ("limit", float(rl), float(plot.limit))}
    rf = record.get("face")
    if rf and plot.face and rf != "?" and plot.face != "?" and rf != plot.face:
        return {"_mismatch": ("face", rf, plot.face)}
    #  والاتجاه زي الوش بالظبط: استجابة اتقاست في X مش تسعيرة لحارة
    #  في Y. اللوحتين ليهم نفس الحد ونفس الوش، فالفحصين اللي فوق
    #  مابيمسكوش ده.
    rd = record.get("dir")
    pd = getattr(plot, "direction", None)
    if rd and pd and rd != pd:
        return {"_mismatch": ("direction", _dir_name(rd), _dir_name(pd))}
    if tol is None:
        tol = max(float(getattr(params, "max_spacing", 0.0) or 0.0), 1.5)
    lim = plot.limit
    now = [{"x": x, "y": y, "v": v} for x, y, v in plot.demand]
    out = {}
    for i, ln in enumerate(record["bands"]):
        n = int(ln.get("strands") or 0)
        w = float(ln.get("width") or 0.0)
        if n <= 0 or w <= 0:
            continue
        #  القراءات اللي كانت على الحارة، وقيمها دلوقتي
        before, after = [], []
        for q in ln.get("readings") or []:
            before.append(float(q["over"]))
            best, bd = None, 1e18
            for r in now:
                d = math.hypot(r["x"] - q["x"], r["y"] - q["y"])
                if d < bd:
                    bd, best = d, r
            if best is None or bd > 0.6:
                after.append(None)
                continue
            #  الفائض الجديد فوق الحد - سالب يعني بقى تحت الحد. الشد
            #  سالب على اللوحة، فـ (-v - lim) هي نفس المعادلة في
            #  الحالتين: شد باقي، أو ضغط بقى مكانه.
            after.append(float(best["v"]) - lim)
        pairs = [(b, a) for b, a in zip(before, after) if a is not None]
        if not pairs:
            continue
        drop = sum(b - a for b, a in pairs) / len(pairs)      # ميجا
        spm = n / max(w, 1e-6)                                 # استرند/متر
        if spm <= 1e-6:
            continue
        out[i] = {"mpa_per_spm": drop / spm, "n": n, "width": w,
                  "drop": drop, "readings": len(pairs),
                  "line": ln}
    return out


def response_factor(measured, params, job=None):
    """
    عامل التصحيح العام: الوسيط بين المقيس والنظري.

    الحارة اللي مالهاش قياس بتاخد الوسيط ده. ولو مفيش أي قياس، بيرجّع
    None والحساب بيفضل نظري زي ما هو.
    """
    if not measured:
        return None
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    fpe = float(params.strand_fpu) * float(params.fpe_ratio)
    p1 = float(params.strand_area) * fpe / 1000.0        # kN
    theory = p1 / h                                       # ميجا لكل استرند/م
    vals = sorted(v["mpa_per_spm"] for v in measured.values()
                  if isinstance(v, dict) and v.get("mpa_per_spm", 0) > 1e-4)
    #  **عيّنة واحدة مش وسيط.** رن حقيقي سعّر 10 حارات على أساس حارة
    #  واحدة اتقاست - رقم واحد بقى حاكم على السقف كله. تحت تلات حارات
    #  القياس مايتعمّمش؛ الحارة اللي اتقاست تاخد رقمها هي، والباقي
    #  يفضل نظري لحد ما يبقى فيه قياس كفاية.
    if 0 < len(vals) < 3:
        if job:
            job.warn(f"Only {len(vals)} band(s) from the previous run could "
                     f"be re-read, which is not enough to price the rest of "
                     f"the floor from. Each measured band still uses its own "
                     f"figure; every other band stays on the theoretical one "
                     f"until at least 3 have been measured.")
        return None
    if not vals:
        if job:
            job.warn("The previous round's bands did not respond measurably, "
                     "so there is nothing to calibrate against - the "
                     "theoretical figure stands.")
        return None
    med = vals[len(vals) // 2]
    if job:
        job.log("What the last round actually bought", "head")
        job.ok(f"{len(vals)} band(s) from the previous run were re-read on "
               f"this plot. A strand per metre of width delivered a median "
               f"{med:.3f} MPa there, against {theory:.3f} MPa on paper - "
               f"{100.0 * med / theory:.0f}% of it.")
        job.info(f"    the range across those bands was "
                 f"{vals[0]:.3f} to {vals[-1]:.3f} MPa per strand per metre")
        job.info("    every band that was measured uses its own figure from "
                 "here; the rest use this median. Nothing is assumed any "
                 "more.")
    return med



# ======================================================================
#  الحلّال: من الكابل إلى العزم إلى الإجهاد - من غير رام
# ======================================================================
#
#  ليه أصلاً: كل دورة في الحلقة بتكلّف تصدير لوحة بالإيد ورن كامل.
#  والسؤال اللي الحلقة بتسأله كل مرة صغير: «لو حطّيت الكابل ده، الإجهاد
#  هيتحرّك كام؟». ده سؤال عن **الفرق**، والفرق مش محتاج رام:
#
#     كابل جديد ──► حِمله المكافئ ──► الفرق في العزم ──► الفرق في الإجهاد
#
#  التلات خطوات دول اتعايروا واحدة واحدة على تصديراتك، مش مفترضين:
#
#  1) **الكابل ← الحِمل**: رام بيكتب الحِمل المكافئ في الملف نفسه، تحت
#     طبقة Balance Loading، أحمال نقطية. على موديل الصفا: 6,610 حِمل،
#     كل واحد فيهم على كابل بالظبط (المسافة صفر مم، الوسيط والأقصى)،
#     منهم 204 = 102 كابل × طرفين = الأنكرات. المجموع الرأسي +22,913
#     و−22,913 كيلونيوتن، الصافي 4 نيوتن. ومن الأنكرات دي طلعت القوة
#     الفعّالة الحقيقية: **96.7 kN للاسترند** مقابل 110.1 من المعادلة.
#
#  2) **الحِمل ← العزم**: كمرة مستمرة على بحور الشريحة. الأحمال الثابتة
#     والحيّة بتتشال من الطرفين لأننا بنحسب فرق، فاللي بيدخل هو حِمل
#     الموازنة بتاع الكابل الجديد بس.
#
#  3) **العزم ← الإجهاد**: من تصديرك. عايرت لوحة عزم ولوحة إجهاد من نفس
#     الرن: σ = M/S + P/A، بـ R² = 0.88 على السقف كله و**وسيط 0.971 لما
#     تتعاير على كل بحر لوحده** (متوسط الخطأ 0.10 ميجا).


def strand_force_from_model(cpt_path, tendons=None, job=None):
    """
    **القوة الفعّالة للاسترند، مقروءة من الموديل مش مفترضة.**

    رام بيحوّل كل كابل لأحمال مكافئة وبيكتبها في الملف تحت طبقة
    Balance Loading. طرفَي كل كابل بيحملوا القوة المحورية كلها، فالقسمة
    على عدد الاسترندات بتدّي القوة الفعّالة بعد كل الفواقد - الاحتكاك،
    الانزلاق، الزحف - محسوبة برام نفسه لا بمعادلتنا.

    بترجّع (kN للاسترند، عدد الكابلات اللي اتقاست) أو (None, 0).
    """
    if not cpt_path or not os.path.isfile(cpt_path):
        return None, 0
    import sqlite3
    import shutil
    import tempfile
    tmp = scratch_cpt_path("bal_read")
    loads = []
    try:
        shutil.copy2(cpt_path, tmp)
        con = sqlite3.connect(tmp)
        #  الطبقة بالاسم، مش برقم ثابت: الـ UID بيتغيّر من ملف لملف
        uid = None
        for r in con.execute("SELECT UID FROM LoadingLayer "
                             "WHERE Name LIKE '%Balance%'"):
            uid = r[0]
            break
        if uid is None:
            con.close()
            return None, 0
        kids = [uid]
        for _ in range(3):
            more = []
            for k in kids:
                for t in ("LoadingLevel", "PointLoadCategory"):
                    try:
                        for r in con.execute(
                                'SELECT UID FROM "%s" WHERE ParentUID=?' % t,
                                (k,)):
                            more.append(r[0])
                    except Exception:
                        pass
            if not more:
                break
            kids += more
        marks = ",".join("?" * len(kids))
        for p0, fx, fy in con.execute(
                "SELECT Point0,PLFx,PLFy FROM PointLoad "
                "WHERE ParentUID IN (%s)" % marks, kids):
            n = re.findall(r"\[(-?\d+)\]", p0 or "")
            if len(n) < 2:
                continue
            loads.append((int(n[0]) * 1e-4, int(n[1]) * 1e-4,
                          math.hypot(fx or 0.0, fy or 0.0)))
        con.close()
    except Exception:
        return None, 0
    finally:
        try:
            os.remove(tmp)
        except Exception:
            pass
    if not loads or not tendons:
        return None, 0
    #  المطابقة **بالمسافة للمسار**، مش بالمستطيل المحيط. المستطيل بتاع
    #  كابل طويل بيبتلع أنكرات كابلات تانية، وعلى سقف كثيف ده بيدّي
    #  أرقام مستحيلة: رن حقيقي طلّع 182.2 kN للاسترند - **99% من حمل
    #  الكسر** (183.6 kN)، يعني أنكر جاره اتحسب له. المسافة للمسار
    #  بتقفل ده، والسقف الفيزيائي بيرمي أي باقي.
    live = [(x, y, f) for x, y, f in loads if f > 1000.0]
    if not live:
        return None, 0
    segs = []
    for ti, t in enumerate(tendons):
        pr = t.get("profile") or []
        for a, b in zip(pr, pr[1:]):
            segs.append((ti, a["pos"], b["pos"]))
    if not segs:
        return None, 0
    owner = {}
    for x, y, f in live:
        bi, bd = None, 1e18
        for ti, a, b in segs:
            dx, dy = b[0] - a[0], b[1] - a[1]
            L2 = dx * dx + dy * dy
            u = (0.0 if L2 < 1e-12
                 else max(0.0, min(1.0, ((x - a[0]) * dx
                                        + (y - a[1]) * dy) / L2)))
            d = math.hypot(x - (a[0] + u * dx), y - (a[1] + u * dy))
            if d < bd:
                bd, bi = d, ti
        if bi is not None and bd <= 0.05:
            if f > owner.get(bi, 0.0):
                owner[bi] = f
    #  السقف الفيزيائي: قوة الاسترند مابتعديش حمل الكسر، والشدّ العملي
    #  حوالي 0.8 منه. أي رقم فوق كده مطابقة غلط، مش قياس.
    brk = float(params_break(tendons))
    per = []
    n_nomatch = len(tendons) - len(owner)
    n_outband = 0
    outband_vals = []
    for ti, f in owner.items():
        n = int(tendons[ti].get("strands") or 0)
        if n <= 0:
            continue
        v = f / 1000.0 / n
        if not (0.45 * brk <= v <= 0.75 * brk):
            n_outband += 1
            outband_vals.append(v)
        #  المدى الواقعي للقوة الفعّالة بعد الفواقد: 45% لـ 75% من حمل
        #  الكسر (83 لـ 138 kN للاسترند العادي). الحد القديم 0.30 كان
        #  بيسمح بـ 59.7 kN يعدّي كقياس - ودي 32% من الكسر، مش قوة
        #  كابل مشدود، دي مطابقة غلط.
        if 0.45 * brk <= v <= 0.75 * brk:
            per.append(v)
    if len(per) < 5:
        return None, 0
    per.sort()
    med = per[len(per) // 2]
    if job:
        job.log("The force a strand actually carries here", "head")
        job.ok(f"Read from the anchor loads RAM wrote into this model "
               f"itself: a median of {med:.1f} kN per strand across "
               f"{len(per)} of {len(tendons)} tendon(s), spread "
               f"{per[0]:.1f} to {per[-1]:.1f} kN.")
        if len(per) < 0.75 * len(tendons):
            job.info(f"    {n_nomatch} tendon(s) had no anchor load within "
                     f"50 mm of their path, and {n_outband} had one whose "
                     f"force per strand was outside {0.45 * brk:.0f}-"
                     f"{0.75 * brk:.0f} kN, which no stressed strand can be. "
                     f"Both are left out rather than averaged in.")
            #  الأرقام بدل التخمين: أول نسخة من الرسالة دي خمّنت السبب
            #  ("الطبقة متكتوبة لهندسة تانية") والرن اللي بعدها كذّبها -
            #  صفر كابل بلا حِمل، و60 بقوة بره المدى. التخمين اتشال،
            #  والتوزيع بيتطبع عشان الرن نفسه يقول السبب.
            if n_outband and outband_vals:
                outband_vals.sort()
                n_lo = sum(1 for v in outband_vals if v < 0.45 * brk)
                job.warn(f"    the {n_outband} out-of-band tendon(s) read "
                         f"{outband_vals[0]:.1f} to {outband_vals[-1]:.1f} kN "
                         f"per strand, median "
                         f"{outband_vals[len(outband_vals) // 2]:.1f} - "
                         f"{n_lo} below the band and "
                         f"{n_outband - n_lo} above it.")
                job.info("    below the band usually means the anchor load "
                         "was missed and a drape load was taken instead; "
                         "above it means a neighbour's anchor was picked up "
                         "at a crossing. Either way those tendons are left "
                         "out, and the median that remains is the answer.")
        job.info(f"    the formula in the settings gives "
                 f"{_formula_force(None):.1f} kN - this is measured after "
                 f"friction, seating and long-term loss, by RAM, on this "
                 f"floor. Every strands-per-metre figure from here uses it.")
    return med, len(per)


def params_break(_tendons, fpu=1860.0, area=98.7):
    """حمل كسر الاسترند الواحد بالـ kN - السقف الفيزيائي لأي قياس."""
    return area * fpu / 1000.0


def _formula_force(params):
    """قوة الاسترند من المعادلة - للمقارنة في اللوج."""
    if params is None:
        return 110.1
    return (float(params.strand_area) * float(params.strand_fpu)
            * float(params.fpe_ratio) / 1000.0)


def _reaches(tendon):
    """
    الكابل مقسوم إلى **مدّات مكافئة**: من قمة لقمة.

    ما بين كل قمتين الكابل قطع مكافئ، وده اللي بيولّد حِمل موزّع صاعد
    منتظم. تقسيم المسار لقطع مستقيمة بين كل نقطتين بيضيّع ده تماماً -
    القياس على موديل الصفا كان بيدّي 47% لـ 85% بس من الحِمل اللي رام
    كتبه، لأن الانحناء العكسي فوق الركيزة والقطع نفسه مابيتحسبوش.

    بترجّع [(المسافة من البداية، الطول، الغطس بالمتر)] لكل مدّة.
    """
    pr = tendon.get("profile") or []
    if len(pr) < 3:
        return []
    xy = [q["pos"] for q in pr]
    z = [-float(q.get("depth") or 0.0) / 1000.0 for q in pr]
    run = [0.0]
    for a, b in zip(xy, xy[1:]):
        run.append(run[-1] + (dist(a, b) or 0.0))
    #  القمم = النقط اللي فوق جيرانها (والطرفان دايماً حدود مدّة)
    tops = [0]
    for i in range(1, len(z) - 1):
        if z[i] >= z[i - 1] and z[i] >= z[i + 1]:
            tops.append(i)
    tops.append(len(z) - 1)
    tops = sorted(set(tops))
    out = []
    for a, b in zip(tops, tops[1:]):
        L = run[b] - run[a]
        if L <= 0.3:
            continue
        #  الغطس: أعمق نقطة تحت الوتر الواصل بين القمتين
        sag = 0.0
        for k in range(a, b + 1):
            f = (run[k] - run[a]) / L
            chord = z[a] + (z[b] - z[a]) * f
            sag = max(sag, chord - z[k])
        if sag > 1e-4:
            out.append((run[a], L, sag))
    return out


def balance_load_of(tendon, p_strand, beta=0.35, mu=0.35, wob=0.0):
    """
    **الحِمل المكافئ لكابل واحد**، بنفس هندسة رام.

    رام مابيمثّلش الكابل كقطع مكافئ واحد بين قمتين. جدول Tendon فيه
    `InflectionRatio = 0.2` على كل الـ 1372 قطعة و `Harped = 0`: يعني
    قرب كل قمة فيه **انحناء عكسي** على أول 20% من نص المدّة، والباقي
    قطع مكافئ عادي. الانحناء العكسي بيدّي حِمل **نازل** فوق الركيزة،
    والقطع بيدّي حِمل **صاعد** في البحر.

    الهندسة (نص مدّة طولها L1 وارتفاع h من القمة للغطس، الميل صفر عند
    الاتنين، ونقطة الانقلاب عند β·L1):

        أقصى ميل      s = 2·h / L1
        نازل فوق الركيزة   P·s   موزّع على  β·L1
        صاعد في البحر      P·s   موزّع على  (1−β)·L1

    المجموع صفر - الكابل بيوازن نفسه. النسخة القديمة كانت بتدّي نفس
    الإجمالي الصاعد بس بتحطّ رد الفعل كله عند نقطة القمة، فالتوزيع
    المكاني كان غلط: على شبكة 3 م ضد أحمال رام الحقيقية كانت R² = 0.446.

    والاحتكاك: القوة بتقل على طول المسار،
    P(s) = P_anchor · exp(−(mu·α(s) + wob·s)). صفر يعني قوة ثابتة.

    **الأرقام الافتراضية مقيسة مش مفترضة.** اتعايروا على موديل الصفا
    ضد أحمال الموازنة اللي رام كتبها بنفسه، بمقارنة **حقل الحِمل على
    شبكة 3 م** - مش كابل بكابل، لأن نسب أي حِمل لكابل بعينه مش موثوقة
    (كابلات بتتقاطع، وأحمال الجار بتتحسب على الجنب؛ القياس بيدّي مجموع
    رأسي مش صفر على كابل مفروض يكون متزن).

        beta = 0.35 · mu = 0.35        R² = 0.813، النسبة 0.993

    والتحقق على سقفين **ماشاركوش في المعايرة**: R² = 0.754 و 0.772،
    النسبة 1.15 و 1.08.

    الرقمين دول **فعّالين مش فيزيائيين**: `beta` أوسع من الـ 0.2 اللي
    في جدول Tendon لأن المقارنة على خلية 3 م بتفضّل توزيع أنعم، و`mu`
    أعلى من معامل احتكاك حقيقي لأن الزاوية عندنا محسوبة من كسرات
    البوليلاين لا من منحنى حقيقي. هما معايرة للنموذج ده، مش ثوابت مادة.

    بترجّع {"reaches": [(البداية، الطول، w)] (موجب صاعد، سالب نازل),
             "ends": [...], "up": إجمالي الصاعد}.
    """
    n = int(tendon.get("strands") or 0)
    pr = tendon.get("profile") or []
    if n <= 0 or len(pr) < 3:
        return {"reaches": [], "ends": [], "up": 0.0}
    P0 = float(p_strand) * n
    xy = [q["pos"] for q in pr]
    z = [-float(q.get("depth") or 0.0) / 1000.0 for q in pr]
    run = [0.0]
    for a, b in zip(xy, xy[1:]):
        run.append(run[-1] + (dist(a, b) or 0.0))
    total = run[-1] or 1e-9
    #  الزاوية التراكمية من البداية - للاحتكاك
    ang = [0.0]
    for i in range(1, len(run)):
        h0 = (run[i] - run[i - 1]) or 1e-9
        s0 = (z[i] - z[i - 1]) / h0
        sp = (0.0 if i < 2 else
              (z[i - 1] - z[i - 2]) / ((run[i - 1] - run[i - 2]) or 1e-9))
        ang.append(ang[-1] + abs(s0 - sp))

    def force_at(s):
        if mu <= 0 and wob <= 0:
            return P0
        i = min(range(len(run)), key=lambda k: abs(run[k] - s))
        a1 = ang[i]
        p1 = P0 * math.exp(-(mu * a1 + wob * s))
        a2 = ang[-1] - ang[i]
        p2 = P0 * math.exp(-(mu * a2 + wob * (total - s)))
        return max(p1, p2)

    #  القمم والغطسات بالتناوب
    turn = [0]
    for i in range(1, len(z) - 1):
        up = z[i] >= z[i - 1] and z[i] >= z[i + 1]
        dn = z[i] <= z[i - 1] and z[i] <= z[i + 1]
        if up or dn:
            turn.append(i)
    turn.append(len(z) - 1)
    turn = sorted(set(turn))

    b = min(max(float(beta), 0.02), 0.45)
    rs, up_tot = [], 0.0
    for a, c in zip(turn, turn[1:]):
        L1 = run[c] - run[a]
        h = abs(z[a] - z[c])
        if L1 <= 0.15 or h <= 1e-4:
            continue
        P = force_at((run[a] + run[c]) / 2.0)
        slope = 2.0 * h / L1
        F = P * slope                       # كل الحِمل في نص المدّة دي
        high_at_a = z[a] > z[c]
        #  الانحناء العكسي جنب القمة، والقطع جنب الغطس
        if high_at_a:
            rs.append((run[a], b * L1, -F / max(b * L1, 1e-9)))
            rs.append((run[a] + b * L1, (1 - b) * L1,
                       F / max((1 - b) * L1, 1e-9)))
        else:
            rs.append((run[a], (1 - b) * L1, F / max((1 - b) * L1, 1e-9)))
            rs.append((run[c] - b * L1, b * L1, -F / max(b * L1, 1e-9)))
        up_tot += F
    ends = [(xy[0][0], xy[0][1], P0, z[0]),
            (xy[-1][0], xy[-1][1], force_at(total), z[-1])]
    return {"reaches": rs, "ends": ends, "up": up_tot}


class ContinuousFrame:
    """
    كمرة مستمرة على بحور شريحة تصميم - طريقة الصلابة.

    النسخة الأولى كانت بحور موشورية على ركائز بسيطة. تلات حاجات كانت
    ناقصة، وكلهم موجودين في الـ .cpt وبيفرقوا كتير في البلاطة اللاكمرية:

      · **الدروب بانل**: البلاطة بتتخن عند العمود، والصلابة بتتناسب مع
        مكعّب السُمك. دروب بياخد البلاطة من 280 لـ 480 بيدّي 5.0 ضعف
        صلابة **موضعياً** - وده بيسحب عزم للركيزة.
      · **عرض العمود**: البحر من مركز لمركز أطول من البحر الصافي. جزء
        الركيزة نفسه شبه جاسئ، والعزم الحاكم عند وش العمود مش مركزه.
      · **صلابة العمود**: ركيزة بسيطة بتدّي دوران حر - يعني عزم صفر عند
        العمود الطرفي، وده غلط. العمود بيقاوم بـ 4EI/L (أو 3EI/L لو
        طرفه التاني مفصلي)، فوق وتحت.

    التنفيذ: كل بحر بيتقسّم لعناصر صغيرة، كل عنصر بياخد صلابته من سُمك
    البلاطة عند منتصفه. منطقة الركيزة بتاخد صلابة عالية (المنطقة
    الجاسئة)، والعُقد عند الركائز بتاخد **نابض دوراني** بصلابة الأعمدة.
    ده بيخلّي الدروب والعرض والصلابة كلهم داخلين في نفس الحل، من غير
    صيغ خاصة لكل حالة.
    """

    def __init__(self, spans, ei=1.0, ei_at=None, springs=None,
                 rigid=None, esize=0.25):
        """
        spans   : [طول البحر بالمتر] - من مركز الركيزة لمركزها
        ei      : صلابة موحّدة، أو قايمة واحدة لكل بحر
        ei_at   : دالة (رقم البحر، المسافة داخله) -> EI - بتغلب على ei،
                  ودي اللي الدروب بانل بتدخل منها
        springs : [صلابة نابض دوراني عند كل عقدة] بطول (عدد البحور + 1)
        rigid   : [نص عرض الركيزة بالمتر عند كل عقدة] - المنطقة دي
                  بتاخد صلابة ×100
        esize   : طول العنصر المستهدف بالمتر
        """
        self.L = [float(q) for q in spans if float(q) > 1e-6]
        n = len(self.L)
        self.EI = ([float(ei)] * n if not isinstance(ei, (list, tuple))
                   else [float(q) for q in ei])
        if len(self.EI) < n:
            self.EI += [self.EI[-1] if self.EI else 1.0] * (n - len(self.EI))
        self.ei_at = ei_at
        self.springs = list(springs or [0.0] * (n + 1))
        self.springs += [0.0] * (n + 1 - len(self.springs))
        self.rigid = list(rigid or [0.0] * (n + 1))
        self.rigid += [0.0] * (n + 1 - len(self.rigid))
        self.esize = max(float(esize), 0.02)
        self._mesh()

    # ---------------------------------------------------------------
    def _stiff(self, i, x):
        """الصلابة داخل البحر i عند المسافة x - مع المنطقة الجاسئة."""
        base = (self.ei_at(i, x) if self.ei_at is not None else self.EI[i])
        base = float(base) or 1.0
        if x <= self.rigid[i] or (self.L[i] - x) <= self.rigid[i + 1]:
            return base * 100.0
        return base

    def _mesh(self):
        """تقسيم كل بحر لعناصر، وترقيم درجات الحرية."""
        self.el = []            # (رقم البحر، بداية العنصر، طوله، EI)
        self.nod = [0.0]        # المسافة التراكمية لكل عقدة
        self.sup = [0]          # أرقام عُقد الركائز
        run = 0.0
        for i, L in enumerate(self.L):
            k = max(int(math.ceil(L / self.esize)), 2)
            h = L / k
            for j in range(k):
                x0 = j * h
                self.el.append((i, x0, h, self._stiff(i, x0 + h / 2.0)))
                run += h
                self.nod.append(run)
            self.sup.append(len(self.nod) - 1)
        self.nn = len(self.nod)

    # ---------------------------------------------------------------
    def solve(self, udl=None, points=None):
        """
        بترجّع (عزوم أطراف البحور، دالة العزم داخل أي بحر).

        udl    : [حِمل موزّع لكل بحر kN/م] موجب لتحت
        points : [(رقم البحر، المسافة من بدايته، القوة kN لتحت)]
        """
        import numpy as np
        n = len(self.L)
        if n == 0:
            return [], (lambda i, x: 0.0)
        udl = list(udl or [0.0] * n)
        udl += [0.0] * (n - len(udl))
        pts = [(int(a), float(b), float(c)) for a, b, c in (points or [])]
        ndof = 2 * self.nn
        K = np.zeros((ndof, ndof))
        F = np.zeros(ndof)
        for e, (i, x0, h, EI) in enumerate(self.el):
            k = EI / h ** 3 * np.array([
                [12.0, 6 * h, -12.0, 6 * h],
                [6 * h, 4 * h * h, -6 * h, 2 * h * h],
                [-12.0, -6 * h, 12.0, -6 * h],
                [6 * h, 2 * h * h, -6 * h, 4 * h * h]])
            d = [2 * e, 2 * e + 1, 2 * e + 2, 2 * e + 3]
            K[np.ix_(d, d)] += k
            w = udl[i]
            if abs(w) > 1e-12:
                F[d[0]] += -w * h / 2.0
                F[d[1]] += -w * h * h / 12.0
                F[d[2]] += -w * h / 2.0
                F[d[3]] += w * h * h / 12.0
            for pi, a, P in pts:
                if pi != i or not (x0 - 1e-9 <= a < x0 + h - 1e-9):
                    continue
                aa = min(max(a - x0, 0.0), h)
                bb = h - aa
                F[d[0]] += -P * bb * bb * (3 * aa + bb) / h ** 3
                F[d[1]] += -P * aa * bb * bb / h ** 2
                F[d[2]] += -P * aa * aa * (aa + 3 * bb) / h ** 3
                F[d[3]] += P * aa * aa * bb / h ** 2
        #  نوابض الأعمدة على درجات الدوران عند الركائز
        for si, nd in enumerate(self.sup):
            kk = float(self.springs[si] if si < len(self.springs) else 0.0)
            if kk > 0:
                K[2 * nd + 1, 2 * nd + 1] += kk
        #  الركائز مسنودة رأسياً
        held = {2 * nd for nd in self.sup}
        free = [j for j in range(ndof) if j not in held]
        try:
            u_free = np.linalg.solve(K[np.ix_(free, free)], F[free])
        except Exception:
            u_free = np.linalg.lstsq(K[np.ix_(free, free)], F[free],
                                     rcond=None)[0]
        u = np.zeros(ndof)
        for j, g in enumerate(free):
            u[g] = u_free[j]
        #  العزم عند كل عقدة، من قوى أطراف العناصر
        Mn = [0.0] * self.nn
        for e, (i, x0, h, EI) in enumerate(self.el):
            k = EI / h ** 3 * np.array([
                [12.0, 6 * h, -12.0, 6 * h],
                [6 * h, 4 * h * h, -6 * h, 2 * h * h],
                [-12.0, -6 * h, 12.0, -6 * h],
                [6 * h, 2 * h * h, -6 * h, 4 * h * h]])
            d = [2 * e, 2 * e + 1, 2 * e + 2, 2 * e + 3]
            fe = np.zeros(4)
            w = udl[i]
            if abs(w) > 1e-12:
                fe += np.array([-w * h / 2.0, -w * h * h / 12.0,
                                -w * h / 2.0, w * h * h / 12.0])
            for pi, a, P in pts:
                if pi != i or not (x0 - 1e-9 <= a < x0 + h - 1e-9):
                    continue
                aa = min(max(a - x0, 0.0), h)
                bb = h - aa
                fe += np.array([-P * bb * bb * (3 * aa + bb) / h ** 3,
                                -P * aa * bb * bb / h ** 2,
                                -P * aa * aa * (aa + 3 * bb) / h ** 3,
                                P * aa * aa * bb / h ** 2])
            f = k.dot(u[d]) - fe
            Mn[e] = -f[1]
            Mn[e + 1] = f[3]
        self._Mn = Mn
        ends = []
        for i in range(n):
            a = self.sup[i]
            b = self.sup[i + 1]
            ends.append((Mn[a], Mn[b]))

        def M(i, x):
            """العزم داخل البحر i على بُعد x من بدايته (السالب = هوجينج)."""
            i = int(i)
            if not (0 <= i < n):
                return 0.0
            L = self.L[i]
            x = min(max(float(x), 0.0), L)
            a, b = self.sup[i], self.sup[i + 1]
            s0 = self.nod[a]
            want = s0 + x
            for nd in range(a, b):
                if self.nod[nd] - 1e-9 <= want <= self.nod[nd + 1] + 1e-9:
                    span = (self.nod[nd + 1] - self.nod[nd]) or 1e-9
                    f = (want - self.nod[nd]) / span
                    return Mn[nd] + (Mn[nd + 1] - Mn[nd]) * f
            return Mn[b]
        return ends, M


def column_spring(b_m, d_m, height_m, fixed_far=True, ang_deg=0.0,
                  along=(1.0, 0.0), e_mpa=30000.0, ifactor=1.0):
    """
    صلابة العمود الدورانية عند البلاطة، kN·م لكل راديان.

        k = 4·E·I / H     (طرفه التاني مثبّت)
        k = 3·E·I / H     (طرفه التاني مفصلي)

    **كل الأبعاد بالمتر** - التحويل من وحدات الملف (0.1 مم) مسؤولية
    القارئ. النسخة الأولى خلطت 0.1 مم بالمليمتر فطلعت الصلابة أكبر
    10,000 مرة، وكل عمود بقى تثبيت كامل. الاختبار اللي كشفها: عمود
    500×500 ارتفاع 3 م لازم يدّي حوالي 208,000 kN·م/راديان، وكان
    بيدّي 2,083,333,333.

    البُعد اللي بيقاوم هو اللي **في اتجاه الشريحة**: عمود 1500×500 على
    شريحة ماشية في اتجاه الـ 1500 أجسأ بكتير من نفس العمود على شريحة
    في الاتجاه التاني. الزاوية داخلة في الحساب.
    """
    b = abs(float(b_m))
    d = abs(float(d_m))
    H = max(abs(float(height_m)), 0.5)
    a = math.radians(float(ang_deg) or 0.0)
    ca, sa = math.cos(a), math.sin(a)
    ux, uy = along
    nn = math.hypot(ux, uy) or 1.0
    ux, uy = ux / nn, uy / nn
    par = abs(ca * ux + sa * uy)
    per = abs(-sa * ux + ca * uy)
    h_along = b * par + d * per          # البُعد في اتجاه الشريحة
    w_perp = b * per + d * par
    I = w_perp * h_along ** 3 / 12.0     # م⁴
    k = (4.0 if fixed_far else 3.0) * float(e_mpa) * 1000.0 * I / H
    return k * float(ifactor or 1.0)


def supports_from_cpt(cpt_path):
    """
    الأعمدة والحوائط بأبعادها وارتفاعاتها وتثبيتها - بالمتر.

    الملف بيخزّن الأطوال بوحدة 0.1 مم، والصلابة بتتناسب مع مكعّب البُعد،
    فأي غلط في الوحدة بيتضاعف ألف مرة. التحويل بيتعمل هنا مرة واحدة.

    بترجّع [{"kind","pos","b","d","ang","h","fixed","ifac","kfac"}].
    """
    out = []
    if not cpt_path or not os.path.isfile(cpt_path):
        return out
    import sqlite3
    import shutil
    import tempfile
    tmp = scratch_cpt_path("sup_read")
    try:
        shutil.copy2(cpt_path, tmp)
        con = sqlite3.connect(tmp)

        def pt(t):
            n = re.findall(r"\[(-?\d+)\]", t or "")
            return ((int(n[0]) * 1e-4, int(n[1]) * 1e-4)
                    if len(n) >= 2 else None)
        try:
            for (p0, b, d, ang, h, fn, ff, ifac, kfac, ss) in con.execute(
                    "SELECT Point0,B,D,Angle,Height,FixedNear,FixedFar,"
                    "IFactor,SlabSupportStiffnessFactor,SupportSet "
                    "FROM Column"):
                q = pt(p0)
                if not q:
                    continue
                out.append({"kind": "column", "pos": q,
                            "b": (b or 0.0) * 1e-4, "d": (d or 0.0) * 1e-4,
                            "ang": ang or 0.0, "h": (h or 0.0) * 1e-4,
                            "fixed": bool(ff), "near": bool(fn),
                            "ifac": ifac if ifac is not None else 1.0,
                            "kfac": kfac if kfac is not None else 1.0,
                            "set": ss or ""})
        except Exception:
            pass
        try:
            for (p0, p1, th, h, fn, ff, kfac, ss) in con.execute(
                    "SELECT Point0,Point1,WallThickness,Height,FixedNear,"
                    "FixedFar,SlabSupportStiffnessFactor,SupportSet "
                    "FROM Wall"):
                a, z = pt(p0), pt(p1)
                if not a or not z:
                    continue
                mid = ((a[0] + z[0]) / 2.0, (a[1] + z[1]) / 2.0)
                ang = math.degrees(math.atan2(z[1] - a[1], z[0] - a[0]))
                out.append({"kind": "wall", "pos": mid, "a": a, "z": z,
                            "b": dist(a, z), "d": (th or 0.0) * 1e-4,
                            "ang": ang, "h": (h or 0.0) * 1e-4,
                            "fixed": bool(ff), "near": bool(fn),
                            "ifac": 1.0,
                            "kfac": kfac if kfac is not None else 1.0,
                            "set": ss or ""})
        except Exception:
            pass
        con.close()
    except Exception:
        return out
    finally:
        try:
            os.remove(tmp)
        except Exception:
            pass
    return out


def thickness_map_from_cpt(cpt_path):
    """
    **سُمك البلاطة عند أي نقطة** - ومنه الدروب بانل.

    الدروب مش جدول لوحده: هو صف SlabArea بسُمك أكبر و Priority أعلى
    فوق بلاطة الأساس. فالسُمك عند نقطة = سُمك أعلى أولوية بوليجونها
    شامل النقطة. ده اللي بيخلّي الحلّال يحس بالدروب من غير ما نعرّفها
    ليه - وفرقها مش صغير: 280 لـ 480 يعني 5.0 ضعف صلابة موضعياً.

    بترجّع دالة (x, y) -> السُمك بالمليمتر.
    """
    areas = []
    if cpt_path and os.path.isfile(cpt_path):
        import sqlite3
        import shutil
        import tempfile
        tmp = scratch_cpt_path("thk_read")
        try:
            shutil.copy2(cpt_path, tmp)
            con = sqlite3.connect(tmp)
            for th, pr, mp in con.execute(
                    "SELECT SlabThickness,Priority,MultiPoint FROM SlabArea"):
                n = re.findall(r"\[(-?\d+)\]", mp or "")
                pts = [(int(n[i]) * 1e-4, int(n[i + 1]) * 1e-4)
                       for i in range(0, len(n) - 1, 2)]
                if len(pts) < 3 or not th:
                    continue
                xs = [q[0] for q in pts]
                ys = [q[1] for q in pts]
                areas.append({"t": float(th) * 0.1,      # 0.1 مم -> مم
                              "p": int(pr or 0), "poly": pts,
                              "bb": (min(xs), min(ys), max(xs), max(ys))})
            con.close()
        except Exception:
            pass
        finally:
            try:
                os.remove(tmp)
            except Exception:
                pass
    areas.sort(key=lambda a: -a["p"])

    def inside(pt, poly):
        x, y = pt
        c = False
        j = len(poly) - 1
        for i in range(len(poly)):
            xi, yi = poly[i]
            xj, yj = poly[j]
            if (yi > y) != (yj > y):
                if x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-12) + xi:
                    c = not c
            j = i
        return c

    def at(x, y):
        for a in areas:
            x0, y0, x1, y1 = a["bb"]
            if not (x0 - 1e-6 <= x <= x1 + 1e-6
                    and y0 - 1e-6 <= y <= y1 + 1e-6):
                continue
            if inside((x, y), a["poly"]):
                return a["t"]
        return None
    at.areas = areas
    return at


def frame_from_axis(axis, width_m, thick=None, sups=None, e_mpa=30000.0,
                    rigid_frac=0.5):
    """
    **يبني الإطار المستمر لشريحة تصميم من الموديل نفسه.**

    axis   : [(x, y)] نقط الركائز على محور الشريحة، بالترتيب
    width_m: عرض الشريحة بالمتر
    thick  : خريطة السُمك من thickness_map_from_cpt (الدروب بانل)
    sups   : الركائز من supports_from_cpt (عرض العمود وصلابته)

    الدروب بتدخل عن طريق ei_at: كل عنصر بياخد سُمكه من مكانه على المحور،
    والصلابة بمكعّب السُمك. العمود بيدخل مرتين - نابض دوراني عند العقدة،
    ومنطقة جاسئة بنص عرضه.
    """
    if not axis or len(axis) < 2:
        return None
    spans = [dist(a, b) for a, b in zip(axis, axis[1:])]
    ux = axis[-1][0] - axis[0][0]
    uy = axis[-1][1] - axis[0][1]
    nn = math.hypot(ux, uy) or 1.0
    along = (ux / nn, uy / nn)
    E = float(e_mpa) * 1000.0                       # kN/م²

    def ei_at(i, x):
        a, b = axis[i], axis[i + 1]
        L = spans[i] or 1e-9
        f = min(max(x / L, 0.0), 1.0)
        px = a[0] + (b[0] - a[0]) * f
        py = a[1] + (b[1] - a[1]) * f
        t = None
        if thick is not None:
            try:
                t = thick(px, py)
            except Exception:
                t = None
        h = (float(t) if t else 280.0) / 1000.0
        return E * float(width_m) * h ** 3 / 12.0

    springs, rigid = [], []
    for q in axis:
        k, half = 0.0, 0.0
        best, bd = None, 1e18
        for sp in (sups or []):
            d = dist(q, sp["pos"])
            if sp["kind"] == "wall":
                d = min(d, dist(q, sp.get("a") or sp["pos"]),
                        dist(q, sp.get("z") or sp["pos"]))
            if d < bd:
                bd, best = d, sp
        if best is not None and bd <= 2.0:
            k = column_spring(best["b"], best["d"], best["h"],
                              best.get("fixed", True), best.get("ang", 0.0),
                              along, e_mpa, best.get("ifac", 1.0))
            k *= float(best.get("kfac", 1.0) or 1.0)
            #  سقف: حائط طوله 15 م موازي للشريحة بيدّي عزم قصور هائل
            #  (القياس: لحد 592,704,000 مقابل وسيط 17,157,000)، والرقم
            #  ده مالوش معنى في نموذج «نابض عند عقدة». وفيزيائياً، نابض
            #  أجسأ 100 مرة من 4EI/L بتاعة البلاطة عنده = تثبيت كامل
            #  ومافيش فرق بعد كده. فالسقف مابيغيّرش إجابة صحيحة، بس
            #  بيمنع رقم بلا معنى من إنه يسيطر على الحل.
            _i = min(max(len(springs), 0), len(spans) - 1)
            _L = spans[_i] if spans else 8.0
            _cap = 100.0 * 4.0 * ei_at(_i, 0.0) / max(_L, 1e-6)
            k = min(k, _cap)
            #  فوق وتحت: لو الموديل فيه الاتنين، الصلابة بتتجمع
            a = math.radians(float(best.get("ang", 0.0)) or 0.0)
            par = abs(math.cos(a) * along[0] + math.sin(a) * along[1])
            per = abs(-math.sin(a) * along[0] + math.cos(a) * along[1])
            half = rigid_frac * (best["b"] * par + best["d"] * per)
        springs.append(k)
        rigid.append(half)
    return ContinuousFrame(spans, ei_at=ei_at, springs=springs, rigid=rigid)


def band_response(b, measured, tol):
    """
    الحارة دي اتقاست قبل كده ولا لأ - وبكام.

    التطابق: نفس الاتجاه (±45°)، نفس الإحداثي العرضي في حدود `tol`،
    ومداها الطولي متداخل مع المسجّل. لو اتطابقت أكتر من واحدة، الأقرب
    عرضياً هي المقصودة.
    """
    best, bd = None, 1e18
    for v in (measured or {}).values():
        ln = v["line"]
        if abs(ln["ux"] * b["ux"] + ln["uy"] * b["uy"]) < 0.70:
            continue
        d = abs(ln["across"] - b["across"])
        if d > tol:
            continue
        if b["hi"] < ln["lo"] - 2.0 or b["lo"] > ln["hi"] + 2.0:
            continue
        if d < bd:
            bd, best = d, v
    return best


def theory_mpa_per_spm(params, rows=None):
    """
    الميجا اللي استرند لكل متر عرض بيدّيها على الورق.

    **لازم تبقى نفس الرقم اللي `plot_deficits` قسّم عليه**، وإلا
    المعايرة بتقارن حاجتين مختلفتين: `scale = theory / measured` وهي
    اللي بتضرب الطلب. لو الطلب اتحسب بالمحوري+العزم والنظري بالمحوري
    وحده، الاتنين بيتشالوا من بعض والتحسين بيروح هدر. فلما تكون
    القراءات موجودة بنرجّع وسيط اللي اتحسب فعلاً عندها.
    """
    if rows:
        v = sorted(float(q.get("relief") or 0.0) for q in rows
                   if q.get("relief"))
        if v:
            return v[len(v) // 2]
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    return float(params.force_per_strand) / max(h, 1e-6)


def _parallel_to_u(t, ux, uy):
    """الكابل ماشي في اتجاه (ux, uy)؟"""
    pr = t.get("profile") or []
    if len(pr) < 2:
        return False
    tx = pr[-1]["pos"][0] - pr[0]["pos"][0]
    ty = pr[-1]["pos"][1] - pr[0]["pos"][1]
    tn = math.hypot(tx, ty) or 1.0
    return abs(ux * tx / tn + uy * ty / tn) >= 0.7071


def _across_at(t, s, ux, uy):
    """الإحداثي العرضي للكابل عند المحطة s على محور الحارة، أو None."""
    pr = t.get("profile") or []
    for p1, p2 in zip(pr, pr[1:]):
        a1 = p1["pos"][0] * ux + p1["pos"][1] * uy
        a2 = p2["pos"][0] * ux + p2["pos"][1] * uy
        if min(a1, a2) - 1e-6 <= s <= max(a1, a2) + 1e-6:
            r1 = -p1["pos"][0] * uy + p1["pos"][1] * ux
            r2 = -p2["pos"][0] * uy + p2["pos"][1] * ux
            if abs(a2 - a1) < 1e-9:
                return r1
            return r1 + (r2 - r1) * (s - a1) / (a2 - a1)
    return None


def _along_span_of(t, ux, uy):
    """محطتي بداية ونهاية الكابل على اتجاه الحارة (u)."""
    pr = t.get("profile") or []
    if len(pr) < 2:
        return None
    ss = [q["pos"][0] * ux + q["pos"][1] * uy for q in pr]
    return min(ss), max(ss)


# ==============================================================================
#  مين ياخد الاسترند الجاي - مقيس من موقع الكابل في القطاع
# ==============================================================================
#  البرنامج بيوزّع الاسترندات على الكابلات اللي **قريبة** من القراية
#  الراسبة. القُرب مش الفاعلية: الاسترند بيدّي ضغط محوري **وعزم**،
#  والعزم إشارته وقوته بيعتمدوا على إن الكابل عالي ولا غاطس عند النقطة
#  دي بالظبط.
#
#  مقيس على دفتر المهندس (32 دورة، 1,923 زوج، الدورات اللي مساراتها
#  ما اتغيّرتش)، بدلالة `rel` = (عمق الكابل − نص السُمك) ÷ السُمك -
#  سالب يعني الكابل فوق نص السُمك (قمة فوق ركيزة)، وموجب يعني تحت
#  (غطسة في نص البحر):
#
#      موقع الكابل      الوش العلوي   الوش السفلي
#      قمة (rel -0.21)    -0.126        -0.009
#      وسط (rel -0.06)    -0.102        -0.029
#      منخفض (rel 0.09)   -0.090        -0.076
#      غطسة (rel 0.19)    -0.068        -0.161
#
#  يعني استرند في كابل **غاطس** بيدّي للوش السفلي **17 ضعف** اللي
#  بيدّيه استرند في كابل **عالي** عند نفس النقطة. والاتنين بيتكلّفوا
#  نفس الكيلوجرامات.
#
#  ده تفسير سطر حرفي في لوج المهندس: «Still 1 readings over the limit -
#  the same as last round, after **34 strand(s) were added**. They did
#  not close a single section on this face.» 34 استرند في الكابلات
#  الغلط.
#
#  الخطين خطيين بدقة عالية على القياس: الأربع نقط على كل وش بتقع على
#  خط واحد، فالجدول اتكتب كميل وقاطع بدل أربع خانات.

#  (قاطع, ميل) لكل وش - ميجا لكل استرند، عند reach 1.5 م وسُمك 200 مم.
#  القيم دي **نسبية في الاستعمال**: بتقرر الترتيب، مش عدد الاسترندات.
STRAND_INFLUENCE = {"top": (0.0955, -0.145), "bottom": (0.0890, 0.380)}
INFLUENCE_FLOOR = 0.10          # نسبة من قيمة الوسط - مايوصلش صفر أبداً


def tendon_rel_at(tendon, pos, thickness):
    """
    موقع الكابل في القطاع عند نقطة، كنسبة من السُمك.

    سالب = فوق نص السُمك، موجب = تحت. بترجّع None لو مافيش بروفايل.
    """
    pr = (tendon or {}).get("profile") or []
    h = float(thickness or 0.0)
    if len(pr) < 2 or h <= 0:
        return None
    best, depth = float("inf"), None
    for i in range(len(pr) - 1):
        a, b = pr[i]["pos"], pr[i + 1]["pos"]
        dx, dy = b[0] - a[0], b[1] - a[1]
        L2 = dx * dx + dy * dy
        t = 0.0 if L2 <= 1e-12 else max(0.0, min(
            1.0, ((pos[0] - a[0]) * dx + (pos[1] - a[1]) * dy) / L2))
        d = math.hypot(pos[0] - (a[0] + t * dx), pos[1] - (a[1] + t * dy))
        if d < best:
            best = d
            depth = (float(pr[i].get("depth") or 0.0)
                     + (float(pr[i + 1].get("depth") or 0.0)
                        - float(pr[i].get("depth") or 0.0)) * t)
    if depth is None:
        return None
    return (depth - h / 2.0) / h


def strand_influence(face, rel, params=None):
    """
    ميجا لكل استرند عند قراية على `face` من كابل موقعه `rel`.

    مش بتنزل تحت أرضية: كابل عالي فوق ركيزة لسه بيدّي **ضغط محوري**
    للوش السفلي حتى لو عزمه مابيساعدش، وصفر هنا معناه إن الترتيب
    هيرمي كابلات سليمة بره الحساب.
    """
    key = "top" if str(face or "").lower().startswith("t") else "bottom"
    tab = (getattr(params, "strand_influence", None)
           or STRAND_INFLUENCE).get(key, STRAND_INFLUENCE[key])
    c, m = float(tab[0]), float(tab[1])
    if rel is None:
        return c
    return max(c + m * float(rel), abs(c) * INFLUENCE_FLOOR)


def measure_strand_influence(rows, reach=1.5, min_pairs=150):
    """
    الميل والقاطع لكل وش، من دفتر التصميم.

    نفس الأزواج اللي `paired_strand_response` بتستعملها - دورتين
    متتاليتين في نفس الرن والمسارات ما اتغيّرتش - بس الانحدار هنا على
    **متغيّرين**: عدد الاسترندات، وعددهم × موقع الكابل. الأول بيدّي
    القاطع والتاني بيدّي الميل.

    بترجّع {"top": (c, m, n), "bottom": (...)} للأوجه اللي فيها كفاية.
    """
    data = {}
    for a, b in zip(rows, rows[1:]):
        if a.get("proc") and b.get("proc") and a["proc"] != b["proc"]:
            continue
        ta, tb = a.get("tendons") or [], b.get("tendons") or []
        if not ta or not tb:
            continue
        kept = len({_log_path_key(t) for t in ta}
                   & {_log_path_key(t) for t in tb})
        if kept < 0.8 * len(ta):
            continue
        h = float((a.get("params") or {}).get("slab_thickness") or 0.0)
        if h <= 0:
            continue
        ka = {(round(q[0], 2), round(q[1], 2), q[4], q[5]): q
              for q in (a.get("reads") or [])}
        kb = {(round(q[0], 2), round(q[1], 2), q[4], q[5]): q
              for q in (b.get("reads") or [])}
        for k in set(ka) & set(kb):
            qa, qb = ka[k], kb[k]
            d = "X" if str(qa[5]).lower().startswith("x") else "Y"
            na = _log_near(ta, qa[0], qa[1], d, reach)
            nb = _log_near(tb, qb[0], qb[1], d, reach)
            sa = sum(n for n, _z in na)
            sb = sum(n for n, _z in nb)
            if abs(sb - sa) < 1e-9 or sa <= 0:
                continue
            #  الموقع الموزون بالاسترندات - الكابل التقيل بيحكم
            rel = (sum(n * z for n, z in na) / sa - h / 2.0) / h
            data.setdefault(qa[4], []).append((sb - sa, qb[2] - qa[2], rel))
    out = {}
    for face, pts in data.items():
        if len(pts) < min_pairs:
            continue
        #  انحدار بمتغيّرين من غير قاطع: dv = -(c·dn + m·dn·rel)
        s11 = sum(dn * dn for dn, _dv, _r in pts)
        s12 = sum(dn * dn * r for dn, _dv, r in pts)
        s22 = sum(dn * dn * r * r for dn, _dv, r in pts)
        b1 = sum(dn * dv for dn, dv, _r in pts)
        b2 = sum(dn * r * dv for dn, dv, r in pts)
        det = s11 * s22 - s12 * s12
        if abs(det) < 1e-12:
            continue
        c = (b1 * s22 - b2 * s12) / det
        m = (s11 * b2 - s12 * b1) / det
        #  الإشارة: الاسترند بيقلّل الشد، فـ dv سالب - بنخزّن الحجم
        out[face] = (-c, -m, len(pts))
    return out


def report_strand_influence(params, job, reach=None):
    """
    بيقول الجدول اللي الترتيب شغّال بيه، **ومعاه اللي دفترك بيقوله**.

    الجدول مش بيتعاير أوتوماتيك - عن قصد في النسخة دي. اللي اتغيّر في
    السلوك هو الترتيب نفسه، ولو الجدول اتحرّك في نفس الرن يبقى مافيش
    طريقة نعرف بيها أي واحد فيهم عمل الفرق. القياس بيتقال، والقرار
    بعد رن أو اتنين.
    """
    if not job:
        return
    if not bool(getattr(params, "topup_by_influence", True)):
        job.info("    the next strand goes to the nearest tendon with room, "
                 "not the most effective one - 'by influence' is off.")
        return
    lo = strand_influence("bottom", 0.19, params)
    hi = strand_influence("bottom", -0.21, params)
    job.info(f"    the next strand goes to the tendon that does most at the "
             f"failing section, not the nearest one. At a sagging section a "
             f"tendon low there is worth {lo:.3f} MPa a strand against "
             f"{hi:.3f} for one passing over a support - {lo / max(hi, 1e-9):.0f}x "
             f"for the same kilograms.")
    try:
        folder = (str(getattr(params, "design_log_dir", "") or "").strip()
                  or DESIGN_LOG_DEFAULT)
        got = measure_strand_influence(
            list(reversed(read_design_log(folder))),
            float(reach or getattr(params, "shave_reach", 1.5) or 1.5))
    except Exception:
        return
    for face in ("top", "bottom"):
        if face not in got:
            continue
        c, m, n = got[face]
        d = (getattr(params, "strand_influence", None)
             or STRAND_INFLUENCE)[face]
        job.info(f"    {face} face, from {n} paired readings in your own "
                 f"log: {c:+.4f} {m:+.4f} against the {d[0]:+.4f} "
                 f"{d[1]:+.4f} this is using. The table is not tuned on the "
                 f"fly - the ranking is what changed, and two things moving "
                 f"at once cannot be told apart.")


def _log_near(tendons, x, y, direction, reach):
    """[(استرندات, عمق عند أقرب نقطة)] لكابلات الدفتر القريبة."""
    out = []
    for t in tendons:
        if t.get("d") != direction:
            continue
        p = t.get("p") or []
        if len(p) < 2:
            continue
        xs = [q[0] for q in p]
        ys = [q[1] for q in p]
        if (x < min(xs) - reach or x > max(xs) + reach
                or y < min(ys) - reach or y > max(ys) + reach):
            continue
        best, z = float("inf"), None
        for i in range(len(p) - 1):
            ax, ay, az = p[i][0], p[i][1], p[i][2]
            bx, by, bz = p[i + 1][0], p[i + 1][1], p[i + 1][2]
            dx, dy = bx - ax, by - ay
            L2 = dx * dx + dy * dy
            tt = 0.0 if L2 <= 1e-12 else max(0.0, min(
                1.0, ((x - ax) * dx + (y - ay) * dy) / L2))
            d = math.hypot(x - (ax + tt * dx), y - (ay + tt * dy))
            if d < best:
                best, z = d, az + (bz - az) * tt
        if best <= reach and z is not None:
            out.append((float(t.get("n") or 0.0), z))
    return out


def topup_cost_order(members, b, ux, uy, face=None, params=None,
                     site=None, tendons=None):
    """
    **18.27: مين ياخد الاسترند الجاي؟ الأرخص.**

    الاسترندات كانت بتتوزّع بالدور على الكابلات اللي في الخط، بترتيب
    اللستة. وكل كابل في الخط بيدّي نفس الفايدة (`wgt` واحد للخط كله)،
    بس تكلفته مش واحدة: الاسترند بيتحط على **طول الكابل كله** وبيشتغل
    على الجزء اللي بيغطّي الرسوب بس. كابل 22 م بيعدّي 3 م من الحارة
    الراسبة بيكلّف 22 استرند·متر عشان نفس الفايدة اللي كابل 8 م بيديها
    بـ 8.

    فالترتيب بقى بالتكلفة الحقيقية: **استرند·متر لكل متر رسوب مغطّى**.
    نفس القوة بالظبط، نفس عدد الاسترندات، كيلوجرامات أقل - وده بالضبط
    اللي الترتيب الأبجدي مابيعملوش.

    بترجّع نفس عناصر `members` مرتّبة بالأرخص الأول. اللي مش بيغطّي
    حاجة من الحارة بيروح الآخر بدل ما يتشال - لسه أحسن من ولا حاجة.

    **18.72: والكابل اللي في ظل كمرة ساقطة بيروح ورا كل اللي بيشتغل.**
    التكلفة فوق بتقيس طول الكابل مقابل الرفع اللي بيديه، وبتفترض إن
    الكابل ليه عرض بلاطة يشيله. الكابل الماشي جنب كمرة ساقطة ملوش:
    الكمرة هي اللي شايلة، فالاسترند بيدي ضغط محوري وبس. مقيس على
    موديل المهندس: 4 من 31 استرند زايد راحوا لكابلين في ظل كمرة،
    والقطاعات اللي كانوا المفروض يسيّفوها فضلت زي ما هي. مابيتشالش
    من الترتيب - الضغط المحوري حقيقي - بس مابياخدش استرند طالما فيه
    كابل شغّال محتاجه.
    """
    lo, hi = float(b["lo"]), float(b["hi"])
    #  **18.35: والفاعلية، مش الطول بس.** التكلفة كانت استرند·متر لكل
    #  متر رسوب مغطّى - وده بيقارن كابلين بيدّوا نفس الحاجة. مابيدّوش:
    #  الاسترند بيدّي ضغط محوري **وعزم**، والعزم بيعتمد على إن الكابل
    #  عالي ولا غاطس عند القراية دي. على الوش السفلي الكابل الغاطس
    #  بيدّي 17 ضعف الكابل العالي - نفس الكيلوجرامات.
    h = float(getattr(params, "slab_thickness", 0.0) or 0.0)
    use_inf = (face is not None and h > 0
               and bool(getattr(params, "topup_by_influence", True)))
    mid = ((lo + hi) / 2.0 * ux, (lo + hi) / 2.0 * uy)
    if b.get("across") is not None:
        a_c = float(b["across"])
        mid = (mid[0] - a_c * uy, mid[1] + a_c * ux)
    shade = (beam_shadow_ids(tendons if tendons is not None
                             else [m for m, _o in members], site, params)
             if site else set())
    rows = []
    for i, (m, o) in enumerate(members):
        pr = m.get("profile") or []
        if len(pr) < 2:
            rows.append((2, float("inf"), i, (m, o)))
            continue
        length = md_cumulative([q["pos"] for q in pr])[-1]
        span = _along_span_of(m, ux, uy)
        cover = 0.0 if span is None else max(
            min(hi, span[1]) - max(lo, span[0]), 0.0)
        if cover <= 1e-6:
            rows.append((2, float("inf"), i, (m, o)))
            continue
        gain = cover
        if use_inf:
            rel = tendon_rel_at(m, mid, h)
            gain = cover * strand_influence(face, rel, params)
        tier = 1 if id(m) in shade else 0
        rows.append((tier, length / max(gain, 1e-9), i, (m, o)))
    rows.sort(key=lambda r: (r[0], r[1], r[2]))
    return [r[3] for r in rows]


def _treat_beside_full(b, need, tendons, made, params, site, a, z, c, tolb,
                       n_max, face=None):
    """
    **الحارة مليانة؟ الكابلات اللي جنبها بتساعد (17.5).**

    قاعدة المهندس: لما الحارة الراسبة مافيهاش مكان لكابل ولا استرند (كل
    كابل في عرضها عند الحد الأقصى، ومافيش مكان بالمسافة الدنيا)، الكابلات
    بتتزاد **جنب** المنطقة. قبل كده الباقي كان بيتساب: على تصميم من
    المومنت حارات علوية كتير كتبت «full in both senses» كل دورة، والقطاعات
    كانت بتقفل واحد في الدورة.

    من كل ناحية، بره عرض الحارة (`tolb`): أول خط كابلات، وبعده التاني.
    لكل خط: كابل مضاف في الفراغ اللي بينه وبين الحارة (ولو ضيّق، الفراغ اللي
    بعده) بشرط المسافة الدنيا لكل الكابلات الموازية؛ وبعدها استرندات على
    كابلات الخط ده لحد الحد الأقصى لو لسه فيه باقي. الاسترند في الخط الأول
    بيتحسب كامل، وفي التاني بالنص - القوة بتتوزّع، والدورة اللي بعدها
    بتقيس.

    بترجّع (استرندات اتزادت على كابلات موجودة، كابلات مضافة جديدة،
    المكافئ اللي اتحسب من الطلب).
    """
    ux, uy = b["ux"], b["uy"]
    across = b["across"]
    min_gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    ext = float(getattr(params, "efm_added_extend", 2.0) or 2.0)
    step = max(float(getattr(params, "max_spacing", 0.0) or 0.0), 1.5)
    reach_max = tolb + 2.0 * step + 0.5
    loose = MdParams(params, efm_added_min_gap=0.0, efm_added_clear=0.0)
    sts = (b["lo"], (b["lo"] + b["hi"]) / 2.0, b["hi"])
    pool = [t for t in tendons + made
            if not t.get("_deleted") and _parallel_to_u(t, ux, uy)]

    offs = []
    for t in pool:
        vals = [v - across for v in (_across_at(t, s, ux, uy) for s in sts)
                if v is not None]
        if vals:
            vals.sort()
            offs.append((t, vals[len(vals) // 2]))

    rings = []
    for sgn in (1, -1):
        out = sorted([(abs(o), t, o) for t, o in offs
                      if o * sgn > tolb and abs(o) <= reach_max],
                     key=lambda e: e[0])
        groups = []
        for d, t, o in out:
            if groups and d <= groups[-1][0] + 0.3:
                groups[-1][1].append((t, o))
            else:
                groups.append([d, [(t, o)]])
        for k, g in enumerate(groups[:2]):
            rings.append((k, sgn, g[1]))
    rings.sort(key=lambda r: r[0])

    topped, new_list, eff = 0, [], 0.0
    for k, sgn, members in rings:
        if need - eff <= 0.5:
            break
        wgt = 1.0 if k == 0 else 0.5
        t_d, o_d = sorted(members, key=lambda m: (bool(m[0].get("added")),
                                                  abs(m[1])))[0]
        cands = []
        inner = [o for _t, o in offs if sgn * o < sgn * o_d - 0.05]
        if inner:
            cands.append((o_d + max(inner, key=lambda o: sgn * o)) / 2.0)
        outer = [o for _t, o in offs if sgn * o > sgn * o_d + 0.05]
        if outer:
            cands.append((o_d + min(outer, key=lambda o: sgn * o)) / 2.0)
        cands = [p for p in cands if abs(p - o_d) >= min_gap]
        if cands:
            pr = t_d["profile"]
            total = md_cumulative([q["pos"] for q in pr])[-1]
            s_a, _ = _station_of(pr, a)
            s_z, _ = _station_of(pr, z)
            lo, hi = sorted((s_a, s_z))
            plan = {"donor": t_d, "lo": max(0.0, lo - ext),
                    "hi": min(total, hi + ext), "total": total, "ext": ext,
                    "runs": [[{"name": f"beside@{b['cx']:.0f},{b['cy']:.0f}",
                               "a": a, "b": z, "mid": c}]]}
            try:
                new = build_added_tendon(plan, tendons + made + new_list,
                                         loose, site)
            except Exception:
                new = None
            if new is not None and new.get("_normal") and new.get("_base"):
                nx, ny = new["_normal"]
                proj = -nx * uy + ny * ux
                others = pool + new_list
                for p in (cands if abs(proj) > 0.5 else []):
                    shift = (p - o_d) / proj
                    pts = [(bb[0] + nx * shift, bb[1] + ny * shift)
                           for bb in new["_base"]]
                    worst = 1e9
                    for o in others:
                        ops = [q["pos"] for q in o["profile"]]
                        for pp in (pts[1:-1] or pts):
                            for i2 in range(len(ops) - 1):
                                worst = min(worst, md_seg_dist(
                                    pp, ops[i2], ops[i2 + 1]))
                    if worst < min_gap:
                        continue
                    for q, pp in zip(new["profile"], pts):
                        q["pos"] = pp
                    n2 = _clamp_strands(
                        max(int(math.ceil((need - eff) / wgt - 1e-9)), 1),
                        params)
                    new["strands"] = n2
                    new["span_keys"] = []
                    new["spans"] = [plan["runs"][0][0]["name"]]
                    new["from_deficit"] = {"spm": b["spm"], "width": b["width"],
                                           "readings": b["n"],
                                           "run": plan["hi"] - plan["lo"],
                                           "beside": k + 1}
                    new_list.append(new)
                    offs.append((new, p))
                    eff += n2 * wgt
                    break
        #  الأرخص الأول - نفس الاسترندات، استرند·متر أقل
        order = (topup_cost_order(members, b, ux, uy, face=face,
                                  params=params, site=site,
                                  tendons=tendons)
                 if bool(getattr(params, "topup_by_benefit", True))
                 else list(members))
        room = [m for m, _o in order if int(m.get("strands") or 0) < n_max]
        while need - eff > 0.5 and room:
            for m in list(room):
                if need - eff <= 0.5:
                    break
                n_now = int(m.get("strands") or 0)
                if n_now >= n_max:
                    continue
                m["strands"] = n_now + 1
                m["_topped"] = int(m.get("_topped") or 0) + 1
                topped += 1
                eff += wgt
            room = [m for m in room if int(m.get("strands") or 0) < n_max]
    return topped, new_list, eff


def relieve_other_direction(tendons, plots, params, job=None, memo=None,
                            hist=None, blame=1.5, reach=1.5):
    """
    **خفّف الحمل اللي جاي على القطاع الراسب من الاتجاه التاني (17.5).**

    قاعدة المهندس: الكابل في الاتجاه التاني قمته فوق المنطقة الراسبة
    بتنزّل عليها حمل. تقليل ارتفاع القمة دي بيقلّل الحمل ده - **من غير ما
    يأثّر على نتيجة الاتجاه التاني**.

    فالقمة بتنزل خطوة (`efm_cross_relief_mm`) بس لو:
      · فيه قطاع راسب في الاتجاه المعاكس على بُعد `blame` منها؛
      · والوشّين في اتجاهها هي اتقروا، وكل قراءاتهم على البحرين اللي حواليها
        لسه تحت الحد بالهامش (`efm_cross_relief_margin`).
    ومايعدّيش نص السُمك.

    **والحكم بالقياس:** `memo` بيفتكر اللي اتنزّل وعدّ الاتجاه ده ساعتها
    (من `hist`، عدّ القراءات الراسبة لكل وش/اتجاه). الدورة اللي بعدها لو
    الاتجاه ده بقى عنده قراءات راسبة أكتر، القمم اللي اتنزّلت فيه بترجع
    مكانها وماتتلمسش تاني.

    بترجّع (اتنزّلت, اتمنعت, اترجّعت, تفاصيل).
    """
    step = float(getattr(params, "efm_cross_relief_mm", 25.0) or 25.0)
    margin = float(getattr(params, "efm_cross_relief_margin", 0.60) or 0.60)
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    mid = h / 2.0
    memo = memo if memo is not None else {}

    plots = [pl for pl in (plots or []) if pl is not None
             and pl.limit is not None
             and getattr(pl, "direction", None) in ("x", "y")]

    def _count(d):
        """
        كل القراءات فوق الحد في الاتجاه ده على الوشّين - جوّه متناول الشد
        وبرّه - ومجموع الزيادة بالميجا. (17.5.1) العدّ على اللي في المتناول
        بس كان بيعدّي قراءة بقت أسوأ لحد ما خرجت من المتناول: 0.28 -> 0.9
        ميجا فوق، والعدّ **نزل**.
        """
        fs = {pl.face for pl in plots if pl.direction == d}
        if not {"top", "bottom"} <= fs:
            return None
        n, ex = 0, 0.0
        for pl in plots:
            if pl.direction == d:
                for _x, _y, v, lim in pl.failing():
                    n += 1
                    ex += v - lim
        return (n, round(ex, 3))

    reverted = 0
    worse = {}
    for d, before in (memo.get("snap") or {}).items():
        now = _count(d)
        if now is None or before is None:
            continue
        if now[0] > before[0] or now[1] > before[1] + 0.10:
            worse[d] = (before, now)
    for e in (memo.get("last") or []):
        if e["dir"] not in worse:
            continue
        t, q = e["t"], e["q"]
        if t.get("_deleted") or not any(r is q for r in
                                        (t.get("profile") or [])):
            continue
        if abs(float(q.get("depth") or 0.0) - e["new"]) > 0.5:
            continue
        q["depth"] = e["d0"]
        q["_relief_blocked"] = True
        q["_relieved"] = round(max(0.0, float(q.get("_relieved") or 0.0)
                                   - (e["new"] - e["d0"])), 1)
        reverted += 1
    if job and worse:
        job.log("Relieving a failing section from the other direction", "head")
        for d, (b0, n0) in sorted(worse.items()):
            job.warn(f"The high points lowered last round in "
                     f"{_dir_name(d)} were checked against that direction's "
                     f"own result: {b0[0]} reading(s) over the limit before "
                     f"({b0[1]:.2f} MPa over in total), {n0[0]} now "
                     f"({n0[1]:.2f} MPa). It came out worse, so they are put "
                     f"back where "
                     f"they were ({reverted} point(s)) and left alone from "
                     f"here - the relief is not allowed to cost the other "
                     f"direction its result.")
    memo["last"] = []
    memo["snap"] = {}

    if not plots or not tendons:
        return 0, 0, reverted, []
    fails = [(pl.direction, pl.face, x, y, v, lim)
             for pl in plots for x, y, v, lim in pl.failing()]
    if not fails:
        return 0, 0, reverted, []
    faces = {"x": set(), "y": set()}
    readings = {"x": [], "y": []}
    for pl in plots:
        faces[pl.direction].add(pl.face)
        for x, y, v in pl.demand:
            readings[pl.direction].append((x, y, v, pl.limit))
    lowered = blocked = 0
    unseen = set()
    detail = []
    done = set()
    for dfail, face, fx, fy, fv, flim in fails:
        other = "y" if dfail == "x" else "x"
        if not {"top", "bottom"} <= faces[other]:
            unseen.add(other)
            continue
        for t in tendons:
            if t.get("_deleted") or str(t.get("dir", "")).lower() != other:
                continue
            pr = t.get("profile") or []
            for i in range(1, len(pr) - 1):
                q = pr[i]
                if (not q.get("high") or q.get("manual_level")
                        or q.get("_relief_blocked")):
                    continue
                key = (id(t), i)
                if key in done:
                    continue
                if md_dist((fx, fy), q["pos"]) > blame:
                    continue
                d0 = float(q.get("depth") or 0.0)
                if d0 >= mid - 1.0:
                    continue
                done.add(key)
                ia = i - 1
                while ia > 0 and not pr[ia].get("high"):
                    ia -= 1
                ib = i + 1
                while ib < len(pr) - 1 and not pr[ib].get("high"):
                    ib += 1
                seg = [r["pos"] for r in pr[ia:ib + 1]]
                gap = None
                for x, y, v, lim in readings[other]:
                    dd = min(md_seg_dist((x, y), seg[k], seg[k + 1])
                             for k in range(len(seg) - 1))
                    if dd <= reach:
                        g = lim - v
                        gap = g if gap is None else min(gap, g)
                if gap is None or gap < margin:
                    blocked += 1
                    continue
                new = min(mid, d0 + step)
                if new - d0 < 1.0:
                    continue
                q["depth"] = new
                q["manual"] = True
                q["_relieved"] = round(float(q.get("_relieved") or 0.0)
                                       + new - d0, 1)
                lowered += 1
                memo["last"].append({"t": t, "q": q, "d0": d0, "new": new,
                                     "dir": other})
                if other not in memo["snap"]:
                    memo["snap"][other] = _count(other)
                if len(detail) < 8:
                    detail.append((tuple(q["pos"]), d0, new,
                                   f"{face}_{dfail}", fv - flim, gap))
    if job:
        if (lowered or blocked) and not worse:
            job.log("Relieving a failing section from the other direction",
                    "head")
        if lowered:
            job.ok(f"{lowered} high point(s) of tendons running the OTHER way "
                   f"sit within {blame:.1f} m of a section over the limit and "
                   f"were lowered {step:.0f} mm, so the load their peak brings "
                   f"down onto that section comes down with them. Each one's "
                   f"own direction is at least {margin:.2f} MPa under the "
                   f"limit on both faces in the spans either side, and the "
                   f"next round checks that direction did not get worse - if "
                   f"it did, they go back. Never past mid-depth ({mid:.0f} mm).")
            for pos, a0, b0, tag, over, gp in detail:
                job.info(f"    ({pos[0]:.1f}, {pos[1]:.1f}) {a0:.0f} -> "
                         f"{b0:.0f} mm below the top, over {tag} +{over:.2f} "
                         f"MPa; its own direction {gp:.2f} MPa under the limit")
        if blocked:
            job.info(f"    {blocked} more high point(s) sit over a failing "
                     f"section across them, but their own direction has less "
                     f"than {margin:.2f} MPa to spare there (or no reading to "
                     f"show it) - lowering them would move the problem, not "
                     f"solve it.")
        if unseen:
            job.info("    the relief needs both faces of the direction it "
                     "lowers, and " + " and ".join(
                         _dir_name(d) for d in sorted(unseen))
                     + " was not read on both - set the faces to check to "
                       "both on the EFM page.")
    return lowered, blocked, reverted, detail


def tendons_from_deficit(plot, tendons, params, site=None, job=None,
                         strip=12.0, record=None, spans=None, budget_kg=None):
    """
    **يرسم الكابلات اللي القطاعات الراسبة محتاجاها** - من العجز نفسه،
    مش من كيلوجرامات الحديد.

    الفرق عن الحلقة القديمة كامل: هي كانت بتقول "البحر ده حديده تقيل،
    زوّد استرند وشوف" - قياس ناتج، ودورات. هنا الطلب معروف بالرقم من
    فحص رام نفسه: كل قراءة راسبة بتترجم استرندات لكل متر، القراءات
    بتتلمّ على **حاراتها**، وكل حارة بتاخد الكابلات اللي بتوصّل الرقم
    على عرضها، بطول يغطّي الرسوب كله - مرة واحدة.

    بترجّع (الكابلات الجديدة، تقرير).
    """
    rows = plot_deficits(plot, params, tendons=tendons)
    #  17.80: الأماكن اللي استراندادتها اتشالت تاني في جولة سابقة (زوّدت
    #  الضرر) مابتاخدش تاني في الرن ده
    _blk = list(getattr(params, "_efm_blocked", None) or [])
    if _blk and rows:
        _keep = [r for r in rows
                 if not any(math.hypot(float(r["x"]) - bx, float(r["y"]) - by) <= 1.0
                            for bx, by in _blk)]
        if len(_keep) < len(rows) and job:
            job.info(f"    {len(rows) - len(_keep)} reading(s) sit where strands "
                     f"were taken back out earlier in this run - left for "
                     f"depth, a moved high point or reinforcement.")
        rows = _keep
    hopt = bool(getattr(params, "hopt_after_draw", False))
    if hopt:
        #  **18.95: H optimization بعد الرسم**.
        #  هذه الحركة لا تزيّد على أي بحر: هي تراجع فقط القراءات اللي
        #  لسه فوق الحد، وتحافظ على التخطيط الحالي كل ما كان آمن.
        #  فلو ما فيش قراءة راسبة في اللوحة، ما تتعملش إضافة، وما تيجيش
        #  لها بقايا من التزويد أو الانشطار. ده هو قصور الـ H optimization
        #  الحقيقي: التعديل في القصور فقط، لا في كل الحارة.
        rows = [r for r in rows if float(r.get("over") or 0.0) > 0.0]
        if not rows:
            if job:
                job.info("H optimization: the current layout is already safe "
                         "on this section plot, so the pass preserves it and "
                         "adds nothing.")
            return [], {"bands": 0, "made": 0, "strands": 0,
                        "hopeless": 0, "skipped": 0}
        if job:
            job.info(f"H optimization: {len(rows)} still-failing reading(s) "
                     f"are being treated; already-safe sections are left alone.")
    if not rows:
        return [], {"bands": 0, "made": 0, "strands": 0, "hopeless": 0,
                    "skipped": 0}
    gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    n_max = max(int(getattr(params, "max_strands", 5) or 5), n_min)
    max_spm = n_min / max(gap, 0.05)
    beyond = {id(d) for d in unreachable_by_prestress(rows, tendons, params)}
    workable = [r for r in rows
                if r["strands_per_m"] <= max_spm and id(r) not in beyond]
    hopeless = len(rows) - len(workable)

    #  **الوش العلوي بيتعالج من البحر المجاور.** القراءة الراسبة فوق
    #  بتقع عند العمود، والكابل القصير فوق العمود مالوش غطس يعمله -
    #  قمته عند الغطاء أصلاً. اللي بيسيّفها هو الرفع في البحر اللي
    #  جنبها. والكابولي هو الاستثناء: مالوش بحر يوازنه.
    if (plot.face == "top") and spans:
        workable = top_face_targets(workable, spans, params, job,
                                    direction=getattr(plot, "direction", None))
        for r in workable:
            if r.get("_move_to"):
                r.setdefault("_orig_xy", (float(r["x"]), float(r["y"])))
                r["x"], r["y"] = r["_move_to"]
    #  اتجاه اللوحة هو اتجاه العلاج. من غيره الحارات بتتبني على أقرب
    #  كابل، واللي بيكسب هو الاتجاه المحزّم أصلاً - مش الاتجاه الراسب.
    _dir = getattr(plot, "direction", None)
    bands = deficit_bands(workable, tendons, params, strip,
                          direction=_dir, job=job)
    if hopt:
        #  **18.95: حظر التزوير على الحارات الآمنة**. لو الحارة في
        #  القيم الحالية لا زالت فوق الحد، فهي الوحيدة اللي تمسّها.
        #  أي حارة كانت آمنة قبل التعديل أو أصبحت آمنة داخل نفس التمريرة
        #  تبقى ثابتة، ومجرد أنها في نفس الاتجاه لا يكفي لإدخالها في
        #  تحسين H.
        bands = [b for b in bands if float(b.get("spm") or 0.0) > 0.0]
    if _dir is None and job:
        job.warn("This plot carries no direction, so the bands below take "
                 "the direction of whatever tendon happens to sit closest "
                 "to each reading. On a floor banded hard one way that is "
                 "always the banded way, which is how strands pile into a "
                 "direction that was never short. Tell the loop which "
                 "direction this export is and it will draw in that "
                 "direction only.")
    #  **القياس بدل التخمين**: لو الرن اللي فات ساب سجل، كل حارة اتعالجت
    #  فيه بنعرف عنها حاجتين بالرقم - كام استرند اتحطّ، والإجهاد اتحرّك
    #  كام عند قراءاتها. القسمة بينهم هي استجابة المكان ده بالذات على
    #  البلاطة دي، مش على الورق. والحساب اللي جاي بيتعمل بالرقم ده.
    tolb = max(float(getattr(params, "max_spacing", 0.0) or 0.0), 1.5)
    meas = measured_response(record, plot, params) if record else {}
    if isinstance(meas, dict) and "_mismatch" in meas:
        what, was, now = meas["_mismatch"]
        if job:
            job.warn(f"The record beside this model was written against a "
                     f"different plot - its {what} is {was} and this "
                     f"export's is {now}. A shortfall measured over one "
                     f"limit cannot be subtracted from a shortfall measured "
                     f"over another, so nothing is calibrated from it and "
                     f"this pass is priced on paper. Delete the stale "
                     f"<model>_stress_bands.json and the next pair will "
                     f"start the measurement cleanly.")
        meas = {}
    med_resp = response_factor(meas, params, job) if meas else None
    theory = theory_mpa_per_spm(params, rows)
    if job and rows and any(q.get("n_tendons") for q in rows):
        _ax = float(params.force_per_strand) / max(
            float(getattr(params, "slab_thickness", 280.0) or 280.0), 1e-6)
        _bad = [q for q in rows if q.get("profile_against")]
        _good = [q for q in rows if not q.get("profile_against")]
        job.log("What a strand is actually worth at these sections", "head")
        if _good:
            _g = sorted(q["relief"] for q in _good)
            _gm = _g[len(_g) // 2]
            job.ok(f"{len(_good)} of {len(rows)} failing reading(s) sit "
                   f"where a tendon is on the right side of the section. "
                   f"There a strand is worth {_gm:.3f} MPa per metre of "
                   f"width, not {_ax:.3f} - the difference is the moment "
                   f"its drape makes against the load, taken from where "
                   f"that tendon actually sits in the section, not "
                   f"assumed. Sizing on the axial part alone asked for "
                   f"{_gm / max(_ax, 1e-9):.1f}x the strands those sections "
                   f"need.")
        if _bad:
            job.warn(f"**{len(_bad)} of {len(rows)} failing reading(s) sit "
                     f"at a tendon HIGH point.** The slab is sagging there "
                     f"and the tendon is at the top, so its drape pushes "
                     f"the same way as the load - only the axial part of a "
                     f"strand helps at all, and the bending part works "
                     f"against you.")
            job.info("    they are NOT priced up for that. Dividing by the "
                     "smaller number would have asked for four times the "
                     "strands in the worst possible place; they are priced "
                     "at the axial value and named here instead. The fix is "
                     "to move the point, not to add force - the profile "
                     "check below lists them one by one with the reading "
                     "under each.")
            for q in _bad[:5]:
                job.info(f"    ({q['x']:.1f}, {q['y']:.1f})  "
                         f"{q['over'] + plot.limit:+.2f} MPa with a high "
                         f"point on top of it")

    #  **حد الكجم/م² (17.8).** `budget_kg` = الكجم اللي الحد لسه سايبه.
    #  الحارات بتتعالج من الأرخص للقطاع الواحد للأغلى، والحارة اللي تمنها
    #  (بعد ما تتحط فعلاً) أكبر من الباقي بترجع زي ما كانت وبتتساب.
    _kgm = strand_kg_per_m(params)
    _budget_left = None if budget_kg is None else float(budget_kg)
    _over_budget = []
    if _budget_left is not None:
        _ext_b = float(getattr(params, "efm_added_extend", 2.0) or 2.0)
        bands = sorted(bands, key=lambda b: (
            b["spm"] * b["width"] * (max(b["hi"] - b["lo"], 1.0) + 2.0 * _ext_b)
            / max(int(b.get("n") or 1), 1)))
    made, skipped = [], []
    for b in bands:
        #  17.7: اللي الحارة دي حطّته بالظبط - للشاشة اللي في آخر الرن.
        _gift0 = {id(t): int(t.get("strands") or 0) for t in tendons + made}
        _made0 = len(made)
        if _budget_left is not None and _budget_left <= 0.0:
            b["_gifts"] = []
            _over_budget.append(b)
            continue
        length = max(b["hi"] - b["lo"], 1.0)
        #  هامش التصميم. القياس على رن حقيقي: 26 حارة اتعالجت، والقراءات
        #  الراسبة نزلت من 77 لـ 62 - يعني حوالي خُمس بس. السبب إن الحساب
        #  بيفترض إن قوة الكابل بتتوزّع على عرض الحارة اللي قِسناها،
        #  وعملياً بتتوزّع أوسع. وكل دورة تصحيح بتكلّف تصدير لوحة بالإيد،
        #  فالتصويب الزيادة أرخص من دورة إضافية.
        margin = float(getattr(params, "efm_rebalance_margin", 1.3) or 1.0)
        #  لو المكان ده اتقاس، الهامش مالوش لزوم: الهامش كان بيغطّي
        #  **نفس** المجهول اللي القياس قفله. بيفضل هامش صغير للضوضاء بس.
        hit = band_response(b, meas, tolb)
        resp = (hit["mpa_per_spm"] if hit else med_resp) or theory
        #  حماية من رقم قياس شاذ: الاستجابة مش هتقل عن رُبع النظري ولا
        #  تزيد عنه. حارة استجابت بـ 0.01 ميجا مش هتطلب 40 ضعف.
        resp = min(max(resp, theory * 0.25), theory)
        scale = theory / resp
        if hit or med_resp:
            margin = float(getattr(params, "efm_rebalance_margin_meas",
                                   1.05) or 1.0)
        b["resp"] = resp
        b["resp_src"] = ("measured here" if hit else
                         ("measured median" if med_resp else "theory"))
        b["scale"] = scale
        want = b["spm"] * b["width"] * margin * scale
        n_new = max(1, int(math.ceil(want / float(n_max))))
        #  التقريب لفوق مرتين بيزوّد: رن حقيقي طلب 32 استرند وحطّ 35.
        #  التقريب بيتعمل على الإجمالي مرة واحدة، والباقي بيتوزّع.
        per = _clamp_strands(max(int(round(want / n_new)), 1), params)
        b["want"] = want
        ux, uy = b["ux"], b["uy"]
        mid = ((b["lo"] + b["hi"]) / 2.0)
        c = (ux * mid - uy * b["across"], uy * mid + ux * b["across"])
        a = (c[0] - ux * length / 2.0, c[1] - uy * length / 2.0)
        z = (c[0] + ux * length / 2.0, c[1] + uy * length / 2.0)
        run = [{"a": a, "b": z, "mid": c, "key": ("plot", 0, 0, 0),
                "name": f"deficit@{b['cx']:.0f},{b['cy']:.0f}",
                "set": "plot", "add": want, "kg": 0.0}]
        got = 0
        for _k in range(n_new):
            pl = plan_added_tendon(run, tendons, params, strip=strip,
                                   site=site)
            if pl is None:
                break
            t = build_added_tendon(pl, tendons + made, params, site)
            if t is None:
                break
            t["strands"] = per
            t["span_keys"] = []
            t["spans"] = [run[0]["name"]]
            t["from_deficit"] = {"spm": b["spm"], "width": b["width"],
                                 "readings": b["n"], "run": length}
            made.append(t)
            got += 1
        #  اللي **اتحطّ فعلاً** - مش اللي اتطلب. ده الرقم اللي الرن الجاي
        #  هيقسم عليه، فلو اتكتب طلب بدل تنفيذ هيطلع القياس غلط.
        #  **الحارة مليانة؟ الاسترندات تروح للكابلات اللي فيها.**
        #  ده كان الفرق الكبير: الحلقة كانت تقول "مافيش مكان لكابل"
        #  وتسيب الحارة من غير أي علاج - على رن حقيقي 46% لـ 75% من
        #  اللي اتطلب مانزلش خالص. والكابل الجديد مش الطريقة الوحيدة
        #  لزيادة القوة: الكابل الموجود بياخد استرندات لحد أقصى العدد
        #  في الإعدادات، من غير ما ياخد أي مساحة زيادة على البلاطة.
        topped = 0
        if got * per < want:
            need = want - got * per
            #  **الحارة اللي ماخدتش حاجة بتاخد استرند على الأقل (17.5.1).**
            #  الاسترند بقى بيتسعّر بالغطس (1.1 ميجا لكل استرند/م بدل 0.35)،
            #  فقراءة فوق الحد بـ 0.1-0.5 ميجا بتطلب أقل من نص استرند،
            #  والتقريب كان بيسيبها صفر كل دورة: «0 of 1 tendons fit - 0
            #  strands still short» والقراءة واقفة مكانها.
            if got == 0:
                need = max(need, 1.0)
            here = []
            for t in tendons + made:
                if t.get("_deleted"):
                    continue
                pr = t.get("profile") or []
                if len(pr) < 2:
                    continue
                tx = pr[-1]["pos"][0] - pr[0]["pos"][0]
                ty = pr[-1]["pos"][1] - pr[0]["pos"][1]
                tn = math.hypot(tx, ty) or 1.0
                if abs(ux * tx / tn + uy * ty / tn) < 0.7071:
                    continue
                #  جوّه عرض الحارة، وعلى امتداد رسوبها
                acr = [-q["pos"][0] * uy + q["pos"][1] * ux for q in pr]
                aln = [q["pos"][0] * ux + q["pos"][1] * uy for q in pr]
                if min(abs(z - b["across"]) for z in acr) > tolb:
                    continue
                if max(aln) < b["lo"] - 1.0 or min(aln) > b["hi"] + 1.0:
                    continue
                if int(t.get("strands") or 0) < n_max:
                    here.append(t)
            #  التوزيع بالتساوي: استرند لكل كابل في كل لفة، عشان
            #  ماينزلش كل الحمل على كابل واحد.
            while need > 0.5 and here:
                for t in list(here):
                    if need <= 0.5:
                        break
                    n_now = int(t.get("strands") or 0)
                    if n_now >= n_max:
                        here.remove(t)
                        continue
                    t["strands"] = n_now + 1
                    t["_topped"] = int(t.get("_topped") or 0) + 1
                    topped += 1
                    need -= 1.0
                if not any(int(t.get("strands") or 0) < n_max for t in here):
                    break
        _bt, _bnew, _beff = 0, [], 0.0
        _bneed = want - got * per - topped
        if got == 0 and topped == 0:
            _bneed = max(_bneed, 1.0)
        if (bool(getattr(params, "efm_beside_full", True))
                and _bneed > 0.5):
            try:
                _bt, _bnew, _beff = _treat_beside_full(
                    b, _bneed, tendons, made, params, site,
                    a, z, c, tolb, n_max,
                    face=getattr(plot, "face", None))
            except Exception as _e:
                _bt, _bnew, _beff = 0, [], 0.0
                if job:
                    job.warn(f"    the tendons beside a full band could not "
                             f"be used: {_e}")
            made.extend(_bnew)
            topped += _bt
        b["beside_eff"] = _beff
        b["beside_new"] = len(_bnew)
        b["topped"] = topped
        b["placed"] = got * per + topped + sum(int(t["strands"]) for t in _bnew)
        _gifts = []
        for t in tendons + made[:_made0]:
            _d = int(t.get("strands") or 0) - _gift0.get(id(t), 0)
            if id(t) in _gift0 and _d > 0:
                _gifts.append((t, _d, False))
        for t in made[_made0:]:
            _gifts.append((t, int(t.get("strands") or 0), True))
        b["_gifts"] = _gifts
        b["kg"] = _kgm * sum(int(d) * tendon_plan_length(t)
                             for t, d, _n in _gifts)
        if _budget_left is not None:
            if _gifts and b["kg"] > _budget_left + 1e-6:
                for t, d, is_new in _gifts:
                    if is_new:
                        made[:] = [x for x in made if x is not t]
                    else:
                        t["strands"] = int(t.get("strands") or 0) - int(d)
                        if t.get("_topped"):
                            t["_topped"] = max(int(t["_topped"]) - int(d), 0)
                b["_gifts"] = []
                b["topped"] = 0
                b["beside_eff"] = 0.0
                b["beside_new"] = 0
                b["placed"] = 0
                _over_budget.append(b)
                continue
            _budget_left -= b["kg"]
        if got < n_new:
            short = max((max(want, 1.0) if got == 0 else want)
                        - got * per - topped
                        - float(b.get("beside_eff") or 0.0), 0.0)
            #  «الحارة مليانة» و«مفيش كابل في الاتجاه ده أصلاً» حالتين
            #  مختلفتين تماماً، والرسالة الواحدة كانت بتخبّي التانية.
            #  الأولى معناها البلاطة مش قادرة تاخد قوة زيادة هنا؛
            #  التانية معناها الاتجاه ده مش محزّم من أوله - وده اللي
            #  محتاج قرار من المهندس، مش استرندات.
            _nd = 0
            if _dir:
                for t in tendons:
                    if t.get("_deleted"):
                        continue
                    pr = t.get("profile") or []
                    if len(pr) < 2:
                        continue
                    ax = pr[-1]["pos"][0] - pr[0]["pos"][0]
                    ay = pr[-1]["pos"][1] - pr[0]["pos"][1]
                    nn = math.hypot(ax, ay) or 1.0
                    if abs((ax if _dir == "x" else ay) / nn) < 0.7071:
                        continue
                    if min(dist((b["cx"], b["cy"]), q["pos"])
                           for q in pr) <= strip:
                        _nd += 1
            if short <= 0.5 and (topped or b.get("beside_eff")):
                #  الحارة اتغطّت من غير كابل جديد: الاسترندات دخلت
                #  الكابلات اللي هناك. ده نجاح، مش نقص - فمابيتسجّلش
                #  في قايمة «مااتغطّتش».
                pass
            elif _dir and got == 0 and _nd == 0:
                skipped.append((b, f"there is no {_dir_name(_dir)} tendon "
                                   f"within {strip:.0f} m of this band to "
                                   f"copy a profile from, so nothing could "
                                   f"be drawn. This part of the floor is "
                                   f"not banded in {_dir.upper()} at all - "
                                   f"it needs a new band laid out, which is "
                                   f"a layout decision, not a strand count."))
            else:
                skipped.append((b, f"{got} of {n_new} tendons fit"
                                   + (f", and {topped} strand(s) went into "
                                      f"the tendons already there"
                                      if topped else "")
                                   + f" - {short:.0f} strands still short. "
                                     f"Every tendon in that band is at the "
                                     f"maximum strand count and there is no "
                                     f"room for another at the minimum gap: "
                                     f"it is full in both senses."
                                   + (f" The tendons beside it took the "
                                      f"equivalent of "
                                      f"{float(b.get('beside_eff') or 0):.0f} "
                                      f"strand(s) of it."
                                      if b.get("beside_eff") else "")))

    strands = sum(int(t["strands"]) for t in made)
    topped_all = sum(int(b.get("topped") or 0) for b in bands)
    strands += topped_all
    wanted = sum(b.get("want", 0.0) for b in bands)
    if job:
        job.log("Re-banding from the section check", "head")
        _thin = list(getattr(params, "_thin_rejects", None) or [])
        if _thin:
            job.info(
                f"{len(_thin)} new tendon(s) were not drawn because a "
                f"parallel one with room to spare was already within "
                f"{float(getattr(params, 'thin_neighbour_gap', 0.75)):.2f} m "
                f"- the closest was {min(_thin):.2f} m away. Their strands "
                f"went onto the tendons already in those lanes instead. Two "
                f"thin tendons half a metre apart are twice the anchorages "
                f"and twice the ducts for the force one thicker tendon "
                f"carries.")
            params._thin_rejects = []
        job.ok(f"{len(bands)} failing band(s) on the plot · {len(made)} "
               f"tendon(s) drawn, {strands} strands in total. Each one runs "
               f"the length of the failure in its band, not a patch over "
               f"each reading.")
        _bs = sum(int(b.get("beside_new") or 0) for b in bands)
        _be = sum(float(b.get("beside_eff") or 0.0) for b in bands)
        if _be > 0:
            job.ok(f"Full bands passed the equivalent of {_be:.0f} strand(s) "
                   f"to the tendons beside them - {_bs} added tendon(s) in the "
                   f"gaps next to the band, the rest onto the next line of "
                   f"tendons out. A strand on the first line out counts in "
                   f"full, on the second at half; the next round measures "
                   f"what it closed.")
        if topped_all:
            job.ok(f"{topped_all} of those went into tendons that were "
                   f"already there, in bands with no room for another one "
                   f"at the {gap:.2f} m minimum gap. A full band is not a "
                   f"band that has to go untreated - the force goes up the "
                   f"tendons in it instead, and it costs no extra width on "
                   f"the slab.")
        for t in made[:8]:
            f = t["from_deficit"]
            job.info(f"    {t['strands']} strands over {t['length']:.0f} m - "
                     f"{f['spm']:.2f} strands per metre across {f['width']:.1f} "
                     f"m, closing {f['readings']} reading(s) over "
                     f"{f['run']:.0f} m of band")
        n_here = sum(1 for b in bands if b.get("resp_src") == "measured here")
        if meas:
            n_up = sum(1 for b in bands if (b.get("scale") or 1.0) > 1.05)
            job.ok(f"{n_here} of {len(bands)} band(s) were priced from a "
                   f"reading taken on this floor, the rest from the median "
                   f"of those. {n_up} band(s) came out heavier than the "
                   f"paper figure would have asked for - that gap is what "
                   f"the first pass was short by.")
        else:
            job.info("    No previous record beside this model, so this pass "
                     "is priced on paper. It writes down what it placed and "
                     "where; the next export lets it price itself on what "
                     "actually moved.")
        if skipped:
            job.warn(f"{len(skipped)} band(s) could not be covered:")
            for b, why in skipped[:5]:
                job.warn(f"    at ({b['cx']:.1f}, {b['cy']:.1f}) - {why}")
        if hopeless:
            job.warn(f"{hopeless} reading(s) are past what any spacing can "
                     f"deliver and were left out on purpose - depth, a drop "
                     f"or reinforcement, not prestress.")
        _shad = list(getattr(params, "_shadow_rejects", None) or [])
        if _shad:
            job.flag(f"{len(_shad)} tendon(s) the bands asked for would have "
                     f"landed in the shadow of a downstand beam and were not "
                     f"drawn. The beam is a support: the slab spans BETWEEN "
                     f"the beams, so a tendon laid alongside one has almost "
                     f"no width to carry and balances almost nothing - it "
                     f"buys precompression, the section stays over the "
                     f"limit, and the next round asks for more. Steel on a "
                     f"beam line belongs IN the beam, profiled to the beam's "
                     f"depth, where the drape is several times the slab's.")
            for x, y, d in _shad[:5]:
                job.warn(f"    at ({x:.1f}, {y:.1f}) - beside a beam "
                         f"{d:.0f} mm deep")
            try:
                params._shadow_rejects = []
            except Exception:
                pass
        used_m = (float(getattr(params, "efm_rebalance_margin_meas", 1.05))
                  if meas else
                  float(getattr(params, "efm_rebalance_margin", 1.3)))
        job.info(f"Asked for {wanted:.0f} strands across the failing bands "
                 f"(a {used_m:.2f} design margin is included), placed "
                 f"{strands}. Export the plot again from the model this run "
                 f"saves - that export says how many readings are still "
                 f"over, and it is also what prices the pass after this one.")
        if strands < 0.75 * wanted and wanted > 0:
            job.warn(f"Placed {100.0 * strands / wanted:.0f}% of what the "
                     f"bands asked for. The rest did not fit at the minimum "
                     f"gap between tendons, which means those bands cannot "
                     f"be closed by prestress alone at this slab depth - "
                     f"whatever the next export says about them, more "
                     f"strands is not the answer there.")
    if _over_budget and job:
        job.warn(f"{len(_over_budget)} failing band(s) were left without "
                 f"tendons: the kg/m2 limit on the EFM page does not cover "
                 f"them. What the limit left was spent on the bands that cost "
                 f"least per section first; these are left for a solution in "
                 f"the concrete.")
        for _b in _over_budget[:8]:
            job.info(f"    ({_b.get('cx', 0.0):.1f}, {_b.get('cy', 0.0):.1f}) "
                     f"- {_b.get('n', 0)} section(s)")
    return made, {"bands": len(bands), "made": len(made), "strands": strands,
                  "hopeless": hopeless, "skipped": len(skipped),
                  "over_budget": len(_over_budget),
                  "budget_left": _budget_left,
                  "wanted": wanted, "band_list": bands,
                  "measured": len(meas), "resp": med_resp,
                  "theory": theory}


def section_fail_counts(plot, params, tendons):
    """
    القراءات الراسبة على لوحة، متقسّمة: اللي الشد يقدر يقفله، واللي لأ.

    نفس الاختبار اللي report_design_check بيطبعه ("out of reach of
    prestress"): استرند/م أكتر من اللي أي مسافة تقدر توصّله، أو ضغط
    مسبق مطلوب فوق حد P/A. بترجّع (قابلة للعلاج, خارج متناول الشد).
    """
    rows = plot_deficits(plot, params)
    gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    max_spm = n_min / max(gap, 0.05)
    beyond = set()
    if tendons:
        for d in unreachable_by_prestress(rows, list(tendons), params):
            beyond.add(id(d))
    reach = [d for d in rows
             if d["strands_per_m"] <= max_spm and id(d) not in beyond]
    hopeless = [d for d in rows
                if d["strands_per_m"] > max_spm or id(d) in beyond]
    return reach, hopeless


def report_design_check(plot, params, job, site=None, _tend=None):
    """
    تقرير «القطاعات اللي مش سيفة» - ومعاه الحكم إذا كانت القوة هي الحل.

    الرقم اللي بيفصل: أقل مسافة بين كابلين في الإعدادات. لو العجز
    بيطلب كابلات أقرب من كده، القوة مش الحل هناك - المقطع محتاج سُمك
    أو حديد، مش استرندات. مقيس على تصدير حقيقي: الوسيط 1.47 استرند/م
    (كابل كل 1.36 م - معقول تماماً) والأسوأ 9.61 استرند/م (كابل كل 21
    سم - مستحيل). الاتنين في نفس اللوحة.

    ⚠ الأرقام المذكورة تحت اتقاست بقارئ اللوحة **قبل تصحيح الإشارة**
      في 15.0 (كان بيقرا الضغط على إنه شد). فهي توصف سلوك
      نسخة غلط، ومتسيبة هنا للتاريخ بس. الأرقام الصحيحة على نفس
      اللوحة: 23 قراءة راسبة من 538 (4%)، أسوأ فائض 0.75 ميجا،
      وواحدة بس بره متناول البوست تنشن.
    """
    #  **اللوحة دي من الموديل ده أصلاً؟** رن حقيقي وقع في ده: لوحة
    #  اتصدّرت من موديل تاني اتحطّت على موديل، فالفحص قال «قراءة واحدة
    #  راسبة من 413» على سقف اللوحة أصلاً مش شايفة تلته. الكشف بسيط
    #  ومقفول: امتداد الكابلات مقابل امتداد اللوحة.
    #  **القراية من رام مالهاش الفحص ده (17.0).** هي من الموديل المفتوح
    #  نفسه بالتعريف، وقراياتها هي القطاعات اللي اللوحة بتكتب عليها بس -
    #  أطراف البحور وقممها - فامتدادها أضيق من الكابلات. أول رن تجريبي
    #  قال على اتجاه Y «مش من الموديل ده» (6% بره) ومنع الرسم منه.
    if getattr(plot, "source", "") == "ram":
        plot._foreign = False
    elif _tend:
        _pts = [q["pos"] for t in _tend if not t.get("_deleted")
                for q in (t.get("profile") or [])]
        _px = [q[0] for q in plot.demand]
        _py = [q[1] for q in plot.demand]
        if _pts and _px:
            x0, x1 = min(_px), max(_px)
            y0, y1 = min(_py), max(_py)
            out = sum(1 for q in _pts
                      if not (x0 - 2.0 <= q[0] <= x1 + 2.0
                              and y0 - 2.0 <= q[1] <= y1 + 2.0))
            frac = out / float(len(_pts))
            if frac > 0.05:
                job.warn(
                    f"**This plot does not cover this model.** "
                    f"{100.0 * frac:.0f}% of the tendon points in the model "
                    f"lie outside the plot's extent - the model runs "
                    f"{min(q[0] for q in _pts):.1f} to "
                    f"{max(q[0] for q in _pts):.1f} in x and "
                    f"{min(q[1] for q in _pts):.1f} to "
                    f"{max(q[1] for q in _pts):.1f} in y, while the plot "
                    f"covers {x0:.1f} to {x1:.1f} and {y0:.1f} to {y1:.1f}. "
                    f"That is an export taken from a different model, or "
                    f"from a window rather than the whole floor.")
                job.warn(
                    "    Everything below is read off that plot, so it "
                    "describes whatever floor it came from - not this one. "
                    "Export the Section Analysis Plot again from the model "
                    "you are running, over the whole slab, and point the "
                    "setting at it. No tendons will be drawn from this one.")
                plot._foreign = True
            else:
                plot._foreign = False

    lim = plot.limit
    if lim is None:
        job.warn("That export carries no capacity value, so nothing can be "
                 "checked against it. Export the Section Analysis Plot with "
                 "the values shown.")
        return []
    rows = plot_deficits(plot, params)
    n_all = len(plot.demand)
    #  توقيع اللوحة، مطبوع كل مرة. الغلط اللي عاش لحد 14.9 كان إشارة
    #  مقلوبة، وماكانش باين في أي سطر لوج لأن ولا سطر كان بيعرض توزيع
    #  القراءات. السطر ده بيخلّي الغلط ده مستحيل يعدّي ساكت تاني.
    if getattr(plot, "source", "") == "ram" and getattr(plot, "ignored", None):
        job.info("    capacities left out of the limit because they cover "
                 "only a few spans: "
                 + ", ".join(f"{_cv:.2f} MPa in {_cn} span(s)"
                             for _cv, _cn in plot.ignored)
                 + f". Sections there are still judged against {lim:.2f}.")
    for _cv, _cn in ([] if getattr(plot, "source", "") == "ram"
                     else (getattr(plot, "ignored", None) or [])):
        job.warn(f"{_cn} label(s) reading exactly {_cv:.2f} were taken out "
                 f"of the readings before anything was checked. A value "
                 f"that repeats to the decimal at {_cn} places spread "
                 f"across the floor is a capacity, not a stress - RAM "
                 f"writes a capacity for every section, and this floor has "
                 f"more than one.")
        job.info(f"    they used to be counted as sections {_cv - lim:.2f} "
                 f"MPa over the {lim:.2f} limit. They never moved however "
                 f"many strands went in, because they were never stress. "
                 f"The limit itself is untouched at {lim:.2f} - the value "
                 f"is dropped, not promoted.")
    _v = sorted(q[2] for q in plot.demand)
    _t = sum(1 for q in _v if q > 0)
    job.info(f"    plot signature: {n_all} readings from {_v[0]:+.2f} to "
             f"{_v[-1]:+.2f} MPa, median {_v[len(_v) // 2]:+.2f}; {_t} in "
             f"tension (positive) and {n_all - _t} in compression. The "
             f"tension limit on the plot is {lim:.2f}, and the highest "
             f"reading is {100.0 * _v[-1] / lim:.0f}% of it - a plot read "
             f"the right way round tops out near its own limit.")
    if not rows:
        job.ok(f"Every section on the {plot.face} face is inside the "
               f"{lim:.2f} MPa limit - {n_all} readings, none over. Nothing "
               f"to add.")
        return []
    gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    max_spm = n_min / max(gap, 0.05)          # أقصى استرند/م ممكن تنفيذه
    #  الاختبار الحاسم مش المسافات - الضغط المسبق اللي القطاع هيحتاجه.
    tend = list(_tend or [])
    beyond = set()
    if tend:
        for d in unreachable_by_prestress(rows, tend, params):
            beyond.add(id(d))
    workable = [d for d in rows
                if d["strands_per_m"] <= max_spm and id(d) not in beyond]
    hopeless = [d for d in rows
                if d["strands_per_m"] > max_spm or id(d) in beyond]

    job.warn(f"{len(rows)} of {n_all} section readings on the {plot.face} "
             f"face are over the {lim:.2f} MPa limit "
             f"({100.0 * len(rows) / max(n_all, 1):.0f}%). This is RAM's own "
             f"section check, "
             f"{'read straight from RAM' if getattr(plot, 'source', '') == 'ram' else 'read off the plot you exported'}"
             f" - not the "
             f"designed rebar, and not an estimate.")
    med = workable[len(workable) // 2] if workable else None
    if med:
        job.info(f"    the typical shortfall is {med['over']:.2f} MPa = "
                 f"{med['kn_per_m']:.0f} kN per metre of width = "
                 f"{med['strands_per_m']:.2f} strands per metre, which is a "
                 f"{n_min}-strand tendon every "
                 f"{n_min / med['strands_per_m']:.2f} m")
    for d in rows[:5]:
        job.info(f"    ({d['x']:.1f}, {d['y']:.1f})  {d['over']:.2f} MPa "
                 f"over  ->  {d['strands_per_m']:.2f} strands per metre")
    if hopeless:
        pa = [d for d in hopeless if d.get("pa_needed")]
        job.warn(f"{len(hopeless)} of them are out of reach of prestress "
                 f"altogether, and adding force there is how a loop spends "
                 f"strands for nothing. They need depth - a drop, a thicker "
                 f"slab - or reinforcement.")
        if pa:
            pa.sort(key=lambda d: -d["pa_needed"])
            w = pa[0]
            job.warn(f"    the reason, in one number: at "
                     f"({w['x']:.1f}, {w['y']:.1f}) there are already "
                     f"{w['strands_here']} strands within 1.5 m - about "
                     f"{w['pa_now']:.2f} MPa of precompression - and closing "
                     f"the section would need {w['pa_needed']:.2f} MPa in "
                     f"total. A slab is normally designed at 1 to 2.5.")
        else:
            job.warn(f"    the closest one would need "
                     f"{hopeless[0]['strands_per_m']:.1f} strands per metre, "
                     f"a tendon every "
                     f"{n_min / hopeless[0]['strands_per_m']:.2f} m, under "
                     f"the {gap:.2f} m minimum spacing.")
    if workable:
        job.ok(f"{len(workable)} of them are inside what tendons can "
               f"actually deliver - those are the ones worth re-banding "
               f"for.")
    if tend:
        over_provided(plot, tend, params, job)
    return rows


def compare_written_tendons(before_cpt, after_cpt, job=None):
    """
    يقارن الكابلات **في الملفين** - اللي فتحناه واللي كتبناه.

    ليه: الفرق اللي بيظهر في الدورة الأولى قبل أي استرند اتّهمنا فيه
    حاجتين وطلعوا الاتنين بريئين بالقياس - نصف القطر الأدنى (نزّلناه من
    12 لـ 3 والفرق زاد) وقواعد البروفايل (قفلناها والفرق فضل +107 كجم).
    الكلام في الفراغ خلص: الجدول ده بيقول اللي **اتغيّر فعلاً في
    الموديل**، مش اللي إحنا فاكرينه.

    بيقارن: عدد القطع، مجموع الاسترندات، عدد العقد، والمناسيب عند العقد
    المشتركة (بالإحداثي المقرّب لسنتيمتر).
    """
    import sqlite3

    def _read(path):
        con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
        try:
            segs = con.execute("select count(*), coalesce(sum(NumStrands),0) "
                               "from Tendon").fetchone()
            nodes = {}
            for pt, ref, val in con.execute(
                    "select Point0, ElevationReference, ElevationValue "
                    "from TendonNode"):
                q = _ram_pts(pt)
                if not q:
                    continue
                key = (round(q[0][0], 2), round(q[0][1], 2))
                nodes[key] = (ref, float(val or 0.0))
            #  العدد لوحده مابيكفيش: 154 جاك في المكانين مش معناه نفس
            #  الأماكن. الجاك بيتشاور على عقدة، فبناخد إحداثي العقدة.
            jpts = set()
            for (nd,) in con.execute("select TendonNode0 from Jack"):
                q = _ram_pts(nd)
                if q:
                    jpts.add((round(q[0][0], 2), round(q[0][1], 2)))
            jacks = con.execute("select count(*) from Jack").fetchone()[0]
            return {"segs": segs[0], "strands": segs[1], "nodes": nodes,
                    "jacks": jacks, "jpts": jpts}
        finally:
            con.close()

    try:
        a = _read(before_cpt)
        b = _read(after_cpt)
    except Exception as e:
        if job:
            job.warn(f"The before/after tendon comparison could not be run: "
                     f"{e}")
        return None

    same = set(a["nodes"]) & set(b["nodes"])
    gone = len(a["nodes"]) - len(same)
    new_n = len(b["nodes"]) - len(same)
    moved = []
    ref_changed = 0
    for k in same:
        r0, v0 = a["nodes"][k]
        r1, v1 = b["nodes"][k]
        if r0 != r1:
            ref_changed += 1
        if abs(v1 - v0) > 1e-6:
            #  1400 في الملف = 140 مم، فالوحدة عُشر مليمتر.
            moved.append(abs(v1 - v0) * 0.1)                # مم
    out = {"segs": (a["segs"], b["segs"]),
           "strands": (a["strands"], b["strands"]),
           "nodes": (len(a["nodes"]), len(b["nodes"])),
           "jacks": (a["jacks"], b["jacks"]),
           "gone": gone, "new": new_n, "moved": moved,
           "ref_changed": ref_changed}
    if job:
        job.log("What actually changed in the model, file against file",
                "head")
        job.info(f"    tendon segments {a['segs']} -> {b['segs']} · "
                 f"strands {a['strands']:.0f} -> {b['strands']:.0f} · "
                 f"nodes {len(a['nodes'])} -> {len(b['nodes'])} · "
                 f"jacks {a['jacks']} -> {b['jacks']}")
        if gone or new_n:
            job.warn(f"    {gone} node position(s) are gone and {new_n} are "
                     f"new - the tendons were not written back on the same "
                     f"points they came in on.")
        if ref_changed:
            job.warn(f"    {ref_changed} node(s) kept their position but "
                     f"changed elevation DATUM (top cover vs bottom cover vs "
                     f"soffit). Same number against a different datum is a "
                     f"different level.")
        if moved:
            moved.sort()
            job.warn(f"    {len(moved)} node(s) stayed in place but changed "
                     f"level: median {moved[len(moved) // 2]:.0f} mm, worst "
                     f"{moved[-1]:.0f} mm.")
        if a["strands"] != b["strands"]:
            job.warn(f"    the strand total changed "
                     f"{a['strands']:.0f} -> {b['strands']:.0f}.")
        j_moved = len(a["jpts"] ^ b["jpts"])
        if j_moved:
            job.warn(f"    {j_moved} jack position(s) differ between the two "
                     f"files even though the count matches. Stressing from a "
                     f"different end changes the force left after friction "
                     f"with no geometry change at all.")
        if a["jacks"] != b["jacks"]:
            job.warn(f"    the jacks changed {a['jacks']} -> {b['jacks']}. "
                     f"Stressing from one end instead of two changes the "
                     f"force left after friction, so this alone moves the "
                     f"steel with no geometry change at all.")
        changed = (gone or new_n or ref_changed or moved
                   or a["strands"] != b["strands"]
                   or a["jacks"] != b["jacks"] or j_moved)
        if not changed:
            job.ok("    Nothing changed - the tendons went back exactly as "
                   "they came in, on the same nodes, with the same strands "
                   "and the same jacks.")
        out["identical"] = not changed
        #  عدد النقط اللي اتغيّرت مقابل الكل - الحكم بيحتاج النسبة
        out["touched"] = (gone + new_n + ref_changed + len(moved))
        #  **تعريف واحد** لـ "عملياً هي هي"، بيستعمله كل سطر بيحكم على
        #  الفرق. من غيره طلع تناقض حقيقي في رن: سطر بيقول "الكابلات
        #  رجعت زي ما هي (2 عقدة من 1514)" وسطر تاني في نفس اللوج بيقول
        #  "الكابلات اتغيرت على الطريق". الاتنين كانوا بيقروا نفس
        #  المقارنة بعتبتين مختلفتين.
        out["near_same"] = (
            not (a["strands"] != b["strands"] or a["jacks"] != b["jacks"]
                 or j_moved)
            and out["touched"] <= max(3, 0.01 * max(len(a["nodes"]), 1)))
    return out


def total_drape(tendons):
    """
    مجموع الغطس الفعلي: بُعد كل نقطة سفلى تحت الوتر الواصل بين جارتيها.

    ده الرقم اللي الحمل الموازن متناسب معاه طرداً. أي قاعدة بترفع غطسة
    بتاخد من الرقم ده، والحديد السفلي بيعوّض الفرق.
    """
    tot = 0.0
    n = 0
    for t in tendons:
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        for i in range(1, len(pr) - 1):
            if not pr[i].get("sag"):
                continue
            chord = (float(pr[i - 1].get("depth", 0.0))
                     + float(pr[i + 1].get("depth", 0.0))) / 2.0
            tot += max(0.0, float(pr[i].get("depth", 0.0)) - chord)
            n += 1
    return tot, n



def lows_to_peak_stress(tendons, plot, spans, params, job=None,
                        max_frac=None, reach=1.5):
    """
    **يحرّك الغطسة لمكان أقصى شد فعلي - من غير ما يزوّد استرند واحد.**

    الغطسة في نص البحر افتراض، مش قياس. أقصى العزم الموجب بيقع فين
    فعلاً بيتحدد من الأحمال والبحور الجارة والدروب، وممكن يبعد عن
    النص. والكابل بيدّي أكبر رفع عند غطسته - فلو الغطسة مش عند القمة،
    جزء من قوة الكابل بيروح في مكان مش محتاجه.

    ومصدر «فين أقصى شد» موجود قدامنا: **اللوحة نفسها**. إجهاد الوش
    السفلي بيتناسب مع العزم الموجب، فأكبر قراءة شد في البحر هي مكان
    أقصى عزم موجب - مقروءة من رام مش محسوبة عندنا.

    الحركة محدودة بنسبة من البحر (افتراضي 10%)، ومابتعدّيش جيرانها،
    والمنسوب مابيتغيّرش. ده أرخص علاج ممكن: مافيهوش حديد ولا استرند.

    بترجّع (اتحركت, اتمنعت).
    """
    if plot is None or not tendons:
        return 0, 0
    lim = plot.limit
    rows = [(x, y, v) for x, y, v in plot.demand]
    if not rows:
        return 0, 0
    frac = float(max_frac if max_frac is not None
                 else getattr(params, "low_move_frac", 0.10) or 0.10)
    gap = max(float(getattr(params, "min_point_gap", 1.0) or 1.0), 1.0)
    #  **القراءة بتخصّ أقرب كابل ليها، وبس.** اللوحة فيها قطاعات
    #  الاتجاهين، ومن غير القيد ده الكابل الطولي بيتحرّك عشان قراءة
    #  بتاعة شريحة عرضية. القياس اللي كشفها: عدد النقط اللي بتتحرك
    #  بيتغيّر مع مدى البحث - 12% عند 0.8 م و53% عند 5 م. رقم بيعتمد
    #  على إعداد بحث كده مش قياس، ده صدى. المِلكية بتقفلها.
    own = {}
    for ti, t in enumerate(tendons):
        if t.get("_deleted"):
            continue
        for q in (t.get("profile") or []):
            pass
    for ri, (x, y, v) in enumerate(rows):
        if v <= 0:
            continue
        bi, bd = None, 1e18
        for ti, t in enumerate(tendons):
            if t.get("_deleted"):
                continue
            pr = t.get("profile") or []
            if len(pr) < 2:
                continue
            d = min(dist((x, y), q["pos"]) for q in pr)
            if d < bd:
                bd, bi = d, ti
        if bi is not None and bd <= reach:
            own[ri] = bi
    moved = blocked = 0
    capped = 0
    detail = []
    for ti, t in enumerate(tendons):
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 3:
            continue
        mine = [rows[ri] for ri, o in own.items() if o == ti]
        if not mine:
            continue
        st = [0.0]
        for a, b in zip(pr, pr[1:]):
            st.append(st[-1] + dist(a["pos"], b["pos"]))
        for i in range(1, len(pr) - 1):
            q = pr[i]
            if not q.get("sag") or q.get("manual"):
                continue
            #  البحر ده: من القمة اللي قبلها للقمة اللي بعدها
            a = i - 1
            while a > 0 and not pr[a].get("high"):
                a -= 1
            b = i + 1
            while b < len(pr) - 1 and not pr[b].get("high"):
                b += 1
            span = st[b] - st[a]
            if span < 3.0:
                continue
            #  أعلى شد على اللوحة في حدود `reach` من مسار البحر ده
            best, bv = None, -1e18
            for x, y, v in mine:
                s, off = _station_of(pr, (x, y))
                if off > reach or not (st[a] <= s <= st[b]):
                    continue
                if v > bv:
                    bv, best = v, s
            if best is None or (lim and bv < 0.5 * lim):
                continue
            here = st[i]
            #  18.09: حد بالمتر فوق النسبة
            _cap = frac * span
            _mx = float(getattr(params, "low_move_max_m", 0.0) or 0.0)
            if _mx > 0:
                _cap = min(_cap, _mx)
            lo = max(st[i - 1] + gap, here - _cap)
            hi = min(st[i + 1] - gap, here + _cap)
            if hi <= lo:
                blocked += 1
                continue
            newst = max(lo, min(hi, best))
            if abs(best - newst) > 0.05:
                capped += 1
            if abs(newst - here) < 0.10:
                continue
            old = tuple(q["pos"])
            q["pos"] = _profile_point_at(pr, newst)
            q["manual"] = True
            q.pop("_s", None)
            moved += 1
            if len(detail) < 6:
                detail.append((old, q["pos"], abs(newst - here), span, bv))
    if job:
        if moved:
            job.ok(f"{moved} low point(s) were slid to where the slab is "
                   f"actually in most tension, instead of sitting at the "
                   f"middle of the span by assumption. **No strands were "
                   f"added for this** - it is the same prestress, put where "
                   f"the demand is.")
            job.info(f"    the target is read off the plot: the most "
                     f"tensile bottom reading inside each span is where the "
                     f"positive moment peaks. The move is capped at "
                     f"{100.0 * frac:.0f}% of the span and never passes a "
                     f"neighbouring point; the level is untouched.")
            for o, n, mv, sp, v in detail:
                job.info(f"    ({o[0]:.1f}, {o[1]:.1f}) -> ({n[0]:.1f}, "
                         f"{n[1]:.1f}) - {mv:.1f} m along a {sp:.1f} m span, "
                         f"towards a reading of {v:+.2f} MPa")
        else:
            job.info("    Every low point is already within reach of the "
                     "worst tension in its span - there is nothing to gain "
                     "by moving them.")
        if blocked:
            job.info(f"    {blocked} more could not move: the points either "
                     f"side are too close.")
        if capped:
            job.info(f"    {capped} of them wanted to go further than the "
                     f"{100.0 * frac:.0f}% cap allows and stopped at it. If "
                     f"the peak really is that far off centre, the span "
                     f"wants a different route, not a nudged point.")
    return moved, blocked



def _own_readings(tendons, rows, reach=1.5):
    """كل قراءة بتخصّ أقرب كابل ليها: {رقم الكابل: [(x, y, v)]}."""
    out = {}
    for x, y, v in rows:
        bi, bd = None, 1e18
        for ti, t in enumerate(tendons):
            if t.get("_deleted"):
                continue
            pr = t.get("profile") or []
            if len(pr) < 2:
                continue
            d = min(dist((x, y), q["pos"]) for q in pr)
            if d < bd:
                bd, bi = d, ti
        if bi is not None and bd <= reach:
            out.setdefault(bi, []).append((x, y, v))
    return out


def _dir_of(t):
    """اتجاه الكابل كمتجه وحدة من أول نقطة لآخر نقطة."""
    pr = t.get("profile") or []
    if len(pr) < 2:
        return (1.0, 0.0)
    dx = pr[-1]["pos"][0] - pr[0]["pos"][0]
    dy = pr[-1]["pos"][1] - pr[0]["pos"][1]
    n = math.hypot(dx, dy) or 1.0
    return (dx / n, dy / n)


def cross_direction_relief(tendons, plot, params, job=None, reach=1.5,
                           slack=0.5, step_mm=None, blame=1.5):
    """
    **القمة في اتجاه بتزوّد إجهاد الاتجاه التاني - ننزّلها لو اتجاهها
    مش محتاجها.**

    الكابل في X قمته عند الغطاء العلوي بتشيل أقصى انحراف هناك، وحِمل
    الموازنة بتاعه بينزل على الركيزة - والشرايح في Y بتحس الحِمل ده
    زي أي حِمل تاني. فقمة في X ممكن تكون هي سبب قطاع راسب في Y.

    والقرار مش مجاني: تنزيل القمة بيقلّل الغطس في بحور X الجارة،
    فبيقلّل الرفع هناك وبيزوّد الشد السفلي في X. فالتنزيل بيتعمل **بس**
    لما اتجاه الكابل نفسه عنده فسحة - قراءاته تحت `slack` من الحد.

    الحد الأقصى للتنزيل: **نص سُمك البلاطة** - عند المركز الانحراف
    صفر ومافيش فايدة من النزول أكتر.

    مسافتين مختلفتين، ولازم يتفصلوا:
      · `reach` = القراءة بتخصّ أنهي كابل. 1.5 م، والنتيجة ثابتة تحتها.
      · `blame` = القطاع المعاكس على بُعد أد إيه يبقى القمة دي مسؤولة
        عنه. **دي سياسة مش قياس**: العدد بيتغيّر معاها - 14 عند 1.0 م،
        27 عند 1.5، 45 عند 2.0، 85 عند 3.0. الافتراضي 1.5 م لأن ده
        تقريباً طول منطقة الانحناء العكسي (β·L₁ من شغل الحِمل المكافئ)،
        يعني المدى اللي رد فعل القمة بيتوزّع عليه فعلاً. عارفين إنها
        سياسة، ومكتوبة كده.

    بترجّع (اتنزّلت, اتمنعت, تفاصيل).
    """
    if plot is None or not tendons:
        return 0, 0, []
    lim = plot.limit
    if not lim:
        return 0, 0, []
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    mid = h / 2.0
    step = float(step_mm if step_mm is not None else 25.0)
    rows = [(x, y, v) for x, y, v in plot.demand]
    own = _own_readings(tendons, rows, reach)
    dirs = [_dir_of(t) for t in tendons]
    lowered = blocked = 0
    detail = []
    for ti, t in enumerate(tendons):
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        mine = own.get(ti) or []
        #  فسحة الاتجاه ده: أعلى شد على قراءات الكابل نفسه
        my_worst = max([v for _x, _y, v in mine], default=-1e9)
        room = (lim * slack) - my_worst
        for i in range(1, len(pr) - 1):
            q = pr[i]
            if not q.get("high") or q.get("manual"):
                continue
            d0 = float(q.get("depth") or 0.0)
            if d0 >= mid - 1.0:
                continue                       # عند المركز أصلاً
            #  قطاعات راسبة **في الاتجاه المعاكس** حوالين القمة دي
            cross = 0
            worst = 0.0
            for tj, other in enumerate(tendons):
                if tj == ti or other.get("_deleted"):
                    continue
                c = abs(dirs[ti][0] * dirs[tj][0] + dirs[ti][1] * dirs[tj][1])
                if c > 0.35:
                    continue                   # مش متعامد
                for x, y, v in (own.get(tj) or []):
                    if dist((x, y), q["pos"]) <= blame and v > lim:
                        cross += 1
                        worst = max(worst, v)
            if not cross:
                continue
            if room <= 0.0:
                blocked += 1
                continue
            new = min(mid, d0 + step)
            if new - d0 < 1.0:
                blocked += 1
                continue
            q["depth"] = new
            q["manual"] = True
            lowered += 1
            if len(detail) < 6:
                detail.append((q["pos"], d0, new, cross, worst, my_worst))
    if job:
        if lowered:
            job.ok(f"{lowered} high point(s) were LOWERED because they sit "
                   f"over a section failing in the OTHER direction, and "
                   f"their own direction has room to spare. The cap is "
                   f"mid-depth ({mid:.0f} mm) - at the centroid the "
                   f"eccentricity is zero and there is nothing left to give.")
            job.info(f"    the test is two-sided: a failing section within "
                     f"{blame:.1f} m across the peak, AND the peak's own "
                     f"readings below {100.0 * slack:.0f}% of the "
                     f"{lim:.2f} MPa limit. Lowering a peak costs drape in "
                     f"its own spans, so it is only done where those spans "
                     f"are not using it.")
            job.info(f"    that {blame:.1f} m is a policy, not a "
                     f"measurement - the count moves with it (14 at 1.0 m, "
                     f"27 at 1.5, 85 at 3.0 on the floor this was measured "
                     f"on). It defaults to the length of the reverse-"
                     f"curvature zone, which is the distance the peak's own "
                     f"reaction is actually spread over.")
            for pos, a, b, n, w, mw in detail:
                job.info(f"    ({pos[0]:.1f}, {pos[1]:.1f}) {a:.0f} -> "
                         f"{b:.0f} mm - {n} section(s) across it at up to "
                         f"{w:+.2f} MPa, its own worst is {mw:+.2f}")
        if blocked:
            job.info(f"    {blocked} peak(s) sit over a failing section "
                     f"across them but their OWN direction has no room - "
                     f"lowering those would move the problem, not solve it.")
        if not lowered and not blocked:
            job.info("    No high point is sitting over a section that is "
                     "failing in the other direction.")
    return lowered, blocked, detail



def lower_peaks_over_tension(marks, params, job=None, cap_frac=0.5,
                             step_mm=None):
    """
    **القمة القاعدة فوق قطاع شغّال موجب: تنزل - لحد نص التخانة وبس.**

    دي آخر حلقة ناقصة في السلسلة. `profile_vs_demand` بتعلّم النقط
    اللي بروفايلها مقلوب على القطاع اللي تحتها، وبتسيبها علامة. وعلى
    السقف ده العلامات دي هي بالظبط القطاعات اللي مابتقفلش: 11 قراءة
    راسبة من 20 تحتها قمة كابل، ورن كامل من تلات دورات نزّل الحديد
    34% وسابهم 20 زي ما هم.

    السبب فيزيائي مباشر: البلاطة عايزة تنزل، والكابل فوق. غطسته بتدفع
    في **نفس اتجاه الحمل**، فالجزء العزمي من كل استرند بيشتغل ضدك -
    وده اللي `strand_relief_mpa` بتقيسه. مافيش عدد استرندات بيقفل
    القطاع ده؛ النقطة هي اللي لازم تتحرك.

    والقيد اللي المهندس حطّه من الأول محفوظ هنا بالحرف: **النزول أقصاه
    نص سُمك البلاطة**. النقطة مابتعديش المحور المحايد، فهي مابتتحولش
    لغطسة - بس تأثيرها العزمي الضار بيروح، والضغط المحوري بيفضل.

    بترجّع (كام نقطة نزلت، متوسط النزول بالمليمتر).
    """
    h = float(getattr(params, "slab_thickness", 280.0) or 280.0)
    cap = h * float(cap_frac)          # أقصى عمق مسموح (من السطح)
    step = float(step_mm if step_mm is not None
                 else getattr(params, "peak_drop_mm", 0.0) or 0.0)
    moved, total = 0, 0.0
    detail = []
    for mk in (marks or []):
        if mk.get("want") != "low":
            continue
        t, i = mk.get("tendon"), mk.get("i")
        pr = (t or {}).get("profile") or []
        if i is None or i <= 0 or i >= len(pr) - 1:
            continue
        q = pr[i]
        if q.get("manual_level"):
            continue
        d0 = float(q.get("depth") or 0.0)
        if d0 >= cap - 1.0:
            continue                    # وصل نص التخانة خلاص
        d1 = min(cap, d0 + step) if step > 0 else cap
        if d1 - d0 < 1.0:
            continue
        q["depth"] = d1
        q["_lowered"] = round(d1 - d0, 1)
        moved += 1
        total += (d1 - d0)
        detail.append((tuple(q["pos"]), d0, d1, mk.get("v")))
    if job and moved:
        job.log("Peaks sitting over a sagging section", "head")
        job.ok(f"{moved} high point(s) were LOWERED towards mid-depth - "
               f"{total / moved:.0f} mm on average, and not one of them "
               f"past {cap:.0f} mm, which is half the slab. **No strands "
               f"were added for this.** A peak over a section in bottom "
               f"tension pushes the same way as the load; dropping it "
               f"takes that away and keeps the axial compression.")
        for pos, d0, d1, v in detail[:6]:
            job.info(f"    ({pos[0]:.1f}, {pos[1]:.1f}) - depth {d0:.0f} -> "
                     f"{d1:.0f} mm below the top, over a reading of "
                     f"{v:+.2f} MPa")
        job.info("    the point stays a high point - it never crosses "
                 "mid-depth and never becomes a dip. What goes away is the "
                 "part of its moment that was working against the section.")
    elif job and marks:
        job.info("    none of the marked peaks could be lowered - they are "
                 "already at or past mid-depth.")
    return moved, (total / moved if moved else 0.0)


def profile_vs_demand(tendons, plot, params, job=None, reach=1.5, near=2.0):
    """
    **البروفايل بيقول إيه، والقطاع في نفس الاتجاه عايز إيه.**

    العلاقة اللي بتربطهم مقيسة على تصديراتك مش مفترضة: إجهاد الوش
    السفلي بيمشي مع العزم خطياً - σ = 0.00686·M − 0.44، بـ R² وسيط
    0.971 لما تتعاير على كل بحر لوحده. يعني اللوحة بتقول مكان العزم
    الموجب والسالب على طول الكابل من غير أي حساب عندنا:

        قراءة **موجبة** (شد سفلي)  = عزم موجب  -> الكابل لازم **تحت**
        قراءة **سالبة قوية** (ضغط) = عزم سالب  -> الكابل لازم **فوق**

    فلو أقصى شد سفلي على الكابل عنده قمة بدل غطسة، الكابل بيشتغل عكس
    بحره: قوته بترفع في مكان مش محتاج رفع، والمكان المحتاج مابياخدش.
    ده مش نقص قوة - ده مسار غلط، وزيادة الاسترندات فيه بتزوّد المشكلة.

    الدالة دي **بتعلّم وتقترح، مابتحركش**. الحركة قرار: ممكن تكون
    القمة هناك عشان دروب أو حيطة، والبرنامج مايعرفش نية الراسم.

    بترجّع [{tendon, i, pos, want, v, why}] وبتحطّ `_want` على النقطة
    عشان المحرّر يرنّ عليها.
    """
    if plot is None or not tendons:
        return []
    lim = plot.limit
    if not lim:
        return []
    rows = [(x, y, v) for x, y, v in plot.demand]
    own = _own_readings(tendons, rows, reach)
    marks = []
    for ti, t in enumerate(tendons):
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        mine = own.get(ti) or []
        if len(pr) < 3 or len(mine) < 2:
            continue
        st = [0.0]
        for a, b in zip(pr, pr[1:]):
            st.append(st[-1] + dist(a["pos"], b["pos"]))
        #  القراءات على محطاتها
        pts = []
        for x, y, v in mine:
            s, off = _station_of(pr, (x, y))
            if off <= reach:
                pts.append((s, v, (x, y)))
        if len(pts) < 2:
            continue
        pts.sort()
        #  أقصى شد سفلي، وأقصى ضغط - الاتنين على نفس الكابل
        hi_v = max(pts, key=lambda q: q[1])
        lo_v = min(pts, key=lambda q: q[1])

        def _nearest(s):
            best, bd = None, 1e18
            for i in range(1, len(pr) - 1):
                d = abs(st[i] - s)
                if d < bd:
                    bd, best = d, i
            return best, bd

        #  1) مكان أقصى شد سفلي: عايز غطسة
        if hi_v[1] > 0.4 * lim:
            i, d = _nearest(hi_v[0])
            if i is not None and d <= near and pr[i].get("high"):
                pr[i]["_want"] = "low"
                marks.append({
                    "tendon": t, "i": i, "pos": tuple(pr[i]["pos"]),
                    "want": "low", "v": hi_v[1],
                    "why": (f"the slab reads {hi_v[1]:+.2f} MPa of BOTTOM "
                            f"tension here - that is a positive moment, and "
                            f"a tendon should be at its LOW point over it. "
                            f"This point is a high point.")})
        #  2) مكان أقصى ضغط سفلي (عزم سالب): عايز قمة
        if lo_v[1] < -0.6 * lim:
            i, d = _nearest(lo_v[0])
            if i is not None and d <= near and pr[i].get("sag"):
                pr[i]["_want"] = "high"
                marks.append({
                    "tendon": t, "i": i, "pos": tuple(pr[i]["pos"]),
                    "want": "high", "v": lo_v[1],
                    "why": (f"the slab reads {lo_v[1]:+.2f} MPa here, which "
                            f"is compression on the bottom - a hogging "
                            f"moment, and a tendon should be at its HIGH "
                            f"point over it. This point is a low point.")})
    if job:
        if marks:
            n_low = sum(1 for q in marks if q["want"] == "low")
            n_high = len(marks) - n_low
            job.warn(f"{len(marks)} profile point(s) are the wrong way round "
                     f"for the section under them - {n_low} sit high where "
                     f"the slab wants the tendon LOW, and {n_high} sit low "
                     f"where it wants it HIGH. A tendon like that lifts "
                     f"where nothing needs lifting, and adding strands to "
                     f"it makes its span worse.")
            job.info("    read off the plot, in the tendon's OWN direction: "
                     "bottom tension is a positive moment (wants a low "
                     "point), bottom compression is hogging (wants a high "
                     "one). Nothing is moved - a peak may be sitting there "
                     "for a drop or a wall, and that is your call.")
            for q in marks[:8]:
                job.warn(f"    ({q['pos'][0]:.1f}, {q['pos'][1]:.1f}) "
                         f"suggest a {q['want'].upper()} point - {q['why']}")
        else:
            job.ok("Every profile point agrees with the section under it - "
                   "the low points are over the sagging, the high points "
                   "over the hogging.")
    return marks


def is_cantilever(span_key, table):
    """البحر ده كابولي؟ - طرف حر، فالعزم السالب عليه بتاعه هو."""
    v = (table or {}).get(span_key) or {}
    return bool(v.get("cantilever"))


def _span_in_direction(a, b, direction):
    """قطعة البحر ماشية في اتجاه اللوحة؟ ("x" / "y"، أو أي اتجاه لو None)."""
    if direction not in ("x", "y"):
        return True
    dx, dy = abs(b[0] - a[0]), abs(b[1] - a[1])
    return dx >= dy if direction == "x" else dy > dx


def top_face_targets(rows, spans, params, job=None, near=2.5, direction=None):
    """
    **الوش العلوي بيتعالج من البحور اللي جنب الركيزة - وفوقها لو فيه بحرين.**

    القطاع الراسب على الوش العلوي بيقع عند الركيزة - عزم سالب. وكابل
    قصير فوق الركيزة مابيعملش حاجة له: القمة هناك عند الغطاء العلوي
    أصلاً. اللي بيسيّفه هو الغطس في البحر اللي جنبه.

    **القاعدة من المهندس (17.1):** الكابلات بتتزاد في البحر اللي جنب
    الركيزة، ولو الركيزة ليها بحر يمين وبحر شمال **الكابل بيكمّل فوق
    الركيزة** ويمشي في البحرين. القديم كان بينقل الهدف لنص بحر واحد -
    أقرب قطعة بحر من غير ما يبص على اتجاهها - فكان بيطلع كابل 6 م في
    نص بحر (على الموديل اللي اتجرّب: 11 من 16 حارة طولها صفر)، والبحر
    التاني ماكانش بياخد حاجة، ومافيش حاجة فوق الركيزة.

    دلوقتي كل قراءة بتطلع **هدفين** على خط البحر في اتجاه اللوحة، بنفس
    رقم الزوج (`_pair`):
      · بحرين: آخر البحر الشمال وآخر البحر اليمين - فالحارة والكابل
        المضاف بيغطّوا البحرين مرة واحدة ومعدّيين فوق الركيزة.
      · بحر واحد (طرف حيطة، بحر طرفي): الركيزة نفسها وآخر البحر.
    "آخر البحر" بيتلاقى بالمشي على قطع البحر المتتالية لحد طرف مكتوب
    عليه AtSupport - مش آخر قطعة. و`deficit_bands` بتلم الأزواج اللي
    فتراتها بتتلامس في حارة واحدة، وتفصل اللي بينها بحور سليمة.

    الكابولي: مالوش بحر يوازنه، فالعلاج مكانه زي ما هو.
    """
    axes = []
    for k, v in (spans or {}).items():
        a, b = v.get("a"), v.get("b")
        if a and b and dist(a, b) > 0.05 and _span_in_direction(a, b, direction):
            axes.append((k, tuple(a), tuple(b), v))

    def unit(a, b):
        L = dist(a, b) or 1.0
        return ((b[0] - a[0]) / L, (b[1] - a[1]) / L)

    def same_ends(s, a, b):
        return ((dist(s[1], a) <= 0.3 and dist(s[2], b) <= 0.3)
                or (dist(s[1], b) <= 0.3 and dist(s[2], a) <= 0.3))

    def far_end(seg, start):
        """من الركيزة `start` على طول القطعة ومابعدها لحد طرف ركيزة."""
        cur = seg
        from_a = dist(seg[1], start) <= dist(seg[2], start)
        for _ in range(40):
            _k, a, b, v = cur
            near_end, far = (a, b) if from_a else (b, a)
            flag = v.get("at_support_b" if from_a else "at_support_a")
            if flag is None or flag:
                return far
            travel = (far[0] - near_end[0], far[1] - near_end[1])
            ua = unit(a, b)
            nxt = None
            for s2 in axes:
                #  نفس القطعة، أو قطعة تانية على نفس الطرفين (شريحة تانية
                #  على نفس الخط) - الرجوع عليها كان بيرجّع الركيزة نفسها
                if s2 is cur or same_ends(s2, a, b):
                    continue
                u2 = unit(s2[1], s2[2])
                if abs(ua[0] * u2[0] + ua[1] * u2[1]) < 0.9:
                    continue
                if dist(s2[1], far) <= 0.3:
                    cand_a, other_end = True, s2[2]
                elif dist(s2[2], far) <= 0.3:
                    cand_a, other_end = False, s2[1]
                else:
                    continue
                if ((other_end[0] - far[0]) * travel[0]
                        + (other_end[1] - far[1]) * travel[1]) <= 0:
                    continue
                nxt, nxt_from_a = s2, cand_a
                break
            if nxt is None:
                return far
            cur, from_a = nxt, nxt_from_a
        return far

    out = []
    n_both = n_one = n_cant = 0
    pair_id = 0
    for r in rows:
        p = (r["x"], r["y"])
        best, bd = None, 1e18
        for k, a, b, v in axes:
            dx, dy = b[0] - a[0], b[1] - a[1]
            L2 = dx * dx + dy * dy
            u = (0.0 if L2 < 1e-12 else
                 max(0.0, min(1.0, ((p[0] - a[0]) * dx
                                    + (p[1] - a[1]) * dy) / L2)))
            d = math.hypot(p[0] - (a[0] + u * dx), p[1] - (a[1] + u * dy))
            if d < bd:
                bd, best = d, (k, a, b, v, u)
        if best is None or bd > 8.0:
            out.append(r)
            continue
        k, a, b, v, u = best
        L = dist(a, b)
        if min(u, 1.0 - u) * L > near:
            out.append(r)
            continue
        if v.get("cantilever"):
            r["_why"] = "cantilever - it has no neighbouring span to balance it"
            n_cant += 1
            out.append(r)
            continue
        E = a if u <= 0.5 else b
        far0 = b if u <= 0.5 else a
        seg0 = (k, a, b, v)
        ua = unit(a, b)
        other = None
        for s2 in axes:
            if s2[0] == k or same_ends(s2, a, b):
                continue
            u2 = unit(s2[1], s2[2])
            if abs(ua[0] * u2[0] + ua[1] * u2[1]) < 0.9:
                continue
            if dist(s2[1], E) <= 0.5:
                f2 = s2[2]
            elif dist(s2[2], E) <= 0.5:
                f2 = s2[1]
            else:
                continue
            #  الناحية التانية من الركيزة، مش نفس الناحية
            if ((far0[0] - E[0]) * (f2[0] - E[0])
                    + (far0[1] - E[1]) * (f2[1] - E[1])) < 0:
                other = s2
                break
        ends = [far_end(seg0, E)]
        if other is not None:
            ends.append(far_end(other, E))
            n_both += 1
        else:
            ends.append(E)
            n_one += 1
        pair_id += 1
        for i, q in enumerate(ends):
            c = dict(r)
            c["_move_to"] = (float(q[0]), float(q[1]))
            c["_span"] = v.get("name") or str(k)
            c["_pair"] = pair_id
            if i:
                c["_dup"] = True
            out.append(c)
    if job and (n_both or n_one or n_cant):
        job.info(f"    {n_both + n_one} top-face reading(s) sit at a support, so "
                 f"the treatment goes into the spans beside it, not onto the "
                 f"support itself: {n_both} with a span on each side get a "
                 f"tendon running through both spans and over the support; "
                 f"{n_one} with a span on one side only get it through that "
                 f"span. Supports whose spans touch share one tendon.")
        if n_cant:
            job.info(f"    {n_cant} of them are over a cantilever, which "
                     f"has no neighbouring span to lift - those are treated "
                     f"where they are.")
    return out


def audit_before_analysis(tendons, params, job=None, site=None):
    """
    فحص الهندسة اللي **بتخنق رام**، قبل ما نبعتله الموديل.

    الحالتين اللي وقّفوا التحليل فعلاً في المشروع ده:
      · كابلين على بُعد صفر من بعض (28 من 28 في اختبار) - التحليل طلع
        من 20 ثانية لـ 44 وبعدين وقف.
      · نصف قطر أقل من الحد (12 من 30 كابل تحت 8 م) - رام وقف في
        الدورة اللي بعدها.
    وكمان نقطتين على نفس الإحداثي في نفس الكابل، وقطعة بطول صفر.

    الفحص ده بيتقال **قبل** التحليل، فلو الرن وقف بعده يبقى السبب مش
    الحاجات دي - وده لوحده يوفّر نص ساعة تخمين.

    بترجّع عدد المشاكل.
    """
    n_dup = n_zero = 0
    worst_pair = (1e9, None)
    pts = []
    for t in tendons:
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        for a, b in zip(pr, pr[1:]):
            d = dist(a["pos"], b["pos"])
            if d < 1e-6:
                n_dup += 1
            elif d < 0.05:
                n_zero += 1
        #  اتجاه الكابل: كابل X وكابل Y **بيتقاطعوا** في المسقط، والمسافة
        #  بينهم عند التقاطع صفر بطبيعتها. الفحص ده عن كابلين ماشيين
        #  **في نفس الاتجاه** وواقعين فوق بعض - أول نسخة كانت بتبلّغ عن
        #  كل تقاطع عادي في البلاطة.
        if len(pr) >= 2:
            ax = pr[-1]["pos"][0] - pr[0]["pos"][0]
            ay = pr[-1]["pos"][1] - pr[0]["pos"][1]
            n = math.hypot(ax, ay) or 1.0
            t["_dir_u"] = (ax / n, ay / n)
        for q in pr[1:-1]:
            pts.append((q["pos"], t))

    #  أقرب نقطتين من كابلين مختلفين - شبكة عشان مانعملش O(n²)
    cell = 1.0        # الجيران في حدود 3 م - أوسع من أي تزاحم حقيقي
    grid = {}
    for pos, t in pts:
        key = (int(pos[0] / cell), int(pos[1] / cell))
        grid.setdefault(key, []).append((pos, t))
    for (cx, cy), items in grid.items():
        near = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                near.extend(grid.get((cx + dx, cy + dy), ()))
        for pos, t in items:
            for pos2, t2 in near:
                if t2 is t:
                    continue
                u1 = t.get("_dir_u")
                u2 = t2.get("_dir_u")
                if u1 and u2 and abs(u1[0] * u2[0] + u1[1] * u2[1]) < 0.70:
                    continue                    # متقاطعين، مش متوازيين
                d = dist(pos, pos2)
                if d < worst_pair[0]:
                    worst_pair = (d, pos)

    bad = 0
    if job:
        if n_dup:
            job.error(f"{n_dup} profile point(s) sit exactly on the point "
                      f"before them - a zero-length tendon segment. RAM can "
                      f"stall on these.")
            bad += n_dup
        if n_zero:
            job.warn(f"{n_zero} profile point pair(s) are closer than 50 mm.")
        d, pos = worst_pair
        if d < 0.05:
            job.error(f"Two tendons come within {d * 1000:.0f} mm of each "
                      f"other at ({pos[0]:.1f}, {pos[1]:.1f}). Tendons lying "
                      f"on top of one another is the geometry that stopped "
                      f"the analysis before - fix it in the editor rather "
                      f"than waiting on RAM.")
            bad += 1
        elif d < 1e8:
            job.info(f"Geometry check before the analysis: closest two "
                     f"tendons running the same way are {d * 1000:.0f} mm "
                     f"apart, and no segment has zero length. If RAM stalls "
                     f"now, it is not this.")
        else:
            job.info("Geometry check before the analysis: no two tendons "
                     "running the same way come within 3 m of each other, "
                     "and no segment has zero length. If RAM stalls now, it "
                     "is not this.")
    return bad


def _run_with_heartbeat(fn, job, label, tick=60.0):
    """
    يشغّل التحليل في خيط جانبي ويفضل يقول إنه شغّال.

    قبل كده كان الاستدعاء بيتعمل في نفس الخيط: RAM يقف، والبرنامج يقف
    معاه، واللوج آخر سطر فيه "Mesh generated" وخلاص - المستخدم قاعد
    قدام شاشة مافيهاش أي إشارة إذا كان فيه حاجة بتحصل ولا الدنيا وقفت.
    وده حصل فعلاً في رن حقيقي.

    مابنقدرش **نوقف** حساب رام من بره - النداء جوّه مكتبته. اللي نقدر
    عليه: نفضّل نقول الوقت كل دقيقة، ونخلّي زرار الإيقاف يشتغل، وبعد
    شوية نقول للمستخدم إيه اللي يبصّ عليه. الخيط daemon، فقفل البرنامج
    مابيستناش رام.
    """
    box = {}

    def _work():
        try:
            box["r"] = fn()
        except BaseException as e:              # noqa: BLE001
            box["e"] = e

    th = threading.Thread(target=_work, daemon=True,
                          name=f"ram-{label}")
    th.start()
    t0 = time.time()
    said = 0
    while th.is_alive():
        th.join(1.0)
        if not th.is_alive():
            break
        job.check()                             # زرار الإيقاف
        mins = (time.time() - t0) / 60.0
        if mins >= said + tick / 60.0:
            said = int(mins)
            job.info(f"RAM is still calculating - {said} min so far. "
                     f"A floor this size normally takes well under a "
                     f"minute.")
            if said in (5, 15, 30):
                job.warn(
                    "If it stays here, the usual causes are in the tendon "
                    "geometry, not in RAM: two tendons lying on top of each "
                    "other, a bend tighter than the duct can take, or a "
                    "profile point outside the slab. The model was saved "
                    "before the analysis started, so nothing is lost - open "
                    "that file in RAM and press Calculate All to see the "
                    "message RAM itself would show.")
    if "e" in box:
        raise box["e"]
    return box.get("r")


def run_model_analysis(session: RamSession, job: Job, mesh_size=None):
    """
    تشغيل التحليل في RAM Concept بعد الرسم.
    أسماء الدالة اختلفت بين الإصدارات، فبنجرّب المتاح ونسجّل اللي اشتغل.
    """
    # The mesh must exist first - this is what "There is no structure to
    # analyze" was telling us.
    job.step(0.88, "Generating the mesh")
    if not generate_mesh_in_ram(session, job, mesh_size):
        return {"ok": False, "method": None, "error": "mesh generation failed"}

    job.step(0.90, "Running the analysis in RAM Concept")
    for target, label in ((session.model, "model"),
                          (session.concept, "concept")):
        for name in RUN_METHODS:
            fn = safe_get(target, name)
            if not callable(fn):
                continue
            try:
                t0 = datetime.datetime.now()
                _run_with_heartbeat(fn, job, f"{label}.{name}")
                dt = (datetime.datetime.now() - t0).total_seconds()
                job.ok(f"Analysis finished in {dt:.1f} s ({label}.{name}).")
                return {"ok": True, "method": f"{label}.{name}", "seconds": dt}
            except CancelledError:
                raise
            except Exception as e:
                job.error(f"{label}.{name}() ran but the analysis failed: {e}")
                return {"ok": False, "method": f"{label}.{name}", "error": str(e)}

    job.warn("No analysis method found in the API. Enable API diagnostics "
             "and send the log, or open the file in RAM and press Calculate All.")
    return {"ok": False, "method": None}


def raise_flagged_points(tendons, flags, params, mm, band=6.0):
    """
    يرفع القمم اللي جوّه البحور المعلّمة - نفس اللي الزرار في المحرّر
    بيعمله، بس من غير شاشة عشان الحلقة تقدر تناديه بين الدورات.

    القمة اللي عند الغطاء الأدنى مبتترفعش: مفيش مكان تروحه، ودي محتاجة
    تتحرك على طول الكابل لحد ما تقف فوق الركيزة - وده قرار هندسي
    مش أوتوماتيك، فبيتقال ومابيتعملش.

    بترجّع (اترفعت, واقفة عند الغطاء).
    """
    moved, stuck = 0, 0
    for f in (flags or []):
        a, b = tuple(f["a"]), tuple(f["b"])
        for t in tendons:
            prof = t.get("profile") or []
            try:
                lo = float(params.covers_for(t.get("dir", "X"))[0])
            except Exception:
                lo = 40.0
            for i, q in enumerate(prof):
                if i == 0 or i == len(prof) - 1 or not q.get("high"):
                    continue
                if _seg_dist(q["pos"], a, b) > band:
                    continue
                d = float(q.get("depth", 0.0))
                if d <= lo + 0.5:
                    stuck += 1
                    continue
                q["depth"] = max(lo, d - float(mm))
                q["manual"] = True
                moved += 1
    return moved, stuck


def move_peaks_onto_supports(bad, tendons, params, job=None,
                             max_move=None, spans=None, passes=3):
    """
    يحرّك القمة المزحلقة **على طول الكابل** لحد طرف البحر - الركيزة.

    ده العلاج الصح للقمة الغلط، مش رفعها. زرار الرفع في المحرّر بيقول
    ده بنفسه: على موديل الاختبار 55 قمة من 57 كانت عند الغطاء العلوي
    أصلاً - مفيش مكان تروح له لفوق.

    القيود، وكلها لازمة عشان الحركة ماتكسرش حاجة تانية:
      · النقطة مابتعدّيش جيرانها: بتقف على بعد الحد الأدنى بين النقط
        من النقطة اللي قبلها واللي بعدها.
      · مسافة الحركة محدودة (افتراضي نص البحر) - القمة اللي محتاجة
        أكتر من كده مش مزحلقة، دي مسار غلط، وده قرار مش حركة نقطة.
      · المنسوب مابيتغيّرش. اللي بيتغيّر هو **المكان على المسار**.
      · بعد الحركة، قواعد البروفايل (الغطسة في نص البحر، نصف القطر
        الأدنى) بتشتغل زي أي دورة - فالغطسات بتترجّع لنص البحور
        الجديدة لوحدها.

    بترجّع (اتحركت, اتمنعت).
    """
    moved = blocked = 0
    #  نفس الحد اللي قواعد البروفايل بتشتغل بيه: متر بين نقطتين.
    gap = max(float(getattr(params, "min_point_gap", 1.0) or 1.0), 1.0)
    detail = []

    def _recentre_sags(t):
        """
        الغطسة بين قمتين بترجع لنص المسافة بينهم.

        من غير الخطوة دي القمة بتقف على بعد متر من الغطسة اللي جنبها
        ومابتوصلش للركيزة: على موديل الاختبار الحركة كانت بتنجح في 25
        قمة من 57 بس. الغطسة اللي المستخدم حطّها بإيده (manual)
        مابتتلمسش.
        """
        pr = t.get("profile") or []
        drop = []
        for k in range(1, len(pr) - 1):
            q = pr[k]
            if not q.get("sag") or q.get("manual"):
                continue
            a, b = pr[k - 1]["pos"], pr[k + 1]["pos"]
            if dist(a, b) < 2.0 * gap:
                #  البحر بقى أقصر من إنه يشيل غطسة والحد الأدنى بين
                #  النقط في نفس الوقت. القاعدة الموجودة أصلاً في
                #  البرنامج بتقول نفس الكلام: الغطسة تتشال، مش تتزنق.
                drop.append(k)
                continue
            q["pos"] = ((a[0] + b[0]) / 2.0, (a[1] + b[1]) / 2.0)
            q.pop("_s", None)
        if drop:
            t["profile"] = [q for k, q in enumerate(pr) if k not in set(drop)]

    freed = 0
    for d in (bad or []):
        t, i = d["tendon"], d["i"]
        prof = t.get("profile") or []
        if i <= 0 or i >= len(prof) - 1:
            continue
        st = [0.0]
        for a, b in zip(prof, prof[1:]):
            st.append(st[-1] + dist(a["pos"], b["pos"]))
        #  الهدف: طرف البحر الأقرب للقمة، **مسقَط على مسار الكابل**
        span = d.get("span") or 0.0
        here = st[i]
        if not d.get("end"):
            blocked += 1
            continue
        want, off_route = _station_of(prof, tuple(d["end"]))
        lim = float(max_move if max_move is not None
                    else getattr(params, "peak_move_max", 0.0) or 0.0)
        if lim <= 0:
            lim = max(0.5 * span, 1.0)
        if abs(want - here) > lim or off_route > 6.0:
            blocked += 1
            continue
        lo = st[i - 1] + gap
        hi = st[i + 1] - gap
        if hi <= lo:
            #  **الجار اللي قافل الطريق غطسة تلقائية؟ شيلها.**
            #  القاعدة دي موجودة أصلاً في البرنامج للغطسة اللي بحرها
            #  قصر: تتشال، مش تتزنق. هي بالظبط نفس الحالة هنا -
            #  القمة عايزة توصل ركيزتها والغطسة اللي جنبها واقفة في
            #  السكة. الغطسة اللي المستخدم حطها بإيده (manual)
            #  مابتتلمسش، والقمة اللي جنبها كمان.
            _kill = None
            for _j in (i - 1, i + 1):
                if _j <= 0 or _j >= len(prof) - 1:
                    continue
                _q = prof[_j]
                if _q.get("sag") and not _q.get("manual"):
                    _kill = _j
                    break
            if _kill is None or len(prof) <= 3:
                blocked += 1
                continue
            del prof[_kill]
            if _kill < i:
                i -= 1
            st = [0.0]
            for a2, b2 in zip(prof, prof[1:]):
                st.append(st[-1] + dist(a2["pos"], b2["pos"]))
            if i <= 0 or i >= len(prof) - 1:
                blocked += 1
                continue
            here = st[i]
            want, off_route = _station_of(prof, tuple(d["end"]))
            lo = st[i - 1] + gap
            hi = st[i + 1] - gap
            freed += 1
            if hi <= lo:
                blocked += 1
                continue
        newst = max(lo, min(hi, want))
        if abs(newst - here) < 0.05:
            blocked += 1
            continue
        pos = _profile_point_at(prof, newst)
        old = tuple(prof[i]["pos"])
        prof[i]["pos"] = pos
        prof[i]["manual"] = True
        prof[i].pop("_s", None)
        prof[i].pop("_peak_off_support", None)
        moved += 1
        _recentre_sags(t)
        if len(detail) < 6:
            detail.append((old, pos, abs(newst - here), span))
    #  تمريرة واحدة مابتوصّلش كل القمم: الجار بيوقّف الحركة عند متر،
    #  والغطسة بترجع لنصّها بعد الحركة فبيبقى فيه مكان جديد. القياس:
    #  57 قمة -> 32 بعد تمريرة، -> 12 بعد تلاتة.
    if spans and passes > 1 and moved:
        again = audit_high_points(tendons, spans, params)
        if again:
            m2, b2 = move_peaks_onto_supports(
                again, tendons, params, None, max_move, spans, passes - 1)
            moved += m2
            blocked = b2
    if job:
        if moved:
            job.ok(f"{moved} high point(s) were slid ALONG their tendon "
                   f"towards the support they belong over - the level was "
                   f"not touched, only the position. This is the fix a peak "
                   f"at the top cover actually needs; lifting it does "
                   f"nothing.")
            for o, n2, mv, sp in detail:
                job.info(f"    ({o[0]:.1f}, {o[1]:.1f}) -> "
                         f"({n2[0]:.1f}, {n2[1]:.1f}) - moved {mv:.1f} m "
                         f"along a {sp:.1f} m span")
        if freed:
            job.info(f"    {freed} of those were blocked by an automatic "
                     f"dip sitting in the way, and the dip was removed to "
                     f"let the peak reach its support - the same rule the "
                     f"program already applies to a dip whose span got too "
                     f"short. A dip you placed by hand is never removed.")
        #  الشفافية على الحاجة اللي الحركة ممكن تكسرها: أقرب نقطتين.
        worst = 1e9
        for t in tendons:
            pr = t.get("profile") or []
            for a, b in zip(pr, pr[1:]):
                worst = min(worst, dist(a["pos"], b["pos"]))
        if moved and worst < gap - 0.01:
            job.warn(f"After the move the closest two points on any tendon "
                     f"are {worst:.2f} m apart, under the {gap:.2f} m "
                     f"minimum - that happens where a peak had to stop "
                     f"beside a dip someone placed by hand, which is not "
                     f"moved automatically. Look at those in the editor.")
        elif moved:
            job.info(f"The closest two points on any tendon are still "
                     f"{worst:.2f} m apart - nothing was crowded by the "
                     f"move.")
        if blocked:
            job.warn(f"{blocked} of them could not be moved: the points "
                     f"either side are too close, or the support is further "
                     f"away than half the span - that is a route to redraw, "
                     f"not a point to nudge. They stay marked in the editor.")
    return moved, blocked


def spans_with_off_peaks(bad, table, reach=6.0):
    """
    البحور اللي فيها قمة مش فوق ركيزة - بمفاتيح جدول البحور.

    دي وصلة الدليلين ببعض. الاختبار الهندسي بيدّي **نقط**، والحلقة بتدّي
    **بحور**؛ ولمّا الاتنين يقعوا على نفس البحر يبقى الكلام مقفول: البحر
    ده مش بيستجيب للقوة، وقمّته فعلاً مش فوق الركيزة.

    وليه لازم الاتنين مع بعض، مش الهندسي لوحده: قِسنا على موديلين.
      · موديل 0056: البحور اللي فيها قمة مزحلقة وسيط حديدها السفلي
        91.6 كجم، واللي مفيهاش 7.2 كجم - و93 بحر من 212 شايلين 73% من
        حديد البلاطة كله. إشارة قوية جداً.
      · موديل 1159: 95.0 مقابل 107.0 كجم - **مفيش فرق، بالعكس شوية**.
    يعني القمة المزحلقة مش دايماً هي السبب: ممكن تكون فوق حرف دروب أو
    فوق ركيزة مش متسجّلة كبحر. فالهندسة **تحذير**، والسلوك (زوّدنا قوة
    وماستجابش) هو **الحكم** - واللي يجتمع عليه الاتنين هو المؤكد.
    """
    out = {}
    for d in (bad or []):
        best, bd = None, 1e18
        for key, v in table.items():
            dd = _seg_dist(d["pos"], v["a"], v["b"])
            if dd < bd:
                best, bd = key, dd
        if best is not None and bd <= reach:
            cur = out.get(best)
            if cur is None or d["u"] > cur["u"]:
                out[best] = d
    return out


def round1_flags(table, tendons, params, face="bottom", top=8):
    """
    البحور اللي تستاهل تبصّ عليها **بعد أول دورة** - من غير ما تستنى
    دورة تانية.

    علامة "البحر ساء بعد ما قوّيناه" محتاجة دورتين بطبيعتها: لازم يكون
    فيه استرندات اتزادت الأول. فبعد الرن الأول ملف العلامات مكانش
    بيتكتب أصلاً، والمهندس بيفتح المحرّر ومش لاقي حاجة متعلّمة - وده
    اللي حصل فعلاً.

    بس الدورة الأولى **عندها** كلام تقوله:
      · أتقل البحور في الحديد المصمّم - دي اللي الحلقة رايحة وراها.
      · القمتين اللي قريبين من بعض لدرجة إن الغطسة بينهم مامتحطّتش -
        الحل هنا قمة واحدة مش اتنين، وده شغل إيد.
      · النقط اللي القاعدة اضطرت ترفعها عشان نصف القطر الأدنى - الكابل
        هناك خسر جزء من غطسه.
    """
    floor = float(getattr(params, "efm_flag_kg", 50.0) or 0.0)
    rows = sorted(table.values(), key=lambda v: -face_kg(v, face))
    out = {}
    for v in rows[:max(int(top), 0)]:
        kg = face_kg(v, face)
        if kg <= floor:
            break
        out[v["key"]] = {
            "name": v["name"], "set": v["set"], "a": list(v["a"]),
            "b": list(v["b"]), "mid": list(v["mid"]),
            "length": v["length"], "worse_kg": round(kg, 1),
            "strands_added": 0, "round": 1,
            "reason": "heaviest designed steel after the first analysis",
            "note": f"{kg:,.0f} kg on the {face} face, "
                    f"{v.get('strands', 0):.0f} strands over it"}

    #  النقط اللي القواعد اتخانقت معاها -> أقرب بحر
    marks = []
    for t in tendons:
        if t.get("_deleted"):
            continue
        for q in (t.get("profile") or []):
            if q.get("_peak_off_support") is not None:
                marks.append((q["pos"],
                              f"a high point here sits "
                              f"{100.0 * float(q['_peak_off_support']):.0f}% "
                              f"of the way into its span instead of over the "
                              f"support - measured off the geometry, before "
                              f"any analysis"))
            elif q.get("_peaks_too_close"):
                marks.append((q["pos"], "two peaks too close to take a dip "
                                        "between them - the fix is one peak, "
                                        "not two"))
            elif q.get("_radius_fixed"):
                marks.append((q["pos"], "the drape here was eased to keep the "
                                        "minimum tendon radius - the tendon "
                                        "lost part of its sag"))
    for pos, why in marks:
        best, bd = None, 1e18
        for key, v in table.items():
            d = _seg_dist(pos, v["a"], v["b"])
            if d < bd:
                best, bd = key, d
        if best is None or bd > 6.0:
            continue
        if best in out:
            #  نفس الجملة بالحرف مرة تانية = نفس المعلومة، مش معلومة
            #  جديدة. رن حقيقي كتب نفس السطر **أربع مرات** على البحر
            #  57-1 لأن أربع نقط على نفس البحر اتعلّمت. العدّ بيقول
            #  الحقيقة؛ التكرار بيخفيها.
            n = out[best].get("_n", {})
            n[why] = n.get(why, 1) + 1
            out[best]["_n"] = n
            out[best]["note"] = " · ".join(
                (w if c < 2 else f"{c} points here: {w}")
                for w, c in n.items())
            continue
        v = table[best]
        out[best] = {
            "name": v["name"], "set": v["set"], "a": list(v["a"]),
            "b": list(v["b"]), "mid": list(v["mid"]),
            "length": v["length"], "worse_kg": round(face_kg(v, face), 1),
            "strands_added": 0, "round": 1,
            "reason": "the profile rules had to fight this span",
            "note": why}
    return out


def load_efm_flags(cpt_path):
    """
    البحور المعلّمة من آخر رن للحلقة، لو ملفها جنب الموديل.

    الاسم بيتبني من اسم الموديل، وبيتشال منه لاحقة الدورة (_EFM_r2)
    عشان تفتح ملف أي دورة وتلاقي نفس العلامات.
    """
    if not cpt_path:
        return []
    stem = os.path.splitext(os.path.basename(cpt_path))[0]
    stem = re.sub(r"_EFM_r\d+$", "", stem)
    path = os.path.join(os.path.dirname(cpt_path), stem + "_EFM_flags.json")
    if not os.path.isfile(path):
        return []
    try:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        spans = list(data.get("spans") or [])
        #  النقط بتتعلّق على الليستة عشان مانكسرش أي نداء قديم بيتوقع
        #  ليستة بحور - نفس القيمة، ومعاها اللي زاد.
        try:
            spans = _FlagList(spans)
            spans.points = list(data.get("points") or [])
        except Exception:
            pass
        return spans
    except Exception:
        return []


class _FlagList(list):
    """ليستة بحور عادية، وشايلة معاها النقط المعلّمة."""
    points = ()


def _marked_points(tendons):
    """
    **النقط المعلّمة، بإحداثياتها - عشان توصل للمحرّر.**

    العلامة بتتحط على النقطة في الذاكرة (`_want`)، والمحرّر بيفتح ملف
    .cpt محفوظ ويقرا الكابلات من الأول - فالعلامة كانت بتضيع بين الرن
    والمحرّر. ملف العلامات كان بيحمل **البحور** بس. دلوقتي بيحمل النقط
    كمان، بإحداثيها وبالاتجاه المقترح، والمحرّر بيلزّقها على أقرب نقطة.
    """
    out = []
    for t in tendons or []:
        if t.get("_deleted"):
            continue
        for q in (t.get("profile") or []):
            w = q.get("_want")
            if not w:
                continue
            out.append({"x": float(q["pos"][0]), "y": float(q["pos"][1]),
                        "want": w, "dir": t.get("dir", "")})
    return out


def apply_marked_points(tendons, points, tol=0.30):
    """بترجّع العلامات على الكابلات بعد ما اتقروا من ملف .cpt."""
    n = 0
    for d in (points or []):
        p = (float(d.get("x", 0.0)), float(d.get("y", 0.0)))
        best, bd = None, 1e18
        for t in tendons or []:
            if t.get("_deleted"):
                continue
            for q in (t.get("profile") or []):
                v = dist(p, q["pos"])
                if v < bd:
                    bd, best = v, q
        if best is not None and bd <= tol:
            best["_want"] = d.get("want")
            n += 1
    return n


def tendon_fingerprint(tendons):
    """
    بصمة حالة الكابلات: العدد، الاسترندات، وكل نقطة بمكانها ومنسوبها.

    الغرض منها سؤال واحد: هل اتغيّرت الكابلات من ساعة آخر حفظ؟ الحلقة
    بتحفظ في **أول** الدورة، فأي شغل بيتعمل بعد الحفظ - تحريك نقطة،
    كابل جديد، استرند مزوّد - مابيوصلش للملف غير لما الدورة اللي
    بعدها ترسم من جديد. آخر دورة مالهاش دورة بعدها.
    """
    out = []
    for t in tendons:
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        out.append((int(t.get("strands") or 0), len(pr),
                    round(sum(q["pos"][0] for q in pr), 4),
                    round(sum(q["pos"][1] for q in pr), 4),
                    round(sum(float(q.get("z") or q.get("level") or 0.0)
                              for q in pr), 4)))
    out.sort()
    return (len(out), tuple(out))


def efm_stall_step(prev_fails, now_fails, stalled, min_close):
    """
    قرار الوقوف على قلّة الجدوى في حلقة الـ EFM، معزول عشان يتجرّب.

    `prev_fails` عدد القراءات فوق الحد **قبل** الدورة دي، `now_fails`
    بعدها. بترجّع (العداد الجديد, هل نقف؟).

    **18.27: وده اتكتب دالة عشان الأول اتكتب جوّه الحلقة وطلع غلط.**
    السطر اللي بيحدّث `prev_fails` كان قبل السطر اللي بيقراها، فالفرق
    كان بيطلع صفر دايمًا مهما كانت الدورة قافلة قد إيه - والحلقة كانت
    بتقف بعد دورتين على طول. على رن المهندس 22:12 قفلت 4 قراءات في
    دورة واحدة (12 → 8) واللوج كتب "it stands at 8, against 8 a round
    ago" ووقف. الحلقة اللي حواليها طولها 800 سطر ومحتاجة جلسة رام،
    فالقرار طلع بره عشان يتقاس لوحده.
    """
    if prev_fails is None or min_close <= 0:
        return 0, False
    stalled = stalled + 1 if (prev_fails - now_fails) < min_close else 0
    return stalled, stalled >= 2


def efm_strand_metres(tendons):
    """مجموع (عدد الاسترندات × الطول) على كل الكابلات الحية."""
    tot = 0.0
    for t in (tendons or []):
        if t.get("_deleted"):
            continue
        pr = t.get("profile") or []
        if len(pr) < 2:
            continue
        L = sum(dist(pr[i]["pos"], pr[i + 1]["pos"])
                for i in range(len(pr) - 1))
        tot += L * int(t.get("strands") or 0)
    return tot


def efm_state_key(sections_over, tendons):
    """
    اللي بيقارن دورة بدورة: (الراسب، ثم الوزن).

    الترتيب مقصود: السلامة قبل الاقتصاد. دورة قفلت قطاع زيادة أحسن من
    دورة أخف حتى لو أتقل، ودورتين بنفس الراسب الأخف فيهم أحسن.
    """
    return (int(sections_over), round(efm_strand_metres(tendons), 3))


def efm_snapshot(tendons):
    """صورة من حالة الاسترندات - (الكابل، عدده، هل هو مشال)."""
    return [(id(t), int(t.get("strands") or 0), bool(t.get("_deleted")))
            for t in (tendons or [])]


def efm_restore(tendons, snap):
    """
    بيرجّع الاسترندات لصورة سابقة، وبيرجّع (كام كابل اتغيّر, فرق الاسترندات).

    الكابل اللي اتضاف بعد الصورة بيتشال - هو مش في الصورة أصلاً.
    """
    want = {i: (n, d) for i, n, d in (snap or [])}
    moved, delta = 0, 0
    for t in (tendons or []):
        key = id(t)
        if key in want:
            n, d = want[key]
            if int(t.get("strands") or 0) != n or bool(t.get("_deleted")) != d:
                delta += n - int(t.get("strands") or 0)
                t["strands"] = n
                t["_deleted"] = d
                moved += 1
        elif not t.get("_deleted"):
            delta -= int(t.get("strands") or 0)
            t["_deleted"] = True
            moved += 1
    return moved, delta


def run_efm_loop(session, tendons, params, job, out_dir, stem,
                 site=None, mesh_size=None, base_kg=None,
                 session_source=None, ask_plot=None, base_over=None):
    """
    الحلقة المقفولة: ارسم -> حلّل -> اقرا الحديد اللي RAM حطّه -> زوّد
    استرندات في البحر اللي قصّر هو بس -> أعد.

    بترجّع {rounds: [...], best: مسار الملف, stopped: السبب}.

    الوقوف: الهدف اتحقق (مفيش نصيحة)، أو المكسب قلّ عن الحد، أو الحديد
    زاد بدل ما ينزل، أو عدد الدورات خلص.
    """
    obj = str(getattr(params, "efm_objective", "report_only") or "report_only")
    if obj not in EFM_OBJECTIVES:
        obj = "report_only"
    hopt = bool(getattr(params, "hopt_after_draw", False))
    if hopt:
        #  **18.95: H optimization بعد الرسم** = نفس حلقة EFM لكن هدفها
        #  "الحفظ على التخطيط الحالي، ومعالجة القطاعات الناقصة فقط".
        #  ما نحتاجش طريقة رسم جديدة، ولا نرسم كابل من الصفر في الموديل
        #  الحالي: نعمل على القطاعات الـ "still short" فقط، ونستعمل
        #  نفس أدوات التزييد/التقشير الموجودة في الـ EFM.
        params.efm_rebalance = True
        params.efm_thin = True
        params.efm_add_tendons = True
        obj = "section_only"
        job.info("H optimization is active after the layout already exists: "
                 "it preserves the current tendons when a section is safe, "
                 "adds strands only to the failing span/direction bands, "
                 "then trims the surplus only when a section still has room.")
    rounds_max = int(getattr(params, "efm_rounds", 4) or 4)
    max_step = int(getattr(params, "efm_max_step", 6) or 6)
    min_gain = float(getattr(params, "efm_min_gain", 2.0) or 0.0)   # %
    if obj == "section_only" and not bool(getattr(params, "efm_rebalance",
                                                  False)):
        job.warn("The objective is section_only and 'Draw the tendons the "
                 "section check asks for' is off, so this run can only report "
                 "the sections over the limit - it will change nothing. Tick "
                 "it on the EFM page.")

    hist = []
    geometry_only = False
    geo_baseline = None
    #  تاريخ القراءات الراسبة **لكل وش/اتجاه على حدة**. مفتاح زي
    #  "bottom_y". لوحة واحدة = مفتاح واحد؛ أربع لوحات = أربع
    #  تواريخ مستقلة. الخلط كان بيطلّع أرقام قفل وهمية.
    fail_hist = {}
    #  **18.27: وهي نازلة قد إيه كل دورة؟**
    #  عتبة المكسب اللي تحتها الحلقة بتقف مبنية على **وزن الحديد**،
    #  والسطر اللي بيحسبها مستثني `section_only` بالنص:
    #  `if prev_kg is not None and obj != "section_only"`. وده صح في
    #  نفسه - الهدف هناك إغلاق القطاعات مش توفير حديد - بس نتيجته إن
    #  الوضع ده **مالوش أي وقفة على قلّة الجدوى خالص**: يا كل القطاعات
    #  تقفل، يا عدّاد الدورات يخلص. فالمهندس بيزوّد العدد عشان يوصل،
    #  وبيلاقي الحلقة ماشية تحلّل من غير ما تقرّب.
    #  القياس الصح هنا هو **عدد القراءات فوق الحد**، مش الكيلو.
    prev_fails = None
    stalled = 0
    #  17.7: كل مجموعة قطاعات اتعالجت، واللي اتحطّ لها - للمراجعة في الآخر.
    section_groups = []
    #  17.8: حد الكجم/م² على السقف كله.
    _area_m2 = slab_area_m2(site)
    _rate = float(getattr(params, "budget_kg_m2", 0.0) or 0.0)
    budget_total = (_rate * _area_m2) if (_rate > 0 and _area_m2) else None
    #  **18.73: والسقف النسبي.** «زوّد لحد 30% وبس» - محسوب من الحديد
    #  اللي السقف داخل بيه، فمابيحتاجش مساحة ولا يعرف كام كيلو في المتر
    #  بيبقى معقول على الدور ده. لو الاتنين متحطّين، الأصغر بيحكم:
    #  السقف حد، والحدّين مع بعض يعني الأقرب.
    _cap_pct = float(getattr(params, "add_cap_pct", 0.0) or 0.0)
    if _cap_pct > 0:
        _kg_in = floor_strand_kg(tendons, params)
        _rel = _kg_in * (1.0 + _cap_pct / 100.0)
        budget_total = _rel if budget_total is None else min(budget_total,
                                                             _rel)
        job.info(f"Limit on what may be added: {_cap_pct:.0f}% of what the "
                 f"floor carries now. It has {_kg_in:,.0f} kg, so the loop "
                 f"may take it to {_rel:,.0f} kg and no further - the "
                 f"sections it cannot reach inside that are reported, not "
                 f"quietly paid for.")
    budget_hit = False
    if _rate > 0:
        if budget_total is None:
            job.warn("A kg/m2 limit is set, but the slab area could not be "
                     "read from the model, so the limit is not applied.")
        else:
            _kg0 = floor_strand_kg(tendons, params)
            job.info(f"Strand limit: {_rate:.2f} kg/m2 over {_area_m2:,.0f} m2 "
                     f"= {budget_total:,.0f} kg. The floor carries "
                     f"{_kg0:,.0f} kg ({_kg0 / _area_m2:.2f} kg/m2) now; the "
                     f"loop spends what is left on the failing sections that "
                     f"cost least per section, and leaves the rest.")
            if _kg0 >= budget_total:
                job.warn("The design already carries more strand than the "
                         "limit - no tendon or strand will be added, and every "
                         "failing section is left for a solution in the "
                         "concrete.")
    #  section_only (17.3): القراءات اللي خارج متناول الشد، لكل وش/اتجاه،
    #  والتخفيف اللي بيتأجّل لآخر الرن.
    unreach = {}
    relief_memo = {}       # 17.5: القمم اللي اتنزّلت للاتجاه التاني
    thin_done = False
    thin_pending = False
    done_early = False
    plot_for = None        # اللوحة اللي في إيدنا اتصدّرت من أنهي موديل
    _mine = set()          # الملفات اللي الرن ده كتبها - عشان مايمسحش غيرها
    #  **دفتر التزويد**: كل بحر، كام استرند دخله في كل دورة. من غيره
    #  مافيش طريقة نرجّع حاجة - الحلقة بتزوّد وخلاص، وبحر مابيردّش
    #  بيفضل شايل الاسترندات اللي ماعملتش حاجة لحد آخر الرن.
    ledger = {}
    frozen = {}
    measured = {}
    flagged = {}
    first_table = None
    last_table = None
    same_model = None
    geo_spans = {}
    creep_count = {}
    sm_hist = []
    #  (مفتاح الحالة, صورة الاسترندات, رقم الدورة) لأحسن دورة لحد دلوقتي
    best_state = None
    prev_table = None
    prev_kg = None
    best_path = None
    stopped = "rounds finished"
    #  كام استرند اتزاد في الدورة اللي فاتت. من غير الرقم ده، سطر
    #  «القطاعات قفلت ولا لأ؟» بيقول "الاسترندات اللي اتزادت ماقفلتش
    #  ولا قطاع" حتى لما الدورة اللي فاتت كانت **هندسة بس** وماحطّتش
    #  ولا استرند. ده حصل في رن حقيقي: الدورة الأولى هندسة، والدورة
    #  التانية اتهمت استرندات مش موجودة.
    added_prev = None
    added_this = 0
    thinned_all = 0            # كام استرند خرج في الرن كله
    #  بصمة حالة الكابلات وقت آخر حفظ. الحفظ بيحصل **في أول الدورة**،
    #  بعد الرسم - يعني اللي الدورة بتعمله (تحريك نقط، كابلات جديدة،
    #  استرندات) مابيوصلش لرام غير في الدورة اللي بعدها. ولما ماتبقاش
    #  فيه دورة بعدها، الشغل ده بيتحسب ويتكتب في التقرير **وبيتشال**.
    #  رن حقيقي بدورة واحدة: 23 كابل و83 استرند اتصمّموا واتقالوا في
    #  اللوج، والملف المحفوظ كان من قبلهم كلهم - "الحديد 1,741 -> 1,741،
    #  نزل 0.0%". البصمة دي هي اللي بتكشف الفرق ده وتفرض كتابة أخيرة.
    saved_fp = None
    #  17.80: تراجع الجولة اللي بتضرّ. لقطة من الكابلات عند بداية كل جولة
    #  (قبل إضافاتها)، وعدّ القطاعات الراسبة ومجموع تجاوزها على كل
    #  اللوحات. لو الجولة اللي فاتت زوّدت استراندات والعدّ أو المجموع
    #  طلع أعلى، الاستراندات دي بتتشال تاني والحارات اللي راحت لها
    #  بتتقفل لباقي الرن. اللي طلّع القاعدة: FIRST p.06، قراءة على حافة
    #  دروب طلعت 3.05 -> 5.35 -> 7.97 -> 8.52 -> 9.44 ميجا فوق الحد وكل
    #  جولة بتحط استراندات عندها.
    import copy as _cp
    _snap_rounds = {}
    _rb_prev = None
    _treated_this, _treated_prev = [], []
    _reverted = 0
    for rnd in range(1, rounds_max + 1):
        job.check()
        job.log("", "info")
        added_prev, added_this = added_this, 0
        _treated_prev, _treated_this = _treated_this, []
        _snap_rounds[rnd] = None                 # 17.82: per-band revert, no snapshot
        _skip_adds = False
        job.log(f"EFM round {rnd} of {rounds_max}", "head")

        #  **نظّف الملزوق قبل ما ترسم.** كابل مضاف واقف أقرب من الحد
        #  الأدنى من كابل موازي مش قابل للتنفيذ، ووجوده بيغشّ كل حساب
        #  بعد كده: القوة محسوبة وهي مش هتتنفّذ. نسخة قديمة كانت
        #  بتسمح بده، فالموديلات اللي طلعت منها فيها الأزواج دي.
        try:
            merge_crowded_added(tendons, params, job)
            tendons[:] = [t for t in tendons if not t.get("_deleted")]
        except Exception as e:
            job.warn(f"The crowding check did not run: {e}")

        #  ارسم الكابلات بعددها الحالي
        job.step(0.60, f"EFM round {rnd}: drawing the tendons")
        clear_tendons_in_ram(session, job)
        drape_before = total_drape(tendons) if rnd == 1 else None
        write_tendons_to_ram(session, tendons, job, params,
                             drops=(site or {}).get("drops"), site=site)
        #  الرسم بيعيد تشغيل قواعد البروفايل على كابلات المهندس. أي
        #  غطس بيضيع هنا هو **سبب مباشر** لحديد سفلي زيادة - والفرق ده
        #  هو اللي بيطلع كل رن في سطر "+118 kg من غير ولا استرند".
        if drape_before is not None:
            d0, n0 = drape_before
            d1, n1 = total_drape(tendons)
            if d0 > 1e-6 and abs(d1 - d0) / d0 > 0.005:
                pc = 100.0 * (d0 - d1) / d0
                rmin = float(getattr(params, "min_tendon_radius", 6.0) or 0.0)
                job.warn(
                    f"Redrawing the tendons changed the total drape by "
                    f"{-pc:+.1f}% ({d0 / 1000.0:.1f} m of sag over {n0} dips "
                    f"-> {d1 / 1000.0:.1f} m over {n1}). Balanced load "
                    f"follows drape directly, so a loss here shows up as "
                    f"bottom steel before the loop has added anything."
                    + (f" The minimum tendon radius is set to {rmin:.1f} m; "
                       f"measured on two models, 12 m costs about 5% of the "
                       f"drape and 6 m costs under 1%. If your duct allows a "
                       f"tighter bend, that setting is the cheapest kg on "
                       f"this floor." if pc > 0.5 and rmin >= 8.0 else ""))
        if bool(getattr(params, "place_jacks", True)):
            try:
                write_jacks_to_ram(session, tendons, job, params)
            except Exception as e:
                job.warn(f"Jacks were not placed this round: {e}")

        audit_before_analysis(tendons, params, job, site)
        res = run_model_analysis(session, job, mesh_size)
        if not res.get("ok"):
            stopped = "the analysis did not run"
            job.error("The EFM loop stopped: RAM did not finish the analysis.")
            break

        #  **مانكتبش فوق رن قديم.** الاسم كان `{stem}_EFM_r{rnd}.cpt`
        #  بالظبط في كل مرة، فرنّين على نفس الملف بيمسحوا بعض من غير
        #  ما حد يعرف. النتيجة اللي كشفتها: موديل اتفتح وقُري منه 1,275
        #  كجم مخزّنة، واتعمله رن بنفس الكابلات بالظبط (المقارنة قالت
        #  «مافيش حاجة اتغيّرت») فطلع 1,741 - فرق 37% على نفس الحالة.
        #  السبب إن الحديد المخزّن كان من رن تاني خالص كتب نفس الاسم.
        path = os.path.join(out_dir, f"{stem}_EFM_r{rnd}.cpt")
        if path not in _mine and os.path.isfile(path):
            k = 2
            while True:
                alt = os.path.join(out_dir, f"{stem}_EFM_r{rnd}-{k}.cpt")
                if alt not in _mine and not os.path.isfile(alt):
                    break
                k += 1
            job.warn(f"{os.path.basename(path)} already exists from an "
                     f"earlier run. Saving as {os.path.basename(alt)} "
                     f"instead - overwriting it would make the two runs "
                     f"impossible to tell apart, and that is exactly how a "
                     f"model comes back reading 37% different reinforcement "
                     f"for the same tendons.")
            path = alt
        _mine.add(path)
        if not safe_save(session, path, job):
            stopped = "the model could not be saved"
            break
        best_path = path
        saved_fp = tendon_fingerprint(tendons)

        #  المقارنة ملف بملف: أول دورة بس، وبتقول اللي اتغيّر فعلاً.
        if rnd == 1:
            try:
                same_model = compare_written_tendons(
                    session_source or "", path, job)
            except Exception as e:
                job.warn(f"The before/after comparison did not run: {e}")

        model = read_designed_steel(path)
        #  section_only: الحديد المصمَّم مش هو الحكم - قطاع ممكن يبقى فوق
        #  حد الكود ورام مصمّمش ولا سيخ، فالوقوف هنا غلط.
        if not model["rebar"] and obj != "section_only":
            job.ok("RAM designed no reinforcement at all this round - "
                   "nothing left for the loop to chase.")
            stopped = "no designed reinforcement"
            hist.append({"round": rnd, "kg": 0.0, "path": path})
            break
        table = steel_by_span(model)
        #  آخر جدول اتقاس فعلاً. مش prev_table: الوقوف بسبب قلّة المكسب
        #  بيحصل قبل ما prev_table تتحدّث، فآخر دورة كانت بتضيع من
        #  الحساب التراكمي.
        last_table = table
        if first_table is None:
            first_table = table
        total = sum(face_kg(v, _face_of(params)) for v in table.values())

        #  الاستجابة المقيسة: الحديد نزل كام لكل استرند اتزاد في البحر ده.
        #  دي بتتقدّم على التقدير النظري من الدورة التانية وطالع.
        #  حاجتين مختلفتين بيتقاسوا هنا:
        #    · **بحر ساء**: حديده زاد فعلاً بعد ما قوّيناه. ده دليل على
        #      قمة في مكان غلط.
        #    · **بحر مش بيستجيب**: حديده نزل، بس أقل بكتير من البلاطة
        #      كلها. مش غلطة بالضرورة - بس هو اللي فاضل.
        #
        #  والعتبة مهمة: البلاطة كلها بتنزل 16-20% كل دورة، فبحر يطلع
        #  20 كجم وسط ده ممكن يكون إعادة توزيع مش قمة غلط. أول ما حطينا
        #  الكاشف من غير عتبة كان بيقول 15 بحر في دورة، أكبرهم 32 كجم -
        #  وده تحت مستوى الضوضاء جنب بحر فيه 1,127 كجم.
        worsened = []
        lagging = []
        crept = []
        face = _face_of(params)
        if prev_table is not None:
            slab_now = sum(face_kg(v, face) for v in table.values())
            slab_was = sum(face_kg(v, face) for v in prev_table.values())
            slab_drop = ((slab_was - slab_now) / slab_was
                         if slab_was > 1e-6 else 0.0)
            floor_kg = float(getattr(params, "efm_flag_kg", 50.0) or 0.0)
            floor_pc = float(getattr(params, "efm_flag_pct", 5.0) or 0.0) / 100.0
            for key, now in table.items():
                was = prev_table.get(key)
                if not was:
                    continue
                dn = (now["strands"] or 0) - (was["strands"] or 0)
                now_kg = face_kg(now, face)
                was_kg = face_kg(was, face)
                dk = was_kg - now_kg
                if dn <= 0:
                    continue
                measured[key] = max(dk / dn, 0.0)
                rise = -dk
                if rise > max(floor_kg, floor_pc * max(was_kg, 1.0)):
                    creep_count[key] = 0
                    worsened.append((now, was, dn, rise))
                elif rise > 0.0 and was_kg > floor_kg:
                    #  الطلوع تحت العتبة مرة = ضوضاء. مرتين ورا بعض على
                    #  نفس البحر = اتجاه. الحلقة بتعدّه، وعند المرة
                    #  التانية بيتحوّل لعلامة كاملة - بدل ما نقول
                    #  "راقبه" كل دورة والمستخدم يراقبه بنفسه.
                    creep_count[key] = creep_count.get(key, 0) + 1
                    if creep_count[key] >= 2:
                        worsened.append((now, was, dn, rise))
                        continue
                    #  طلع، بس تحت العتبة. مش قمة غلط مؤكدة، وبرضه مش
                    #  "مامشيش" - فله سطره لوحده بدل ما يتحط في قايمة
                    #  الثابتين ويتقري غلط.
                    crept.append((now, was, dn, rise))
                elif (slab_drop > 0.05 and was_kg > floor_kg
                      and dk / max(was_kg, 1e-6) < slab_drop / 3.0):
                    lagging.append((now, was, dn,
                                    100.0 * dk / max(was_kg, 1e-6)))

        job.log(efm_round_report(model, table, [], obj, rnd, _face_of(params)), "info")
        #  **الرقم اللي الخطة كلها اتعملت عشانه.** الدورة الأولى حرّكت
        #  نقط ومازوّدتش استرند واحد، فرقم الدورة دي هو ثمن الحركة
        #  لوحدها - من غير أي حاجة تانية مخلوطة فيه. البرنامج كان
        #  بيسيب المستخدم يطرح بنفسه من سطرين متباعدين.
        if geo_baseline is not None:
            _now = sum(face_kg(v, _face_of(params)) for v in table.values())
            d = geo_baseline - _now
            pc = 100.0 * d / max(geo_baseline, 1e-6)
            if d > 0:
                job.ok(f"**Moving the points was worth {d:,.0f} kg "
                       f"({pc:.1f}%), and it cost nothing.** Round 1 added "
                       f"no strands at all - it only slid low points onto "
                       f"the measured tension and peaks onto their supports. "
                       f"{geo_baseline:,.0f} kg before, {_now:,.0f} kg "
                       f"after, same {sum(int(t.get('strands') or 0) for t in tendons)} strands.")
            else:
                job.warn(f"**Moving the points cost {-d:,.0f} kg "
                         f"({-pc:.1f}%).** Round 1 added no strands - the "
                         f"geometry moves alone made this floor worse. Those "
                         f"low points were better where they were, and the "
                         f"10% cap is not the reason: turn "
                         f"'geometry before force' off for this floor and "
                         f"the loop will go straight to strands.")
            job.info("    everything from here is what the strands bought, "
                     "on top of that.")
            geo_baseline = None

        #  ملف العلامات بيتكتب **من أول دورة**. علامة "ساء بعد التقوية"
        #  محتاجة دورتين، فالرن الأول كان بيقفل من غير ما يكتب حاجة
        #  والمحرّر بيفتح فاضي. الدورة الأولى عندها دليلها الخاص: أتقل
        #  البحور، والقمم اللي القواعد اتخانقت معاها.
        #  **الفحص المقطعي بيشتغل كل دورة، مش الدورة الأولى بس.**
        #  كان متحبوس جوّه `if rnd == 1`، وده كان مقبول أيام ما الرن
        #  كان بياخد لوحة واحدة في أوله ويخلص. بس من ساعة ما الوقفة
        #  بقت بتطلب تصدير جديد بعد كل دورة، الحبس ده بقى غلط - وبقى
        #  أسوأ لما «الهندسة الأول» خدت الدورة الأولى لنفسها: النتيجة
        #  إن مسار إعادة التوزيع **مااشتغلش ولا مرة** في رن كامل.
        #  القياس: رن على سقف حقيقي نزّل الحديد 21% وحرّك القراءات
        #  الراسبة من 24 لـ 21 بس - لأن اللي بيلاحقها ماتنفّذش.
        if True:
            #  الاختبار الهندسي: مستقل عن كل ده، وبيشتغل من أول دورة
            #  لأنه مش محتاج مقارنة أصلاً - بيقيس مكان القمة من بحور
            #  رام نفسها.
            #  لو فيه لوحة مصدّرة، الفحص ده هو **التصميم الحقيقي**:
            #  الطلب مقابل المقاومة من رام نفسه. الحديد المصمَّم فرز،
            #  واللوحة حكم.
            #  **الوقفة**: الحلقة محتاجة تصدير من الموديل اللي لسه
            #  اتحفظ، والتصدير بالإيد - مافيش طريقة تانية. بدل ما الرن
            #  يخلص ويقول «صدّر وشغّل تاني»، بيقف هنا ويطلبه بالاسم،
            #  ويفحص اللي يظهر قبل ما يبني عليه.
            #  **من 17.0: الفحص من رام نفسه.** الموديل لسه مفتوح ومتحسوب
            #  في الجلسة، فالأرقام اللي اللوحة كانت بتتصدّر عشانها بتتقرا
            #  على طول. التصدير بالإيد بقى احتياطي: بيرجع بس لو القراية
            #  فشلت.
            _ram_plots = []
            if bool(getattr(params, "efm_read_ram", True)):
                try:
                    _ram_plots = read_section_plots_from_ram(session, params,
                                                             job)
                except CancelledError:
                    raise
                except Exception as e:
                    job.warn(f"Reading the section check from RAM did not "
                             f"work ({e}). This round falls back to the "
                             f"exported plot.")
                    _ram_plots = []
            _paths = ([] if _ram_plots else
                      [q.strip() for q in
                       (getattr(params, "stress_plot", "") or "").split(";")
                       if q.strip()])
            #  **اللوحة بتوصف الموديل اللي اتصدّرت منه، وبس.** بعد ما
            #  الدورة تحفظ موديل جديد، لوحة الدورة اللي فاتت بقت تاريخ.
            #  الوقفة كانت بتفتح بس لما مافيش لوحة أصلاً، فأول لوحة
            #  فضلت مستعملة كل الدورات. النتيجة في رن حقيقي: التلات
            #  دورات قروا نفس الملف وطبعوا نفس الـ24 قراءة بالحرف،
            #  والسطر اللي بيسأل «قفلوا ولا لأ؟» كان بيقارن اللوحة
            #  بنفسها ويقول «ولا واحدة قفلت». ده مش قياس، ده صدى.
            if (not _ram_plots and plot_for is not None
                    and plot_for != path):
                job.warn(f"The plot in hand was exported from "
                         f"{os.path.basename(plot_for)}, and this round has "
                         f"saved {os.path.basename(path)}. It describes the "
                         f"model before this round's strands, so it cannot "
                         f"say whether they closed anything. Asking for a "
                         f"fresh one.")
                _paths = []
            _fresh = []
            for _q in _paths:
                #  الوسم "|x" أو "|y" جزء من الإدخال، مش من المسار
                _qp, _, _qd = str(_q).partition("|")
                if not os.path.isfile(_qp):
                    continue
                _ok, _why, _ = check_section_plot(_qp, tendons)
                if _ok:
                    _fresh.append(_q)
                else:
                    job.warn(f"{os.path.basename(_qp)} is not usable for "
                             f"this model - {_why}")
            if _ram_plots:
                _fresh = list(_ram_plots)
                plot_for = path
            if not _fresh and ask_plot is not None:
                job.warn("The loop is waiting for a Section Analysis Plot "
                         "exported from the model it just saved. The window "
                         "on screen says exactly which file to open and what "
                         "to export; it watches the output folder and checks "
                         "whatever appears.")
                job.step(0.0, "Waiting for the section plot")
                _got = ask_plot(path, out_dir, tendons, rnd)
                if _got is None:
                    job.warn("Stopped at your request. The model for this "
                             "round is saved and analysed.")
                    return {"rounds": hist, "best": path,
                            "stopped": "you stopped at the plot step"}
                if _got.get("paths") or _got.get("path"):
                    #  ممكن أكتر من لوحة في الدورة الواحدة - وش واتجاه
                    #  لكل واحدة. القديم كان بياخد واحدة، فالاتجاه
                    #  التاني كان بيفضل مش مفحوص طول الرن.
                    _fresh = list(_got.get("paths") or [_got["path"]])
                    plot_for = path
                    job.ok("Using " + ", ".join(
                        os.path.basename(str(q).partition("|")[0])
                        + (f" [{str(q).partition('|')[2].upper()}]"
                           if str(q).partition("|")[2] else "")
                        for q in _fresh))
                else:
                    job.warn("Carrying on without a section check - this "
                             "round chases the designed rebar only, which is "
                             "the slower target.")
            _plots_read = []
            _thin_budget = 0
            #  17.82: التراجع حارة حارة. 17.80 كان بيرجّع الجولة كلها لو
            #  المجموع زاد، فحارة واحدة وحشة كانت بتضيّع 40 استراند صح
            #  وتقفل 28 مكان. دلوقتي كل مجموعة (حارة اتعالجت في الجولة
            #  اللي فاتت، بقراءاتها وهداياها) بتتقارن بقراءاتها هي:
            #  لو أعلى تجاوز عندها زاد أكتر من 0.10 ميجا، هداياها بتترجع
            #  (revert_group_gifts) وأماكنها بتتقفل؛ الباقي بيفضل.
            _rb_now = None
            _skip_adds = False
            if _fresh and all(isinstance(_pp, RamSectionPlot) for _pp in _fresh):
                try:
                    _rows_by_tag = {}
                    _c, _mpa = 0, 0.0
                    for _pp in _fresh:
                        _all = plot_deficits(_pp, params)
                        _rows_by_tag[plot_tag(_pp)] = _all
                        if obj == "section_only":
                            _r, _h = section_fail_counts(_pp, params, tendons)
                        else:
                            _r = _all
                        _c += len(_r)
                        _mpa += sum(float(d.get("over") or 0.0) for d in _r)
                    _rb_now = (_c, _mpa)
                    _undone = []
                    for _g in section_groups:
                        if (_g.get("src") != "efm" or _g.get("round") != rnd - 1
                                or _g.get("removed") or not _g.get("readings")):
                            continue
                        _then = max(float(q[2]) for q in _g["readings"])
                        _rows = _rows_by_tag.get(_g.get("tag"), [])
                        _now = 0.0
                        for x0, y0, _o in _g["readings"]:
                            for d in _rows:
                                if math.hypot(float(d["x"]) - float(x0),
                                              float(d["y"]) - float(y0)) <= 1.0:
                                    _now = max(_now, float(d.get("over") or 0.0))
                        if _now > _then + 0.10:
                            _gone, _back = revert_group_gifts([_g], params)
                            _blk = list(getattr(params, "_efm_blocked", None) or [])
                            _blk.extend((float(x0), float(y0)) for x0, y0, _o in _g["readings"])
                            setattr(params, "_efm_blocked", _blk)
                            _undone.append((_g, _then, _now, _gone, _back))
                    if _undone:
                        tendons[:] = [t for t in tendons if not t.get("_deleted")]
                        _reverted += len(_undone)
                        job.warn(f"{len(_undone)} band(s) from round {rnd - 1} made "
                                 f"their own sections WORSE and are undone - the "
                                 f"strands come back out and those places are "
                                 f"closed to strands for the rest of this run "
                                 f"(force there feeds the reading: a kink, or a "
                                 f"tendon high point on a sagging section).")
                        for _g, _then, _now, _gone, _back in _undone[:8]:
                            x0, y0, _o = _g["readings"][0]
                            job.info(f"    {_g.get('tag')} near ({x0:.1f}, {y0:.1f}): "
                                     f"{_then:.2f} -> {_now:.2f} MPa over; "
                                     f"{_back} strand(s) back, {_gone} tendon(s) out")
                    if (_rb_prev is not None and added_prev > 0
                            and _rb_now[0] > _rb_prev[0] and not _undone):
                        job.warn(f"Round {rnd - 1} left MORE sections over the "
                                 f"limit ({_rb_prev[0]} -> {_rb_now[0]}) without "
                                 f"any treated band getting worse itself - the "
                                 f"new failures are elsewhere; carrying on.")
                except Exception as _e:
                    job.warn(f"The round check did not run: {_e}")
                    _rb_now = None
            if _rb_now is not None:
                _rb_prev = _rb_now
            for _pp in _fresh:
                try:
                    #  المسار ممكن يجي معاه اتجاهه: "C:\...\x.dxf|y".
                    #  الملف نفسه مافيهوش الاتجاه (الشرح في StressPlot)،
                    #  فالوسم ده هو الطريق الوحيد.
                    if isinstance(_pp, RamSectionPlot):
                        _plot = _pp
                        _src = f"RAM, {_plot.face} face"
                    else:
                        _pp, _sep, _pd = str(_pp).partition("|")
                        _plot = StressPlot(_pp, direction=(_pd or None))
                        _src = os.path.basename(_pp)
                    if _plot.direction is None and _plot.dir_hint:
                        _plot.direction = _plot.dir_hint
                        job.info(f"    the direction of this export is not "
                                 f"in the file, and its name suggests "
                                 f"{_dir_name(_plot.dir_hint)}. That is a "
                                 f"guess from the name - if it is wrong, "
                                 f"every band below is drawn the wrong way.")
                    job.log(f"Design check from {_src}"
                            + (f" · {_dir_name(_plot.direction)}"
                               if _plot.direction else ""), "head")
                    report_design_check(_plot, params, job, site,
                                        _tend=tendons)
                    #  ولو مطلوب موديل **سيف**: نرسم اللي الفحص طالبه
                    #  مرة واحدة، بدل ما نقرّب عليه استرند استرند.
                    if not bool(getattr(params, "efm_rebalance", False)):
                        #  الفحص قال إن فيه قطاعات راسبة، والبرنامج يقدر
                        #  يرسم علاجها - بس الخيار مقفول. السكوت هنا
                        #  بيخلّي الرن يعدّي وكأن مفيش حاجة ممكن تتعمل.
                        job.warn(
                            "Those failing sections are what the loop can "
                            "actually draw for, and it is switched off: tick "
                            "'Draw the tendons the section check asks for' "
                            "on the EFM page. Without it this run only "
                            "reports them, and the strand raise below is "
                            "chasing designed rebar instead - a different, "
                            "slower target.")
                    #  **الدورة الأولى: هندسة بس.** الغطسة اللي في نص
                    #  البحر افتراض؛ مكان أقصى شد مقروء من اللوحة. تحريكها
                    #  عليه مافيهوش استرند واحد. ولو ده لوحده سيّف قطاعات،
                    #  الاسترندات اللي بعدها بتبقى أقل - وده أرخص علاج
                    #  ممكن. الدورة اللي بعدها هي اللي بتزوّد.
                    #  **«الهندسة الأول» محتاجة دورة تانية تدفع.**
                    #  لو الرن كله دورة واحدة، الدورة دي هتحرّك النقط
                    #  وتقف - يعني تصدير كامل مقابل صفر استرند، وموديل
                    #  خرج زي ما دخل تقريباً. لما تكون الدورة الوحيدة،
                    #  الهندسة والقوة بيتعملوا في نفس الدورة.
                    _solo = (rounds_max <= 1)
                    _geo = bool(getattr(params, "efm_geometry_first", True))
                    if _geo and rnd == 1:
                        job.log("Round 1: geometry before force", "head")
                        lows_to_peak_stress(tendons, _plot,
                                            model.get("spans"), params, job)
                        if _solo:
                            job.info("    This run has one round, so the "
                                     "strands are placed in it too - the "
                                     "points move first and the re-banding "
                                     "below prices what is still short "
                                     "after they have. The one thing you "
                                     "give up is the separate measurement "
                                     "of what the geometry alone was worth; "
                                     "the design itself is complete.")
                        else:
                            geometry_only = True
                            job.info("    No strands are added this round on "
                                     "purpose. The next export says what "
                                     "moving the points alone was worth, and "
                                     "round 2 only pays for what is still "
                                     "short.")
                    _plots_read.append(_plot)
                    _fail_now = len(plot_deficits(_plot, params))
                    #  **section_only (17.3): العدّ على اللي الشد يقدر يقفله.**
                    #  القراءات "out of reach of prestress" (دروب، أطراف
                    #  حيطان) مابتدخلش في المقارنة ولا في الوقوف - بتتسجّل
                    #  وبتتقال بالإحداثي في الآخر، للحديد أو السُمك.
                    if obj == "section_only":
                        _reach, _hope = section_fail_counts(_plot, params,
                                                            tendons)
                        _fail_now = len(_reach)
                        unreach[plot_tag(_plot)] = [
                            (float(d["x"]), float(d["y"]), float(d["over"]))
                            for d in _hope]
                    #  **العدّ بيتقارن بلوحة نفس الوش ونفس الاتجاه، وبس.**
                    #  لما الرن بقى ياخد أكتر من لوحة، القايمة الواحدة
                    #  كانت بتخلط: 44 راسبة في Y علوي تتقارن بـ 4 في X
                    #  سفلي وتطلع "40 قفلت" - وولا واحدة قفلت.
                    _tag = plot_tag(_plot)
                    _hist = fail_hist.setdefault(_tag, []) \
                        if isinstance(fail_hist, dict) else fail_hist
                    if _hist:
                        _d = _hist[-1] - _fail_now
                        job.log(f"Are the failing sections actually closing? "
                                f"({_tag})", "head")
                        if _d > 0:
                            job.ok(f"{_hist[-1]} readings were over the "
                                   f"limit last round and {_fail_now} are "
                                   f"now - **{_d} closed**. That is the only "
                                   f"number that says the floor is getting "
                                   f"safer; the reinforcement weight says "
                                   f"how much it costs.")
                        elif _d == 0 and not added_prev:
                            #  الدورة اللي فاتت ماحطّتش استرند - يبقى
                            #  مافيش حاجة "فشلت"، وده الرقم اللي كنا
                            #  عايزينه: الهندسة لوحدها ساوت كام.
                            job.info(f"Still {_fail_now} readings over the "
                                     f"limit, the same as last round - and "
                                     f"last round added no strands at all, "
                                     f"so nothing here failed. That is the "
                                     f"measurement of what moving the points "
                                     f"alone was worth on this face: nothing "
                                     f"yet. The strands come next.")
                        elif _d == 0:
                            job.warn(f"Still {_fail_now} readings over the "
                                     f"limit - the same as last round, after "
                                     f"{added_prev} strand(s) were added. "
                                     f"They did not close a single section "
                                     f"on this face.")
                        else:
                            job.warn(f"{-_d} MORE readings are over the "
                                     f"limit than last round "
                                     f"({_hist[-1]} -> {_fail_now}). The "
                                     f"last round made this face worse.")
                    _hist.append(_fail_now)
                    #  **لوحة واحدة نضيفة مش معناها السقف سيف.** مع
                    #  أربع لوحات، الوش السفلي في X ممكن يبقى صفر
                    #  والوش العلوي في Y عليه 44 قراءة. الوقوف بيتقرر
                    #  لما **كل** اللوحات اللي اتقرت في الدورة دي تبقى
                    #  صفر - والباقي بيتسمّى بالاسم.
                    if _fail_now == 0:
                        job.ok(f"Nothing on {_tag} is over the limit any "
                               f"more.")
                    if getattr(_plot, "_foreign", False):
                        job.warn(
                            "No tendons are drawn from that export, because "
                            "it is not this model's. Fix the plot and run "
                            "again - the loop carries on below on the "
                            "designed rebar alone.")
                    elif geometry_only:
                        pass
                    elif _skip_adds:
                        job.info("    no strands this round: the model was "
                                 "put back to the state before the last "
                                 "round's additions and is re-analysed next.")
                    elif bool(getattr(params, "efm_rebalance", False)):
                        #  **18.95: H optimization بعد الرسم**.
                        #  هنا التحديد ما يبقاش "أي كابلات في أي بحر"، لأن
                        #  المعنى الحقيقي للـ H optimization هو: شغل على
                        #  المخطط الموجود، مع القطاعات الناقصة فقط، ونسحب
                        #  الفائض بس لو لسه فيه رصيد. نفس محرك الـ EFM يقوم
                        #  بالمهمة، لكن وسمنا هيتحكم في السلوك.
                        if hopt:
                            job.info("    H optimization pass: preserve the "
                                     "existing layout, add only in the "
                                     "failing span/direction bands, and leave "
                                     "already-safe sections alone.")
                        _rec = load_rebanding_record(out_dir, stem, _tag)
                        extra, rep = tendons_from_deficit(
                            _plot, tendons, params, site, job, record=_rec,
                            spans=model.get("spans"),
                            budget_kg=(None if budget_total is None else
                                       budget_total
                                       - floor_strand_kg(tendons, params)))
                        #  18.102: مسار H optimization اتنقل لتحت، بعد ما
                        #  الكابلات الجديدة تدخل الموديل والميزانية تتحسب
                        #  (شوف "H optimization بعد الإضافة" تحت).
                        if rep.get("over_budget"):
                            budget_hit = True
                        try:
                            for _b in (rep.get("band_list") or []):
                                for q in (_b.get("rows") or []):
                                    _xy = q.get("_orig_xy") or (q["x"], q["y"])
                                    _treated_this.append((float(_xy[0]), float(_xy[1])))
                        except Exception:
                            pass
                        try:
                            for _b in (rep.get("band_list") or []):
                                if not _b.get("_gifts"):
                                    continue
                                section_groups.append({
                                    "id": f"s{len(section_groups) + 1}",
                                    "src": "efm", "round": rnd, "tag": _tag,
                                    "face": _plot.face,
                                    "dir": _plot.direction,
                                    "limit": _plot.limit,
                                    "readings": [
                                        (tuple(q.get("_orig_xy")
                                               or (q["x"], q["y"]))
                                         + (float(q.get("over") or 0.0),))
                                        for q in (_b.get("rows") or [])],
                                    "gifts": list(_b["_gifts"])})
                        except Exception:
                            pass
                        #  ونكتب سجل الدورة دي عشان اللي بعدها تقيس.
                        try:
                            _rp = save_rebanding_record(
                                rebanding_path(out_dir, stem, _tag),
                                rep.get("band_list") or [], params, _plot)
                            if _rp:
                                job.info(
                                    f"    what this pass placed, band by "
                                    f"band, is written beside the model in "
                                    f"{os.path.basename(_rp)}. Export the "
                                    f"plot again and run once more: that "
                                    f"file is how the next pass knows what "
                                    f"a strand is worth here.")
                        except Exception:
                            pass
                        #  التخفيف مابيتعملش هنا: لازم يشوف كل اللوحات
                        #  مع بعض، وده بعد ما اللفة تخلص. والميزانية
                        #  بتعدّ الاسترندات اللي راحت على كابلات موجودة
                        #  كمان، مش الكابلات الجديدة بس.
                        _thin_budget += int(rep.get("strands") or 0)
                        #  الاسترندات اللي راحت على كابلات موجودة
                        #  بتتحسب زيادة زي أي زيادة - من غير كده سطر
                        #  «الدورة اللي فاتت ماحطّتش حاجة» بيكدب.
                        added_this += int(rep.get("strands") or 0)
                        if extra:
                            tendons.extend(extra)
                            job.ok(
                                f"Those {len(extra)} tendon(s) are in the "
                                f"model from the next round on. What the "
                                f"next export of this plot shows is the "
                                f"answer: the readings that were over the "
                                f"limit should be under it, and the "
                                f"{rep['hopeless']} that no spacing can "
                                f"reach will still be over - those are for "
                                f"depth or reinforcement, and no run of this "
                                f"loop will close them.")
                            if rep.get("measured"):
                                job.info(
                                    "The strand counts above are not from "
                                    "the formula any more. They are what a "
                                    "strand was measured to be worth in "
                                    "these bands on this floor, between the "
                                    "last export and this one - drape, load "
                                    "balance, spreading and all, whatever "
                                    "their share, already inside the number.")
                            else:
                                job.info(
                                    "One caveat worth knowing: the strands "
                                    "per metre are worked out from "
                                    "precompression alone - a new tendon "
                                    "also balances load with its drape, "
                                    "which relieves the same tension again. "
                                    "So this errs on the generous side, and "
                                    "the next export is what trims it.")
                        #  **18.102: H optimization بعد الإضافة.**
                        #  كان بيتنادى قبل tendons.extend(extra) وقبل حساب
                        #  الميزانية، وكان بيمرّر لوحة واحدة مكان قائمة
                        #  لـ hopt_trim_surplus فبيقع بـ TypeError يتبلع في
                        #  except اللوحة تحت - وكل دورة بتطلّع كابلات كانت
                        #  بترميها من غير ما تقول. دلوقتي: القراءات اللي
                        #  tendons_from_deficit عالجتها الدورة دي مستثناة،
                        #  واللي بيتزاد بيتحسب في الميزانية وسطر "الدورة
                        #  اللي فاتت"، والتخفيف بيتعمل مرة واحدة على
                        #  التخطيط الكامل.
                        if hopt:
                            _kg_now = floor_strand_kg(tendons, params)
                            if (budget_total is not None
                                    and _kg_now >= budget_total):
                                budget_hit = True
                                hopt_res = {"added": 0}
                                job.info("    H optimization: the strand "
                                         "budget is used up, so no focused "
                                         "pass this round.")
                            else:
                                hopt_res = run_h_optimization_pass(
                                    session, tendons, params, job, _plot,
                                    site=site, mesh_size=mesh_size,
                                    skip_xy=list(_treated_this))
                            _h_add = int(hopt_res.get("added") or 0)
                            if _h_add:
                                _thin_budget += _h_add
                                added_this += _h_add
                                job.ok(f"    H optimization completed a "
                                       f"focused pass: {_h_add} strand(s) "
                                       f"were added only in the still-short "
                                       f"sections the add pass had not "
                                       f"reached. The next export says "
                                       f"whether they closed.")
                            if extra or _h_add:
                                job.info("    H optimization: the loop now "
                                         "trims only the surplus that still "
                                         "sits within a safe margin.")
                                trim = hopt_trim_surplus(
                                    session, tendons, params, job, out_dir,
                                    stem, site=site, mesh_size=mesh_size,
                                    plots=[_plot])
                                if trim.get("removed"):
                                    job.ok(f"    H optimization trimmed "
                                           f"{trim['removed']} strand(s) "
                                           f"back from the safe surplus "
                                           f"without making a new section "
                                           f"fail.")
                                else:
                                    job.info("    H optimization found no "
                                             "safe surplus to trim; the "
                                             "current layout is left in "
                                             "place to protect the "
                                             "already-safe sections.")
                except Exception as e:
                    job.warn(f"That plot export could not be read ({e}). It "
                             f"has to be the Section Analysis Plot exported "
                             f"as DXF with the values shown.")
            #  **ادفع تمن اللي زوّدته من الفايض** - بعد ما كل
            #  اللوحات اتقرت، عشان الكابل يتحكم عليه بالاتجاهين. لوحة
            #  واحدة معناها كابل نضيف في X ياخد تخفيف وهو ماشي على
            #  قطاع راسب في Y. والميزانية = كل اللي اتزاد الدورة دي،
            #  فالسقف مايخفّش صافي أبداً.
            #  **18.57: حلقة رام.** بعد ما كل اللوحات اتقرت وقبل أي
            #  علاج من البرنامج: التخطيط اللي رام حلّله والقراءات اللي
            #  رسبت بيروحوا للموديل، والتخطيط المعدّل بياخد مكانه.
            #  المكان ده بالذات عشان الموديل يشوف **حكم رام على شغله**
            #  مش على شغل القواعد اللي بعده.
            _air = int(getattr(params, "ai_revise_rounds", 0) or 0)
            if (_air > 0 and rnd <= _air and _plots_read
                    and bool(getattr(params, "ai_layout", False))):
                _new = ai_revised_tendons(site, params, job, tendons,
                                          _plots_read, out_dir, stem, rnd)
                if _new:
                    tendons[:] = _new
                    #  الدفاتر بتتصفّى: مفاتيحها بحور التخطيط القديم،
                    #  والتخطيط الجديد بحوره غيرها. دفتر بيوصف حاجة
                    #  مابقتش موجودة أسوأ من دفتر فاضي.
                    for _bk in (ledger, frozen, measured, flagged,
                                geo_spans, creep_count):
                        try:
                            _bk.clear()
                        except Exception:
                            pass
                    job.info("    the round's ledgers are cleared: they were "
                             "keyed to the spans of the layout that has just "
                             "been replaced.")

            #  **الحمل من الاتجاه التاني (17.5).** بعد ما كل اللوحات
            #  اتقرت: قمم الاتجاه المعاكس فوق القطاعات الراسبة بتنزل خطوة
            #  لو اتجاهها لسه فيه هامش - وبترجع لو اتجاهها طلع أسوأ.
            if bool(getattr(params, "efm_cross_relief", True)) and _plots_read:
                try:
                    relieve_other_direction(
                        tendons, _plots_read, params, job, memo=relief_memo,
                        hist=fail_hist if isinstance(fail_hist, dict)
                        else None)
                except Exception as _e:
                    job.warn(f"The relief from the other direction did not "
                             f"run: {_e}")
            _thin_ok = _thin_budget > 0
            if obj == "section_only":
                #  **التخفيف في الآخر (17.3).** قبل كده كان بيشيل قصاد كل
                #  استرند بيتحط - "15 in, 15 out" كل دورة - فالقوة الإجمالية
                #  ماكانتش بتزيد أبداً، والقطاعات ماكانتش بتقفل. دلوقتي
                #  بيستنى لحد ما مايبقاش قطاع يقدر الشد يقفله فوق الحد،
                #  يخفّف مرة واحدة من غير سقف (بقواعده: الهامش، استرندين
                #  بالكتير، والحد الأدنى)، والدورة اللي بعدها بتحلل النتيجة.
                _thin_ok = False
                if (_fresh and fail_hist and not thin_done
                        and sum(v[-1] for v in fail_hist.values() if v) == 0):
                    _thin_ok = True
                    _thin_budget = None
                    thin_done = True
            if (bool(getattr(params, "efm_thin", False))
                    and _plots_read and _thin_ok):
                try:
                    _tn, _tsx = thin_over_provided(
                        tendons, _plots_read, params, job,
                        budget=_thin_budget)
                    thinned_all += int(_tsx or 0)
                    if _tsx and _thin_budget is None:
                        job.ok(f"    final thinning (section_only): {_tsx} "
                               f"strand(s) came out of places that do not "
                               f"need them, now that no section prestress "
                               f"can reach is over the limit. One more round "
                               f"analyses the thinned floor before the run "
                               f"stops.")
                        thin_pending = True
                    elif _tsx:
                        job.ok(f"    net this round: {_thin_budget} "
                               f"strand(s) in, {_tsx} out - a change of "
                               f"{_thin_budget - _tsx:+d}. The force moved "
                               f"from where the slab did not need it to "
                               f"where it was short, and the floor is not "
                               f"carrying more steel than it was.")
                except Exception as e:
                    job.warn(f"The thinning step did not run: {e}")

            #  **الحكم بعد كل اللوحات.** الوقوف على "سيف" بيتقرر لما
            #  كل وش/اتجاه اتقرا في الدورة دي يبقى صفر - مش أول لوحة
            #  نضيفة.
            if _fresh and fail_hist:
                _left = {k: v[-1] for k, v in fail_hist.items() if v}
                _tot = sum(_left.values())
                _u = sum(len(v) for v in unreach.values())
                was_fails, prev_fails = prev_fails, _tot
                #  **18.34: أحسن دورة بتتحفظ.** الحلقة كانت بتسلّم آخر
                #  دورة مهما كانت. في رن المهندس راحت 5 -> 5 -> 7 -
                #  البحور اللي اتعالجت اتحسّنت والعطل ظهر في مكان تاني،
                #  فالرجوع الموضعي (efm_rollback) مالقاش حاجة يرجّعها -
                #  والموديل اللي اتسلّم كان أسوأ من اللي كان عندها في
                #  الدورة الأولى.
                _key = efm_state_key(_tot, tendons)
                if best_state is None or _key < best_state[0]:
                    best_state = (_key, efm_snapshot(tendons), rnd)
                if _tot == 0 and obj == "section_only" and thin_pending:
                    thin_pending = False
                    job.info("    every section prestress can reach is inside "
                             "the limit, and the thinning above took strands "
                             "out - the next round analyses the thinned floor "
                             "before the run stops.")
                elif _tot == 0 and obj == "section_only":
                    stopped = ("every section prestress can reach is inside "
                               "the limit"
                               + (f"; {_u} out of its reach are left for "
                                  f"reinforcement or depth" if _u else ""))
                    job.ok(f"**Every section prestress can reach is inside "
                           f"the limit on all {len(_left)} face/direction(s) "
                           f"checked.** That is the target, and it has been "
                           f"reached. Stopping.")
                    if _u:
                        job.warn(f"{_u} reading(s) are still over the limit "
                                 f"and out of reach of prestress - they want "
                                 f"reinforcement or depth, not strands:")
                        for _tg, _lst in sorted(unreach.items()):
                            for _x, _y, _ov in sorted(_lst,
                                                      key=lambda z: -z[2])[:10]:
                                job.warn(f"    {_tg:<9} ({_x:.2f}, {_y:.2f})  "
                                         f"+{_ov:.2f} MPa over")
                    done_early = True
                elif _tot == 0:
                    stopped = ("every section on every face and direction "
                               "checked is inside the limit")
                    job.ok(f"**Nothing is over the limit on any of the "
                           f"{len(_left)} face/direction(s) checked.** That "
                           f"is the target - not a percentage of "
                           f"reinforcement - and it has been reached. "
                           f"Stopping.")
                    done_early = True
                else:
                    #  **18.78: الهندسة لوحدها كلّفت كام؟**
                    #  الدورة الأولى بتحرّك نقط ومابتزوّدش استرند. لو
                    #  الرقم ده أسوأ من اللي الموديل وصل بيه، يبقى
                    #  اللي بعده كله بيلاحق ضرر الرن عمله بنفسه - وده
                    #  بالظبط اللي حصل على 15-SOUTH: 7 فوق الحد عند
                    #  الوصول، 22 بعد تحريك 424 نقطة وقبل أول استرند.
                    if rnd == 1 and base_over is not None:
                        _bo = int(base_over)
                        job.log("What the profile changes alone cost", "head")
                        if _tot > _bo:
                            job.flag(
                                f"**The floor arrived with {_bo} section(s) "
                                f"over the limit and the profile changes "
                                f"alone have made it {_tot}** - no strand has "
                                f"been added yet. A profile is a design, not "
                                f"a set of independent points: the peaks sit "
                                f"where the moments are. Everything this run "
                                f"spends from here is chasing damage it did "
                                f"itself. The two switches are 'take the "
                                f"drape on tendons read from the model' and "
                                f"'geometry before force' on the EFM page - "
                                f"turn the first off and run again, and the "
                                f"run below starts from the floor you drew.")
                        elif _tot < _bo:
                            job.ok(f"The floor arrived with {_bo} section(s) "
                                   f"over the limit and moving the points "
                                   f"alone has taken it to {_tot} - "
                                   f"{_bo - _tot} closed for no steel at all.")
                        else:
                            job.info(f"    {_tot} over the limit, the same as "
                                     f"the floor arrived with. Moving the "
                                     f"points cost nothing and bought "
                                     f"nothing; the strands come next.")
                    job.info("    still over the limit: "
                             + ", ".join(f"{k} {v}"
                                         for k, v in sorted(_left.items())
                                         if v)
                             + f" ({_tot} in total)"
                             + (f" · {_u} more out of reach of prestress, "
                                f"left out of the count"
                                if obj == "section_only" and _u else ""))
                    if (budget_total is not None and budget_hit
                            and not added_this):
                        stopped = "the kg/m2 limit is reached"
                        job.warn(f"**The strand limit is reached** - "
                                 f"{floor_strand_kg(tendons, params):,.0f} kg "
                                 f"on the floor against {budget_total:,.0f} kg "
                                 f"({_rate:.2f} kg/m2), and nothing more fits "
                                 f"this round. Stopping: the {_tot} section(s) "
                                 f"still over the limit are left for a "
                                 f"solution in the concrete, and the review "
                                 f"screen shows each one.")
                        done_early = True
                    #  دورتين ورا بعض من غير ما العدد ينزل بما يستاهل =
                    #  وقوف. **دورة واحدة مش كفاية**: في رن المهندس
                    #  الحديد نزل 1.8% في دورة وبعدها 11.8% في اللي
                    #  بعدها، فقاعدة على دورة واحدة كانت هتقطع الحلقة
                    #  قبل أكبر مكسب فيها.
                    _min_close = int(getattr(params, "efm_min_close", 1) or 0)
                    stalled, _stop = efm_stall_step(was_fails, _tot, stalled,
                                                    _min_close)
                    if _stop:
                        stopped = (f"two rounds in a row closed fewer "
                                   f"than {_min_close} reading(s)")
                        job.warn(
                            f"**Stopping: the loop has stopped making "
                            f"progress.** Two rounds running took fewer "
                            f"than {_min_close} reading(s) off the count "
                            f"over the limit - it stands at {_tot}, "
                            f"against {was_fails} a round ago. More "
                            f"rounds here spend strands and analysis time "
                            f"without closing sections. What is left "
                            f"wants a look by hand: the section review "
                            f"screen names each one, and a section that "
                            f"will not close to prestress is asking for "
                            f"depth or reinforcement.")
                        done_early = True
                    _miss = [d for d in ("x", "y")
                             if not any(k.endswith("_" + d)
                                        for k in fail_hist)]
                    if _miss:
                        job.warn(
                            f"No export was read for "
                            f"{' and '.join(_dir_name(d) for d in _miss)}. "
                            f"Whatever is short in that direction is "
                            f"invisible to this run, and no strand it adds "
                            f"is aimed there. On a real floor the two "
                            f"directions failed in different places - 44 "
                            f"readings over in Y against 19 in X on the same "
                            f"face - so one export is half the check.")
            #  البروفايل مقابل القطاع اللي تحته، في نفس الاتجاه. دي
            #  علامة مش حركة: القمة ممكن تكون هناك عشان دروب أو حيطة.
            try:
                for _pp2 in _fresh:
                    if isinstance(_pp2, RamSectionPlot):
                        _pl2 = _pp2
                    else:
                        _p2, _, _d2 = str(_pp2).partition("|")
                        _pl2 = StressPlot(_p2, direction=_d2 or None)
                    _mk = profile_vs_demand(tendons, _pl2, params, job)
                    #  **العلامة مش كفاية لما تكون هي السبب.** على سقف
                    #  حقيقي 11 من 20 قراءة راسبة تحتها قمة، ورن كامل
                    #  نزّل الحديد 34% وساب الـ20 زي ما هم.
                    if bool(getattr(params, "efm_drop_peaks", False)):
                        lower_peaks_over_tension(_mk, params, job)
                    break
            except Exception as e:
                job.warn(f"The profile-against-demand check did not run: {e}")
            geo_bad = audit_high_points(tendons, model.get("spans"),
                                        params, job)
            geo_spans = spans_with_off_peaks(geo_bad, table)
            #  البروفايل قبل القوة. القمة الغلط بتخلّي كل استرند بعدها
            #  يشتغل في المكان الغلط، فتصليحها الأول بيغيّر كل الأرقام
            #  اللي بعدها - وبيتقاس في الدورة اللي بعدها زي أي حاجة.
            if bool(getattr(params, "peak_move", False)) and geo_bad:
                mv, bl = move_peaks_onto_supports(
                    geo_bad, tendons, params, job,
                    spans=model.get("spans"))
                if mv:
                    job.info("The next round is drawn with those peaks in "
                             "their new place, so its numbers already "
                             "include the fix - that is the measurement of "
                             "whether it was the right move.")
                    geo_bad = [d for d in geo_bad
                               if d["tendon"]["profile"][d["i"]]
                               .get("_peak_off_support") is not None]
                    geo_spans = spans_with_off_peaks(geo_bad, table)
            if rnd == 1:
                flagged.update(round1_flags(table, tendons, params, face))
            if flagged:
                try:
                    fpath = os.path.join(out_dir, f"{stem}_EFM_flags.json")
                    with open(fpath, "w", encoding="utf-8") as fh:
                        json.dump({"model": stem, "round": 1,
                                   "spans": list(flagged.values()),
                                   "points": _marked_points(tendons)}, fh,
                                  ensure_ascii=False, indent=1)
                    job.ok(f"{len(flagged)} span(s) worth looking at after "
                           f"this first round are written to "
                           f"{os.path.basename(fpath)} - the heaviest spans, "
                           f"and the ones where two peaks sit too close to "
                           f"take a dip between them. Open "
                           f"{os.path.basename(path)} in the tendon editor "
                           f"and they are ringed on the plan. Whether more "
                           f"force helps them is what the next round "
                           f"answers.")
                except Exception as e:
                    job.warn(f"The flag file could not be written: {e}")
        if prev_kg is not None:
            gain = 100.0 * (prev_kg - total) / max(prev_kg, 1e-6)
            job.ok(f"Designed reinforcement went from {prev_kg:,.0f} kg to "
                   f"{total:,.0f} kg - "
                   + (f"down {gain:.1f}%." if gain >= 0
                      else f"UP {-gain:.1f}%."))

        #  البحر اللي حديده **زاد** بعد ما قوّيناه: المشكلة في مكان القمة
        #  مش في القوة. زيادة تانية هتزوّد الطين بلة.
        if worsened:
            job.warn(f"{len(worsened)} span(s) got WORSE after strands were "
                     f"added - the high point over them is in the wrong "
                     f"place, the force is not what is short:")
            for now, _was, dn, worse in sorted(
                    worsened, key=lambda z: -z[3])[:6]:
                g = geo_spans.get(now["key"])
                job.warn(f"    {now['name']:<10} +{dn} strands -> "
                         f"{worse:,.0f} kg MORE steel. Move its high point "
                         f"in the editor instead."
                         + (f" **The geometry says the same**: a peak here "
                            f"sits {100.0 * g['u']:.0f}% of the way into the "
                            f"span, {g['off_m']:.1f} m from the end."
                            if g else ""))
            for now, _was, _dn, _w in worsened:
                measured[now["key"]] = 0.0        # يتشال من الترشيح
            #  بتتكتب من **أول دورة تظهر فيها**، عشان تفتح محرّر الكابلات
            #  وتشوف القمم دي متعلّمة وانت لسه في نص الحلقة.
            for now, _was, dn, worse in worsened:
                flagged[now["key"]] = {
                    "name": now["name"], "set": now["set"],
                    "a": list(now["a"]), "b": list(now["b"]),
                    "mid": list(now["mid"]), "length": now["length"],
                    "worse_kg": round(worse, 1), "strands_added": dn,
                    "round": rnd}
            try:
                fpath = os.path.join(out_dir, f"{stem}_EFM_flags.json")
                with open(fpath, "w", encoding="utf-8") as fh:
                    json.dump({"model": stem, "round": rnd,
                               "spans": list(flagged.values()),
                               "points": _marked_points(tendons)}, fh,
                              ensure_ascii=False, indent=1)
                job.ok(f"The spans with a misplaced high point are written to "
                       f"{os.path.basename(fpath)}. Open the model in the "
                       f"tendon editor and they will be ringed on the plan.")
            except Exception as e:
                job.warn(f"The flag file could not be written: {e}")

            if bool(getattr(params, "efm_autofix", False)):
                lift = float(getattr(params, "efm_autofix_mm", 25.0) or 25.0)
                mv, st = raise_flagged_points(
                    tendons, list(flagged.values()), params, lift)
                if mv:
                    job.ok(f"{mv} high point(s) in those spans were raised "
                           f"{lift:.0f} mm automatically - the next round "
                           f"will show whether that was the right move.")
                if st:
                    job.warn(f"{st} of them are already at the top cover and "
                             f"were left alone. A peak at the cover cannot be "
                             f"lifted; it has to be moved ALONG the tendon "
                             f"until it sits over the support, and that is a "
                             f"judgement call - open them in the editor.")

        if lagging:
            job.warn(f"{len(lagging)} span(s) took strands and barely moved "
                     f"while the slab dropped "
                     f"{100.0 * slab_drop:.0f}% - these are what is left, and "
                     f"more force is not buying much there:")
            for now, was, dn, pc in sorted(
                    lagging, key=lambda z: -face_kg(z[1], face))[:6]:
                #  الكلمة مش الإشارة: "+4%" جنب بحر اتحسّن 4% بتتقري
                #  زيادة، و"-13%" جنب بحر ساء بتتقري نقص. الاتنين كانوا
                #  مقلوبين في العرض.
                #  والأرقام لازم تبقى **على نفس الوش**: السطر ده كان
                #  بيطبع kg للوشين والنسبة محسوبة على الوش المختار، فطلع
                #  "129 -> 174 كجم (نزل 0%)" - رقمين بيقولوا زاد وكلمة
                #  بتقول نزل، والاتنين صح كل واحد على وشه. دلوقتي كله
                #  على الوش اللي الحلقة شغّالة عليه.
                word = "fell" if pc >= 0 else "rose"
                job.warn(f"    {now['name']:<10} {face_kg(was, face):>7,.0f} "
                         f"-> {face_kg(now, face):>7,.0f} kg {face} face "
                         f"({word} {abs(pc):.0f}%) on +{dn} strands")
        promoted = [w for w in worsened if creep_count.get(w[0]["key"], 0) >= 2]
        if promoted:
            job.warn(f"{len(promoted)} of those were flagged because they "
                     f"have risen two rounds running - each rise on its own "
                     f"was under the threshold, but a span that climbs every "
                     f"time it is strengthened is a misplaced peak, not "
                     f"noise.")
        if crept:
            job.info(f"{len(crept)} span(s) rose a little but stayed under "
                     f"the flag threshold ({floor_kg:.0f} kg and "
                     f"{100.0 * floor_pc:.0f}%), so they are not called "
                     f"misplaced - watch them if they keep creeping up:")
            for now, was, dn, rise in sorted(crept, key=lambda z: -z[3])[:5]:
                job.info(f"    {now['name']:<10} {face_kg(was, face):>7,.0f} "
                         f"-> {face_kg(now, face):>7,.0f} kg {face} face "
                         f"(rose {rise:,.0f} kg) on +{dn} strands")
        sm = sum(int(t.get("strands") or 0) * float(t.get("length") or 0.0)
                 for t in tendons if not t.get("_deleted"))
        sm_hist.append(sm)
        #  الوزن الكامل بيتسجّل جنب وزن الوش المختار: الهدف بيتقاس على
        #  الوش، لكن **المقايضة لازم تتقاس على الاتنين** - نفس الاسترندات
        #  بتقلل الحديد العلوي كمان. من غير ده كنا بنقارن تكلفة كل
        #  الاسترندات بتوفير نص الحديد.
        kg_all = sum(float(v.get("kg") or 0.0) for v in table.values())
        hist.append({"round": rnd, "kg": total, "kg_all": kg_all,
                     "path": path, "spans": len(table),
                     "worsened": len(worsened),
                     "lagging": len(lagging), "sm": sm})
        if rnd == 1 and base_kg is not None:
            drift = total - base_kg
            if abs(drift) > max(0.005 * base_kg, 5.0):
                job.warn(f"Round 1 differs from the model you started with by "
                         f"{drift:+,.0f} kg although not one strand was added "
                         f"yet. That difference is the redraw itself, not the "
                         f"loop - the tendons were taken apart and written "
                         f"back. Judge every later round against round 1, not "
                         f"against the file you opened.")
                #  والسبب معروف ومقيس: قواعد البروفايل شغّالة. أكبر
                #  حاجة بتعملها في الدورة الأولى هي شدّ كل طرف كابل
                #  لعمق المرساة - على موديل مقيس، 32 طرف من 204 كانوا
                #  قمم حقيقية فوق ركائز طرفية، وكل واحد نزل 100 مم.
                #  وده بيحصل مرة واحدة، في الدورة الأولى بالظبط - زي
                #  الفرق ده.
                #  الحكم بقى مبني على المقارنة ملف بملف، مش على فرض.
                #  اتّهمنا نصف القطر واتّهمنا قواعد البروفايل والاتنين
                #  طلعوا بريئين بالقياس. لما الكابلات تطلع **هي هي** -
                #  نفس القطع ونفس العقد ونفس الاسترندات ونفس الجاكات -
                #  يبقى الفرق ده مش تغيير في التصميم أصلاً: الحديد اللي
                #  كان محفوظ في الملف مش ناتج تحليل للحالة دي بالظبط.
                #  وساعتها الأساس الصح للمقارنة هو الدورة 1، مش الملف.
                if same_model and same_model.get("near_same"):
                    #  "came back the same - 2 node(s) of 1371" بتتقري
                    #  متناقضة: الجملة بتقول «زي ما هي» والرقم بيقول
                    #  «اتنين اتغيّروا». الصياغة بتتبع الرقم.
                    _tc = int(same_model.get("touched") or 0)
                    _same = ("came back untouched - not one node of "
                             f"{same_model['nodes'][0]} moved"
                             if _tc == 0 else
                             f"came back all but identical - {_tc} node(s) "
                             f"of {same_model['nodes'][0]} differ, which is "
                             f"too few to explain any of it")
                    job.warn(
                        f"The two files were compared and the tendons "
                        f"{_same}, same strands, same "
                        f"jacks. So this difference is NOT a change in the "
                        f"design: the reinforcement stored in the file you "
                        f"opened was not produced by an analysis of this "
                        f"exact state. Round 1 is the baseline; the number "
                        f"in the file you opened is not comparable to it, "
                        f"and no setting of ours will close it.")
                elif bool(getattr(params, "efm_reprofile", False)):
                    job.warn(
                        "'Let the loop re-run the profile rules' is on, and "
                        "the file comparison above shows what it changed. "
                        "Set the profile rules to 'safety only' and the loop "
                        "measures only what the strands do.")

        #  عتبة المكسب على الحديد، ومالهاش معنى لـ section_only.
        if prev_kg is not None and obj != "section_only":
            gain = 100.0 * (prev_kg - total) / max(prev_kg, 1e-6)
            if gain < min_gain:
                stopped = (f"the last round gained {gain:+.1f}%, under the "
                           f"{min_gain:.1f}% worth carrying on for")
                job.ok(f"Stopping: {stopped}.")
                #  **الوقوف ده على الحديد، مش على السلامة.** لو لسه فيه
                #  قطاعات فوق الحد، اللي بيوقف هو عتبة المكسب - وده
                #  قرار اقتصادي، مش شهادة إن السقف سيف. الفرق ده كان
                #  ضايع: رن كامل وقف على 18.6% وساب 21 قراءة راسبة،
                #  والمستخدم سأل «ليه ماكملش لحد ما يسيف؟» - وكان حقه.
                _sofar = sum(v[-1] for v in fail_hist.values() if v)
                if _sofar > 0:
                    job.warn(
                        f"**That is a stop on cost, not on safety.** "
                        f"{_sofar} reading(s) are still over the "
                        f"limit across the faces checked. The loop stopped because the "
                        f"next round would not take enough weight off the "
                        f"reinforcement to be worth the strands - not "
                        f"because the floor is finished.")
                    job.info("    to carry on to a satisfied face instead, "
                             "lower 'stop under ...% gain' towards 0 and run "
                             "again from the model this run saved. The loop "
                             "will then only stop when that count reaches "
                             "zero, or when what is left is out of reach of "
                             "prestress and it says so by name.")
                break

        #  17.8.1: الوقفة اللي الحلقة قررتها بنفسها في آخر دورة (حد الكجم/م²،
        #  أو كل القطاعات جوّه الحد) مابتتكتبش فوقها «حد الدورات».
        if rnd == rounds_max and not done_early:
            stopped = ("this run was set to one round"
                       if rounds_max <= 1 else "the round limit was reached")
            _sofar = sum(v[-1] for v in fail_hist.values() if v)
            if _sofar > 0:
                #  **الرقم ده من قبل تصميم الدورة دي.** اللوحات اتقرت
                #  من الموديل اللي اتحفظ في أول الدورة، وبعدها اتحطّت
                #  الكابلات. فالعدد ده بيوصف الموديل **قبل** العلاج،
                #  مش بعده - وقول "لسه 88 راسبة" كإنه نتيجة الرن غلط.
                if added_this:
                    job.info(
                        f"{_sofar} reading(s) were over the limit on the "
                        f"exports you gave this round. Those exports came "
                        f"from the model as it stood **before** this round "
                        f"designed anything, and it has since placed "
                        f"{added_this} strand(s). Whether they closed is "
                        f"what the next export answers - this number is the "
                        f"question, not the answer.")
                elif rounds_max <= 1:
                    job.warn(f"**{_sofar} reading(s) are still over the "
                             f"limit** and this round placed nothing. "
                             f"Set 'rounds' higher, or check the bands the "
                             f"log says are full - those are not a strand "
                             f"problem.")
                else:
                    job.warn(f"The round limit stopped this, not the design: "
                             f"**{_sofar} reading(s) are still over the "
                             f"limit.** Raise 'rounds' and run again from "
                             f"the model this run saved - the loop only "
                             f"stops on its own when that count reaches "
                             f"zero.")
            break

        added_this += sum(int(_v) for _v in _LEDGER.values())
        for _k, _v in _LEDGER.items():
            ledger[_k] = int(ledger.get(_k, 0)) + int(_v)
        _LEDGER.clear()

        #  **البحر اللي مابيردّش: رجّع اللي دخله، وسيبه.**
        if bool(getattr(params, "efm_rollback", True)):
            dead = []
            for now, was, dn, pc in lagging:
                k = now["key"]
                if k in frozen:
                    continue
                if pc <= 1.0 and ledger.get(k):
                    dead.append((k, now))
            for now, was, dn, rise in worsened:
                k = now["key"]
                if k not in frozen and ledger.get(k):
                    dead.append((k, now))
            seen_k = set()
            back = 0
            for k, now in dead:
                if k in seen_k:
                    continue
                seen_k.add(k)
                give = int(ledger.get(k) or 0)
                if give <= 0:
                    continue
                #  شيل الاسترندات من الكابلات اللي البحر ده اتزوّد فيها
                left = give
                for t in tendons:
                    if t.get("_deleted") or left <= 0:
                        continue
                    if k not in (t.get("_gave") or ()):
                        continue
                    can = int(t.get("_gave", {}).get(k, 0))
                    take = min(can, left, max(int(t.get("strands") or 0)
                                              - int(getattr(params,
                                                            "min_strands", 2)
                                                    or 2), 0))
                    if take <= 0:
                        continue
                    t["strands"] = int(t["strands"]) - take
                    t["_gave"][k] = can - take
                    left -= take
                    back += take
                frozen[k] = now["name"]
                ledger[k] = 0
            if seen_k:
                job.warn(f"{len(seen_k)} span(s) took strands and did not "
                         f"answer. **{back} strand(s) have been taken back "
                         f"out of them**, and they are left out of every "
                         f"round from here - force is not what they are "
                         f"short of, and carrying it costs money on the "
                         f"floor for nothing.")
                for k in list(seen_k)[:6]:
                    job.warn(f"    {frozen[k]:<12} frozen - look at its "
                             f"depth, its support, or a load the tendons "
                             f"cannot reach")

        #  **الدورة الأولى بتقول «مافيش استرندات» - فلازم تبقى مافيش.**
        #  الحاجز كان على مسار إعادة التوزيع بس، ومسار الحديد المصمَّم
        #  عدّى من جنبه: رن حقيقي طبع "No strands are added this round on
        #  purpose" وبعدها بستة سطور "+32 strands placed over 17 spans".
        #  الوعد اللي البرنامج بيكتبه لازم يكون هو اللي بيعمله.
        if done_early:
            break
        if geometry_only:
            job.ok("Round 1 moved geometry only, and nothing else was added: "
                   "no re-banding, and no strand raise on the designed "
                   "rebar either. Export the plot from the model this round "
                   "saved - the difference against the plot you gave it is "
                   "what the points alone were worth, with nothing else "
                   "mixed in. Round 2 pays for whatever is still short.")
            geometry_only = False
            geo_baseline = sum(face_kg(v, _face_of(params))
                               for v in table.values())
            continue

        #  **section_only (17.2): أقل استرندات تعدّي حد الكود.** الدورة
        #  عالجت القطاعات فوق الحد فوق (الكابلات المضافة وقاعدة الوش العلوي)،
        #  وده كل اللي بتعمله. مافيش رفع استرندات على الحديد المصمَّم - على
        #  تصميم من المومنت، zero_rebar زوّد 162 استرند على 75 كابل في دورة
        #  واحدة وملاهم لحد الأقصى، فحارات الوش العلوي مالقتش مكان تتعالج
        #  فيه. ومافيش وقوف على "مافيش بحر محتاج": الوقوف لما مايبقاش قطاع
        #  فوق الحد في أي وش واتجاه، أو الدورات تخلص.
        if obj == "section_only":
            prev_table, prev_kg = table, total
            continue
        advice = efm_advice(table, params, obj, measured=measured,
                            max_step=max_step)
        if frozen:
            n0 = len(advice)
            advice = [a for a in advice if a.get("key") not in frozen]
            if n0 != len(advice):
                job.info(f"    {n0 - len(advice)} span(s) were dropped from "
                         f"this round's advice because they are frozen.")
        sk = getattr(efm_advice, "skipped", None)
        if sk and (sk[0] or sk[1]):
            bits = []
            if sk[0]:
                bits.append(f"{sk[0]} carry fewer than {sk[2]} bars on the "
                            f"{face} face")
            if sk[1]:
                bits.append(f"{sk[1]} are shorter than {sk[3]:.1f} m")
            job.info(f"{sk[0] + sk[1]} span(s) with designed steel were left "
                     f"out of the treatment: " + " and ".join(bits) + ". A "
                     f"bar or two over the minimum is not worth a tendon, "
                     f"and steel in a short span usually comes from the "
                     f"tendons themselves - more force there makes it worse, "
                     f"not better.")
            #  أتقل اللي اتشال بيتقال بالاسم: لو واحد منهم مستاهل فعلاً،
            #  الحد في الإعدادات وانت اللي تنزّله - مش قرار البرنامج
            #  يتاخد في الضلمة.
            for r, why in getattr(efm_advice, "skipped_rows", []):
                job.info(f"    {r['name']:<12} {face_kg(r, face):>7,.0f} kg "
                         f"left alone - {why}")
        if not advice:
            if obj == "min_cost":
                rs = [v.get("breakeven", 0.0) for v in table.values()
                      if v.get("breakeven")]
                best = max(rs) if rs else 0.0
                ps = float(getattr(params, "efm_price_strand", 3.5) or 0.0)
                pr = float(getattr(params, "efm_price_rebar", 0.9) or 0.0)
                stopped = ("no strand pays for itself at these prices")
                job.ok(f"Stopping: {stopped}. The best span reaches "
                       f"{best:.2f} - a strand there buys back "
                       f"{best * 100:.0f}% of its own cost in rebar.")
                job.info(f"At {ps:g} per metre of strand and {pr:g} per kg of "
                         f"rebar, a strand would start to pay below "
                         f"{ps * best:.2f} per metre, or above "
                         f"{pr / max(best, 1e-6):.2f} per kg of rebar. And "
                         f"this weighs steel against steel only - it does "
                         f"not know that post-tensioning is what lets the "
                         f"slab be thinner and the spans longer, which is "
                         f"usually what actually pays for it. Read it as an "
                         f"answer to the narrow question, not to whether PT "
                         f"is worth it.")
            else:
                stopped = "the objective is met - no span needs more strands"
                job.ok(f"Stopping: {stopped}.")
            break

        #  لو الكابل الإضافي غطّى البحر، البحر ده **يخرج** من ترشيح
        #  رفع الكابلات الطويلة - وإلا كان هياخد قوة مرتين: مرة من
        #  الكابل الجديد ومرة من رفع القديم.
        if bool(getattr(params, "efm_add_tendons", False)):
            #  الأول: الكابل الإضافي اللي وصل للحد ولسه البحر قاصر
            #  يتحوّل لكابلين في نفس الفراغ - لو الفراغ يسمح.
            split_added_tendons(tendons, advice, params, job)
            n_new, s_new, covered = add_tendons_for_shortfall(
                tendons, advice, params, job, site=site)
            rest = [d for d in advice if d["key"] not in covered]
            if covered:
                job.info(f"{len(covered)} span(s) are now served by an added "
                         f"tendon and are left out of the strand raise, so "
                         f"the force is not put in twice. "
                         f"{len(rest)} span(s) still go to the existing "
                         f"tendons.")
        else:
            n_new = s_new = 0
            rest = advice
            covered = set()
        added, orphan = allocate_strands(tendons, rest, params, job)
        added += s_new
        job.ok(f"+{added} strands placed over {len(advice)} spans for the "
               f"next round.")
        if orphan:
            job.warn(f"{orphan} span(s) that need strands have no tendon "
                     f"running along them - they cannot be fixed by adding "
                     f"strands. Draw tendons there, or accept the rebar.")
        if added == 0:
            #  السبب مش دايماً "كله وصل للحد". لما كل البحور المحتاجة
            #  بقت متغطّية بكابل إضافي، التوزيع بيلاقي قدامه لا شيء
            #  ويرجّع صفر - وده حاجة تانية خالص. الرسالة بقت بتقول
            #  الاتنين بأسمائهم.
            if not rest and covered:
                stopped = ("every short span is already served by an added "
                           "tendon, and those tendons are at the cap for an "
                           "added tendon")
            else:
                stopped = ("no strand could be added - every tendon over the "
                           "short spans is at its cap")
            job.warn(f"Stopping: {stopped}.")
            break
        prev_table, prev_kg = table, total

    #  البحور اللي ماستجابتش **على مدى الحلقة كلها**.
    #
    #  الكشف الدوري بيقارن دورة بالدورة اللي قبلها، وده بيفوّت أهم حالة:
    #  بحر بياخد استرندات كل دورة وحديده واقف مكانه. في رن حقيقي، بحر
    #  43-1 خد 8 استرندات على تلات دورات وحديده السفلي راح من 101 لـ 90
    #  لـ 91 كجم - كل دورة لوحدها تحت العتبة، فماتقالش عنه حاجة، والبلاطة
    #  كلها كانت بتنزل 15% و14% في نفس الوقت. الجمع هو اللي بيوريه.
    #
    #  ودي بالظبط علامة القمة اللي في مكان غلط: القوة مش هي الناقصة.
    if first_table is not None and last_table is not None \
            and last_table is not first_table:
        face = _face_of(params)
        k0 = sum(face_kg(v, face) for v in first_table.values())
        k1 = sum(face_kg(v, face) for v in last_table.values())
        drop = (k0 - k1) / k0 if k0 > 1e-6 else 0.0
        floor_kg = float(getattr(params, "efm_flag_kg", 50.0) or 0.0)
        stale = []
        for key, now in last_table.items():
            was = first_table.get(key)
            if not was:
                continue
            dn = (now["strands"] or 0) - (was["strands"] or 0)
            was_kg = face_kg(was, face)
            now_kg = face_kg(now, face)
            if dn < 2 or was_kg <= floor_kg:
                continue
            got = (was_kg - now_kg) / max(was_kg, 1e-6)
            #  العتبة هنا أقسى من العتبة الدورية (الثلث): على مدى
            #  الحلقة كلها الضوضاء بتتوسّط وتختفي. بالثلث كان بحر 43-1
            #  بيعدّي بفارق شعرة (9.9% جنب 9.2%) وهو واقف فعلاً - نزل
            #  10% وحده والبلاطة نزلت 27.6% وهو خد 8 استرندات.
            if drop > 0.05 and got < drop / 2.0:
                stale.append((now, was, dn, 100.0 * got))
        if stale:
            job.log("", "info")
            job.warn(f"{len(stale)} span(s) took strands round after round "
                     f"and never responded, while the slab as a whole came "
                     f"down {100.0 * drop:.0f}%. More prestress is not what "
                     f"they are short of - look at where the high point sits "
                     f"over them:")
            agreed = 0
            for now, was, dn, pc in sorted(stale, key=lambda z: -z[3])[:8]:
                g = geo_spans.get(now["key"])
                if g:
                    agreed += 1
                job.warn(f"    {now['name']:<10} "
                         f"{face_kg(was, face):>7,.0f} -> "
                         f"{face_kg(now, face):>7,.0f} kg {face} face "
                         f"over the whole loop on +{dn} strands "
                         f"({pc:.0f}% against the slab's "
                         f"{100.0 * drop:.0f}%)"
                         + (f"   <- and its peak is {100.0 * g['u']:.0f}% "
                            f"into the span, at ({g['pos'][0]:.1f}, "
                            f"{g['pos'][1]:.1f})" if g else ""))
            n_geo_only = sum(1 for k in geo_spans
                             if k not in {z[0]["key"] for z in stale})
            if agreed:
                job.warn(f"{agreed} of them are confirmed by BOTH tests - the "
                         f"span does not answer to more force, and its peak "
                         f"measurably is not over the support. Those are the "
                         f"ones to move first; the fix is to drag the peak "
                         f"along the tendon onto the support, not to lift it.")
            else:
                job.info("None of them has a peak that the geometry calls "
                         "misplaced, so the reason they do not respond is "
                         "something else - depth, a support that is not "
                         "really there, or a load the tendons cannot reach.")
            if n_geo_only:
                job.info(f"{n_geo_only} more span(s) have an off-support peak "
                         f"but did respond to the extra force. Geometry alone "
                         f"is a warning, not a verdict - worth an eye in the "
                         f"editor, not a rebuild.")
            for now, was, dn, pc in stale:
                if now["key"] in flagged:
                    continue
                flagged[now["key"]] = {
                    "name": now["name"], "set": now["set"],
                    "a": list(now["a"]), "b": list(now["b"]),
                    "mid": list(now["mid"]), "length": now["length"],
                    "worse_kg": round(face_kg(now, face), 1),
                    "strands_added": dn, "round": len(hist),
                    "reason": "did not respond over the whole loop"}
            try:
                fpath = os.path.join(out_dir, f"{stem}_EFM_flags.json")
                with open(fpath, "w", encoding="utf-8") as fh:
                    json.dump({"model": stem, "round": len(hist),
                               "spans": list(flagged.values())}, fh,
                              ensure_ascii=False, indent=1)
                job.ok(f"They are in {os.path.basename(fpath)} with the rest "
                       f"- open the model in the tendon editor and every one "
                       f"of them is ringed on the plan.")
            except Exception as e:
                job.warn(f"The flag file could not be written: {e}")

    #  **الكتابة الأخيرة.** لو الدورة الأخيرة عملت أي حاجة بعد الحفظ -
    #  حرّكت نقطة، زوّدت كابل، رفعت استرندات - الملف المحفوظ لسه من
    #  قبلها. من غير المرور ده، آخر دورة في أي رن بتروح، والرن اللي
    #  دورته واحدة بيروح كله.
    if saved_fp is not None and tendon_fingerprint(tendons) != saved_fp:
        #  **18.34: الموديل اللي بيتسلّم هو أحسن دورة، مش آخر دورة.**
        try:
            _now = sum(v[-1] for v in fail_hist.values() if v)
            _now_key = efm_state_key(_now, tendons)
            if best_state is not None and best_state[0] < _now_key:
                _moved, _delta = efm_restore(tendons, best_state[1])
                job.warn(
                    f"**Going back to round {best_state[2]}.** The loop ends "
                    f"with {_now_key[0]} reading(s) over the limit and "
                    f"{_now_key[1]:,.0f} strand-metres; round "
                    f"{best_state[2]} stood at {best_state[0][0]} over and "
                    f"{best_state[0][1]:,.0f}. Adding prestress to a floor "
                    f"that is already close to balanced lifts it, and the "
                    f"tension moves rather than goes - the rounds after that "
                    f"one closed the bands they treated and opened others "
                    f"elsewhere, which is why the per-band rollback found "
                    f"nothing to undo. {_moved} tendon(s) go back, "
                    f"{abs(_delta)} strand(s) "
                    + ("out" if _delta < 0 else "in") + ".")
                job.info("    the model written below is that state, and it "
                         "is analysed again before it is saved - so the file "
                         "you keep is the best the loop reached, not the "
                         "last thing it tried.")
        except Exception as _e:
            job.info(f"    the best-round check was skipped ({_e}).")
        try:
            job.log("", "info")
            job.log("Writing the last round's work into the model", "head")
            job.info("    the model is saved at the start of each round, "
                     "from the tendons as they stood then. This round "
                     "changed them after that, so what you have on disk is "
                     "still the state before those changes. One more draw "
                     "and analysis puts them in.")
            job.step(0.90, "Writing the final model")
            clear_tendons_in_ram(session, job)
            write_tendons_to_ram(session, tendons, job, params,
                                 drops=(site or {}).get("drops"), site=site)
            if bool(getattr(params, "place_jacks", True)):
                try:
                    write_jacks_to_ram(session, tendons, job, params)
                except Exception as e:
                    job.warn(f"Jacks were not placed in the final "
                             f"write: {e}")
            _fres = run_model_analysis(session, job, mesh_size)
            _fp = os.path.join(out_dir, f"{stem}_EFM_final.cpt")
            _k = 2
            while _fp in _mine or os.path.isfile(_fp):
                _fp = os.path.join(out_dir, f"{stem}_EFM_final-{_k}.cpt")
                _k += 1
            _mine.add(_fp)
            if safe_save(session, _fp, job):
                best_path = _fp
                saved_fp = tendon_fingerprint(tendons)
                _n = sum(1 for t in tendons if t.get("added")
                         and not t.get("_deleted"))
                _st = sum(int(t.get("strands") or 0) for t in tendons
                          if t.get("added") and not t.get("_deleted"))
                job.ok(f"**{os.path.basename(_fp)} is the model to keep.** "
                       f"It carries everything this run designed - "
                       f"{_n} added tendon(s), {_st} added strand(s), and "
                       f"every point the loop moved. The earlier files are "
                       f"the states before each round.")
                job.info("    the failing-reading counts above describe the "
                         "model this run READ, not this one. To see what "
                         "the design actually did, export the plots again "
                         "from this file and run once more - and that run "
                         "starts already priced on what a strand was "
                         "measured to be worth here.")
                if not _fres.get("ok"):
                    job.warn("    RAM did not finish the analysis on this "
                             "final model, so its reinforcement figures are "
                             "not refreshed. The tendons in it are correct; "
                             "run Calc All in RAM to get its steel.")
                try:
                    _m = read_designed_steel(_fp)
                    if _m.get("rebar"):
                        _t = steel_by_span(_m)
                        _kg = sum(face_kg(v, _face_of(params))
                                  for v in _t.values())
                        hist.append({"round": "final", "kg": _kg,
                                     "path": _fp})
                        job.ok(f"Designed reinforcement on the final model: "
                               f"{_kg:,.0f} kg. That is the number this run "
                               f"actually produced.")
                        #  **حكم على التخفيف بالرقم.** التخفيف بيحسب
                        #  الضغط المحوري بس، والاسترند بيشيل حمل موازن
                        #  كمان. لو الحديد طلع بعد رن خفّف فيه، ده
                        #  قياس إن الحساب كان متفائل - ولازم يتقال
                        #  بصوت عالي مش يتساب للمهندس يكتشفه.
                        _r1 = next((q["kg"] for q in hist
                                    if q.get("round") == 1), None)
                        if thinned_all and _r1 and _kg > _r1 + 0.5:
                            job.warn(
                                f"**The thinning did not pay off on this "
                                f"floor.** {thinned_all} strand(s) came out "
                                f"of places the section check said were "
                                f"over-provided, and the same number went "
                                f"into the short bands - yet the "
                                f"reinforcement went from {_r1:,.0f} kg to "
                                f"{_kg:,.0f} kg, UP {_kg - _r1:,.0f} kg.")
                            job.info(
                                "    that is the caveat printed with every "
                                "thinning, measured: a strand carries "
                                "balanced load through its drape as well as "
                                "axial precompression, and only the axial "
                                "part is in the calculation. Where the "
                                "strand came out, the uplift went with it "
                                "and the span answered with bottom steel. "
                                "Raise 'Margin a thinned section must keep' "
                                "well above 0.60, or switch the thinning "
                                "off on this floor - the number above is "
                                "the evidence either way.")
                        elif thinned_all and _r1:
                            job.ok(
                                f"    the thinning paid: {thinned_all} "
                                f"strand(s) moved from where they bought "
                                f"nothing to where the slab was short, and "
                                f"the reinforcement still went "
                                f"{_r1:,.0f} -> {_kg:,.0f} kg. The floor "
                                f"carries the same prestress and less "
                                f"steel.")
                except Exception:
                    pass
        except Exception as e:
            job.error(f"The final write did not complete ({e}). The last "
                      f"model saved is {os.path.basename(best_path or '-')}, "
                      f"and it does NOT contain this round's additions.")

    #  الخلاصة
    if hist:
        job.log("", "info")
        job.log("EFM loop summary", "head")
        if _reverted:
            job.info(f"{_reverted} band(s) were undone because their strands "
                     f"made their own sections worse; those places were "
                     f"closed to strands from then on.")
        first = hist[0]["kg"]
        last = hist[-1]["kg"]
        for h in hist:
            job.info(f"    round {h['round']}: {h['kg']:,.0f} kg"
                     + (f" · {h['worsened']} worse"
                        if h.get("worsened") else "")
                     + (f" · {h['lagging']} not responding"
                        if h.get("lagging") else ""))
        #  المقايضة: صرفنا كام استرند-متر عشان نوفّر كام كيلو حديد.
        #  ده الرقم اللي بيقول إذا كانت الحلقة كسبت فعلاً ولا بس نقلت
        #  التكلفة من الحديد للاسترند.
        if len(sm_hist) >= 2 and hist:
            d_sm = sm_hist[-1] - sm_hist[0]
            d_kg = hist[0].get("kg_all", hist[0]["kg"]) - \
                hist[-1].get("kg_all", hist[-1]["kg"])
            face_now = _face_of(params)
            if d_sm > 1.0:
                ps = float(getattr(params, "efm_price_strand", 0.0) or 0.0)
                pr = float(getattr(params, "efm_price_rebar", 0.0) or 0.0)
                job.info(f"The trade: {d_sm:,.0f} strand-metres more "
                         f"prestress bought {d_kg:,.0f} kg less "
                         f"reinforcement across BOTH faces - "
                         f"{d_kg / d_sm:.2f} kg of steel per strand-metre."
                         + (f" (The loop was chasing the {face_now} face, "
                            f"but the same strands take steel off the other "
                            f"one too, so the trade counts both.)"
                            if face_now != "both" else ""))
                if ps > 0 and pr > 0:
                    cost = d_sm * ps
                    save = d_kg * pr
                    job.info(f"At {ps:g} per strand-metre and {pr:g} per kg "
                             f"that is {cost:,.0f} spent against "
                             f"{save:,.0f} saved - "
                             + ("worth it on steel alone."
                                if save > cost else
                                "NOT worth it on steel weight alone, though "
                                "that ignores what the prestress does for "
                                "deflection and cracking."))
        if first > 0:
            pc = 100.0 * (first - last) / first
            job.ok(f"Designed reinforcement {first:,.0f} kg -> {last:,.0f} kg "
                   + (f"- down {pc:.1f}%. " if pc >= 0
                      else f"- UP {-pc:.1f}%. ")
                   + f"Stopped because {stopped}.")
        #  الحساب الشريف: مقابل **الملف اللي فتحته**، مش مقابل الدورة
        #  الأولى. المقارنة بالدورة الأولى بتشيل تكلفة إعادة الرسم من
        #  الحساب، وهي تكلفة حقيقية دفعتها. لو النتيجة النهائية أسوأ من
        #  اللي بدأت بيه، ده لازم يتقال في سطر واحد واضح.
        if base_kg:
            d = last - base_kg
            if d > max(0.005 * base_kg, 5.0):
                if same_model and same_model.get("near_same"):
                    job.info(
                        f"Against the file you opened it reads "
                        f"{base_kg:,.0f} kg -> {last:,.0f} kg, {d:,.0f} kg "
                        f"more - but those two numbers are not comparable. "
                        f"The tendons in both files are identical, so the "
                        f"reinforcement stored in the file you opened was "
                        f"not produced by an analysis of that same state. "
                        f"The honest measure of this run is round 1 to the "
                        f"last round.")
                else:
                    job.warn(
                        f"Against the file you opened, though: "
                        f"{base_kg:,.0f} kg -> {last:,.0f} kg, which is "
                        f"{d:,.0f} kg MORE, and the file comparison in round "
                        f"1 shows the tendons did change on the way in. Read "
                        f"that comparison - it says what moved.")
            elif d < -max(0.005 * base_kg, 5.0):
                job.ok(f"Against the file you opened: {base_kg:,.0f} kg -> "
                       f"{last:,.0f} kg, {-d:,.0f} kg less - the loop is "
                       f"ahead even after paying for its own redraw.")
            else:
                job.info(f"Against the file you opened: {base_kg:,.0f} kg -> "
                         f"{last:,.0f} kg - level. Everything the loop won "
                         f"went on paying for its own redraw.")
        job.ok(f"The model to keep: {os.path.basename(best_path or '')}")
    try:
        if _area_m2:
            _kgf = floor_strand_kg(tendons, params)
            job.info(f"Strand on the floor: {_kgf:,.0f} kg = "
                     f"{_kgf / _area_m2:.2f} kg/m2 over {_area_m2:,.0f} m2"
                     + (f" (limit {_rate:.2f} kg/m2)" if budget_total else ""))
    except Exception:
        pass
    return {"rounds": hist, "best": best_path, "stopped": stopped,
            "groups": section_groups}


def export_tendons_dxf(path, site, tendons, support_lines, params, bands=None):
    """
    تصدير المسارات لملف DXF جديد للمراجعة أو للإدراج في لوحات التنفيذ.
    كل عنصر في ليّر منفصل، والمناسيب مكتوبة كنصوص عند النقط العالية والسفلية.
    """
    import ezdxf

    doc = ezdxf.new("R2010", setup=True)
    doc.header["$INSUNITS"] = 6          # متر
    msp = doc.modelspace()

    layers = {
        "AUTOPT-BOUNDARY": 7,
        "AUTOPT-OPENING": 1,
        "AUTOPT-DROP": 4,
        "AUTOPT-COLUMN": 5,
        "AUTOPT-WALL": 8,
        "AUTOPT-TENDON-X": 5,
        "AUTOPT-TENDON-Y": 3,
        "AUTOPT-BAND": 6,
                "AUTOPT-TEXT": 2,
    }
    for name, color in layers.items():
        if name not in doc.layers:
            doc.layers.add(name, color=color)

    if site.get("boundary"):
        for _pc in ((site.get("pieces") or [site["boundary"]])
                    if len(site.get("pieces") or []) > 1 else [site["boundary"]]):
            msp.add_lwpolyline(_pc, close=True,
                               dxfattribs={"layer": "AUTOPT-BOUNDARY"})
    for op in site.get("openings", []):
        msp.add_lwpolyline(op, close=True, dxfattribs={"layer": "AUTOPT-OPENING"})
    for dp in site.get("drops", []):
        msp.add_lwpolyline(dp, close=True, dxfattribs={"layer": "AUTOPT-DROP"})

    for c in site.get("columns", []):
        b = c.get("b", 400.0) / 2000.0
        d = c.get("d", 400.0) / 2000.0
        cx, cy = c["center"]
        a = math.radians(c.get("angle_deg", 0.0))
        ca, sa = math.cos(a), math.sin(a)
        pts = [(cx + dx * ca - dy * sa, cy + dx * sa + dy * ca)
               for dx, dy in ((-b, -d), (b, -d), (b, d), (-b, d))]
        msp.add_lwpolyline(pts, close=True, dxfattribs={"layer": "AUTOPT-COLUMN"})

    for w in site.get("walls", []):
        msp.add_line(w["p1"], w["p2"], dxfattribs={"layer": "AUTOPT-WALL"})

    text_h = 0.15

    # Banded groups: the outline of each band and its centre line, so what the
    # crossing tendons were lifted over can be checked on the drawing.
    for b in (bands or []):
        foot = b.get("footprint") or []
        #  الاسم ده كان `path` - نفس اسم مسار الملف اللي الدالة بتحفظ
        #  فيه. أول دور مجموعة، مسار الملف بيتمسح ويتحوّل لليستة نقط،
        #  و doc.saveas بيقع. فلوحة الـ DXF كانت بتضيع من غير سبب واضح
        #  في أي رن فيه مجموعات مربوطة.
        bpath = b.get("path") or []
        if len(foot) >= 3:
            msp.add_lwpolyline(foot, close=True,
                               dxfattribs={"layer": "AUTOPT-BAND"})
        if len(bpath) >= 2:
            msp.add_lwpolyline(bpath, dxfattribs={"layer": "AUTOPT-BAND"})
            mid = bpath[len(bpath) // 2]
            msp.add_text(f"BAND {b['dir']} x{b['lines']} "
                         f"({b.get('support', '?')})"
                         f"{' EDGE' if b.get('edge') else ''}", height=text_h,
                         dxfattribs={"layer": "AUTOPT-BAND"}
                         ).set_placement((mid[0], mid[1] + 0.25))

    for t in tendons:
        layer = "AUTOPT-TENDON-X" if t["dir"] == "X" else "AUTOPT-TENDON-Y"
        msp.add_lwpolyline([q["pos"] for q in t["profile"]],
                           dxfattribs={"layer": layer})
        for q in t["profile"]:
            if q.get("high") or q.get("inflection"):
                continue
        mid = t["profile"][len(t["profile"]) // 2]
        gids = [str(g) for _a, _b, g in (t.get("span_groups") or [])]
        msp.add_text(f"{t['strands']}S"
                     + ("  G" + "/G".join(gids) if gids else ""),
                     height=text_h,
                     dxfattribs={"layer": "AUTOPT-TEXT"}
                     ).set_placement((mid["pos"][0], mid["pos"][1] + 0.10))
        for q in t["profile"]:
            msp.add_text(f"{q['depth']:.0f}", height=text_h * 0.8,
                         dxfattribs={"layer": "AUTOPT-TEXT"}
                         ).set_placement((q["pos"][0], q["pos"][1] - 0.18))
            if q.get("band_high"):
                msp.add_circle(q["pos"], radius=0.12,
                               dxfattribs={"layer": "AUTOPT-BAND"})
        # Why each high point is where it is, one letter per rule:
        #   C column · W wall · B beam · D drop · A support axis
        #   F moment field · N band centre · G shared with the group
        for q in t["profile"]:
            if not q.get("high"):
                continue
            code = NODE_SOURCE_CODE.get(q.get("src"))
            if q.get("band_high"):
                code = "N"
            elif q.get("grouped") and not code:
                code = "G"
            if not code:
                continue
            msp.add_text(code, height=text_h * 0.8,
                         dxfattribs={"layer": "AUTOPT-TEXT"}
                         ).set_placement((q["pos"][0] + 0.10,
                                          q["pos"][1] + 0.10))


    doc.saveas(path)
    return path


# ==============================================================================
#  القسم 4د — تنظيف الهندسة قبل الكتابة
#
#  خطأ "An entity has become misshaped" اللي بيطلع من RAM أثناء التحليل معناه
#  إن عنصر واحد على الأقل هندسته مش صالحة للتشبيك. الموديل بيتحفظ عادي،
#  والخطأ بيظهر بس عند الحساب — فالفلتر ده لازم يشتغل قبل الكتابة.
#
#  أشهر الأسباب اللي بنمسكها هنا:
#    • عمود بُعده صفر بعد التقريب لأقرب 50 مم (شكل 20 مم → 0)
#    • مضلع بضلع طوله أقل من مليمترات — RAM بيرفض يشبّكه
#    • مضلع بيقطع نفسه (رقم ثمانية)
#    • قطعة كابل طولها شبه صفر
#    • حائط أو كمرة طولها صفر
# ==============================================================================

MIN_COLUMN_SIDE_MM = 100.0
MIN_MEMBER_LENGTH_M = 0.10
MIN_MEMBER_WIDTH_MM = 100.0
MIN_POLY_EDGE_M = 0.020
MIN_POLY_AREA_M2 = 0.010
MIN_TENDON_SEG_M = 0.050


def polygon_is_simple(pts, tol=1e-9):
    """
    هل المضلع بسيط (مش بيقطع نفسه)؟ O(n²) وده مقبول للمضلعات دي.
    الأضلاع المتجاورة بتتخطى لأنها بتشترك في رأس.
    """
    n = len(pts)
    if n < 4:
        return True
    for i in range(n):
        a1, a2 = pts[i], pts[(i + 1) % n]
        for j in range(i + 1, n):
            if j == i or (j + 1) % n == i or j == (i + 1) % n:
                continue
            b1, b2 = pts[j], pts[(j + 1) % n]
            hit = segment_intersection(a1, a2, b1, b2)
            if hit is None:
                continue
            # تجاهل التلامس عند رأس مشترك
            if min(dist(hit, a1), dist(hit, a2), dist(hit, b1), dist(hit, b2)) < 1e-6:
                continue
            return False
    return True


def sanitize_polygon(pts, min_edge=MIN_POLY_EDGE_M, min_area=MIN_POLY_AREA_M2):
    """
    تنظيف مضلع: شيل الرؤوس اللي بتعمل أضلاع قصيرة جدًا، والرؤوس على استقامة،
    وتأكد إنه بسيط وله مساحة معقولة.
    بترجع (المضلع النظيف أو None، سبب الرفض أو None).
    """
    poly = clean_polygon(pts, tol=min_edge)
    if len(poly) < 3:
        return None, "fewer than 3 vertices after cleaning"

    poly = drop_collinear(poly)
    if len(poly) < 3:
        return None, "all vertices are collinear"

    shortest = min(dist(poly[i], poly[(i + 1) % len(poly)])
                   for i in range(len(poly)))
    if shortest < min_edge:
        return None, f"shortest edge {shortest * 1000:.0f} mm"

    area = polygon_area(poly)
    if area < min_area:
        return None, f"area {area * 1e4:.0f} cm²"

    if not polygon_is_simple(poly):
        return None, "the polygon self-intersects"

    return poly, None


def _tally(counter, reason):
    counter[reason] = counter.get(reason, 0) + 1


def sanitize_site(site, job):
    """
    تنظيف كل هندسة الموديل قبل ما تتكتب في RAM.
    بيعدّل site في مكانه وبيرجع تقرير بالمرفوض.
    """
    rejected = {"slabs": {}, "openings": {}, "columns": {}, "walls": {}, "beams": {}}

    # ---------- البلاطات ----------
    clean_slabs = []
    for slab in site.get("slabs", []):
        poly, why = sanitize_polygon(slab["points"])
        if poly is None:
            _tally(rejected["slabs"], why)
            continue
        slab = dict(slab)
        slab["points"] = poly
        slab["area"] = polygon_area(poly)
        clean_slabs.append(slab)
    site["slabs"] = clean_slabs
    site["drops"] = [s["points"] for s in clean_slabs if s.get("is_drop")]

    if site.get("boundary"):
        poly, why = sanitize_polygon(site["boundary"])
        if poly is not None:
            site["boundary"] = poly
        else:
            job.error(f"The slab boundary itself was rejected ({why}) - "
                      f"the model will not analyse correctly.")

    # ---------- الفتحات ----------
    clean_openings = []
    for op in site.get("openings", []):
        poly, why = sanitize_polygon(op, min_area=MIN_POLY_AREA_M2 * 0.5)
        if poly is None:
            _tally(rejected["openings"], why)
            continue
        clean_openings.append(poly)
    site["openings"] = clean_openings

    # ---------- الأعمدة ----------
    clean_cols = []
    for c in site.get("columns", []):
        b = float(c.get("b", 0.0) or 0.0)
        d = float(c.get("d", 0.0) or 0.0)
        if c.get("circular"):
            b = d = max(b, d)
        if min(b, d) < MIN_COLUMN_SIDE_MM:
            # ده بالظبط اللي بيولّد "misshaped entity": بُعد صفر بعد التقريب
            _tally(rejected["columns"],
                   f"a side under {MIN_COLUMN_SIDE_MM:.0f} mm ({min(b, d):.0f})")
            continue
        c = dict(c)
        c["b"], c["d"] = b, d
        clean_cols.append(c)
    site["columns"] = clean_cols

    # ---------- الحوائط والكمرات ----------
    for key in ("walls", "beams"):
        clean = []
        for m in site.get(key, []):
            L = dist(m["p1"], m["p2"])
            if L < MIN_MEMBER_LENGTH_M:
                _tally(rejected[key], f"length {L * 1000:.0f} mm")
                continue
            width = float(m.get("width", 0.0) or 0.0)
            if width < MIN_MEMBER_WIDTH_MM:
                width = MIN_MEMBER_WIDTH_MM
            m = dict(m)
            m["width"] = width
            clean.append(m)
        site[key] = clean

    # ---------- التقرير ----------
    total = sum(sum(d.values()) for d in rejected.values())
    if total:
        job.warn(f"Geometry sanitiser: {total} elements removed before writing "
                 f"(they would have caused a misshaped entity error at analysis):")
        labels = {"slabs": "slab", "openings": "opening", "columns": "column",
                  "walls": "wall", "beams": "beam"}
        for key, reasons in rejected.items():
            for why, n in sorted(reasons.items(), key=lambda kv: -kv[1]):
                job.warn(f"    · {n}× {labels[key]}: {why}")
    else:
        job.ok("Geometry sanitiser: every element is valid.")

    return rejected


def _pa_from_tendons(tendons, params, direction, area_m2):
    """P/A بالميجاباسكال من عدد الاستراندات اللي في إيدنا دلوقتي."""
    force = 0.0
    for t in tendons:
        if t.get("dir") != direction:
            continue
        n = float(t.get("strands") or 0)
        per = (t["losses"]["force_per_strand"] if t.get("losses")
               else params.force_per_strand)
        force += n * per
    return (force / max(area_m2, 1e-6)) / 1000.0


def restate_pa_after_rounding(tendons, params, job, design):
    """
    **18.26: الـ P/A المكتوب لازم يكون بتاع الاستراندات اللي اترسمت.**

    حلقة الـ P/A بتنزّل استراندات لحد ما توصل للسقف - على الرن ده نزّلت
    23 سترند ووقفت عند 2.74 MPa وكل كابل على الحد الأدنى 2. وبعدين،
    قبل الرسم بثواني، `apply_allowed_strands` بترفع 89 كابل من 2 لـ 3
    عشان 2 مش مقاس متاح. يعني الرقم اللي الحلقة وصلت له اتكسر بعدها،
    والأوديت فضل بيقرا الرقم القديم من `design["pa"]` ويقول 2.74 -
    والموديل فيه قوة أكبر من كده.

    الترتيب نفسه مايتغيّرش (التقريب لازم يكون آخر خطوة قبل الكتابة)،
    بس الرقم بيتحسب تاني من الكابلات بعد التقريب، فاللي في التقرير
    واللي في الموديل واحد.
    """
    if not design or not isinstance(design.get("pa"), dict):
        return
    for direction in ("X", "Y"):
        info = ((design or {}).get("pa") or {}).get(direction)
        if not info or not info.get("area_m2"):
            continue
        strands_now = sum(int(t.get("strands") or 0) for t in tendons
                          if t.get("dir") == direction)
        was = float(info.get("pa_MPa") or 0.0)
        if strands_now == int(info.get("strands") or 0):
            continue
        now = _pa_from_tendons(tendons, params, direction, info["area_m2"])
        info["strands"] = strands_now
        info["force_kN"] = now * info["area_m2"] * 1000.0
        info["pa_MPa"] = now
        info["rounded_up"] = True
        info["strands_col"] = sum(int(t.get("strands") or 0) for t in tendons
                                  if t.get("dir") == direction
                                  and t.get("strip") == "column")
        info["strands_mid"] = sum(int(t.get("strands") or 0) for t in tendons
                                  if t.get("dir") == direction
                                  and t.get("strip") == "middle")
        if job and abs(now - was) >= 0.005:
            msg = (f"Direction {direction}: P/A is {now:.2f} MPa after the "
                   f"available-sizes rounding, not the {was:.2f} MPa the "
                   f"sizing loop stopped at - rounding up added strands the "
                   f"loop had taken off.")
            if now > float(getattr(params, "pa_max", 2.5) or 2.5):
                job.warn(msg + f" It is over the {params.pa_max:.2f} MPa "
                               f"ceiling: widen the tendon spacing or add a "
                               f"smaller strand size to the available list.")
            else:
                job.info(msg)


def finalize_strands(tendons, params, job, design=None):
    """
    آخر خطوتين قبل الكتابة، في مكان واحد (17.71): تقريب الاستراندات
    للمقاسات المتاحة ثم تنضيف الهندسة. كانوا مكتوبين كزوج في ست
    مسارات، ولو واحد اتعدّل الباقي مايتعدلش.

    18.26: وبعد التقريب، الـ P/A بيتحسب تاني على الاستراندات الجديدة لو
    تقرير التصميم معانا - عشان الأوديت مايقراش رقم اتكسر قبل الرسم.
    """
    #  18.80: اجمع المتجاورين قبل ما تقرّب - التقريب على كل كابل لوحده
    #  بيدفع درجة لكل واحد، والجمع بيدفع درجة واحدة للاتنين.
    try:
        merge_for_strand_sizes(tendons, params, job)
    except Exception as _e:
        job.warn(f"The tendons were rounded one at a time ({_e}).")
    apply_allowed_strands(tendons, params, job)
    out = sanitize_tendons(tendons, job)
    restate_pa_after_rounding(out, params, job, design)
    return out


def sanitize_tendons(tendons, job, min_seg=MIN_TENDON_SEG_M):
    """
    دمج نقط البروفايل المتقاربة جدًا وحذف الكابلات اللي بقت قصيرة.
    قطعة كابل طولها أقل من مليمترات بترفضها RAM عند التشبيك.
    """
    kept = []
    merged_pts = 0
    dropped = 0

    for t in tendons:
        prof = t["profile"]
        clean = [prof[0]]
        for q in prof[1:]:
            if dist(clean[-1]["pos"], q["pos"]) < min_seg:
                # النقطة الأقرب للسطح العلوي هي الأهم — نحتفظ بيها
                if q["depth"] < clean[-1]["depth"]:
                    keep_high = clean[-1].get("high") or q.get("high")
                    clean[-1] = dict(q)
                    clean[-1]["high"] = keep_high
                elif q.get("high"):
                    clean[-1]["high"] = True
                merged_pts += 1
                continue
            clean.append(q)

        # النهاية لازم تفضل النهاية الحقيقية للكابل
        if dist(clean[-1]["pos"], prof[-1]["pos"]) > 1e-9:
            if dist(clean[-1]["pos"], prof[-1]["pos"]) >= min_seg:
                clean.append(prof[-1])
            else:
                clean[-1] = prof[-1]

        if len(clean) < 2 or dist(clean[0]["pos"], clean[-1]["pos"]) < min_seg:
            dropped += 1
            continue

        t = dict(t)
        t["profile"] = clean
        kept.append(t)

    if merged_pts or dropped:
        job.warn(f"Tendon sanitiser: {merged_pts} points merged "
                 f"(closer than {min_seg * 1000:.0f} mm) · "
                 f"{dropped} tendons dropped as too short.")
    else:
        job.ok("Tendon sanitiser: every segment has a valid length.")

    return kept


