UI_LANG = "English"


def set_ui_language(lang):
    """UI text language: English or Arabic."""
    global UI_LANG
    value = str(lang or "English").strip()
    if value in ("Arabic", "العربية", "ar"):
        UI_LANG = "Arabic"
    else:
        UI_LANG = "English"
    return UI_LANG


