#  --- AR_UI_CHUNKS ---


def _has_arabic(text):
    try:
        return any("\u0600" <= ch <= "\u06FF" for ch in str(text))
    except Exception:
        return False


def tr(text):
    """النص بلغة الواجهة: الجدول الكامل، وإلا المقاطع القديمة، وإلا كما هو."""
    if UI_LANG != "Arabic" or not isinstance(text, str) or not text:
        return text
    hit = AR_UI.get(text)
    if hit is None:
        hit = AR_UI.get(text.strip())
    if hit is not None:
        return hit
    return ui_translate(text)


def _tr_widget(base):
    """نسخة من كلاس ويدجت بتترجم `text` وتحاذي العربي يمين."""

    #  18.125: `justify` للّيبل بس - زرار ttk وCheckbutton ttk مايقبلوش
    #  الخيار ده، وكان بيرمي TclError جوّه إعادة بناء الشاشة فتفضل فاضية.
    can_justify = base.__name__ == "Label"

    class Translated(base):
        def __init__(self, master=None, cnf=None, **kw):
            if "text" in kw:
                kw["text"] = tr(kw["text"])
                if can_justify and _has_arabic(kw["text"]):
                    kw.setdefault("justify", "right")
            if cnf is None:
                super().__init__(master, **kw)
            else:
                super().__init__(master, cnf, **kw)

        def configure(self, cnf=None, **kw):
            if "text" in kw:
                kw["text"] = tr(kw["text"])
            if cnf is None:
                return super().configure(**kw)
            return super().configure(cnf, **kw)

        config = configure

    Translated.__name__ = base.__name__
    return Translated


def install_ui_translation():
    """بيلفّ كلاسات الويدجت وصناديق الرسائل مرة واحدة عند بدء البرنامج."""
    if getattr(install_ui_translation, "_done", False):
        return
    install_ui_translation._done = True
    for mod, names in ((ttk, ("Button", "Checkbutton", "Radiobutton", "Label",
                              "Labelframe", "LabelFrame")),
                       (tk, ("Button", "Checkbutton", "Radiobutton", "Label",
                             "LabelFrame"))):
        for name in names:
            base = getattr(mod, name, None)
            if base is None or getattr(base, "_pt_translated", False):
                continue
            wrapped = _tr_widget(base)
            wrapped._pt_translated = True
            setattr(mod, name, wrapped)
    for name in ("showinfo", "showwarning", "showerror", "askyesno",
                 "askokcancel", "askquestion", "askretrycancel", "askyesnocancel"):
        fn = getattr(messagebox, name, None)
        if fn is None or getattr(fn, "_pt_translated", False):
            continue

        def make(f):
            def call(title=None, message=None, **kw):
                return f(tr(title), tr(message), **kw)
            call._pt_translated = True
            return call
        setattr(messagebox, name, make(fn))


def ui_translate(text):
    """Translate only the explanatory helper text in the UI.

    Actual field names and option values stay as they are. The hint text beside
    each setting is what is translated for Arabic.
    """
    if UI_LANG != "Arabic" or text is None:
        return text
    s = str(text)
    if not s.strip():
        return s

    bare = s.strip()
    if bare.lower() in {
        "tendon", "tendons", "strand", "strands", "anchor", "anchorage",
        "anchorages", "steel", "top cover", "bottom cover", "spacing",
        "edge offset", "band spacing", "long span lift", "minimum distance",
        "minimum point gap", "support line reach", "max gap",
        "design moment offset", "field veto", "clash offset"
    }:
        return s

