def _shop_notes(msp, params, origin, chair_drop, txt_h=SHOP_TEXT_H):
    """لوحة الملاحظات والمفتاح - الجزء اللي بيخلّي الورقة تتقرا لوحدها."""
    x0, y0 = origin
    w = 16000.0
    _shop_text(msp, "GENERAL NOTES", (x0, y0), txt_h * 1.4, "PT-Notes",
               align="BOTTOM_LEFT")
    msp.add_line((x0, y0 - 150.0), (x0 + w, y0 - 150.0),
                 dxfattribs={"layer": "PT-Notes"})
    y = y0 - 700.0
    for note in SHOP_NOTES:
        #  السطر بيتقطّع يدوي: TEXT مش MTEXT عشان يفضل مقروء في أي أوتوكاد
        words, line = note.split(), ""
        for word in words:
            if len(line) + len(word) + 1 > 95:
                _shop_text(msp, line, (x0, y), txt_h, "PT-Notes",
                           align="BOTTOM_LEFT")
                y -= txt_h * 1.8
                line = word
            else:
                line = (line + " " + word).strip()
        if line:
            _shop_text(msp, line, (x0, y), txt_h, "PT-Notes",
                       align="BOTTOM_LEFT")
            y -= txt_h * 2.4
    y -= 400.0
    _shop_text(msp, "LEGEND", (x0, y), txt_h * 1.4, "PT-Notes",
               align="BOTTOM_LEFT")
    msp.add_line((x0, y - 150.0), (x0 + w / 2, y - 150.0),
                 dxfattribs={"layer": "PT-Notes"})
    y -= 800.0
    legend = [("Tendons-A", "TENDON, DIRECTION A"),
              ("Tendons-B", "TENDON, DIRECTION B"),
              ("Text-Profile-A-HIGH", "HIGH POINT HEIGHT"),
              ("Text-Profile-A-LOW", "LOW POINT HEIGHT"),
              ("Text-Profile-A", "INTERMEDIATE CHAIR HEIGHT"),
              ("PT-Section-Support", "COLUMN / WALL / BEAM IN SECTION")]
    for layer, label in legend:
        msp.add_line((x0, y + 60.0), (x0 + 900.0, y + 60.0),
                     dxfattribs={"layer": layer})
        _shop_text(msp, label, (x0 + 1200.0, y), txt_h, "PT-Notes",
                   align="BOTTOM_LEFT")
        y -= txt_h * 2.2
    _shop_text(msp,
               f"SLAB {params.slab_thickness:.0f} / DROP "
               f"{params.drop_thickness:.0f} · COVER TOP "
               f"{params.covers_for('X')[0]:.0f} BOTTOM "
               f"{params.covers_for('X')[1]:.0f} · CHAIR SET "
               f"{chair_drop:.0f} mm BELOW THE TENDON CENTRELINE",
               (x0, y - 400.0), txt_h, "PT-Notes", align="BOTTOM_LEFT")
    return y - 1200.0


SHOP_TABLE_COLS = [
    ("MARK NO.", 1400), ("QTY", 700), ("ANCHOR NO.\n(SEE NOTE 1)", 1800),
    ("NO. OF\nSTRANDS", 1400), ("LENGTH\n(M)", 1200),
    ("NO. OF LIVE\nENDS", 1500), ("EXTENSION\n(MM)", 1500),
    ("STRAND\nTYPE", 1300), ("GUTS\n(KN)", 1100),
    ("JACKING FORCE\nPER STRAND (KN)", 2200),
]


def _shop_table(msp, rows, fam, params, origin, txt_h=SHOP_TEXT_H):
    """جدول الكابلات بخطوط وكتابة - نفس أعمدة الـ template."""
    x0, y0 = origin
    rh = 500.0
    head_h = 900.0
    widths = [w for _t, w in SHOP_TABLE_COLS]
    total_w = sum(widths)
    guts = params.strand_area * params.strand_fpu / 1000.0
    lp = getattr(params, "losses", None) or LossParameters()
    jack = params.strand_area * lp.jack_ratio * params.strand_fpu / 1000.0
    dia = {98.7: "12.7", 140.0: "15.24", 150.0: "15.7",
           100.0: "12.9"}.get(round(params.strand_area, 1), "15.24")

    def cell(x, y, w, h, text, height=txt_h, bold=False):
        msp.add_lwpolyline([(x, y), (x + w, y), (x + w, y - h), (x, y - h)],
                           close=True, dxfattribs={"layer": "Table"})
        lines = str(text).split("\n")
        for i, ln in enumerate(lines):
            _shop_text(msp, ln,
                       (x + w / 2.0,
                        y - h / 2.0 - (i - (len(lines) - 1) / 2.0) * height * 1.4),
                       height, "Table")

    _shop_text(msp, f"TENDON SCHEDULE ({fam})",
               (x0 + total_w / 2.0, y0 + 500.0), txt_h * 1.6, "Table")
    x = x0
    for (head, w) in SHOP_TABLE_COLS:
        cell(x, y0, w, head_h, head)
        x += w
    msp.add_lwpolyline([(x0, y0 + 250.0), (x0 + total_w, y0 + 250.0),
                        (x0 + total_w, y0 - head_h), (x0, y0 - head_h)],
                       close=True, dxfattribs={"layer": "Table"})
    y = y0 - head_h
    for r in rows:
        x = x0
        vals = [r["mark"], r["qty"], "", r["strands"], f"{r['length']:.1f}",
                r["live"], f"{r['elong']:.0f}", dia, f"{guts:.0f}",
                f"{jack:.0f}"]
        for (head, w), v in zip(SHOP_TABLE_COLS, vals):
            cell(x, y, w, rh, v)
            x += w
        y -= rh
    _shop_text(msp, "NOTE 1: ANCHOR NUMBERS ARE FILLED ON SITE AGAINST THE "
                    "STRESSING RECORD.", (x0, y - 400.0), txt_h,
               "PT-Notes", align="BOTTOM_LEFT")
    return y


