#
#  وضع "design the tendons from RAM's moments": بيقرا مومنت الأحمال الميتة
#  ومومنت طبقة Balance Loading على مسار كل كابل من رام مباشرة (الأمر
#  GET_SLAB_ANALYSIS_USER - اتأكد عليه ببلوتات مومنت مصدّرة: أرقام العنوان
#  طابقت و96-99% من نقط الكونتور جوّه نطاقها)، بيصمّم أساس + كابلات مضافة
#  لكذا نسبة موازنة، بيرسم كل مرشح ويحلله ويقرا الفحص المقطعي من رام،
#  بيختار (أو بيسألك)، وبعدين حلقة الـ EFM بـ section_only.
#
#  اتطوّر كأداة منفصلة (pt_moment_design.py) واتأكد على 0000_EFM_final-4:
#    · الركيزة من إشارة المومنت لوحدها وهمية في ربع الحالات (مومنتها -11
#      مقابل -61 عند الحقيقية) - فبتتقبل بس قرب عمود/حيطة/دروب أو لو
#      مومنتها السالب نص M0 البحر على الأقل.
#    · معادلة P·الغطسة/M0 لكل متر طلعت ضعف المقاس (البلاطة بتشتغل في
#      الاتجاهين)، فالحساب بيكبّر نسبة الموازنة **المقاسة** من طبقة Balance.
#    · أساس بعدد استرندات + كابلات مضافة في البحور المحتاجة بس (طلب
#      المهندس)؛ الأساس لكل كابل بيتختار لأقل استرند·متر.

MD_CHOICES = {"automatic - fewest strand-metres": "auto",
              "pause and let me choose": "ask"}
MD_BASES = {"best base for each tendon": "best",
            "minimum strands everywhere": "min"}


class MdParams:
    """نفس الإعدادات مع قيم متغيّرة - من غير ما نلمس الأصل."""

    def __init__(self, base, **over):
        self._base = base
        self._over = over

    def __getattr__(self, k):
        if k in self._over:
            return self._over[k]
        return getattr(self._base, k)


def md_dist(a, b):
    return math.hypot(b[0] - a[0], b[1] - a[1])


def md_cumulative(pts):
    cum = [0.0]
    for a, b in zip(pts, pts[1:]):
        cum.append(cum[-1] + md_dist(a, b))
    return cum


def md_polyline_at(pts, cum, s):
    """النقطة واتجاه المماس على مسافة s على طول البوليلاين."""
    if s <= 0:
        i = 0
    elif s >= cum[-1]:
        i = len(pts) - 2
    else:
        i = max(0, min(len(pts) - 2,
                       next(k for k in range(len(cum) - 1) if cum[k + 1] >= s)))
    a, b = pts[i], pts[i + 1]
    seg = (cum[i + 1] - cum[i]) or 1e-9
    t = max(0.0, min(1.0, (s - cum[i]) / seg))
    ux, uy = (b[0] - a[0]) / seg, (b[1] - a[1]) / seg
    return (a[0] + t * (b[0] - a[0]), a[1] + t * (b[1] - a[1])), (ux, uy)


def md_depth_at(profile, cum, s):
    """عمق البروفايل (مم من فوق) على مسافة s - خطي بين النقط."""
    d = [float(q.get("depth") or 0.0) for q in profile]
    if s <= 0:
        return d[0]
    if s >= cum[-1]:
        return d[-1]
    for k in range(len(cum) - 1):
        if cum[k + 1] >= s:
            seg = (cum[k + 1] - cum[k]) or 1e-9
            return d[k] + (d[k + 1] - d[k]) * (s - cum[k]) / seg
    return d[-1]


def md_side_distance(p, u, pts):
    """أقرب مسافة عمودية لبوليلاين، وجنبها (+1 شمال المماس u، -1 يمينه)."""
    best = None
    for a, b in zip(pts, pts[1:]):
        dx, dy = b[0] - a[0], b[1] - a[1]
        L2 = dx * dx + dy * dy
        if L2 < 1e-12:
            continue
        t = ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / L2
        if t < -0.02 or t > 1.02:
            continue
        t = max(0.0, min(1.0, t))
        q = (a[0] + t * dx, a[1] + t * dy)
        d = md_dist(p, q)
        if best is None or d < best[0]:
            side = 1 if (u[0] * (q[1] - p[1]) - u[1] * (q[0] - p[0])) > 0 else -1
            best = (d, side)
    return best


def md_seg_dist(p, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    L2 = dx * dx + dy * dy
    t = 0.0 if L2 < 1e-12 else max(0.0, min(1.0, ((p[0] - a[0]) * dx
                                                   + (p[1] - a[1]) * dy) / L2))
    return math.hypot(p[0] - (a[0] + t * dx), p[1] - (a[1] + t * dy))


def md_point_in_poly(p, poly):
    x, y = p
    inside = False
    n = len(poly)
    for i in range(n):
        x1, y1 = poly[i]
        x2, y2 = poly[(i + 1) % n]
        if (y1 > y) != (y2 > y):
            xi = x1 + (y - y1) * (x2 - x1) / ((y2 - y1) or 1e-12)
            if xi > x:
                inside = not inside
    return inside


def md_support_near(p, site):
    """أقرب ركيزة حقيقية: (المسافة بالمتر، النوع)."""
    best = (1e9, "none")
    for c in (site or {}).get("columns") or []:
        d = md_dist(p, c["center"])
        if d < best[0]:
            best = (d, "column")
    for w in (site or {}).get("walls") or []:
        d = md_seg_dist(p, w["p1"], w["p2"])
        if d < best[0]:
            best = (d, "wall")
    for poly in (site or {}).get("drops") or []:
        if len(poly) >= 3 and md_point_in_poly(p, poly):
            return (0.0, "drop")
    return best


def md_parallel(t, o):
    a = (t["profile"][-1]["pos"][0] - t["profile"][0]["pos"][0],
         t["profile"][-1]["pos"][1] - t["profile"][0]["pos"][1])
    b = (o["profile"][-1]["pos"][0] - o["profile"][0]["pos"][0],
         o["profile"][-1]["pos"][1] - o["profile"][0]["pos"][1])
    na, nb = math.hypot(*a) or 1.0, math.hypot(*b) or 1.0
    return abs((a[0] * b[0] + a[1] * b[1]) / (na * nb)) >= 0.7071


def md_parse_betas(text):
    out = []
    for q in re.split(r"[,;\s]+", str(text or "")):
        try:
            v = float(q)
        except ValueError:
            continue
        if 0.05 <= v <= 2.0:
            out.append(round(v, 2))
    return sorted(set(out)) or [0.3, 0.4, 0.5]


class MdMomentReader:
    """
    مومنت البلاطة عند نقطة، لكل طبقة حمل لوحدها.

    النقطة الجديدة بتاخد ~140 ملي ثانية بطبقتين (رام بيدوّر على العنصر)،
    فالإحداثي بيتقرّب لشبكة 0.25 م ويتخزّن - الكابلات المتجاورة بتشارك.
    """

    GRID = 0.25

    def __init__(self, session, job):
        model = session.model
        self.el = model.cad_manager.element_layer
        layers = {str(L.name or "").strip(): L.uid
                  for L in list(model.cad_manager.all_layers)}
        self.uid_dead = layers.get("All Dead LC")
        self.uid_sd = next((u for n, u in layers.items()
                            if n.startswith("Self-Dead")), None)
        self.uid_od = next((u for n, u in layers.items()
                            if n.startswith("Other Dead")), None)
        self.uid_bal = next((u for n, u in layers.items()
                             if n.startswith("Balance")), None)
        if not self.uid_bal or not (self.uid_dead or
                                    (self.uid_sd and self.uid_od)):
            raise RuntimeError("the model has no Balance Loading layer, or no "
                               "dead-load layers to read the moments from")
        self.cache = {}
        self.calls = 0
        self.points = 0
        self.t = 0.0

    def _one(self, x, y, uid, axis):
        self.calls += 1
        try:
            r = self.el._command(
                f"[GET_SLAB_ANALYSIS_USER][[{x:.3f}][{y:.3f}]][{uid}]"
                f"[ContextStandard][SlabMoment][ContextMidDepth][{axis}]"
                f"[Smoothed][0]")
            v = float(r)
            return v if math.isfinite(v) else None
        except Exception:
            return None

    def at(self, x, y, axis):
        """{dead, bal} بالكيلونيوتن·م/م - موجب = شد سفلي."""
        gx, gy = round(x / self.GRID), round(y / self.GRID)
        key = (gx, gy, axis)
        if key in self.cache:
            return self.cache[key]
        qx, qy = gx * self.GRID, gy * self.GRID
        t0 = time.time()
        self.points += 1
        if self.uid_dead:
            dead = self._one(qx, qy, self.uid_dead, axis)
        else:
            a = self._one(qx, qy, self.uid_sd, axis)
            b = self._one(qx, qy, self.uid_od, axis)
            dead = None if a is None or b is None else a + b
        out = {"dead": dead, "bal": self._one(qx, qy, self.uid_bal, axis)}
        self.t += time.time() - t0
        self.cache[key] = out
        return out


def md_stations(t, cum, step):
    """كل `step` في نص البحر، وكل نص متر لمسافة 1.5 م حوالين القمم والأطراف."""
    L = cum[-1]
    ss = {round(k * step, 3) for k in range(int(L / step) + 1)}
    ss |= {round(c, 3) for c in cum}
    ss.add(round(L, 3))
    for k, q in enumerate(t["profile"]):
        if q.get("high") or k in (0, len(t["profile"]) - 1):
            for d in (-1.5, -1.0, -0.5, 0.5, 1.0, 1.5):
                s = cum[k] + d
                if 0.0 <= s <= L:
                    ss.add(round(s, 3))
    return sorted(ss)


def md_read_profiles(session, tendons, job, step=1.5):
    """منحنيات المومنت الميت ومومنت Balance على مسار كل كابل."""
    mr = MdMomentReader(session, job)
    profiles = []
    t0 = time.time()
    n = len(tendons)
    for ti, t in enumerate(tendons):
        job.check()
        pts = [q["pos"] for q in t["profile"]]
        cum = md_cumulative(pts)
        if cum[-1] < 1.0 or len(pts) < 2:
            continue
        axis = "ContextYAxis" if t["dir"] == "X" else "ContextXAxis"
        samples = []
        for s in md_stations(t, cum, step):
            xy, _u = md_polyline_at(pts, cum, s)
            samples.append((s, xy, mr.at(xy[0], xy[1], axis)))
        profiles.append({"tendon": ti, "dir": t["dir"],
                         "strands": t.get("strands"),
                         "added": bool(t.get("added")),
                         "s": [q[0] for q in samples],
                         "xy": [q[1] for q in samples],
                         "dead_raw": [q[2]["dead"] for q in samples],
                         "bal_raw": [q[2]["bal"] for q in samples]})
        job.step(0.12 + 0.30 * (ti + 1) / max(n, 1),
                 f"Reading the moments: tendon {ti + 1} of {n}")
        if (ti + 1) % 20 == 0 or ti + 1 == n:
            job.info(f"    tendon {ti + 1}/{n} · {mr.points:,} points read · "
                     f"{1000.0 * mr.t / max(mr.points, 1):.0f} ms a point · "
                     f"{(time.time() - t0) / 60.0:.1f} min")
    return profiles


def md_smooth(vals):
    """متوسط تلات نقط، مع ملء الفاضي خطياً."""
    n = len(vals)
    v = list(vals)
    idx = [i for i in range(n) if v[i] is not None]
    if not idx:
        return v
    for i in range(n):
        if v[i] is None:
            lo = max((k for k in idx if k < i), default=None)
            hi = min((k for k in idx if k > i), default=None)
            if lo is None:
                v[i] = v[hi]
            elif hi is None:
                v[i] = v[lo]
            else:
                v[i] = v[lo] + (v[hi] - v[lo]) * (i - lo) / (hi - lo)
    return [(v[max(i - 1, 0)] + v[i] + v[min(i + 1, n - 1)]) / 3.0
            for i in range(n)]


def md_find_spans(s, m, min_len=1.0, min_sag=2.0):
    """البحور من إشارة المومنت: [(i1, i_low, i2, end1, end2)]."""
    n = len(s)
    sign = [1 if m[i] > 0 else -1 for i in range(n)]

    def regions():
        out, i = [], 0
        while i < n:
            j = i
            while j + 1 < n and sign[j + 1] == sign[i]:
                j += 1
            out.append([sign[i], i, j])
            i = j + 1
        return out

    for sg, i, j in regions():
        if sg > 0 and ((s[j] - s[i]) < min_len or max(m[i:j + 1]) < min_sag):
            for k in range(i, j + 1):
                sign[k] = -1
    reg = regions()
    spans = []
    for r, (sg, i, j) in enumerate(reg):
        if sg < 0:
            continue
        i_low = max(range(i, j + 1), key=lambda k: m[k])
        if r > 0:
            pi, pj = reg[r - 1][1], reg[r - 1][2]
            i1, e1 = min(range(pi, pj + 1), key=lambda k: m[k]), "support"
        else:
            i1, e1 = 0, "end"
        if r + 1 < len(reg):
            ni, nj = reg[r + 1][1], reg[r + 1][2]
            i2, e2 = min(range(ni, nj + 1), key=lambda k: m[k]), "support"
        else:
            i2, e2 = n - 1, "end"
        spans.append((i1, i_low, i2, e1, e2))
    return spans


def md_chord_at(v, i1, i2, t):
    return v[i1] + (v[i2] - v[i1]) * t


def md_merged_spans(s, md, xy, site, min_ratio=0.5, near_m=1.5):
    """البحور بعد شيل الركايز الوهمية."""
    spans = [dict(i1=a, il=b, i2=c, e1=d, e2=e)
             for a, b, c, d, e in md_find_spans(s, md)]

    def m0(sp):
        L = max(s[sp["i2"]] - s[sp["i1"]], 1e-9)
        return md[sp["il"]] - md_chord_at(md, sp["i1"], sp["i2"],
                                          (s[sp["il"]] - s[sp["i1"]]) / L)

    merged = 0
    changed = True
    while changed:
        changed = False
        for k in range(len(spans) - 1):
            A, B = spans[k], spans[k + 1]
            if A["e2"] != "support":
                continue
            ih = A["i2"]
            if md_support_near(xy[ih], site)[0] <= near_m:
                continue
            if abs(md[ih]) >= min_ratio * max(m0(A), m0(B), 1.0):
                continue
            il = max(range(A["i1"], B["i2"] + 1), key=lambda i: md[i])
            spans[k:k + 2] = [dict(i1=A["i1"], il=il, i2=B["i2"],
                                   e1=A["e1"], e2=B["e2"])]
            merged += 1
            changed = True
            break
    return spans, merged


def md_median(v):
    v = sorted(x for x in v if x is not None)
    return v[len(v) // 2] if v else None


def md_span_rows(profiles, tendons, site, params, anchor, betas,
                 min_ratio=0.5, near=1.5):
    """سطر لكل بحر من كل كابل أصلي، والاسترندات المطلوبة عند كل β."""
    h = float(params.slab_thickness)
    spacing = float(getattr(params, "spacing", 1.5) or 1.5)
    window = 1.5 * spacing
    routes = []
    for ti, t in enumerate(tendons):
        pts = [q["pos"] for q in t["profile"]]
        routes.append({"ti": ti, "dir": t["dir"], "pts": pts,
                       "cum": md_cumulative(pts),
                       "n": int(t.get("strands") or 0),
                       "added": bool(t.get("added"))})
    rows = []
    merged_total = 0
    for pr in profiles:
        ti = pr["tendon"]
        if ti >= len(tendons):
            continue
        t = tendons[ti]
        if t.get("added"):
            continue
        s = pr["s"]
        xy = [tuple(q) for q in pr["xy"]]
        mdd = md_smooth(pr.get("dead_raw") or pr.get("dead") or [])
        mbb = md_smooth(pr.get("bal_raw") or pr.get("bal") or [])
        if not mdd or any(v is None for v in mdd) or any(v is None for v in mbb):
            continue
        pts, cum = routes[ti]["pts"], routes[ti]["cum"]
        spans, merged = md_merged_spans(s, mdd, xy, site, min_ratio, near)
        merged_total += merged
        top_cgs, bot_cgs = params.covers_for(t["dir"])
        d_hi, d_lo = float(top_cgs), h - float(bot_cgs)
        cur_low = [cum[k] for k, q in enumerate(t["profile"]) if q.get("sag")]
        same_dir = [r for r in routes if r["dir"] == t["dir"]]
        for k, sp in enumerate(spans):
            i1, il, i2 = sp["i1"], sp["il"], sp["i2"]
            s1, sl, s2 = s[i1], s[il], s[i2]
            if s2 - s1 < 1.0:
                continue
            tt = (sl - s1) / (s2 - s1)
            M0 = mdd[il] - md_chord_at(mdd, i1, i2, tt)
            B0 = md_chord_at(mbb, i1, i2, tt) - mbb[il]
            e1d = d_hi if sp["e1"] == "support" else anchor
            e2d = d_hi if sp["e2"] == "support" else anchor
            a_ideal = (d_lo - (e1d + (e2d - e1d) * tt)) / 1000.0
            lows_in = [c for c in cur_low if s1 < c < s2]
            if lows_in:
                s_now = max(lows_in,
                            key=lambda c: md_depth_at(t["profile"], cum, c))
            else:
                s_now = max((c for c in cum if s1 <= c <= s2),
                            key=lambda c: md_depth_at(t["profile"], cum, c),
                            default=sl)
            tn = (s_now - s1) / (s2 - s1)
            dn1 = md_depth_at(t["profile"], cum, s1)
            dn2 = md_depth_at(t["profile"], cum, s2)
            a_now = (md_depth_at(t["profile"], cum, s_now)
                     - (dn1 + (dn2 - dn1) * tn)) / 1000.0
            p_low, u = md_polyline_at(pts, cum, sl)
            p1, _ = md_polyline_at(pts, cum, s1)
            p2, _ = md_polyline_at(pts, cum, s2)
            now_n = 0
            left = right = None
            for r in same_dir:
                dd = md_side_distance(p_low, u, r["pts"])
                if dd is None:
                    continue
                if dd[0] <= window:
                    now_n += r["n"]
                if r["ti"] != ti and not r["added"] and dd[0] >= 0.05:
                    if dd[1] > 0 and (left is None or dd[0] < left):
                        left = dd[0]
                    if dd[1] < 0 and (right is None or dd[0] < right):
                        right = dd[0]
            gaps = [g for g in (left, right) if g is not None]
            trib = ((left + right) / 2.0 if len(gaps) == 2
                    else (gaps[0] if gaps else spacing))
            rows.append({
                "tendon": ti, "dir": t["dir"], "span": k, "L": s2 - s1,
                "s1": s1, "s2": s2, "end1": sp["e1"], "end2": sp["e2"],
                "x1": p1[0], "y1": p1[1], "x2": p2[0], "y2": p2[1],
                "support1_m": md_support_near(p1, site)[0],
                "support2_m": md_support_near(p2, site)[0],
                "s_low_ideal": sl, "x_low": p_low[0], "y_low": p_low[1],
                "s_low_now": s_now, "low_shift": sl - s_now,
                "M0": M0, "B0": B0, "beta_now": (B0 / M0) if M0 > 1.0 else None,
                "a_ideal_mm": a_ideal * 1000.0, "a_now_mm": a_now * 1000.0,
                "spm_now": now_n / (2.0 * window), "trib_m": trib,
                "gap_plus": left, "gap_minus": right,
                "strands_now": int(t.get("strands") or 0)})
    for d in ("X", "Y"):
        ok = [r["beta_now"] for r in rows if r["dir"] == d and r["M0"] >= 10.0
              and r["beta_now"] is not None and 0.15 <= r["beta_now"] <= 2.0]
        med = md_median(ok) or 0.6
        for r in rows:
            if r["dir"] != d:
                continue
            good = (r["M0"] >= 10.0 and r["beta_now"] is not None
                    and 0.15 <= r["beta_now"] <= 2.0)
            r["beta_used"] = r["beta_now"] if good else med
            r["beta_fallback"] = not good
            a_now_eff = (r["a_now_mm"] if r["a_now_mm"] >= 20.0
                         else r["a_ideal_mm"])
            for b in betas:
                key = f"nreq_{b:.2f}"
                if r["M0"] < 1.0 or r["a_ideal_mm"] < 5.0 or r["spm_now"] <= 0:
                    r[key] = 0.0
                    continue
                spm_req = (r["spm_now"] * (b / r["beta_used"])
                           * (a_now_eff / r["a_ideal_mm"]))
                r[key] = spm_req * r["trib_m"]
    return rows, merged_total


def md_plan_tendon(rows, L, nb, params, key, min_need=0.5):
    """لكابل واحد بأساس nb: الكابلات المضافة وتكلفتها بالاسترند·متر."""
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    cap = max(int(getattr(params, "max_strands", 5) or 5), n_min)
    ext = float(getattr(params, "efm_added_extend", 2.0) or 2.0)
    need = [r for r in sorted(rows, key=lambda z: z["s1"])
            if r[key] - nb >= min_need]
    runs = []
    for r in need:
        if runs and r["s1"] - runs[-1][-1]["s2"] <= 2.0 * ext:
            runs[-1].append(r)
        else:
            runs.append([r])
    specs, cost, short_sm = [], nb * L, 0.0
    for run in runs:
        extra = max(r[key] - nb for r in run)
        lo, hi = max(0.0, run[0]["s1"] - ext), min(L, run[-1]["s2"] + ext)
        if hi - lo < 6.0 and L >= 6.0:
            grow = (6.0 - (hi - lo)) / 2.0
            lo, hi = max(0.0, lo - grow), min(L, hi + grow)
            if hi - lo < 6.0:
                lo, hi = (0.0, 6.0) if lo <= 0.0 else (L - 6.0, L)
        n_add = max(n_min, min(cap, math.ceil(extra - 1e-9)))
        short_sm += sum(max(0.0, r[key] - nb - n_add) * r["L"] for r in run)
        specs.append({"lo": lo, "hi": hi, "strands": n_add, "runs": run,
                      "extra": extra})
        cost += n_add * (hi - lo)
    return specs, cost, short_sm


def md_design(rows, tendons, site, params, beta, mode="best", job=None,
              move_lows=True, min_need=0.5):
    """
    الأساس + الإضافة لنسبة موازنة واحدة. بترجّع (الكابلات، تقرير).

    الكابل المضاف في نص الفراغ على نفس الجنب دايماً، فكل فراغ فيه كابل
    مضاف واحد بالكتير. البناء بـ build_added_tendon (الامتداد، الالتصاق
    للحرف، أقل طول 6 م)، والنقط الواطية بـ lows_to_peak_stress على قمم
    المومنت - قبل بناء المضاف عشان ينسخها بعد ما اتحركت.
    """
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    cap = max(int(getattr(params, "max_strands", 5) or 5), n_min)
    ext = float(getattr(params, "efm_added_extend", 2.0) or 2.0)
    min_gap = float(getattr(params, "efm_added_min_gap", 0.40) or 0.40)
    key = f"nreq_{beta:.2f}"
    loose = MdParams(params, efm_added_min_gap=0.0, efm_added_clear=0.0)

    work, by_ti = [], {}
    for ti, t in enumerate(tendons):
        if t.get("added"):
            continue
        c = {k: v for k, v in t.items() if k != "profile"}
        c["profile"] = [dict(q) for q in t["profile"]]
        c["strands"] = n_min
        c["_ti"] = ti
        work.append(c)
        by_ti[ti] = c
    rows_by_t = {}
    for r in rows:
        rows_by_t.setdefault(r["tendon"], []).append(r)

    specs_all, short_sm = [], 0.0
    for ti, lst in rows_by_t.items():
        donor = by_ti.get(ti)
        if donor is None:
            continue
        L = md_cumulative([q["pos"] for q in donor["profile"]])[-1]
        choices = range(n_min, cap + 1) if mode == "best" else (n_min,)
        if donor.get("col_band") and int(getattr(params, "column_band_strands", 0) or 0) > 0:
            #  17.75/17.77: عدد ثابت لكابل الحزمة لو المهندس حدّده؛ 0 = التصميم
            #  بيقيسه من عزومه على نصيبه من الشريط.
            want = min(int(params.column_band_strands), cap)
            choices = (want,)
        best = None
        for nb in choices:
            specs, cost, short = md_plan_tendon(lst, L, nb, params, key,
                                                min_need)
            score = cost + 10.0 * short
            if best is None or score < best[0] - 1e-6:
                best = (score, nb, specs, short)
        _score, nb, specs, short = best
        donor["strands"] = nb
        short_sm += short
        for sp in specs:
            sp["donor"] = donor
            specs_all.append(sp)

    lows = {"lows_moved": 0, "lows_blocked": 0}
    if move_lows:
        import types
        demand = [(r["x_low"], r["y_low"], 1.0) for r in rows
                  if r["M0"] >= 10.0 and abs(r["low_shift"]) > 0.3]
        peaks = types.SimpleNamespace(limit=1.0, demand=demand)
        origs = [t for t in work if not t.get("added")]
        mv, bl = lows_to_peak_stress(
            origs, peaks, None, params, job,
            max_frac=float(getattr(params, "low_move_frac", 0.25) or 0.25),
            reach=1.5)
        lows = {"lows_moved": mv, "lows_blocked": bl}

    added, unbuilt_sm, merged_into = [], 0.0, 0
    for sp in sorted(specs_all, key=lambda z: -z["strands"]):
        donor = sp["donor"]
        run = sp["runs"]
        total = md_cumulative([q["pos"] for q in donor["profile"]])[-1]
        plan = {"donor": donor, "lo": sp["lo"], "hi": sp["hi"],
                "total": total, "ext": ext,
                "runs": [[{"name": f"t{donor['_ti']}-s{r['span']}",
                           "a": (r["x1"], r["y1"]), "b": (r["x2"], r["y2"]),
                           "mid": (r["x_low"], r["y_low"])} for r in run]]}
        new = build_added_tendon(plan, work, loose, site)
        need_sm = sum(min(sp["strands"], max(0.0, r[key] - donor["strands"]))
                      * r["L"] for r in run)
        if new is None or not new.get("_normal") or not new.get("_base"):
            unbuilt_sm += need_sm
            continue
        plus = [r["gap_plus"] for r in run if r["gap_plus"]]
        minus = [r["gap_minus"] for r in run if r["gap_minus"]]
        if plus:
            off = min(plus) / 2.0
        elif minus:
            off = -min(minus) / 2.0
        else:
            off = float(getattr(params, "spacing", 1.5) or 1.5) / 2.0
        nx, ny = new["_normal"]
        for q, b in zip(new["profile"], new["_base"]):
            q["pos"] = (b[0] + nx * off, b[1] + ny * off)
        new["offset"] = off
        new["strands"] = sp["strands"]
        new["_need"] = sp["extra"]
        new["_md_group"] = {"strands": int(sp["strands"]), "beta": float(beta),
                            "label": f"t{donor['_ti']}",
                            "spans": [((r["x1"], r["y1"]), (r["x2"], r["y2"]))
                                      for r in run]}
        worst, worst_t = 1e9, None
        for o in work:
            if o is new or o.get("_deleted") or not md_parallel(new, o):
                continue
            for q in new["profile"][1:-1]:
                for r in o["profile"]:
                    d = md_dist(q["pos"], r["pos"])
                    if d < worst:
                        worst, worst_t = d, o
        if worst < min_gap:
            if (worst_t is not None and worst_t.get("added")
                    and int(worst_t["strands"]) + sp["strands"] <= cap):
                worst_t["strands"] = int(worst_t["strands"]) + sp["strands"]
                merged_into += 1
            else:
                unbuilt_sm += need_sm
            continue
        work.append(new)
        added.append(new)

    alive = [t for t in work if not t.get("_deleted")]
    length = lambda t: md_cumulative([q["pos"] for q in t["profile"]])[-1]
    rep = {"beta": beta, "mode": mode, "tendons": len(alive),
           "added_tendons": sum(1 for t in alive if t.get("added")),
           "strands": sum(int(t["strands"]) for t in alive),
           "strand_m": sum(int(t["strands"]) * length(t) for t in alive),
           "unplaced_strand_m": short_sm + unbuilt_sm,
           "merged_into_added": merged_into}
    rep.update(lows)
    return alive, rep


def md_summary(label, tendons, plots, params):
    """عدد الكابلات والاسترندات، والقطاعات فوق الحد: قابلة للعلاج وخارج متناول الشد."""
    live = [t for t in tendons if not t.get("_deleted")]
    length = lambda t: md_cumulative([q["pos"] for q in t["profile"]])[-1]
    per, reach, unreach, where = {}, 0, 0, []
    for pl in plots or []:
        r, hop = section_fail_counts(pl, params, live)
        per[plot_tag(pl)] = (len(r), len(hop))
        reach += len(r)
        unreach += len(hop)
        where += [(plot_tag(pl), float(d["x"]), float(d["y"]), float(d["over"]))
                  for d in hop]
    return {"label": label, "tendons": len(live),
            "added": sum(1 for t in live if t.get("added")),
            "strands": sum(int(t.get("strands") or 0) for t in live),
            "strand_m": sum(int(t.get("strands") or 0) * length(t)
                            for t in live),
            "reach": reach, "unreach": unreach, "per": per,
            "unreach_where": where}


def direction_section_area(site, params, direction):
    """
    مساحة المقطع المقاوم لاتجاه معيّن (م²) - نفس تعريف
    `SiteModel._direction_area` بالحرف، بس من الـ site مباشرة عشان
    الحاجات اللي مش جوّه محرّك.

    **دي مساحة القطاع، مش مساحة المسقط.** الـ P/A = القوة ÷ (عرض
    البلاطة المتوسط × السُمك). القسمة على مساحة المسقط بتدّي رقم أصغر
    بمقدار السُمك ÷ طول البلاطة - على سقف 20 م بسُمك 250 مم يبقى 80
    مرة أصغر، ويعدّي في التقرير كأنه P/A.
    """
    site = site or {}
    pts = []
    for poly in (site.get("pieces") or []):
        pts += list(poly or [])
    if not pts:
        pts = list(site.get("boundary") or [])
    area = slab_area_m2(site)
    if not pts or not area:
        return None
    xs = [q[0] for q in pts]
    ys = [q[1] for q in pts]
    span = max((max(xs) - min(xs)) if direction == "X"
               else (max(ys) - min(ys)), 1e-6)
    avg_width = area / span
    return max(avg_width, 1e-6) * float(params.slab_thickness) / 1000.0


def design_scorecard(tendons, plots, params, site=None, job=None,
                     reach=None):
    """
    **18.27: صف واحد بيقول التصميم ده كويس قد إيه، مش بس سليم ولا لأ.**

    كل رقم في اللوج لحد دلوقتي بيجاوب على "آمن؟": القطاعات الراسبة،
    الـ P/A، التدقيق. ولا واحد بيجاوب على "بأقل حديد؟". سقفين مافيهمش
    ولا قطاع راسب، واحد فيهم بـ 5.1 والتاني بـ 9.1 كجم/م² - كل سطر في
    اللوج بتاعهم بيقرا زي بعضه.

    الأرقام اللي بتفرق:
      · استرند·متر/م²  - الوحدة اللي بنك الخبرة متعاير بيها، فعندك هدف
      · الاستغلال      - الأدنى والوسيط والأقصى؛ الأدنى هو الحديد الضايع
      · الفايض والناقص - نفس الأرقام مترجمة استرندات

    بترجّع dict. مابتحكمش على حاجة - `design_gates` هي اللي بتحكم.
    """
    live = [t for t in tendons if not t.get("_deleted")]
    area = slab_area_m2(site) if site else None
    strand_m = sum(int(t.get("strands") or 0) * tendon_plan_length(t)
                   for t in live)
    kg = floor_strand_kg(live, params)
    n, lo, med, hi, over = utilisation_stats(plots or [])
    head = tendon_headroom(live, plots or [], params, reach) if plots else {}
    #  نفس تقسيمة باقي اللوج: اللي الشد يقدر يقفله، واللي بره متناوله.
    #  من غيرها الكارت بيقول 8 والسطر اللي فوقه بيقول 4 على نفس السقف.
    can = cannot = 0
    for pl in (plots or []):
        try:
            r, hop = section_fail_counts(pl, params, live)
        except Exception:
            continue
        can += len(r)
        cannot += len(hop)
    target = None
    try:
        target = (getattr(params, "_experience", None) or {}).get(
            "strand_m_per_m2")
    except Exception:
        target = None

    #  القسمة على مساحة **القطاع**، مش على مساحة المسقط
    pa = {}
    for d in ("X", "Y"):
        sec = direction_section_area(site, params, d) if site else None
        pa[d] = _pa_from_tendons(live, params, d, sec) if sec else None

    card = {
        "tendons": len(live),
        "strands": sum(int(t.get("strands") or 0) for t in live),
        "strand_m": strand_m,
        "kg": kg,
        "area_m2": area,
        "strand_m_per_m2": (strand_m / area) if area else None,
        "kg_per_m2": (kg / area) if area else None,
        "target_strand_m_per_m2": target,
        "readings": n, "u_low": lo, "u_med": med, "u_high": hi,
        "sections_over": over,
        "over_reachable": can, "over_out_of_reach": cannot,
        "loose_tendons": sum(1 for h in head.values() if h["spare"] > 0),
        "short_strands": section_shortfall(plots or [], params, reach)[2],
        "idle_tendons": sum(1 for h in head.values() if h["u"] < 0.60),
        "pa": pa,
    }

    if job:
        job.log("Scorecard", "head")
        job.info(f"    {card['tendons']} tendons · {card['strands']} strands · "
                 f"{strand_m:,.0f} strand-m · {kg:,.0f} kg")
        if area:
            line = (f"    {card['strand_m_per_m2']:.2f} strand-m/m² · "
                    f"{card['kg_per_m2']:.2f} kg/m² over {area:,.0f} m²")
            if target:
                d = card["strand_m_per_m2"] - target
                line += (f" · the bank's floors use {target:.2f}, so this one "
                         f"is {abs(d) / target * 100:.0f}% "
                         + ("above" if d > 0 else "below") + " them")
            job.info(line)
        if n:
            job.info(f"    utilisation {lo:.2f} / {med:.2f} / {hi:.2f} "
                     f"(lowest, median, highest)"
                     + (f" · {over} reading(s) over 1.00" if over
                        else " · nothing over 1.00"))
            job.info(f"    {card['loose_tendons']} tendon(s) have a size to "
                     f"spare · about {card['short_strands']} strand(s) short "
                     f"across {can} place(s) prestress can reach"
                     + (f" ({cannot} more are past what prestress can do)"
                        if cannot else "")
                     + f" · {card['idle_tendons']} tendon(s) never pass a "
                       f"section working harder than 0.60")
        else:
            job.info("    no section check was read, so nothing can be said "
                     "about how hard the sections are working - the strand "
                     "figures above are the whole picture.")
    return card


def design_gates(card, tendons, params, job=None):
    """
    **الشروط اللي التصميم مايعدّيش من غيرها.**

    تقليل الحديد بيتوقف عند حدود، والحدود دي شروط مش أهداف: التصميم
    اللي بيكسر واحد فيها مرفوض مهما كان خفيف.

    اللي البرنامج يقدر يحكم عليه دلوقتي:
      · مافيش قطاع فوق حدّه في فحص رام
      · أقل ضغط مسبق في الكود (ACI 8.6.2.1 = 0.86 MPa) في الاتجاهين
      · أقصى تباعد بين الكابلات (8h أو 1.5 م)

    **واللي مايقدرش** - وبيتقال بصوت عالي بدل ما يتفهم إنه عدّى:
      · الترخيم طويل المدى
      · القص الثاقب حوالين الأعمدة
      · الحد الأدنى للحديد الملصوق

    بترجّع (اللي عدّى, [(اسم, عدّى؟, السطر)]).
    """
    rows = []
    can = card.get("over_reachable") or 0
    cannot = card.get("over_out_of_reach") or 0
    if card.get("readings"):
        #  الحكم على اللي الشد يقدر يقفله. اللي بره متناوله بيتقال في
        #  نفس السطر ومابيرسّبش التصميم: مافيش كابل بيقفله، فالبوابة
        #  اللي بتقف عليه بتقف للأبد وبتخبّي اللي ينفع يتعمل.
        why = ("nothing over its limit that prestress can reach" if not can
               else f"{can} reading(s) over the limit that prestress can "
                    f"reach - the design is not finished, whatever it weighs")
        if cannot:
            why += (f", and {cannot} more are past what prestress can do at "
                    f"all - those need concrete or rebar, not strands")
        rows.append(("sections over the limit", not can, why))
    pa_min = float(getattr(params, "pa_min", 0.86) or 0.0)
    for d in ("X", "Y"):
        v = (card.get("pa") or {}).get(d)
        if v is None or not any(t.get("dir") == d and not t.get("_deleted")
                                for t in tendons):
            continue
        rows.append((f"minimum precompression, {d}", v >= pa_min - 1e-9,
                     f"P/A {v:.2f} MPa against the code minimum "
                     f"{pa_min:.2f}"))
    try:
        max_sp = float(params.max_tendon_spacing)
    except Exception:
        max_sp = None
    if max_sp:
        worst = 0.0
        for d in ("X", "Y"):
            cs = sorted({round(float(t["coord"]), 4) for t in tendons
                         if not t.get("_deleted") and t.get("dir") == d
                         and t.get("coord") is not None})
            for a, b in zip(cs, cs[1:]):
                worst = max(worst, b - a)
        if worst > 0:
            rows.append(("tendon spacing", worst <= max_sp + 1e-6,
                         f"widest gap between neighbouring tendons "
                         f"{worst:.2f} m against the {max_sp:.2f} m limit"))

    passed = all(ok for _n, ok, _w in rows)
    if job:
        for name, ok, why in rows:
            (job.ok if ok else job.error)(f"    [{'pass' if ok else 'FAIL'}] "
                                          f"{name}: {why}")
        job.warn("    [not checked] long-term deflection, punching shear "
                 "around the columns, and the code minimum of bonded "
                 "reinforcement. This program does not compute them, and a "
                 "layout this light has to be checked for all three before "
                 "it is built.")
    return passed, rows


def md_choose_auto(cands, baseline, budget=None):
    """
    أقل استرند·متر، بشرط القطاعات القابلة للعلاج فوق الحد ماتزيدش عن
    الموديل زي ما هو. لو مافيش مرشح بيحقق ده: الأقل قطاعات، ثم الأقل
    استرند·متر.

    17.8: لو فيه حد كجم/م² (`budget`)، الاختيار من المرشحين اللي جوّه الحد
    بس؛ ولو ولا واحد جوّه، الأخف.
    """
    if not cands:
        return None
    idx = list(range(len(cands)))
    if budget:
        within = [i for i in idx if cands[i].get("kg_m2") is not None
                  and cands[i]["kg_m2"] <= float(budget) + 1e-9]
        if not within:
            return min(idx, key=lambda i: (cands[i].get("kg_m2") or 1e9))
        idx = within
    ok = [i for i in idx if cands[i]["reach"] <= baseline["reach"]]
    if ok:
        return min(ok, key=lambda i: cands[i]["strand_m"])
    return min(idx, key=lambda i: (cands[i]["reach"], cands[i]["strand_m"]))


def run_moment_design(session, cpt, tendons, site, params, job, out_dir, stem,
                      choose=None, mesh_size=None, profiles=None):
    """
    التصميم من خريطة المومنت على موديل مفتوح في الجلسة.

    بترجّع {"baseline", "candidates", "chosen"} - chosen فيه الكابلات
    ومسار الموديل المحفوظ، أو None لو المهندس وقف عند الاختيار.
    """
    import csv as _csv
    h = float(params.slab_thickness)
    anchor = float(getattr(params, "anchor_elevation", h / 2.0) or h / 2.0)
    betas = md_parse_betas(getattr(params, "md_candidates", "0.3, 0.4, 0.5"))
    base_mode = ("min" if str(getattr(params, "md_base", "best")) == "min"
                 else "best")
    move = bool(getattr(params, "md_move_lows", True))
    step = float(getattr(params, "md_step", 1.5) or 1.5)
    pcheck = MdParams(params, efm_face="both")
    pdraw = MdParams(params, efm_profile_mode="safe")
    _area = slab_area_m2(site)
    _budget = float(getattr(params, "budget_kg_m2", 0.0) or 0.0) or None

    job.log("The model as it is", "head")
    job.step(0.05, "Analysing the model as it is")
    res = run_model_analysis(session, job, mesh_size)
    if not res.get("ok"):
        raise RuntimeError("RAM did not finish the analysis of the model as "
                           "it is")
    baseline = md_summary("the model as it is", tendons,
                          read_section_plots_from_ram(session, pcheck, job),
                          pcheck)
    baseline["kg"] = floor_strand_kg(tendons, params)
    baseline["kg_m2"] = (baseline["kg"] / _area) if _area else None
    job.ok(f"The model as it is: {baseline['strands']} strands · "
           f"{baseline['strand_m']:,.0f} strand-m · {baseline['reach']} "
           f"section(s) over the limit that prestress can reach, "
           f"{baseline['unreach']} out of its reach.")

    if profiles is None:
        job.log("Reading the moments along every tendon", "head")
        job.info("    dead load (All Dead LC) and the Balance Loading layer, "
                 "read straight from RAM - about a tenth of a second a "
                 "point, denser near the high points. This is the RAM "
                 "moment field, not a saved plot file.")
        profiles = md_read_profiles(session, tendons, job, step)
        try:
            with open(os.path.join(out_dir, f"{stem}_moment_profiles.json"),
                      "w", encoding="utf-8") as fh:
                json.dump({"model": cpt, "tendons": profiles}, fh)
        except Exception as e:
            job.warn(f"The moment profiles could not be written: {e}")

    rows, merged = md_span_rows(profiles, tendons, site, params, anchor, betas)
    if not rows:
        raise RuntimeError("no span could be read from the moments")
    try:
        with open(os.path.join(out_dir, f"{stem}_moment_spans.csv"), "w",
                  newline="", encoding="utf-8") as fh:
            w = _csv.DictWriter(fh, fieldnames=list(rows[0].keys()))
            w.writeheader()
            for r in rows:
                w.writerow({k: (f"{v:.4f}" if isinstance(v, float) else v)
                            for k, v in r.items()})
    except Exception as e:
        job.warn(f"The span table could not be written: {e}")
    job.log("What the moments say", "head")
    job.ok(f"{len(rows)} spans on {len({r['tendon'] for r in rows})} tendons; "
           f"{merged} support(s) the moment sign alone suggested were merged "
           f"away - no column, wall or drop there, and a hogging moment under "
           f"half the span's.")
    for d in ("X", "Y"):
        rr = [r for r in rows if r["dir"] == d]
        if not rr:
            continue
        good = sorted(r["beta_now"] for r in rr if not r["beta_fallback"])
        shifts = [abs(r["low_shift"]) for r in rr if r["M0"] >= 10.0]
        job.info(f"    {d}: {len(rr)} spans · balance ratio now, measured: "
                 f"median {good[len(good) // 2] if good else 0:.2f} · drape "
                 f"ideal {md_median([r['a_ideal_mm'] for r in rr]) or 0:.0f} "
                 f"mm, now {md_median([r['a_now_mm'] for r in rr]) or 0:.0f} "
                 f"mm · {sum(1 for x in shifts if x > 1.5)} low point(s) more "
                 f"than 1.5 m from the sagging peak")

    cands = []
    for i, b in enumerate(betas):
        job.check()
        job.log(f"Candidate {i + 1} of {len(betas)}: balance ratio {b:.2f}",
                "head")
        job.step(0.45 + 0.45 * i / max(len(betas), 1),
                 f"Candidate {i + 1} of {len(betas)}")
        alive, rep = md_design(rows, tendons, site, params, b, base_mode, job,
                               move_lows=move)
        job.info(f"    {rep['tendons']} tendons ({rep['added_tendons']} added) "
                 f"· {rep['strands']} strands · {rep['strand_m']:,.0f} strand-m "
                 f"· low points moved {rep['lows_moved']}"
                 + (f" · {rep['unplaced_strand_m']:,.0f} strand-m asked for "
                    f"did not fit" if rep["unplaced_strand_m"] >= 1.0 else ""))
        for t in alive:
            if not t.get("added"):
                t["as_drawn"] = True
        enforce_min_radius([t for t in alive if not t.get("added")], pdraw, job)
        clear_tendons_in_ram(session, job)
        write_tendons_to_ram(session, alive, job, pdraw,
                             drops=(site or {}).get("drops"), site=site)
        if bool(getattr(params, "place_jacks", True)):
            try:
                write_jacks_to_ram(session, alive, job, pdraw)
            except Exception as e:
                job.warn(f"Jacks were not placed: {e}")
        r = run_model_analysis(session, job, mesh_size)
        if not r.get("ok"):
            job.warn(f"RAM did not finish the analysis of candidate {b:.2f} - "
                     f"it is left out.")
            continue
        path = os.path.join(out_dir, f"{stem}_MD_b{b:.2f}.cpt")
        k = 2
        while os.path.isfile(path):
            path = os.path.join(out_dir, f"{stem}_MD_b{b:.2f}-{k}.cpt")
            k += 1
        safe_save(session, path, job)
        s = md_summary(f"balance ratio {b:.2f}", alive,
                       read_section_plots_from_ram(session, pcheck, job),
                       pcheck)
        s.update({"beta": b, "path": path, "tendons_list": alive,
                  "report": rep})
        s["kg"] = floor_strand_kg(alive, params)
        s["kg_m2"] = (s["kg"] / _area) if _area else None
        cands.append(s)
        job.ok(f"    checked: {s['reach']} section(s) over the limit that "
               f"prestress can reach, {s['unreach']} out of its reach · saved "
               f"{os.path.basename(path)}")

    if not cands:
        raise RuntimeError("no candidate could be analysed")
    auto = md_choose_auto(cands, baseline, _budget)
    job.log("The candidates", "head")
    job.info(f"    {'':<22} {'tendons':>8} {'strands':>8} {'strand-m':>9} "
             f"{'vs now':>7} {'over':>5} {'out of reach':>13}")
    job.info(f"    {'the model as it is':<22} {baseline['tendons']:>8} "
             f"{baseline['strands']:>8} {baseline['strand_m']:>9,.0f} "
             f"{'':>7} {baseline['reach']:>5} {baseline['unreach']:>13}")
    for i, c in enumerate(cands):
        pc = 100.0 * (c["strand_m"] - baseline["strand_m"]) / max(
            baseline["strand_m"], 1.0)
        job.info(f"    {c['label'] + (' <- chosen' if i == auto else ''):<22} "
                 f"{c['tendons']:>8} {c['strands']:>8} {c['strand_m']:>9,.0f} "
                 f"{pc:>6.0f}% {c['reach']:>5} {c['unreach']:>13}")
    if _area:
        job.info("    strand on the floor: the model as it is "
                 f"{baseline['kg_m2']:.2f} kg/m2 · "
                 + " · ".join(f"{c['label']} {c['kg_m2']:.2f}" for c in cands)
                 + (f" · limit {_budget:.2f} kg/m2" if _budget else ""))
        if _budget and not any((c.get("kg_m2") or 1e9) <= _budget
                               for c in cands):
            job.warn(f"    no candidate is inside the {_budget:.2f} kg/m2 "
                     f"limit - the lightest is taken, and the loop after it "
                     f"adds nothing. Try lower balance ratios.")
    job.info("    'over' counts only sections prestress can reach; the "
             "automatic choice is the fewest strand-metres with no more of "
             "them than the model as it is.")

    choice = auto
    if str(getattr(params, "md_choice", "auto")) == "ask" and choose is not None:
        got = choose(baseline, cands, auto)
        if got is None:
            job.warn("Stopped at the choice. Every candidate is saved beside "
                     "the model and can be opened in RAM.")
            return {"baseline": baseline, "candidates": cands, "chosen": None}
        choice = int(got)
    chosen = cands[choice]
    job.ok(f"Chosen: {chosen['label']} - {chosen['strands']} strands, "
           f"{chosen['strand_m']:,.0f} strand-m, {chosen['reach']} section(s) "
           f"over the limit that prestress can reach "
           f"({os.path.basename(chosen['path'])}).")
    return {"baseline": baseline, "candidates": cands, "chosen": chosen}


# ==============================================================================
#  17.7 — كل قطاع اتسيّف بكام، والمراجعة في آخر الرن
# ==============================================================================

STEEL_DENSITY_KG_M3 = 7850.0


def strand_kg_per_m(params):
    """وزن الاسترند الواحد كجم/م.ط من مساحته (0.6" = 140 مم² ≈ 1.10)."""
    try:
        area = float(params.strand_area)
    except Exception:
        area = 140.0
    return area * 1e-6 * STEEL_DENSITY_KG_M3


def tendon_plan_length(t):
    pts = [q["pos"] for q in (t.get("profile") or [])]
    return md_cumulative(pts)[-1] if len(pts) >= 2 else 0.0


def floor_strand_kg(tendons, params):
    """كجم الاسترند في السقف كله: طول كل كابل × استرنداته × الوزن."""
    kgm = strand_kg_per_m(params)
    return kgm * sum(int(t.get("strands") or 0) * tendon_plan_length(t)
                     for t in tendons if not t.get("_deleted"))


def slab_area_m2(site):
    """
    مساحة الخرسانة (مساحات البلاطة متّحدة، ناقص الفتحات)، أو None.

    17.10.2: كانت بتتحسب من «الحدود»، واللي بيلفّ أرض مافيهاش خرسانة على
    أي سقف شكله مش مستطيل - وده بيكبّر المقام في كل نسبة بتتقال.
    """
    site = site or {}
    if HAS_SHAPELY:
        try:
            poly = _shp_slab(site)
            if poly is not None and poly.area > 1.0:
                return float(poly.area)
        except Exception:
            pass
    tot = 0.0
    for s in site.get("slabs") or []:
        if s.get("is_drop"):
            continue
        try:
            tot += abs(polygon_area(s.get("points") or []))
        except Exception:
            continue
    if tot > 1.0:
        return tot
    pieces = [p for p in (site.get("pieces") or []) if p and len(p) >= 3]
    if len(pieces) > 1:                                       # 18.15
        try:
            a = sum(abs(float(SlabRegion(p, site.get("openings") or []).area)) for p in pieces)
            if a > 1.0:
                return a
        except Exception:
            pass
    b = site.get("boundary") or []
    try:
        if len(b) >= 3:
            a = abs(float(SlabRegion(b, site.get("openings") or []).area))
            if a > 1.0:
                return a
    except Exception:
        pass
    return None


def _gift_target(t):
    """الكابل اللي الاسترندات دي فيه دلوقتي - لو اتدمج، في جاره."""
    for _ in range(12):
        if t is None:
            return None
        if not t.get("_deleted"):
            return t
        t = t.get("_merged_into")
    return None


def group_tendons(g):
    out, seen = [], set()
    for t, _d, _n in g.get("gifts") or []:
        tt = _gift_target(t)
        if tt is not None and id(tt) not in seen:
            seen.add(id(tt))
            out.append(tt)
    return out


def group_marks(g):
    """مكان القطاعات على المسقط (كابل التصميم من المومنت: نص الكابل)."""
    if g.get("src") == "md":
        t = g.get("tendon") or {}
        pts = [q["pos"] for q in (t.get("profile") or [])]
        if len(pts) < 2:
            return []
        cum = md_cumulative(pts)
        return [md_polyline_at(pts, cum, cum[-1] / 2.0)[0]]
    out, seen = [], set()
    for x, y, _o in g.get("readings") or []:
        k = (round(x, 2), round(y, 2))
        if k not in seen:
            seen.add(k)
            out.append((float(x), float(y)))
    return out


def group_kg(g, params):
    """الكجم اللي المجموعة دي كلّفته: الاسترندات اللي اتحطّت × طول كابلها."""
    kgm = strand_kg_per_m(params)
    tot = 0.0
    for t, d, _n in g.get("gifts") or []:
        tt = _gift_target(t)
        if tt is not None:
            tot += int(d) * tendon_plan_length(tt)
    return tot * kgm


def md_groups_from(tendons):
    """الكابلات اللي التصميم من المومنت أضافها، كل واحد مجموعة."""
    out = []
    for t in tendons or []:
        info = t.get("_md_group")
        if not info or t.get("_deleted"):
            continue
        out.append({"id": f"m{len(out) + 1}", "src": "md", "round": 0,
                    "tag": "moment", "face": None,
                    "dir": str(t.get("dir", "")).lower(), "readings": [],
                    "tendon": t, "label": info.get("label"),
                    "gifts": [(t, int(info.get("strands") or
                                      t.get("strands") or 0), True)]})
    return out


def section_groups_status(groups, plots, near=1.0):
    """
    حالة كل مجموعة من الفحص الحالي: كام قطاع من قطاعاتها لسه فوق الحد
    (نفس الوش والاتجاه، في حدود `near`). لكابل التصميم من المومنت: كام
    قطاع فوق الحد على طوله.
    """
    fails = {}
    for pl in plots or []:
        try:
            fails.setdefault(plot_tag(pl), []).extend(
                (x, y) for x, y, v, lim in pl.failing())
        except Exception:
            continue
    allf = [p for v in fails.values() for p in v]
    out = {}
    for g in groups:
        if g.get("src") == "md":
            pts = [q["pos"] for q in (g["tendon"].get("profile") or [])]
            n = 0
            if len(pts) >= 2:
                n = sum(1 for p in allf
                        if min(md_seg_dist(p, a, b)
                               for a, b in zip(pts, pts[1:])) <= near)
            out[g["id"]] = {"closed": n == 0, "open": n, "total": None}
            continue
        ff = fails.get(g.get("tag"), [])
        marks = group_marks(g)
        n = sum(1 for p in marks if any(md_dist(p, f) <= near for f in ff))
        out[g["id"]] = {"closed": n == 0, "open": n, "total": len(marks)}
    return out


def revert_group_gifts(groups, params):
    """
    يشيل اللي المجموعات دي كلّفته: الكابل المضاف بيتشال لو اللي فاضل فيه
    أقل من الحد الأدنى، والاسترندات اللي اتزادت على كابل موجود بترجع
    (مش تحت الحد الأدنى). بترجّع (كابلات اتشالت، استرندات رجعت).
    """
    n_min = max(int(getattr(params, "min_strands", 2) or 2), 1)
    gone = back = 0
    for g in groups:
        if g.get("removed"):
            continue
        for t, d, is_new in g.get("gifts") or []:
            tt = _gift_target(t)
            if tt is None:
                continue
            now = int(tt.get("strands") or 0)
            left = now - int(d)
            if tt.get("added") or is_new:
                if left < n_min:
                    tt["_deleted"] = True
                    gone += 1
                    back += now
                else:
                    tt["strands"] = left
                    back += int(d)
            else:
                new_n = max(left, n_min)
                back += now - new_n
                tt["strands"] = new_n
        g["removed"] = True
    return gone, back


