def apply_theme(root):
    pick_ui_fonts(root)
    style = ttk.Style(root)
    try:
        style.theme_use("clam")
    except Exception:
        pass

    base = F(10)
    P = PALETTE
    style.configure(".", background=P["bg"], foreground=P["ink"], font=base,
                    bordercolor=P["line"], lightcolor=P["panel"],
                    darkcolor=P["line"], focuscolor=P["brand"])
    style.configure("TFrame", background=P["bg"])
    #  18.74: الكارت الأبيض على خلفية فاتحة محتاج حد رفيع عشان يبان
    #  إنه كارت. في Classic الخلفية أغمق فالحد مالوش لازمة.
    if theme_modern():
        style.configure("Card.TFrame", background=P["panel"], borderwidth=1,
                        relief="solid", bordercolor=P["line"],
                        lightcolor=P["line"], darkcolor=P["line"])
    else:
        style.configure("Card.TFrame", background=P["panel"])
    style.configure("TLabel", background=P["bg"], foreground=P["ink"])
    style.configure("Card.TLabel", background=P["panel"])
    style.configure("Muted.TLabel", background=P["panel"],
                    foreground=P["muted"], font=F(9))
    style.configure("Head.TLabel", background=P["panel"],
                    foreground=P["ink"], font=F(11, "bold"))

    #  أزرار مسطّحة بحالة ضغط وتعطيل واضحة. 18.74: الحشوة أكبر في
    #  Studio - الزرار الصغير المتلزّق شكل برامج التسعينات، والزرار
    #  اللي ليه هوا حواليه هو اللي بيبان كأنه بيتضغط.
    _bp = (18, 11) if theme_modern() else (14, 8)
    _pp = (30, 14) if theme_modern() else (24, 11)
    style.configure("TButton", padding=_bp, font=F(9),
                    background=P["btn"], foreground=P["ink"],
                    borderwidth=0, focusthickness=0, relief="flat")
    style.map("TButton",
              background=[("pressed", P["btn_press"]),
                          ("active", P["btn_hover"]),
                          ("disabled", "#eef1f4")],
              foreground=[("disabled", "#9aa7b4")])
    style.configure("Primary.TButton", padding=_pp,
                    font=F(10, "bold"),
                    background=P["brand"], foreground="white", borderwidth=0)
    style.map("Primary.TButton",
              background=[("pressed", P["brand_dark"]),
                          ("active", P["brand_dark"]),
                          ("disabled", "#a3b4c2")],
              foreground=[("disabled", "#eef3f7")])
    #  زرار تاني بلون الأكسنت - للأفعال اللي مش "ابدأ" بس لسه مهمة
    style.configure("Accent.TButton", padding=_bp, font=F(9, "bold"),
                    background=P["accent"], foreground="#1f1300",
                    borderwidth=0)
    style.map("Accent.TButton",
              background=[("pressed", P["accent"]), ("active", P["accent"]),
                          ("disabled", "#e8e2d6")])
    style.configure("Danger.TButton", padding=_bp, background="#fbe9e9",
                    foreground=P["err"], borderwidth=0)
    style.map("Danger.TButton",
              background=[("active", "#f4d4d4"), ("disabled", "#f3eeee")],
              foreground=[("disabled", "#c9a3a3")])

    #  **18.75: الخانة لازم تبان إنها خانة.**
    #  الشكوى بالحرف: «القوايم المنسدلة ألوانها تايهة في وسط الشاشة
    #  الفاتحة». والسبب إن الحد كان `line` - نفس اللون الرفيع اللي
    #  بيفصل الصفوف - وجوّها أبيض زي الكارت اللي هي واقفة عليه، فمافيش
    #  حاجة بتقول «دي حاجة تتضغط». الحد بقى `line_strong` وبيغمق وقت
    #  الوقوف عليها، والسهم بلون العلامة التجارية مش رمادي باهت.
    style.configure("TEntry", fieldbackground=P["field"], padding=7,
                    foreground=P["field_ink"],
                    bordercolor=P["line_strong"], lightcolor=P["line_strong"],
                    darkcolor=P["line_strong"], insertcolor=P["ink"])
    style.map("TEntry",
              bordercolor=[("focus", P["brand"]), ("hover", P["brand"])],
              lightcolor=[("focus", P["brand"])],
              darkcolor=[("focus", P["brand"])])
    style.configure("Invalid.TEntry", fieldbackground="#fff4f4",
                    bordercolor=P["err"], lightcolor=P["err"],
                    darkcolor=P["err"])
    style.configure("TCombobox", fieldbackground=P["field"], padding=6,
                    foreground=P["field_ink"],
                    bordercolor=P["line_strong"], lightcolor=P["line_strong"],
                    darkcolor=P["line_strong"], arrowsize=S(16),
                    arrowcolor=P["brand"])
    style.map("TCombobox",
              bordercolor=[("focus", P["brand"]), ("hover", P["brand"])],
              lightcolor=[("focus", P["brand"]), ("hover", P["brand"])],
              darkcolor=[("focus", P["brand"]), ("hover", P["brand"])],
              arrowcolor=[("disabled", P["muted"])],
              fieldbackground=[("readonly", P["field"]),
                               ("hover", P["chip"])],
              foreground=[("readonly", P["field_ink"])],
              selectbackground=[("readonly", P["field"])],
              selectforeground=[("readonly", P["field_ink"])])
    #  **القايمة اللي بتنزل نفسها.** دي Listbox من تِك القديمة، ومالهاش
    #  ستايل في ttk خالص - بتتظبط من قاعدة الخيارات وبس. من غير
    #  السطور دي بتفضل بيضا بسطر أزرق فاقع في كل الثيمات، والليلي
    #  بيبقى شباك أبيض في نص شاشة غامقة.
    for opt, val in (("background", P["panel"]), ("foreground", P["ink"]),
                     ("selectBackground", P["brand"]),
                     ("selectForeground", P["on_brand"]),
                     ("font", F(10)), ("borderWidth", 0),
                     ("highlightThickness", 1),
                     ("highlightColor", P["line_strong"]),
                     ("highlightBackground", P["line_strong"])):
        try:
            root.option_add(f"*TCombobox*Listbox.{opt}", val)
        except Exception:
            pass
    #  17.69: مربع الاختيار كان 10 بكسل مهما كان مقياس الشاشة
    style.configure("TCheckbutton", background=P["panel"], font=F(10),
                    foreground=P["ink"],
                    indicatorbackground=P["field"],
                    indicatorforeground=P["field"],
                    indicatorsize=S(12), indicatormargin=(0, 0, 8, 0))
    style.map("TCheckbutton",
              indicatorbackground=[("selected", P["brand"]),
                                   ("disabled", "#e3e8ee")],
              background=[("active", P["panel"])])
    style.configure("Bar.TCheckbutton", background=P["bg"])
    style.map("Bar.TCheckbutton", background=[("active", P["bg"])])
    style.configure("Horizontal.TProgressbar", background=P["brand"],
                    troughcolor=P["chip"], borderwidth=0, thickness=6,
                    lightcolor=P["brand"], darkcolor=P["brand"])
    style.configure("TSeparator", background=P["line"])
    for orient in ("Vertical", "Horizontal"):
        style.configure(f"{orient}.TScrollbar", background=P["line_strong"],
                        troughcolor=P["bg"], bordercolor=P["bg"],
                        arrowcolor=P["muted"], gripcount=0, relief="flat")
        style.map(f"{orient}.TScrollbar",
                  background=[("active", P["muted"]),
                              ("pressed", P["muted"])])
    style.configure("Treeview", background=P["field"],
                    fieldbackground=P["field"],
                    foreground=P["field_ink"], rowheight=S(24),
                    bordercolor=P["line"], font=F(9))
    style.configure("Treeview.Heading", background=P["chip"],
                    foreground=P["muted"], font=F(9, "bold"), relief="flat",
                    padding=(6, 4))
    style.map("Treeview", background=[("selected", P["chip"])],
              foreground=[("selected", P["ink"])])
    style.configure("TNotebook", background=P["bg"], borderwidth=0)
    style.configure("TNotebook.Tab", padding=(14, 6), font=F(9))
    return style


def draw_tool_icon(cv, key, colour, size, bg):
    """أيقونات شريط أدوات المحرّر (18.17) - مرسومة بالخطوط زي أيقونات التنقّل."""
    cv.delete("all")
    s = size / 24.0
    lw = max(1.6 * s, 1.4)

    def P(*pts):
        return [c * s for c in pts]

    line = dict(fill=colour, width=lw, capstyle="round", joinstyle="round")
    if key == "sel_tendon":
        cv.create_line(*P(3, 12, 21, 12), **line)
        cv.create_line(*P(3, 12, 6, 8), **line)
        cv.create_line(*P(21, 12, 18, 8), **line)
        cv.create_rectangle(*P(8.5, 9.5, 15.5, 14.5), outline=colour, width=lw, dash=(2, 2))
    elif key == "sel_point":
        cv.create_line(*P(3, 13, 12, 17, 21, 13), **line)
        for x, y in ((3, 13), (12, 17), (21, 13)):
            cv.create_oval(*P(x - 2.4, y - 2.4, x + 2.4, y + 2.4), fill=bg, outline=colour, width=lw)
    elif key == "measure":
        cv.create_line(*P(3, 18, 21, 6), **line)
        for f in (0.25, 0.5, 0.75):
            x, y = 3 + 18 * f, 18 - 12 * f
            cv.create_line(*P(x - 1.5, y - 2.2, x + 1.5, y + 2.2), **line)
    elif key == "undo":
        cv.create_arc(*P(5, 6, 19, 20), start=40, extent=250, style="arc", outline=colour, width=lw)
        cv.create_polygon(*P(4, 4, 10.5, 6, 6, 11), fill=colour, outline=colour)
    elif key == "redo":
        cv.create_arc(*P(5, 6, 19, 20), start=-110, extent=250, style="arc", outline=colour, width=lw)
        cv.create_polygon(*P(20, 4, 13.5, 6, 18, 11), fill=colour, outline=colour)
    elif key == "delete":
        cv.create_line(*P(6, 6, 18, 18), **line)
        cv.create_line(*P(18, 6, 6, 18), **line)
    elif key == "add_beside":
        cv.create_line(*P(4, 8, 20, 8), **line)
        cv.create_line(*P(4, 16, 13, 16), **line)
        cv.create_line(*P(17, 13, 17, 19), **line)
        cv.create_line(*P(14, 16, 20, 16), **line)
    elif key in ("s_minus", "s_plus"):
        cv.create_oval(*P(4, 4, 20, 20), outline=colour, width=lw)
        cv.create_line(*P(8, 12, 16, 12), **line)
        if key == "s_plus":
            cv.create_line(*P(12, 8, 12, 16), **line)
    elif key in ("h_up", "h_down"):
        cv.create_line(*P(4, 20, 20, 20), **line)
        if key == "h_up":
            cv.create_line(*P(12, 17, 12, 5), **line)
            cv.create_polygon(*P(12, 3, 8, 8, 16, 8), fill=colour, outline=colour)
        else:
            cv.create_line(*P(12, 4, 12, 15), **line)
            cv.create_polygon(*P(12, 18, 8, 13, 16, 13), fill=colour, outline=colour)
    elif key == "recentre":
        cv.create_line(*P(3, 7, 8, 7, 12, 17, 16, 7, 21, 7), **line)
        cv.create_line(*P(12, 19, 12, 22), **line)
    elif key == "rules":
        cv.create_line(*P(4, 13, 9.5, 18.5, 20, 6), **line)
    elif key == "unlock":
        cv.create_rectangle(*P(5, 11, 19, 21), outline=colour, width=lw)
        cv.create_arc(*P(8, 3, 16, 13), start=0, extent=180, style="arc", outline=colour, width=lw)
        cv.create_line(*P(16, 8, 16, 11), **line)
    elif key == "fit":
        for x, y, dx, dy in ((4, 4, 1, 1), (20, 4, -1, 1), (4, 20, 1, -1), (20, 20, -1, -1)):
            cv.create_line(*P(x, y + 5 * dy, x, y, x + 5 * dx, y), **line)
    elif key in ("dir_x", "dir_y", "dir_both"):
        txt = {"dir_x": "X", "dir_y": "Y", "dir_both": "XY"}[key]
        cv.create_text(size / 2, size / 2, text=txt, fill=colour, font=F(9, "bold"))
    elif key == "invert":
        cv.create_rectangle(*P(4, 4, 20, 20), outline=colour, width=lw)
        cv.create_polygon(*P(4, 4, 20, 4, 4, 20), fill=colour, outline=colour)
    elif key == "heights":
        cv.create_text(size / 2, size / 2, text="H", fill=colour, font=F(10, "bold"))
    elif key == "by_strands":
        cv.create_text(size / 2, size / 2, text="nS", fill=colour, font=F(8, "bold"))
    else:
        cv.create_text(size / 2, size / 2, text="•", fill=colour, font=F(12))


class _Tip:
    """تلميح صغير بيظهر بعد نص ثانية على الأيقونة (18.17)."""

    def __init__(self, widget, text):
        self.w = widget
        self.text = text
        self.tip = None
        self._after = None
        widget.bind("<Enter>", self._enter, add="+")
        widget.bind("<Leave>", self._leave, add="+")
        widget.bind("<ButtonPress>", self._leave, add="+")

    def _enter(self, _e=None):
        self._after = self.w.after(450, self._show)

    def _leave(self, _e=None):
        if self._after:
            try:
                self.w.after_cancel(self._after)
            except Exception:
                pass
            self._after = None
        if self.tip:
            try:
                self.tip.destroy()
            except Exception:
                pass
            self.tip = None

    def _show(self):
        try:
            x = self.w.winfo_rootx() + 12
            y = self.w.winfo_rooty() + self.w.winfo_height() + 6
            self.tip = tk.Toplevel(self.w)
            self.tip.wm_overrideredirect(True)
            self.tip.wm_geometry(f"+{x}+{y}")
            tk.Label(self.tip, text=self.text, bg="#2b3a48", fg="white",
                     font=F(9), padx=8, pady=4, justify="left").pack()
        except Exception:
            self.tip = None


def draw_nav_icon(cv, key, colour, size, bg, fallback=""):
    """
    أيقونة عمود التنقّل مرسومة بخطوط على كانفاس صغير (17.64).

    الرموز اليونيكود القديمة (🗀 ⚙ ▣ …) كانت بتتعرض من خط مختلف لكل
    رمز، فمقاساتها ومحاذاتها مش متسقة، والمجلد ممكن يطلع ملوّن على
    ويندوز 11. الرسم بالخطوط بيدي نفس الشكل على كل جهاز وبيتلوّن مع
    حالة الصفحة (نشطة / عادية).
    """
    cv.delete("all")
    s = size / 24.0
    lw = max(1.7 * s, 1.5)

    def P(*pts):
        return [c * s for c in pts]

    line = dict(fill=colour, width=lw, capstyle="round", joinstyle="round")
    if key == "project":            # مجلد
        cv.create_polygon(*P(3, 6, 9.5, 6, 11.5, 8.5, 21, 8.5, 21, 19, 3, 19),
                          outline=colour, fill="", width=lw, joinstyle="round")
        cv.create_line(*P(3, 11.5, 21, 11.5), **line)
    elif key == "settings":         # منزلقات
        for y, x in ((6.5, 15.5), (12, 8.5), (17.5, 14)):
            cv.create_line(*P(3.5, y, 20.5, y), **line)
            cv.create_oval(*P(x - 2.6, y - 2.6, x + 2.6, y + 2.6),
                           fill=bg, outline=colour, width=lw)
    elif key == "banks":            # أربع بلاطات
        for x, y in ((3.5, 3.5), (13, 3.5), (3.5, 13), (13, 13)):
            cv.create_rectangle(*P(x, y, x + 7.5, y + 7.5),
                                outline=colour, width=lw)
    elif key == "shop":             # لوحة عليها سطور
        cv.create_rectangle(*P(5, 3, 19, 21), outline=colour, width=lw)
        cv.create_line(*P(8, 8, 16, 8), **line)
        cv.create_line(*P(8, 12, 16, 12), **line)
        cv.create_line(*P(8, 16, 13, 16), **line)
    elif key == "efm":              # حلقة بسهمين
        cv.create_arc(*P(4, 4, 20, 20), start=20, extent=150, style="arc",
                      outline=colour, width=lw)
        cv.create_arc(*P(4, 4, 20, 20), start=200, extent=150, style="arc",
                      outline=colour, width=lw)
        cv.create_polygon(*P(19.5, 3.5, 20.8, 9.3, 15.2, 8.6),
                          fill=colour, outline=colour)
        cv.create_polygon(*P(4.5, 20.5, 3.2, 14.7, 8.8, 15.4),
                          fill=colour, outline=colour)
    elif key == "editor":           # قلم
        cv.create_polygon(*P(4, 20, 5.5, 15, 16, 4.5, 19.5, 8, 9, 18.5),
                          outline=colour, fill="", width=lw, joinstyle="round")
        cv.create_line(*P(13.5, 7, 17, 10.5), **line)
        cv.create_line(*P(4, 20, 9, 18.5), **line)
    elif key == "adapt":            # سهمين متقابلين
        cv.create_line(*P(4, 8.5, 18, 8.5), **line)
        cv.create_polygon(*P(15, 4.5, 20.5, 8.5, 15, 12.5), fill=colour, outline=colour)
        cv.create_line(*P(20, 16, 6, 16), **line)
        cv.create_polygon(*P(9, 12, 3.5, 16, 9, 20), fill=colour, outline=colour)
    elif key == "review":           # لوحة عليها علامة صح
        cv.create_rectangle(*P(5, 4, 19, 21), outline=colour, width=lw)
        cv.create_rectangle(*P(9, 2.5, 15, 6), outline=colour, fill=bg, width=lw)
        cv.create_line(*P(8, 13.5, 11, 16.5, 16.5, 9.5), **line)
    elif key == "geometry":         # قطاع بلاطة على عمود
        cv.create_rectangle(*P(3, 6, 21, 10), outline=colour, width=lw)
        cv.create_rectangle(*P(9.5, 10, 14.5, 20), outline=colour, width=lw)
        cv.create_line(*P(6, 3.5, 6, 6), **line)
        cv.create_line(*P(12, 3.5, 12, 6), **line)
        cv.create_line(*P(18, 3.5, 18, 6), **line)
    elif key == "design":           # بروفايل كابل: قمة - غطسة - قمة
        cv.create_line(*P(3, 7, 6, 7, 9, 16, 12, 18, 15, 16, 18, 7, 21, 7),
                       smooth=True, **line)
        cv.create_oval(*P(4.6, 5.6, 7.4, 8.4), fill=colour, outline=colour)
        cv.create_oval(*P(16.6, 5.6, 19.4, 8.4), fill=colour, outline=colour)
    elif key == "run":              # تشغيل
        cv.create_polygon(*P(7, 4, 20, 12, 7, 20), fill=colour,
                          outline=colour, width=lw, joinstyle="round")
    else:
        cv.create_text(size / 2, size / 2, text=fallback or "•",
                       fill=colour, font=F(12))


class NavRail(tk.Frame):
    """Vertical icon navigation rail, replacing tabs."""

    #  18.74: الألوان من اللوحة، مش مكتوبة هنا - عمود التنقّل في
    #  Studio فاتح، فالثوابت المكتوبة كانت هتخلّيه رمادي على أبيض.
    @property
    def C_ICON(self):
        return PALETTE["nav_icon"]

    @property
    def C_TITLE(self):
        return PALETTE["nav_ink"]

    @property
    def C_SUB(self):
        return PALETTE["nav_sub"]

    def __init__(self, master, items, on_select):
        super().__init__(master, bg=PALETTE["nav"], width=S(252))
        self.pack_propagate(False)
        self.on_select = on_select
        self.buttons = {}
        self.active = None

        tk.Frame(self, bg=PALETTE["nav"], height=S(14)).pack(fill="x")

        for i, (key, icon, title, sub) in enumerate(items, start=1):
            row = tk.Frame(self, bg=PALETTE["nav"], cursor="hand2")
            row.pack(fill="x", padx=S(10), pady=S(2))

            marker = tk.Frame(row, bg=PALETTE["nav"], width=S(4))
            marker.pack(side="right", fill="y")

            inner = tk.Frame(row, bg=PALETTE["nav"])
            inner.pack(fill="x", padx=(0, S(8)), pady=S(9))

            isz = S(22)
            ico = tk.Canvas(inner, width=isz, height=isz, bg=PALETTE["nav"],
                            highlightthickness=0, bd=0)
            ico.pack(side="right", padx=(S(10), S(6)))
            ico._key, ico._fallback, ico._size = key, icon, isz
            draw_nav_icon(ico, key, self._icon_colour(key, False), isz,
                          PALETTE["nav"], icon)

            txt = tk.Frame(inner, bg=PALETTE["nav"])
            txt.pack(side="right", fill="x", expand=True)
            lbl = tk.Label(txt, text=title, bg=PALETTE["nav"], fg=self.C_TITLE,
                           font=F(10, "bold"), anchor="e")
            lbl.pack(fill="x")
            sublbl = tk.Label(txt, text=sub, bg=PALETTE["nav"], fg=self.C_SUB,
                              font=F(8), anchor="e")
            sublbl.pack(fill="x")
            #  اختصار الصفحة، صغير على الطرف - Ctrl+1 … Ctrl+6
            hint = tk.Label(inner, text=f"^{i}", bg=PALETTE["nav"],
                            fg=PALETTE["nav_hint"], font=F(7, mono=True))
            hint.pack(side="left", padx=(S(6), 0))

            widgets = (row, inner, txt, ico, lbl, sublbl, hint)
            for w in widgets:
                w.bind("<Button-1>", lambda e, k=key: self.select(k))
                w.bind("<Enter>", lambda e, k=key: self._hover(k, True))
                w.bind("<Leave>", lambda e, k=key: self._hover(k, False))
            self.buttons[key] = (row, inner, txt, marker, ico, lbl, sublbl, hint)

        foot = tk.Label(self, text=f"v{APP_VERSION}", bg=PALETTE["nav"],
                        fg=PALETTE["nav_hint"], font=F(8, mono=True))
        foot.pack(side="bottom", pady=S(12))

    def _paint(self, key, on, hover=False):
        row, inner, txt, marker, ico, lbl, sublbl, hint = self.buttons[key]
        if on:
            bg = PALETTE["nav_active"]
        elif hover:
            bg = PALETTE["nav_hover"]
        else:
            bg = PALETTE["nav"]
        for w in (row, inner, txt, ico, lbl, sublbl, hint):
            w.configure(bg=bg)
        marker.configure(bg=PALETTE["brand"] if on else bg)
        draw_nav_icon(ico, ico._key, self._icon_colour(ico._key, on),
                      ico._size, bg, ico._fallback)
        lbl.configure(fg=PALETTE["nav_on_ink"] if on else self.C_TITLE)
        sublbl.configure(fg=PALETTE["nav_on_sub"] if on else self.C_SUB)

    def _icon_colour(self, key, on):
        if not theme_is("classic"):
            return nav_colours().get(key, PALETTE["brand"])
        return PALETTE["nav_on_ink"] if on else self.C_ICON

    def _hover(self, key, entering):
        if key != self.active:
            self._paint(key, False, hover=entering)

    def select(self, key):
        for k in self.buttons:
            self._paint(k, k == key)
        self.active = key
        self.on_select(key)


# ==============================================================================
#  SECTION 9a - What does this setting actually do?
#
#  Forty-odd numbers control where the nodes land, and a one-line hint next to
#  a box cannot show a shape. Every setting that changes the geometry gets a
#  small drawing instead: the profile with and without it, the distance it
#  measures, the node it adds or takes away. The drawings are painted on a
#  canvas rather than shipped as images, so the whole program stays one file.
# ==============================================================================

class Ink:
    """Drawing helpers shared by every parameter diagram."""

    TOP = "#c47a12"          # high point
    LOW = "#12496f"          # low point
    RUN = "#c1362b"          # the tendon
    GHOST = "#9aa7b2"        # the "before" state
    OK = "#178a5a"
    NO = "#a0392f"

    def __init__(self, cv, w, h):
        self.cv, self.w, self.h = cv, w, h

    # ---- structure ----------------------------------------------------
    def slab(self, x0, x1, y_top, y_bot):
        self.cv.create_rectangle(x0, y_top, x1, y_bot, fill="#eef2f6",
                                 outline="#c4d0da")
        return y_top, y_bot

    def drop(self, x0, x1, y_bot, deep=16):
        self.cv.create_rectangle(x0, y_bot, x1, y_bot + deep, fill="#dce8f2",
                                 outline="#9fbcd4")

    def column(self, x, y_bot, w=24, h=34):
        self.cv.create_rectangle(x - w / 2, y_bot, x + w / 2, y_bot + h,
                                 fill="#12496f", outline="")

    def wall(self, x0, x1, y, thick=9):
        self.cv.create_rectangle(x0, y - thick / 2, x1, y + thick / 2,
                                 fill="#6b7d8c", outline="")

    # ---- the tendon ---------------------------------------------------
    def run(self, pts, colour=None, width=2, dash=None):
        flat = [c for p in pts for c in p]
        kw = {"fill": colour or self.RUN, "width": width, "smooth": True}
        if dash:
            kw["dash"] = dash
        self.cv.create_line(*flat, **kw)

    def high(self, x, y, r=4):
        self.cv.create_rectangle(x - r, y - r, x + r, y + r, fill=self.TOP,
                                 outline="")

    def low(self, x, y, r=4.5):
        self.cv.create_oval(x - r, y - r, x + r, y + r, fill=self.LOW,
                            outline="")

    def anchor(self, x, y, r=4.5):
        self.cv.create_oval(x - r, y - r, x + r, y + r, fill="",
                            outline="#5b6b7a", width=1.6)

    def cross(self, x, y, r=5):
        self.cv.create_line(x - r, y - r, x + r, y + r, fill=self.NO, width=1.8)
        self.cv.create_line(x + r, y - r, x - r, y + r, fill=self.NO, width=1.8)

    # ---- annotation ---------------------------------------------------
    def dim(self, x0, x1, y, text, colour="#5b6b7a"):
        self.cv.create_line(x0, y, x1, y, fill=colour, arrow="both",
                            arrowshape=(6, 7, 2.5))
        self.cv.create_line(x0, y - 4, x0, y + 4, fill=colour)
        self.cv.create_line(x1, y - 4, x1, y + 4, fill=colour)
        self.cv.create_text((x0 + x1) / 2, y - 9, text=text, fill=colour,
                            font=F(8))

    def vdim(self, x, y0, y1, text, colour="#5b6b7a"):
        self.cv.create_line(x, y0, x, y1, fill=colour, arrow="both",
                            arrowshape=(6, 7, 2.5))
        self.cv.create_text(x + 4, (y0 + y1) / 2, text=text, fill=colour,
                            anchor="w", font=F(8))

    def note(self, x, y, text, colour="#5b6b7a", anchor="center", bold=False):
        self.cv.create_text(x, y, text=text, fill=colour, anchor=anchor,
                            font=F(8, "bold" if bold else "normal"))

    def caption(self, text, colour="#5b6b7a"):
        self.cv.create_text(self.w / 2, self.h - 12, text=text, fill=colour,
                            font=F(8))

    def split(self, label_a, label_b):
        """Two panels side by side, with a rule between them."""
        mid = self.w / 2
        self.cv.create_line(mid, 18, mid, self.h - 26, fill="#d6dee6")
        self.note(mid / 2, 14, label_a, "#5b6b7a", bold=True)
        self.note(mid + mid / 2, 14, label_b, self.OK, bold=True)
        return mid


# ------------------------------------------------------------------ draws --

def _d_covers(k):
    k.slab(40, 460, 40, 110)
    k.note(46, 32, "top surface", anchor="w")
    k.note(46, 120, "soffit", anchor="w")
    k.run([(40, 92), (150, 92), (250, 52), (350, 92), (460, 92)])
    k.high(250, 52)
    k.low(150, 92)
    k.vdim(258, 40, 52, "CGS from top", k.TOP)
    k.vdim(158, 92, 110, "CGS from soffit", k.LOW)
    k.caption("the high point is measured downwards from the top surface, "
              "the low point upwards from the soffit")


def _d_min_point_gap(k):
    mid = k.split("too close", "kept apart")
    k.run([(30, 70), (110, 46), (190, 70)])
    k.high(104, 46); k.high(118, 46)
    k.cross(111, 46)
    k.dim(104, 118, 96, "< gap")
    k.note(mid / 2, 118, "the second node cannot be built - it is dropped")
    k.run([(mid + 30, 70), (mid + 110, 46), (mid + 190, 70)])
    k.high(mid + 90, 46); k.high(mid + 140, 46)
    k.dim(mid + 90, mid + 140, 96, "≥ gap")
    k.caption("also how close a node may come to an anchorage")


def _d_min_sag_span(k):
    k.slab(40, 460, 40, 100)
    k.run([(40, 60), (120, 60), (150, 60), (250, 92), (350, 60), (400, 60), (460, 60)])
    k.high(120, 60); k.high(150, 60); k.high(350, 60); k.high(400, 60)
    k.low(250, 92)
    k.dim(120, 150, 116, "short - no low point")
    k.dim(150, 350, 130, "long enough - low point at its middle")
    k.caption("a gap shorter than this stays flat")


def _d_support_line_reach(k):
    k.column(180, 96); k.column(300, 96)
    k.cv.create_line(180, 60, 300, 60, fill="#12496f", width=3)
    k.dim(300, 360, 44, "reach")
    k.cv.create_line(300, 60, 360, 60, fill="#12496f", width=2, dash=(4, 3))
    k.run([(60, 76), (440, 76)], k.RUN)
    k.high(340, 76)
    k.note(400, 76, "✓", k.OK, anchor="w", bold=True)
    k.run([(60, 130), (440, 130)], k.RUN)
    k.cross(400, 130)
    k.note(250, 152, "a tendon past the reach gets no peak on this line")
    k.caption("how far the support line still counts past its last support")


def _d_axis_max_gap(k):
    k.column(90, 92); k.column(150, 92); k.column(400, 92)
    k.cv.create_line(90, 60, 150, 60, fill="#12496f", width=3)
    k.cv.create_line(400, 60, 400, 60, fill="#12496f", width=3)
    k.dim(150, 400, 44, "gap between two supports")
    k.run([(40, 76), (460, 76)])
    k.high(90, 76); k.high(150, 76); k.high(400, 76)
    k.note(275, 76, "no peak here", k.OK)
    k.cv.create_line(275, 52, 275, 100, fill=k.NO, width=1.4, dash=(3, 3))
    k.note(250, 130, "wider than the limit → the support line is cut in two,")
    k.note(250, 144, "and the empty middle stops lifting anything")
    k.caption("0 turns the limit off and the whole line counts as one axis")


def _d_drop_top_run(k):
    k.slab(40, 460, 46, 100)
    k.drop(170, 350, 100)
    k.column(260, 116)
    k.run([(40, 84), (120, 84), (200, 58), (320, 58), (400, 84), (460, 84)])
    k.high(200, 58); k.high(320, 58)
    k.dim(260, 320, 42, "run")
    k.dim(200, 260, 42, "run")
    k.note(260, 130, "flat on top across the drop, but no further")
    k.note(260, 144, "than this from the column inside it")
    k.note(260, 158, "a short drop ends the flat top at its own face")
    k.caption("a ceiling, not a distance to run out to")


def _d_drop_node_inset(k):
    k.slab(40, 460, 46, 100)
    k.drop(150, 380, 100)
    k.run([(40, 84), (120, 84), (185, 58), (345, 58), (410, 84), (460, 84)])
    k.high(185, 58); k.high(345, 58)
    k.cv.create_line(150, 46, 150, 118, fill="#9fbcd4", dash=(3, 3))
    k.dim(150, 185, 132, "inset")
    k.note(265, 152, "a node sitting on the change in thickness meshes badly")
    k.caption("so it is pulled back inside the drop")


def _d_wall_parallel(k):
    k.wall(140, 380, 60)
    k.note(260, 44, "wall, seen on plan")
    k.run([(40, 80), (460, 80)], k.RUN)
    k.vdim(200, 64, 80, "reach")
    k.high(140, 80); k.high(380, 80)
    k.note(140, 100, "wall starts", anchor="center")
    k.note(380, 100, "wall ends", anchor="center")
    k.note(260, 130, "a tendon within reach of a wall and parallel to it")
    k.note(260, 144, "is supported all along it - it peaks at both ends")


def _d_crossing_wide(k):
    mid = k.split("narrow", "wide")
    k.wall(90, 110, 70, thick=20)
    k.run([(30, 90), (100, 56), (190, 90)])
    k.high(100, 56)
    k.note(110, 116, "one node in the middle")
    k.wall(mid + 70, mid + 150, 70, thick=20)
    k.run([(mid + 20, 90), (mid + 70, 56), (mid + 150, 56), (mid + 200, 90)])
    k.high(mid + 70, 56); k.high(mid + 150, 56)
    k.note(mid + 110, 116, "two nodes, flat between them")
    k.caption("the width at which one node becomes two - both methods")


def _d_inflection(k):
    k.run([(40, 56), (180, 56), (250, 100), (320, 100), (460, 56)])
    k.high(60, 56); k.low(285, 100)
    k.cv.create_oval(174, 68, 182, 76, outline="#5b6b7a", width=1.5)
    k.note(190, 62, "inflection", anchor="w")
    k.dim(60, 285, 128, "high → low")
    k.dim(60, 178, 142, "β of it")
    k.caption("where the reverse curve crosses, as a fraction of the run")


def _d_short_sag(k):
    for i, (x0, x1, drop_y, lab) in enumerate((
            (40, 140, 74, "50%"), (170, 300, 88, "75%"), (330, 460, 104, "full"))):
        k.slab(x0, x1, 40, 110)
        k.run([(x0, 56), ((x0 + x1) / 2, drop_y), (x1, 56)])
        k.high(x0 + 4, 56); k.high(x1 - 4, 56)
        k.low((x0 + x1) / 2, drop_y)
        k.note((x0 + x1) / 2, 126, lab, k.LOW, bold=True)
    k.note(250, 146, "a short span cannot reach the full drape - "
                     "the low point is lifted")


def _d_spacing(k):
    for i in range(7):
        x = 90 + i * 50
        k.cv.create_line(x, 40, x, 120, fill=k.RUN, width=1.8)
    k.cv.create_rectangle(50, 40, 440, 120, outline="#c4d0da")
    k.dim(90, 140, 132, "spacing")
    k.dim(50, 90, 30, "edge offset")
    k.caption("both edges get the same offset; the run between them is centred")


def _d_band_spacing(k):
    k.cv.create_rectangle(50, 36, 450, 130, outline="#c4d0da")
    for grp in (110, 250, 390):
        for i in range(4):
            x = grp - 12 + i * 8
            k.cv.create_line(x, 36, x, 130, fill=k.RUN, width=1.6)
        k.column(grp, 130, w=18, h=14)
    k.dim(238, 246, 26, "band spacing")
    k.caption("banded mode gathers the tendons of one direction onto the "
              "column lines")


def _d_band_group(k):
    k.column(120, 96, w=20, h=26); k.column(360, 96, w=20, h=26)
    for y in (70, 80, 90):
        k.cv.create_line(60, y, 430, y, fill="#1668b8", width=1.8)
    k.cv.create_rectangle(120, 62, 360, 98, outline=k.NO, dash=(4, 3))
    k.cv.create_line(120, 80, 360, 80, fill=k.NO, width=1.4, dash=(3, 3))
    k.note(240, 52, "band: same two supports, bunched, with a support in it",
           k.NO)
    k.cv.create_line(240, 20, 240, 150, fill="#178a5a", width=1.8)
    k.high(240, 80)
    k.note(300, 130, "the crossing tendon peaks on the band's centre line",
           anchor="w")


def _d_clear_high(k):
    k.cv.create_line(60, 60, 440, 60, fill=k.NO, width=1.4, dash=(3, 3))
    k.note(60, 48, "band centre", k.NO, anchor="w")
