def _d_edge_band(k):
    k.cv.create_line(40, 118, 460, 118, fill="#12496f", width=2.5)
    k.note(46, 130, "slab edge", anchor="w")
    for y in (96, 104):
        k.cv.create_line(70, y, 430, y, fill="#1668b8", width=1.8)
    k.cv.create_rectangle(70, 90, 430, 110, outline=k.NO, dash=(4, 3))
    k.note(250, 78, "edge band - runs alongside the edge", k.NO)
    k.cv.create_line(250, 30, 250, 116, fill="#178a5a", width=1.8)
    k.cross(250, 100)
    k.note(250, 150, "the crossing tendon anchors at that edge, "
                     "so it is not lifted")


def _d_sag_midspan(k):
    mid = k.split("from the plot", "at midspan")
    k.run([(30, 56), (80, 96), (190, 56)])
    k.high(30, 56); k.high(190, 56); k.low(80, 96)
    k.cv.create_line(110, 46, 110, 106, fill="#9aa7b2", dash=(3, 3))
    k.note(110, 120, "middle")
    k.run([(mid + 30, 56), (mid + 110, 96), (mid + 190, 56)])
    k.high(mid + 30, 56); k.high(mid + 190, 56); k.low(mid + 110, 96)
    k.caption("measured along the tendon, so a curved run stays on its route")


def _d_cantilever(k):
    k.column(150, 100); k.column(390, 100)
