class InfoPopup(tk.Toplevel):
    """One setting, one drawing, one paragraph."""

    W, H = 500, 176

    def __init__(self, parent, key):
        super().__init__(parent)
        title, text, draw = PARAM_INFO[key]
        self.title(title)
        self.configure(bg=PALETTE["panel"])
        self.resizable(False, False)
        self.transient(parent.winfo_toplevel())

        tk.Label(self, text=title, bg=PALETTE["panel"], fg=PALETTE["ink"],
                 font=F(11, "bold"), anchor="w"
                 ).pack(fill="x", padx=18, pady=(14, 2))
        tk.Label(self, text=key, bg=PALETTE["panel"], fg=PALETTE["muted"],
                 font=F(8, mono=True), anchor="w").pack(fill="x", padx=18)

        cv = tk.Canvas(self, width=self.W, height=self.H,
                       bg=PALETTE["figure_bg"],
                       highlightthickness=1,
                       highlightbackground=PALETTE["line"])
        cv.pack(padx=18, pady=12)
        try:
            draw(Ink(cv, self.W, self.H))
        except Exception as e:                      # a drawing must never stop
            cv.create_text(self.W / 2, self.H / 2,  # the program
                           text=f"(diagram unavailable: {e})",
                           fill=PALETTE["muted"], font=F(8))

        tk.Label(self, text=text, bg=PALETTE["panel"], fg=PALETTE["ink"],
                 font=F(9), justify="left", anchor="w",
                 wraplength=self.W).pack(fill="x", padx=18, pady=(0, 6))
        ttk.Button(self, text="Close", command=self.destroy
                   ).pack(anchor="e", padx=18, pady=(0, 14))

        self.bind("<Escape>", lambda e: self.destroy())
        self.update_idletasks()
        px = parent.winfo_toplevel()
        self.geometry(f"+{px.winfo_rootx() + 90}+{px.winfo_rooty() + 70}")


def round_rect(cv, x1, y1, x2, y2, r, **kw):
    """
    مستطيل بحواف مدوّرة على كانفاس - تِك مافيهاش نصف قطر أصلاً.

    بيتعمل بمضلّع نقطه على قوس الزوايا و`smooth`. رخيص: نداء واحد
    لكل كارت، مش رسم كل إطار.
    """
    pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r,
           x2, y2, x2 - r, y2, x1 + r, y2, x1, y2, x1, y2 - r,
           x1, y1 + r, x1, y1]
    return cv.create_polygon(pts, smooth=True, **kw)


class Card(ttk.Frame):
    """A titled card with an icon."""

    #  18.74: كل كارت بياخد اللون اللي بعده في الدور - الصفحة بتبقى
    #  ليها إيقاع، والكارت بيبقى ليه علامة تفتكرها بدل سطر في قايمة.
    _accent_n = 0

    def __init__(self, master, title, subtitle=None, icon=None):
        pad = (20, 16, 20, 18) if theme_modern() else (18, 14, 18, 16)
        super().__init__(master, style="Card.TFrame", padding=pad)
        self.title_text = tr(title)
        self.subtitle_text = tr(subtitle) if subtitle else None
        head = ttk.Frame(self, style="Card.TFrame")
        head.pack(fill="x")
        if icon:
            if theme_modern():
                _acc = card_accents()
                chip, tint = _acc[Card._accent_n % len(_acc)]
                Card._accent_n += 1
                box_px = S(34)
                cv = tk.Canvas(head, width=box_px, height=box_px,
                               bg=PALETTE["panel"], highlightthickness=0,
                               bd=0)
                cv.pack(side="right", padx=(S(12), 0))
                round_rect(cv, 1, 1, box_px - 1, box_px - 1, S(9),
                           fill=chip, outline="")
                cv.create_text(box_px / 2, box_px / 2, text=icon, fill=tint,
                               font=F(14))
            else:
                tk.Label(head, text=icon, bg=PALETTE["panel"],
                         fg=PALETTE["brand"], font=F(14)).pack(
                             side="right", padx=(10, 0))
        box = ttk.Frame(head, style="Card.TFrame")
        box.pack(side="right", fill="x", expand=True)
        ttk.Label(box, text=self.title_text, style="Head.TLabel", anchor="e").pack(fill="x")
        if self.subtitle_text:
            ttk.Label(box, text=self.subtitle_text, style="Muted.TLabel",
                      anchor="e").pack(fill="x")

        if theme_modern():
            #  مفيش خط فاصل: المسافة هي الفاصل. الخطوط الرفيعة بين كل
            #  حاجة وحاجة هي اللي بتخلّي الشاشة تبان مزدحمة.
            tk.Frame(self, bg=PALETTE["panel"], height=S(12)).pack(fill="x")
        else:
            ttk.Separator(self, orient="horizontal").pack(fill="x",
                                                          pady=(10, 10))
        self.body = ttk.Frame(self, style="Card.TFrame")
        self.body.pack(fill="both", expand=True)
        self.body.columnconfigure(0, weight=1)
        self._row = 0
        # A one-line hint is as wide as its sentence, and a card is as wide as
        # its widest child - which is how a column came to demand more than
        # half the window. Wrapping them to the card's own width stops that.
        self._wrap = []
        #  **ده اللي كان بيخلّي البرنامج يفتح في دقيقة ونص (17.64).** سطر
        #  التلميح كان بيتعمل من غير wraplength، فجملة طويلة بتطلب 8,600
        #  بكسل والكارت بياخد عرضها. أول <Configure> بيلفّ التلميحات على
        #  (العرض - 48)، فالكارت يضيق بكام بكسل (آخر كلمة في السطر)،
        #  فتيجي <Configure> جديدة بعرض أصغر، وهكذا: 500 دورة لكل كارت
        #  و6,765 نداء قبل ما التخطيط يستقر - 37 ثانية لصفحة الإعدادات
        #  و47 لصفحة الـ EFM. دلوقتي كل تلميح بيتعمل ملفوف على عرض كارت
        #  معقول من الأول، والتعديل بيتجمّع في نداء واحد وقت الخمول.
        self._wrap_w = S(400)
        self._wrap_after = None
        #  المرجع هو كانفاس الصفحة: عرضه من النافذة مش من المحتوى، فمفيش
        #  دوّامة. الكارت في نص عمود من اتنين (فاصل 18) وحشوته 48.
        self._canvas = self._find_canvas()
        self.bind("<Configure>", self._rewrap)

    def _find_canvas(self):
        w = self.master
        while w is not None and not isinstance(w, tk.Canvas):
            w = getattr(w, "master", None)
        return w

    def _add_wrapped(self, lbl):
        lbl.configure(wraplength=self._wrap_w)
        self._wrap.append(lbl)
        return lbl

    def _target_wrap(self, event_width):
        if self._canvas is not None:
            try:
                cw = int(self._canvas.winfo_width())
            except Exception:
                cw = 0
            if cw <= 100:                 # الصفحة لسه ماتحطتش على الشاشة
                return self._wrap_w
            return max(int((cw - 18) / 2) - 48, 160)
        return max(event_width - 48, 160)

    def _rewrap(self, event):
        w = self._target_wrap(event.width)
        if w == self._wrap_w:
            return
        self._wrap_w = w
        if self._wrap_after is None:
            try:
                self._wrap_after = self.after_idle(self._apply_wrap)
            except Exception:
                self._apply_wrap()

    def _apply_wrap(self):
        self._wrap_after = None
        w = self._wrap_w
        for lbl in self._wrap:
            try:
                if int(lbl.cget("wraplength") or 0) != w:
                    lbl.configure(wraplength=w)
            except Exception:
                pass

    def _info(self, parent, key):
        """The little mark that opens the drawing for this setting."""
        if not key or key not in PARAM_INFO:
            return None
        btn = tk.Label(parent, text="\u24d8", bg=PALETTE["panel"],
                       fg=PALETTE["brand"], font=F(11),
                       cursor="hand2")
        btn.bind("<Button-1>", lambda e, k=key: InfoPopup(self, k))
        btn.bind("<Enter>", lambda e: btn.configure(fg=PALETTE["accent"]))
        btn.bind("<Leave>", lambda e: btn.configure(fg=PALETTE["brand"]))
        return btn

    def field(self, label, widget, hint=None, info=None):
        hint = tr(hint)
        label = tr(label)
        box = ttk.Frame(self.body, style="Card.TFrame")
        box.grid(row=self._row, column=1, sticky="e", padx=(12, 0), pady=5)
        lab = ttk.Label(box, text=label, style="Card.TLabel", anchor="e")
        lab.pack(side="right")
        mark = self._info(box, info)
        if mark is not None:
            mark.pack(side="right", padx=(0, 6))
        widget.grid(row=self._row, column=0, sticky="ew", pady=5)
        parts = [box, widget]
        if hint:
            self._row += 1
            h = ttk.Label(self.body, text=hint, style="Muted.TLabel",
                          anchor="e", justify="right")
            h.grid(row=self._row, column=0, columnspan=2, sticky="e", pady=(0, 5))
            self._add_wrapped(h)
            parts.append(h)
        self._row += 1
        # A row is a label, a widget and often a hint. Hiding a setting means
        # hiding all of them, so they travel together.
        widget._row_parts = parts
        return widget

    def entry(self, label, var, hint=None, width=14, info=None):
        hint = tr(hint)
        e = ttk.Entry(self.body, textvariable=var, justify="right")
        return self.field(label, e, hint, info=info)

    def combo(self, label, var, values, hint=None, width=34, info=None):
        hint = tr(hint)
        c = ttk.Combobox(self.body, textvariable=var, values=list(values),
                         state="readonly", justify="right")
        return self.field(label, c, hint, info=info)

    def check(self, label, var, hint=None, info=None):
        hint = tr(hint)
        label = tr(label)
        box = ttk.Frame(self.body, style="Card.TFrame")
        box.grid(row=self._row, column=0, columnspan=2, sticky="e", pady=5)
        c = ttk.Checkbutton(box, text=label, variable=var)
        c.pack(side="right")
        mark = self._info(box, info)
        if mark is not None:
            mark.pack(side="right", padx=(0, 6))
        self._row += 1
        parts = [box]
        if hint:
            h = ttk.Label(self.body, text=hint, style="Muted.TLabel",
                          anchor="e", justify="right")
            h.grid(row=self._row, column=0, columnspan=2, sticky="e", pady=(0, 5))
            self._add_wrapped(h)
            parts.append(h)
            self._row += 1
        c._row_parts = parts
        return c

    def note(self, text_var):
        lbl = ttk.Label(self.body, textvariable=text_var, style="Muted.TLabel",
                        anchor="e", justify="right")
        lbl.grid(row=self._row, column=0, columnspan=2, sticky="e", pady=(10, 0))
        self._add_wrapped(lbl)
        self._row += 1
        return lbl

    def text(self, content):
        content = tr(content)
        lbl = tk.Label(self.body, text=content, bg=PALETTE["panel"],
                       fg=PALETTE["muted"], font=F(9),
                       justify="right", anchor="e")
        lbl.grid(row=self._row, column=0, columnspan=2, sticky="e", pady=(8, 0))
        self._add_wrapped(lbl)
        self._row += 1
        return lbl

    def row(self):
        """
        صف أزرار داخل الكارت.

        [F16] الجسم بتاع الكارت متداره بـ grid (كل field/entry/check
        بيعمل .grid عليه). لو حطينا فيه إطار بـ .pack، تِك بيرمي
        TclError: cannot use geometry manager pack ... already has slaves
        managed by grid — والخطأ ده بيقتل بناء النافذة كلها، فالبرنامج
        مبيفتحش أصلاً. ده اللي حصل من إصدار 83 لحد 85: صفحة البنوك
        كانت بتعمل الحتة دي أربع مرات.
        """
        frame = ttk.Frame(self.body, style="Card.TFrame")
        frame.grid(row=self._row, column=0, columnspan=2, sticky="ew",
                   pady=(10, 4))
        self._row += 1
        return frame

    def figure(self, key, height=150):
        """
        رسمة الإعداد ظاهرة على طول، مش وراء أيقونة.

        الأيقونة ⓘ لسه موجودة جنب كل خانة، لكن اللي بيفتح صفحة إعدادات
        أول مرة مش هايضغط عليها - فالمجموعة اللي ليها رسمة بتوريها فوقها
        من غير ضغط.
        """
        if not key or key not in PARAM_INFO:
            return None
        title, _text, draw = PARAM_INFO[key]
        w = 440
        box = ttk.Frame(self.body, style="Card.TFrame")
        box.grid(row=self._row, column=0, columnspan=2, pady=(4, 10))
        self._row += 1
        cv = tk.Canvas(box, width=w, height=height,
                       bg=PALETTE["figure_bg"],
                       highlightthickness=1, highlightbackground=PALETTE["line"])
        cv.pack()
        try:
            draw(Ink(cv, w, height))
        except Exception as e:            # a drawing must never stop the page
            cv.create_text(w / 2, height / 2, text=f"(diagram unavailable: {e})",
                           fill=PALETTE["muted"], font=F(8))
        ttk.Label(box, text=title, style="Muted.TLabel", anchor="center"
                  ).pack(fill="x", pady=(3, 0))
        return box

    def separator(self):
        ttk.Separator(self.body, orient="horizontal").grid(
            row=self._row, column=0, columnspan=2, sticky="ew", pady=12)
        self._row += 1


class _BankArgs:
    """
    كائن وسائط شبيه بـ argparse عشان ننادي دوال البنوك زي ما سطر الأوامر
    بينادينها بالظبط.

    الفايدة إن الصفحة مش بتكرر أي منطق: نفس الدالة اللي الباتش بيشغّلها هي
    اللي الزرار بيشغّلها، فمستحيل الاتنين يختلفوا في النتيجة.
    أي خاصية مش متحطّة بترجع None.
    """

    def __init__(self, **kw):
        self.__dict__.update(kw)

    def __getattr__(self, name):
        return None


class AutoPTApp:

    #  18.25: الترتيب بالاستخدام - من غير صفحة "إعدادات" واحدة: الهندسة
    #  والأحمال (اللي بتتظبط لكل مشروع) في صفحة، والتصميم في صفحة.
    NAV = [
        ("project",  "🗀", "Project",          "Method and files"),
        ("geometry", "▤", "Geometry & loads", "Slab, members, loads"),
        ("design",   "⌒", "Design",           "Profile, layout, strands, strips"),
        ("efm",      "↻", "EFM loop",         "Let RAM's own design drive it"),
        ("run",      "▶", "Run",              "Log and progress"),
        ("editor",   "✎", "Tendon editor",    "Edit a model's tendons"),
        ("review",   "✓", "Project review",   "Many models, one report"),
        ("shop",     "◫", "Shop drawings",    "Layout, style and export"),
        ("banks",    "▣", "Banks",            "Experience · edits · tests"),
        ("adapt",    "⇄", "ADAPT → RAM",      "Convert an .adm file"),
    ]

    def __init__(self, root):
        self.root = root
        self._groups = {}
        self.bridge = UiBridge(root)
        self.job = None
        self.worker = None
        self._last_output = None      # آخر موديل البرنامج حفظه — بيتملّي في صفحة البنوك
        self._last_drawing = None     # آخر لوحة (DXF) - مش موديل
        #  حالة الرن الواحد: تخطيط الليّرات اللي اتأكد، ومسح كابلات
        #  المرحلة الأولى، وتخطّي إعادة كتابة الشرائح في المرحلة التانية.
        self._layer_choice = None
        self._clear_pass1_tendons = False
        self._skip_strips = False
        self.pages = {}
        #  طابور اللوج. كل سطر كان بيتجدول لوحده بـ root.after(0)، يعني
        #  حدث Tk لكل سطر، وكل حدث بيعمل insert + see("end") - والـ
        #  see بتجبر الويدجت تتمرّر وترسم. الرن بيطلّع آلاف السطور في
        #  دفعات (جدول الاسترندات، قوائم البحور، و87 سطر خطأ رسم في رن
        #  واحد)، وأحداث after(0) بتتنفّذ قبل الرسم - فالشباك بيقف
        #  ويبيّض. الطابور بيتفرّغ دفعة واحدة كل 80 مللي بدل كده.
        self._log_q = []
        self._log_lock = threading.Lock()
        self._log_all = []
        self._progress_pending = None
        #  17.64: اللوج بيتابع آخر سطر إلا لو المستخدم وقّف المتابعة عشان
        #  يقرا سطر قديم أثناء الرن، وعدّاد الوقت المنقضي من الضغطة.
        self._log_follow = tk.BooleanVar(value=True)
        #  18.81: الفلتر والحفظ التلقائي
        self._log_important = tk.BooleanVar(value=False)
        self._log_saved_to = None
        self._run_t0 = None
        self._elapsed_txt = ""
        self._live_summary = "جاهز"

        root.title(f"{APP_NAME} {APP_VERSION}")
        root.geometry("1180x820")
        root.minsize(1020, 700)
        root.configure(bg=PALETTE["bg"])

        apply_theme(root)
        self._make_vars()
        self.v["ui_lang"].trace_add("write", self._refresh_ui_language)
        set_ui_language(self.v["ui_lang"].get())
        install_ui_translation()
        self._build_ui()
        self.load_config()
        self.root.after(LOG_FLUSH_MS, self._drain_log)
        root.protocol("WM_DELETE_WINDOW", self._on_close)
        self._bind_shortcuts()

    # ------------------------------------------------------------------

    def _bind_shortcuts(self):
        """اختصارات على النافذة كلها (17.64): F5 تشغيل، Shift+F5 إيقاف،
        Ctrl+S حفظ الإعدادات، Ctrl+1…6 الصفحات."""
        r = self.root
        r.bind("<F5>", lambda e: self._shortcut_start())
        r.bind("<Shift-F5>", lambda e: self.stop())
        r.bind("<Control-s>", lambda e: self.save_config())
        r.bind("<Control-S>", lambda e: self.save_config())
        #  18.25: عشر صفحات - Ctrl+1 ... Ctrl+9 وبعدين Ctrl+0
        for i, item in enumerate(self.NAV, start=1):
            key = i % 10
            r.bind(f"<Control-Key-{key}>", lambda e, k=item[0]: self.nav.select(k))

    def _shortcut_start(self):
        try:
            if str(self.run_btn["state"]) == "disabled":
                return
        except Exception:
            return
        self.start()

