    # ---------------- Settings: tendon profile ----------------

    def _set_profile(self, parent):
        outer, page = self._scroll_page(parent)
        right, left = self._columns(page)

        c = Card(right, "CGS - where the tendon sits", "Millimetres from the face named", icon="⌒")
        c.pack(fill="x", pady=(0, 14))
        c.figure("top_cover", 150)
        c.entry("CGS from top surface (hogging)", self.v["top_cover"],
                "High point over the supports. Written to RAM against the "
                "Top Cover datum.", info="top_cover")
        c.entry("CGS from soffit (sagging)", self.v["bot_cover"],
                "Low point at midspan. Written against the Bottom Cover datum.",
                info="bot_cover")
        c.check("Dimension each point from the face its moment implies",
                self.v["per_point_datum"],
                "High points and anchors from Top Cover, midspan from Bottom "
                "Cover. Turn off to force one datum everywhere.")
