    # ---------------- Banks page ----------------
    #
    #  الصفحة دي واجهة للتلات بنوك اللي جنب البرنامج. مش بتنفّذ أي منطق
    #  بنفسها — بتنادي نفس الدوال اللي سطر الأوامر بيناديها، فالنتيجة واحدة
    #  سواء شغّلت من هنا أو من الباتش.
    #
    #  والبنوك بتشتغل على **نسخة البرنامج الشغّالة دلوقتي** (core.use_suite)
    #  مش على أحدث ملف على الديسك، فاختبار بتشغّله من هنا بيقيس الكود اللي
    #  قدامك بالظبط.

    BANK_MODULES = ("pt_bank_core", "pt_edit_bank",
                    "pt_regression_bank", "pt_design_bank")

    def _banks(self):
        """
        يحمّل موديولات البنوك مرة واحدة ويوصّلها بالبرنامج الشغّال.
        يرجّع None ويشرح السبب لو الملفات مش موجودة.
        """
        if getattr(self, "_bank_mods", None):
            return self._bank_mods
        here = os.path.dirname(os.path.abspath(
            getattr(sys.modules.get("__main__"), "__file__", "") or os.getcwd()))
        if here not in sys.path:
            sys.path.insert(0, here)
        try:
            import pt_bank_core as bank_core
            import pt_edit_bank as edits
            import pt_regression_bank as tests
            import pt_design_bank as archive
        except Exception as e:
            messagebox.showerror(
                "Bank files are missing",
                f"Could not load the bank scripts from:\n{here}\n\n{e}\n\n"
                f"pt_bank_core.py, pt_edit_bank.py, pt_regression_bank.py and "
                f"pt_design_bank.py must sit next to this program.",
                parent=self.root)
            return None
        bank_core.use_suite(sys.modules.get("__main__"),
                            getattr(sys.modules.get("__main__"), "__file__", None))
        self._bank_mods = {"core": bank_core, "edits": edits,
                           "tests": tests, "archive": archive}
        return self._bank_mods

    def _bank_run(self, title, fn):
        """
        يشغّل شغل بنك في ثريد، ويوجّه كل الطباعة للكونسول بتاع البرنامج.

        البنوك بتطبع بـ print، فبنحوّل stdout مؤقتًا لسطر لوج. كده الشاشة
        واحدة لكل حاجة والمستخدم مش محتاج يفتح نافذة أوامر.
        """
        if self.worker and self.worker.is_alive():
            messagebox.showinfo("Busy", "A run is already in progress.",
                                parent=self.root)
            return
        mods = self._banks()
        if not mods:
            return

        self.nav.select("run")
        self._clear_log()
        self.log("═" * 62, "head")
        self.log(f"  {title}", "head")
        self.log("═" * 62, "head")
        self.run_btn.configure(state="disabled", text="Working...")

        class _ToLog:
            """يحوّل أي print لسطر في كونسول البرنامج."""

            def __init__(self, app):
                self.app = app
                self.buf = ""

            def write(self, data):
                self.buf += data
                while "\n" in self.buf:
                    line, self.buf = self.buf.split("\n", 1)
                    line = line.rstrip()
                    if not line:
                        continue
                    lvl = ("error" if line.lstrip().startswith("✖") else
                           "warn" if line.lstrip().startswith("⚠") else
                           "ok" if line.lstrip().startswith("✔") else
                           "head" if line.startswith("═") else "info")
                    self.app._log_async(line, lvl)
                return len(data)

            def flush(self):
                if self.buf.strip():
                    self.app._log_async(self.buf.rstrip(), "info")
                self.buf = ""

        def worker():
            sink = _ToLog(self)
            old_out, old_err = sys.stdout, sys.stderr
            sys.stdout = sys.stderr = sink
            try:
                fn(mods)
            except Exception as e:
                sink.flush()
                self._log_async(f"✖ {type(e).__name__}: {e}", "error")
                for line in traceback.format_exc().splitlines()[-6:]:
                    self._log_async("   " + line, "info")
            finally:
                sink.flush()
                sys.stdout, sys.stderr = old_out, old_err
                self.root.after(0, self._finish)

        self.worker = threading.Thread(target=worker, daemon=True)
        self.worker.start()

