    # ---------------- actions ----------------

    def _bank_fill_last(self):
        """يملّي خانة (قبل) بآخر موديل البرنامج حفظه في الجلسة دي."""
        if not self._last_output or not os.path.isfile(self._last_output):
            messagebox.showinfo(
                "No run yet",
                "The program has not saved a model in this session yet. "
                "Pick the file by hand instead.", parent=self.root)
            return
        self.v["bank_before"].set(self._last_output)
        if not self.v["bank_job"].get().strip():
            self.v["bank_job"].set(
                os.path.splitext(os.path.basename(self._last_output))[0][:40])
        self.log(f"Before = {os.path.basename(self._last_output)}", "ok")

    def _bank_add_edit(self, strips_only=False):
        before = self.v["bank_before"].get().strip()
        after = self.v["bank_after"].get().strip()
        if not os.path.isfile(before) or not os.path.isfile(after):
            messagebox.showerror("Pick both models",
                                 "Choose the model the program produced and "
                                 "the model after your edits.", parent=self.root)
            return
        if os.path.abspath(before) == os.path.abspath(after):
            messagebox.showerror(
                "Same file twice",
                "Both boxes point at the same file. Save your edited model "
                "under a NEW name so the original stays as the 'before'.",
                parent=self.root)
            return
        name = self.v["bank_job"].get().strip() or None
        note = self.v["bank_note"].get().strip()
        api = self.v["api_path"].get().strip() or None

        def work(mods):
            args = _BankArgs(before=before, after=after, name=name, note=note,
                             api=api, method=None, root=None, suite=None,
                             verbose=False, traceback=True,
                             include_program=False, strips_only=strips_only,
                             tol_match=0.60, tol_plan=0.05, tol_depth=5.0)
            mods["edits"].cmd_add(args)

        self._bank_run("Edit bank - "
                       + ("design strips only" if strips_only
                          else "comparing before and after"), work)

    def _bank_remove_edit(self):
        """
        يمسح شغلانة من بنك التعديلات.

        لازم يكون سهل: المقارنة اللي اتعملت على الملف الغلط بتزوّر خريطة
        التطوير كلها، لأن الترتيب مبني على تكرار التعديلات.
        """
        name = self.v["bank_job"].get().strip()
        if not name:
            messagebox.showinfo(
                "Which job?",
                "Type the job name in the 'Job name' box, then press this "
                "again. Press 'Roadmap report' if you want to see the names "
                "that are recorded.", parent=self.root)
            return
        mods = self._banks()
        if not mods:
            return
        jid = mods["core"].slugify(name)
        if not messagebox.askyesno(
                "Delete this job",
                f"Delete the recorded comparison '{jid}' from the edit bank?\n\n"
                f"Your model files are not touched.", parent=self.root):
            return

        def work(mods):
            mods["edits"].cmd_remove(_BankArgs(root=None, job=jid))

        self._bank_run("Edit bank - deleting a job", work)

    def _bank_edit_report(self):
        def work(mods):
            mods["edits"].cmd_report(_BankArgs(root=None, suite=None, html=True))
        self._bank_run("Edit bank - what gets fixed most", work)

    def _bank_add_cases(self):
        folder = self.v["bank_dxf_dir"].get().strip()
        if not os.path.isdir(folder):
            messagebox.showerror("Pick a folder",
                                 "Choose the folder holding the DXF files.",
                                 parent=self.root)
            return
        try:
            params = self.collect_params(strict=False)
        except Exception:
            params = TendonDesignParams()

        def work(mods):
            pd = mods["core"].params_to_dict(params)
            path = os.path.join(mods["core"].DEFAULT_ROOT, "_page_params.json")
            mods["core"].write_json(path, pd)
            mods["tests"].cmd_add(_BankArgs(
                root=None, suite=None, verbose=False, traceback=True,
                dxf=None, folder=folder, name=None, config=None,
                params_json=path, role=None, unit=self.v["unit"].get(),
                note="from the Banks page", link=False, no_run=False))

        self._bank_run("Test bank - registering cases", work)

    def _bank_run_tests(self):
        def work(mods):
            mods["tests"].cmd_run(_BankArgs(
                root=None, suite=None, verbose=False, traceback=True,
                case=None, label=None, baseline=None, accept=False, html=True))
        self._bank_run("Test bank - running every case", work)

    def _bank_accept(self):
        mods = self._banks()
        if not mods:
            return
        bank = mods["tests"].RegressionBank(None)
        labels = bank.run_labels()
        if not labels:
            messagebox.showinfo("Nothing to accept",
                                "No run has been recorded yet.", parent=self.root)
            return
        label = labels[-1]
        if not messagebox.askyesno(
                "Accept as baseline",
                f"Make run '{label}' the baseline every future run is "
                f"compared against?", parent=self.root):
            return

        def work(m):
            m["tests"].cmd_accept(_BankArgs(root=None, suite=None, label=label))
        self._bank_run(f"Test bank - accepting {label}", work)

    def _bank_import(self):
        cpt = self.v["bank_archive_cpt"].get().strip()
        if not os.path.isfile(cpt):
            messagebox.showerror("Pick a model",
                                 "Choose the .cpt file to add to the archive.",
                                 parent=self.root)
            return
        api = self.v["api_path"].get().strip() or None

        def work(mods):
            mods["archive"].cmd_import(_BankArgs(
                root=None, suite=None, api=api, verbose=False, traceback=True,
                cpt=cpt, folder=None, name=None, project=None, note=None,
                strand=None, strand_area=None, fpu=None, fpe=0.60,
                include_program=False))
        self._bank_run("Design archive - reading the model", work)

    def _bank_list_archive(self):
        def work(mods):
            mods["archive"].cmd_list(_BankArgs(root=None, suite=None))
        self._bank_run("Design archive", work)

    def _bank_stats(self):
        def work(mods):
            mods["archive"].cmd_stats(_BankArgs(root=None, suite=None, html=True))
        self._bank_run("Design archive - office figures", work)

    def _bank_open_root(self):
        mods = self._banks()
        root = mods["core"].DEFAULT_ROOT if mods else os.path.expanduser("~")
        os.makedirs(root, exist_ok=True)
        self._open_path(root)

    def _bank_open_report(self):
        """يفتح أحدث تقرير HTML من أي بنك."""
        mods = self._banks()
        if not mods:
            return
        newest, when = None, 0
        for sub in ("edits", "regression", "designs"):
            d = os.path.join(mods["core"].DEFAULT_ROOT, sub, "reports")
            if not os.path.isdir(d):
                continue
            for f in os.listdir(d):
                if not f.endswith(".html"):
                    continue
                p = os.path.join(d, f)
                t = os.path.getmtime(p)
                if t > when:
                    newest, when = p, t
        if not newest:
            messagebox.showinfo("No report yet",
                                "No HTML report has been produced yet.",
                                parent=self.root)
            return
        self._open_path(newest)

    # ---------------- the model a run just produced ----------------

    def _mark_output(self, cpt_path):
        """
        يفعّل أزرار «افتح الموديل» بعد ما الرن يحفظ.

        بيتنادى من الثريد، فكل لمس للواجهة بيروح للـ main thread بـ after().

        **18.42: الملف اللي مش .cpt بيتسجّل وبس.** الدالة دي بتقيس
        الملف كموديل رام - بتقرا الأعمدة والكابلات وجداول الشرائح منه.
        لما وضع الرسم نادى عليها بالـ DXF اللي لسه كاتبه، الناتج كان
        «file is not a database» تلات مرات، وقياس بصفر كابل وصفر متر
        مربع، وتقرير تاني فاضي جنب التقرير الحقيقي. وأخطر من الضوضاء:
        `_last_output` هو الملف اللي الرن المتسلسل بيدّيه لمرحلة
        العزوم، ولوحة DXF هناك كانت هتوقّف رن كامل.
        """
        if not str(cpt_path or "").lower().endswith(".cpt"):
            self._last_drawing = cpt_path
            return
        self._last_output = cpt_path
        #  **التقرير والقياس بيتكتبوا هنا (17.35).** ده المكان الوحيد
        #  اللي كل رن بيعدّي منه لما يحفظ موديل، فالمهندس بياخد الصفحة
        #  والأرقام من غير ما يطلبهم.
        try:
            _p = getattr(self, "_run_params", None)
            if _p is not None and bool(getattr(_p, "run_report", True)):
                _m = measure_model(cpt_path, _p, self.job)
                _folder = os.path.dirname(cpt_path)
                _stem = os.path.splitext(os.path.basename(cpt_path))[0]
                format_measurements(_m, self.job)
                save_measurements(_m, _folder, _stem, self.job)
                save_run_report(_m, _folder, _stem, self.job)
        except Exception as _e:
            try:
                self.job.info(f"    the run report was not produced ({_e}).")
            except Exception:
                pass

        def apply():
            name = os.path.basename(cpt_path)
            self.v["last_output_note"].set(f"Saved:  {name}")
            for btn in (self.btn_open_model, self.btn_open_folder):
                btn.configure(state="normal")
            dxf = os.path.splitext(cpt_path)[0] + "_layout.dxf"
            self.btn_open_dxf.configure(
                state="normal" if os.path.isfile(dxf) else "disabled")

        try:
            self.root.after(0, apply)
        except Exception:
            pass

    def _show_changelog(self):
        """
        سجل التغييرات جوّه البرنامج.

        النسخة القديمة بتفضل موجودة كملف لوحدها، فلو إصدار جديد عمل
        مشكلة ترجع للي قبله وتعرف من هنا إيه اللي اتغيّر بينهم بالظبط.
        """
        win = tk.Toplevel(self.root)
        win.title(f"{APP_NAME} - version history")
        win.configure(bg=PALETTE["bg"])
        win.geometry("760x560")
        win.transient(self.root)

        head = tk.Frame(win, bg=PALETTE["bg"])
        head.pack(fill="x", padx=18, pady=(16, 8))
        tk.Label(head, text=f"Version {APP_VERSION}", bg=PALETTE["bg"],
                 fg=PALETTE["ink"], font=F(14, "bold"),
                 anchor="w").pack(side="left")
        ttk.Button(head, text="Open CHANGELOG.md",
                   command=lambda: self._write_changelog(win)).pack(side="right")

        box = tk.Frame(win, bg=PALETTE["console"])
        box.pack(fill="both", expand=True, padx=18, pady=(0, 10))
        txt = tk.Text(box, bg=PALETTE["console"], fg="#cfe3f2", bd=0,
                      font=F(9, mono=True), wrap="word", padx=14, pady=12)
        sb = ttk.Scrollbar(box, orient="vertical", command=txt.yview)
        txt.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        txt.pack(fill="both", expand=True)
        txt.tag_configure("ver", foreground="#ffffff",
                          font=F(10, "bold", mono=True))
        txt.tag_configure("sub", foreground="#f0b95a",
                          font=F(9, "bold", mono=True))
        txt.tag_configure("warn", foreground="#ff7b7b")
        #  17.69: السجل بيتقرا من CHANGELOG.md جنب البرنامج - ده اللي
        #  بيتكتب فيه من 17.x - والجدول الداخلي هو الاحتياطي بس.
        note = changelog_version_note()
        if note:
            txt.insert("end", note + "\n\n", "warn")
        path = changelog_path()
        if os.path.isfile(path):
            try:
                with open(path, encoding="utf-8") as fh:
                    for line in fh:
                        if line.startswith("## "):
                            txt.insert("end", line[3:], "ver")
                        elif line.startswith("### "):
                            txt.insert("end", line[4:], "sub")
                        elif line.startswith("# "):
                            continue
                        else:
                            txt.insert("end", line)
            except Exception as e:
                txt.insert("end", f"Could not read {path}: {e}\n", "warn")
        else:
            txt.insert("end", f"CHANGELOG.md is not beside the program, so "
                              f"this is the built-in table, which ends at "
                              f"{CHANGES[0][0] if CHANGES else '?'} - the "
                              f"record for {APP_VERSION} is in CHANGELOG.md "
                              f"next to the build it came with.\n\n", "warn")
            for ver, when, notes in CHANGES:
                txt.insert("end", f"{ver}   {when}\n", "ver")
                for n in notes:
                    txt.insert("end", f"   - {n}\n")
                txt.insert("end", "\n")
        txt.configure(state="disabled")

        ttk.Button(win, text="Close", command=win.destroy
                   ).pack(anchor="e", padx=18, pady=(0, 14))
        win.bind("<Escape>", lambda e: win.destroy())

    def _write_changelog(self, parent=None):
        """يفتح CHANGELOG.md لو موجود؛ لو مش موجود بيكتبه من الجدول الداخلي."""
        path = changelog_path()
        try:
            if not os.path.isfile(path):
                path = write_changelog()
            self._open_path(path)
        except Exception as e:
            messagebox.showwarning("Could not open it", str(e),
                                   parent=parent or self.root)

    def _open_last_model(self):
        if self._last_output and os.path.isfile(self._last_output):
            self.log(f"Opening {os.path.basename(self._last_output)} - RAM "
                     f"Concept may take a moment to start.", "info")
            self._open_path(self._last_output)
        else:
            messagebox.showinfo("No model yet",
                                "No model has been saved in this session yet.",
                                parent=self.root)

    def _open_last_folder(self):
        if self._last_output:
            self._open_path(os.path.dirname(self._last_output))

    def _open_last_dxf(self):
        if not self._last_output:
            return
        dxf = os.path.splitext(self._last_output)[0] + "_layout.dxf"
        if os.path.isfile(dxf):
            self._open_path(dxf)
        else:
            messagebox.showinfo("No layout DXF",
                                "This run did not export a layout DXF. Turn "
                                "it on under Outputs on the Project page.",
                                parent=self.root)

    def _open_path(self, path):
        try:
            if sys.platform.startswith("win"):
                os.startfile(path)          # noqa
            elif sys.platform == "darwin":
                os.system(f'open "{path}"')
            else:
                os.system(f'xdg-open "{path}"')
        except Exception as e:
            messagebox.showerror("Could not open", str(e), parent=self.root)

