        c.entry("Mark prefix (blank = A and B)", self.v["shop_mark_prefix"],
                hint="A.01, A.02 … for the first direction and B.01 … for the "
                     "second. Type a prefix here to force one letter on all "
                     "of them, e.g. the level's own mark.")

        c = Card(right, "What the numbers mean",
                 "The figures written along every tendon", icon="↕")
