    # ---------- المشاريع السابقة في البنك (18.19) ----------

    def _xp_refresh(self):
        lb = getattr(self, "_xp_list", None)
        if lb is None:
            return
        try:
            recs, path = experience_records(self.v["experience_bank"].get())
        except Exception:
            recs, path = [], ""
        lb.delete(0, "end")
        for r in recs:
            tx, ty = (r.get("tendons") or {}).get("X") or {}, (r.get("tendons") or {}).get("Y") or {}
            strips = sum(((r.get("strips") or {}).get(d) or {}).get("strips", 0) for d in "XY")
            lb.insert("end",
                      f"{str(r.get('model', '?'))[:34]:34s} h{float(r.get('h') or 0):4.0f} "
                      f"{float(r.get('area') or 0):6.0f}m² "
                      f"X{int(tx.get('tendons') or 0):3d}@{float(tx.get('spacing_med') or 0):.2f}/"
                      f"{tx.get('strands_med') or 0}s "
                      f"Y{int(ty.get('tendons') or 0):3d}@{float(ty.get('spacing_med') or 0):.2f}/"
                      f"{ty.get('strands_med') or 0}s strips{strips:3d}")
        if not recs:
            lb.insert("end", "(no projects in the bank yet)")
        self._xp_names = [r.get("model") for r in recs]
        self._xp_show_pick()

    def _xp_selected_names(self):
        lb = getattr(self, "_xp_list", None)
        names = getattr(self, "_xp_names", None) or []
        if lb is None:
            return []
        out = []
        for i in lb.curselection():
            if 0 <= int(i) < len(names):
                out.append(str(names[int(i)]))
        return [n for n in out if n]

    def _xp_pick_selected(self, add=False):
        """
        اللي محدّد في القايمة هو اللي البرنامج هيتعلّم منه.

        `add=True` بيضيف على الاختيار الحالي بدل ما يستبدله - عشان
        مجموعة المدارس تتلمّ على مرات من غير ما القايمة تتمسح.
        """
        picked = self._xp_selected_names()
        if not picked:
            messagebox.showinfo(
                "Nothing selected",
                "Select the projects in the list first - click one, then "
                "Ctrl-click or Shift-click for more.", parent=self.root)
            return
        if add:
            have = [p for p in self.v["experience_pick"].get().split(";")
                    if p.strip()]
            for n in picked:
                if n not in have:
                    have.append(n)
            picked = have
        self.v["experience_pick"].set(";".join(picked))
        for label, key in XP_SCOPES.items():
            if key == "chosen":
                self.v["experience_scope"].set(label)
                break
        if not bool(self.v["use_experience"].get()):
            self.v["use_experience"].set(True)
        self.save_config(silent=True)
        self._xp_show_pick()

    def _xp_pick_all(self):
        for label, key in XP_SCOPES.items():
            if key == "all":
                self.v["experience_scope"].set(label)
                break
        self.save_config(silent=True)
        self._xp_show_pick()

    def _xp_show_pick(self):
        """السطر اللي بيقول بيتعلّم من إيه دلوقتي - بالاسم."""
        try:
            scope = XP_SCOPES.get(self.v["experience_scope"].get(), "all")
            recs, _p = experience_records(self.v["experience_bank"].get())
            if scope != "chosen":
                self._xp_pick_note.set(
                    f"Learning from all {len(recs)} project(s) in the bank.")
                return
            keep, missing = experience_chosen(
                recs, self.v["experience_pick"].get())
            names = ", ".join(str(r.get("model")) for r in keep[:6])
            more = " …" if len(keep) > 6 else ""
            txt = (f"Learning from {len(keep)} of {len(recs)}: {names}{more}"
                   if keep else
                   "Nothing chosen yet - the whole bank is used until you "
                   "select some and press 'Use only the selected'.")
            if missing:
                txt += (f"  ·  {len(missing)} chosen project(s) are no longer "
                        f"in the bank and are skipped.")
            self._xp_pick_note.set(txt)
        except Exception:
            pass

    def _xp_add_folder(self):
        d = filedialog.askdirectory(parent=self.root, title="Folder of previous projects (.cpt)")
        if not d:
            return
        files = sorted(glob.glob(os.path.join(d, "*.cpt")))
        files = [f for f in files if not os.path.basename(f).startswith("_")]
        if not files:
            messagebox.showinfo("Folder", "No .cpt files in that folder.", parent=self.root)
            return
        self._xp_add(files)

    def _xp_add_files(self):
        files = filedialog.askopenfilenames(
            parent=self.root, title="Previous projects to add",
            filetypes=[("RAM Concept model", "*.cpt")])
        if files:
            self._xp_add(list(files))

    def _xp_add(self, files):
        try:
            params = self.collect_params(strict=False)
        except Exception as e:
            messagebox.showerror("Settings", str(e), parent=self.root)
            return
        bank = (self.v["experience_bank"].get() or "").strip()
        self.nav.select("run")
        self._clear_log()
        self.log(f"{APP_NAME} {APP_VERSION} - adding {len(files)} previous project(s) to the bank",
                 "head")
        self.run_btn.configure(state="disabled", text="Working...")
        self.stop_btn.configure(state="normal")
        self._run_t0 = time.time()
        self._elapsed_txt = ""
        self.lbl_elapsed.configure(text="00:00")
        self._run_marker = self._last_output
        self._review_report = None
        self.job = Job(log_cb=self._log_async, progress_cb=self._progress_async)

        def work():
            job = self.job
            try:
                added, skipped, path = experience_add_projects(
                    files, bank, params, job, api_path=self.v["api_path"].get() or None)
                if added and not bool(self.v["use_experience"].get()):
                    self.v["use_experience"].set(True)
                    job.info("'Draw the tendons and design strips from past experience' "
                             "is now on (Settings) - switch it off there to design "
                             "without the bank.")
                job.step(1.0, "Done")
            except CancelledError:
                job.warn("Stopped.")
                job.step(0.0, "Stopped")
            except Exception as e:
                job.error(f"Adding the projects failed: {e}")
                for line in traceback.format_exc().strip().splitlines()[-8:]:
                    job.log("   " + line, "error")
                job.step(0.0, "Failed")
            finally:
                self.root.after(0, self._xp_refresh)
                self.root.after(0, self._finish)

        self.worker = threading.Thread(target=work, daemon=True)
        self.worker.start()

    def _xp_remove(self):
        lb = self._xp_list
        picked = [self._xp_names[i] for i in lb.curselection()
                  if i < len(getattr(self, "_xp_names", []))]
        if not picked:
            messagebox.showinfo("Remove", "Select the projects to remove first.",
                                parent=self.root)
            return
        if not messagebox.askyesno("Remove from the bank",
                                   f"Remove {len(picked)} project(s) from the bank? "
                                   f"The model files themselves are not touched.",
                                   parent=self.root):
            return
        n, path = experience_remove_projects(picked, self.v["experience_bank"].get())
        self.log(f"{n} project(s) removed from the bank ({path}).", "ok")
        self._xp_refresh()

    def _xp_remove_all(self):
        names = list(getattr(self, "_xp_names", []) or [])
        if not names:
            return
        if not messagebox.askyesno("Empty the bank",
                                   f"Remove all {len(names)} project(s) from the bank?",
                                   parent=self.root):
            return
        n, path = experience_remove_projects(names, self.v["experience_bank"].get())
        self.log(f"The bank is empty ({n} removed, {path}).", "ok")
        self._xp_refresh()

    # ---------- الأحمال المنقولة (18.21) ----------

    def _xfer_begin(self, title):
        self.nav.select("run")
        self._clear_log()
        self.log(f"{APP_NAME} {APP_VERSION} - {title}", "head")
        self.run_btn.configure(state="disabled", text="Working...")
        self.stop_btn.configure(state="normal")
        self._run_t0 = time.time()
        self._elapsed_txt = ""
        self.lbl_elapsed.configure(text="00:00")
        self._run_marker = self._last_output
        self._review_report = None
        self.job = Job(log_cb=self._log_async, progress_cb=self._progress_async)
        return self.job

    def _xfer_read_cases(self):
        src = (self.v["xfer_src"].get() or "").strip()
        if not src or not os.path.isfile(src):
            messagebox.showerror("Model", "Pick the model of the floor above first.",
                                 parent=self.root)
            return
        job = self._xfer_begin(f"reading the load cases of {os.path.basename(src)}")

        def work():
            names = []
            try:
                with RamSession(job, api_path=self.v["api_path"].get() or None) as session:
                    session.open(src)
                    names = [(c["name"], c["kind"]) for c in ram_load_cases(session, job)]
                job.step(1.0, "Done")
            except Exception as e:
                job.error(f"Could not read the load cases: {e}")
                job.step(0.0, "Failed")
            finally:
                def fill():
                    for lb in (self._xfer_dead, self._xfer_live):
                        lb.delete(0, "end")
                        for n, k in names:
                            lb.insert("end", f"{n}   [{k}]")
                    self._xfer_case_names = [n for n, k in names]
                    self._finish()
                self.root.after(0, fill)

        self.worker = threading.Thread(target=work, daemon=True)
        self.worker.start()

    def _xfer_import(self):
        src = (self.v["xfer_src"].get() or "").strip()
        dst = (self.v["cpt"].get() or "").strip()
        if not src or not os.path.isfile(src):
            messagebox.showerror("Model", "Pick the model of the floor above first.",
                                 parent=self.root)
            return
        if not dst or not os.path.isfile(dst):
            messagebox.showerror("Model", "The Project page needs the model that "
                                 "receives the loads.", parent=self.root)
            return
        names = getattr(self, "_xfer_case_names", None) or []
        dead = [names[i] for i in self._xfer_dead.curselection() if i < len(names)]
        live = [names[i] for i in self._xfer_live.curselection() if i < len(names)]
        if not dead and not live:
            messagebox.showerror("Load cases", "Read the load cases and select the ones "
                                 "for the Dead group and the Live group.", parent=self.root)
            return
        try:
            factor = float(self.v["xfer_factor"].get() or 1.0)
        except ValueError:
            messagebox.showerror("Factor", "The multiplier must be a number.", parent=self.root)
            return
        comps = [k.capitalize() for k in ("fx", "fy", "fz", "mx", "my", "mz")
                 if bool(self.v[f"xfer_{k}"].get())]
        if not comps:
            messagebox.showerror("Components", "Pick at least one component.", parent=self.root)
            return
        if not messagebox.askyesno(
                "Import the loads",
                f"Dead: {', '.join(dead) or '-'}\nLive: {', '.join(live) or '-'}\n"
                f"x{factor:g}, components {', '.join(comps)}\n\n"
                f"The loads are written into\n{os.path.basename(dst)}\nand it is saved. "
                f"Carry on?", parent=self.root):
            return
        job = self._xfer_begin(f"transfer loads: {os.path.basename(src)} -> {os.path.basename(dst)}")
        analyse = bool(self.v["xfer_analyse"].get())
        dead_layer = (self.v["xfer_dead_layer"].get() or "").strip()
        live_layer = (self.v["xfer_live_layer"].get() or "").strip()

        def work():
            try:
                api = self.v["api_path"].get() or None
                job.log("Reading the reactions of the floor above", "head")
                got = {}
                with RamSession(job, api_path=api) as session:
                    session.open(src)
                    if analyse:
                        res = run_model_analysis(session, job, None)
                        if not res.get("ok"):
                            raise RuntimeError("RAM did not finish the analysis of the floor above")
                    if dead:
                        got["dead"] = read_reactions_from_ram(session, dead, job)
                    if live:
                        got["live"] = read_reactions_from_ram(session, live, job)
                job.log("Writing them into this floor", "head")
                with RamSession(job, api_path=api) as session:
                    session.open(dst)
                    if "dead" in got:
                        write_transfer_loads_to_ram(session, got["dead"], dead_layer,
                                                    DEAD_CAUSE_NAMES, factor, comps, job,
                                                    what="Dead transfer loads")
                    if "live" in got:
                        write_transfer_loads_to_ram(session, got["live"], live_layer,
                                                    LIVE_CAUSE_NAMES, factor, comps, job,
                                                    what="Live transfer loads")
                    if not safe_save(session, dst, job):
                        raise RuntimeError("the model could not be saved")
                self._mark_output(dst)
                job.step(1.0, "Done")
            except CancelledError:
                job.warn("Stopped.")
                job.step(0.0, "Stopped")
            except Exception as e:
                job.error(f"The transfer loads failed: {e}")
                for line in traceback.format_exc().strip().splitlines()[-8:]:
                    job.log("   " + line, "error")
                job.step(0.0, "Failed")
            finally:
                self.root.after(0, self._finish)

        self.worker = threading.Thread(target=work, daemon=True)
        self.worker.start()

