    def _editor_open(self):
        path = (self.v["editor_cpt"].get() or "").strip()
        if not path or not os.path.isfile(path):
            messagebox.showerror("Model", "Pick the model to edit.", parent=self.root)
            return
        self._edit_existing_model(path=path,
                                  copy_first=bool(self.v["editor_copy"].get()))

    def _port_from_editor_page(self):
        """
        **18.91: نفس الأداة من صفحة تعديل الموديل.**

        الموديل اللي رام رافض يحفظه هو بالظبط اللي المهندس بيفتحه هنا،
        فالمصدر بيتاخد من خانة الصفحة بدل ما يتسأل عنه تاني.
        """
        src = (self.v["editor_cpt"].get() or "").strip()
        if not src or not os.path.isfile(src):
            messagebox.showerror(
                "Model", "Put the model that will not save in the box above "
                "(or press Browse), then try again.", parent=self.root)
            return
        self._port_model(src=src)

    def _editor_open_last(self):
        if not self._last_output or not os.path.isfile(self._last_output):
            messagebox.showinfo("No model yet", "Nothing has been saved in this "
                                "session yet.", parent=self.root)
            return
        self.v["editor_cpt"].set(self._last_output)
        self._editor_open()

