    def _review_browse(self):
        d = filedialog.askdirectory(parent=self.root, title="Folder with the models")
        if d:
            self.v["review_folder"].set(d)

    def _start_review(self):
        folder = (self.v["review_folder"].get() or "").strip()
        if not folder or not os.path.isdir(folder):
            messagebox.showerror("Folder", "Pick the folder that holds the models.",
                                 parent=self.root)
            return
        files = sorted(glob.glob(os.path.join(folder, "*.cpt")),
                       key=lambda f: os.path.getsize(f))
        files = [f for f in files if not os.path.basename(f).startswith("_")]
        if not files:
            messagebox.showerror("Folder", "No .cpt files in that folder.", parent=self.root)
            return
        try:
            params = self.collect_params(strict=True)
            self.save_config(silent=True)
        except ValueError as e:
            messagebox.showerror("Check your input", f"Some values need fixing:{e}",
                                 parent=self.root)
            return
        out_dir = (self.v["review_out"].get() or "").strip() or os.path.join(folder, "AutoPT review")
        try:
            os.makedirs(out_dir, exist_ok=True)
        except Exception as e:
            messagebox.showerror("Output folder", str(e), parent=self.root)
            return
        self.nav.select("run")
        self._clear_log()
        _LAST_DRAWN.update(tendons=None, lines=None, params=None)
        self.log(f"{APP_NAME} {APP_VERSION} - reviewing {len(files)} model(s) in {folder}",
                 "head")
        self.log(f"   out:   {out_dir}", "info")
        self.run_btn.configure(state="disabled", text="Working...")
        self.stop_btn.configure(state="normal")
        self._run_t0 = time.time()
        self._elapsed_txt = ""
        self.lbl_elapsed.configure(text="00:00")
        self._run_marker = self._last_output
        self._review_report = None
        self._review_live = None
        self.job = Job(log_cb=self._log_async, progress_cb=self._progress_async)
        self._run_params = params
        self.worker = threading.Thread(target=self._review_pipeline,
                                       args=(files, out_dir, params), daemon=True)
        self.worker.start()

    def _review_pipeline(self, files, out_dir, params):
        job = self.job
        rows = []
        method = REVIEW_METHODS.get(self.v["review_method"].get(), "osh")

        def on_model(info):
            self._review_live = info

        try:
            rows = review_project(files, params, job, out_dir,
                                  api_path=self.v["api_path"].get() or None,
                                  do_efm=bool(self.v["review_efm"].get()),
                                  do_shave=bool(self.v["review_shave"].get()),
                                  method=method, on_model=on_model)
        except CancelledError:
            job.warn("Stopped.")
            job.step(0.0, "Stopped")
        except Exception as e:
            job.error(f"The review failed: {e}")
            for line in traceback.format_exc().strip().splitlines()[-12:]:
                job.log("   " + line, "error")
            job.step(0.0, "Failed")
        finally:
            if rows:
                stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M")
                xlsx = os.path.join(out_dir, f"AutoPT_review_{stamp}.xlsx")
                path = write_review_xlsx(rows, xlsx, params, job)
                write_review_md(rows, os.path.join(out_dir, f"AutoPT_review_{stamp}.md"), job)
                if path:
                    self._review_report = path
                    job.log("=" * 62, "head")
                    job.ok(f"Review done: {sum(1 for r in rows if r.get('status') == 'ok')} "
                           f"of {len(rows)} model(s) went through. Report: {path}")
                    job.step(1.0, "Done")
            self._review_live = None
            self.root.after(0, self._finish)

